    public function __construct(
        private readonly string $home,
        private readonly ?string $brokerInternalEndpoint = null,
        private readonly ?string $brokerFencingPath = null,
        private readonly ?int $brokerAdoptedNginxPid = null,
        private readonly ?string $brokerHostBootId = null,
    ) {
        // A latched pressure marker is inspected before any mkdir/chmod/GC or
        // reserve work. Recovery startup is an adoption-only path: it may
        // inspect the existing runtime and serve the Broker transport, but it
        // must not rewrite durable gateway state.
        $this->readOnlyRecoveryMode = $this->diskPressureMarkerActive();
        if ($this->brokerInternalEndpoint !== null) {
            $this->brokerGenerationFencingToken = $this->brokerFencingToken();
            if (\preg_match(
                '/\A[a-f0-9]{64}\z/D',
                $this->brokerGenerationFencingToken,
            ) !== 1) {
                throw new \RuntimeException(
                    'Controller startup cannot lock the Native Broker generation fence.'
                );
            }
        }
        $this->ensureDirectories($this->readOnlyRecoveryMode);
        $this->freshInstallBootstrapAllowed = $this->freshInstallBootstrapAllowed();
        $diskPressureRecovery = $this->readOnlyRecoveryMode;
        if ($this->brokerHostBootId !== null
            && \preg_match('/\A[a-f0-9]{64}\z/D', $this->brokerHostBootId) !== 1
        ) {
            throw new \RuntimeException(
                'Controller startup received an invalid Native Broker boot identity.'
            );
        }
        $this->hostBootId = $this->brokerHostBootId ?? $this->detectHostBootId();
        $this->state = $this->loadState(!$diskPressureRecovery);
        $this->enforceLoadedInstanceRetirementFloors();
        $this->securityAnchorTrusted = $this->verifySecurityAnchor();
        if (!$this->securityAnchorTrusted
            && !($this->state['_security_ledger_bootstrap'] ?? false)
        ) {
            $this->state['health_state'] = 'SECURITY_ANCHOR_UNTRUSTED';
            $this->state = $this->sanitizeIsolationState($this->state);
            $this->state['_state_rebuild_required'] = true;
        }
        if (!$this->initializationMarkerTrusted) {
            $this->state['health_state'] = 'INITIALIZATION_MARKER_UNTRUSTED';
            $this->state = $this->sanitizeIsolationState($this->state);
            $this->state['_state_rebuild_required'] = true;
        }
        $bootstrapSecurityLedger = ($this->state['_security_ledger_bootstrap'] ?? false) === true;
        $this->securityLedgerBootstrapRequired = $bootstrapSecurityLedger;
        $persistRecoveredState = ($this->state['_state_rebuild_required'] ?? false) === true;
        unset(
            $this->state['_security_ledger_bootstrap'],
            $this->state['_state_rebuild_required'],
        );
        if (!$diskPressureRecovery && $bootstrapSecurityLedger) {
            $this->persistSecurityLedger();
            $this->securityLedgerBootstrapRequired = false;
        }
        if (!$diskPressureRecovery
            && ($bootstrapSecurityLedger || $persistRecoveredState)
        ) {
            $this->persistState();
        }
        $this->initializeJournalChain(!$diskPressureRecovery);
        if (!$diskPressureRecovery
            && $this->freshInstallBootstrapAllowed
            && $this->journalTrusted
            && !\file_exists($this->journalFile())
            && !\is_link($this->journalFile())
        ) {
            if (!$this->journal('gateway_initialized', ['host_id' => $this->hostId()])) {
                throw new \RuntimeException(
                    'Unable to establish the initial gateway audit chain.'
                );
            }
        }
        if (!$diskPressureRecovery
            && $this->journalTrusted
            && $this->initializationMarkerTrusted
            && ($this->state['security_ledger_valid'] ?? false) === true
        ) {
            $this->persistInitializationMarker();
        }
        if ($diskPressureRecovery) {
            $this->state['ready'] = false;
            $this->state['health_state'] = 'DISK_PRESSURE';
            $this->state['recovery']['stage'] = $this->journalTrusted
                ? 'DISK_PRESSURE'
                : 'DISK_PRESSURE_JOURNAL_UNTRUSTED';
            $this->state['recovery']['last_failure'] = $this->journalTrusted
                ? 'startup_recovery_suspended'
                : 'startup_recovery_suspended_with_untrusted_journal';
        } else {
            $this->reconcileActiveRuntimeSlot();
            $this->reconcileInterruptedPublication();
        }
        $persistedNonces = $this->state['security']['nonces'] ?? [];
        $this->nonces = $this->normalizePersistedNonces($persistedNonces);
        $this->loadNonceWal();
        $this->pruneNonces();
        $this->clockWallAnchor = \time();
        $this->clockMonotonicAnchor = \hrtime(true) / 1_000_000_000;
    }

    public static function main(array $argv): int
    {
        if (\in_array('--self-test', $argv, true)) {
            $requiredFunctions = [
                'disk_free_space',
                'hrtime',
                'openssl_x509_read',
                'proc_open',
                'sodium_memzero',
                'stream_socket_server',
            ];
            if (\PHP_OS_FAMILY !== 'Windows') {
                $requiredFunctions[] = 'posix_geteuid';
                $requiredFunctions[] = 'posix_kill';
            }
            $missingFunctions = \array_values(\array_filter(
                $requiredFunctions,
                static fn (string $function): bool => !\function_exists($function),
            ));
            $ok = $missingFunctions === [] && \PHP_INT_SIZE >= 8;
            echo \json_encode([
                'ok' => $ok,
                'protocol' => self::PROTOCOL,
                'implementation_level' => 'wls-2.0',
                'security_profile' => 'native-broker-v1',
                'broker_internal_transport' => true,
                'php' => \PHP_VERSION,
                'openssl' => \defined('OPENSSL_VERSION_TEXT') ? \OPENSSL_VERSION_TEXT : '',
                'missing_runtime_functions' => $missingFunctions,
            ], JSON_UNESCAPED_SLASHES) . PHP_EOL;
            return $ok ? 0 : 1;
        }

        $home = '';
        $brokerInternal = null;
        $brokerFencing = null;
        $brokerAdoptedNginxPid = null;
        $brokerHostBootId = null;
        foreach ($argv as $arg) {
            if (\str_starts_with((string)$arg, '--home=')) {
                $home = \substr((string)$arg, 7);
            } elseif (\str_starts_with((string)$arg, '--broker-internal=')) {
                $brokerInternal = \substr((string)$arg, 18);
            } elseif (\str_starts_with((string)$arg, '--broker-fencing-file=')) {
                $brokerFencing = \substr((string)$arg, 22);
            } elseif (\str_starts_with((string)$arg, '--host-boot-id=')) {
                $brokerHostBootId = \strtolower(\substr((string)$arg, 15));
            } elseif (\str_starts_with((string)$arg, '--broker-adopted-nginx-pid=')) {
                $rawPid = \substr((string)$arg, 27);
                if (\preg_match('/\A[1-9][0-9]{0,9}\z/D', $rawPid) !== 1
                    || (int)$rawPid > 4294967295
                ) {
                    \fwrite(STDERR, "Invalid --broker-adopted-nginx-pid.\n");
                    return 2;
                }
                $brokerAdoptedNginxPid = (int)$rawPid;
            }
        }
        if ($home === '' || \str_contains($home, "\0")) {
            \fwrite(STDERR, "Missing --home for WLS Gateway Controller.\n");
            return 2;
        }
        $home = \rtrim($home, '/\\');
        $expectedRun = $home . DIRECTORY_SEPARATOR . 'runtime'
            . DIRECTORY_SEPARATOR . 'run';
        if (\PHP_OS_FAMILY === 'Linux'
            && \hash_equals('/var/lib/weline-gateway', $home)
        ) {
            $expectedRun = '/run/weline-gateway';
        } elseif (\PHP_OS_FAMILY === 'Darwin'
            && \hash_equals('/Library/Application Support/WelineGateway', $home)
        ) {
            $expectedRun = '/var/run/weline-gateway';
        }
        $expectedUnixBroker = 'unix://' . $expectedRun
            . DIRECTORY_SEPARATOR . 'controller.sock';
        $expectedFencing = $home . DIRECTORY_SEPARATOR . 'trust'
            . DIRECTORY_SEPARATOR . 'broker-fencing-token';
        $validUnixBroker = $brokerInternal !== null
            && \PHP_OS_FAMILY !== 'Windows'
            && \hash_equals($expectedUnixBroker, $brokerInternal)
            && \is_string($brokerFencing)
            && $brokerFencing !== ''
            && !\str_contains($brokerFencing, "\0")
            && \hash_equals($expectedFencing, $brokerFencing);
        $validWindowsBroker = $brokerInternal !== null
            && \PHP_OS_FAMILY === 'Windows'
            && \preg_match('/\A(?:[A-Za-z]:[\\\\\/]|\\\\\\\\)/D', $home) === 1
            && \preg_match(
                '#\Atcp://127\.0\.0\.1:([1-9][0-9]{0,4})\z#D',
                $brokerInternal,
                $matches,
            ) === 1
            && (int)$matches[1] <= 65535
            && \is_string($brokerFencing)
            && $brokerFencing !== ''
            && !\str_contains($brokerFencing, "\0")
            && \strcasecmp(
                \str_replace('/', '\\', $expectedFencing),
                \str_replace('/', '\\', $brokerFencing),
            ) === 0;
        if ($brokerInternal !== null
            && ((!$validUnixBroker && !$validWindowsBroker)
                || \str_contains($brokerInternal, "\0"))
        ) {
            \fwrite(STDERR, "Invalid --broker-internal endpoint.\n");
            return 2;
        }
        if ($brokerAdoptedNginxPid !== null && !$validWindowsBroker) {
            \fwrite(STDERR, "Broker Nginx adoption requires the Windows native transport.\n");
            return 2;
        }
        if ($brokerInternal !== null
            && (!\is_string($brokerHostBootId)
                || \preg_match('/\A[a-f0-9]{64}\z/D', $brokerHostBootId) !== 1)
        ) {
            \fwrite(STDERR, "Native Broker startup requires a canonical host boot identity.\n");
            return 2;
        }
        if ($brokerInternal === null && $brokerHostBootId !== null) {
            \fwrite(STDERR, "A host boot identity may only be supplied by the Native Broker.\n");
            return 2;
        }

        try {
            return (new self(
                $home,
                $brokerInternal,
                $brokerFencing,
                $brokerAdoptedNginxPid,
                $brokerHostBootId,
            ))->run();
        } catch (\Throwable $throwable) {
            \fwrite(STDERR, '[wls-edge/2] fatal: ' . $throwable->getMessage() . "\n");
            return (int)$throwable->getCode() === self::SERVICE_TREE_RESTART_EXIT
                ? self::SERVICE_TREE_RESTART_EXIT
                : 1;
        }
    }

    public function run(): int
    {
        $this->assertBrokerGenerationOwnership('startup data-plane adoption');
        // Start/adopt Nginx before opening the control listener. Otherwise a
        // daemonized Nginx master can inherit the Unix listening descriptor
        // and impersonate a live-but-silent controller after a controller exit.
        $this->adoptOrRecoverDataPlane();
        $this->controlServer = $this->openControlServer();
        if (!$this->readOnlyRecoveryMode) {
            $this->writePid();
        }
        try {
            while ($this->running) {
                if (!\is_resource($this->controlServer)) {
                    $this->controlServer = $this->openControlServer();
                }
                $read = [$this->controlServer];
                $write = [];
                $except = [];
                $selected = @\stream_select($read, $write, $except, 0, 100000);
                if ($selected === false) {
                    \usleep(100000);
                } elseif ($selected > 0) {
                    $client = @\stream_socket_accept($this->controlServer, 0);
                    if (\is_resource($client)) {
                        $this->serveClient($client);
                    }
                }
                $this->maintenance();
            }
        } finally {
            if (\is_resource($this->controlServer)) {
                @\fclose($this->controlServer);
            }
            $this->controlServer = null;
            if (\PHP_OS_FAMILY !== 'Windows') {
                $this->removeUnixSocketFile($this->socketFile());
            }
            if (!$this->readOnlyRecoveryMode) {
                $this->removeVerifiedPidFile($this->controllerPidFile());
            }
        }
        return 0;
    }

    /**
     * @param resource $client
     */
    private function serveClient($client, float $readTimeoutSeconds = 3.0): void
    {
        // Publication probes deliberately service a bounded set of nested
        // status/heartbeat requests. Preserve the outer Native action
        // exchange and request transaction exactly; otherwise a nested
        // serveClient() finally block clears the Broker channel while the
        // outer publication still needs a fresh PROCESS_ATTEST receipt.
        $previousBrokerExchange = $this->brokerExchange;
        $previousActiveBrokerPeer = $this->activeBrokerPeer;
        $previousDeferPublication = $this->deferPublication;
        $previousRequestOperation = $this->requestOperation;
        $previousRequestPrincipal = $this->requestPrincipal;
        $previousQueuedOperationId = $this->lastQueuedOperationId;
        $previousOperationResultContext = $this->requestOperationResultContext;
        $previousStateBeforeMutation = $this->requestStateBeforeMutation;
        $previousPublicationBeforeMutation = $this->requestPublicationBeforeMutation;
        $previousConfigDirtyBeforeMutation = $this->requestConfigDirtyBeforeMutation;
        $responseSecret = '';
        try {
            if (!\stream_set_blocking($client, true)) {
                throw new \RuntimeException(
                    'Unable to establish a blocking native Broker exchange.'
                );
            }
            $readTimeoutSeconds = \max(0.001, $readTimeoutSeconds);
            $this->configureClientReadTimeout($client, $readTimeoutSeconds);
            $brokerPeer = null;
            if ($this->brokerInternalEndpoint !== null) {
                // The Windows controller transport is loopback TCP. Reject a
                // client that cannot prove the Broker fencing secret quickly
                // so unauthenticated sockets cannot monopolize this
                // single-threaded control loop for the ordinary 3-second
                // request timeout.
                $this->configureClientReadTimeout(
                    $client,
                    \min(
                        self::BROKER_HANDSHAKE_TIMEOUT_SECONDS,
                        $readTimeoutSeconds,
                    ),
                );
                $brokerLine = @\fgets($client, 8192);
                if (!\is_string($brokerLine)
                    || !$this->authenticateBrokerProbe($client, $brokerLine)
                ) {
                    return;
                }
                $this->configureClientReadTimeout($client, $readTimeoutSeconds);
                $brokerLine = @\fgets($client, 8192);
                if (!\is_string($brokerLine)) {
                    // A readiness probe authenticates the endpoint and then
                    // closes without submitting a control-plane request.
                    return;
                }
                $brokerPeer = \is_string($brokerLine) ? \json_decode($brokerLine, true) : null;
                if (!\is_array($brokerPeer)) {
                    $this->writeResponse(
                        $client,
                        '',
                        false,
                        [],
                        'broker_identity_invalid',
                        'Native broker identity envelope is missing or invalid.',
                    );
                    return;
                }
            }
            $line = @\fgets($client, self::MAX_REQUEST_BYTES + 1);
            if (!\is_string($line) || \strlen($line) > self::MAX_REQUEST_BYTES) {
                $this->writeResponse($client, '', false, [], 'invalid_request', 'Request is empty or too large.');
                return;
            }
            $request = \json_decode($line, true);
            if (!\is_array($request)) {
                $this->writeResponse($client, '', false, [], 'invalid_json', 'Request is not valid JSON.');
                return;
            }
            if ($brokerPeer !== null) {
                $brokerError = $this->validateBrokerEnvelope($brokerPeer, \strlen($line));
                if ($brokerError !== '') {
                    $this->writeResponse(
                        $client,
                        (string)($request['request_id'] ?? ''),
                        false,
                        [],
                        'broker_identity_invalid',
                        $brokerError,
                    );
                    return;
                }
            }
            $requestId = (string)($request['request_id'] ?? '');
            if ($brokerPeer === null) {
                $this->writeResponse(
                    $client,
                    $requestId,
                    false,
                    [],
                    'broker_required',
                    'WLS Edge Protocol 2 requires the native platform broker.',
                );
                return;
            }
            $authentication = $this->authenticate($request, $brokerPeer);
            $responseSecret = (string)($authentication['secret'] ?? '');
            $authError = (string)($authentication['error'] ?? '');
            if ($authError !== '') {
                $this->writeResponse(
                    $client,
                    $requestId,
                    false,
                    [],
                    (string)($authentication['error_code'] ?? 'unauthorized'),
                    $authError,
                    $responseSecret,
                );
                return;
            }
            $operation = \strtolower(\trim((string)($request['operation'] ?? '')));
            $payload = \is_array($request['payload'] ?? null) ? $request['payload'] : [];
            $payload['_broker_peer'] = $brokerPeer;
            if ((string)$brokerPeer['channel'] === 'project') {
                $authenticatedProject = (string)($authentication['project_uuid'] ?? '');
                $payloadProject = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
                if ($authenticatedProject === ''
                    || !\hash_equals($authenticatedProject, $payloadProject)
                ) {
                    $this->writeResponse(
                        $client,
                        $requestId,
                        false,
                        [],
                        'forbidden',
                        'The project capability cannot act on another project identity.',
                        $responseSecret,
                    );
                    return;
                }
                $payload['_authenticated_project_uuid'] = $authenticatedProject;
            }
            try {
                $this->brokerExchange = $client;
                $this->activeBrokerPeer = $brokerPeer;
                if ((string)$brokerPeer['channel'] === 'admin'
                    && !$this->readOnlyRecoveryMode
                    && $operation !== 'bootstrap'
                    && !\in_array(
                        $operation,
                        [
                            'status',
                            'own-status',
                            'operation-status',
                            'routes',
                            'doctor',
                            'repair',
                        ],
                        true,
                    )
                ) {
                    // A replay may advance both the Native ledger and the
                    // host security files. Validate the local authority and
                    // storage reserve before any recovery write. Native
                    // equality is deliberately checked after replay because
                    // LEDGER_COMMITTED is the durable crash fence for a
                    // Native commit that may not have happened yet.
                    $this->assertPersistentMutationPreconditions($operation);
                    $this->replayEnrollmentCommits();
                    $this->replayCommittedSecurityTransactions();
                    $this->replayProjectIdentityRotations();
                }
                $this->assertRateLimit(
                    (string)$brokerPeer['channel'],
                    (string)($authentication['project_uuid'] ?? 'admin'),
                    $operation,
                );
                $this->requestOperation = $operation;
                $this->requestPrincipal = (string)(
                    $authentication['project_uuid'] ?? 'admin'
                );
                $this->lastQueuedOperationId = '';
                $this->requestOperationResultContext = [];
                $this->deferPublication = \in_array($operation, [
                    'register',
                    'renew',
                    'acme-challenge-sync',
                    'drain',
                    'unregister',
                ], true);
                $result = $this->dispatch($operation, $payload);
                if ($this->lastQueuedOperationId !== '') {
                    $operationState = $this->operationStatus(
                        $this->lastQueuedOperationId,
                        $this->requestPrincipal,
                        (string)$brokerPeer['channel'] === 'admin',
                    );
                    $result['operation_id'] = $this->lastQueuedOperationId;
                    $result['operation'] = $operationState;
                }
                $this->writeResponse(
                    $client,
                    $requestId,
                    true,
                    $result,
                    '',
                    '',
                    $responseSecret,
                    ($operation === 'enroll'
                        && (string)$brokerPeer['channel'] === 'admin')
                    || ($operation === 'rotate-prepare'
                        && (string)$brokerPeer['channel'] === 'project'),
                );
            } catch (\Throwable $throwable) {
                $code = $operation === 'bootstrap'
                    ? 'bootstrap_recovery_failed'
                    : ($throwable instanceof WlsEdgeProtocolException
                        ? $throwable->protocolCode()
                        : ($throwable instanceof \DomainException
                            ? 'rejected'
                            : 'operation_failed'));
                $this->journal('request_rejected', [
                    'operation' => $operation,
                    'channel' => (string)$brokerPeer['channel'],
                    'uid' => $brokerPeer['uid'] ?? null,
                    'sid' => $brokerPeer['sid'] ?? null,
                    'reason' => $throwable->getMessage(),
                ]);
                $this->writeResponse(
                    $client,
                    $requestId,
                    false,
                    [],
                    $code,
                    $throwable->getMessage(),
                    $responseSecret,
                );
            }
        } finally {
            @\fclose($client);
            $this->deferPublication = $previousDeferPublication;
            $this->requestOperation = $previousRequestOperation;
            $this->requestPrincipal = $previousRequestPrincipal;
            $this->lastQueuedOperationId = $previousQueuedOperationId;
            $this->requestOperationResultContext = $previousOperationResultContext;
            $this->requestStateBeforeMutation = $previousStateBeforeMutation;
            $this->requestPublicationBeforeMutation = $previousPublicationBeforeMutation;
            $this->requestConfigDirtyBeforeMutation = $previousConfigDirtyBeforeMutation;
            $this->brokerExchange = $previousBrokerExchange;
            $this->activeBrokerPeer = $previousActiveBrokerPeer;
        }
    }

    /** @param resource $client */
    private function configureClientReadTimeout(
        $client,
        float $timeoutSeconds,
    ): void {
        $timeoutSeconds = \max(0.001, $timeoutSeconds);
        $wholeSeconds = (int)\floor($timeoutSeconds);
        $microseconds = (int)\round(
            ($timeoutSeconds - $wholeSeconds) * 1_000_000,
        );
        if ($microseconds >= 1_000_000) {
            ++$wholeSeconds;
            $microseconds = 0;
        }
        if (!@\stream_set_timeout(
            $client,
            $wholeSeconds,
            \max(0, $microseconds),
        )) {
            throw new \RuntimeException(
                'Unable to bound the native Broker exchange timeout.'
            );
        }
    }

    /** @param resource $client */
    private function authenticateBrokerProbe($client, string $line): bool
    {
        if (\preg_match(
            '/\AWLS-BROKER-PROBE\/1\t([a-f0-9]{64})\t([a-f0-9]{64})\n\z/D',
            $line,
            $matches,
        ) !== 1) {
            return false;
        }
        $token = $this->ownedBrokerGenerationToken();
        $key = $token !== '' ? \hex2bin($token) : false;
        if (!\is_string($key) || \strlen($key) !== 32) {
            return false;
        }
        try {
            $nonce = (string)$matches[1];
            $requestPayload = self::BROKER_PROBE_PROTOCOL . "\nnonce={$nonce}\n";
            $expectedRequest = \hash_hmac('sha256', $requestPayload, $key);
            if (!\hash_equals($expectedRequest, (string)$matches[2])) {
                return false;
            }
            $responsePayload = self::BROKER_READY_PROTOCOL . "\nnonce={$nonce}\n";
            $response = self::BROKER_READY_PROTOCOL . "\t"
                . \hash_hmac('sha256', $responsePayload, $key) . "\n";
            return $this->writeStreamAll($client, $response);
        } finally {
            if (\function_exists('sodium_memzero')) {
                \sodium_memzero($key);
            }
        }
    }

    /** @param resource $stream */
    private function writeStreamAll($stream, string $contents): bool
    {
        $offset = 0;
        $length = \strlen($contents);
        while ($offset < $length) {
            $written = @\fwrite($stream, \substr($contents, $offset));
            if (!\is_int($written) || $written < 1) {
                return false;
            }
            $offset += $written;
        }
        return true;
    }

    /**
     * @param array<string,mixed> $broker
     */
    private function validateBrokerEnvelope(array $broker, int $payloadLength): string
    {
        if ((int)($broker['broker_schema'] ?? 0) !== 1
            || !\in_array((string)($broker['channel'] ?? ''), ['admin', 'project'], true)
            || (int)($broker['payload_length'] ?? -1) !== $payloadLength
            || (int)($broker['action_protocol'] ?? 0) !== 2
        ) {
            return 'Native broker identity envelope fields are invalid.';
        }
        $hasPosixIdentity = (int)($broker['uid'] ?? -1) >= 0
            && (int)($broker['gid'] ?? -1) >= 0
            && (int)($broker['pid'] ?? -1) > 0;
        $hasWindowsIdentity = \preg_match(
            '/\AS-1-(?:[0-9]+-)+[0-9]+\z/D',
            (string)($broker['sid'] ?? ''),
        ) === 1
            && (int)($broker['pid'] ?? -1) > 0;
        if (!$hasPosixIdentity && !$hasWindowsIdentity) {
            return 'Native broker did not provide a verifiable OS peer identity.';
        }
        $token = \strtolower(\trim((string)($broker['fencing_token'] ?? '')));
        $active = $this->ownedBrokerGenerationToken();
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $token) !== 1 || $active === '') {
            return 'Native broker fencing token is unavailable.';
        }
        if (!\hash_equals($active, $token)) {
            return 'Native broker fencing token does not own the active controller generation.';
        }
        return '';
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function dispatch(string $operation, array $payload): array
    {
        if ($this->publicationBlocksOperation($operation)) {
            throw new \DomainException(
                'Gateway publication is active; retry_after=1.'
            );
        }
        if (!\in_array(
            $operation,
            [
                'status',
                'own-status',
                'operation-status',
                'routes',
                'doctor',
                'repair',
                'bootstrap',
            ],
            true,
        )) {
            $this->assertPersistentMutationAllowed($operation);
        }
        return match ($operation) {
            'status' => $this->status(),
            'own-status' => $this->ownStatus(
                (string)($payload['_authenticated_project_uuid'] ?? ''),
                $payload,
            ),
            'operation-status' => $this->operationStatus(
                (string)($payload['operation_id'] ?? ''),
                (string)($payload['_authenticated_project_uuid'] ?? 'admin'),
                (string)($payload['_broker_peer']['channel'] ?? '') === 'admin',
            ),
            'routes' => $this->routePage(
                ['routes' => \array_values((array)($this->state['routes'] ?? []))],
                $payload,
                'admin-routes',
                'admin',
                ['host_boot_id' => $this->hostBootId],
            ),
            'doctor' => $this->doctor(),
            'bootstrap' => $this->bootstrapRecovery($payload),
            'register' => $this->register($payload, false),
            'renew' => $this->register($payload, true),
            'heartbeat' => $this->heartbeat($payload),
            'acme-challenge-sync' => $this->syncAcmeChallenges($payload),
            'transfer-stage' => $this->stageDomainTransfer($payload),
            'drain' => $this->drain($payload),
            'unregister' => $this->unregister($payload),
            'rotate-prepare' => $this->prepareProjectIdentityRotation($payload),
            'rotate-commit' => $this->commitProjectIdentityRotation($payload),
            'rotate-status' => $this->projectIdentityRotationStatus($payload),
            'rotate-finalize' => $this->finalizeProjectIdentityRotation($payload),
            'rotate-abort' => $this->abortProjectIdentityRotation($payload),
            'enroll' => $this->enroll($payload),
            'revoke' => $this->revoke($payload),
            'transfer' => $this->transferDomain($payload),
            'repair' => $this->repair($payload),
            'upgrade' => $this->upgradeSnapshot($payload),
            'stop' => $this->stopGateway($payload),
            default => throw new \DomainException('Unsupported wls-edge/2 operation: ' . $operation),
        };
    }

    private function publicationBlocksOperation(string $operation): bool
    {
        if ($this->probeCriticalSectionDepth > 0) {
            return !\in_array(
                $operation,
                ['status', 'own-status', 'operation-status', 'routes', 'doctor', 'heartbeat'],
                true,
            );
        }
        if ($this->publication === null
            || !\in_array(
                (string)($this->publication['phase'] ?? ''),
                ['PREPARED', 'SHADOW_VERIFIED', 'ACTIVATING', 'DURABILITY_PENDING'],
                true,
            )
        ) {
            return false;
        }

        // Publication verification deliberately keeps the authenticated
        // control plane responsive. Reads and fenced lease heartbeats cannot
        // change the candidate routing generation; every other mutation is
        // serialized behind the active publication transaction.
        return !\in_array(
            $operation,
            ['status', 'own-status', 'operation-status', 'routes', 'doctor', 'heartbeat'],
            true,
        );
    }

    /**
     * Native Broker startup recovery entry point. The ordinary authenticated
     * admin envelope still supplies freshness, HMAC and OS-root proof; this
     * payload marker prevents a normal administrator status request from
     * accidentally becoming a process-management operation.
     *
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function bootstrapRecovery(array $payload): array
    {
        $peer = \is_array($payload['_broker_peer'] ?? null)
            ? $payload['_broker_peer']
            : [];
        $bootstrapPayload = $payload;
        unset($bootstrapPayload['_broker_peer']);
        $bootstrapKeys = \array_keys($bootstrapPayload);
        \sort($bootstrapKeys, SORT_STRING);
        if (!\hash_equals('admin', (string)($peer['channel'] ?? ''))
            || !$this->administratorPeerAllowed($peer)
            || $bootstrapKeys !== ['host_id', 'internal_bootstrap']
            || ($payload['internal_bootstrap'] ?? null) !== true
            || !\hash_equals($this->hostId(), (string)($payload['host_id'] ?? ''))
        ) {
            throw new \DomainException(
                'Native Broker bootstrap identity or host fence was rejected.'
            );
        }
        if ($this->readOnlyRecoveryMode) {
            throw new \RuntimeException(
                'Native Broker bootstrap cannot mutate a disk-pressure recovery host.'
            );
        }

        $this->assertPersistentMutationPreconditions('bootstrap');

        // The authenticated internal bootstrap is the sole startup-recovery
        // path for this exchange. handleClient deliberately skips its generic
        // admin replay/adoption hooks for this operation so PROCESS_ATTEST,
        // adoption and any reload can occur at most once per bootstrap call.
        $this->replayEnrollmentCommits();
        $this->replayCommittedSecurityTransactions();
        $this->replayProjectIdentityRotations();
        // Recovery transactions intentionally make the local crash fence
        // durable before their Native commit. Exact Native equality is only
        // meaningful after those commits have been replayed.
        $this->attestBrokerSecurityRoot('bootstrap');
        $pendingStage = (string)($this->state['recovery']['stage'] ?? '');
        $recoveryPending = $this->startupDataPlaneRecoveryPending
            || \in_array($pendingStage, [
                'BROKER_ACTION_PENDING_RECOVERY',
                'BROKER_ACTION_PENDING_STARTUP',
            ], true);
        $pendingPublication = $this->publication !== null
            && \hash_equals(
                'PENDING_PUBLICATION',
                (string)($this->publication['phase'] ?? ''),
            );
        if ($recoveryPending
            && !$pendingPublication
            && !\hash_equals('BROKER_ACTION_PENDING_RECOVERY', $pendingStage)
        ) {
            $this->adoptOrRecoverDataPlane();
        }
        // A Native internal bootstrap is also the periodic privileged
        // maintenance callback. Queued publications and recovery decisions
        // remain durable while no client is connected, then advance only
        // inside this fresh root/admin-attested exchange.
        $this->processPendingPublication();
        if ($recoveryPending
            && \hash_equals('BROKER_ACTION_PENDING_RECOVERY', $pendingStage)
        ) {
            $this->recoverDataPlane();
        }
        // Clear only after every pending action returned normally. An
        // exception leaves the in-memory intent set, while the durable stage
        // above reconstructs it after a Controller restart.
        $this->startupDataPlaneRecoveryPending = false;
        // The five-second Native callback must stay cheap while no action is
        // pending. A cached root-owned receipt is enough for this response;
        // publication/restart paths above already requested a fresh receipt
        // before signalling a process.
        $dataPlane = $this->nginxStatus(false, false);
        $running = ($dataPlane['running'] ?? false) === true;
        $status = $this->status(false);
        $ready = $running && ($status['ready'] ?? false) === true;
        $upgradeBinding = $this->bootstrapUpgradeBinding();

        return [
            'ready' => $ready,
            'generation' => (int)($this->state['generation'] ?? 0),
            'active_config_generation' => (int)(
                $this->state['active_config_generation'] ?? 0
            ),
            'publication_generation' => (int)(
                $this->state['active_config_generation'] ?? 0
            ),
            'gateway_epoch' => (string)($this->state['epoch'] ?? ''),
            'controller_epoch' => (string)($this->state['epoch'] ?? ''),
            'active_slot' => (string)($this->state['active_slot'] ?? ''),
            'runtime_generation' => $this->activeRuntimeGeneration(),
            'host_boot_id' => $this->hostBootId,
            'upgrade_intent_sha256' => $upgradeBinding['digest'],
            'upgrade_intent_nonce' => $upgradeBinding['nonce'],
            'data_plane' => $running ? 'RUNNING' : 'DOWN',
            'recovery_pending' => !$ready,
        ];
    }

    /** @return array{digest:string,nonce:string} */
    private function bootstrapUpgradeBinding(): array
    {
        $intent = $this->readOptionalStableRegularFile(
            $this->trustDir() . DIRECTORY_SEPARATOR . 'upgrade.intent',
            4096,
            'Gateway signed upgrade intent',
        );
        if ($intent === null) {
            return ['digest' => \str_repeat('0', 64), 'nonce' => \str_repeat('0', 32)];
        }
        if (\preg_match(
            '/\AWLS-UPGRADE\/1\n'
                . 'host_id=([a-f0-9]{32})\nfrom=([AB])\nto=([AB])\n'
                . 'prepared_at=(0|[1-9][0-9]{0,18})\n'
                . 'deadline=(0|[1-9][0-9]{0,18})\n'
                . 'runtime_generation=([a-f0-9]{64})\n'
                . 'nonce=([a-f0-9]{32})\nsignature=([a-f0-9]{64})\n\z/D',
            $intent,
            $matches,
        ) !== 1 || !\hash_equals($this->hostId(), (string)$matches[1])) {
            throw new \RuntimeException('Gateway upgrade intent cannot bind bootstrap health.');
        }
        $signatureOffset = \strrpos($intent, 'signature=');
        $secret = \strtolower(\trim($this->readStableRegularFile(
            $this->adminTokenFile(),
            65,
            'Gateway administrator credential',
        )));
        $key = \preg_match('/\A[a-f0-9]{64}\z/D', $secret) === 1
            ? \hex2bin($secret)
            : false;
        if ($signatureOffset === false || !\is_string($key) || \strlen($key) !== 32) {
            throw new \RuntimeException('Gateway upgrade intent health binding is unavailable.');
        }
        try {
            $expected = \hash_hmac('sha256', \substr($intent, 0, $signatureOffset), $key);
        } finally {
            \sodium_memzero($key);
        }
        if (!\hash_equals($expected, (string)$matches[8])) {
            throw new \RuntimeException('Gateway upgrade intent health binding is invalid.');
        }
        return ['digest' => \hash('sha256', $intent), 'nonce' => (string)$matches[7]];
    }

    /**
     * @return array<string,mixed>
     */
    private function status(bool $refreshNativeAttestation = true): array
    {
        $nginx = $this->nginxStatus(false, $refreshNativeAttestation);
        $manifest = $this->slotManifestFromActiveFile();
        $recovery = (array)($this->state['recovery'] ?? []);
        $recovery['next_retry_in_seconds'] = \hash_equals(
            $this->hostBootId,
            (string)($recovery['circuit_boot_id'] ?? ''),
        ) ? \max(
            0,
            (int)\ceil(
                (float)($recovery['circuit_open_until_monotonic'] ?? 0.0)
                - $this->monotonicNow(),
            ),
        ) : 0;
        $recovery['lkg_rollback_hold_generation'] = (int)(
            $this->state['lkg_rollback_hold_generation'] ?? 0
        );
        $recovery['lkg_rollback_hold_since'] = (int)(
            $this->state['lkg_rollback_hold_since'] ?? 0
        );
        $recovery['lkg_rollback_hold_desired_digest'] = (string)(
            $this->state['lkg_rollback_hold_desired_digest'] ?? ''
        );
        $brokerReady = $this->brokerInternalReady();
        $releaseReady = ($manifest['release_ready'] ?? false) === true
            && ($manifest['test_mode'] ?? true) === false
            && \hash_equals('wls-2.0', (string)($manifest['implementation_level'] ?? ''))
            && \hash_equals('native-broker-v1', (string)($manifest['security_profile'] ?? ''));
        try {
            $service = \json_decode($this->readStableRegularFile(
                $this->trustDir() . DIRECTORY_SEPARATOR . 'platform-service.json',
                16_384,
                'Gateway platform service metadata',
            ), true);
        } catch (\Throwable) {
            $service = null;
        }
        $supervisorReady = \is_array($service)
            && ($service['test_mode'] ?? true) === false
            && \in_array(
                (string)($service['kind'] ?? ''),
                ['systemd-system', 'launchd-system', 'windows-service'],
                true,
            );
        $routeCounts = [];
        foreach ((array)($this->state['routes'] ?? []) as $route) {
            $status = (string)($route['status'] ?? 'UNKNOWN');
            $routeCounts[$status] = ($routeCounts[$status] ?? 0) + 1;
        }
        $operationCounts = [];
        foreach ((array)($this->state['operations'] ?? []) as $operation) {
            if (!\is_array($operation)) {
                continue;
            }
            $operationState = (string)($operation['state'] ?? 'UNKNOWN');
            $operationCounts[$operationState] = ($operationCounts[$operationState] ?? 0) + 1;
        }
        $clockUntrustedSince = (string)(
            $this->state['security']['clock_untrusted_since'] ?? ''
        );
        $clockStableFor = $clockUntrustedSince !== ''
            && $this->clockStableSinceMonotonic > 0.0
                ? \max(0.0, $this->monotonicNow() - $this->clockStableSinceMonotonic)
                : 0.0;
        $clockRecoveryRemaining = $clockUntrustedSince !== ''
            ? \max(
                0,
                (int)\ceil(self::CLOCK_RECOVERY_STABLE_SECONDS - $clockStableFor),
            )
            : 0;
        return [
            'ready' => (bool)($this->state['ready'] ?? false)
                && $brokerReady
                && $releaseReady
                && $supervisorReady
                && $this->journalTrusted
                && !($this->state['isolation_mode'] ?? false),
            'protocol' => self::PROTOCOL,
            'protocol_min' => 2,
            'protocol_max' => 2,
            'implementation_level' => (string)($manifest['implementation_level'] ?? 'checkpoint'),
            'security_profile' => (string)($manifest['security_profile'] ?? 'untrusted'),
            'release_ready' => $releaseReady,
            'broker_ready' => $brokerReady,
            'host_boot_id' => $this->hostBootId,
            'epoch' => (string)$this->state['epoch'],
            'generation' => (int)($this->state['active_config_generation'] ?? 0),
            'control_generation' => (int)$this->state['generation'],
            'state' => (string)$this->state['health_state'],
            'clock' => [
                'trusted' => $clockUntrustedSince === '',
                'untrusted_since' => $clockUntrustedSince,
                'retrusted_at' => (string)(
                    $this->state['security']['clock_retrusted_at'] ?? ''
                ),
                'stable_for_seconds' => (int)\floor($clockStableFor),
                'recovery_remaining_seconds' => $clockRecoveryRemaining,
                'state_persist_pending' => $this->clockStatePersistPending,
            ],
            'data_plane' => $nginx,
            'route_counts' => $routeCounts,
            'publication' => [
                'transaction_id' => (string)($this->publication['transaction_id'] ?? ''),
                'phase' => (string)($this->publication['phase'] ?? 'IDLE'),
                'desired_generation' => (int)($this->state['generation'] ?? 0),
                'candidate_generation' => (int)($this->publication['candidate_generation'] ?? 0),
                'active_generation' => (int)($this->state['active_config_generation'] ?? 0),
                'operation_counts' => $operationCounts,
            ],
            'public_http' => (int)$this->state['public_http'],
            'public_https' => (int)$this->state['public_https'],
            'h3_enabled' => (bool)($this->state['h3_enabled'] ?? false),
            'h3_reason' => (string)($this->state['h3_reason'] ?? ''),
            'active_slot' => (string)$this->state['active_slot'],
            'previous_slot' => (string)$this->state['previous_slot'],
            'runtime_generation' => (string)($manifest['runtime_generation'] ?? ''),
            'recovery' => $recovery,
            'journal' => [
                'trusted' => $this->journalTrusted,
                'sequence' => $this->journalSequence,
                'head_sha256' => $this->journalHead,
            ],
            'storage' => $this->storageStatus(),
            'supervisor_ready' => $supervisorReady,
            'test_mode' => (bool)($manifest['test_mode'] ?? false),
            'isolation_mode' => (bool)($this->state['isolation_mode'] ?? false),
        ];
    }

    /**
     * @return array<string,mixed>
     */
    private function ownStatus(string $projectUuid, array $requestPayload = []): array
    {
        if (!$this->validProjectUuid($projectUuid)
            || !\is_array($this->state['enrollments'][$projectUuid] ?? null)
        ) {
            throw new \DomainException('The project is not enrolled on this gateway.');
        }
        $status = $this->status();
        $controlTreeTrusted = (bool)$status['release_ready']
            && (bool)$status['broker_ready']
            && (bool)$status['supervisor_ready']
            && \hash_equals(self::PROTOCOL, (string)$status['protocol'])
            && \hash_equals('wls-2.0', (string)$status['implementation_level'])
            && \hash_equals('native-broker-v1', (string)$status['security_profile'])
            && ($this->state['security_ledger_valid'] ?? true) === true
            && $this->securityAnchorTrusted
            && $this->initializationMarkerTrusted;
        // Admission means a register/renew can be durably committed now. It
        // is intentionally stricter than existing data-plane availability:
        // journal, clock or storage degradation may preserve verified traffic
        // while refusing every new persistent mutation.
        $controlPlaneReady = $controlTreeTrusted
            && $this->journalTrusted
            && (($status['clock']['trusted'] ?? false) === true)
            && (($status['storage']['mutation_ready'] ?? false) === true)
            && !$this->readOnlyRecoveryMode;
        $dataPlaneRunning = (bool)($status['data_plane']['running'] ?? false);
        $dataPlaneState = \strtoupper((string)$status['state']);
        $publication = $this->projectPublicationAssessment($projectUuid);
        $projectReady = $controlTreeTrusted
            && $dataPlaneRunning
            && !\str_contains($dataPlaneState, 'DATA_PLANE_DOWN')
            && !\in_array(
                $dataPlaneState,
                ['ADMIN_STOPPED', 'SECURITY_MUTATION_FAILED_CLOSED'],
                true,
            )
            && $publication['ready'];
        $project = \is_array($this->state['projects'][$projectUuid] ?? null)
            ? $this->state['projects'][$projectUuid]
            : [];
        $activeProjectRoutes = $this->projectRoutesFromState(
            $projectUuid,
            (array)($this->state['active_routes'] ?? []),
        );
        $desiredProjectRoutes = $this->projectRoutes($projectUuid);
        $projectOperations = \array_values(\array_filter(
            (array)($this->state['operations'] ?? []),
            static fn (mixed $operation): bool => \is_array($operation)
                && \hash_equals(
                    $projectUuid,
                    (string)($operation['project_uuid'] ?? ''),
                ),
        ));
        $visibleOperations = \array_slice(
            \array_reverse($projectOperations),
            0,
            self::MAX_STATUS_OPERATIONS,
        );
        $payload = [
            'ready' => (bool)$status['ready'],
            'project_ready' => $projectReady,
            'project_converged' => $controlTreeTrusted
                && $dataPlaneRunning
                && $publication['converged'],
            'publication_exact' => $publication['exact'],
            'active_route_count' => $publication['active_route_count'],
            'pending_certificate_route_count'
                => $publication['pending_certificate_route_count'],
            'control_plane_ready' => $controlPlaneReady,
            'protocol' => (string)$status['protocol'],
            'host_boot_id' => $this->hostBootId,
            'protocol_min' => (int)$status['protocol_min'],
            'protocol_max' => (int)$status['protocol_max'],
            'implementation_level' => (string)$status['implementation_level'],
            'security_profile' => (string)$status['security_profile'],
            'release_ready' => (bool)$status['release_ready'],
            'broker_ready' => (bool)$status['broker_ready'],
            'supervisor_ready' => (bool)$status['supervisor_ready'],
            'epoch' => (string)$status['epoch'],
            'generation' => (int)$status['generation'],
            'active_config_generation' => (int)$status['generation'],
            'active_config_digest' => (string)(
                $this->state['active_config_digest'] ?? ''
            ),
            'state' => (string)$status['state'],
            'clock' => (array)$status['clock'],
            'data_plane' => [
                'running' => $dataPlaneRunning,
                'message' => (string)($status['data_plane']['message'] ?? ''),
            ],
            'public_http' => (int)$status['public_http'],
            'public_https' => (int)$status['public_https'],
            'project_uuid' => $projectUuid,
            'project_generation' => (int)($project['generation'] ?? 0),
            'request_digest' => (string)($project['digest'] ?? ''),
            'non_certificate_desired_digest' => (string)(
                $project['non_certificate_desired_digest'] ?? ''
            ),
            'idempotency_key' => (string)($project['idempotency_key'] ?? ''),
            'active_routes' => $activeProjectRoutes,
            'desired_routes' => $desiredProjectRoutes,
            'instances' => $this->projectInstanceStatuses($projectUuid),
            'operation_count' => \count($projectOperations),
            'operations_truncated' => \count($projectOperations)
                > self::MAX_STATUS_OPERATIONS,
            'operations' => \array_map(
                fn (array $operation): array => $this->operationWireProjection($operation),
                $visibleOperations,
            ),
        ];
        // WLS Edge Protocol 2 has one exact wire-frame ceiling. Keep ACTIVE and
        // desired semantics distinct, but page their bounded public projections
        // instead of duplicating ACTIVE routes under the legacy `routes` alias.
        return $this->routePage(
            [
                'active_routes' => $activeProjectRoutes,
                'desired_routes' => $desiredProjectRoutes,
            ],
            $requestPayload,
            'project-status',
            $projectUuid,
            $payload,
        );
    }

    /**
     * @param array<string,list<array<string,mixed>>> $collections
     * @param array<string,mixed> $requestPayload
     * @param array<string,mixed> $basePayload
     * @return array<string,mixed>
     */
    private function routePage(
        array $collections,
        array $requestPayload,
        string $scope,
        string $principal,
        array $basePayload = [],
    ): array {
        $projected = [];
        foreach ($collections as $name => $routes) {
            $projected[$name] = [];
            foreach ($routes as $route) {
                if (\is_array($route)) {
                    $projected[$name][] = $this->routeWireProjection(
                        $route,
                        $routes,
                    );
                }
            }
            \usort(
                $projected[$name],
                static fn (array $left, array $right): int =>
                    (string)($left['route_id'] ?? '') <=> (string)($right['route_id'] ?? ''),
            );
            unset($basePayload[$name]);
        }

        $fence = [
            'host_boot_id' => $this->hostBootId,
            'epoch' => (string)($this->state['epoch'] ?? ''),
            'generation' => (int)($this->state['generation'] ?? 0),
            'active_config_generation' => (int)(
                $this->state['active_config_generation'] ?? 0
            ),
            'active_config_digest' => (string)(
                $this->state['active_config_digest'] ?? ''
            ),
            'principal' => $principal,
            'scope' => $scope,
            'routes_digest' => \hash('sha256', $this->canonicalJson($projected)),
        ];
        if ($principal !== 'admin') {
            $project = \is_array($this->state['projects'][$principal] ?? null)
                ? $this->state['projects'][$principal]
                : [];
            $fence['project_generation'] = (int)($project['generation'] ?? 0);
            $fence['project_digest'] = (string)($project['digest'] ?? '');
        }
        $fenceDigest = \hash('sha256', $this->canonicalJson($fence));
        $cursor = \trim((string)($requestPayload['page_cursor'] ?? ''));
        $offset = $cursor === ''
            ? 0
            : $this->decodeRoutePageCursor(
                $cursor,
                $scope,
                $principal,
                $fenceDigest,
            );
        $limit = (int)($requestPayload['page_limit'] ?? self::ROUTE_PAGE_DEFAULT);
        if ($limit < 1 || $limit > self::ROUTE_PAGE_MAX) {
            throw new \DomainException('Gateway route page limit must be between 1 and 128.');
        }

        $flat = [];
        foreach ($projected as $name => $routes) {
            foreach ($routes as $route) {
                $flat[] = ['collection' => $name, 'route' => $route];
            }
        }
        if ($offset < 0 || $offset > \count($flat)) {
            throw new \DomainException('Gateway route page cursor is outside the current result.');
        }
        foreach (\array_keys($projected) as $name) {
            $basePayload[$name] = [];
        }
        foreach (\array_slice($flat, $offset, $limit) as $entry) {
            $basePayload[(string)$entry['collection']][] = $entry['route'];
        }
        $nextOffset = \min(\count($flat), $offset + $limit);
        $basePayload['page'] = [
            'schema' => 1,
            'fence' => $fence,
            'fence_digest' => $fenceDigest,
            'offset' => $offset,
            'limit' => $limit,
            'total' => \count($flat),
            'complete' => $nextOffset >= \count($flat),
            'next_cursor' => $nextOffset < \count($flat)
                ? $this->encodeRoutePageCursor(
                    $nextOffset,
                    $scope,
                    $principal,
                    $fenceDigest,
                )
                : '',
        ];
        return $basePayload;
    }

    /**
     * @param array<string,mixed> $route
     * @param list<array<string,mixed>> $publicationRoutes
     * @return array<string,mixed>
     */
    private function routeWireProjection(
        array $route,
        array $publicationRoutes,
    ): array
    {
        $backends = $this->routeWireBackends($route['backends'] ?? []);
        $identity = \is_array($route['backend_identity'] ?? null)
            ? $this->routeWireBackendIdentity($route['backend_identity'])
            : [];
        $backendInstances = $this->routeWireBackendInstances($route);
        $flattenedBackends = [];
        $instancesById = [];
        foreach ($backendInstances as $backendInstance) {
            $projectedInstanceId = (string)$backendInstance['instance_id'];
            $instancesById['instance:' . $projectedInstanceId] = $backendInstance;
            foreach ($backendInstance['backends'] as $backend) {
                $flattenedBackends[] = $backend;
            }
        }
        $preferredInstanceId = (string)($route['instance_id'] ?? '');
        $preferredInstance = $instancesById[
            'instance:' . $preferredInstanceId
        ] ?? null;
        if (!\hash_equals(
            $this->canonicalJson($backends),
            $this->canonicalJson($flattenedBackends),
        ) || ($backendInstances === []
            ? ($backends !== [] || $identity !== [])
            : (!\is_array($preferredInstance)
                || $identity === []
                || !\hash_equals(
                    $this->canonicalJson($identity),
                    $this->canonicalJson(
                        $preferredInstance['backend_identity'] ?? null,
                    ),
                )))
        ) {
            throw new \RuntimeException(
                'Gateway route projection is not one exact transport closure.'
            );
        }
        [$rootToWwwTarget, $rootToWwwTargetReady]
            = $this->routeWireRedirectClosure($route, $publicationRoutes);
        $certificate = \is_array($route['certificate'] ?? null)
            ? $route['certificate']
            : [];
        return [
            'route_id' => (string)($route['route_id'] ?? ''),
            'project_uuid' => (string)($route['project_uuid'] ?? ''),
            'instance_id' => \substr(
                (string)($route['instance_id'] ?? ''),
                0,
                self::MAX_INSTANCE_ID_BYTES,
            ),
            'domain' => (string)($route['domain'] ?? ''),
            'backends' => $backends,
            'backend_instances' => $backendInstances,
            'backend_identity' => $identity,
            'certificate' => [
                'state' => $this->certificateLifecycleState($certificate),
                'valid' => (bool)($certificate['valid'] ?? false),
                'pending' => (bool)($certificate['pending'] ?? false),
                'source_digest' => (string)($certificate['source_digest'] ?? ''),
                'snapshot_digest' => (string)($certificate['snapshot_digest'] ?? ''),
                'generation' => (int)($certificate['generation'] ?? 0),
                'not_after' => (int)($certificate['not_after'] ?? 0),
            ],
            'route_generation' => (int)($route['route_generation'] ?? 0),
            'domain_security_generation' => (int)(
                $route['domain_security_generation'] ?? 0
            ),
            'status' => (string)($route['status'] ?? ''),
            'last_heartbeat' => (int)($route['last_heartbeat'] ?? 0),
            'last_backend_probe' => (int)($route['last_backend_probe'] ?? 0),
            'stale_since' => isset($route['stale_since'])
                ? (int)$route['stale_since']
                : null,
            'drain_until' => isset($route['drain_until'])
                ? (int)$route['drain_until']
                : null,
            'force_https' => (bool)($route['force_https'] ?? true),
            'force_root_to_www' => (bool)($route['force_root_to_www'] ?? false),
            'root_to_www_target' => $rootToWwwTarget,
            'root_to_www_target_ready' => $rootToWwwTargetReady,
            'updated_at' => (string)($route['updated_at'] ?? ''),
        ];
    }

    /** @return list<array{host:string,port:int,weight:int}> */
    private function routeWireBackends(mixed $value): array
    {
        if (!\is_array($value) || \count($value) > self::MAX_BACKENDS_PER_ROUTE) {
            throw new \RuntimeException(
                'Gateway route backend projection exceeds its protocol bound.'
            );
        }
        $backends = [];
        $seen = [];
        foreach ($value as $backend) {
            if (!\is_array($backend)) {
                throw new \RuntimeException('Gateway route backend projection is malformed.');
            }
            $host = (string)($backend['host'] ?? '');
            $port = (int)($backend['port'] ?? 0);
            $weight = (int)($backend['weight'] ?? 0);
            $key = $host . ':' . $port;
            if (!\in_array($host, ['127.0.0.1', '::1'], true)
                || $port < 1
                || $port > 65535
                || $weight < 1
                || $weight > 1000
                || isset($seen[$key])
            ) {
                throw new \RuntimeException('Gateway route backend projection is malformed.');
            }
            $seen[$key] = true;
            $backends[] = [
                'host' => $host,
                'port' => $port,
                'weight' => $weight,
            ];
        }
        return $backends;
    }

    /** @param array<string,mixed> $identity @return array<string,mixed> */
    private function routeWireBackendIdentity(array $identity): array
    {
        if ($identity === []) {
            return [];
        }
        try {
            return $this->publicBackendIdentityProjection($identity);
        } catch (\Throwable) {
            // Preserve authenticated diagnostics for a damaged/pre-upgrade
            // route, but never emit a partial identity that could be mistaken
            // for a usable listener proof.
            return [];
        }
    }

    /**
     * Numeric-only instance IDs are valid protocol identities. They cannot be
     * used as JSON object keys safely because PHP coerces them to integers and
     * a sole `0` key is serialized as a list. Keep the public wire shape an
     * explicitly sorted list; each row carries its own authenticated ID.
     *
     * @param array<string,mixed> $route
     * @return list<array{instance_id:string,backends:list<array{host:string,port:int,weight:int}>,backend_identity:array<string,mixed>}>
     */
    private function routeWireBackendInstances(array $route): array
    {
        $instances = $this->routeBackendInstances($route);
        if (\count($instances) > self::MAX_BACKENDS_PER_ROUTE) {
            throw new \RuntimeException(
                'Gateway route instance projection exceeds its protocol bound.'
            );
        }
        $projected = [];
        $seen = [];
        $backendCount = 0;
        foreach ($instances as $instanceKey => $instance) {
            $instanceId = (string)$instanceKey;
            if (\preg_match(
                    '/\A[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}\z/D',
                    $instanceId,
                ) !== 1
                || !\is_array($instance)
                || isset($seen['instance:' . $instanceId])
            ) {
                throw new \RuntimeException('Gateway route instance projection is malformed.');
            }
            $declaredInstanceId = (string)($instance['instance_id'] ?? '');
            $backends = $this->routeWireBackends($instance['backends'] ?? []);
            $identity = \is_array($instance['backend_identity'] ?? null)
                ? $this->routeWireBackendIdentity($instance['backend_identity'])
                : [];
            $backendCount += \count($backends);
            if (!\hash_equals($instanceId, $declaredInstanceId)
                || $backends === []
                || $backendCount > self::MAX_BACKENDS_PER_ROUTE
                || $identity === []
                || !\hash_equals(
                    $instanceId,
                    (string)($identity['instance_id'] ?? ''),
                )
            ) {
                throw new \RuntimeException('Gateway route instance projection is malformed.');
            }
            $seen['instance:' . $instanceId] = true;
            $projected[] = [
                'instance_id' => $instanceId,
                'backends' => $backends,
                'backend_identity' => $identity,
            ];
        }
        \usort(
            $projected,
            static fn (array $left, array $right): int =>
                (string)$left['instance_id'] <=> (string)$right['instance_id'],
        );
        return $projected;
    }

    /**
     * Derive redirect readiness from the exact collection being signed. For
     * ACTIVE pages that collection is the immutable active_routes snapshot,
     * so desired state can never make an unpublished target look ready.
     *
     * @param array<string,mixed> $route
     * @param list<array<string,mixed>> $publicationRoutes
     * @return array{0:string,1:bool}
     */
    private function routeWireRedirectClosure(
        array $route,
        array $publicationRoutes,
    ): array {
        if (($route['force_root_to_www'] ?? false) !== true) {
            return ['', true];
        }
        $projectUuid = (string)($route['project_uuid'] ?? '');
        $domain = $this->normalizeDomain((string)($route['domain'] ?? ''));
        if (!$this->validProjectUuid($projectUuid)
            || \str_starts_with($domain, '*.')
            || \str_starts_with($domain, 'www.')
        ) {
            throw new \RuntimeException(
                'Gateway redirect source cannot be projected from malformed route state.'
            );
        }
        $targetDomain = $this->normalizeDomain('www.' . $domain);
        $matches = [];
        foreach ($publicationRoutes as $candidate) {
            if (\is_array($candidate)
                && \hash_equals(
                    $projectUuid,
                    (string)($candidate['project_uuid'] ?? ''),
                )
                && \hash_equals(
                    $targetDomain,
                    (string)($candidate['domain'] ?? ''),
                )
                && (string)($candidate['status'] ?? '') !== 'REMOVED'
            ) {
                $matches[] = $candidate;
            }
        }
        if (\count($matches) !== 1) {
            return [$targetDomain, false];
        }
        $target = $matches[0];
        $targetInstances = $this->routeWireBackendInstances($target);
        $ready = (string)($target['status'] ?? '') === 'ACTIVE'
            && $this->routeAllowedBySecurity($target)
            && $this->certificateSnapshotValidForDomain(
                (array)($target['certificate'] ?? []),
                $targetDomain,
            )
            && $this->routeWireBackends($target['backends'] ?? []) !== []
            && $targetInstances !== [];
        return [$targetDomain, $ready];
    }

    private function encodeRoutePageCursor(
        int $offset,
        string $scope,
        string $principal,
        string $fenceDigest,
    ): string {
        $body = $this->canonicalJson([
            'fence_digest' => $fenceDigest,
            'offset' => $offset,
            'principal' => $principal,
            'scope' => $scope,
        ]);
        $signature = \hash_hmac('sha256', $body, $this->routePageSecret($principal));
        return \rtrim(\strtr(\base64_encode($body . "\n" . $signature), '+/', '-_'), '=');
    }

    private function decodeRoutePageCursor(
        string $cursor,
        string $scope,
        string $principal,
        string $fenceDigest,
    ): int {
        if (\preg_match('/\A[A-Za-z0-9_-]{1,1024}\z/D', $cursor) !== 1) {
            throw new \DomainException('Gateway route page cursor is invalid.');
        }
        $padding = (4 - \strlen($cursor) % 4) % 4;
        $decoded = \base64_decode(
            \strtr($cursor . \str_repeat('=', $padding), '-_', '+/'),
            true,
        );
        if (!\is_string($decoded) || \strlen($decoded) > 768) {
            throw new \DomainException('Gateway route page cursor is invalid.');
        }
        $separator = \strrpos($decoded, "\n");
        if ($separator === false) {
            throw new \DomainException('Gateway route page cursor is invalid.');
        }
        $body = \substr($decoded, 0, $separator);
        $signature = \substr($decoded, $separator + 1);
        $expected = \hash_hmac('sha256', $body, $this->routePageSecret($principal));
        $value = \json_decode($body, true);
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $signature) !== 1
            || !\hash_equals($expected, $signature)
            || !\is_array($value)
            || !\hash_equals($scope, (string)($value['scope'] ?? ''))
            || !\hash_equals($principal, (string)($value['principal'] ?? ''))
            || !\hash_equals($fenceDigest, (string)($value['fence_digest'] ?? ''))
            || !\is_int($value['offset'] ?? null)
            || (int)$value['offset'] < 0
        ) {
            throw new \DomainException(
                'Gateway route page changed generation, digest, epoch, or principal.',
            );
        }
        return (int)$value['offset'];
    }

    private function routePageSecret(string $principal): string
    {
        $secret = $principal === 'admin'
            ? \strtolower(\trim($this->readStableRegularFile(
                $this->adminTokenFile(),
                65,
                'Gateway administrator credential',
            )))
            : (string)(
                $this->state['enrollments'][$principal]['credential_secret'] ?? ''
            );
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $secret) !== 1) {
            throw new \RuntimeException('Gateway route page signing credential is unavailable.');
        }
        return $secret;
    }

    private function projectHasPublishedActiveRoute(string $projectUuid): bool
    {
        return $this->projectPublicationAssessment($projectUuid)['ready'];
    }

    private function projectPublicationExact(string $projectUuid): bool
    {
        return $this->projectPublicationAssessment($projectUuid)['exact'];
    }

    /**
     * A partially issued multi-domain project is still serviceable: every
     * certificate-ready route must be the exact ACTIVE publication with a
     * fresh public proof, while an exact PENDING_CERTIFICATE route contributes
     * only its HTTP-01/404 surface and must not suppress healthy siblings.
     *
     * @return array{
     *     exact:bool,
     *     ready:bool,
     *     converged:bool,
     *     active_route_count:int,
     *     pending_certificate_route_count:int
     * }
     */
    private function projectPublicationAssessment(string $projectUuid): array
    {
        $empty = [
            'exact' => false,
            'ready' => false,
            'converged' => false,
            'active_route_count' => 0,
            'pending_certificate_route_count' => 0,
        ];
        if ((int)($this->state['active_config_generation'] ?? 0) < 1) {
            return $empty;
        }
        $project = $this->state['projects'][$projectUuid] ?? null;
        if (!\is_array($project)) {
            return $empty;
        }
        $expectedRouteIds = \array_values(\array_unique(\array_map(
            'strval',
            (array)($project['route_ids'] ?? []),
        )));
        $publishedRouteIds = [];
        foreach ((array)($this->state['active_routes'] ?? []) as $routeId => $published) {
            if (\is_array($published)
                && \hash_equals(
                    $projectUuid,
                    (string)($published['project_uuid'] ?? ''),
                )
                && (string)($published['status'] ?? '') !== 'REMOVED'
            ) {
                $publishedRouteIds[] = (string)$routeId;
            }
        }
        \sort($expectedRouteIds, SORT_STRING);
        \sort($publishedRouteIds, SORT_STRING);
        if ($expectedRouteIds === [] || $expectedRouteIds !== $publishedRouteIds) {
            return $empty;
        }
        $activeRouteCount = 0;
        $disabledRouteCount = 0;
        $pendingCertificateRouteCount = 0;
        $certificateReadyNonActive = false;
        foreach ($expectedRouteIds as $routeId) {
            $published = $this->state['active_routes'][$routeId] ?? null;
            $current = $this->state['routes'][$routeId] ?? null;
            if (!\is_array($published)
                || !\is_array($current)
                || !$this->routeAllowedBySecurity($published)
                || !$this->routeAllowedBySecurity($current)
                || !$this->publishedRouteMatchesCurrentDesired($published, $current)
            ) {
                return $empty;
            }
            $status = (string)($current['status'] ?? '');
            $domain = (string)($current['domain'] ?? '');
            $certificate = (array)($current['certificate'] ?? []);
            $certificateReady = $this->certificateSnapshotValidForDomain(
                $certificate,
                $domain,
            );
            if ($status === 'PENDING_CERTIFICATE') {
                $certificateState = $this->certificateLifecycleState($certificate);
                $inactiveStateValid = ($certificateState === 'pending'
                    && (int)($certificate['generation'] ?? -1) === 0
                    && \hash_equals(
                        \hash('sha256', "wls-pending-certificate\0" . $domain),
                        (string)($certificate['source_digest'] ?? ''),
                    ))
                    || ($certificateState === 'disabled'
                        && (int)($certificate['generation'] ?? 0) >= 1
                        && ($current['force_https'] ?? true) === false
                        && ($current['force_root_to_www'] ?? true) === false
                        && \hash_equals(
                            \hash(
                                'sha256',
                                "wls-disabled-certificate\0" . $domain . "\0"
                                    . (int)$certificate['generation'],
                            ),
                            (string)($certificate['source_digest'] ?? ''),
                        ));
                if ($certificateReady
                    || !$inactiveStateValid
                    || ($certificate['valid'] ?? true) !== false
                    || ($certificate['pending'] ?? false) !== true
                    || (string)($certificate['snapshot_digest'] ?? '') !== ''
                    || (string)($certificate['cert_path'] ?? '') !== ''
                    || (string)($certificate['key_path'] ?? '') !== ''
                    || \preg_match(
                        '/\A[a-f0-9]{64}\z/D',
                        (string)($certificate['source_digest'] ?? ''),
                    ) !== 1
                ) {
                    return $empty;
                }
                if ($certificateState === 'disabled') {
                    if ((array)($published['backends'] ?? []) === []
                        || (array)($published['backend_instances'] ?? []) === []
                        || !$this->publicRouteProbeProofMatches($published, true)
                    ) {
                        return $empty;
                    }
                    ++$disabledRouteCount;
                }
                ++$pendingCertificateRouteCount;
                continue;
            }
            if (!$certificateReady
                || !\hash_equals('active', $this->certificateLifecycleState($certificate))
            ) {
                return $empty;
            }
            if ($status !== 'ACTIVE') {
                if (!\in_array(
                    $status,
                    ['PENDING_BACKEND', 'DRAINING', 'STALE'],
                    true,
                )) {
                    return $empty;
                }
                $certificateReadyNonActive = true;
                continue;
            }
            if ((array)($published['backends'] ?? []) === []
                || (array)($published['backend_instances'] ?? []) === []
                || !$this->publicRouteProbeProofMatches($published, true)
            ) {
                return $empty;
            }
            ++$activeRouteCount;
        }
        $exact = true;
        return [
            'exact' => $exact,
            'ready' => ($activeRouteCount + $disabledRouteCount) > 0
                && !$certificateReadyNonActive,
            'converged' => ($activeRouteCount + $disabledRouteCount)
                === \count($expectedRouteIds),
            'active_route_count' => $activeRouteCount,
            'pending_certificate_route_count' => $pendingCertificateRouteCount,
        ];
    }

    /**
     * @param array<string,mixed> $published
     * @param array<string,mixed> $current
     */
    private function publishedRouteMatchesCurrentDesired(
        array $published,
        array $current,
    ): bool {
        $publishedCertificate = (array)($published['certificate'] ?? []);
        $currentCertificate = (array)($current['certificate'] ?? []);
        return \hash_equals(
                (string)($published['route_id'] ?? ''),
                (string)($current['route_id'] ?? ''),
            )
            && \hash_equals(
                (string)($published['project_uuid'] ?? ''),
                (string)($current['project_uuid'] ?? ''),
            )
            && \hash_equals(
                (string)($published['domain'] ?? ''),
                (string)($current['domain'] ?? ''),
            )
            && (int)($published['route_generation'] ?? 0)
                === (int)($current['route_generation'] ?? -1)
            && (bool)($published['force_https'] ?? true)
                === (bool)($current['force_https'] ?? true)
            && (bool)($published['force_root_to_www'] ?? false)
                === (bool)($current['force_root_to_www'] ?? false)
            && \hash_equals(
                (string)($publishedCertificate['source_digest'] ?? ''),
                (string)($currentCertificate['source_digest'] ?? ''),
            )
            && (int)($publishedCertificate['generation'] ?? 0)
                === (int)($currentCertificate['generation'] ?? -1)
            && \hash_equals(
                (string)($publishedCertificate['snapshot_digest'] ?? ''),
                (string)($currentCertificate['snapshot_digest'] ?? ''),
            )
            && \hash_equals(
                $this->routeRoutingDigest($published),
                $this->routeRoutingDigest($current),
            );
    }

    /**
     * A project readiness proof is route-local. Host-global ROUTE_DEGRADED
     * must not make one tenant borrow another tenant's successful sentinel,
     * and a stale proof must not survive a config generation/backend/cert
     * transition.
     *
     * @param array<string,mixed> $route
     */
    private function publicRouteProbeProofMatches(
        array $route,
        bool $requireAvailable,
    ): bool {
        $routeId = (string)($route['route_id'] ?? '');
        $proof = $this->publicRouteProbeResults[$routeId] ?? null;
        if (!\is_array($proof)
            || ($proof['success'] ?? false) !== true
            || ($requireAvailable && ($proof['available'] ?? false) !== true)
            || !\hash_equals(
                $this->hostBootId,
                (string)($proof['boot_id'] ?? ''),
            )
            || (int)($proof['generation'] ?? 0)
                !== (int)($this->state['active_config_generation'] ?? 0)
            || !\hash_equals(
                $this->routeRoutingDigest($route),
                (string)($proof['route_digest'] ?? ''),
            )
        ) {
            return false;
        }
        $age = $this->monotonicNow()
            - (float)($proof['observed_monotonic'] ?? 0.0);
        return $age >= 0.0
            && $age <= self::PUBLIC_ROUTE_PROBE_PROOF_TTL_SECONDS;
    }

    /**
     * @return array<string,mixed>
     */
    private function operationWireProjection(array $operation): array
    {
        $result = \is_array($operation['result'] ?? null)
            ? $operation['result']
            : [];
        $receipt = \is_array($operation['lease_receipt'] ?? null)
            ? $operation['lease_receipt']
            : [];
        return [
            'operation_id' => (string)($operation['operation_id'] ?? ''),
            'operation' => (string)($operation['operation'] ?? ''),
            'state' => (string)($operation['state'] ?? 'UNKNOWN'),
            'desired_generation' => (int)($operation['desired_generation'] ?? 0),
            'active_generation' => (int)($operation['active_generation'] ?? 0),
            'transaction_id' => (string)($operation['transaction_id'] ?? ''),
            'created_at' => (string)($operation['created_at'] ?? ''),
            'updated_at' => (string)($operation['updated_at'] ?? ''),
            'completed_at' => (string)($operation['completed_at'] ?? ''),
            'error' => \substr((string)($operation['error'] ?? ''), 0, 1024),
            'result_digest' => $result !== []
                ? \hash('sha256', $this->canonicalJson($result))
                : '',
            'lease_receipt_digest' => $receipt !== []
                ? \hash('sha256', $this->canonicalJson($receipt))
                : '',
        ];
    }

    /**
     * @return array<string,mixed>
     */
    private function operationStatus(
        string $operationId,
        string $principal,
        bool $administrator,
    ): array {
        $operationId = \strtolower(\trim($operationId));
        if (\preg_match('/\A[a-f0-9]{32}\z/D', $operationId) !== 1) {
            throw new \DomainException('Gateway operation ID is invalid.');
        }
        $operation = $this->state['operations'][$operationId] ?? null;
        if (!\is_array($operation)) {
            throw new \DomainException('Gateway operation was not found or has expired.');
        }
        if (!$administrator
            && !\hash_equals($principal, (string)($operation['project_uuid'] ?? ''))
        ) {
            throw new \DomainException('Gateway operation belongs to another project.');
        }
        $result = [
            'operation_id' => $operationId,
            'operation' => (string)($operation['operation'] ?? ''),
            'state' => (string)($operation['state'] ?? 'UNKNOWN'),
            'desired_generation' => (int)($operation['desired_generation'] ?? 0),
            'active_generation' => (int)($operation['active_generation'] ?? 0),
            'transaction_id' => (string)($operation['transaction_id'] ?? ''),
            'created_at' => (string)($operation['created_at'] ?? ''),
            'updated_at' => (string)($operation['updated_at'] ?? ''),
            'completed_at' => (string)($operation['completed_at'] ?? ''),
            'error' => (string)($operation['error'] ?? ''),
        ];
        $operationResult = \is_array($operation['result'] ?? null)
            ? $operation['result']
            : [];
        if ($operationResult !== []) {
            $result['result'] = $operationResult;
        }
        if (\is_array($operation['lease_receipt'] ?? null)) {
            $result['lease_receipt'] = $operation['lease_receipt'];
        }
        return $result;
    }

    private function brokerInternalReady(): bool
    {
        return $this->brokerInternalEndpoint !== null
            && $this->ownedBrokerGenerationToken() !== '';
    }

    private function brokerGenerationOwned(): bool
    {
        if ($this->brokerInternalEndpoint === null) {
            return true;
        }
        if (\preg_match(
            '/\A[a-f0-9]{64}\z/D',
            $this->brokerGenerationFencingToken,
        ) !== 1) {
            return false;
        }
        $active = $this->brokerFencingToken();
        return $active !== ''
            && \hash_equals($this->brokerGenerationFencingToken, $active);
    }

    private function ownedBrokerGenerationToken(): string
    {
        return $this->brokerGenerationOwned()
            ? $this->brokerGenerationFencingToken
            : '';
    }

    private function assertBrokerGenerationOwnership(string $operation): void
    {
        if ($this->brokerGenerationOwned()) {
            return;
        }
        // Do not persist a health transition or touch Nginx: the replacement
        // Broker generation owns recovery now. Exiting the control plane
        // leaves the verified data plane available for no-reload adoption.
        $this->running = false;
        throw new \DomainException(
            'Native Broker generation changed; the retired Controller refuses '
                . $operation . ' and is exiting.'
        );
    }

    private function brokerFencingToken(): string
    {
        try {
            $file = $this->brokerFencingFile();
        } catch (\Throwable) {
            return '';
        }
        $status = @\lstat($file);
        if (!\is_array($status)
            || !\is_file($file)
            || \is_link($file)
            || (int)($status['size'] ?? -1) < 64
            || (int)($status['size'] ?? -1) > 65
        ) {
            return '';
        }
        if (\PHP_OS_FAMILY !== 'Windows') {
            $mode = (int)($status['mode'] ?? 0);
            $owner = (int)($status['uid'] ?? -1);
            $current = \function_exists('posix_geteuid') ? (int)\posix_geteuid() : -2;
            try {
                // This check is also used before gateway state is loaded to
                // lock the Controller's Broker generation. Read the
                // root-owned active-slot pointer directly instead of
                // consulting the not-yet-initialized state projection.
                $testMode = ($this->slotManifestFromActiveFile()['test_mode'] ?? false) === true;
            } catch (\Throwable) {
                return '';
            }
            $directory = @\lstat(\dirname($file));
            if (($mode & 0170000) !== 0100000
                || ($mode & 0022) !== 0
                || !\is_array($directory)
                || ((int)($directory['mode'] ?? 0) & 0170000) !== 0040000
                || (((int)($directory['mode'] ?? 0)) & 0022) !== 0
                || \is_link(\dirname($file))
                || ($owner !== 0 && (!$testMode || $owner !== $current))
                || ((int)($directory['uid'] ?? -1) !== 0
                    && (!$testMode || (int)$directory['uid'] !== $current))
            ) {
                return '';
            }
        }
        try {
            $contents = $this->readStableRegularFile(
                $file,
                65,
                'Native Broker fencing token',
            );
        } catch (\Throwable) {
            return '';
        }
        if (\preg_match('/\A([a-f0-9]{64})(?:\n)?\z/D', $contents, $matches) !== 1) {
            return '';
        }
        return (string)$matches[1];
    }

    private function brokerActionsRequired(): bool
    {
        return ($this->slotManifest()['test_mode'] ?? false) !== true;
    }

    private function brokerActionsAvailable(string $channel): bool
    {
        return \is_resource($this->brokerExchange)
            && \is_array($this->activeBrokerPeer)
            && (int)($this->activeBrokerPeer['action_protocol'] ?? 0) === 2
            && \hash_equals($channel, (string)($this->activeBrokerPeer['channel'] ?? ''));
    }

    private function currentBrokerActionAvailable(): bool
    {
        $channel = (string)($this->activeBrokerPeer['channel'] ?? '');
        return \in_array($channel, ['admin', 'project'], true)
            && $this->brokerActionsAvailable($channel);
    }

    private function brokerDrivenActionPending(): bool
    {
        return $this->brokerActionsRequired()
            && !$this->currentBrokerActionAvailable();
    }

    /**
     * @param list<string> $fields
     * @return list<string> Opcode-specific response fields, excluding the opcode.
     */
    private function brokerAction(string $channel, array $fields): array
    {
        if (!$this->brokerActionsAvailable($channel)) {
            throw new \RuntimeException(
                'Native Broker action protocol is unavailable for this request.'
            );
        }
        $opcode = (string)($fields[0] ?? '');
        if (\preg_match('/\A[A-Z][A-Z0-9_]{1,63}\z/D', $opcode) !== 1) {
            throw new \DomainException('Native Broker action opcode is invalid.');
        }
        foreach ($fields as $field) {
            if ($field === '' || \str_contains($field, "\0")
                || \str_contains($field, "\t") || \str_contains($field, "\n")
                || \str_contains($field, "\r")
            ) {
                throw new \DomainException('Native Broker action field is invalid.');
            }
        }
        $line = 'WLS-ACTION/2' . "\t" . \implode("\t", $fields) . "\n";
        if (\strlen($line) > 65_536) {
            throw new \DomainException('Native Broker action request is too large.');
        }
        $response = $this->exchangeBrokerActionLine($line);
        if (!\is_string($response)
            || $response === ''
            || !\str_ends_with($response, "\n")
            || \strlen($response) > 65_536
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid restricted-action response.'
            );
        }
        $response = \rtrim($response, "\r\n");
        if (\str_contains($response, "\0")) {
            throw new \RuntimeException(
                'Native Broker returned an invalid restricted-action response.'
            );
        }
        $parts = \explode("\t", $response);
        if (!\hash_equals('WLS-ACTION/2', (string)($parts[0] ?? ''))) {
            throw new \RuntimeException(
                'Native Broker returned an incompatible restricted-action protocol.'
            );
        }
        $status = (string)($parts[1] ?? '');
        if ($status === 'ERR') {
            $code = (string)($parts[2] ?? 'BROKER_REJECTED');
            $responseOpcode = (string)($parts[3] ?? '');
            [$expectedTransaction, $expectedIntent] =
                $this->brokerActionErrorBinding($opcode, $fields);
            if (\preg_match('/\A[A-Z][A-Z0-9_]{1,63}\z/D', $code) !== 1
                || !\hash_equals($opcode, $responseOpcode)
                || \count($parts) !== 6
                || !\hash_equals($expectedTransaction, (string)($parts[4] ?? ''))
                || !\hash_equals($expectedIntent, (string)($parts[5] ?? ''))
            ) {
                throw new \RuntimeException(
                    'Native Broker returned a malformed restricted-action rejection.'
                );
            }
            throw new \RuntimeException(
                'Native Broker rejected ' . $opcode . ' with stable code ' . $code . '.'
            );
        }
        if ($status !== 'OK'
            || !\hash_equals($opcode, (string)($parts[2] ?? ''))
        ) {
            throw new \RuntimeException(
                'Native Broker returned a malformed restricted-action acknowledgement.'
            );
        }
        $this->state['broker_action_verified'] = true;
        return \array_values(\array_slice($parts, 3));
    }

    private function exchangeBrokerActionLine(string $line): string
    {
        if (!\is_resource($this->brokerExchange)
            || !@\stream_set_blocking($this->brokerExchange, false)
        ) {
            throw new \RuntimeException(
                'Native Broker action exchange could not enter bounded I/O mode.'
            );
        }
        $deadline = $this->monotonicNow() + self::BROKER_ACTION_TIMEOUT_SECONDS;
        $offset = 0;
        $response = '';
        try {
            while ($offset < \strlen($line)) {
                $remaining = $deadline - $this->monotonicNow();
                if ($remaining <= 0.0) {
                    throw new \RuntimeException(
                        'Native Broker action request exceeded its absolute write deadline.'
                    );
                }
                $read = [];
                $write = [$this->brokerExchange];
                $except = [];
                $seconds = (int)\floor($remaining);
                $microseconds = (int)\floor(($remaining - $seconds) * 1_000_000);
                $selected = @\stream_select(
                    $read,
                    $write,
                    $except,
                    $seconds,
                    $microseconds,
                );
                if ($selected === false) {
                    continue;
                }
                if ($selected === 0) {
                    throw new \RuntimeException(
                        'Native Broker action request exceeded its absolute write deadline.'
                    );
                }
                $written = @\fwrite($this->brokerExchange, \substr($line, $offset));
                if (!\is_int($written) || $written < 1) {
                    throw new \RuntimeException(
                        'Native Broker action request could not be written.'
                    );
                }
                $offset += $written;
            }
            while (!\str_contains($response, "\n")) {
                $remaining = $deadline - $this->monotonicNow();
                if ($remaining <= 0.0) {
                    throw new \RuntimeException(
                        'Native Broker action response exceeded its absolute read deadline.'
                    );
                }
                $read = [$this->brokerExchange];
                $write = [];
                $except = [];
                $seconds = (int)\floor($remaining);
                $microseconds = (int)\floor(($remaining - $seconds) * 1_000_000);
                $selected = @\stream_select(
                    $read,
                    $write,
                    $except,
                    $seconds,
                    $microseconds,
                );
                if ($selected === false) {
                    continue;
                }
                if ($selected === 0) {
                    throw new \RuntimeException(
                        'Native Broker action response exceeded its absolute read deadline.'
                    );
                }
                $chunk = @\fread(
                    $this->brokerExchange,
                    65_537 - \strlen($response),
                );
                if (!\is_string($chunk) || $chunk === '') {
                    throw new \RuntimeException(
                        'Native Broker action response ended before acknowledgement.'
                    );
                }
                $response .= $chunk;
                if (\strlen($response) > 65_536) {
                    throw new \RuntimeException(
                        'Native Broker action response exceeds its byte contract.'
                    );
                }
            }
            if (!\str_ends_with($response, "\n")
                || \substr_count($response, "\n") !== 1
            ) {
                throw new \RuntimeException(
                    'Native Broker returned multiple or trailing action responses.'
                );
            }
            return $response;
        } finally {
            if (\is_resource($this->brokerExchange)) {
                @\stream_set_blocking($this->brokerExchange, true);
                $this->configureClientReadTimeout(
                    $this->brokerExchange,
                    self::BROKER_ACTION_TIMEOUT_SECONDS,
                );
            }
        }
    }

    /**
     * @param list<string> $fields
     * @return array{0:string,1:string}
     */
    private function brokerActionErrorBinding(string $opcode, array $fields): array
    {
        if (\in_array($opcode, [
            'AUTH_PREPARE',
            'AUTH_COMMIT',
            'AUTH_ABORT',
            'ATTEST_ROOT',
            'SNAP',
            'EMERGENCY_BIND',
        ], true)) {
            return [(string)($fields[2] ?? '-'), (string)($fields[3] ?? '-')];
        }
        if (\in_array($opcode, [
            'SECURITY_RESERVE',
            'SECURITY_COMMIT',
            'SECURITY_ABORT',
        ], true)) {
            return [(string)($fields[1] ?? '-'), (string)($fields[2] ?? '-')];
        }
        if (\in_array($opcode, [
            'AUTH_TRANSFER_PREPARE',
            'AUTH_TRANSFER_COMMIT',
            'AUTH_TRANSFER_ABORT',
            'AUTH_TRANSFER_ATTEST',
        ], true)) {
            return [(string)($fields[3] ?? '-'), (string)($fields[4] ?? '-')];
        }
        return ['-', '-'];
    }

    /** @param array{kind:string,uid?:int,gid?:int,sid?:string} $owner */
    private function brokerOwnerIdentity(array $owner): string
    {
        if ((string)($owner['kind'] ?? '') === 'posix'
            && (int)($owner['uid'] ?? -1) >= 0
        ) {
            return (string)(int)$owner['uid'];
        }
        $sid = \strtoupper((string)($owner['sid'] ?? ''));
        if ((string)($owner['kind'] ?? '') === 'windows'
            && \preg_match('/\AS-1-(?:[0-9]+-)+[0-9]+\z/D', $sid) === 1
        ) {
            return $sid;
        }
        throw new \RuntimeException(
            'Native Broker enrollment transaction requires a verified OS owner identity.'
        );
    }

    /**
     * @param array<string,string> $roots
     * @param array{kind:string,uid?:int,gid?:int,sid?:string} $owner
     * @return array{assigned_generation:int,root_attestations:array<string,array<string,mixed>>}
     */
    private function prepareBrokerCertificateRoots(
        string $transactionId,
        string $projectUuid,
        string $intentDigest,
        int $expectedPreviousGeneration,
        string $projectRoot,
        array $roots,
        array $owner,
    ): array {
        \ksort($roots, SORT_STRING);
        $this->assertSecurityAllocationSerialized($transactionId);
        if (!$this->brokerActionsAvailable('admin')) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production enrollment requires native Broker AUTH_PREPARE.'
                );
            }
            return [
                'assigned_generation' => $this->nextSecurityGeneration(),
                'root_attestations' => [],
            ];
        }
        $ownerIdentity = $this->brokerOwnerIdentity($owner);
        $assignedGeneration = 0;
        $attestations = [];
        $rootCount = \count($roots);
        foreach ($roots as $alias => $root) {
            $response = $this->brokerAction('admin', [
                'AUTH_PREPARE',
                $projectUuid,
                $transactionId,
                $intentDigest,
                $ownerIdentity,
                (string)$alias,
                \bin2hex($projectRoot),
                \bin2hex((string)$root),
                (string)$rootCount,
                (string)$expectedPreviousGeneration,
            ]);
            if (\count($response) !== 6
                || !\hash_equals($transactionId, (string)$response[0])
                || !\hash_equals($intentDigest, (string)$response[1])
                || \preg_match('/\A[1-9][0-9]*\z/D', (string)$response[2]) !== 1
                || \preg_match('/\A[a-f0-9]{1,32}-[a-f0-9]{1,32}\z/D', (string)$response[3]) !== 1
                || \preg_match('/\A[a-f0-9]{1,32}-[a-f0-9]{1,32}\z/D', (string)$response[4]) !== 1
                || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[5]) !== 1
            ) {
                throw new \RuntimeException(
                    'Native Broker returned an invalid AUTH_PREPARE root attestation.'
                );
            }
            $rootGeneration = (int)$response[2];
            if ($assignedGeneration !== 0 && $assignedGeneration !== $rootGeneration) {
                throw new \RuntimeException(
                    'Native Broker split one enrollment across multiple security generations.'
                );
            }
            $assignedGeneration = $rootGeneration;
            $attestations[(string)$alias] = [
                'project_object_id' => (string)$response[3],
                'certificate_object_id' => (string)$response[4],
                'attestation_digest' => (string)$response[5],
            ];
        }
        if ($assignedGeneration <= $expectedPreviousGeneration
            || \count($attestations) !== $rootCount
        ) {
            throw new \RuntimeException(
                'Native Broker did not allocate a complete monotonic enrollment generation.'
            );
        }
        $previousAnchor = (string)(
            $this->state['native_security_anchor_digest'] ?? ''
        );
        $nativeSecurity = $this->attestNativeSecurityState(
            'admin',
            $expectedPreviousGeneration,
            '-',
            \preg_match('/\A[a-f0-9]{64}\z/D', $previousAnchor) === 1
                ? $previousAnchor
                : '-',
        );
        if ($nativeSecurity['allocated'] !== $assignedGeneration
            || $nativeSecurity['committed'] !== $expectedPreviousGeneration
        ) {
            throw new \RuntimeException(
                'Native AUTH_PREPARE allocation is not security-attested.'
            );
        }
        $this->recordNativeSecurityState($nativeSecurity);
        return [
            'assigned_generation' => $assignedGeneration,
            'root_attestations' => $attestations,
        ];
    }

    private function commitBrokerCertificateRoots(
        string $transactionId,
        string $projectUuid,
        string $intentDigest,
        int $securityGeneration,
        array $rootAttestations,
    ): void {
        if (!$this->brokerActionsAvailable('admin')) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production enrollment requires native Broker AUTH_COMMIT.'
                );
            }
            return;
        }
        \ksort($rootAttestations, SORT_STRING);
        $proofLines = '';
        foreach ($rootAttestations as $alias => $attestation) {
            if (!\is_array($attestation)) {
                throw new \RuntimeException('Enrollment root attestation is invalid.');
            }
            $proofLines .= (string)$alias . "\t" . $securityGeneration . "\t"
                . (string)($attestation['project_object_id'] ?? '') . "\t"
                . (string)($attestation['certificate_object_id'] ?? '') . "\t"
                . (string)($attestation['attestation_digest'] ?? '') . "\n";
        }
        $rootCount = \count($rootAttestations);
        if ($rootCount < 1) {
            throw new \RuntimeException('Enrollment root attestation set is empty.');
        }
        $rootsDigest = \hash('sha256', $proofLines);
        $response = $this->brokerAction('admin', [
            'AUTH_COMMIT',
            $projectUuid,
            $transactionId,
            $intentDigest,
            (string)$rootCount,
            $rootsDigest,
        ]);
        if (\count($response) !== 6
            || !\hash_equals($transactionId, (string)$response[0])
            || !\hash_equals($intentDigest, (string)$response[1])
            || (int)$response[2] !== $securityGeneration
            || (int)$response[3] !== $rootCount
            || !\hash_equals($rootsDigest, (string)$response[4])
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[5]) !== 1
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid AUTH_COMMIT acknowledgement.'
            );
        }
        $this->recordNativeSecurityState([
            'assigned' => $securityGeneration,
            'allocated' => \max(
                $securityGeneration,
                (int)($this->state['security_generation_high_water'] ?? 0),
            ),
            'committed' => $securityGeneration,
            'ledger_digest' => (string)$response[5],
            'anchor_digest' => $rootsDigest,
        ]);
    }

    /** @param array{kind:string,uid?:int,gid?:int,sid?:string} $owner */
    private function bindBrokerEmergencyCredential(
        string $transactionId,
        string $projectUuid,
        string $intentDigest,
        int $securityGeneration,
        array $owner,
        string $credentialId,
        int $credentialGeneration,
        string $credentialSecret,
    ): void {
        if (!$this->brokerActionsAvailable('admin')) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production enrollment requires Native emergency credential binding.',
                );
            }
            return;
        }
        $response = $this->brokerAction('admin', [
            'EMERGENCY_BIND',
            $projectUuid,
            $transactionId,
            $intentDigest,
            (string)$securityGeneration,
            $this->brokerOwnerIdentity($owner),
            $credentialId,
            (string)$credentialGeneration,
            $credentialSecret,
        ]);
        if (\count($response) !== 5
            || !\hash_equals($transactionId, (string)$response[0])
            || !\hash_equals($intentDigest, (string)$response[1])
            || (int)$response[2] !== $securityGeneration
            || (int)$response[3] !== $credentialGeneration
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[4]) !== 1
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid emergency credential binding receipt.',
            );
        }
    }

    private function abortBrokerCertificateRoots(
        string $transactionId,
        string $projectUuid,
        string $intentDigest,
    ): int {
        if (!$this->brokerActionsAvailable('admin')) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production enrollment requires native Broker AUTH_ABORT.'
                );
            }
            return 0;
        }
        $response = $this->brokerAction('admin', [
            'AUTH_ABORT',
            $projectUuid,
            $transactionId,
            $intentDigest,
        ]);
        if (\count($response) !== 5
            || !\hash_equals($transactionId, (string)$response[0])
            || !\hash_equals($intentDigest, (string)$response[1])
            || \preg_match('/\A[0-9]+\z/D', (string)$response[2]) !== 1
            || \preg_match('/\A[0-9]+\z/D', (string)$response[3]) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[4]) !== 1
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid AUTH_ABORT acknowledgement.'
            );
        }
        $committedHighWater = (int)(
            $this->state['security_committed_high_water'] ?? 0
        );
        $attestation = $this->brokerAction('admin', [
            'SECURITY_ATTEST',
            $this->hostId(),
            (string)$committedHighWater,
            '-',
            '-',
        ]);
        if (\count($attestation) !== 5
            || !\hash_equals($this->hostId(), (string)$attestation[0])
            || \preg_match('/\A[0-9]+\z/D', (string)$attestation[1]) !== 1
            || \preg_match('/\A[0-9]+\z/D', (string)$attestation[2]) !== 1
            || (int)$attestation[1] < (int)$response[3]
            || (int)$attestation[2] !== $committedHighWater
            || !\hash_equals((string)$response[4], (string)$attestation[3])
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$attestation[3]) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$attestation[4]) !== 1
        ) {
            throw new \RuntimeException(
                'Native Broker could not attest the security state after AUTH_ABORT.'
            );
        }
        $this->recordNativeSecurityState([
            'assigned' => (int)$response[2],
            'allocated' => (int)$attestation[1],
            'committed' => (int)$attestation[2],
            'ledger_digest' => (string)$attestation[3],
            'anchor_digest' => (string)$attestation[4],
        ]);
        return (int)$response[2];
    }

    private function assertSecurityAllocationSerialized(string $transactionId): void
    {
        foreach ((array)($this->state['enrollment_transactions'] ?? []) as $id => $transaction) {
            if (!\is_array($transaction)
                || \hash_equals($transactionId, (string)$id)
                || !\in_array(
                    (string)($transaction['phase'] ?? ''),
                    ['PREPARED', 'ABORT_PENDING', 'LEDGER_COMMITTED'],
                    true,
                )
            ) {
                continue;
            }
            throw new \DomainException(
                'Another enrollment owns the pending Native security generation.'
            );
        }
        foreach ((array)($this->state['rotation_transactions'] ?? []) as $id => $transaction) {
            if (!\is_array($transaction)
                || \hash_equals($transactionId, (string)$id)
                || !\in_array(
                    (string)($transaction['phase'] ?? ''),
                    ['PREPARED', 'NATIVE_PREPARED', 'LEDGER_COMMITTED'],
                    true,
                )
            ) {
                continue;
            }
            throw new \DomainException(
                'Another identity rotation owns the pending Native security generation.'
            );
        }
        foreach ((array)($this->state['security_transactions'] ?? []) as $id => $transaction) {
            if (!\is_array($transaction)
                || \hash_equals($transactionId, (string)$id)
                || !\in_array(
                    (string)($transaction['phase'] ?? ''),
                    ['PREPARED', 'RESERVED', 'COMMITTED'],
                    true,
                )
            ) {
                continue;
            }
            $sealed = $this->state['security_sealed_transactions'][$id] ?? null;
            if ((string)($transaction['phase'] ?? '') === 'COMMITTED'
                && \is_array($sealed)
                && (int)($sealed['assigned_generation'] ?? 0)
                    === (int)($transaction['assigned_generation'] ?? -1)
            ) {
                continue;
            }
            throw new \DomainException(
                'Another mutation owns the pending Native security generation.'
            );
        }
    }

    /**
     * @return array{assigned:int,allocated:int,committed:int,ledger_digest:string,anchor_digest:string}
     */
    private function reserveSecurityMutation(
        string $transactionId,
        string $intentDigest,
        string $kind,
    ): array {
        if (\preg_match('/\A[a-f0-9]{32}\z/D', $transactionId) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $intentDigest) !== 1
            || \preg_match('/\A[A-Z][A-Z0-9_]{1,63}\z/D', $kind) !== 1
        ) {
            throw new \DomainException('Security reservation binding is invalid.');
        }
        $this->assertSecurityAllocationSerialized($transactionId);
        $expectedPrevious = (int)(
            $this->state['security_committed_high_water'] ?? 0
        );
        $existing = $this->state['security_transactions'][$transactionId] ?? null;
        if (\is_array($existing)) {
            if (!\hash_equals(
                    $intentDigest,
                    (string)($existing['intent_digest'] ?? ''),
                )
                || !\hash_equals($kind, (string)($existing['kind'] ?? ''))
                || !\in_array(
                    (string)($existing['phase'] ?? ''),
                    ['PREPARED', 'RESERVED'],
                    true,
                )
            ) {
                throw new \DomainException(
                    'Security transaction ID is bound to another or terminal mutation.'
                );
            }
        } else {
            $this->state['security_transactions'][$transactionId] = [
                'schema_version' => 1,
                'transaction_id' => $transactionId,
                'intent_digest' => $intentDigest,
                'kind' => $kind,
                'assigned_generation' => 0,
                'phase' => 'PREPARED',
                'created_at' => \gmdate(DATE_ATOM),
                'updated_at' => \gmdate(DATE_ATOM),
            ];
            // The local transaction fence must precede Native H allocation.
            $this->persistSecurityLedger();
            $this->persistState();
            $existing = $this->state['security_transactions'][$transactionId];
        }
        $assignedExisting = (int)($existing['assigned_generation'] ?? 0);
        if (!$this->brokerActionsAvailable('admin')) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production security mutation requires native Broker SECURITY_RESERVE.'
                );
            }
            $assigned = $assignedExisting > 0
                ? $assignedExisting
                : $this->nextSecurityGeneration();
            $receipt = [
                'assigned' => $assigned,
                'allocated' => $assigned,
                'committed' => $expectedPrevious,
                'ledger_digest' => $this->fileHash($this->securityLedgerFile()),
                'anchor_digest' => $this->fileHash($this->securityAnchorFile()),
            ];
            $this->state['security_transactions'][$transactionId]['assigned_generation']
                = $assigned;
            $this->state['security_transactions'][$transactionId]['phase'] = 'RESERVED';
            $this->state['security_transactions'][$transactionId]['updated_at']
                = \gmdate(DATE_ATOM);
            $this->persistSecurityLedger();
            $this->persistState();
            return $receipt;
        }
        $response = $this->brokerAction('admin', [
            'SECURITY_RESERVE',
            $transactionId,
            $intentDigest,
            $kind,
            (string)$expectedPrevious,
        ]);
        $parsed = $this->parseSecurityMutationResponse(
            $response,
            $transactionId,
            $intentDigest,
        );
        if ($parsed['assigned'] <= $expectedPrevious
            || $parsed['allocated'] < $parsed['assigned']
            || $parsed['committed'] !== $expectedPrevious
            || ($assignedExisting > 0
                && $parsed['assigned'] !== $assignedExisting)
        ) {
            throw new \RuntimeException(
                'Native Broker SECURITY_RESERVE did not allocate a monotonic host generation.'
            );
        }
        $this->recordNativeSecurityState($parsed);
        $this->state['security_transactions'][$transactionId]['assigned_generation']
            = $parsed['assigned'];
        $this->state['security_transactions'][$transactionId]['phase'] = 'RESERVED';
        $this->state['security_transactions'][$transactionId]['updated_at']
            = \gmdate(DATE_ATOM);
        $this->persistSecurityLedger();
        $this->persistState();
        return $parsed;
    }

    /**
     * @return array{assigned:int,allocated:int,committed:int,ledger_digest:string,anchor_digest:string}
     */
    private function commitSecurityMutation(
        string $transactionId,
        string $intentDigest,
        string $kind,
        int $assignedGeneration,
    ): array {
        if (!$this->brokerActionsAvailable('admin')) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production security mutation requires native Broker SECURITY_COMMIT.'
                );
            }
            $this->state['security_committed_high_water'] = \max(
                (int)($this->state['security_committed_high_water'] ?? 0),
                $assignedGeneration,
            );
            $this->state['security_sealed_transactions'][$transactionId] = [
                'intent_digest' => $intentDigest,
                'kind' => $kind,
                'assigned_generation' => $assignedGeneration,
                'sealed_anchor_digest' => $this->fileHash($this->securityAnchorFile()),
                'sealed_at' => \gmdate(DATE_ATOM),
            ];
            return [
                'assigned' => $assignedGeneration,
                'allocated' => (int)$this->state['security_generation_high_water'],
                'committed' => (int)$this->state['security_committed_high_water'],
                'ledger_digest' => $this->fileHash($this->securityLedgerFile()),
                'anchor_digest' => $this->fileHash($this->securityAnchorFile()),
            ];
        }
        $anchorDigest = $this->fileHash($this->securityAnchorFile());
        $response = $this->brokerAction('admin', [
            'SECURITY_COMMIT',
            $transactionId,
            $intentDigest,
            $kind,
            (string)$assignedGeneration,
            $anchorDigest,
        ]);
        $parsed = $this->parseSecurityMutationResponse(
            $response,
            $transactionId,
            $intentDigest,
        );
        if ($parsed['assigned'] !== $assignedGeneration
            || $parsed['allocated'] < $assignedGeneration
            || $parsed['committed'] < $assignedGeneration
            || !\hash_equals($anchorDigest, $parsed['anchor_digest'])
        ) {
            throw new \RuntimeException(
                'Native Broker SECURITY_COMMIT did not seal the current security ledger.'
            );
        }
        $this->recordNativeSecurityState($parsed);
        $this->state['security_sealed_transactions'][$transactionId] = [
            'intent_digest' => $intentDigest,
            'kind' => $kind,
            'assigned_generation' => $assignedGeneration,
            'sealed_anchor_digest' => $parsed['anchor_digest'],
            'sealed_at' => \gmdate(DATE_ATOM),
        ];
        // Native digests are part of schema-5 security authority. Persist the
        // Broker after-image before returning so state.json loss cannot revive
        // the pre-commit Native anchor from an otherwise trusted ledger.
        $this->persistSecurityLedger();
        return $parsed;
    }

    /**
     * @return array{assigned:int,allocated:int,committed:int,ledger_digest:string,anchor_digest:string}
     */
    private function abortSecurityMutation(
        string $transactionId,
        string $intentDigest,
        string $kind,
        int $assignedGeneration,
    ): array {
        if ($assignedGeneration < 1) {
            throw new \RuntimeException(
                'Security abort requires the generation allocated by SECURITY_RESERVE.'
            );
        }
        if (!$this->brokerActionsAvailable('admin')) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production security mutation requires native Broker SECURITY_ABORT.'
                );
            }
            return [
                'assigned' => $assignedGeneration,
                'allocated' => (int)($this->state['security_generation_high_water'] ?? 0),
                'committed' => (int)($this->state['security_committed_high_water'] ?? 0),
                'ledger_digest' => $this->fileHash($this->securityLedgerFile()),
                'anchor_digest' => $this->fileHash($this->securityAnchorFile()),
            ];
        }
        $response = $this->brokerAction('admin', [
            'SECURITY_ABORT',
            $transactionId,
            $intentDigest,
            $kind,
            (string)$assignedGeneration,
        ]);
        $parsed = $this->parseSecurityMutationResponse(
            $response,
            $transactionId,
            $intentDigest,
        );
        if ($parsed['assigned'] !== $assignedGeneration
            || $parsed['allocated'] < $assignedGeneration
            || $parsed['committed'] !== (int)(
                $this->state['security_committed_high_water'] ?? 0
            )) {
            throw new \RuntimeException(
                'Native Broker SECURITY_ABORT changed committed security state.'
            );
        }
        $this->recordNativeSecurityState($parsed);
        return $parsed;
    }

    /**
     * @param list<string> $response
     * @return array{assigned:int,allocated:int,committed:int,ledger_digest:string,anchor_digest:string}
     */
    private function parseSecurityMutationResponse(
        array $response,
        string $transactionId,
        string $intentDigest,
    ): array {
        if (\count($response) !== 7
            || !\hash_equals($transactionId, (string)$response[0])
            || !\hash_equals($intentDigest, (string)$response[1])
            || \preg_match('/\A[0-9]+\z/D', (string)$response[2]) !== 1
            || \preg_match('/\A[0-9]+\z/D', (string)$response[3]) !== 1
            || \preg_match('/\A[0-9]+\z/D', (string)$response[4]) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[5]) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[6]) !== 1
        ) {
            throw new \RuntimeException(
                'Native Broker returned a malformed security mutation receipt.'
            );
        }
        return [
            'assigned' => (int)$response[2],
            'allocated' => (int)$response[3],
            'committed' => (int)$response[4],
            'ledger_digest' => (string)$response[5],
            'anchor_digest' => (string)$response[6],
        ];
    }

    /**
     * @param array{assigned:int,allocated:int,committed:int,ledger_digest:string,anchor_digest:string} $receipt
     */
    private function recordNativeSecurityState(array $receipt): void
    {
        if ($receipt['allocated'] < 0
            || $receipt['committed'] < 0
            || $receipt['committed'] > $receipt['allocated']
            || \preg_match('/\A[a-f0-9]{64}\z/D', $receipt['ledger_digest']) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $receipt['anchor_digest']) !== 1
            || \hash_equals(\str_repeat('0', 64), $receipt['ledger_digest'])
        ) {
            throw new \RuntimeException('Native Broker security state receipt is invalid.');
        }
        $this->state['security_generation_high_water'] = $receipt['allocated'];
        $this->state['security_committed_high_water'] = $receipt['committed'];
        $this->state['native_security_ledger_digest'] = $receipt['ledger_digest'];
        $this->state['native_security_anchor_digest'] = $receipt['anchor_digest'];
        $this->state['native_security_attested'] = true;
    }

    /**
     * @return array{assigned:int,allocated:int,committed:int,ledger_digest:string,anchor_digest:string}
     */
    private function attestNativeSecurityState(
        string $channel,
        int $minimumCommitted,
        string $expectedLedgerDigest = '-',
        string $expectedAnchorDigest = '-',
    ): array {
        if (!$this->brokerActionsAvailable($channel)
            || $minimumCommitted < 0
            || ($expectedLedgerDigest !== '-'
                && \preg_match('/\A[a-f0-9]{64}\z/D', $expectedLedgerDigest) !== 1)
            || ($expectedAnchorDigest !== '-'
                && \preg_match('/\A[a-f0-9]{64}\z/D', $expectedAnchorDigest) !== 1)
        ) {
            throw new \RuntimeException(
                'Native Broker security attestation request is malformed.'
            );
        }
        $response = $this->brokerAction($channel, [
            'SECURITY_ATTEST',
            $this->hostId(),
            (string)$minimumCommitted,
            $expectedLedgerDigest,
            $expectedAnchorDigest,
        ]);
        if (\count($response) !== 5
            || !\hash_equals($this->hostId(), (string)$response[0])
            || \preg_match('/\A[0-9]+\z/D', (string)$response[1]) !== 1
            || \preg_match('/\A[0-9]+\z/D', (string)$response[2]) !== 1
            || (int)$response[1] < (int)$response[2]
            || (int)$response[2] < $minimumCommitted
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[3]) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[4]) !== 1
            || \hash_equals(\str_repeat('0', 64), (string)$response[3])
            || ($expectedLedgerDigest !== '-'
                && !\hash_equals($expectedLedgerDigest, (string)$response[3]))
            || ($expectedAnchorDigest !== '-'
                && !\hash_equals($expectedAnchorDigest, (string)$response[4]))
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid security attestation receipt.'
            );
        }
        return [
            'assigned' => 0,
            'allocated' => (int)$response[1],
            'committed' => (int)$response[2],
            'ledger_digest' => (string)$response[3],
            'anchor_digest' => (string)$response[4],
        ];
    }

    private function replayCommittedSecurityTransactions(): void
    {
        if (!$this->brokerActionsAvailable('admin')) {
            return;
        }
        $count = 0;
        $replayed = false;
        foreach ((array)($this->state['security_transactions'] ?? []) as $transaction) {
            if (!\is_array($transaction)
                || !\hash_equals('COMMITTED', (string)($transaction['phase'] ?? ''))
            ) {
                continue;
            }
            if (++$count > 1024) {
                throw new \RuntimeException(
                    'Security transaction replay quota is exceeded.'
                );
            }
            $transactionId = (string)($transaction['transaction_id'] ?? '');
            $intentDigest = (string)($transaction['intent_digest'] ?? '');
            $kind = (string)($transaction['kind'] ?? '');
            $assigned = (int)($transaction['assigned_generation'] ?? 0);
            if (\preg_match('/\A[a-f0-9]{32}\z/D', $transactionId) !== 1
                || \preg_match('/\A[a-f0-9]{64}\z/D', $intentDigest) !== 1
                || \preg_match('/\A[A-Z][A-Z0-9_]{1,63}\z/D', $kind) !== 1
                || $assigned < 1
            ) {
                throw new \RuntimeException(
                    'Committed security transaction is malformed.'
                );
            }
            $sealed = $this->state['security_sealed_transactions'][$transactionId] ?? null;
            if (\is_array($sealed)
                && \hash_equals($intentDigest, (string)($sealed['intent_digest'] ?? ''))
                && \hash_equals($kind, (string)($sealed['kind'] ?? ''))
                && $assigned === (int)($sealed['assigned_generation'] ?? 0)
                && \preg_match(
                    '/\A[a-f0-9]{64}\z/D',
                    (string)($sealed['sealed_anchor_digest'] ?? ''),
                ) === 1
            ) {
                continue;
            }
            $this->commitSecurityMutation(
                $transactionId,
                $intentDigest,
                $kind,
                $assigned,
            );
            $replayed = true;
        }
        if ($replayed) {
            $this->persistState();
        }
    }

    private function replayEnrollmentCommits(): void
    {
        if (!$this->brokerActionsAvailable('admin')) {
            return;
        }
        $changed = false;
        foreach ((array)($this->state['enrollment_transactions'] ?? []) as $transactionId => $transaction) {
            if (!\is_array($transaction)) {
                continue;
            }
            $phase = (string)($transaction['phase'] ?? '');
            if (!\in_array(
                $phase,
                ['ABORT_PENDING', 'LEDGER_COMMITTED', 'BROKER_COMMITTED'],
                true,
            )) {
                continue;
            }
            $projectUuid = (string)($transaction['project_uuid'] ?? '');
            $intentDigest = (string)(
                $transaction['authenticated_desired_digest'] ?? ''
            );
            $peerDigest = (string)($transaction['authenticated_peer_digest'] ?? '');
            $reconstructedDesiredDigest = \hash('sha256', $this->canonicalJson([
                'project_uuid' => $projectUuid,
                'project_root' => (string)($transaction['project_root'] ?? ''),
                'certificate_roots' => (array)(
                    $transaction['certificate_roots'] ?? []
                ),
                'allowed_domains' => (array)($transaction['allowed_domains'] ?? []),
                'owner' => (array)($transaction['owner'] ?? []),
                'capabilities' => (array)($transaction['capabilities'] ?? []),
            ]));
            $reconstructedPeerDigest = \hash(
                'sha256',
                $this->canonicalJson((array)($transaction['owner'] ?? [])),
            );
            $securityGeneration = (int)($transaction['security_generation'] ?? 0);
            if (\preg_match('/\A[a-f0-9]{32}\z/D', (string)$transactionId) !== 1
                || !$this->validProjectUuid($projectUuid)
                || \preg_match('/\A[a-f0-9]{64}\z/D', $intentDigest) !== 1
                || \preg_match('/\A[a-f0-9]{64}\z/D', $peerDigest) !== 1
                || !\hash_equals($reconstructedDesiredDigest, $intentDigest)
                || !\hash_equals($reconstructedPeerDigest, $peerDigest)
                || ($phase !== 'ABORT_PENDING' && $securityGeneration < 1)
            ) {
                throw new \RuntimeException(
                    'Interrupted enrollment transaction is malformed.'
                );
            }
            if ($phase === 'ABORT_PENDING') {
                $abortedGeneration = $this->abortBrokerCertificateRoots(
                    (string)$transactionId,
                    $projectUuid,
                    $intentDigest,
                );
                if ($abortedGeneration > 0) {
                    $this->state['enrollment_transactions'][$transactionId]
                        ['security_generation'] = $abortedGeneration;
                }
                $this->state['enrollment_transactions'][$transactionId]['phase']
                    = 'ABORTED';
                $this->state['enrollment_transactions'][$transactionId]['updated_at']
                    = \gmdate(DATE_ATOM);
                $changed = true;
                continue;
            }
            if ($phase === 'LEDGER_COMMITTED') {
                $this->commitBrokerCertificateRoots(
                    (string)$transactionId,
                    $projectUuid,
                    $intentDigest,
                    $securityGeneration,
                    (array)($transaction['root_attestations'] ?? []),
                );
            }
            $committedAt = \gmdate(DATE_ATOM);
            $this->state['enrollment_transactions'][$transactionId]['phase'] = 'COMMITTED';
            $this->state['enrollment_transactions'][$transactionId]['committed_at']
                = $committedAt;
            $this->state['enrollment_transactions'][$transactionId]['updated_at']
                = $committedAt;
            $this->state['security_committed_high_water'] = \max(
                (int)($this->state['security_committed_high_water'] ?? 0),
                $securityGeneration,
            );
            $changed = true;
        }
        if ($changed) {
            $this->persistSecurityLedger();
            $this->persistState();
        }
    }

    /**
     * @param array{root_alias?:mixed,relative_path?:mixed} $reference
     */
    private function brokerSnapshotCertificateSource(
        string $projectUuid,
        int $securityGeneration,
        array $reference,
        string $snapshotDigest,
        string $leaf,
    ): string {
        if (!$this->brokerActionsAvailable('project')) {
            throw new \RuntimeException(
                'Production certificate snapshot requires the native Broker action protocol.'
            );
        }
        $alias = \strtolower(\trim((string)($reference['root_alias'] ?? '')));
        $relative = \trim((string)($reference['relative_path'] ?? ''));
        if (\preg_match('/\A[a-z][a-z0-9_]{0,31}\z/D', $alias) !== 1
            || $relative === ''
        ) {
            throw new \DomainException('Certificate source reference is invalid.');
        }
        $enrollment = $this->state['enrollments'][$projectUuid] ?? null;
        if (!\is_array($enrollment)
            || $securityGeneration !== (int)($enrollment['security_generation'] ?? 0)
        ) {
            throw new \DomainException(
                'Certificate snapshot authorization generation is unavailable.'
            );
        }
        $transactionId = (string)(
            $enrollment['native_authorization_transaction_id'] ?? ''
        );
        $intentDigest = (string)(
            $enrollment['native_authorization_intent_digest'] ?? ''
        );
        if (\preg_match('/\A[a-f0-9]{32}\z/D', $transactionId) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $intentDigest) !== 1
        ) {
            throw new \DomainException(
                'Certificate snapshot enrollment attestation is unavailable.'
            );
        }
        $response = $this->brokerAction('project', [
            'SNAP',
            $projectUuid,
            $transactionId,
            $intentDigest,
            $alias,
            \bin2hex($relative),
            $snapshotDigest,
            $leaf,
        ]);
        if (\count($response) !== 5
            || !\hash_equals($transactionId, (string)$response[0])
            || !\hash_equals($intentDigest, (string)$response[1])
            || !\hash_equals($alias, (string)$response[2])
            || !\hash_equals($snapshotDigest, (string)$response[3])
            || !\hash_equals($leaf, (string)$response[4])
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid SNAP acknowledgement.'
            );
        }
        $path = $this->home . DIRECTORY_SEPARATOR . 'snapshots'
            . DIRECTORY_SEPARATOR . $snapshotDigest . DIRECTORY_SEPARATOR . $leaf;
        if (!\is_file($path) || \is_link($path)) {
            throw new \RuntimeException('Native Broker did not publish the certificate source snapshot.');
        }
        return $path;
    }

    /**
     * @return array<string,mixed>
     */
    private function doctor(): array
    {
        $status = $this->status();
        $status['paths'] = [
            'home' => $this->home,
            'state' => $this->stateFile(),
            'config' => $this->configFile(),
            'journal' => $this->journalFile(),
        ];
        $status['binary'] = [
            'path' => $this->nginxBinary(),
            'sha256' => $this->fileHash($this->nginxBinary()),
            'expected_sha256' => (string)($this->slotManifest()['binary_sha256'] ?? ''),
        ];
        $status['lkg'] = (array)($this->state['lkg'] ?? []);
        $status['failures'] = (array)($this->state['failure_events'] ?? []);
        return $status;
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function register(array $payload, bool $renew): array
    {
        $registrationDeadline = $this->monotonicNow() + self::REGISTRATION_BUDGET_SECONDS;
        $this->assertPayloadBudget($payload, self::MAX_REQUEST_BYTES, 'Registration');
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        $projectRootInput = \trim((string)($payload['project_root'] ?? ''));
        if ($projectRootInput === '' || \strlen($projectRootInput) > 4096) {
            throw new \DomainException('Registration project root is missing or too long.');
        }
        $projectRoot = $this->canonicalDirectory($projectRootInput);
        $instanceId = \trim((string)($payload['instance_id'] ?? ''));
        $generation = (int)($payload['project_generation'] ?? 0);
        $digest = \strtolower(\trim((string)($payload['request_digest'] ?? '')));
        $idempotencyKey = \strtolower(\trim((string)($payload['idempotency_key'] ?? '')));
        $instanceGeneration = (int)($payload['instance_generation'] ?? 0);
        $instanceDigest = \strtolower(\trim((string)($payload['instance_digest'] ?? '')));
        $nonCertificateDesiredDigest = \strtolower(\trim((string)(
            $payload['non_certificate_desired_digest'] ?? ''
        )));
        $masterEpoch = (int)($payload['master_epoch'] ?? 0);
        $launchId = \strtolower(\trim((string)($payload['launch_id'] ?? '')));
        $gatewayEpoch = \trim((string)($payload['gateway_epoch'] ?? ''));
        if (!$this->validProjectUuid($projectUuid)
            || $instanceId === ''
            || \strlen($instanceId) > self::MAX_INSTANCE_ID_BYTES
            || \preg_match('/\A[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}\z/D', $instanceId) !== 1
            || $generation < 1
            || !\preg_match('/\A[a-f0-9]{64}\z/D', $digest)
            || \preg_match('/\A[a-f0-9]{40}\z/D', $idempotencyKey) !== 1
            || $instanceGeneration < 1
            || !\preg_match('/\A[a-f0-9]{64}\z/D', $instanceDigest)
            || !\preg_match('/\A[a-f0-9]{64}\z/D', $nonCertificateDesiredDigest)
            || $masterEpoch < 1
            || !\preg_match('/\A[a-f0-9]{32}\z/D', $launchId)
        ) {
            throw new \DomainException('Registration identity or fencing fields are incomplete.');
        }
        $expectedIdempotencyKey = \substr(\hash(
            'sha256',
            $projectUuid . ':desired:' . $generation . ':' . $digest,
        ), 0, 40);
        if (!\hash_equals($expectedIdempotencyKey, $idempotencyKey)) {
            throw new \DomainException(
                'Registration idempotency key is not bound to project generation and request digest.'
            );
        }
        if (($renew && $gatewayEpoch === '')
            || ($gatewayEpoch !== ''
                && !\hash_equals((string)$this->state['epoch'], $gatewayEpoch))
        ) {
            throw new \DomainException('Gateway epoch changed; submit a full registration against epoch '
                . (string)$this->state['epoch'] . '.');
        }
        $this->assertCurrentHostBootPayload($payload, $renew ? 'Renew' : 'Register');
        $peer = \is_array($payload['_broker_peer'] ?? null) ? $payload['_broker_peer'] : [];
        $this->assertEnrollment($projectUuid, $projectRoot, $peer);
        $retirementFloor = $this->assertInstanceRetirementFence(
            $projectUuid,
            $instanceId,
            $instanceGeneration,
        );

        $projects = (array)($this->state['projects'] ?? []);
        $existing = \is_array($projects[$projectUuid] ?? null) ? $projects[$projectUuid] : [];
        $existingGeneration = (int)($existing['generation'] ?? 0);
        $existingDigest = (string)($existing['digest'] ?? '');
        if ($generation < $existingGeneration) {
            throw new \DomainException('Stale project generation rejected.');
        }
        if ($generation === $existingGeneration
            && $existingDigest !== ''
            && !\hash_equals($existingDigest, $digest)
        ) {
            throw new \DomainException('Same project generation has a different request digest.');
        }
        if ($generation === $existingGeneration
            && (string)($existing['idempotency_key'] ?? '') !== ''
            && !\hash_equals(
                (string)$existing['idempotency_key'],
                $idempotencyKey,
            )
        ) {
            throw new \DomainException(
                'Same project generation has a different idempotency key.'
            );
        }
        $projectChanged = $generation > $existingGeneration;

        if ($existing === []
            && \count((array)($this->state['projects'] ?? [])) >= self::MAX_PROJECTS
        ) {
            throw new \DomainException('Gateway project quota would be exceeded.');
        }

        $instances = (array)($this->state['instances'][$projectUuid] ?? []);
        $existingInstance = \is_array($instances[$instanceId] ?? null)
            ? $instances[$instanceId]
            : [];
        $existingInstanceGeneration = (int)($existingInstance['generation'] ?? 0);
        $existingInstanceDigest = (string)($existingInstance['digest'] ?? '');
        if ($existingInstance === []) {
            if (\count($instances) >= self::MAX_INSTANCES_PER_PROJECT) {
                throw new \DomainException('Project instance quota would be exceeded.');
            }
            $totalInstances = 0;
            foreach ((array)($this->state['instances'] ?? []) as $projectInstances) {
                $totalInstances += \count((array)$projectInstances);
            }
            if ($totalInstances >= self::MAX_TOTAL_INSTANCES) {
                throw new \DomainException('Gateway instance quota would be exceeded.');
            }
        }
        if ($instanceGeneration < $existingInstanceGeneration) {
            throw new \DomainException('Stale instance generation rejected.');
        }
        if ($instanceGeneration === $existingInstanceGeneration
            && (string)($existingInstance['status'] ?? '') === 'DRAINING'
            && (int)($existingInstance['master_epoch'] ?? 0) === $masterEpoch
            && \hash_equals(
                (string)($existingInstance['launch_id'] ?? ''),
                $launchId,
            )
        ) {
            throw new WlsEdgeProtocolException(
                'instance_draining',
                'This launch is irreversibly draining and cannot be reactivated; '
                    . 'start a strictly newer instance_generation.',
            );
        }
        $sameGenerationInstanceDigestChanged = $instanceGeneration === $existingInstanceGeneration
            && $existingInstanceDigest !== ''
            && !\hash_equals($existingInstanceDigest, $instanceDigest);
        if ($sameGenerationInstanceDigestChanged
            && !$this->mayRefreshInstanceDigest(
                $existingInstance,
                $masterEpoch,
                $launchId,
            )
        ) {
            throw new \DomainException('Same instance generation has a different instance digest.');
        }
        $sameDesiredRegistration = $instanceGeneration === $existingInstanceGeneration
            && $existingInstanceDigest !== ''
            && \hash_equals($existingInstanceDigest, $instanceDigest)
            && $generation === $existingGeneration
            && $existingDigest !== ''
            && \hash_equals($existingDigest, $digest);
        $storedNonCertificateDesiredMatches = \preg_match(
            '/\A[a-f0-9]{64}\z/D',
            (string)($existing['non_certificate_desired_digest'] ?? ''),
        ) === 1 && \hash_equals(
            (string)$existing['non_certificate_desired_digest'],
            $nonCertificateDesiredDigest,
        );
        $routePayloads = \is_array($payload['routes'] ?? null) ? $payload['routes'] : [];
        if ($routePayloads === [] || \count($routePayloads) > self::MAX_ROUTES_PER_PROJECT) {
            throw new \DomainException('Registration must contain 1..256 routes.');
        }

        $preflightRouteIds = [];
        $preflightDomains = [];
        $preflightRoutes = [];
        foreach ($routePayloads as $routePayload) {
            if (!\is_array($routePayload)) {
                throw new \DomainException('Route payload must be an object.');
            }
            if (!\is_bool($routePayload['force_https'] ?? null)
                || !\is_bool($routePayload['force_root_to_www'] ?? null)
            ) {
                throw new \DomainException(
                    'Route edge policies must be explicit booleans.'
                );
            }
            $domain = $this->normalizeDomain((string)($routePayload['domain'] ?? ''));
            $routeId = \strtolower(\trim((string)($routePayload['route_id'] ?? '')));
            if (!\hash_equals($this->canonicalRouteId($projectUuid, $domain), $routeId)) {
                throw new \DomainException(
                    'Route ID must be the canonical project/domain digest.'
                );
            }
            if (isset($preflightRouteIds[$routeId]) || isset($preflightDomains[$domain])) {
                throw new \DomainException('Registration contains a duplicate route.');
            }
            $preflightRouteIds[$routeId] = true;
            $preflightDomains[$domain] = true;
            $preflightRoutes[] = [
                'route_id' => $routeId,
                'domain' => $domain,
                'force_root_to_www' => $routePayload['force_root_to_www'],
            ];
        }
        // REMOVED route bodies remain part of the 24-hour ownership/recovery
        // surface and must consume the host quota. Counting only live routes
        // (or only other projects) lets one tenant rotate 256 domains per
        // generation until state and probe memory are exhausted.
        $this->assertRetainedRouteCapacity(\array_keys($preflightRouteIds));
        foreach ($preflightRoutes as $preflightRoute) {
            if (($preflightRoute['force_root_to_www'] ?? false) !== true) {
                continue;
            }
            $sourceDomain = (string)$preflightRoute['domain'];
            if (\str_starts_with($sourceDomain, '*.')
                || \str_starts_with($sourceDomain, 'www.')
            ) {
                throw new \DomainException(
                    'force_root_to_www is valid only on an exact non-www route.'
                );
            }
            $wwwDomain = $this->normalizeDomain('www.' . $sourceDomain);
            if (!isset($preflightDomains[$wwwDomain])) {
                throw new \DomainException(
                    'force_root_to_www requires the exact www target route in the same project registration.'
                );
            }
        }
        // Domain capability and ownership are cheap, authoritative checks.
        // Complete them before any project-controlled listener is contacted.
        $this->assertDomainsAuthorized($projectUuid, $preflightRoutes);
        $this->assertNoDomainConflicts($projectUuid, $preflightRoutes);
        if (!$projectChanged && $existingGeneration > 0) {
            $expectedRouteIds = \array_values(\array_unique(\array_map(
                'strval',
                (array)($existing['route_ids'] ?? []),
            )));
            $submittedRouteIds = \array_keys($preflightRouteIds);
            \sort($expectedRouteIds, SORT_STRING);
            \sort($submittedRouteIds, SORT_STRING);
            if ($expectedRouteIds !== $submittedRouteIds) {
                throw new \DomainException(
                    'Unchanged project generation attempted to change its route set.'
                );
            }
        }
        $expectedRenewGenerations = [];
        if ($renew) {
            $expected = \is_array($payload['expected_route_generations'] ?? null)
                ? $payload['expected_route_generations']
                : [];
            $expectedIds = \array_keys($expected);
            $submittedIds = \array_keys($preflightRouteIds);
            \sort($expectedIds, SORT_STRING);
            \sort($submittedIds, SORT_STRING);
            if ($expectedIds !== $submittedIds) {
                throw new \DomainException(
                    'Certificate renew generation map must exactly cover submitted routes.'
                );
            }
            foreach ($expected as $routeId => $expectedGeneration) {
                $current = $this->state['routes'][(string)$routeId] ?? null;
                if (!\is_int($expectedGeneration)
                    || !\is_array($current)
                    || !\hash_equals($projectUuid, (string)($current['project_uuid'] ?? ''))
                    || $expectedGeneration < 1
                ) {
                    throw new \DomainException('Certificate renew route generation fence was rejected.');
                }
                $expectedRenewGenerations[(string)$routeId] = $expectedGeneration;
            }
        } elseif (\array_key_exists('expected_route_generations', $payload)) {
            throw new \DomainException(
                'Route generation fences are accepted only by renew.'
            );
        }

        $candidateRoutes = [];
        $candidateRouteIds = [];
        $candidateDomains = [];
        foreach ($routePayloads as $routePayload) {
            if (!\is_array($routePayload)) {
                throw new \DomainException('Route payload must be an object.');
            }
            $candidate = $this->validateRoute(
                $routePayload,
                $projectUuid,
                $projectRoot,
                $instanceId,
                $instanceGeneration,
                $masterEpoch,
                $launchId,
                $registrationDeadline,
                true,
                true,
            );
            $candidateRouteId = (string)$candidate['route_id'];
            if (isset($candidateRouteIds[$candidateRouteId])) {
                throw new \DomainException(
                    'Registration contains a duplicate route ID: ' . $candidateRouteId
                );
            }
            $candidateDomain = (string)$candidate['domain'];
            if (isset($candidateDomains[$candidateDomain])) {
                throw new \DomainException(
                    'Registration contains a duplicate route domain: ' . $candidateDomain
                );
            }
            $candidateRouteIds[$candidateRouteId] = true;
            $candidateDomains[$candidateDomain] = true;
            $candidateRoutes[] = $candidate;
        }
        $calculatedNonCertificateDesiredDigest = $this->nonCertificateDesiredDigest(
            $projectUuid,
            $projectRoot,
            $candidateRoutes,
        );
        if (!\hash_equals(
            $calculatedNonCertificateDesiredDigest,
            $nonCertificateDesiredDigest,
        )) {
            throw new \DomainException(
                'Registration non-certificate desired digest does not match its route facts.'
            );
        }
        $calculatedProjectDesiredDigest = $this->projectDesiredDigest(
            $projectUuid,
            $projectRoot,
            $candidateRoutes,
        );
        if (!\hash_equals($calculatedProjectDesiredDigest, $digest)) {
            throw new \DomainException(
                'Registration request digest does not match its complete desired-state facts.'
            );
        }
        $calculatedInstanceDigest = $this->instanceDesiredDigest(
            $projectUuid,
            $instanceId,
            $instanceGeneration,
            $candidateRoutes,
        );
        if (!\hash_equals($calculatedInstanceDigest, $instanceDigest)) {
            throw new \DomainException(
                'Registration instance digest does not match its backend identity facts.'
            );
        }
        $requestedSecurityRevocations = $this->registrationSecurityRevocations(
            $projectUuid,
            $candidateRoutes,
        );
        $securityRetirementRefreshRequired = $requestedSecurityRevocations !== []
            && \count($this->securityRetirementResult($requestedSecurityRevocations))
                !== \count($requestedSecurityRevocations);
        if (!$renew
            && $sameDesiredRegistration
            && $storedNonCertificateDesiredMatches
        ) {
            $pendingOperation = $this->pendingPublicationOperationForProject(
                $projectUuid,
                $instanceId,
            );
            if ($pendingOperation !== []) {
                $this->lastQueuedOperationId = (string)$pendingOperation['operation_id'];
                return [
                    'idempotent' => true,
                    'epoch' => (string)$this->state['epoch'],
                    'generation' => (int)$this->state['generation'],
                    'routes' => $this->projectRoutes($projectUuid),
                    'security_retirements' => $this->securityRetirementResult(
                        $this->registrationSecurityRevocations(
                            $projectUuid,
                            $candidateRoutes,
                        ),
                    ),
                ];
            }
            if (!$securityRetirementRefreshRequired
                && $this->registrationLeaseFullyActive($projectUuid, $instanceId)
            ) {
                $this->touchInstanceLease(
                    $projectUuid,
                    $instanceId,
                    $masterEpoch,
                    $launchId,
                    $instanceGeneration,
                );
                return [
                    'idempotent' => true,
                    'epoch' => (string)$this->state['epoch'],
                    'generation' => (int)$this->state['generation'],
                    'routes' => $this->projectRoutes($projectUuid),
                    'lease_receipt' => $this->registrationLeaseReceipt(
                        $projectUuid,
                        $instanceId,
                    ),
                    'security_retirements' => $this->securityRetirementResult(
                        $this->registrationSecurityRevocations(
                            $projectUuid,
                            $candidateRoutes,
                        ),
                    ),
                ];
            }
        }
        if ($renew) {
            $renewIdempotent = $this->assertCertificateOnlyRenewal(
                $projectUuid,
                $projectRoot,
                $instanceId,
                $instanceGeneration,
                $instanceDigest,
                $masterEpoch,
                $launchId,
                $nonCertificateDesiredDigest,
                $candidateRoutes,
                $expectedRenewGenerations,
                $sameDesiredRegistration,
            );
            if ($renewIdempotent) {
                $pendingOperation = $this->pendingPublicationOperationForProject(
                    $projectUuid,
                    $instanceId,
                );
                if ($pendingOperation !== []) {
                    $this->lastQueuedOperationId = (string)$pendingOperation['operation_id'];
                    return [
                        'idempotent' => true,
                        'epoch' => (string)$this->state['epoch'],
                        'generation' => (int)$this->state['generation'],
                        'routes' => $this->projectRoutes($projectUuid),
                        'security_retirements' => $this->securityRetirementResult(
                            $this->registrationSecurityRevocations(
                                $projectUuid,
                                $candidateRoutes,
                            ),
                        ),
                    ];
                }
                if (!$securityRetirementRefreshRequired
                    && $this->registrationLeaseFullyActive($projectUuid, $instanceId)
                ) {
                    $this->touchInstanceLease(
                        $projectUuid,
                        $instanceId,
                        $masterEpoch,
                        $launchId,
                        $instanceGeneration,
                    );
                    return [
                        'idempotent' => true,
                        'epoch' => (string)$this->state['epoch'],
                        'generation' => (int)$this->state['generation'],
                        'routes' => $this->projectRoutes($projectUuid),
                        'lease_receipt' => $this->registrationLeaseReceipt(
                            $projectUuid,
                            $instanceId,
                        ),
                        'security_retirements' => $this->securityRetirementResult(
                            $this->registrationSecurityRevocations(
                                $projectUuid,
                                $candidateRoutes,
                            ),
                        ),
                    ];
                }
            }
        }
        if ($sameGenerationInstanceDigestChanged && !$projectChanged) {
            $this->assertCapabilityOnlyInstanceRefresh(
                $projectUuid,
                $instanceId,
                $existingInstance,
                $candidateRoutes,
            );
        }
        // Structural, generation, capability and conflict checks are now
        // complete. Probe each unique instance/list once, and require every
        // tuple in that list to attest before it becomes routable.
        /** @var array<string,array{result:string,failure_kind:?string}> $backendProbeCache */
        $backendProbeCache = [];
        foreach ($candidateRoutes as $candidateIndex => $candidate) {
            $probeKey = $this->backendProbeCacheKey(
                (array)$candidate['backends'],
                (array)$candidate['backend_identity'],
            );
            if (!isset($backendProbeCache[$probeKey])) {
                $failureKind = null;
                $probeResult = $this->probeBackends(
                    (array)$candidate['backends'],
                    (array)$candidate['backend_identity'],
                    false,
                    $failureKind,
                    $registrationDeadline,
                );
                $backendProbeCache[$probeKey] = [
                    'result' => $probeResult,
                    'failure_kind' => $failureKind,
                ];
            }
            $backendProbe = (string)$backendProbeCache[$probeKey]['result'];
            $failureKind = $backendProbeCache[$probeKey]['failure_kind'];
            if ($backendProbe === 'DEFERRED') {
                throw new \DomainException(
                    'Registration backend validation exceeded its deadline.'
                );
            }
            if ($backendProbe !== 'HEALTHY'
                && !\hash_equals('transport', (string)$failureKind)
            ) {
                // A transport outage is a retryable availability state. An
                // HMAC, lease, launch, tuple, generation or framing mismatch
                // is an authentication failure and must never be persisted as
                // a merely pending route.
                throw new \DomainException(
                    'Registration backend identity attestation was rejected.'
                );
            }
            $candidateRoutes[$candidateIndex]['status'] = $backendProbe === 'HEALTHY'
                ? 'ACTIVE'
                : 'PENDING_BACKEND';
        }

        // Certificate bundles become globally visible under their content
        // digest while this batch is assembled. Track only bundles created by
        // this request so any later route failure can remove its unreferenced
        // prefix without touching a reused/active/LKG snapshot.
        $this->beginCertificateSnapshotBatch();
        $routingMutationStarted = false;
        try {
            foreach ($candidateRoutes as $candidateIndex => $candidate) {
                $this->assertDeadlineAvailable(
                    $registrationDeadline,
                    'Certificate snapshot',
                );
                $certificate = $this->snapshotCertificate(
                    $projectUuid,
                    $projectRoot,
                    (string)$candidate['domain'],
                    (array)$candidate['certificate'],
                );
                $candidateRoutes[$candidateIndex]['certificate'] = $certificate;
                if (!$certificate['valid']) {
                    $candidateRoutes[$candidateIndex]['status'] = 'PENDING_CERTIFICATE';
                }
            }
            $securityRevocations = $this->registrationSecurityRevocations(
                $projectUuid,
                $candidateRoutes,
            );
            $this->beginRoutingMutation('register:' . $projectUuid . ':' . $instanceId);
            $routingMutationStarted = true;
            if ($securityRetirementRefreshRequired) {
                $this->markPublicationIrrevocableSecurity();
            }
            $this->recordPublicationLeaseCandidate(
                $projectUuid,
                $instanceId,
                $instanceGeneration,
                $instanceDigest,
                $masterEpoch,
                $launchId,
            );
            $incomingRouteIds = [];
            foreach ($candidateRoutes as $route) {
                $incomingRouteIds[(string)$route['route_id']] = true;
            }
            if ($projectChanged) {
                foreach ((array)($this->state['routes'] ?? []) as $routeId => $route) {
                    if (\is_array($route)
                        && (string)($route['project_uuid'] ?? '') === $projectUuid
                        && !isset($incomingRouteIds[(string)$routeId])
                    ) {
                        $this->enforceRemovedRoute(
                            $this->state['routes'][$routeId],
                            \time(),
                        );
                    }
                }
            }
            $routingChanged = false;
            foreach ($candidateRoutes as $candidate) {
                $routeId = (string)$candidate['route_id'];
                $old = \is_array($this->state['routes'][$routeId] ?? null)
                    ? $this->state['routes'][$routeId]
                    : [];
                if ($old !== []
                    && !\hash_equals($projectUuid, (string)($old['project_uuid'] ?? ''))
                ) {
                    throw new \DomainException('Route ID is already owned by another project.');
                }
                if ($old !== []
                    && !$projectChanged
                    && (!\hash_equals((string)$old['domain'], (string)$candidate['domain'])
                        || (bool)($old['force_https'] ?? true)
                            !== (bool)($candidate['force_https'] ?? true)
                        || (bool)($old['force_root_to_www'] ?? false)
                            !== (bool)($candidate['force_root_to_www'] ?? false)
                        || (!$renew
                            && (!\hash_equals(
                                (string)($old['certificate']['source_digest'] ?? ''),
                                (string)($candidate['certificate']['source_digest'] ?? ''),
                            )
                            || (int)($old['certificate']['generation'] ?? -1)
                                !== (int)($candidate['certificate']['generation'] ?? -2))))
                ) {
                    throw new \DomainException(
                        'Unchanged project generation attempted to modify route desired state.'
                    );
                }
                if ($old === [] && !$projectChanged && $existingGeneration > 0) {
                    throw new \DomainException(
                        'Unchanged project generation attempted to add a route.'
                    );
                }
                if ($old !== []) {
                    $oldCertificateGeneration = (int)($old['certificate']['generation'] ?? 0);
                    $candidateCertificateGeneration = (int)(
                        $candidate['certificate']['generation'] ?? 0
                    );
                    $oldSourceDigest = (string)(
                        $old['certificate']['source_digest'] ?? ''
                    );
                    $candidateSourceDigest = (string)(
                        $candidate['certificate']['source_digest'] ?? ''
                    );
                    if ($candidateCertificateGeneration < $oldCertificateGeneration) {
                        throw new \DomainException(
                            'Stale certificate generation rejected for route ' . $routeId . '.'
                        );
                    }
                    if ($candidateCertificateGeneration === $oldCertificateGeneration
                        && !\hash_equals($oldSourceDigest, $candidateSourceDigest)
                    ) {
                        throw new \DomainException(
                            'Same certificate generation has a different source digest.'
                        );
                    }
                }
                if ($old !== []
                    && \hash_equals(
                        (string)($old['certificate']['source_digest'] ?? ''),
                        (string)($candidate['certificate']['source_digest'] ?? ''),
                    )
                    && (int)($old['certificate']['generation'] ?? 0)
                        === (int)($candidate['certificate']['generation'] ?? 0)
                ) {
                    $candidateCertificate = (array)$candidate['certificate'];
                    $candidate['certificate'] = \array_replace(
                        (array)$old['certificate'],
                        [
                            'state' => (string)($candidateCertificate['state'] ?? ''),
                            'pending' => (bool)($candidateCertificate['pending'] ?? false),
                        ],
                    );
                }
                $routeInstances = \is_array($old['instances'] ?? null) ? $old['instances'] : [];
                $routeInstances[$instanceId] = [
                    'instance_id' => $instanceId,
                    'generation' => $instanceGeneration,
                    'digest' => $instanceDigest,
                    'master_epoch' => $masterEpoch,
                    'launch_id' => $launchId,
                    'retirement_floor_generation' => (int)(
                        $retirementFloor['instance_generation'] ?? 0
                    ),
                    'retirement_floor_digest' => (string)(
                        $retirementFloor['retirement_digest'] ?? ''
                    ),
                    'backends' => $candidate['backends'],
                    'backend_identity' => $candidate['backend_identity'],
                    'backend_healthy' => (string)$candidate['status'] !== 'PENDING_BACKEND',
                    'status' => 'ACTIVE',
                    'last_heartbeat' => \time(),
                    'last_heartbeat_monotonic' => $this->monotonicNow(),
                    'lease_boot_id' => $this->hostBootId,
                    'drain_until' => null,
                    'drain_until_monotonic' => null,
                ];
                $candidate['instances'] = $routeInstances;
                $candidate['route_generation'] = \max(
                    (int)($candidate['route_generation'] ?? 1),
                    (int)($old['route_generation'] ?? 0) + 1,
                );
                $this->selectRouteBackends($candidate);
                $routingChanged = $routingChanged
                    || $this->routeRoutingDigest($old) !== $this->routeRoutingDigest($candidate);
                $this->state['routes'][$routeId] = $candidate;
            }
            foreach (\array_keys($incomingRouteIds) as $routeId) {
                $registeredRoute = $this->state['routes'][$routeId] ?? null;
                if (\is_array($registeredRoute)) {
                    $this->retainRouteSecurityClosure($registeredRoute);
                }
            }
            // Domain ownership and certificate floors are durable security
            // facts, not publication state. Seal them before routing publish
            // and preserve them if the candidate config later rolls back.
            $this->retainSecurityClosureAcrossRoutingRollback();
            $this->persistSecurityLedger();
            $this->persistState();
            $projects[$projectUuid] = [
                'project_uuid' => $projectUuid,
                'project_root' => $projectRoot,
                'generation' => $generation,
                'digest' => $digest,
                'non_certificate_desired_digest' => $nonCertificateDesiredDigest,
                'idempotency_key' => $idempotencyKey,
                'route_ids' => \array_keys($incomingRouteIds),
                'registered_at' => \gmdate(DATE_ATOM),
            ];
            $this->state['projects'] = $projects;
            $instanceBackends = [];
            $instanceIdentity = [];
            foreach (\array_keys($incomingRouteIds) as $routeId) {
                $registeredRoute = $this->state['routes'][$routeId] ?? null;
                if (!\is_array($registeredRoute)) {
                    continue;
                }
                $instanceIdentity = $instanceIdentity !== []
                    ? $instanceIdentity
                    : (array)($registeredRoute['backend_identity'] ?? []);
                foreach ((array)($registeredRoute['instances'][$instanceId]['backends'] ?? []) as $backend) {
                    if (!\is_array($backend)) {
                        continue;
                    }
                    $key = (string)($backend['host'] ?? '') . ':'
                        . (int)($backend['port'] ?? 0);
                    $instanceBackends[$key] = $backend;
                }
            }
            $instances[$instanceId] = [
                'instance_id' => $instanceId,
                'generation' => $instanceGeneration,
                'digest' => $instanceDigest,
                'master_epoch' => $masterEpoch,
                'launch_id' => $launchId,
                'retirement_floor_generation' => (int)(
                    $retirementFloor['instance_generation'] ?? 0
                ),
                'retirement_floor_digest' => (string)(
                    $retirementFloor['retirement_digest'] ?? ''
                ),
                'last_heartbeat' => \time(),
                'last_heartbeat_monotonic' => $this->monotonicNow(),
                'lease_boot_id' => $this->hostBootId,
                'registered_at' => \gmdate(DATE_ATOM),
                'backends' => \array_values($instanceBackends),
                'backend_identity' => $instanceIdentity,
                'status' => 'ACTIVE',
                'drain_until' => null,
                'drain_until_monotonic' => null,
            ];
            $this->state['instances'][$projectUuid] = $instances;
            $this->maybeLeaveIsolationMode();
            $this->requestOperationResultContext = [
                'kind' => 'registration_lease',
                'project_uuid' => $projectUuid,
                'instance_id' => $instanceId,
                'security_revocations' => $securityRevocations,
            ];
            $this->bumpGeneration('register', [
                'project_uuid' => $projectUuid,
                'instance_id' => $instanceId,
                'renew' => $renew,
                'project_changed' => $projectChanged,
            ]);
            $this->configDirty = $this->configDirty
                || $routingChanged
                || $projectChanged
                || $securityRetirementRefreshRequired;
            if ($this->configDirty && !$this->publishIfDirty()) {
                throw new \DomainException(
                    'Gateway desired state was rejected; the previous active publication was retained.'
                );
            } else {
                $this->completePublication();
            }
            $result = [
                'idempotent' => false,
                'epoch' => (string)$this->state['epoch'],
                'generation' => (int)$this->state['generation'],
                'routes' => $this->projectRoutes($projectUuid),
                'security_retirements' => $this->securityRetirementResult(
                    $securityRevocations,
                ),
            ];
            if ($this->lastQueuedOperationId === '') {
                $result['lease_receipt'] = $this->registrationLeaseReceipt(
                    $projectUuid,
                    $instanceId,
                );
            }
            $this->commitCertificateSnapshotBatch();
            return $result;
        } catch (\Throwable $throwable) {
            try {
                if ($routingMutationStarted) {
                    $this->abortRoutingMutation(
                        'Registration transaction aborted: ' . $throwable->getMessage()
                    );
                }
            } finally {
                $this->abortCertificateSnapshotBatch();
            }
            throw $throwable;
        }
    }

    /**
     * @param array<int,array<string,mixed>> $routes
     * @return list<array{project_uuid:string,domain:string,generation:int,source_digest:string}>
     */
    private function registrationSecurityRevocations(
        string $projectUuid,
        array $routes,
    ): array {
        $revocations = [];
        foreach ($routes as $route) {
            if (!\is_array($route)) {
                continue;
            }
            $certificate = \is_array($route['certificate'] ?? null)
                ? $route['certificate']
                : [];
            if (!\hash_equals(
                'disabled',
                \strtolower(\trim((string)($certificate['state'] ?? ''))),
            )) {
                continue;
            }
            $domain = $this->normalizeDomain((string)($route['domain'] ?? ''));
            $generation = $certificate['generation'] ?? null;
            $sourceDigest = \strtolower(\trim((string)(
                $certificate['source_digest'] ?? ''
            )));
            if (!\is_int($generation)
                || $generation < 1
                || !\hash_equals(
                    \hash(
                        'sha256',
                        "wls-disabled-certificate\0" . $domain . "\0" . $generation,
                    ),
                    $sourceDigest,
                )
            ) {
                throw new \DomainException(
                    'Disabled certificate route is not bound to an exact tombstone.',
                );
            }
            $key = $projectUuid . ':' . $domain;
            $revocations[$key] = [
                'project_uuid' => $projectUuid,
                'domain' => $domain,
                'generation' => $generation,
                'source_digest' => $sourceDigest,
            ];
        }
        \ksort($revocations, SORT_STRING);
        return \array_values($revocations);
    }

    /**
     * @param array<int,mixed> $requirements
     * @return list<array<string,mixed>>
     */
    private function securityRetirementResult(array $requirements): array
    {
        $result = [];
        foreach ($requirements as $requirement) {
            if (!\is_array($requirement)) {
                continue;
            }
            $projectUuid = (string)($requirement['project_uuid'] ?? '');
            $domain = (string)($requirement['domain'] ?? '');
            $generation = (int)($requirement['generation'] ?? 0);
            $sourceDigest = (string)($requirement['source_digest'] ?? '');
            $receipt = $this->state['security_retirements'][
                $projectUuid . ':' . $domain
            ] ?? null;
            if (!\is_array($receipt)
                || !\hash_equals($projectUuid, (string)($receipt['project_uuid'] ?? ''))
                || !\hash_equals($domain, (string)($receipt['domain'] ?? ''))
                || (int)($receipt['generation'] ?? 0) !== $generation
                || !\hash_equals(
                    $sourceDigest,
                    (string)($receipt['source_digest'] ?? ''),
                )
                || ($receipt['old_generation_retired'] ?? false) !== true
                || !\hash_equals(
                    (string)($this->state['epoch'] ?? ''),
                    (string)($receipt['gateway_epoch'] ?? ''),
                )
                || (int)($receipt['active_config_generation'] ?? 0)
                    !== (int)($this->state['active_config_generation'] ?? -1)
                || !\hash_equals(
                    (string)($this->state['active_config_digest'] ?? ''),
                    (string)($receipt['active_config_digest'] ?? ''),
                )
            ) {
                continue;
            }
            $result[] = $receipt;
        }
        \usort(
            $result,
            static fn (array $left, array $right): int =>
                ((string)$left['project_uuid'] . ':' . (string)$left['domain'])
                    <=> ((string)$right['project_uuid'] . ':' . (string)$right['domain']),
        );
        return $result;
    }

    /**
     * Return the existing in-flight publication for an identical project
     * registration. A response can be lost after the desired state is
     * durably queued; retrying that same envelope must not increment route
     * generations or enqueue a second publication.
     *
     * @return array<string,mixed>
     */
    private function pendingPublicationOperationForProject(
        string $projectUuid,
        string $instanceId,
    ): array
    {
        $operations = \array_reverse((array)($this->state['operations'] ?? []), true);
        foreach ($operations as $operationId => $operation) {
            if (!\is_array($operation)
                || !\in_array(
                    (string)($operation['state'] ?? ''),
                    ['PENDING_PUBLICATION', 'PREPARING', 'ACTIVATING'],
                    true,
                )
                || !\hash_equals(
                    $projectUuid,
                    (string)($operation['project_uuid'] ?? ''),
                )
                || !\in_array(
                    (string)($operation['operation'] ?? ''),
                    ['register', 'renew'],
                    true,
                )
                || !\hash_equals(
                    $instanceId,
                    (string)($operation['result_context']['instance_id'] ?? ''),
                )
            ) {
                continue;
            }
            $operation['operation_id'] = (string)($operation['operation_id'] ?? $operationId);
            if (\preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)$operation['operation_id'],
            ) === 1) {
                return $operation;
            }
        }
        return [];
    }

    /** @param list<int|string> $incomingRouteIds */
    private function assertRetainedRouteCapacity(array $incomingRouteIds): void
    {
        $projectedRouteIds = \array_fill_keys(
            \array_map('strval', \array_keys((array)($this->state['routes'] ?? []))),
            true,
        );
        foreach ($incomingRouteIds as $routeId) {
            $routeId = (string)$routeId;
            if ($routeId !== '') {
                $projectedRouteIds[$routeId] = true;
            }
        }
        if (\count($projectedRouteIds) > self::MAX_TOTAL_ROUTES) {
            throw new \DomainException(
                'Gateway retained route quota of 2048 would be exceeded; '
                    . 'wait for safe REMOVED-route compaction before adding domains.'
            );
        }
    }

    /**
     * @param list<array<string,mixed>> $routes
     */
    private function assertDomainsAuthorized(string $projectUuid, array $routes): void
    {
        $enrollment = $this->state['enrollments'][$projectUuid] ?? null;
        $allowed = \is_array($enrollment)
            ? \array_values(\array_map('strval', (array)($enrollment['allowed_domains'] ?? [])))
            : [];
        foreach ($routes as $route) {
            $domain = (string)($route['domain'] ?? '');
            $authorized = false;
            foreach ($allowed as $pattern) {
                if (\hash_equals($pattern, $domain)) {
                    $authorized = true;
                    break;
                }
                if (\str_starts_with($pattern, '*.')
                    && !\str_starts_with($domain, '*.')
                    && \substr_count($pattern, '.') === \substr_count($domain, '.')
                    && \str_ends_with($domain, \substr($pattern, 1))
                ) {
                    $authorized = true;
                    break;
                }
            }
            if (!$authorized) {
                throw new \DomainException(
                    'Route domain is outside the project enrollment capability: ' . $domain
                );
            }
        }
    }

    private function registrationLeaseFullyActive(
        string $projectUuid,
        string $instanceId,
    ): bool {
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        $routeIds = (array)($this->state['projects'][$projectUuid]['route_ids'] ?? []);
        $monotonicNow = $this->monotonicNow();
        $instanceLeaseAge = \is_array($instance)
            ? $monotonicNow - (float)($instance['last_heartbeat_monotonic'] ?? 0.0)
            : -1.0;
        if (!\is_array($instance)
            || !\hash_equals('ACTIVE', (string)($instance['status'] ?? ''))
            || !$this->sameLeaseBoot($instance)
            || $instanceLeaseAge < 0.0
            || $instanceLeaseAge >= self::HEARTBEAT_TTL
            || $routeIds === []
            || !$this->projectPublicationExact($projectUuid)
        ) {
            return false;
        }
        foreach ($routeIds as $routeId) {
            $route = $this->state['routes'][(string)$routeId] ?? null;
            $published = $this->state['active_routes'][(string)$routeId] ?? null;
            $routeInstance = \is_array($route)
                ? ($route['instances'][$instanceId] ?? null)
                : null;
            $publishedInstance = \is_array($published)
                ? ($published['instances'][$instanceId] ?? null)
                : null;
            $routeLeaseAge = \is_array($routeInstance)
                ? $monotonicNow - (float)(
                    $routeInstance['last_heartbeat_monotonic'] ?? 0.0
                )
                : -1.0;
            if (!\is_array($route)
                || !\is_array($published)
                || !\in_array(
                    (string)($route['status'] ?? ''),
                    ['ACTIVE', 'PENDING_CERTIFICATE'],
                    true,
                )
                || !\is_array($routeInstance)
                || !\is_array($publishedInstance)
                || !$this->sameLeaseBoot($routeInstance)
                || $routeLeaseAge < 0.0
                || $routeLeaseAge >= self::HEARTBEAT_TTL
                || !\hash_equals('ACTIVE', (string)($routeInstance['status'] ?? ''))
                || !\hash_equals('ACTIVE', (string)($publishedInstance['status'] ?? ''))
                || ($routeInstance['backend_healthy'] ?? false) !== true
                || ($publishedInstance['backend_healthy'] ?? false) !== true
                || !$this->registrationInstanceFactsMatch($instance, $routeInstance)
                || !$this->registrationInstanceFactsMatch($instance, $publishedInstance)
                || !\hash_equals(
                    $this->canonicalJson((array)($routeInstance['backends'] ?? [])),
                    $this->canonicalJson((array)($publishedInstance['backends'] ?? [])),
                )
                || !\hash_equals(
                    $this->canonicalJson((array)($routeInstance['backend_identity'] ?? [])),
                    $this->canonicalJson((array)($publishedInstance['backend_identity'] ?? [])),
                )
            ) {
                return false;
            }
        }
        return true;
    }

    /**
     * A draining lease is valid only for the exact, already-published launch
     * and drain operation. It authorizes lifecycle heartbeats/unregister while
     * the fixed deadline runs; it never changes the instance back to ACTIVE.
     */
    private function drainingLeaseFullyPublished(
        string $projectUuid,
        string $instanceId,
        string $expectedDrainOperationId = '',
    ): bool {
        $project = $this->state['projects'][$projectUuid] ?? null;
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        $routeIds = \is_array($project)
            ? \array_values(\array_unique(\array_map(
                'strval',
                (array)($project['route_ids'] ?? []),
            )))
            : [];
        $drainOperationId = \is_array($instance)
            ? \strtolower(\trim((string)($instance['drain_operation_id'] ?? '')))
            : '';
        $drainSeconds = \is_array($instance)
            ? (int)($instance['drain_seconds'] ?? 0)
            : 0;
        $drainStartedAt = \is_array($instance)
            ? (int)($instance['drain_started_at'] ?? 0)
            : 0;
        $drainStartedMonotonic = \is_array($instance)
            ? (float)($instance['drain_started_monotonic'] ?? 0.0)
            : 0.0;
        $drainUntil = \is_array($instance)
            ? (int)($instance['drain_until'] ?? 0)
            : 0;
        $drainUntilMonotonic = \is_array($instance)
            ? (float)($instance['drain_until_monotonic'] ?? 0.0)
            : 0.0;
        $computedDrainOperationId = \is_array($instance)
            ? $this->drainOperationId(
                $projectUuid,
                $instanceId,
                (int)($instance['generation'] ?? 0),
                (int)($instance['master_epoch'] ?? 0),
                \strtolower(\trim((string)($instance['launch_id'] ?? ''))),
            )
            : '';
        if (!\is_array($project)
            || !\is_array($instance)
            || !\hash_equals('DRAINING', (string)($instance['status'] ?? ''))
            || !$this->sameLeaseBoot($instance)
            || \preg_match('/\A[a-f0-9]{64}\z/D', $drainOperationId) !== 1
            || !\hash_equals($computedDrainOperationId, $drainOperationId)
            || ($expectedDrainOperationId !== ''
                && (\preg_match('/\A[a-f0-9]{64}\z/D', $expectedDrainOperationId) !== 1
                    || !\hash_equals($expectedDrainOperationId, $drainOperationId)))
            || $drainSeconds < 1
            || $drainSeconds > self::DRAIN_SECONDS
            || $drainStartedAt < 1
            || !\is_finite($drainStartedMonotonic)
            || $drainStartedMonotonic <= 0.0
            || $drainUntil < 1
            || !\is_finite($drainUntilMonotonic)
            || $drainUntilMonotonic <= 0.0
            || $drainUntil !== $drainStartedAt + $drainSeconds
            || \abs(
                $drainUntilMonotonic
                    - ($drainStartedMonotonic + $drainSeconds),
            ) > 0.001
            || $routeIds === []
            || !$this->drainingDesiredClosureMatches(
                $projectUuid,
                $instanceId,
                $drainOperationId,
                $drainSeconds,
                $drainStartedAt,
                $drainStartedMonotonic,
                $drainUntil,
                $drainUntilMonotonic,
            )
            || !$this->projectPublicationExact($projectUuid)
        ) {
            return false;
        }
        foreach ($routeIds as $routeId) {
            $current = $this->state['routes'][$routeId] ?? null;
            $published = $this->state['active_routes'][$routeId] ?? null;
            $currentInstance = \is_array($current)
                ? ($current['instances'][$instanceId] ?? null)
                : null;
            $publishedInstance = \is_array($published)
                ? ($published['instances'][$instanceId] ?? null)
                : null;
            if (!\is_array($current)
                || !\is_array($published)
                || !\is_array($currentInstance)
                || !\is_array($publishedInstance)
                || !\hash_equals(
                    $projectUuid,
                    (string)($current['project_uuid'] ?? ''),
                )
                || !\hash_equals(
                    $projectUuid,
                    (string)($published['project_uuid'] ?? ''),
                )
                || !\hash_equals(
                    'DRAINING',
                    (string)($currentInstance['status'] ?? ''),
                )
                || !\hash_equals(
                    'DRAINING',
                    (string)($publishedInstance['status'] ?? ''),
                )
                || !$this->sameLeaseBoot($currentInstance)
                || !$this->sameLeaseBoot($publishedInstance)
                || !\hash_equals(
                    $drainOperationId,
                    (string)($currentInstance['drain_operation_id'] ?? ''),
                )
                || !\hash_equals(
                    $drainOperationId,
                    (string)($publishedInstance['drain_operation_id'] ?? ''),
                )
                || (int)($currentInstance['drain_seconds'] ?? 0) !== $drainSeconds
                || (int)($publishedInstance['drain_seconds'] ?? 0) !== $drainSeconds
                || (int)($currentInstance['drain_started_at'] ?? 0)
                    !== $drainStartedAt
                || (int)($publishedInstance['drain_started_at'] ?? 0)
                    !== $drainStartedAt
                || (float)($currentInstance['drain_started_monotonic'] ?? 0.0)
                    !== $drainStartedMonotonic
                || (float)($publishedInstance['drain_started_monotonic'] ?? 0.0)
                    !== $drainStartedMonotonic
                || (int)($currentInstance['drain_until'] ?? 0) !== $drainUntil
                || (int)($publishedInstance['drain_until'] ?? 0) !== $drainUntil
                || (float)($currentInstance['drain_until_monotonic'] ?? 0.0)
                    !== $drainUntilMonotonic
                || (float)($publishedInstance['drain_until_monotonic'] ?? 0.0)
                    !== $drainUntilMonotonic
                || !$this->registrationInstanceFactsMatch($instance, $currentInstance)
                || !$this->registrationInstanceFactsMatch($instance, $publishedInstance)
            ) {
                return false;
            }
        }
        return true;
    }

    /**
     * @param array<string,mixed> $instance
     * @param array<string,mixed> $routeInstance
     */
    private function registrationInstanceFactsMatch(
        array $instance,
        array $routeInstance,
    ): bool {
        return (int)($instance['generation'] ?? 0) > 0
            && (int)($instance['generation'] ?? 0)
                === (int)($routeInstance['generation'] ?? -1)
            && \hash_equals(
                (string)($instance['digest'] ?? ''),
                (string)($routeInstance['digest'] ?? ''),
            )
            && (int)($instance['master_epoch'] ?? 0) > 0
            && (int)($instance['master_epoch'] ?? 0)
                === (int)($routeInstance['master_epoch'] ?? -1)
            && \hash_equals(
                (string)($instance['launch_id'] ?? ''),
                (string)($routeInstance['launch_id'] ?? ''),
            );
    }

    /**
     * Issue the project's durable proof that a specific WLS launch and its
     * complete route generation set reached Controller COMMITTED state.
     *
     * @return array<string,mixed>
     */
    private function registrationLeaseReceipt(
        string $projectUuid,
        string $instanceId,
        bool $allowPublishedDrain = false,
        string $expectedDrainOperationId = '',
    ): array {
        if (!$this->registrationLeaseFullyActive($projectUuid, $instanceId)
            && (!$allowPublishedDrain
                || !$this->drainingLeaseFullyPublished(
                    $projectUuid,
                    $instanceId,
                    $expectedDrainOperationId,
                ))
        ) {
            throw new \RuntimeException(
                'Registration lease cannot be issued before the exact desired route and '
                    . 'instance lifecycle closure is active in the verified publication.'
            );
        }
        $project = $this->state['projects'][$projectUuid] ?? null;
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        $enrollment = $this->state['enrollments'][$projectUuid] ?? null;
        if (!\is_array($project)
            || !\is_array($instance)
            || !\is_array($enrollment)
            || !$this->validProjectUuid($projectUuid)
            || !\hash_equals(
                (string)($project['project_uuid'] ?? ''),
                $projectUuid,
            )
            || !\hash_equals(
                (string)($enrollment['project_uuid'] ?? ''),
                $projectUuid,
            )
        ) {
            throw new \RuntimeException(
                'Committed registration lease facts are unavailable.'
            );
        }
        $secret = \strtolower(\trim((string)(
            $enrollment['credential_secret'] ?? ''
        )));
        $projectGeneration = (int)($project['generation'] ?? 0);
        $instanceGeneration = (int)($instance['generation'] ?? 0);
        $instanceDigest = \strtolower(\trim((string)($instance['digest'] ?? '')));
        $masterEpoch = (int)($instance['master_epoch'] ?? 0);
        $launchId = \strtolower(\trim((string)($instance['launch_id'] ?? '')));
        $requestDigest = \strtolower(\trim((string)($project['digest'] ?? '')));
        $idempotencyKey = \strtolower(\trim((string)(
            $project['idempotency_key'] ?? ''
        )));
        $activeConfigGeneration = (int)(
            $this->state['active_config_generation'] ?? 0
        );
        $activeConfigDigest = \strtolower(\trim((string)(
            $this->state['active_config_digest'] ?? ''
        )));
        $issuedMonotonic = $this->monotonicNow();
        $leaseSequence = \max(
            $this->lastLeaseReceiptSequence + 1,
            (int)\hrtime(true),
        );
        $this->lastLeaseReceiptSequence = $leaseSequence;
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $secret) !== 1
            || $projectGeneration < 1
            || $instanceGeneration < 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $instanceDigest) !== 1
            || $masterEpoch < 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $launchId) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $requestDigest) !== 1
            || \preg_match('/\A[a-f0-9]{40}\z/D', $idempotencyKey) !== 1
            || $activeConfigGeneration < 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $activeConfigDigest) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $this->hostBootId) !== 1
            || $issuedMonotonic <= 0.0
            || $leaseSequence < 1
            || !\hash_equals(
                \substr(\hash(
                    'sha256',
                    $projectUuid . ':desired:' . $projectGeneration . ':'
                        . $requestDigest,
                ), 0, 40),
                $idempotencyKey,
            )
        ) {
            throw new \RuntimeException(
                'Committed registration lease identity is malformed.'
            );
        }
        $routeGenerations = [];
        foreach ((array)($project['route_ids'] ?? []) as $routeId) {
            $routeId = \strtolower(\trim((string)$routeId));
            $route = $this->state['routes'][$routeId] ?? null;
            if (\preg_match('/\A[a-f0-9]{32}\z/D', $routeId) !== 1
                || !\is_array($route)
                || !\hash_equals(
                    $projectUuid,
                    (string)($route['project_uuid'] ?? ''),
                )
                || (int)($route['route_generation'] ?? 0) < 1
            ) {
                throw new \RuntimeException(
                    'Committed registration route generation closure is malformed.'
                );
            }
            $routeGenerations[$routeId] = (int)$route['route_generation'];
        }
        \ksort($routeGenerations, SORT_STRING);
        if ($routeGenerations === [] || \count($routeGenerations) > 256) {
            throw new \RuntimeException(
                'Committed registration has no bounded route generation closure.'
            );
        }
        $receipt = [
            'schema_version' => 2,
            'protocol' => self::PROTOCOL,
            'host_id' => $this->hostId(),
            'host_boot_id' => $this->hostBootId,
            'project_uuid' => $projectUuid,
            'gateway_epoch' => (string)$this->state['epoch'],
            'project_generation' => $projectGeneration,
            'instance_id' => $instanceId,
            'instance_generation' => $instanceGeneration,
            'instance_digest' => $instanceDigest,
            'master_epoch' => $masterEpoch,
            'launch_id' => $launchId,
            'request_digest' => $requestDigest,
            'idempotency_key' => $idempotencyKey,
            'active_config_generation' => $activeConfigGeneration,
            'active_config_digest' => $activeConfigDigest,
            'lease_ttl_seconds' => self::HEARTBEAT_TTL,
            'issued_monotonic' => $issuedMonotonic,
            'lease_sequence' => $leaseSequence,
            'route_generations' => $routeGenerations,
            'routes_digest' => \hash(
                'sha256',
                $this->canonicalJson($routeGenerations),
            ),
            'issued_at' => \gmdate(DATE_ATOM),
        ];
        $receipt['signature'] = \hash_hmac(
            'sha256',
            $this->canonicalJson($receipt),
            $secret,
        );
        return $receipt;
    }

    /**
     * Replace the authenticated project's complete HTTP-01 lease set.
     *
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function syncAcmeChallenges(array $payload): array
    {
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        $challengeGeneration = (int)($payload['challenge_generation'] ?? 0);
        if ($challengeGeneration < 1) {
            throw new \DomainException(
                'ACME HTTP-01 challenge generation must be positive.'
            );
        }
        $enrollment = $this->state['enrollments'][$projectUuid] ?? null;
        if (!\is_array($enrollment)
            || (($enrollment['capabilities']['acme_http_01'] ?? false) !== true)
        ) {
            throw new \DomainException(
                'The project enrollment does not grant the ACME HTTP-01 capability.'
            );
        }
        $incoming = \is_array($payload['challenges'] ?? null)
            ? $payload['challenges']
            : [];
        if (\count($incoming) > 32) {
            throw new \DomainException('A project may hold at most 32 ACME HTTP-01 leases.');
        }
        $now = \time();
        $leases = [];
        $desiredChallenges = [];
        foreach ($incoming as $challenge) {
            if (!\is_array($challenge)) {
                throw new \DomainException('ACME HTTP-01 lease must be an object.');
            }
            $domain = $this->normalizeDomain((string)($challenge['domain'] ?? ''));
            if (\str_starts_with($domain, '*.')) {
                throw new \DomainException('Wildcard domains cannot use ACME HTTP-01.');
            }
            $this->assertDomainsAuthorized($projectUuid, [['domain' => $domain]]);
            $routeOwned = false;
            foreach ((array)($this->state['routes'] ?? []) as $route) {
                if (\is_array($route)
                    && \hash_equals($projectUuid, (string)($route['project_uuid'] ?? ''))
                    && \hash_equals($domain, (string)($route['domain'] ?? ''))
                    && (string)($route['status'] ?? '') !== 'REMOVED'
                ) {
                    $routeOwned = true;
                    break;
                }
            }
            if (!$routeOwned) {
                throw new \DomainException(
                    'ACME HTTP-01 lease requires an existing project-owned route.'
                );
            }
            $token = \trim((string)($challenge['token'] ?? ''));
            $keyAuthorization = \trim((string)(
                $challenge['key_authorization'] ?? $challenge['keyAuth'] ?? ''
            ));
            $expiresAt = (int)($challenge['expires_at'] ?? 0);
            if (\preg_match('/\A[A-Za-z0-9_-]{1,256}\z/D', $token) !== 1
                || \preg_match(
                    '/\A[A-Za-z0-9_-]{1,256}\.[A-Za-z0-9_-]{20,256}\z/D',
                    $keyAuthorization,
                ) !== 1
                || !\str_starts_with($keyAuthorization, $token . '.')
                || $expiresAt < $now + 30
                || $expiresAt > $now + 900
            ) {
                throw new \DomainException('ACME HTTP-01 lease token, key authorization or expiry is invalid.');
            }
            $leaseId = \hash('sha256', $projectUuid . "\0" . $domain . "\0" . $token);
            if (isset($leases[$leaseId])) {
                throw new \DomainException('Duplicate ACME HTTP-01 lease is forbidden.');
            }
            $desiredChallenge = [
                'domain' => $domain,
                'token' => $token,
                'key_authorization' => $keyAuthorization,
                'expires_at' => $expiresAt,
            ];
            $desiredChallenges[] = $desiredChallenge;
            $leases[$leaseId] = [
                'lease_id' => $leaseId,
                'project_uuid' => $projectUuid,
                ...$desiredChallenge,
            ];
        }
        \ksort($leases, SORT_STRING);
        \usort(
            $desiredChallenges,
            static fn (array $left, array $right): int => [
                $left['domain'],
                $left['token'],
            ] <=> [
                $right['domain'],
                $right['token'],
            ],
        );
        $desiredDigest = \hash(
            'sha256',
            $this->canonicalJson($desiredChallenges),
        );
        $claimedDigest = \strtolower(\trim((string)(
            $payload['desired_digest'] ?? $desiredDigest
        )));
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $claimedDigest) !== 1
            || !\hash_equals($desiredDigest, $claimedDigest)
        ) {
            throw new \DomainException('ACME HTTP-01 desired digest does not match its leases.');
        }
        $existingGeneration = \is_array(
            $this->state['acme_generations'][$projectUuid] ?? null,
        ) ? $this->state['acme_generations'][$projectUuid] : [];
        $currentGeneration = (int)($existingGeneration['generation'] ?? 0);
        $currentDigest = (string)($existingGeneration['digest'] ?? '');
        if ($challengeGeneration < $currentGeneration) {
            throw new \DomainException('ACME HTTP-01 challenge generation is stale.');
        }
        if ($challengeGeneration === $currentGeneration
            && $currentGeneration > 0
            && !\hash_equals($currentDigest, $desiredDigest)
        ) {
            throw new \DomainException(
                'ACME HTTP-01 challenge generation is ambiguous.'
            );
        }

        $this->beginRoutingMutation('acme-challenge-sync:' . $projectUuid);
        try {
            $current = (array)($this->state['acme_challenges'] ?? []);
            foreach ($current as $leaseId => $lease) {
                if (\is_array($lease)
                    && \hash_equals($projectUuid, (string)($lease['project_uuid'] ?? ''))
                ) {
                    unset($current[$leaseId]);
                }
            }
            $current += $leases;
            \ksort($current, SORT_STRING);
            $before = $this->canonicalJson((array)($this->state['acme_challenges'] ?? []));
            $after = $this->canonicalJson($current);
            $this->state['acme_challenges'] = $current;
            $this->state['acme_generations'][$projectUuid] = [
                'generation' => $challengeGeneration,
                'digest' => $desiredDigest,
                'updated_at' => \gmdate(DATE_ATOM),
            ];
            if (!\hash_equals($before, $after)) {
                $this->configDirty = true;
                $this->bumpGeneration('acme_challenge_sync', [
                    'project_uuid' => $projectUuid,
                    'count' => \count($leases),
                ]);
                if (!$this->publishIfDirty()) {
                    throw new \DomainException(
                        'ACME challenge publication failed; the previous active config was retained.'
                    );
                }
            } else {
                // The Nginx bundle is unchanged, but the anti-replay fence is
                // durable protocol state and must survive Controller restart.
                $this->persistState();
                $this->completePublication();
            }
            return [
                'accepted' => true,
                'count' => \count($leases),
                'challenge_generation' => $challengeGeneration,
                'desired_digest' => $desiredDigest,
            ];
        } catch (\Throwable $throwable) {
            $this->abortRoutingMutation(
                'ACME challenge transaction aborted: ' . $throwable->getMessage()
            );
            throw $throwable;
        }
    }

    /**
     * @param array<string,mixed> $route
     * @return array<string,mixed>
     */
    private function validateRoute(
        array $route,
        string $projectUuid,
        string $projectRoot,
        string $instanceId,
        int $instanceGeneration,
        int $masterEpoch,
        string $launchId,
        float $deadlineMonotonic,
        bool $deferCertificateSnapshot = false,
        bool $deferBackendProbe = false,
    ): array {
        $this->assertDeadlineAvailable($deadlineMonotonic, 'Route validation');
        $routeId = \strtolower(\trim((string)($route['route_id'] ?? '')));
        $domain = $this->normalizeDomain((string)($route['domain'] ?? ''));
        if (!\is_bool($route['force_https'] ?? null)
            || !\is_bool($route['force_root_to_www'] ?? null)
        ) {
            throw new \DomainException(
                'Route edge policies must be explicit booleans.'
            );
        }
        if ($route['force_root_to_www'] === true
            && (\str_starts_with($domain, '*.') || \str_starts_with($domain, 'www.'))
        ) {
            throw new \DomainException(
                'force_root_to_www is valid only on an exact non-www route.'
            );
        }
        $rootToWwwTarget = (string)($route['root_to_www_target'] ?? '');
        $expectedRootToWwwTarget = $route['force_root_to_www'] === true
            ? 'www.' . $domain
            : '';
        if (!\hash_equals($expectedRootToWwwTarget, $rootToWwwTarget)) {
            throw new \DomainException(
                'Route root-to-www target is not the canonical same-project domain.'
            );
        }
        if (!\hash_equals($this->canonicalRouteId($projectUuid, $domain), $routeId)) {
            throw new \DomainException('Route ID must be the canonical project/domain digest.');
        }
        $backends = \is_array($route['backends'] ?? null) ? $route['backends'] : [];
        if ($backends === [] || \count($backends) > self::MAX_BACKENDS_PER_ROUTE) {
            throw new \DomainException('Route must contain 1..16 backends.');
        }
        $normalizedBackends = [];
        $backendEndpoints = [];
        foreach ($backends as $backend) {
            if (!\is_array($backend)) {
                throw new \DomainException('Backend must be an object.');
            }
            $host = \strtolower(\trim((string)($backend['host'] ?? '')));
            $port = (int)($backend['port'] ?? 0);
            if (!\in_array($host, ['127.0.0.1', '::1', 'localhost'], true)
                || $port < 1 || $port > 65535
            ) {
                throw new \DomainException('Gateway backends must be valid loopback endpoints.');
            }
            $normalizedHost = $host === 'localhost' ? '127.0.0.1' : $host;
            $endpointKey = $normalizedHost . ':' . $port;
            if (isset($backendEndpoints[$endpointKey])) {
                throw new \DomainException(
                    'Route contains a duplicate backend listener: ' . $endpointKey
                );
            }
            $backendEndpoints[$endpointKey] = true;
            $normalizedBackends[] = [
                'host' => $normalizedHost,
                'port' => $port,
                'weight' => \max(1, \min(1000, (int)($backend['weight'] ?? 1))),
            ];
        }

        $identity = \is_array($route['backend_identity'] ?? null)
            ? $route['backend_identity']
            : [];
        if (!\hash_equals($projectUuid, (string)($identity['project_uuid'] ?? ''))
            || !\hash_equals($instanceId, (string)($identity['instance_id'] ?? ''))
            || (int)($identity['generation'] ?? 0) !== $instanceGeneration
            || (int)($identity['master_epoch'] ?? 0) !== $masterEpoch
            || !\hash_equals(
                $launchId,
                \strtolower(\trim((string)($identity['launch_id'] ?? ''))),
            )
        ) {
            throw new \DomainException(
                'Backend identity does not match the registering project and launch fence.'
            );
        }
        $certificate = \is_array($route['certificate'] ?? null) ? $route['certificate'] : [];
        $certificateGeneration = (int)($certificate['generation'] ?? -1);
        $certificatePending = $certificate['pending'] ?? $certificateGeneration === 0;
        $certificateState = \strtolower(\trim((string)(
            $certificate['state']
                ?? (($certificateGeneration > 0 && $certificatePending === false)
                    ? 'active'
                    : 'pending')
        )));
        if (!\in_array($certificateState, ['active', 'pending', 'disabled'], true)
            || ($certificateState === 'disabled'
                && ($route['force_https'] !== false
                    || $route['force_root_to_www'] !== false))
        ) {
            throw new \DomainException(
                'Disabled certificate routes must retain plain HTTP without redirects.'
            );
        }
        $this->assertCertificateProgression($projectUuid, $domain, $certificate);
        $this->validateBackendEndpointIdentity($identity, $projectRoot, $normalizedBackends);
        $backendHealthy = false;
        if (!$deferBackendProbe) {
            $failureKind = null;
            $backendProbe = $this->probeBackends(
                $normalizedBackends,
                $identity,
                false,
                $failureKind,
                $deadlineMonotonic,
            );
            if ($backendProbe === 'DEFERRED') {
                throw new \DomainException('Registration route validation exceeded its deadline.');
            }
            $backendHealthy = $backendProbe === 'HEALTHY';
        }

        $snapshot = $certificate;
        if (!$deferCertificateSnapshot) {
            $this->assertDeadlineAvailable($deadlineMonotonic, 'Certificate snapshot');
            $snapshot = $this->snapshotCertificate(
                $projectUuid,
                $projectRoot,
                $domain,
                $certificate,
            );
            $this->assertDeadlineAvailable($deadlineMonotonic, 'Certificate snapshot');
        }
        $enrollment = (array)($this->state['enrollments'][$projectUuid] ?? []);
        $status = $backendHealthy ? 'ACTIVE' : 'PENDING_BACKEND';
        if (!$deferCertificateSnapshot && !($snapshot['valid'] ?? false)) {
            $status = 'PENDING_CERTIFICATE';
        }
        $existing = $this->state['routes'][$routeId] ?? null;
        $ownershipFloor = $this->state['domain_ownership'][$domain] ?? null;
        $retainedRouteGeneration = \is_array($ownershipFloor)
            && \hash_equals(
                $projectUuid,
                (string)($ownershipFloor['project_uuid'] ?? ''),
            )
            && \hash_equals($routeId, (string)($ownershipFloor['route_id'] ?? ''))
                ? (int)($ownershipFloor['route_generation'] ?? 0)
                : 0;
        $routeGeneration = \max(
            \is_array($existing)
                ? (int)($existing['route_generation'] ?? 0) + 1
                : 1,
            $retainedRouteGeneration + 1,
        );
        $domainOwnership = $this->state['security']['tombstones']['domain:' . $domain] ?? null;
        $domainSecurityGeneration = \is_array($domainOwnership)
            && \hash_equals(
                $projectUuid,
                (string)($domainOwnership['to_project_uuid'] ?? ''),
            )
                ? (int)($domainOwnership['generation'] ?? 0)
                : 0;
        return [
            'route_id' => $routeId,
            'project_uuid' => $projectUuid,
            'project_root' => $projectRoot,
            'enrollment_security_generation' => (int)($enrollment['security_generation'] ?? 0),
            'instance_id' => $instanceId,
            'domain' => $domain,
            'backends' => $normalizedBackends,
            'backend_identity' => $identity,
            'certificate' => $snapshot,
            'route_generation' => $routeGeneration,
            'domain_security_generation' => $domainSecurityGeneration,
            'status' => $status,
            'last_heartbeat' => \time(),
            'last_backend_probe' => \time(),
            'stale_since' => null,
            'drain_until' => null,
            'force_https' => $route['force_https'],
            'force_root_to_www' => $route['force_root_to_www'],
            'root_to_www_target' => $rootToWwwTarget,
            'updated_at' => \gmdate(DATE_ATOM),
        ];
    }

    /**
     * @param list<array<string,mixed>> $routes
     */
    private function nonCertificateDesiredDigest(
        string $projectUuid,
        string $projectRoot,
        array $routes,
    ): string {
        $facts = [];
        foreach ($routes as $route) {
            $facts[] = [
                'route_id' => (string)($route['route_id'] ?? ''),
                'domain' => (string)($route['domain'] ?? ''),
                'force_https' => (bool)($route['force_https'] ?? true),
                'force_root_to_www' => (bool)(
                    $route['force_root_to_www'] ?? false
                ),
                'root_to_www_target' => (string)(
                    $route['root_to_www_target'] ?? ''
                ),
            ];
        }
        \usort(
            $facts,
            static fn (array $left, array $right): int =>
                (string)$left['domain'] <=> (string)$right['domain'],
        );
        return \hash('sha256', $this->canonicalJson([
            'project_uuid' => $projectUuid,
            'project_root' => $projectRoot,
            // WLS 2.0 project generation carries only the stable policy; all
            // live capability evidence remains instance-fenced below.
            'backend_capability' => ['policy' => 'runtime_attested'],
            'routes' => $facts,
        ]));
    }

    /**
     * Bind the project generation/idempotency key to the exact desired route
     * facts emitted by GatewayRegistrationBuilder. The narrower
     * non-certificate digest is an additional renew fence; it must not become
     * a substitute that leaves certificate source/generation outside the
     * request digest.
     *
     * @param list<array<string,mixed>> $routes
     */
    private function projectDesiredDigest(
        string $projectUuid,
        string $projectRoot,
        array $routes,
    ): string {
        $facts = [];
        foreach ($routes as $route) {
            $certificate = \is_array($route['certificate'] ?? null)
                ? $route['certificate']
                : [];
            $facts[] = [
                'route_id' => (string)($route['route_id'] ?? ''),
                'domain' => (string)($route['domain'] ?? ''),
                'certificate' => [
                    'state' => $this->certificateLifecycleState($certificate),
                    'source_digest' => (string)(
                        $certificate['source_digest'] ?? ''
                    ),
                    'generation' => (int)($certificate['generation'] ?? 0),
                ],
                'force_https' => (bool)($route['force_https'] ?? true),
                'force_root_to_www' => (bool)(
                    $route['force_root_to_www'] ?? false
                ),
                'root_to_www_target' => (string)(
                    $route['root_to_www_target'] ?? ''
                ),
            ];
        }
        \usort(
            $facts,
            static fn (array $left, array $right): int =>
                (string)$left['domain'] <=> (string)$right['domain'],
        );
        return \hash('sha256', $this->canonicalJson([
            'project_uuid' => $projectUuid,
            'project_root' => $projectRoot,
            'backend_capability' => ['policy' => 'runtime_attested'],
            'routes' => $facts,
        ]));
    }

    /**
     * @param list<array<string,mixed>> $routes
     */
    private function instanceDesiredDigest(
        string $projectUuid,
        string $instanceId,
        int $instanceGeneration,
        array $routes,
    ): string {
        $orderedRoutes = $routes;
        \usort(
            $orderedRoutes,
            static fn (array $left, array $right): int =>
                (string)($left['domain'] ?? '') <=> (string)($right['domain'] ?? ''),
        );
        $identity = null;
        $backendSets = [];
        foreach ($orderedRoutes as $route) {
            $candidateIdentity = \is_array($route['backend_identity'] ?? null)
                ? $route['backend_identity']
                : [];
            if ($candidateIdentity === []) {
                throw new \DomainException(
                    'Registration route has no backend identity for its instance digest.'
                );
            }
            if ($identity === null) {
                $identity = $candidateIdentity;
            } elseif (!\hash_equals(
                $this->canonicalJson($identity),
                $this->canonicalJson($candidateIdentity),
            )) {
                throw new \DomainException(
                    'One instance registration must use one backend identity across all routes.'
                );
            }
            $backendSets[] = \array_values((array)($route['backends'] ?? []));
        }
        if (!\is_array($identity) || $backendSets === []) {
            throw new \DomainException(
                'Registration instance digest has no complete route closure.'
            );
        }
        return \hash('sha256', $this->canonicalJson([
            'project_uuid' => $projectUuid,
            'instance_id' => $instanceId,
            'instance_generation' => $instanceGeneration,
            'backend_identity' => $identity,
            'backends' => $backendSets,
        ]));
    }

    /**
     * `renew` is deliberately narrower than `register`: it may replace only
     * certificate source/generation facts. Any route, ownership, transport or
     * live capability transition needs a full register replay so its complete
     * desired-state digest and publication fences are reevaluated together.
     *
     * @param list<array<string,mixed>> $candidateRoutes
     * @param array<string,int> $expectedRouteGenerations
     */
    private function assertCertificateOnlyRenewal(
        string $projectUuid,
        string $projectRoot,
        string $instanceId,
        int $instanceGeneration,
        string $instanceDigest,
        int $masterEpoch,
        string $launchId,
        string $nonCertificateDesiredDigest,
        array $candidateRoutes,
        array $expectedRouteGenerations,
        bool $sameDesiredRegistration,
    ): bool {
        $replayRequired = static function (string $reason): never {
            throw new \DomainException(
                'REGISTER_REPLAY_REQUIRED: certificate renew may only change '
                    . 'certificate facts; ' . $reason
            );
        };
        $project = $this->state['projects'][$projectUuid] ?? null;
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        if (!\is_array($project) || !\is_array($instance)) {
            $replayRequired('the project or instance has no current registration');
        }
        if (!\hash_equals($projectRoot, (string)($project['project_root'] ?? ''))
            || !\hash_equals(
                $nonCertificateDesiredDigest,
                (string)($project['non_certificate_desired_digest'] ?? ''),
            )
        ) {
            $replayRequired('the project non-certificate desired state changed');
        }
        if ((int)($instance['generation'] ?? 0) !== $instanceGeneration
            || !\hash_equals((string)($instance['digest'] ?? ''), $instanceDigest)
            || (int)($instance['master_epoch'] ?? 0) !== $masterEpoch
            || !\hash_equals((string)($instance['launch_id'] ?? ''), $launchId)
        ) {
            $replayRequired('the instance capability or launch fence changed');
        }
        $registeredRouteIds = \array_values(\array_unique(\array_map(
            'strval',
            (array)($project['route_ids'] ?? []),
        )));
        $candidateRouteIds = \array_map(
            static fn (array $route): string => (string)($route['route_id'] ?? ''),
            $candidateRoutes,
        );
        \sort($registeredRouteIds, SORT_STRING);
        \sort($candidateRouteIds, SORT_STRING);
        if ($registeredRouteIds === [] || $registeredRouteIds !== $candidateRouteIds) {
            $replayRequired('the route set changed');
        }

        $certificatesAlreadyApplied = $sameDesiredRegistration;
        foreach ($candidateRoutes as $candidate) {
            $routeId = (string)($candidate['route_id'] ?? '');
            $current = $this->state['routes'][$routeId] ?? null;
            $currentInstance = \is_array($current)
                ? ($current['instances'][$instanceId] ?? null)
                : null;
            if (!\is_array($current) || !\is_array($currentInstance)) {
                $replayRequired('a route or its instance lease is no longer registered');
            }
            $currentNonCertificateFacts = [
                'route_id' => (string)($current['route_id'] ?? ''),
                'project_uuid' => (string)($current['project_uuid'] ?? ''),
                'project_root' => (string)($current['project_root'] ?? ''),
                'enrollment_security_generation' => (int)(
                    $current['enrollment_security_generation'] ?? 0
                ),
                'domain' => (string)($current['domain'] ?? ''),
                'domain_security_generation' => (int)(
                    $current['domain_security_generation'] ?? 0
                ),
                'force_https' => (bool)($current['force_https'] ?? true),
                'force_root_to_www' => (bool)(
                    $current['force_root_to_www'] ?? false
                ),
                'instance_id' => (string)($currentInstance['instance_id'] ?? ''),
                'backends' => (array)($currentInstance['backends'] ?? []),
                'backend_identity' => (array)(
                    $currentInstance['backend_identity'] ?? []
                ),
            ];
            $candidateNonCertificateFacts = [
                'route_id' => (string)($candidate['route_id'] ?? ''),
                'project_uuid' => (string)($candidate['project_uuid'] ?? ''),
                'project_root' => (string)($candidate['project_root'] ?? ''),
                'enrollment_security_generation' => (int)(
                    $candidate['enrollment_security_generation'] ?? 0
                ),
                'domain' => (string)($candidate['domain'] ?? ''),
                'domain_security_generation' => (int)(
                    $candidate['domain_security_generation'] ?? 0
                ),
                'force_https' => (bool)($candidate['force_https'] ?? true),
                'force_root_to_www' => (bool)(
                    $candidate['force_root_to_www'] ?? false
                ),
                'instance_id' => $instanceId,
                'backends' => (array)($candidate['backends'] ?? []),
                'backend_identity' => (array)($candidate['backend_identity'] ?? []),
            ];
            if (!\hash_equals(
                \hash('sha256', $this->canonicalJson($currentNonCertificateFacts)),
                \hash('sha256', $this->canonicalJson($candidateNonCertificateFacts)),
            )) {
                $replayRequired(
                    'route ownership, edge policy, backend or capability facts changed'
                );
            }
            $currentRouteGeneration = (int)($current['route_generation'] ?? 0);
            $expectedRouteGeneration = (int)(
                $expectedRouteGenerations[$routeId] ?? 0
            );
            $currentCertificate = (array)($current['certificate'] ?? []);
            $candidateCertificate = (array)($candidate['certificate'] ?? []);
            $certificateAlreadyApplied = (int)($currentCertificate['generation'] ?? -1)
                    === (int)($candidateCertificate['generation'] ?? -2)
                && \hash_equals(
                    (string)($currentCertificate['source_digest'] ?? ''),
                    (string)($candidateCertificate['source_digest'] ?? ''),
                );
            $certificatesAlreadyApplied = $certificatesAlreadyApplied
                && $certificateAlreadyApplied;
            if ($sameDesiredRegistration && $certificateAlreadyApplied) {
                if (!\in_array(
                    $expectedRouteGeneration,
                    [$currentRouteGeneration, $currentRouteGeneration - 1],
                    true,
                )) {
                    throw new \DomainException(
                        'Certificate renew idempotent route generation fence was rejected.'
                    );
                }
            } elseif ($expectedRouteGeneration !== $currentRouteGeneration) {
                throw new \DomainException(
                    'Certificate renew route generation fence was rejected.'
                );
            }
        }
        return $certificatesAlreadyApplied;
    }

    /**
     * @param array<string,mixed> $identity
     * @param list<array{host:string,port:int,weight:int}> $backends
     */
    private function validateBackendEndpointIdentity(array $identity, string $projectRoot, array $backends): void
    {
        $instanceId = (string)($identity['instance_id'] ?? '');
        $edgeSecret = \strtolower(\trim((string)($identity['edge_capability_secret'] ?? '')));
        $edgeDigest = \strtolower(\trim((string)($identity['edge_capability_digest'] ?? '')));
        $projectUuid = \strtolower(\trim((string)($identity['project_uuid'] ?? '')));
        $generation = (int)($identity['generation'] ?? 0);
        $masterPid = (int)($identity['master_pid'] ?? 0);
        $masterEpoch = (int)($identity['master_epoch'] ?? 0);
        $launchId = \strtolower(\trim((string)($identity['launch_id'] ?? '')));
        $listenerLeaseId = \strtolower(\trim((string)(
            $identity['listener_lease_id'] ?? ''
        )));
        $publicDigest = \strtolower(\trim((string)(
            $identity['public_digest'] ?? ''
        )));
        $claimedDigest = \strtolower(\trim((string)($identity['digest'] ?? '')));
        $allowedIdentityFields = \array_fill_keys(\array_merge(
            self::BACKEND_IDENTITY_PUBLIC_FIELDS,
            self::BACKEND_IDENTITY_PRIVATE_FIELDS,
        ), true);
        foreach (\array_keys($identity) as $identityField) {
            if (!\is_string($identityField)
                || !isset($allowedIdentityFields[$identityField])
            ) {
                throw new \DomainException(
                    'Backend signed identity contains an unsupported field.'
                );
            }
        }
        $publicIdentity = $identity;
        unset(
            $publicIdentity['edge_capability_secret'],
            $publicIdentity['digest'],
            $publicIdentity['public_digest'],
        );
        $unsignedIdentity = $identity;
        unset($unsignedIdentity['digest']);
        if (!\hash_equals(
                self::BACKEND_IDENTITY_SCHEMA,
                (string)($identity['schema'] ?? ''),
            )
            || \preg_match('/\A[a-f0-9]{64}\z/D', $edgeSecret) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $edgeDigest) !== 1
            || !\hash_equals($edgeDigest, \hash('sha256', $edgeSecret))
            || !$this->validProjectUuid($projectUuid)
            || $instanceId === ''
            || $generation < 1
            || $masterPid < 1
            || $masterEpoch < 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $launchId) !== 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $listenerLeaseId) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $publicDigest) !== 1
            || !\hash_equals(
                $publicDigest,
                \hash('sha256', $this->canonicalJson($publicIdentity)),
            )
            || \preg_match('/\A[a-f0-9]{64}\z/D', $claimedDigest) !== 1
            || !\hash_equals(
                $claimedDigest,
                \hash('sha256', $this->canonicalJson($unsignedIdentity)),
            )
        ) {
            throw new \DomainException(
                'Backend signed identity claim is incomplete or internally inconsistent.'
            );
        }
        foreach ($backends as $backend) {
            if (!\is_array($backend)
                || !\in_array((string)($backend['host'] ?? ''), ['127.0.0.1', '::1'], true)
                || (int)($backend['port'] ?? 0) < 1
                || (int)($backend['port'] ?? 0) > 65535
            ) {
                throw new \DomainException(
                    'Every backend must be a valid loopback listener.'
                );
            }
        }
        // Do not read a project-controlled endpoint file from the privileged
        // gateway. probeBackendHealth() challenges the actual listener and
        // verifies an HMAC over these exact claims instead.
        $this->validateBackendSessionCapabilityClaim($identity);
    }

    /**
     * Runtime distribution evidence is accepted only when it is bound to the
     * exact project endpoint record. Legacy or unknown claims stay isolated.
     *
     * @param array<string,mixed> $identity
     * @param array<string,mixed> $endpoint
     */
    private function validateBackendSessionCapabilityClaim(array $identity): void
    {
        $modeValue = $identity['session_capability'] ?? null;
        $mode = \is_string($modeValue)
            ? \strtolower(\trim($modeValue))
            : '';
        $evidencePresent = \array_key_exists(
            'session_capability_evidence',
            $identity,
        );
        $evidenceDigestPresent = \array_key_exists(
            'session_capability_evidence_digest',
            $identity,
        );
        if ($mode === 'isolated') {
            if ($evidencePresent || $evidenceDigestPresent) {
                throw new \DomainException(
                    'Isolated backend capability must not carry distribution evidence.'
                );
            }
            return;
        }
        if (!\in_array($mode, ['stateless', 'shared_session'], true)
            || !$evidencePresent
            || !$evidenceDigestPresent
        ) {
            throw new \DomainException(
                'Backend session capability evidence is missing or invalid.'
            );
        }
        $evidence = \is_array($identity['session_capability_evidence'] ?? null)
            ? $identity['session_capability_evidence']
            : [];
        $evidenceDigest = \strtolower(\trim((string)(
            $identity['session_capability_evidence_digest'] ?? ''
        )));
        if ($evidence === []
            || \preg_match('/\A[a-f0-9]{64}\z/D', $evidenceDigest) !== 1
            || !\hash_equals(
                $evidenceDigest,
                \hash('sha256', $this->canonicalJson($evidence)),
            )
        ) {
            throw new \DomainException(
                'Backend session capability evidence is missing or invalid.'
            );
        }
        if ($mode === 'stateless') {
            $generation = (int)($identity['generation'] ?? 0);
            $validStateless = $this->exactCapabilityEvidenceFields($evidence, [
                    'schema',
                    'runtime_source',
                    'runtime_declared',
                    'instance_generation',
                    'reason',
                ])
                && \is_bool($evidence['runtime_declared'] ?? null)
                && \is_int($evidence['instance_generation'] ?? null)
                && \hash_equals(
                    'wls-stateless-capability/1',
                    (string)($evidence['schema'] ?? ''),
                )
                && \hash_equals(
                    'project_endpoint',
                    (string)($evidence['runtime_source'] ?? ''),
                )
                && ($evidence['runtime_declared'] ?? false) === true
                && (int)($evidence['instance_generation'] ?? 0) === $generation
                && \hash_equals(
                    'declared_stateless_runtime',
                    (string)($evidence['reason'] ?? ''),
                );
            if (!$validStateless) {
                throw new \DomainException(
                    'Backend stateless capability evidence does not match the project runtime.'
                );
            }
            return;
        }
        if ($mode !== 'shared_session') {
            throw new \DomainException(
                'Backend session capability evidence is missing or invalid.'
            );
        }

        $host = \strtolower(\trim((string)($evidence['host'] ?? '')));
        if ($host === 'localhost') {
            $host = '127.0.0.1';
        }
        $tokenScopeDigest = \strtolower(\trim((string)(
            $evidence['token_scope_digest'] ?? ''
        )));
        $valid = $this->exactCapabilityEvidenceFields($evidence, [
                'schema',
                'storage',
                'runtime_source',
                'runtime_registered',
                'runtime_shared_service',
                'host',
                'port',
                'token_scope_digest',
                'probe',
                'reason',
            ])
            && \is_bool($evidence['runtime_registered'] ?? null)
            && \is_bool($evidence['runtime_shared_service'] ?? null)
            && \is_int($evidence['port'] ?? null)
            && \hash_equals(
                'wls-session-capability/1',
                (string)($evidence['schema'] ?? ''),
            )
            && \hash_equals('wls', (string)($evidence['storage'] ?? ''))
            && \hash_equals(
                'project_shared_state',
                (string)($evidence['runtime_source'] ?? ''),
            )
            && ($evidence['runtime_registered'] ?? false) === true
            && ($evidence['runtime_shared_service'] ?? false) === true
            && \hash_equals('healthy', (string)($evidence['probe'] ?? ''))
            && \hash_equals(
                'authenticated_session_runtime',
                (string)($evidence['reason'] ?? ''),
            )
            && \in_array($host, ['127.0.0.1', '::1'], true)
            && (int)($evidence['port'] ?? 0) > 0
            && (int)($evidence['port'] ?? 0) <= 65535
            && \preg_match('/\A[a-f0-9]{64}\z/D', $tokenScopeDigest) === 1
            ;
        if (!$valid) {
            throw new \DomainException(
                'Backend session capability evidence does not match the project runtime.'
            );
        }
    }

    /** @param list<string> $expected */
    private function exactCapabilityEvidenceFields(array $evidence, array $expected): bool
    {
        if (\array_is_list($evidence)) {
            return false;
        }
        $actual = \array_keys($evidence);
        foreach ($actual as $field) {
            if (!\is_string($field)) {
                return false;
            }
        }
        \sort($actual, SORT_STRING);
        \sort($expected, SORT_STRING);
        return $actual === $expected;
    }

    /** @param array<string,mixed> $join */
    private function joinBackendHasLiveWorker(array $join): bool
    {
        foreach ((array)($join['workers'] ?? []) as $worker) {
            if (!\is_array($worker)
                || !\hash_equals('READY', \strtoupper((string)($worker['state'] ?? '')))
            ) {
                continue;
            }
            if ($this->pidRunning((int)($worker['pid'] ?? 0))) {
                return true;
            }
        }
        return $this->pidRunning((int)($join['worker_pid'] ?? 0));
    }

    private function beginCertificateSnapshotBatch(): void
    {
        if ($this->certificateSnapshotBatchActive) {
            throw new \RuntimeException(
                'A certificate snapshot batch is already active.'
            );
        }
        $this->stagedCertificateSnapshots = [];
        $this->certificateSnapshotBatchActive = true;
    }

    private function commitCertificateSnapshotBatch(): void
    {
        $this->stagedCertificateSnapshots = [];
        $this->certificateSnapshotBatchActive = false;
    }

    private function abortCertificateSnapshotBatch(): void
    {
        if (!$this->certificateSnapshotBatchActive) {
            return;
        }
        $created = \array_keys($this->stagedCertificateSnapshots);
        // Close the batch before cleanup. Reference discovery deliberately
        // excludes the operation-local set and protects only independently
        // durable users of a bundle.
        $this->stagedCertificateSnapshots = [];
        $this->certificateSnapshotBatchActive = false;
        foreach ($created as $digest) {
            if ($this->certificateSnapshotReferenced((string)$digest)) {
                continue;
            }
            $this->removeSnapshotDirectory(
                $this->home . DIRECTORY_SEPARATOR . 'snapshots'
                    . DIRECTORY_SEPARATOR . (string)$digest,
            );
        }
    }

    private function certificateSnapshotReferenced(string $digest): bool
    {
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $digest) !== 1) {
            return true;
        }
        if ($this->valueContainsSnapshotDigest($this->state, $digest)
            || ($this->publication !== null
                && $this->valueContainsSnapshotDigest($this->publication, $digest))
        ) {
            return true;
        }

        // The durable route checkpoint and both retained LKG bundles are
        // independent recovery roots. If one is present but unreadable, fail
        // closed and retain the candidate rather than risk breaking recovery.
        $routeLkgFile = $this->routeLkgFile();
        $routeLkg = $this->loadRouteSnapshot($routeLkgFile);
        if ((\is_file($routeLkgFile) || \is_link($routeLkgFile))
            && $routeLkg === null
        ) {
            return true;
        }
        if ($routeLkg !== null
            && $this->valueContainsSnapshotDigest($routeLkg, $digest)
        ) {
            return true;
        }
        foreach ((array)($this->state['lkg'] ?? []) as $entry) {
            if (!\is_array($entry)) {
                return true;
            }
            $bundle = $this->loadLkgBundle($entry);
            if ($bundle === null) {
                return true;
            }
            if (\in_array($digest, $bundle['certificate_digests'], true)) {
                return true;
            }
        }
        return false;
    }

    private function valueContainsSnapshotDigest(mixed $value, string $digest, int $depth = 0): bool
    {
        if ($depth > 64 || !\is_array($value)) {
            return false;
        }
        foreach ($value as $key => $item) {
            if (\is_string($key)
                && \hash_equals('snapshot_digest', $key)
                && \is_string($item)
                && \hash_equals($digest, $item)
            ) {
                return true;
            }
            if ($this->valueContainsSnapshotDigest($item, $digest, $depth + 1)) {
                return true;
            }
        }
        return false;
    }

    /**
     * @param array<string,mixed> $certificate
     * @return array<string,mixed>
     */
    private function snapshotCertificate(
        string $projectUuid,
        string $projectRoot,
        string $domain,
        array $certificate,
    ): array {
        $sourceDigest = \strtolower(\trim((string)(
            $certificate['source_digest'] ?? ''
        )));
        $certificateGeneration = (int)($certificate['generation'] ?? -1);
        $pending = $certificate['pending'] ?? $certificateGeneration === 0;
        $state = \strtolower(\trim((string)(
            $certificate['state']
                ?? (($certificateGeneration > 0 && $pending === false)
                    ? 'active'
                    : 'pending')
        )));
        if (!\in_array($state, ['active', 'pending', 'disabled'], true)
            || !\is_bool($pending)
            || \preg_match('/\A[a-f0-9]{64}\z/D', $sourceDigest) !== 1
        ) {
            throw new \DomainException('Certificate lifecycle state is invalid.');
        }
        if ($state !== 'active') {
            $certReference = $certificate['cert'] ?? [];
            $keyReference = $certificate['key'] ?? [];
            if (\str_starts_with($domain, '*.')
                || !\is_array($certReference)
                || $certReference !== []
                || !\is_array($keyReference)
                || $keyReference !== []
                || ($certificate['chain'] ?? null) !== null
                || $pending !== true
                || ($state === 'pending'
                    && ($certificateGeneration !== 0
                        || !\hash_equals(
                            \hash('sha256', "wls-pending-certificate\0" . $domain),
                            $sourceDigest,
                        )))
                || ($state === 'disabled'
                    && ($certificateGeneration < 1
                        || !\hash_equals(
                            \hash(
                                'sha256',
                                "wls-disabled-certificate\0" . $domain . "\0"
                                    . $certificateGeneration,
                            ),
                            $sourceDigest,
                        )))
            ) {
                throw new \DomainException(
                    'Inactive certificate route lifecycle envelope is invalid.'
                );
            }
            return [
                'state' => $state,
                'valid' => false,
                'pending' => true,
                'source_digest' => $sourceDigest,
                'snapshot_digest' => '',
                'generation' => $certificateGeneration,
                'cert_path' => '',
                'key_path' => '',
                'chain_path' => '',
                'not_after' => 0,
            ];
        }
        if ($pending !== false || $certificateGeneration < 1) {
            throw new \DomainException(
                'Active certificate route lifecycle envelope is invalid.'
            );
        }
        $certReference = \is_array($certificate['cert'] ?? null)
            ? $certificate['cert']
            : [];
        $keyReference = \is_array($certificate['key'] ?? null)
            ? $certificate['key']
            : [];
        $chainReference = \is_array($certificate['chain'] ?? null)
            ? $certificate['chain']
            : null;
        $reused = $this->reusableCertificateSnapshot(
            $domain,
            $sourceDigest,
            $certificateGeneration,
            $certReference,
            $keyReference,
            $chainReference,
        );
        // A content-addressed bundle is only a storage candidate. The project
        // remains the certificate fact source, so every register/renew must
        // still re-read its currently enrolled paths with the no-follow
        // Broker and prove permissions, key match, SAN, validity and the exact
        // source digest before the global bundle may be reused.
        if ($reused === null
            && $this->snapshotStorageBytes()
                + self::MAX_CERTIFICATE_SNAPSHOT_BUNDLE_BYTES
                > self::MAX_SNAPSHOT_BYTES
        ) {
            $this->collectSnapshots();
            if ($this->snapshotStorageBytes()
                    + self::MAX_CERTIFICATE_SNAPSHOT_BUNDLE_BYTES
                > self::MAX_SNAPSHOT_BYTES
            ) {
                $this->markDiskPressure(
                    'SNAPSHOT_QUOTA',
                    'certificate_snapshot_quota_exhausted',
                );
                throw new \DomainException(
                    'Gateway certificate snapshot quota is exhausted; active and LKG snapshots were retained.'
                );
            }
        }
        $snapshotRoot = $this->home . DIRECTORY_SEPARATOR . 'snapshots';
        $stagingDigest = \hash('sha256', 'candidate:' . \random_bytes(32));
        $snapshotDir = $snapshotRoot . DIRECTORY_SEPARATOR . $stagingDigest;
        $brokerSnapshot = $this->brokerActionsAvailable('project');
        $stagingMode = $brokerSnapshot ? 0770 : 0700;
        if (!@\mkdir($snapshotDir, $stagingMode) || !\is_dir($snapshotDir)) {
            throw new \RuntimeException('Unable to create certificate snapshot directory.');
        }
        if (!@\chmod($snapshotDir, $stagingMode)) {
            $this->removeSnapshotDirectory($snapshotDir);
            throw new \RuntimeException(
                'Unable to seal certificate snapshot staging permissions.'
            );
        }
        $newlyPublishedFinalDir = '';
        $publishedSnapshotAccepted = false;
        try {
        $enrollment = \is_array($this->state['enrollments'][$projectUuid] ?? null)
            ? $this->state['enrollments'][$projectUuid]
            : [];
        $securityGeneration = (int)($enrollment['security_generation'] ?? 0);
        if ($brokerSnapshot) {
            if ($securityGeneration < 1) {
                throw new \DomainException('Certificate snapshot enrollment generation is unavailable.');
            }
            $certReal = $this->brokerSnapshotCertificateSource(
                $projectUuid,
                $securityGeneration,
                $certReference,
                $stagingDigest,
                'source-cert.pem',
            );
            $keyReal = $this->brokerSnapshotCertificateSource(
                $projectUuid,
                $securityGeneration,
                $keyReference,
                $stagingDigest,
                'source-key.pem',
            );
            $chainReal = $chainReference !== null
                ? $this->brokerSnapshotCertificateSource(
                    $projectUuid,
                    $securityGeneration,
                    $chainReference,
                    $stagingDigest,
                    'source-chain.pem',
                )
                : '';
        } elseif ($this->brokerActionsRequired()) {
            throw new \RuntimeException(
                'Production certificate snapshot requires a native Broker no-follow action.'
            );
        } else {
            $certReal = $this->resolveCertificateReference($projectUuid, $certReference);
            $keyReal = $this->resolveCertificateReference($projectUuid, $keyReference);
            $chainReal = $chainReference !== null
                ? $this->resolveCertificateReference($projectUuid, $chainReference)
                : '';
        }
        try {
            $certSource = $this->readStableRegularFileWithStatus(
                $certReal,
                1024 * 1024,
                'Certificate source',
            );
            $keySource = $this->readStableRegularFileWithStatus(
                $keyReal,
                1024 * 1024,
                'Certificate private key source',
            );
            $chainSource = $chainReal !== ''
                ? $this->readStableRegularFileWithStatus(
                    $chainReal,
                    1024 * 1024,
                    'Certificate chain source',
                )
                : ['contents' => '', 'status' => []];
        } catch (\Throwable $throwable) {
            throw new \DomainException(
                'Certificate material cannot be read from one stable regular file identity: '
                    . $throwable->getMessage()
            );
        }
        if (\PHP_OS_FAMILY !== 'Windows'
            && ((((int)($keySource['status']['mode'] ?? 0)) & 0077) !== 0)
        ) {
            throw new \DomainException(
                'Certificate private key must not grant group or other permissions.'
            );
        }
        $certPem = $certSource['contents'];
        $keyPem = $keySource['contents'];
        $chainPem = $chainSource['contents'];
        $beforeCert = \hash('sha256', $certPem);
        $beforeKey = \hash('sha256', $keyPem);
        $beforeChain = $chainPem !== '' ? \hash('sha256', $chainPem) : '';
        $normalizedBundle = $this->normalizeAndValidateCertificateChain(
            $certPem,
            $chainPem,
        );
        $leafPem = $normalizedBundle['leaf'];
        $x509 = @\openssl_x509_read($leafPem);
        $private = @\openssl_pkey_get_private($keyPem);
        $public = $x509 !== false ? @\openssl_pkey_get_public($x509) : false;
        if ($x509 === false || $private === false || $public === false) {
            throw new \DomainException('Certificate or private key is invalid.');
        }
        $privateDetails = @\openssl_pkey_get_details($private);
        $publicDetails = @\openssl_pkey_get_details($public);
        if (!\is_array($privateDetails)
            || !\is_array($publicDetails)
            || !\hash_equals((string)($privateDetails['key'] ?? ''), (string)($publicDetails['key'] ?? ''))
        ) {
            throw new \DomainException('Certificate private key does not match.');
        }
        $keyType = (int)($privateDetails['type'] ?? -1);
        $keyBits = (int)($privateDetails['bits'] ?? 0);
        if (($keyType === OPENSSL_KEYTYPE_RSA && $keyBits < 2048)
            || ($keyType === OPENSSL_KEYTYPE_EC && $keyBits < 256)
            || !\in_array($keyType, [OPENSSL_KEYTYPE_RSA, OPENSSL_KEYTYPE_EC], true)
        ) {
            throw new \DomainException('Certificate key algorithm or strength is not accepted.');
        }
        $parsed = @\openssl_x509_parse($x509, false);
        $now = \time();
        if (!\is_array($parsed)
            || (int)($parsed['validFrom_time_t'] ?? PHP_INT_MAX) > $now
            || (int)($parsed['validTo_time_t'] ?? 0) <= \time()
            || !$this->certificateCoversDomain($parsed, $domain)
        ) {
            throw new \DomainException('Certificate SAN or validity does not cover route domain.');
        }
        $calculatedSourceDigest = \hash(
            'sha256',
            $beforeCert . ':' . $beforeKey . ':' . $beforeChain,
        );
        if (!\hash_equals($calculatedSourceDigest, $sourceDigest)) {
            throw new \DomainException('Certificate source digest does not match registered material.');
        }
        if ($reused !== null) {
            return $reused;
        }
        $snapshotDigest = $calculatedSourceDigest;
        $certCandidate = $snapshotDir . DIRECTORY_SEPARATOR . 'fullchain.pem';
        $keyCandidate = $snapshotDir . DIRECTORY_SEPARATOR . 'privkey.pem';
        $fullchain = $normalizedBundle['fullchain'];
        $this->atomicWrite($certCandidate, $fullchain, 0644);
        $this->atomicWrite($keyCandidate, $keyPem, 0600);
        foreach (['source-cert.pem', 'source-key.pem', 'source-chain.pem'] as $sourceLeaf) {
            $sourcePath = $snapshotDir . DIRECTORY_SEPARATOR . $sourceLeaf;
            if (\file_exists($sourcePath) || \is_link($sourcePath)) {
                $this->removeStableRegularFile(
                    $sourcePath,
                    'Gateway broker certificate source snapshot',
                );
            }
        }
        $manifestPayload = [
            'schema_version' => 1,
            'source_digest' => $snapshotDigest,
            'fullchain_sha256' => \hash('sha256', $fullchain),
            'private_key_sha256' => \hash('sha256', $keyPem),
            'not_after' => (int)$parsed['validTo_time_t'],
            'created_at' => \gmdate(DATE_ATOM),
        ];
        $this->atomicWrite(
            $snapshotDir . DIRECTORY_SEPARATOR . 'manifest.json',
            (string)\json_encode([
                'payload' => $manifestPayload,
                'sha256' => \hash('sha256', $this->canonicalJson($manifestPayload)),
            ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR),
            0600,
        );
        if (!@\chmod($snapshotDir, 0700)) {
            throw new \RuntimeException(
                'Unable to seal certificate snapshot publication permissions.'
            );
        }
        $this->syncDirectory($snapshotDir);
        $finalSnapshotDir = $snapshotRoot . DIRECTORY_SEPARATOR . $snapshotDigest;
        if (\is_dir($finalSnapshotDir)) {
            if (!$this->snapshotBundleValid($finalSnapshotDir, $snapshotDigest)) {
                $this->removeSnapshotDirectory($snapshotDir);
                throw new \RuntimeException(
                    'Existing content-addressed certificate snapshot is damaged; refusing to overwrite it.'
                );
            }
            $this->removeSnapshotDirectory($snapshotDir);
        } else {
            try {
                $this->moveStableChildDirectory(
                    $snapshotDir,
                    $finalSnapshotDir,
                    $snapshotRoot,
                    '/\A[a-f0-9]{64}\z/D',
                    '/\A[a-f0-9]{64}\z/D',
                    3,
                    'Gateway certificate snapshot bundle',
                );
            } catch (\Throwable $throwable) {
                $this->removeSnapshotDirectory($snapshotDir);
                throw new \RuntimeException(
                    'Unable to atomically publish the certificate snapshot bundle: '
                        . $throwable->getMessage(),
                    0,
                    $throwable,
                );
            }
            $newlyPublishedFinalDir = $finalSnapshotDir;
            if ($this->certificateSnapshotBatchActive) {
                $this->stagedCertificateSnapshots[$snapshotDigest] = true;
            }
            $this->syncDirectory($snapshotRoot);
            $this->invalidateStorageStatus();
        }
        $certSnapshot = $finalSnapshotDir . DIRECTORY_SEPARATOR . 'fullchain.pem';
        $keySnapshot = $finalSnapshotDir . DIRECTORY_SEPARATOR . 'privkey.pem';
        if (!$this->snapshotBundleValid($finalSnapshotDir, $snapshotDigest)) {
            throw new \RuntimeException(
                'Published certificate snapshot bundle failed verification.'
            );
        }
        if ($newlyPublishedFinalDir !== ''
            && $this->snapshotStorageBytes() > self::MAX_SNAPSHOT_BYTES
        ) {
            throw new \RuntimeException(
                'Published certificate snapshot would exceed the hard storage quota.'
            );
        }
        $publishedSnapshotAccepted = true;
        return [
            'state' => 'active',
            'valid' => true,
            'pending' => false,
            'source_digest' => $sourceDigest,
            'source_refs' => [
                'cert' => $certReference,
                'key' => $keyReference,
                'chain' => $chainReference,
            ],
            'generation' => $certificateGeneration,
            'snapshot_digest' => $snapshotDigest,
            'cert_path' => $certSnapshot,
            'key_path' => $keySnapshot,
            'not_after' => (int)$parsed['validTo_time_t'],
        ];
        } finally {
            // The source validation and publication path has many intentional
            // rejection points. A rejected candidate must never accumulate
            // into the content-addressed snapshot quota.
            $this->removeSnapshotDirectory($snapshotDir);
            if (!$publishedSnapshotAccepted && $newlyPublishedFinalDir !== '') {
                unset($this->stagedCertificateSnapshots[$snapshotDigest]);
                $this->removeSnapshotDirectory($newlyPublishedFinalDir);
            }
        }
    }

    /**
     * Reuse is evaluated before quota reservation only to avoid charging an
     * existing immutable bundle as new storage. This is not source authority:
     * snapshotCertificate() still validates the current project-owned files
     * before accepting this candidate. The bundle itself is also revalidated,
     * including SAN and expiry, so a matching digest cannot cross domains.
     *
     * @param array<string,mixed> $certReference
     * @param array<string,mixed> $keyReference
     * @param array<string,mixed>|null $chainReference
     * @return array<string,mixed>|null
     */
    private function reusableCertificateSnapshot(
        string $domain,
        string $digest,
        int $generation,
        array $certReference,
        array $keyReference,
        ?array $chainReference,
    ): ?array {
        $root = $this->home . DIRECTORY_SEPARATOR . 'snapshots'
            . DIRECTORY_SEPARATOR . $digest;
        if (!$this->snapshotBundleValid($root, $digest)) {
            return null;
        }
        try {
            $certPath = $root . DIRECTORY_SEPARATOR . 'fullchain.pem';
            $keyPath = $root . DIRECTORY_SEPARATOR . 'privkey.pem';
            $certPem = $this->readStableRegularFile(
                $certPath,
                2 * 1024 * 1024,
                'Reusable gateway certificate snapshot',
            );
            $normalizedBundle = $this->normalizeAndValidateCertificateChain(
                $certPem,
                '',
            );
            $manifest = \json_decode($this->readStableRegularFile(
                $root . DIRECTORY_SEPARATOR . 'manifest.json',
                65_536,
                'Reusable gateway certificate manifest',
            ), true);
            $payload = \is_array($manifest['payload'] ?? null)
                ? $manifest['payload']
                : [];
            $x509 = @\openssl_x509_read($normalizedBundle['leaf']);
            $parsed = $x509 !== false ? @\openssl_x509_parse($x509, false) : false;
            $notAfter = (int)($payload['not_after'] ?? 0);
            if (!\is_array($parsed)
                || $notAfter <= \time()
                || $notAfter !== (int)($parsed['validTo_time_t'] ?? 0)
                || !$this->certificateCoversDomain($parsed, $domain)
            ) {
                return null;
            }
            return [
                'state' => 'active',
                'valid' => true,
                'pending' => false,
                'source_digest' => $digest,
                'source_refs' => [
                    'cert' => $certReference,
                    'key' => $keyReference,
                    'chain' => $chainReference,
                ],
                'generation' => $generation,
                'snapshot_digest' => $digest,
                'cert_path' => $certPath,
                'key_path' => $keyPath,
                'not_after' => $notAfter,
            ];
        } catch (\Throwable) {
            return null;
        }
    }

    /**
     * Normalize a leaf-first PEM bundle and independently verify every
     * adjacent issuer signature. Project metadata is only an input claim; the
     * privileged Controller must re-establish the complete chain from the
     * Broker-copied bytes before publishing it globally.
     *
     * @return array{leaf:string,fullchain:string}
     */
    private function normalizeAndValidateCertificateChain(
        string $certificatePem,
        string $chainPem,
    ): array {
        $blocks = $this->certificatePemBlocks($certificatePem, 'Certificate source');
        if ($blocks === []) {
            throw new \DomainException(
                'Certificate source does not contain a PEM leaf certificate.'
            );
        }
        if ($chainPem !== '') {
            $blocks = [
                ...$blocks,
                ...$this->certificatePemBlocks($chainPem, 'Certificate chain'),
            ];
        }
        if (\count($blocks) > 16) {
            throw new \DomainException(
                'Certificate bundle exceeds the 16-certificate chain limit.'
            );
        }

        $normalized = [];
        $parsedCertificates = [];
        $fingerprints = [];
        $now = \time();
        foreach ($blocks as $block) {
            $certificate = @\openssl_x509_read($block);
            $normalizedPem = '';
            if ($certificate === false
                || !@\openssl_x509_export($certificate, $normalizedPem, false)
            ) {
                throw new \DomainException(
                    'Certificate bundle contains an invalid X.509 certificate.'
                );
            }
            $body = \preg_replace(
                '/-----BEGIN CERTIFICATE-----|-----END CERTIFICATE-----|\s+/D',
                '',
                $normalizedPem,
            );
            $der = \is_string($body) ? \base64_decode($body, true) : false;
            if (!\is_string($der) || $der === '') {
                throw new \DomainException(
                    'Certificate bundle cannot be normalized to DER.'
                );
            }
            $fingerprint = \hash('sha256', $der);
            if (isset($fingerprints[$fingerprint])) {
                // Repeated intermediates are semantically redundant and can
                // make order/signature checks ambiguous. Normalize them out
                // while keeping the first leaf-first occurrence.
                continue;
            }
            $parsed = @\openssl_x509_parse($certificate, false);
            if (!\is_array($parsed)
                || (int)($parsed['validFrom_time_t'] ?? PHP_INT_MAX) > $now
                || (int)($parsed['validTo_time_t'] ?? 0) <= $now
            ) {
                throw new \DomainException(
                    'Certificate bundle contains a certificate outside its validity period.'
                );
            }
            $fingerprints[$fingerprint] = true;
            $normalized[] = \rtrim($normalizedPem) . "\n";
            $parsedCertificates[] = $parsed;
        }
        if ($normalized === []) {
            throw new \DomainException('Certificate bundle is empty after normalization.');
        }

        for ($index = 0, $last = \count($normalized) - 1; $index < $last; ++$index) {
            $issuerIndex = $index + 1;
            $issuerParsed = $parsedCertificates[$issuerIndex];
            $basicConstraints = \strtoupper((string)(
                $issuerParsed['extensions']['basicConstraints'] ?? ''
            ));
            $keyUsage = \strtolower((string)(
                $issuerParsed['extensions']['keyUsage'] ?? ''
            ));
            if (!\str_contains($basicConstraints, 'CA:TRUE')
                || ($keyUsage !== ''
                    && !\str_contains($keyUsage, 'certificate sign')
                    && !\str_contains($keyUsage, 'key cert sign'))
            ) {
                throw new \DomainException(
                    'Certificate chain issuer lacks CA or certificate-signing constraints.'
                );
            }
            if (!\hash_equals(
                $this->canonicalJson((array)(
                    $parsedCertificates[$index]['issuer'] ?? []
                )),
                $this->canonicalJson((array)($issuerParsed['subject'] ?? [])),
            )) {
                throw new \DomainException(
                    'Certificate chain is not ordered leaf-to-issuer.'
                );
            }
            $issuerKey = @\openssl_pkey_get_public($normalized[$issuerIndex]);
            if ($issuerKey === false
                || @\openssl_x509_verify($normalized[$index], $issuerKey) !== 1
            ) {
                throw new \DomainException(
                    'Certificate chain contains an invalid issuer signature.'
                );
            }
        }
        return [
            'leaf' => $normalized[0],
            'fullchain' => \implode('', $normalized),
        ];
    }

    /** @return list<string> */
    private function certificatePemBlocks(string $source, string $label): array
    {
        $matches = [];
        $count = \preg_match_all(
            '/-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----/s',
            $source,
            $matches,
        );
        if (!\is_int($count) || $count < 1) {
            throw new \DomainException($label . ' does not contain a PEM certificate.');
        }
        if ($count > 16) {
            throw new \DomainException(
                $label . ' exceeds the 16-certificate PEM block limit.'
            );
        }
        $remainder = \preg_replace(
            '/-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----/s',
            '',
            $source,
        );
        if (!\is_string($remainder) || \trim($remainder) !== '') {
            throw new \DomainException(
                $label . ' contains data outside PEM certificate blocks.'
            );
        }
        return \array_values(\array_map('strval', (array)($matches[0] ?? [])));
    }

    /**
     * @param array<string,mixed> $parsed
     */
    private function certificateCoversDomain(array $parsed, string $domain): bool
    {
        $names = [];
        $san = (string)($parsed['extensions']['subjectAltName'] ?? '');
        foreach (\explode(',', $san) as $entry) {
            $entry = \trim($entry);
            if (\str_starts_with($entry, 'DNS:')) {
                try {
                    $names[] = $this->normalizeDomain(\substr($entry, 4));
                } catch (\Throwable) {
                }
            }
        }
        foreach (\array_unique($names) as $name) {
            if ($name === $domain) {
                return true;
            }
            if (\str_starts_with($name, '*.')
                && \substr_count($domain, '.') === \substr_count($name, '.')
                && \str_ends_with($domain, \substr($name, 1))
            ) {
                return true;
            }
        }
        return false;
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function heartbeat(array $payload): array
    {
        $this->assertGatewayEpochPayload($payload, 'Heartbeat');
        $this->assertCurrentHostBootPayload($payload, 'Heartbeat');
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        $projectGeneration = (int)($payload['project_generation'] ?? 0);
        $instanceId = \trim((string)($payload['instance_id'] ?? ''));
        $instanceGeneration = (int)($payload['instance_generation'] ?? 0);
        $instanceDigest = \strtolower(\trim((string)(
            $payload['instance_digest'] ?? ''
        )));
        $masterEpoch = (int)($payload['master_epoch'] ?? 0);
        $launchId = \strtolower(\trim((string)($payload['launch_id'] ?? '')));
        $this->assertInstanceRetirementFence(
            $projectUuid,
            $instanceId,
            $instanceGeneration,
        );
        $project = $this->state['projects'][$projectUuid] ?? null;
        if (!\is_array($project)
            || (int)($project['generation'] ?? 0) !== $projectGeneration
            || $instanceId === ''
        ) {
            throw new \DomainException('Heartbeat project generation is stale or unknown.');
        }
        if ($instanceDigest !== ''
            && \preg_match('/\A[a-f0-9]{64}\z/D', $instanceDigest) !== 1
        ) {
            throw new \DomainException('Heartbeat instance digest is invalid.');
        }
        $registeredInstance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        if (!\is_array($registeredInstance)
            || (int)($registeredInstance['generation'] ?? 0) !== $instanceGeneration
            || (int)($registeredInstance['master_epoch'] ?? 0) !== $masterEpoch
            || !\hash_equals(
                (string)($registeredInstance['launch_id'] ?? ''),
                $launchId,
            )
        ) {
            throw new \DomainException('Instance lease fencing identity is stale or unknown.');
        }
        if ($instanceDigest !== ''
            && (string)($registeredInstance['digest'] ?? '') !== ''
            && !\hash_equals(
                (string)$registeredInstance['digest'],
                $instanceDigest,
            )
        ) {
            // Heartbeat remains state-only. Do not extend a lease whose full
            // runtime identity changed; ask the Agent to replay register.
            return [
                'epoch' => (string)$this->state['epoch'],
                'generation' => (int)$this->state['generation'],
                'accepted' => true,
                're_register_required' => true,
            ];
        }
        if (!$this->sameLeaseBoot($registeredInstance)) {
            // A monotonic timestamp is meaningful only within one host boot.
            // Never let a heartbeat rewrite the boot fence and revive a
            // persisted lease after reboot; the full signed desired state and
            // backend identity must be registered again.
            return [
                'epoch' => (string)$this->state['epoch'],
                'generation' => (int)$this->state['generation'],
                'accepted' => true,
                're_register_required' => true,
                'reason' => 'host_boot_changed',
            ];
        }
        $this->touchInstanceLease(
            $projectUuid,
            $instanceId,
            $masterEpoch,
            $launchId,
            $instanceGeneration,
            $this->normalizeDrainCounters($payload['drain_counters'] ?? null),
        );
        $expectedRouteIds = \array_values(\array_unique(\array_map(
            'strval',
            (array)($project['route_ids'] ?? []),
        )));
        $matchedRouteIds = [];
        $reRegisterRequired = false;
        foreach ((array)$this->state['routes'] as $routeId => $route) {
            if (!\is_array($route)
                || !\hash_equals(
                    $projectUuid,
                    (string)($route['project_uuid'] ?? ''),
                )
                || !\is_array($route['instances'][$instanceId] ?? null)
            ) {
                continue;
            }
            $matchedRouteIds[(string)$routeId] = true;
            $routeStatus = (string)($route['status'] ?? '');
            $instanceStatus = (string)(
                $route['instances'][$instanceId]['status'] ?? ''
            );
            if (\in_array(
                $routeStatus,
                ['STALE', 'PENDING_BACKEND', 'REMOVED'],
                true,
            ) || $instanceStatus === 'STALE') {
                $reRegisterRequired = true;
                break;
            }
        }
        \sort($expectedRouteIds, SORT_STRING);
        $matchedRouteIds = \array_keys($matchedRouteIds);
        \sort($matchedRouteIds, SORT_STRING);
        $reRegisterRequired = $reRegisterRequired
            || $expectedRouteIds === []
            || $expectedRouteIds !== $matchedRouteIds
            || !$this->registrationLeaseFullyActive($projectUuid, $instanceId);
        $response = [
            'epoch' => (string)$this->state['epoch'],
            'generation' => (int)$this->state['generation'],
            'accepted' => true,
            're_register_required' => $reRegisterRequired,
        ];
        if (!$reRegisterRequired) {
            // Stop/drain authorization is time-bound. Refresh the signed
            // committed registration lease on every accepted heartbeat so a
            // healthy long-running project never has to use an expired
            // receipt or weaken local Stop fencing.
            $response['lease_receipt'] = $this->registrationLeaseReceipt(
                $projectUuid,
                $instanceId,
            );
        } elseif ($this->drainingLeaseFullyPublished($projectUuid, $instanceId)) {
            // DRAINING is an irreversible lifecycle state, not a registration
            // replay request. Keep the exact launch's local heartbeat and
            // unregister authority alive for the complete (up to 300 second)
            // drain without making the backend ACTIVE again. The helper
            // proves that the same operation and launch are present in both
            // desired and published state before this receipt can be signed.
            $response['lease_receipt'] = $this->registrationLeaseReceipt(
                $projectUuid,
                $instanceId,
                true,
            );
        }
        return $response;
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function drain(array $payload): array
    {
        $this->assertGatewayEpochPayload($payload, 'Drain');
        $this->assertCurrentHostBootPayload($payload, 'Drain');
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        $instanceId = \trim((string)($payload['instance_id'] ?? ''));
        $instanceGeneration = (int)($payload['instance_generation'] ?? 0);
        $masterEpoch = (int)($payload['master_epoch'] ?? 0);
        $launchId = \strtolower(\trim((string)($payload['launch_id'] ?? '')));
        $drainOperationId = \strtolower(\trim((string)(
            $payload['drain_operation_id'] ?? ''
        )));
        $expectedDrainOperationId = $this->drainOperationId(
            $projectUuid,
            $instanceId,
            $instanceGeneration,
            $masterEpoch,
            $launchId,
        );
        if (!$this->validProjectUuid($projectUuid)
            || \preg_match('/\A[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}\z/D', $instanceId) !== 1
            || $instanceGeneration < 1
            || $masterEpoch < 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $launchId) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $drainOperationId) !== 1
            || !\hash_equals($expectedDrainOperationId, $drainOperationId)
        ) {
            throw new WlsEdgeProtocolException(
                'drain_operation_invalid',
                'Drain operation identity is missing or not bound to the launch fencing tuple.',
            );
        }
        $seconds = \max(1, \min(
            self::DRAIN_SECONDS,
            (int)($payload['seconds'] ?? self::DRAIN_SECONDS),
        ));
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        if (!\is_array($instance)) {
            return [
                'accepted' => true,
                'idempotent' => true,
                'already_removed' => true,
                'drain_operation_id' => $drainOperationId,
            ];
        }
        $this->assertInstanceRetirementFence(
            $projectUuid,
            $instanceId,
            (int)($instance['generation'] ?? 0),
        );
        $this->assertInstancePayloadFence($instance, $payload);
        if ((string)($instance['status'] ?? '') === 'DRAINING') {
            $storedOperationId = \strtolower(\trim((string)(
                $instance['drain_operation_id'] ?? ''
            )));
            $storedSeconds = (int)($instance['drain_seconds'] ?? 0);
            $storedStartedAt = (int)($instance['drain_started_at'] ?? 0);
            $storedStartedMonotonic = (float)(
                $instance['drain_started_monotonic'] ?? 0.0
            );
            $storedDeadline = (int)($instance['drain_until'] ?? 0);
            $storedMonotonicDeadline = (float)(
                $instance['drain_until_monotonic'] ?? 0.0
            );
            if (\preg_match('/\A[a-f0-9]{64}\z/D', $storedOperationId) !== 1
                || !\hash_equals($storedOperationId, $drainOperationId)
                || $storedSeconds < 1
                || $storedSeconds > self::DRAIN_SECONDS
                || $storedStartedAt < 1
                || !\is_finite($storedStartedMonotonic)
                || $storedStartedMonotonic <= 0.0
                || $storedDeadline !== $storedStartedAt + $storedSeconds
                || !\is_finite($storedMonotonicDeadline)
                || \abs(
                    $storedMonotonicDeadline
                        - ($storedStartedMonotonic + $storedSeconds),
                ) > 0.001
                || !$this->drainingDesiredClosureMatches(
                    $projectUuid,
                    $instanceId,
                    $drainOperationId,
                    $storedSeconds,
                    $storedStartedAt,
                    $storedStartedMonotonic,
                    $storedDeadline,
                    $storedMonotonicDeadline,
                )
            ) {
                throw new WlsEdgeProtocolException(
                    'drain_state_invalid',
                    'The irreversible drain state is malformed or belongs to another operation.',
                );
            }
            $pendingOperation = $this->pendingPublicationOperationForDrain(
                $projectUuid,
                $instanceId,
                $drainOperationId,
            );
            if ($pendingOperation !== []) {
                $this->lastQueuedOperationId = (string)$pendingOperation['operation_id'];
            }
            $result = [
                'accepted' => true,
                'idempotent' => true,
                'irreversible' => true,
                'drain_operation_id' => $drainOperationId,
                'drain_seconds' => $storedSeconds,
                'drain_until' => $storedDeadline,
            ];
            if ($pendingOperation === []
                && $this->drainingLeaseFullyPublished(
                    $projectUuid,
                    $instanceId,
                    $drainOperationId,
                )
            ) {
                $result['lease_receipt'] = $this->registrationLeaseReceipt(
                    $projectUuid,
                    $instanceId,
                    true,
                    $drainOperationId,
                );
            }
            return $result;
        }
        $this->beginRoutingMutation('drain:' . $projectUuid . ':' . $instanceId);
        try {
            $startedAt = \time();
            $startedMonotonic = $this->monotonicNow();
            $deadline = $startedAt + $seconds;
            $monotonicDeadline = $startedMonotonic + $seconds;
            $this->state['instances'][$projectUuid][$instanceId]['status'] = 'DRAINING';
            $this->state['instances'][$projectUuid][$instanceId]['drain_operation_id']
                = $drainOperationId;
            $this->state['instances'][$projectUuid][$instanceId]['drain_seconds'] = $seconds;
            $this->state['instances'][$projectUuid][$instanceId]['drain_started_at'] = $startedAt;
            $this->state['instances'][$projectUuid][$instanceId]['drain_started_monotonic']
                = $startedMonotonic;
            $this->state['instances'][$projectUuid][$instanceId]['drain_until'] = $deadline;
            $this->state['instances'][$projectUuid][$instanceId]['drain_until_monotonic']
                = $monotonicDeadline;
            $routingChanged = false;
            foreach ((array)$this->state['routes'] as $routeId => $route) {
                if (!\is_array($route)
                    || (string)$route['project_uuid'] !== $projectUuid
                    || !\is_array($route['instances'][$instanceId] ?? null)
                ) {
                    continue;
                }
                $this->state['routes'][$routeId]['instances'][$instanceId]['status'] = 'DRAINING';
                $this->state['routes'][$routeId]['instances'][$instanceId]['drain_operation_id']
                    = $drainOperationId;
                $this->state['routes'][$routeId]['instances'][$instanceId]['drain_seconds']
                    = $seconds;
                $this->state['routes'][$routeId]['instances'][$instanceId]['drain_started_at']
                    = $startedAt;
                $this->state['routes'][$routeId]['instances'][$instanceId]['drain_started_monotonic']
                    = $startedMonotonic;
                $this->state['routes'][$routeId]['instances'][$instanceId]['drain_until'] = $deadline;
                $this->state['routes'][$routeId]['instances'][$instanceId]['drain_until_monotonic']
                    = $monotonicDeadline;
                $this->selectRouteBackends($this->state['routes'][$routeId]);
                // Instance lifecycle state is part of the durable ACTIVE/LKG
                // closure even when this instance was not selected by the
                // current single-backend Nginx projection. Force publication
                // so a later rollback can never reinterpret it as ACTIVE.
                $routingChanged = true;
            }
            if (!$this->drainingDesiredClosureMatches(
                $projectUuid,
                $instanceId,
                $drainOperationId,
                $seconds,
                $startedAt,
                $startedMonotonic,
                $deadline,
                $monotonicDeadline,
            )) {
                throw new \RuntimeException(
                    'Drain mutation did not produce one exact project route closure.'
                );
            }
            $this->requestOperationResultContext = [
                'kind' => 'instance_drain',
                'project_uuid' => $projectUuid,
                'instance_id' => $instanceId,
                'drain_operation_id' => $drainOperationId,
            ];
            $this->bumpGeneration('drain', [
                'project_uuid' => $projectUuid,
                'instance_id' => $instanceId,
                'drain_operation_id' => $drainOperationId,
                'deadline' => $deadline,
            ]);
            $this->configDirty = $this->configDirty || $routingChanged;
            if ($this->configDirty && !$this->publishIfDirty()) {
                throw new \DomainException(
                    'Drain publication failed; the previous active routing state was retained.'
                );
            } else {
                $this->completePublication();
            }
            return [
                'accepted' => true,
                'idempotent' => false,
                'irreversible' => true,
                'drain_operation_id' => $drainOperationId,
                'drain_seconds' => $seconds,
                'drain_until' => $deadline,
            ];
        } catch (\Throwable $throwable) {
            $this->abortRoutingMutation(
                'Drain transaction aborted: ' . $throwable->getMessage()
            );
            throw $throwable;
        }
    }

    private function drainOperationId(
        string $projectUuid,
        string $instanceId,
        int $instanceGeneration,
        int $masterEpoch,
        string $launchId,
    ): string {
        return \hash('sha256', $this->canonicalJson([
            'operation' => 'drain',
            'project_uuid' => $projectUuid,
            'instance_id' => $instanceId,
            'instance_generation' => $instanceGeneration,
            'master_epoch' => $masterEpoch,
            'launch_id' => $launchId,
        ]));
    }

    private function drainingDesiredClosureMatches(
        string $projectUuid,
        string $instanceId,
        string $drainOperationId,
        int $seconds,
        int $startedAt,
        float $startedMonotonic,
        int $deadline,
        float $monotonicDeadline,
    ): bool {
        $project = $this->state['projects'][$projectUuid] ?? null;
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        $routeIds = \is_array($project)
            ? \array_values(\array_unique(\array_map(
                'strval',
                (array)($project['route_ids'] ?? []),
            )))
            : [];
        if (!\is_array($instance)
            || $routeIds === []
            || !\hash_equals('DRAINING', (string)($instance['status'] ?? ''))
        ) {
            return false;
        }
        foreach ($routeIds as $routeId) {
            $route = $this->state['routes'][$routeId] ?? null;
            $routeInstance = \is_array($route)
                ? ($route['instances'][$instanceId] ?? null)
                : null;
            if (!\is_array($route)
                || !\hash_equals(
                    $projectUuid,
                    (string)($route['project_uuid'] ?? ''),
                )
                || !\is_array($routeInstance)
                || !\hash_equals('DRAINING', (string)($routeInstance['status'] ?? ''))
                || !\hash_equals(
                    $drainOperationId,
                    (string)($routeInstance['drain_operation_id'] ?? ''),
                )
                || (int)($routeInstance['drain_seconds'] ?? 0) !== $seconds
                || (int)($routeInstance['drain_started_at'] ?? 0) !== $startedAt
                || (float)($routeInstance['drain_started_monotonic'] ?? 0.0)
                    !== $startedMonotonic
                || (int)($routeInstance['drain_until'] ?? 0) !== $deadline
                || (float)($routeInstance['drain_until_monotonic'] ?? 0.0)
                    !== $monotonicDeadline
                || !$this->sameLeaseBoot($routeInstance)
                || !$this->registrationInstanceFactsMatch($instance, $routeInstance)
                || isset($route['backend_instances'][$instanceId])
            ) {
                return false;
            }
        }
        return true;
    }

    /** @return array<string,mixed> */
    private function pendingPublicationOperationForDrain(
        string $projectUuid,
        string $instanceId,
        string $drainOperationId,
    ): array {
        $operations = \array_reverse((array)($this->state['operations'] ?? []), true);
        foreach ($operations as $operationId => $operation) {
            if (!\is_array($operation)) {
                continue;
            }
            $context = \is_array($operation['result_context'] ?? null)
                ? $operation['result_context']
                : [];
            if (!\in_array(
                    (string)($operation['state'] ?? ''),
                    ['PENDING_PUBLICATION', 'PREPARING', 'ACTIVATING'],
                    true,
                )
                || !\hash_equals('drain', (string)($operation['operation'] ?? ''))
                || !\hash_equals($projectUuid, (string)($operation['project_uuid'] ?? ''))
                || !\hash_equals('instance_drain', (string)($context['kind'] ?? ''))
                || !\hash_equals($instanceId, (string)($context['instance_id'] ?? ''))
                || !\hash_equals(
                    $drainOperationId,
                    (string)($context['drain_operation_id'] ?? ''),
                )
            ) {
                continue;
            }
            $operation['operation_id'] = (string)($operation['operation_id'] ?? $operationId);
            if (\preg_match('/\A[a-f0-9]{32}\z/D', (string)$operation['operation_id']) === 1) {
                return $operation;
            }
        }
        return [];
    }

    /**
     * A queued drain may reach its fixed deadline while its publication is
     * still being prepared. If that same transaction removed and durably
     * retired the exact launch, the drain objective is committed without a
     * new lifecycle receipt because no instance remains to authorize.
     *
     * @param array<string,mixed> $context
     * @return array<string,mixed>
     */
    private function committedDrainRetirementResult(array $context): array
    {
        $projectUuid = (string)($context['project_uuid'] ?? '');
        $instanceId = (string)($context['instance_id'] ?? '');
        $drainOperationId = (string)($context['drain_operation_id'] ?? '');
        if (!$this->validProjectUuid($projectUuid)
            || \preg_match(
                '/\A[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}\z/D',
                $instanceId,
            ) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $drainOperationId) !== 1
            || \is_array($this->state['instances'][$projectUuid][$instanceId] ?? null)
        ) {
            return [];
        }
        $retirement = $this->state['instance_retirements'][$projectUuid][$instanceId]
            ?? null;
        if (!\is_array($retirement)
            || !$this->validInstanceRetirementEntry(
                $retirement,
                $projectUuid,
                $instanceId,
            )
            || !\hash_equals(
                $drainOperationId,
                $this->drainOperationId(
                    $projectUuid,
                    $instanceId,
                    (int)$retirement['instance_generation'],
                    (int)$retirement['master_epoch'],
                    (string)$retirement['launch_id'],
                ),
            )
        ) {
            return [];
        }
        return [
            'drain_operation_id' => $drainOperationId,
            'already_removed' => true,
            'retired' => true,
            'instance_generation' => (int)$retirement['instance_generation'],
            'retirement_digest' => (string)$retirement['retirement_digest'],
        ];
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function unregister(array $payload): array
    {
        $this->assertGatewayEpochPayload($payload, 'Unregister');
        $this->assertCurrentHostBootPayload($payload, 'Unregister');
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        $instanceId = \trim((string)($payload['instance_id'] ?? ''));
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        if (!\is_array($instance)) {
            return ['accepted' => true, 'idempotent' => true, 'already_removed' => true];
        }
        $this->assertInstanceRetirementFence(
            $projectUuid,
            $instanceId,
            (int)($instance['generation'] ?? 0),
        );
        $this->assertInstancePayloadFence($instance, $payload);
        $this->beginRoutingMutation('unregister:' . $projectUuid . ':' . $instanceId);
        try {
            $retirement = $this->stageInstanceRetirementCandidate(
                $projectUuid,
                $instanceId,
                $instance,
            );
            $this->requestOperationResultContext = [
                'kind' => 'instance_retirement',
                'project_uuid' => $projectUuid,
                'instance_id' => $instanceId,
                'instance_generation' => (int)$retirement['instance_generation'],
                'retirement_digest' => (string)$retirement['retirement_digest'],
            ];
            unset($this->state['instances'][$projectUuid][$instanceId]);
            $routingChanged = false;
            foreach ((array)$this->state['routes'] as $routeId => $route) {
                if (\is_array($route)
                    && (string)$route['project_uuid'] === $projectUuid
                    && \is_array($route['instances'][$instanceId] ?? null)
                ) {
                    unset($this->state['routes'][$routeId]['instances'][$instanceId]);
                    $this->selectRouteBackends($this->state['routes'][$routeId]);
                    // Removing an unselected instance may leave rendered
                    // upstream bytes unchanged, but the publication/LKG must
                    // still seal the retirement generation floor.
                    $routingChanged = true;
                }
            }
            if (($this->state['instances'][$projectUuid] ?? []) === []) {
                unset($this->state['instances'][$projectUuid]);
            }
            $this->bumpGeneration('unregister', [
                'project_uuid' => $projectUuid,
                'instance_id' => $instanceId,
                'instance_generation' => (int)$retirement['instance_generation'],
                'retirement_digest' => (string)$retirement['retirement_digest'],
            ]);
            $this->configDirty = $this->configDirty || $routingChanged;
            if (!$this->configDirty) {
                // No public route referenced this instance, so the state-only
                // removal is already the committed data-plane result. Seal
                // the floor before completing the empty publication.
                $this->commitInstanceRetirementCandidates();
            }
            if ($this->configDirty && !$this->publishIfDirty()) {
                throw new \DomainException(
                    'Unregister publication failed; the previous active routing state was retained.'
                );
            } else {
                $this->completePublication();
            }
            return ['accepted' => true];
        } catch (\Throwable $throwable) {
            $this->abortRoutingMutation(
                'Unregister transaction aborted: ' . $throwable->getMessage()
            );
            throw $throwable;
        }
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function enroll(array $payload): array
    {
        if (($this->state['security_ledger_valid'] ?? true) !== true) {
            throw new \DomainException(
                'The host security ledger is untrusted; explicitly reset it before enrolling projects.'
            );
        }
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        $projectRoot = $this->canonicalDirectory((string)($payload['project_root'] ?? ''));
        if (!$this->validProjectUuid($projectUuid)) {
            throw new \DomainException('Enrollment requires a valid project UUID.');
        }
        foreach ((array)($this->state['enrollments'] ?? []) as $enrolledUuid => $enrollment) {
            if (!\is_array($enrollment)) {
                continue;
            }
            if (\hash_equals((string)($enrollment['project_root'] ?? ''), $projectRoot)
                && !\hash_equals((string)$enrolledUuid, $projectUuid)
            ) {
                throw new \DomainException(
                    'This project root is already enrolled under another project UUID.'
                );
            }
        }
        $existing = $this->state['enrollments'][$projectUuid] ?? null;
        if (\is_array($existing)
            && !\hash_equals((string)($existing['project_root'] ?? ''), $projectRoot)
        ) {
            throw new \DomainException('The project UUID is already enrolled to another project root.');
        }
        if (!\is_array($existing)
            && \count((array)($this->state['enrollments'] ?? [])) >= 128
        ) {
            throw new \DomainException('Gateway enrollment quota of 128 projects is exhausted.');
        }
        $roots = [];
        foreach ((array)($payload['certificate_roots'] ?? []) as $alias => $root) {
            $alias = \strtolower(\trim((string)$alias));
            if (\preg_match('/\A[a-z][a-z0-9_]{0,31}\z/D', $alias) !== 1) {
                throw new \DomainException(
                    'Enrollment certificate roots require explicit stable aliases.'
                );
            }
            $canonical = $this->canonicalDirectory((string)$root);
            if (!$this->pathInside($canonical, $projectRoot)) {
                throw new \DomainException('Enrollment certificate roots must stay inside the project root.');
            }
            $roots[$alias] = $canonical;
        }
        \ksort($roots, SORT_STRING);
        $defaultRoot = $this->canonicalDirectory($projectRoot . DIRECTORY_SEPARATOR
            . 'app' . DIRECTORY_SEPARATOR . 'etc' . DIRECTORY_SEPARATOR . 'ssl');
        if (!isset($roots['project_ssl'])
            || !\hash_equals($defaultRoot, (string)$roots['project_ssl'])
        ) {
            throw new \DomainException(
                'Enrollment must map project_ssl to the project app/etc/ssl directory.'
            );
        }
        $allowedDomains = [];
        foreach ((array)($payload['allowed_domains'] ?? []) as $domain) {
            $allowedDomains[] = $this->normalizeDomain((string)$domain);
        }
        $allowedDomains = \array_values(\array_unique($allowedDomains));
        \sort($allowedDomains, SORT_STRING);
        if ($allowedDomains === [] || \count($allowedDomains) > 2048) {
            throw new \DomainException('Enrollment requires 1..2048 explicitly allowed domains.');
        }
        $owner = $this->projectRootOwner($projectRoot, $payload);
        $submittedCapabilities = \is_array($payload['capabilities'] ?? null)
            ? $payload['capabilities']
            : [];
        $wireCapabilities = [];
        foreach ($submittedCapabilities as $name => $enabled) {
            if (!\is_string($name)
                || !\in_array($name, [
                    'stateless',
                    'shared_session',
                    'acme_http_01',
                    'acme_dns_01',
                ], true)
                || !\is_bool($enabled)
            ) {
                throw new \DomainException(
                    'Enrollment capability wire facts are invalid.'
                );
            }
            $wireCapabilities[$name] = $enabled;
        }
        \ksort($wireCapabilities, SORT_STRING);
        $capabilities = $this->normalizeEnrollmentCapabilities(
            $submittedCapabilities,
        );
        \ksort($capabilities, SORT_STRING);
        $wireFacts = [
            'project_uuid' => $projectUuid,
            'project_root' => $projectRoot,
            'certificate_roots' => $roots,
            'allowed_domains' => $allowedDomains,
            'capabilities' => $wireCapabilities,
        ];
        if (\array_key_exists('project_owner_uid', $payload)
            || \array_key_exists('project_owner_gid', $payload)
        ) {
            if ((string)($owner['kind'] ?? '') !== 'posix'
                || !\is_int($payload['project_owner_uid'] ?? null)
                || !\is_int($payload['project_owner_gid'] ?? null)
                || (int)$payload['project_owner_uid'] !== (int)($owner['uid'] ?? -1)
                || (int)$payload['project_owner_gid'] !== (int)($owner['gid'] ?? -1)
            ) {
                throw new \DomainException(
                    'Enrollment POSIX owner proof does not match the authenticated project root.'
                );
            }
            $wireFacts['project_owner_uid'] = (int)$payload['project_owner_uid'];
            $wireFacts['project_owner_gid'] = (int)$payload['project_owner_gid'];
        }
        $clientRequestDigest = \hash('sha256', $this->canonicalJson($wireFacts));
        $desired = [
            'project_uuid' => $projectUuid,
            'project_root' => $projectRoot,
            'certificate_roots' => $roots,
            'allowed_domains' => $allowedDomains,
            'owner' => $owner,
            'capabilities' => $capabilities,
        ];
        $desiredDigest = \hash('sha256', $this->canonicalJson($desired));
        $submittedDigest = \strtolower(\trim((string)($payload['request_digest'] ?? '')));
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $submittedDigest) !== 1
            || !\hash_equals($clientRequestDigest, $submittedDigest)
        ) {
            throw new \DomainException('Enrollment client request digest is invalid.');
        }
        $authenticatedPeerDigest = \hash(
            'sha256',
            $this->canonicalJson($owner),
        );
        $idempotencyKey = \strtolower(\trim((string)(
            $payload['idempotency_key'] ?? ''
        )));
        $expectedIdempotencyKey = \substr(\hash(
            'sha256',
            $projectUuid . ':enroll:' . $clientRequestDigest,
        ), 0, 40);
        if (\preg_match('/\A[a-f0-9]{40}\z/D', $idempotencyKey) !== 1
            || !\hash_equals($expectedIdempotencyKey, $idempotencyKey)
        ) {
            throw new \DomainException('Enrollment idempotency key is invalid.');
        }

        $transactions = (array)($this->state['enrollment_transactions'] ?? []);
        $transaction = null;
        $transactionId = '';
        foreach ($transactions as $candidateId => $candidateTransaction) {
            if (!\is_array($candidateTransaction)) {
                continue;
            }
            $sameKey = \hash_equals(
                $idempotencyKey,
                (string)($candidateTransaction['idempotency_key'] ?? ''),
            );
            $sameDesiredEnrollment = \hash_equals(
                $projectUuid,
                (string)($candidateTransaction['project_uuid'] ?? ''),
            ) && \hash_equals(
                $clientRequestDigest,
                (string)($candidateTransaction['request_digest'] ?? ''),
            ) && \hash_equals(
                $desiredDigest,
                (string)($candidateTransaction['authenticated_desired_digest'] ?? ''),
            ) && \hash_equals(
                $authenticatedPeerDigest,
                (string)($candidateTransaction['authenticated_peer_digest'] ?? ''),
            );
            if (!$sameKey && !$sameDesiredEnrollment) {
                continue;
            }
            if (!$sameDesiredEnrollment) {
                throw new \DomainException(
                    'Enrollment idempotency key was already used for different desired state.'
                );
            }
            $transactionId = (string)$candidateId;
            $transaction = $candidateTransaction;
            break;
        }
        if (\is_array($existing)
            && \hash_equals($desiredDigest, (string)($existing['desired_digest'] ?? ''))
        ) {
            $existingTransactionId = (string)(
                $existing['enrollment_transaction_id'] ?? ''
            );
            $existingTransaction = $transactions[$existingTransactionId] ?? null;
            if (\is_array($existingTransaction)
                && \hash_equals(
                    'COMMITTED',
                    (string)($existingTransaction['phase'] ?? ''),
                )
                && \hash_equals(
                    $clientRequestDigest,
                    (string)($existingTransaction['request_digest'] ?? ''),
                )
                && \hash_equals(
                    $authenticatedPeerDigest,
                    (string)($existingTransaction['authenticated_peer_digest'] ?? ''),
                )
            ) {
                return $this->enrollmentResponse($existingTransaction, true);
            }
        }
        if ($transaction === null) {
            if (\count($transactions) >= self::MAX_ENROLLMENT_TRANSACTIONS) {
                throw new \DomainException(
                    'Gateway enrollment transaction quota is exhausted; repair is required.'
                );
            }
            $transactionId = \bin2hex(\random_bytes(16));
            $issuedAt = \gmdate(DATE_ATOM);
            $transaction = [
                'schema_version' => 1,
                'transaction_id' => $transactionId,
                'idempotency_key' => $idempotencyKey,
                'request_digest' => $clientRequestDigest,
                'authenticated_desired_digest' => $desiredDigest,
                'authenticated_peer_digest' => $authenticatedPeerDigest,
                'project_uuid' => $projectUuid,
                'project_root' => $projectRoot,
                'certificate_roots' => $roots,
                'allowed_domains' => $allowedDomains,
                'domains_digest' => \hash(
                    'sha256',
                    $this->canonicalJson($allowedDomains),
                ),
                'capabilities' => $capabilities,
                'capabilities_digest' => \hash(
                    'sha256',
                    $this->canonicalJson($wireCapabilities),
                ),
                'owner' => $owner,
                // Native AUTH_PREPARE is the sole production allocator. Zero
                // records that no host security generation has been granted
                // yet; replaying this tx/intent returns the same allocation.
                'security_generation' => 0,
                'root_attestations' => [],
                'credential_generation' => (int)(
                    $existing['credential_generation'] ?? 0
                ) + 1,
                'credential_id' => \bin2hex(\random_bytes(16)),
                'credential_secret' => \bin2hex(\random_bytes(32)),
                'credential_issued_at' => $issuedAt,
                'phase' => 'PREPARED',
                'created_at' => $issuedAt,
                'updated_at' => $issuedAt,
            ];
            $this->state['enrollment_transactions'][$transactionId] = $transaction;
            // PREPARED must exist in the authoritative security ledger before
            // Native AUTH_PREPARE can allocate. Otherwise state.json loss
            // after a durable H/P append would orphan the Broker transaction.
            $this->persistSecurityLedger();
            $this->persistState();
            if (!$this->journal('enrollment_prepared', [
                'transaction_id' => $transactionId,
                'project_uuid' => $projectUuid,
                'security_generation' => 0,
                'request_digest' => $clientRequestDigest,
                'client_request_digest' => $clientRequestDigest,
                'authenticated_desired_digest' => $desiredDigest,
                'authenticated_peer_digest' => $authenticatedPeerDigest,
            ])) {
                throw new \RuntimeException(
                    'Enrollment PREPARED state could not be audited.'
                );
            }
        }

        $phase = (string)($transaction['phase'] ?? '');
        if ($phase === 'ABORTED') {
            throw new \DomainException(
                'The enrollment transaction was aborted and cannot be reused.'
            );
        }
        if ($phase === 'ABORT_PENDING') {
            try {
                $abortedGeneration = $this->abortBrokerCertificateRoots(
                    $transactionId,
                    $projectUuid,
                    $desiredDigest,
                );
            } catch (\Throwable $abortFailure) {
                throw new \RuntimeException(
                    'Enrollment Native abort is still pending recovery: '
                        . $abortFailure->getMessage(),
                    0,
                    $abortFailure,
                );
            }
            if ($abortedGeneration > 0) {
                $this->state['enrollment_transactions'][$transactionId]
                    ['security_generation'] = $abortedGeneration;
            }
            $this->state['enrollment_transactions'][$transactionId]['phase'] = 'ABORTED';
            $this->state['enrollment_transactions'][$transactionId]['updated_at']
                = \gmdate(DATE_ATOM);
            $this->persistSecurityLedger();
            $this->persistState();
            throw new \DomainException(
                'The enrollment transaction was aborted during recovery and cannot be reused.'
            );
        }
        if ($phase === 'COMMITTED') {
            return $this->enrollmentResponse($transaction, true);
        }
        $securityGeneration = (int)($transaction['security_generation'] ?? 0);
        if ($phase === 'PREPARED') {
            try {
                $authorization = $this->prepareBrokerCertificateRoots(
                    $transactionId,
                    $projectUuid,
                    $desiredDigest,
                    (int)($this->state['security_committed_high_water'] ?? 0),
                    $projectRoot,
                    $roots,
                    $owner,
                );
                $securityGeneration = (int)$authorization['assigned_generation'];
                if ($securityGeneration < 1) {
                    throw new \RuntimeException(
                        'Enrollment security generation was not allocated.'
                    );
                }
                $this->state['security_generation_high_water'] = \max(
                    (int)($this->state['security_generation_high_water'] ?? 0),
                    $securityGeneration,
                );
                $this->state['enrollment_transactions'][$transactionId]['security_generation']
                    = $securityGeneration;
                $this->state['enrollment_transactions'][$transactionId]['root_attestations']
                    = (array)$authorization['root_attestations'];
                $this->state['enrollment_transactions'][$transactionId]['updated_at']
                    = \gmdate(DATE_ATOM);
                $this->persistState();
                $transaction = (array)$this->state['enrollment_transactions'][$transactionId];
            } catch (\Throwable $throwable) {
                $abortFailure = null;
                try {
                    $abortedGeneration = $this->abortBrokerCertificateRoots(
                        $transactionId,
                        $projectUuid,
                        $desiredDigest,
                    );
                    if ($abortedGeneration > 0) {
                        $this->state['enrollment_transactions'][$transactionId]
                            ['security_generation'] = $abortedGeneration;
                    }
                } catch (\Throwable $nativeAbortFailure) {
                    $abortFailure = $nativeAbortFailure;
                }
                $this->state['enrollment_transactions'][$transactionId]['phase']
                    = $abortFailure === null ? 'ABORTED' : 'ABORT_PENDING';
                $this->state['enrollment_transactions'][$transactionId]['updated_at']
                    = \gmdate(DATE_ATOM);
                $this->state['enrollment_transactions'][$transactionId]['error']
                    = $throwable->getMessage()
                        . ($abortFailure !== null
                            ? ' Native abort pending: ' . $abortFailure->getMessage()
                            : '');
                // AUTH_ABORT never rolls back Native's allocation. Anchor the
                // observed high-water and the ABORTED tx so a host-state
                // rollback cannot reuse that generation.
                $this->persistSecurityLedger();
                $this->persistState();
                $this->journal(
                    $abortFailure === null
                        ? 'enrollment_aborted'
                        : 'enrollment_abort_pending',
                    [
                    'transaction_id' => $transactionId,
                    'project_uuid' => $projectUuid,
                    'reason' => $throwable->getMessage(),
                    ],
                );
                if ($abortFailure !== null) {
                    throw new \RuntimeException(
                        'Enrollment failed and Native abort requires recovery: '
                            . $abortFailure->getMessage(),
                        0,
                        $throwable,
                    );
                }
                throw $throwable;
            }
            $newEnrollment = [
                'project_uuid' => $projectUuid,
                'project_root' => $projectRoot,
                'certificate_roots' => $roots,
                'allowed_domains' => $allowedDomains,
                'owner' => $owner,
                'credential_id' => (string)$transaction['credential_id'],
                'credential_secret' => (string)$transaction['credential_secret'],
                'credential_generation' => (int)$transaction['credential_generation'],
                'security_generation' => $securityGeneration,
                'capabilities' => $capabilities,
                'desired_digest' => $desiredDigest,
                'client_request_digest' => $clientRequestDigest,
                'authenticated_peer_digest' => $authenticatedPeerDigest,
                'enrollment_transaction_id' => $transactionId,
                'native_authorization_transaction_id' => $transactionId,
                'native_authorization_intent_digest' => $desiredDigest,
                'credential_issued_at' => (string)$transaction['credential_issued_at'],
                'enrolled_at' => (string)(
                    $existing['enrolled_at'] ?? $transaction['created_at']
                ),
                'updated_at' => \gmdate(DATE_ATOM),
            ];
            $this->state['enrollments'][$projectUuid] = $newEnrollment;
            $this->state['enrollment_transactions'][$transactionId]['phase']
                = 'LEDGER_COMMITTED';
            $this->state['enrollment_transactions'][$transactionId]['updated_at']
                = \gmdate(DATE_ATOM);
            $this->persistSecurityLedger();
            $this->persistState();
            $phase = 'LEDGER_COMMITTED';
        }
        if ($phase === 'LEDGER_COMMITTED') {
            $ledgerDigest = $this->fileHash($this->securityLedgerFile());
            if ($ledgerDigest === '') {
                throw new \RuntimeException(
                    'Committed enrollment security ledger digest is unavailable.'
                );
            }
            $this->commitBrokerCertificateRoots(
                $transactionId,
                $projectUuid,
                $desiredDigest,
                $securityGeneration,
                (array)($transaction['root_attestations'] ?? []),
            );
            $this->bindBrokerEmergencyCredential(
                $transactionId,
                $projectUuid,
                $desiredDigest,
                $securityGeneration,
                (array)($transaction['owner'] ?? []),
                (string)($transaction['credential_id'] ?? ''),
                (int)($transaction['credential_generation'] ?? 0),
                (string)($transaction['credential_secret'] ?? ''),
            );
            $this->state['security_committed_high_water'] = \max(
                (int)($this->state['security_committed_high_water'] ?? 0),
                $securityGeneration,
            );
            $this->state['enrollment_transactions'][$transactionId]['phase']
                = 'BROKER_COMMITTED';
            $this->state['enrollment_transactions'][$transactionId]['updated_at']
                = \gmdate(DATE_ATOM);
            $this->persistState();
            $phase = 'BROKER_COMMITTED';
        }
        if ($phase === 'BROKER_COMMITTED') {
            $committedAt = \gmdate(DATE_ATOM);
            $this->state['enrollment_transactions'][$transactionId]['phase'] = 'COMMITTED';
            $this->state['enrollment_transactions'][$transactionId]['committed_at']
                = $committedAt;
            $this->state['enrollment_transactions'][$transactionId]['updated_at']
                = $committedAt;
            $this->persistSecurityLedger();
            $this->bumpGeneration('enroll', [
                'transaction_id' => $transactionId,
                'project_uuid' => $projectUuid,
                'credential_id' => (string)$transaction['credential_id'],
                'allowed_domains' => $allowedDomains,
                'security_generation' => $securityGeneration,
            ]);
        }
        return $this->enrollmentResponse(
            (array)$this->state['enrollment_transactions'][$transactionId],
            false,
        );
    }

    /** @param array<string,mixed> $transaction */
    private function enrollmentResponse(array $transaction, bool $idempotent): array
    {
        if (!\hash_equals('COMMITTED', (string)($transaction['phase'] ?? ''))) {
            throw new \RuntimeException('Enrollment credential is not committed.');
        }
        $secret = (string)($transaction['credential_secret'] ?? '');
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $secret) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['request_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['authenticated_desired_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($transaction['authenticated_peer_digest'] ?? ''),
            ) !== 1
        ) {
            throw new \RuntimeException('Committed enrollment credential is unavailable.');
        }
        $receipt = [
            'schema_version' => 1,
            'protocol' => self::PROTOCOL,
            'host_id' => $this->hostId(),
            'gateway_epoch' => (string)$this->state['epoch'],
            'tx_id' => (string)$transaction['transaction_id'],
            'project_uuid' => (string)$transaction['project_uuid'],
            'security_generation' => (int)$transaction['security_generation'],
            'credential_generation' => (int)$transaction['credential_generation'],
            'credential_id' => (string)$transaction['credential_id'],
            'domains_digest' => (string)$transaction['domains_digest'],
            'capabilities_digest' => (string)$transaction['capabilities_digest'],
            'request_digest' => (string)$transaction['request_digest'],
            'authenticated_desired_digest' => (string)(
                $transaction['authenticated_desired_digest'] ?? ''
            ),
            'idempotency_key' => (string)$transaction['idempotency_key'],
            'state' => 'COMMITTED',
            'issued_at' => (string)(
                $transaction['committed_at'] ?? $transaction['updated_at'] ?? ''
            ),
        ];
        $receipt['signature'] = \hash_hmac(
            'sha256',
            $this->canonicalJson($receipt),
            $secret,
        );
        return [
            'accepted' => true,
            'idempotent' => $idempotent,
            'project_uuid' => (string)$transaction['project_uuid'],
            'security_generation' => (int)$transaction['security_generation'],
            'credential_generation' => (int)$transaction['credential_generation'],
            'credential_receipt' => $receipt,
            'credential' => [
                'schema_version' => 1,
                'protocol' => self::PROTOCOL,
                'host_id' => $this->hostId(),
                'project_uuid' => (string)$transaction['project_uuid'],
                'credential_id' => (string)$transaction['credential_id'],
                'credential_generation' => (int)$transaction['credential_generation'],
                'secret' => $secret,
                'issued_at' => (string)$transaction['credential_issued_at'],
            ],
        ];
    }

    /** @param array<string,mixed> $payload @return array<string,mixed> */
    private function prepareProjectIdentityRotation(array $payload): array
    {
        if ($this->publication !== null) {
            throw new \DomainException(
                'Project identity rotation requires an idle publication pipeline.'
            );
        }
        $facts = $this->projectIdentityRotationFacts($payload);
        $oldUuid = (string)$facts['old_project_uuid'];
        $newUuid = (string)$facts['new_project_uuid'];
        $rotationId = (string)$facts['rotation_id'];
        $authenticated = (string)($payload['_authenticated_project_uuid'] ?? '');
        if (!\hash_equals($oldUuid, $authenticated)
            || !\hash_equals($oldUuid, (string)($payload['project_uuid'] ?? ''))
        ) {
            throw new \DomainException(
                'Rotation prepare must use the old project credential and OS peer.'
            );
        }
        $requestDigest = \strtolower(\trim((string)($payload['request_digest'] ?? '')));
        $expectedDigest = \hash('sha256', $this->canonicalJson($facts));
        $idempotencyKey = \strtolower(\trim((string)(
            $payload['idempotency_key'] ?? ''
        )));
        $expectedIdempotency = \substr(\hash(
            'sha256',
            $oldUuid . ':rotate:' . $newUuid . ':' . $expectedDigest,
        ), 0, 40);
        if (!\hash_equals($expectedDigest, $requestDigest)
            || !\hash_equals($expectedIdempotency, $idempotencyKey)
        ) {
            throw new \DomainException(
                'Project identity rotation digest or idempotency fence is invalid.'
            );
        }
        $oldEnrollment = $this->state['enrollments'][$oldUuid] ?? null;
        if (!\is_array($oldEnrollment)
            || !\hash_equals(
                (string)$facts['project_root'],
                (string)($oldEnrollment['project_root'] ?? ''),
            )
        ) {
            throw new \DomainException(
                'Old project enrollment does not match the rotation root.'
            );
        }

        $transaction = $this->state['rotation_transactions'][$rotationId] ?? null;
        if (\is_array($transaction)) {
            $this->assertSameProjectIdentityRotation(
                $transaction,
                $facts,
                $requestDigest,
                $idempotencyKey,
            );
            if (\hash_equals('ABORTED', (string)($transaction['phase'] ?? ''))) {
                throw new \DomainException(
                    'The project identity rotation was aborted and cannot be reused.'
                );
            }
        } else {
            if (\count((array)($this->state['rotation_transactions'] ?? []))
                >= self::MAX_ROTATION_TRANSACTIONS
            ) {
                throw new \DomainException(
                    'Gateway project identity rotation quota is exhausted; repair is required.'
                );
            }
            if (\is_array($this->state['enrollments'][$newUuid] ?? null)
                || \is_array($this->state['projects'][$newUuid] ?? null)
                || \is_array(
                    $this->state['security']['tombstones']['project:' . $newUuid] ?? null
                )
            ) {
                throw new \DomainException(
                    'The target project UUID is already used or security-fenced.'
                );
            }
            foreach ((array)($this->state['rotation_transactions'] ?? []) as $candidate) {
                if (!\is_array($candidate)
                    || \in_array(
                        (string)($candidate['phase'] ?? ''),
                        ['ABORTED', 'FINALIZED'],
                        true,
                    )
                ) {
                    continue;
                }
                if (\in_array($oldUuid, [
                        (string)($candidate['old_project_uuid'] ?? ''),
                        (string)($candidate['new_project_uuid'] ?? ''),
                    ], true)
                    || \in_array($newUuid, [
                        (string)($candidate['old_project_uuid'] ?? ''),
                        (string)($candidate['new_project_uuid'] ?? ''),
                    ], true)
                ) {
                    throw new \DomainException(
                        'A project identity is already participating in another rotation.'
                    );
                }
            }
            foreach ((array)($this->state['transfers'] ?? []) as $transfer) {
                if (\is_array($transfer)
                    && !\in_array(
                        (string)($transfer['status'] ?? ''),
                        ['ABORTED', 'COMMITTED'],
                        true,
                    )
                    && \in_array($oldUuid, [
                        (string)($transfer['from_project_uuid'] ?? ''),
                        (string)($transfer['to_project_uuid'] ?? ''),
                    ], true)
                ) {
                    throw new \DomainException(
                        'Project identity rotation conflicts with an active domain transfer.'
                    );
                }
            }
            $issuedAt = \gmdate(DATE_ATOM);
            $transaction = [
                'schema_version' => 1,
                ...$facts,
                'request_digest' => $requestDigest,
                'idempotency_key' => $idempotencyKey,
                'owner' => (array)($oldEnrollment['owner'] ?? []),
                'old_enrollment_snapshot' => $oldEnrollment,
                'old_project_snapshot' => \is_array(
                    $this->state['projects'][$oldUuid] ?? null
                ) ? $this->state['projects'][$oldUuid] : [],
                'old_credential_id' => (string)(
                    $oldEnrollment['credential_id'] ?? ''
                ),
                'new_credential_id' => \bin2hex(\random_bytes(16)),
                'new_credential_secret' => \bin2hex(\random_bytes(32)),
                'new_credential_generation' => (int)(
                    $oldEnrollment['credential_generation'] ?? 0
                ) + 1,
                'security_generation' => 0,
                'native_registry_digest' => '',
                'native_tombstone_digest' => '',
                'phase' => 'PREPARED',
                'created_at' => $issuedAt,
                'updated_at' => $issuedAt,
            ];
            $this->state['rotation_transactions'][$rotationId] = $transaction;
            $this->persistSecurityLedger();
            $this->persistState();
            $this->journal('project_rotation_prepared', [
                'rotation_id' => $rotationId,
                'old_project_uuid' => $oldUuid,
                'new_project_uuid' => $newUuid,
                'request_digest' => $requestDigest,
            ]);
        }

        if (\hash_equals('PREPARED', (string)($transaction['phase'] ?? ''))) {
            $native = $this->prepareNativeProjectIdentityRotation($transaction);
            $this->state['rotation_transactions'][$rotationId]['security_generation']
                = (int)$native['assigned'];
            $this->state['rotation_transactions'][$rotationId]['native_registry_digest']
                = (string)$native['registry_digest'];
            $this->state['rotation_transactions'][$rotationId]['phase']
                = 'NATIVE_PREPARED';
            $this->state['rotation_transactions'][$rotationId]['updated_at']
                = \gmdate(DATE_ATOM);
            $this->state['security_generation_high_water'] = \max(
                (int)($this->state['security_generation_high_water'] ?? 0),
                (int)$native['assigned'],
            );
            $this->persistSecurityLedger();
            $this->persistState();
            $transaction = (array)$this->state['rotation_transactions'][$rotationId];
        }
        return $this->projectIdentityRotationResponse($transaction, true, true);
    }

    /** @param array<string,mixed> $payload @return array<string,mixed> */
    private function commitProjectIdentityRotation(array $payload): array
    {
        $transaction = $this->projectIdentityRotationTransactionForRequest($payload);
        $phase = (string)($transaction['phase'] ?? '');
        $oldUuid = (string)$transaction['old_project_uuid'];
        if (!\hash_equals(
            $oldUuid,
            (string)($payload['_authenticated_project_uuid'] ?? ''),
        )) {
            throw new \DomainException(
                'Rotation commit must use the old project credential.'
            );
        }
        if ($phase === 'ABORTED') {
            throw new \DomainException('An aborted project identity rotation cannot commit.');
        }
        $newCredentialId = \strtolower(\trim((string)(
            $payload['new_credential_id'] ?? ''
        )));
        $newProof = \strtolower(\trim((string)($payload['new_proof'] ?? '')));
        $proofFacts = $this->projectIdentityRotationCommitFacts($transaction);
        $expectedProof = \hash_hmac(
            'sha256',
            $this->canonicalJson($proofFacts),
            (string)$transaction['new_credential_secret'],
        );
        if (!\hash_equals(
                (string)$transaction['new_credential_id'],
                $newCredentialId,
            )
            || \preg_match('/\A[a-f0-9]{64}\z/D', $newProof) !== 1
            || !\hash_equals($expectedProof, $newProof)
        ) {
            throw new \DomainException(
                'Rotation commit requires proof of both old and pending new credentials.'
            );
        }
        if ($phase === 'PREPARED') {
            $native = $this->prepareNativeProjectIdentityRotation($transaction);
            $this->state['rotation_transactions'][$transaction['rotation_id']]
                ['security_generation'] = (int)$native['assigned'];
            $this->state['rotation_transactions'][$transaction['rotation_id']]
                ['native_registry_digest'] = (string)$native['registry_digest'];
            $this->state['rotation_transactions'][$transaction['rotation_id']]['phase']
                = 'NATIVE_PREPARED';
            $this->state['security_generation_high_water'] = \max(
                (int)($this->state['security_generation_high_water'] ?? 0),
                (int)$native['assigned'],
            );
            $phase = 'NATIVE_PREPARED';
        }
        if ($phase === 'NATIVE_PREPARED') {
            $rotationId = (string)$transaction['rotation_id'];
            $this->state['rotation_transactions'][$rotationId]['commit_proof_digest']
                = \hash('sha256', $newProof);
            $this->state['rotation_transactions'][$rotationId]['commit_authorized_at']
                = \gmdate(DATE_ATOM);
            $this->state['rotation_transactions'][$rotationId]['phase']
                = 'LEDGER_COMMITTED';
            $this->state['rotation_transactions'][$rotationId]['updated_at']
                = \gmdate(DATE_ATOM);
            $this->persistSecurityLedger();
            $this->persistState();
            $phase = 'LEDGER_COMMITTED';
        }
        if ($phase === 'LEDGER_COMMITTED') {
            $this->commitNativeProjectIdentityRotation(
                (array)$this->state['rotation_transactions'][$transaction['rotation_id']],
            );
            $phase = (string)$this->state['rotation_transactions']
                [$transaction['rotation_id']]['phase'];
        }
        if ($phase === 'BROKER_COMMITTED') {
            $this->applyCommittedProjectIdentityRotation(
                (string)$transaction['rotation_id'],
            );
        }
        $transaction = (array)$this->state['rotation_transactions']
            [$transaction['rotation_id']];
        if (!\in_array(
            (string)($transaction['phase'] ?? ''),
            ['CONTROLLER_COMMITTED', 'FINALIZED'],
            true,
        )) {
            throw new \RuntimeException(
                'Project identity rotation has not reached Controller COMMITTED state.'
            );
        }
        return $this->projectIdentityRotationResponse($transaction, false, false);
    }

    /** @param array<string,mixed> $payload @return array<string,mixed> */
    private function projectIdentityRotationStatus(array $payload): array
    {
        $transaction = $this->projectIdentityRotationTransactionForRequest($payload);
        $principal = (string)($payload['_authenticated_project_uuid'] ?? '');
        if (!\in_array($principal, [
            (string)$transaction['old_project_uuid'],
            (string)$transaction['new_project_uuid'],
        ], true)) {
            throw new \DomainException('Project identity rotation belongs to another project.');
        }
        if (\in_array(
            (string)($transaction['phase'] ?? ''),
            ['PREPARED', 'NATIVE_PREPARED'],
            true,
        )) {
            $transaction = $this->reconcilePreparedProjectIdentityRotation(
                $transaction,
            );
        }
        if (\hash_equals('ABORTED', (string)($transaction['phase'] ?? ''))) {
            return ['accepted' => true, 'idempotent' => true, 'state' => 'ABORTED'];
        }
        return $this->projectIdentityRotationResponse($transaction, true, false);
    }

    /** @param array<string,mixed> $payload @return array<string,mixed> */
    private function finalizeProjectIdentityRotation(array $payload): array
    {
        $transaction = $this->projectIdentityRotationTransactionForRequest($payload);
        $rotationId = (string)$transaction['rotation_id'];
        $newUuid = (string)$transaction['new_project_uuid'];
        $oldUuid = (string)$transaction['old_project_uuid'];
        if (!\hash_equals(
            $newUuid,
            (string)($payload['_authenticated_project_uuid'] ?? ''),
        )) {
            throw new \DomainException(
                'Rotation finalize requires the committed new project credential.'
            );
        }
        $phase = (string)($transaction['phase'] ?? '');
        if ($phase === 'FINALIZED') {
            return $this->projectIdentityRotationResponse($transaction, true, false);
        }
        if ($phase !== 'CONTROLLER_COMMITTED') {
            throw new \DomainException(
                'Project identity rotation cannot finalize before Controller commit.'
            );
        }
        unset($this->state['enrollments'][$oldUuid]);
        unset(
            $this->state['enrollments'][$newUuid]['rotation_role'],
            $this->state['enrollments'][$newUuid]['rotation_id'],
        );
        $this->state['rotation_transactions'][$rotationId]['phase'] = 'FINALIZED';
        $this->state['rotation_transactions'][$rotationId]['finalized_at']
            = \gmdate(DATE_ATOM);
        $this->state['rotation_transactions'][$rotationId]['updated_at']
            = \gmdate(DATE_ATOM);
        unset(
            $this->state['rotation_transactions'][$rotationId]
                ['new_credential_secret'],
            $this->state['rotation_transactions'][$rotationId]
                ['old_enrollment_snapshot'],
            $this->state['rotation_transactions'][$rotationId]
                ['old_project_snapshot'],
        );
        $this->persistSecurityLedger();
        $this->persistState();
        $this->journal('project_rotation_finalized', [
            'rotation_id' => $rotationId,
            'old_project_uuid' => $oldUuid,
            'new_project_uuid' => $newUuid,
        ]);
        return $this->projectIdentityRotationResponse(
            (array)$this->state['rotation_transactions'][$rotationId],
            false,
            false,
        );
    }

    /** @param array<string,mixed> $payload @return array<string,mixed> */
    private function abortProjectIdentityRotation(array $payload): array
    {
        $rotationId = \strtolower(\trim((string)($payload['rotation_id'] ?? '')));
        $stored = $this->state['rotation_transactions'][$rotationId] ?? null;
        if (!\is_array($stored)) {
            $facts = $this->projectIdentityRotationFacts($payload);
            $oldUuid = (string)$facts['old_project_uuid'];
            $requestDigest = \strtolower(\trim((string)(
                $payload['request_digest'] ?? ''
            )));
            $expectedDigest = \hash('sha256', $this->canonicalJson($facts));
            $idempotencyKey = \strtolower(\trim((string)(
                $payload['idempotency_key'] ?? ''
            )));
            $expectedIdempotency = \substr(\hash(
                'sha256',
                $oldUuid . ':rotate:' . (string)$facts['new_project_uuid']
                    . ':' . $expectedDigest,
            ), 0, 40);
            if (!\hash_equals(
                    $oldUuid,
                    (string)($payload['_authenticated_project_uuid'] ?? ''),
                )
                || !\hash_equals($oldUuid, (string)($payload['project_uuid'] ?? ''))
                || !\hash_equals($expectedDigest, $requestDigest)
                || !\hash_equals($expectedIdempotency, $idempotencyKey)
            ) {
                throw new \DomainException(
                    'Absent rotation abort facts or old-identity proof are invalid.'
                );
            }
            return ['accepted' => true, 'idempotent' => true, 'state' => 'ABORTED'];
        }
        $transaction = $this->projectIdentityRotationTransactionForRequest($payload);
        $rotationId = (string)$transaction['rotation_id'];
        if (!\hash_equals(
            (string)$transaction['old_project_uuid'],
            (string)($payload['_authenticated_project_uuid'] ?? ''),
        )) {
            throw new \DomainException(
                'Rotation abort requires the old project credential.'
            );
        }
        $phase = (string)($transaction['phase'] ?? '');
        if ($phase === 'ABORTED') {
            return ['accepted' => true, 'idempotent' => true, 'state' => 'ABORTED'];
        }
        if (!\in_array($phase, ['PREPARED', 'NATIVE_PREPARED'], true)) {
            throw new \DomainException(
                'Ledger-committed project identity rotation can only roll forward.'
            );
        }
        $transaction = $this->reconcilePreparedProjectIdentityRotation($transaction);
        if (\hash_equals('ABORTED', (string)($transaction['phase'] ?? ''))) {
            return ['accepted' => true, 'idempotent' => true, 'state' => 'ABORTED'];
        }
        $abortReceipt = $this->abortNativeProjectIdentityRotation($transaction);
        if ((int)$abortReceipt['assigned'] > 0) {
            $this->state['rotation_transactions'][$rotationId]['security_generation']
                = (int)$abortReceipt['assigned'];
            $this->state['rotation_transactions'][$rotationId]['native_registry_digest']
                = (string)$abortReceipt['registry_digest'];
        }
        $this->state['rotation_transactions'][$rotationId]['phase'] = 'ABORTED';
        $this->state['rotation_transactions'][$rotationId]['aborted_at']
            = \gmdate(DATE_ATOM);
        $this->state['rotation_transactions'][$rotationId]['updated_at']
            = \gmdate(DATE_ATOM);
        unset(
            $this->state['rotation_transactions'][$rotationId]
                ['new_credential_secret'],
            $this->state['rotation_transactions'][$rotationId]
                ['old_enrollment_snapshot'],
            $this->state['rotation_transactions'][$rotationId]
                ['old_project_snapshot'],
        );
        $this->persistSecurityLedger();
        $this->persistState();
        $this->journal('project_rotation_aborted', ['rotation_id' => $rotationId]);
        return ['accepted' => true, 'idempotent' => false, 'state' => 'ABORTED'];
    }

    /**
     * Recover the Native PREPARE outcome that may have become durable before
     * the Controller received or persisted its acknowledgement.
     *
     * @param array<string,mixed> $transaction
     * @return array<string,mixed>
     */
    private function reconcilePreparedProjectIdentityRotation(
        array $transaction,
    ): array {
        $phase = (string)($transaction['phase'] ?? '');
        if (!\in_array($phase, ['PREPARED', 'NATIVE_PREPARED'], true)) {
            return $transaction;
        }
        $attestation = $this->attestNativeProjectIdentityRotationState($transaction);
        $nativeState = (string)$attestation['state'];
        $rotationId = (string)$transaction['rotation_id'];
        if ($nativeState === 'UNKNOWN') {
            if ($phase === 'NATIVE_PREPARED') {
                $reason = 'Native rotation reservation disappeared after Controller '
                    . 'acknowledgement.';
                $this->failClosedSecurityMutation($reason, true);
                throw new \RuntimeException($reason . ' Gateway stopped fail-closed.');
            }
            return $transaction;
        }
        if ($nativeState === 'COMMITTED') {
            $reason = 'Native rotation is committed while the Controller ledger is '
                . 'pre-commit; commit authorization cannot be proven.';
            $this->failClosedSecurityMutation($reason, true);
            throw new \RuntimeException($reason . ' Gateway stopped fail-closed.');
        }
        $this->state['rotation_transactions'][$rotationId]['security_generation']
            = (int)$attestation['assigned'];
        $this->state['rotation_transactions'][$rotationId]['native_registry_digest']
            = (string)$attestation['registry_digest'];
        $this->state['security_generation_high_water'] = \max(
            (int)($this->state['security_generation_high_water'] ?? 0),
            (int)$attestation['assigned'],
        );
        $now = \gmdate(DATE_ATOM);
        if ($nativeState === 'ABORTED') {
            $this->state['rotation_transactions'][$rotationId]['phase'] = 'ABORTED';
            $this->state['rotation_transactions'][$rotationId]['aborted_at'] = $now;
            unset(
                $this->state['rotation_transactions'][$rotationId]
                    ['new_credential_secret'],
                $this->state['rotation_transactions'][$rotationId]
                    ['old_enrollment_snapshot'],
                $this->state['rotation_transactions'][$rotationId]
                    ['old_project_snapshot'],
            );
        } else {
            $this->state['rotation_transactions'][$rotationId]['phase']
                = 'NATIVE_PREPARED';
        }
        $this->state['rotation_transactions'][$rotationId]['updated_at'] = $now;
        $this->persistSecurityLedger();
        $this->persistState();
        return (array)$this->state['rotation_transactions'][$rotationId];
    }

    /** @param array<string,mixed> $payload @return array<string,mixed> */
    private function projectIdentityRotationFacts(array $payload): array
    {
        $rotationId = \strtolower(\trim((string)($payload['rotation_id'] ?? '')));
        $oldUuid = \strtolower(\trim((string)(
            $payload['old_project_uuid'] ?? ''
        )));
        $newUuid = \strtolower(\trim((string)(
            $payload['new_project_uuid'] ?? ''
        )));
        $rootInput = \trim((string)($payload['project_root'] ?? ''));
        if (\preg_match('/\A[a-f0-9]{32}\z/D', $rotationId) !== 1
            || !$this->validProjectUuid($oldUuid)
            || !$this->validProjectUuid($newUuid)
            || \hash_equals($oldUuid, $newUuid)
            || $rootInput === ''
            || \strlen($rootInput) > 4096
        ) {
            throw new \DomainException(
                'Project identity rotation facts are invalid.'
            );
        }
        return [
            'schema_version' => 1,
            'protocol' => self::PROTOCOL,
            'rotation_id' => $rotationId,
            'old_project_uuid' => $oldUuid,
            'new_project_uuid' => $newUuid,
            'project_root' => $this->canonicalDirectory($rootInput),
        ];
    }

    /**
     * @param array<string,mixed> $transaction
     * @param array<string,mixed> $facts
     */
    private function assertSameProjectIdentityRotation(
        array $transaction,
        array $facts,
        string $requestDigest,
        string $idempotencyKey,
    ): void {
        foreach ([
            'rotation_id',
            'old_project_uuid',
            'new_project_uuid',
            'project_root',
        ] as $field) {
            if (!\hash_equals(
                (string)($facts[$field] ?? ''),
                (string)($transaction[$field] ?? ''),
            )) {
                throw new \DomainException(
                    'Rotation ID or idempotency key is bound to different facts.'
                );
            }
        }
        if (!\hash_equals(
                $requestDigest,
                (string)($transaction['request_digest'] ?? ''),
            )
            || !\hash_equals(
                $idempotencyKey,
                (string)($transaction['idempotency_key'] ?? ''),
            )
        ) {
            throw new \DomainException(
                'Rotation ID or idempotency key is bound to different facts.'
            );
        }
    }

    /** @param array<string,mixed> $payload @return array<string,mixed> */
    private function projectIdentityRotationTransactionForRequest(array $payload): array
    {
        $rotationId = \strtolower(\trim((string)($payload['rotation_id'] ?? '')));
        if (\preg_match('/\A[a-f0-9]{32}\z/D', $rotationId) !== 1) {
            throw new \DomainException('Project identity rotation ID is invalid.');
        }
        $transaction = $this->state['rotation_transactions'][$rotationId] ?? null;
        if (!\is_array($transaction)) {
            throw new \DomainException('Project identity rotation was not found.');
        }
        $oldUuid = \strtolower(\trim((string)(
            $payload['old_project_uuid'] ?? ''
        )));
        $newUuid = \strtolower(\trim((string)(
            $payload['new_project_uuid'] ?? ''
        )));
        if (!\hash_equals(
                (string)($transaction['old_project_uuid'] ?? ''),
                $oldUuid,
            )
            || !\hash_equals(
                (string)($transaction['new_project_uuid'] ?? ''),
                $newUuid,
            )
        ) {
            throw new \DomainException(
                'Project identity rotation UUID fence does not match the transaction.'
            );
        }
        return $transaction;
    }

    /** @param array<string,mixed> $transaction @return array<string,mixed> */
    private function projectIdentityRotationCommitFacts(array $transaction): array
    {
        return [
            'schema_version' => 1,
            'protocol' => self::PROTOCOL,
            'operation' => 'rotate-commit',
            'rotation_id' => (string)$transaction['rotation_id'],
            'old_project_uuid' => (string)$transaction['old_project_uuid'],
            'new_project_uuid' => (string)$transaction['new_project_uuid'],
            'project_root' => (string)$transaction['project_root'],
            'request_digest' => (string)$transaction['request_digest'],
            'idempotency_key' => (string)$transaction['idempotency_key'],
            'new_credential_id' => (string)$transaction['new_credential_id'],
        ];
    }

    /** @param array<string,mixed> $transaction */
    private function nativeProjectIdentityRotationIntent(array $transaction): string
    {
        return \hash('sha256', $this->canonicalJson([
            'kind' => 'PROJECT_IDENTITY_ROTATION',
            'rotation_id' => (string)($transaction['rotation_id'] ?? ''),
            'old_project_uuid' => (string)($transaction['old_project_uuid'] ?? ''),
            'new_project_uuid' => (string)($transaction['new_project_uuid'] ?? ''),
            'project_root' => (string)($transaction['project_root'] ?? ''),
            'request_digest' => (string)($transaction['request_digest'] ?? ''),
            'owner' => (array)($transaction['owner'] ?? []),
            'old_credential_id' => (string)(
                $transaction['old_credential_id'] ?? ''
            ),
            'new_credential_id' => (string)(
                $transaction['new_credential_id'] ?? ''
            ),
        ]));
    }

    /**
     * @param array<string,mixed> $transaction
     * @return array{assigned:int,registry_digest:string}
     */
    private function prepareNativeProjectIdentityRotation(array $transaction): array
    {
        $this->assertSecurityAllocationSerialized(
            (string)($transaction['rotation_id'] ?? ''),
        );
        $assignedExisting = (int)($transaction['security_generation'] ?? 0);
        if (!\is_resource($this->brokerExchange)
            || !\is_array($this->activeBrokerPeer)
        ) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production project identity rotation requires Native AUTH_TRANSFER_PREPARE.'
                );
            }
            $assigned = $assignedExisting > 0
                ? $assignedExisting
                : $this->nextSecurityGeneration();
            return [
                'assigned' => $assigned,
                'registry_digest' => \hash(
                    'sha256',
                    'test-project-rotation:' . $transaction['rotation_id'],
                ),
            ];
        }
        $channel = (string)$this->activeBrokerPeer['channel'];
        $intent = $this->nativeProjectIdentityRotationIntent($transaction);
        $previousCommitted = (int)(
            $this->state['security_committed_high_water'] ?? 0
        );
        $previousAnchor = (string)(
            $this->state['native_security_anchor_digest'] ?? ''
        );
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $previousAnchor) !== 1) {
            throw new \RuntimeException(
                'Native project identity rotation prior anchor is unavailable.'
            );
        }
        $response = $this->brokerAction($channel, [
            'AUTH_TRANSFER_PREPARE',
            (string)$transaction['old_project_uuid'],
            (string)$transaction['new_project_uuid'],
            (string)$transaction['rotation_id'],
            $intent,
            $this->brokerOwnerIdentity((array)$transaction['owner']),
            (string)(int)($this->state['security_committed_high_water'] ?? 0),
        ]);
        if (\count($response) !== 4
            || !\hash_equals((string)$transaction['rotation_id'], (string)$response[0])
            || !\hash_equals($intent, (string)$response[1])
            || \preg_match('/\A[1-9][0-9]*\z/D', (string)$response[2]) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[3]) !== 1
            || ($assignedExisting > 0 && $assignedExisting !== (int)$response[2])
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid AUTH_TRANSFER_PREPARE receipt.'
            );
        }
        $nativeSecurity = $this->attestNativeSecurityState(
            $channel,
            $previousCommitted,
            (string)$response[3],
            $previousAnchor,
        );
        if ($nativeSecurity['allocated'] !== (int)$response[2]
            || $nativeSecurity['committed'] !== $previousCommitted
        ) {
            throw new \RuntimeException(
                'Native AUTH_TRANSFER_PREPARE allocation is not security-attested.'
            );
        }
        $this->recordNativeSecurityState($nativeSecurity);
        return [
            'assigned' => (int)$response[2],
            'registry_digest' => (string)$response[3],
        ];
    }

    /** @param array<string,mixed> $transaction */
    private function commitNativeProjectIdentityRotation(array $transaction): void
    {
        $rotationId = (string)$transaction['rotation_id'];
        $assigned = (int)($transaction['security_generation'] ?? 0);
        $intent = $this->nativeProjectIdentityRotationIntent($transaction);
        if ($assigned < 1) {
            throw new \RuntimeException(
                'Native project identity rotation generation is missing.'
            );
        }
        if (!\is_resource($this->brokerExchange)
            || !\is_array($this->activeBrokerPeer)
        ) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production project identity rotation requires Native AUTH_TRANSFER_COMMIT.'
                );
            }
            $registryDigest = (string)($transaction['native_registry_digest'] ?? '');
            $tombstoneDigest = \hash('sha256', 'test-tombstone:' . $rotationId);
        } else {
            $channel = (string)$this->activeBrokerPeer['channel'];
            $anchorDigest = (string)(
                $this->state['native_security_anchor_digest'] ?? ''
            );
            $preparedRegistryDigest = (string)(
                $transaction['native_registry_digest'] ?? ''
            );
            if (\preg_match('/\A[a-f0-9]{64}\z/D', $preparedRegistryDigest) !== 1) {
                throw new \RuntimeException(
                    'Native prepared rotation registry digest is unavailable.'
                );
            }
            $priorCommitted = (int)(
                $this->state['security_committed_high_water'] ?? 0
            );
            $priorSecurity = $this->attestNativeSecurityState(
                $channel,
                $priorCommitted,
                $preparedRegistryDigest,
                \preg_match('/\A[a-f0-9]{64}\z/D', $anchorDigest) === 1
                    ? $anchorDigest
                    : '-',
            );
            if ($priorSecurity['allocated'] < $assigned
                || $priorSecurity['committed'] !== $priorCommitted
                || $assigned <= $priorCommitted
            ) {
                throw new \RuntimeException(
                    'Native prepared rotation does not extend the prior committed state.'
                );
            }
            $this->recordNativeSecurityState($priorSecurity);
            $anchorDigest = (string)$priorSecurity['anchor_digest'];
            $response = $this->brokerAction($channel, [
                'AUTH_TRANSFER_COMMIT',
                (string)$transaction['old_project_uuid'],
                (string)$transaction['new_project_uuid'],
                $rotationId,
                $intent,
                (string)$assigned,
                $anchorDigest,
            ]);
            if (\count($response) !== 5
                || !\hash_equals($rotationId, (string)$response[0])
                || !\hash_equals($intent, (string)$response[1])
                || (int)$response[2] !== $assigned
                || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[3]) !== 1
                || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[4]) !== 1
            ) {
                throw new \RuntimeException(
                    'Native Broker returned an invalid AUTH_TRANSFER_COMMIT receipt.'
                );
            }
            $registryDigest = (string)$response[3];
            $tombstoneDigest = (string)$response[4];
            $attestation = $this->attestNativeProjectIdentityRotation(
                $transaction,
            );
            if (!\hash_equals(
                    $registryDigest,
                    (string)$attestation['registry_digest'],
                )
                || !\hash_equals(
                    $tombstoneDigest,
                    (string)$attestation['tombstone_digest'],
                )
            ) {
                throw new \RuntimeException(
                    'Native AUTH_TRANSFER commit and attestation receipts diverged.'
                );
            }
        }
        $this->state['rotation_transactions'][$rotationId]['native_registry_digest']
            = $registryDigest;
        $this->state['rotation_transactions'][$rotationId]['native_tombstone_digest']
            = $tombstoneDigest;
        $this->state['rotation_transactions'][$rotationId]['phase'] = 'BROKER_COMMITTED';
        $this->state['rotation_transactions'][$rotationId]['broker_committed_at']
            = \gmdate(DATE_ATOM);
        $this->state['rotation_transactions'][$rotationId]['updated_at']
            = \gmdate(DATE_ATOM);
        $this->state['security_generation_high_water'] = \max(
            (int)($this->state['security_generation_high_water'] ?? 0),
            $assigned,
        );
        $this->state['security_committed_high_water'] = \max(
            (int)($this->state['security_committed_high_water'] ?? 0),
            $assigned,
        );
        $this->persistSecurityLedger();
        $this->persistState();
    }

    /**
     * @param array<string,mixed> $transaction
     * @return array{registry_digest:string,tombstone_digest:string}
     */
    private function attestNativeProjectIdentityRotation(array $transaction): array
    {
        $attestation = $this->attestNativeProjectIdentityRotationState($transaction);
        if (!\hash_equals('COMMITTED', (string)$attestation['state'])
            || (int)$attestation['assigned']
                !== (int)($transaction['security_generation'] ?? 0)
        ) {
            throw new \RuntimeException(
                'Native project identity rotation is not committed at the expected generation.'
            );
        }
        return [
            'registry_digest' => (string)$attestation['registry_digest'],
            'tombstone_digest' => (string)$attestation['tombstone_digest'],
        ];
    }

    /**
     * @param array<string,mixed> $transaction
     * @return array{state:string,assigned:int,registry_digest:string,tombstone_digest:string}
     */
    private function attestNativeProjectIdentityRotationState(
        array $transaction,
    ): array {
        $requestedAssigned = (int)($transaction['security_generation'] ?? 0);
        $zeroDigest = \str_repeat('0', 64);
        if (!\is_resource($this->brokerExchange)
            || !\is_array($this->activeBrokerPeer)
        ) {
            $phase = (string)($transaction['phase'] ?? '');
            $state = \in_array(
                $phase,
                ['LEDGER_COMMITTED', 'BROKER_COMMITTED', 'CONTROLLER_COMMITTED', 'FINALIZED'],
                true,
            ) ? 'COMMITTED' : ($requestedAssigned > 0 ? 'PREPARED' : 'UNKNOWN');
            return [
                'state' => $state,
                'assigned' => $requestedAssigned,
                'registry_digest' => (string)(
                    $transaction['native_registry_digest'] ?? $zeroDigest
                ),
                'tombstone_digest' => (string)(
                    $transaction['native_tombstone_digest'] ?? $zeroDigest
                ),
            ];
        }
        $intent = $this->nativeProjectIdentityRotationIntent($transaction);
        $channel = (string)$this->activeBrokerPeer['channel'];
        $response = $this->brokerAction(
            $channel,
            [
                'AUTH_TRANSFER_ATTEST',
                (string)$transaction['old_project_uuid'],
                (string)$transaction['new_project_uuid'],
                (string)$transaction['rotation_id'],
                $intent,
                (string)$requestedAssigned,
            ],
        );
        $state = (string)($response[2] ?? '');
        $assigned = (int)($response[3] ?? -1);
        $registryDigest = (string)($response[4] ?? '');
        $tombstoneDigest = (string)($response[5] ?? '');
        if (\count($response) !== 6
            || !\hash_equals((string)$transaction['rotation_id'], (string)$response[0])
            || !\hash_equals($intent, (string)$response[1])
            || !\in_array($state, ['UNKNOWN', 'PREPARED', 'ABORTED', 'COMMITTED'], true)
            || \preg_match('/\A[0-9]+\z/D', (string)$response[3]) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $registryDigest) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $tombstoneDigest) !== 1
            || ($requestedAssigned > 0 && $assigned !== $requestedAssigned)
            || ($state === 'UNKNOWN'
                && ($assigned !== 0
                    || !\hash_equals($zeroDigest, $registryDigest)
                    || !\hash_equals($zeroDigest, $tombstoneDigest)))
            || ($state !== 'UNKNOWN' && $assigned < 1)
            || (\in_array($state, ['PREPARED', 'ABORTED'], true)
                && !\hash_equals($zeroDigest, $tombstoneDigest))
            || ($state === 'COMMITTED'
                && \hash_equals($zeroDigest, $tombstoneDigest))
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid AUTH_TRANSFER_ATTEST receipt.'
            );
        }
        if ($state !== 'UNKNOWN') {
            $minimumCommitted = $state === 'COMMITTED'
                ? $assigned
                : (int)($this->state['security_committed_high_water'] ?? 0);
            $expectedAnchor = $state === 'COMMITTED'
                ? $tombstoneDigest
                : (string)($this->state['native_security_anchor_digest'] ?? '-');
            if (\preg_match('/\A[a-f0-9]{64}\z/D', $expectedAnchor) !== 1) {
                $expectedAnchor = '-';
            }
            $nativeSecurity = $this->attestNativeSecurityState(
                $channel,
                $minimumCommitted,
                $registryDigest,
                $expectedAnchor,
            );
            if ($nativeSecurity['allocated'] < $assigned
                || ($state === 'COMMITTED'
                    && $nativeSecurity['committed'] !== $assigned)
                || ($state !== 'COMMITTED'
                    && $nativeSecurity['committed']
                        !== (int)($this->state['security_committed_high_water'] ?? 0))
            ) {
                throw new \RuntimeException(
                    'Native transfer attestation diverges from the security ledger.'
                );
            }
            $localPhase = (string)($transaction['phase'] ?? '');
            if ($state !== 'COMMITTED'
                || \in_array(
                    $localPhase,
                    ['LEDGER_COMMITTED', 'BROKER_COMMITTED', 'CONTROLLER_COMMITTED', 'FINALIZED'],
                    true,
                )
            ) {
                $this->recordNativeSecurityState($nativeSecurity);
            }
        }
        return [
            'state' => $state,
            'assigned' => $assigned,
            'registry_digest' => $registryDigest,
            'tombstone_digest' => $tombstoneDigest,
        ];
    }

    /**
     * @param array<string,mixed> $transaction
     * @return array{assigned:int,registry_digest:string}
     */
    private function abortNativeProjectIdentityRotation(array $transaction): array
    {
        if (!\is_resource($this->brokerExchange)
            || !\is_array($this->activeBrokerPeer)
        ) {
            if ($this->brokerActionsRequired()) {
                throw new \RuntimeException(
                    'Production project identity rotation requires Native AUTH_TRANSFER_ABORT.'
                );
            }
            return [
                'assigned' => (int)($transaction['security_generation'] ?? 0),
                'registry_digest' => (string)(
                    $transaction['native_registry_digest'] ?? \str_repeat('0', 64)
                ),
            ];
        }
        $intent = $this->nativeProjectIdentityRotationIntent($transaction);
        $requestedAssigned = (int)($transaction['security_generation'] ?? 0);
        $channel = (string)$this->activeBrokerPeer['channel'];
        $response = $this->brokerAction(
            $channel,
            [
                'AUTH_TRANSFER_ABORT',
                (string)$transaction['old_project_uuid'],
                (string)$transaction['new_project_uuid'],
                (string)$transaction['rotation_id'],
                $intent,
                (string)$requestedAssigned,
            ],
        );
        $assigned = (int)($response[2] ?? -1);
        if (\count($response) !== 4
            || !\hash_equals((string)$transaction['rotation_id'], (string)$response[0])
            || !\hash_equals($intent, (string)$response[1])
            || \preg_match('/\A[0-9]+\z/D', (string)$response[2]) !== 1
            || ($requestedAssigned > 0 && $assigned !== $requestedAssigned)
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[3]) !== 1
            || ($assigned === 0
                && !\hash_equals(\str_repeat('0', 64), (string)$response[3]))
        ) {
            throw new \RuntimeException(
                'Native Broker returned an invalid AUTH_TRANSFER_ABORT receipt.'
            );
        }
        if ($assigned > 0) {
            $anchorDigest = (string)(
                $this->state['native_security_anchor_digest'] ?? ''
            );
            $nativeSecurity = $this->attestNativeSecurityState(
                $channel,
                (int)($this->state['security_committed_high_water'] ?? 0),
                (string)$response[3],
                \preg_match('/\A[a-f0-9]{64}\z/D', $anchorDigest) === 1
                    ? $anchorDigest
                    : '-',
            );
            if ($nativeSecurity['allocated'] < $assigned) {
                throw new \RuntimeException(
                    'Native AUTH_TRANSFER_ABORT generation is not security-attested.'
                );
            }
            $this->recordNativeSecurityState($nativeSecurity);
        }
        return [
            'assigned' => $assigned,
            'registry_digest' => (string)$response[3],
        ];
    }

    private function replayProjectIdentityRotations(): void
    {
        if (!\is_resource($this->brokerExchange)
            || !\is_array($this->activeBrokerPeer)
            || !\hash_equals('admin', (string)$this->activeBrokerPeer['channel'])
        ) {
            return;
        }
        $count = 0;
        foreach ((array)($this->state['rotation_transactions'] ?? []) as $rotationId => $transaction) {
            if (!\is_array($transaction)) {
                continue;
            }
            $phase = (string)($transaction['phase'] ?? '');
            if (!\in_array($phase, ['LEDGER_COMMITTED', 'BROKER_COMMITTED'], true)) {
                continue;
            }
            if (++$count > 128) {
                throw new \RuntimeException(
                    'Project identity rotation replay quota is exceeded.'
                );
            }
            if ($phase === 'LEDGER_COMMITTED') {
                $this->commitNativeProjectIdentityRotation($transaction);
            }
            if ((string)($this->state['rotation_transactions'][$rotationId]['phase'] ?? '')
                === 'BROKER_COMMITTED'
            ) {
                $this->applyCommittedProjectIdentityRotation((string)$rotationId);
            }
        }
    }

    private function applyCommittedProjectIdentityRotation(string $rotationId): void
    {
        try {
            $transaction = $this->state['rotation_transactions'][$rotationId] ?? null;
            if (!\is_array($transaction)
                || !\hash_equals(
                    'BROKER_COMMITTED',
                    (string)($transaction['phase'] ?? ''),
                )
            ) {
                throw new \RuntimeException(
                    'Only a Native-committed project identity rotation can update routing state.'
                );
            }
            $oldUuid = (string)$transaction['old_project_uuid'];
            $newUuid = (string)$transaction['new_project_uuid'];
            $securityGeneration = (int)($transaction['security_generation'] ?? 0);
            $oldEnrollment = $this->state['enrollments'][$oldUuid] ?? null;
            if (!\is_array($oldEnrollment)) {
                $oldEnrollment = $transaction['old_enrollment_snapshot'] ?? null;
            }
            if (!\is_array($oldEnrollment)
                || $securityGeneration < 1
                || \preg_match(
                    '/\A[a-f0-9]{64}\z/D',
                    (string)($transaction['native_registry_digest'] ?? ''),
                ) !== 1
                || \preg_match(
                    '/\A[a-f0-9]{64}\z/D',
                    (string)($transaction['native_tombstone_digest'] ?? ''),
                ) !== 1
            ) {
                throw new \RuntimeException(
                    'Committed project identity rotation security closure is malformed.'
                );
            }

            $this->beginRoutingMutation('project-identity-rotation:' . $rotationId);
            // Native has already tombstoned the old identity. From this point
            // every Controller failure must retain the security overlay and
            // stop the old data plane; rolling back to the previous routes is
            // no longer a valid recovery outcome.
            $this->markPublicationIrrevocableSecurity();
            $oldEnrollment['rotation_role'] = 'old';
            $oldEnrollment['rotation_id'] = $rotationId;
            $oldEnrollment['rotated_to_project_uuid'] = $newUuid;
            $oldEnrollment['updated_at'] = \gmdate(DATE_ATOM);
            $newEnrollment = $oldEnrollment;
            $newEnrollment['project_uuid'] = $newUuid;
            $newEnrollment['credential_id'] = (string)$transaction['new_credential_id'];
            $newEnrollment['credential_secret'] = (string)(
                $transaction['new_credential_secret']
            );
            $newEnrollment['credential_generation'] = (int)(
                $transaction['new_credential_generation']
            );
            $newEnrollment['security_generation'] = $securityGeneration;
            $newEnrollment['rotation_role'] = 'new';
            $newEnrollment['rotation_id'] = $rotationId;
            $newEnrollment['rotated_from_project_uuid'] = $oldUuid;
            unset(
                $newEnrollment['rotated_to_project_uuid'],
                $newEnrollment['enrollment_transaction_id'],
            );
            $newEnrollment['native_authorization_transaction_id'] = $rotationId;
            $newEnrollment['native_authorization_intent_digest']
                = $this->nativeProjectIdentityRotationIntent($transaction);
            $newEnrollment['desired_digest'] = \hash(
                'sha256',
                $this->canonicalJson([
                    'project_uuid' => $newUuid,
                    'project_root' => (string)$newEnrollment['project_root'],
                    'certificate_roots' => (array)$newEnrollment['certificate_roots'],
                    'allowed_domains' => (array)$newEnrollment['allowed_domains'],
                    'owner' => (array)$newEnrollment['owner'],
                    'capabilities' => (array)$newEnrollment['capabilities'],
                ]),
            );
            $newEnrollment['credential_issued_at'] = (string)(
                $transaction['created_at'] ?? \gmdate(DATE_ATOM)
            );
            $newEnrollment['updated_at'] = \gmdate(DATE_ATOM);
            $this->state['enrollments'][$oldUuid] = $oldEnrollment;
            $this->state['enrollments'][$newUuid] = $newEnrollment;
            $this->state['security']['tombstones']['project:' . $oldUuid] = [
                'kind' => 'project_identity_rotation',
                'project_uuid' => $oldUuid,
                'to_project_uuid' => $newUuid,
                'rotation_id' => $rotationId,
                'credential_id' => (string)($oldEnrollment['credential_id'] ?? ''),
                'generation' => $securityGeneration,
                'native_tombstone_digest' => (string)(
                    $transaction['native_tombstone_digest']
                ),
                'created_at' => \gmdate(DATE_ATOM),
            ];

            $oldProject = \is_array($this->state['projects'][$oldUuid] ?? null)
                ? $this->state['projects'][$oldUuid]
                : (\is_array($transaction['old_project_snapshot'] ?? null)
                    ? $transaction['old_project_snapshot']
                    : []);
            $newRouteIds = [];
            foreach ((array)($this->state['routes'] ?? []) as $oldRouteId => $route) {
                if (!\is_array($route)
                    || !\hash_equals(
                        $oldUuid,
                        (string)($route['project_uuid'] ?? ''),
                    )
                    || \hash_equals('REMOVED', (string)($route['status'] ?? ''))
                ) {
                    continue;
                }
                $domain = (string)$route['domain'];
                $newRouteId = $this->canonicalRouteId($newUuid, $domain);
                $candidate = $route;
                $candidate['route_id'] = $newRouteId;
                $candidate['project_uuid'] = $newUuid;
                $candidate['enrollment_security_generation'] = $securityGeneration;
                $candidate['domain_security_generation'] = $securityGeneration;
                $candidate['route_generation'] = \max(
                    1,
                    (int)($route['route_generation'] ?? 0) + 1,
                );
                $candidate['instances'] = [];
                $candidate['backends'] = [];
                $candidate['backend_instances'] = [];
                $candidate['backend_identity'] = [];
                $candidate['preferred_instance_id'] = '';
                $candidate['instance_id'] = '';
                $candidate['status'] = ($candidate['certificate']['valid'] ?? false) === true
                    ? 'PENDING_BACKEND'
                    : 'PENDING_CERTIFICATE';
                $candidate['stale_since'] = null;
                $candidate['stale_since_monotonic'] = null;
                $candidate['stale_boot_id'] = null;
                $candidate['updated_at'] = \gmdate(DATE_ATOM);
                $this->enforceRemovedRoute(
                    $this->state['routes'][$oldRouteId],
                    \time(),
                );
                $this->state['routes'][$oldRouteId]['security_tombstone_generation']
                    = $securityGeneration;
                $this->state['routes'][$newRouteId] = $candidate;
                $this->retainRouteSecurityClosure(
                    $this->state['routes'][$newRouteId],
                    true,
                    (string)$candidate['status'],
                );
                $oldFloorKey = $this->certificateFloorKey($oldUuid, $domain);
                $newFloorKey = $this->certificateFloorKey($newUuid, $domain);
                if (\is_array($this->state['certificate_floors'][$oldFloorKey] ?? null)
                    && !\is_array(
                        $this->state['certificate_floors'][$newFloorKey] ?? null
                    )
                ) {
                    $this->state['certificate_floors'][$newFloorKey]
                        = $this->state['certificate_floors'][$oldFloorKey];
                    $this->state['certificate_floors'][$newFloorKey]['project_uuid']
                        = $newUuid;
                    $this->state['certificate_floors'][$newFloorKey]['route_generation']
                        = (int)$candidate['route_generation'];
                    $this->state['certificate_floors'][$newFloorKey]['updated_at']
                        = \gmdate(DATE_ATOM);
                }
                $this->state['security']['tombstones']['domain:' . $domain] = [
                    'kind' => 'project_identity_rotation',
                    'domain' => $domain,
                    'from_project_uuid' => $oldUuid,
                    'to_project_uuid' => $newUuid,
                    'rotation_id' => $rotationId,
                    'generation' => $securityGeneration,
                    'created_at' => \gmdate(DATE_ATOM),
                ];
                $newRouteIds[] = $newRouteId;
            }
            if ($newRouteIds === []) {
                foreach ((array)($this->state['routes'] ?? []) as $routeId => $route) {
                    if (\is_array($route)
                        && !\hash_equals('REMOVED', (string)($route['status'] ?? ''))
                        && \hash_equals(
                            $newUuid,
                            (string)($route['project_uuid'] ?? ''),
                        )
                    ) {
                        $newRouteIds[] = (string)$routeId;
                    }
                }
            }
            $newRouteIds = \array_values(\array_unique($newRouteIds));
            \sort($newRouteIds, SORT_STRING);
            $retainedProjectGeneration = \max(
                0,
                (int)($oldProject['generation'] ?? 0),
            );
            $retainedProjectDigest = \strtolower(\trim((string)(
                $oldProject['digest'] ?? ''
            )));
            if ($retainedProjectGeneration > 0
                && \preg_match('/\A[a-f0-9]{64}\z/D', $retainedProjectDigest) !== 1
            ) {
                throw new \RuntimeException(
                    'Rotated project desired-generation floor is malformed.'
                );
            }
            $retainedIdempotency = $retainedProjectGeneration > 0
                ? \substr(\hash(
                    'sha256',
                    $newUuid . ':desired:' . $retainedProjectGeneration . ':'
                        . $retainedProjectDigest,
                ), 0, 40)
                : '';
            $this->state['projects'][$newUuid] = [
                'project_uuid' => $newUuid,
                'project_root' => (string)$transaction['project_root'],
                'generation' => $retainedProjectGeneration,
                'digest' => $retainedProjectDigest,
                'idempotency_key' => $retainedIdempotency,
                'route_ids' => $newRouteIds,
                'registered_at' => (string)(
                    $oldProject['registered_at'] ?? \gmdate(DATE_ATOM)
                ),
                'rotation_id' => $rotationId,
                'rotation_pending_registration' => true,
            ];
            unset($this->state['projects'][$oldUuid]);
            unset($this->state['instances'][$oldUuid]);
            $this->state['instances'][$newUuid] = [];
            foreach ((array)($this->state['acme_challenges'] ?? []) as $leaseId => $lease) {
                if (\is_array($lease)
                    && \hash_equals(
                        $oldUuid,
                        (string)($lease['project_uuid'] ?? ''),
                    )
                ) {
                    unset($this->state['acme_challenges'][$leaseId]);
                }
            }
            unset($this->state['acme_generations'][$oldUuid]);
            $this->persistSecurityLedger();
            $this->persistState();
            $this->bumpGeneration('project_identity_rotation', [
                'rotation_id' => $rotationId,
                'old_project_uuid' => $oldUuid,
                'new_project_uuid' => $newUuid,
                'security_generation' => $securityGeneration,
            ]);
            $this->configDirty = true;
            if (!$this->publishIfDirty()) {
                throw new \RuntimeException(
                    'Committed project identity rotation could not publish its fail-closed routes.'
                );
            }
            $committedAt = \gmdate(DATE_ATOM);
            $this->state['rotation_transactions'][$rotationId]['phase']
                = 'CONTROLLER_COMMITTED';
            $this->state['rotation_transactions'][$rotationId]
                ['controller_committed_at'] = $committedAt;
            $this->state['rotation_transactions'][$rotationId]['updated_at']
                = $committedAt;
            $this->persistSecurityLedger();
            $this->persistState();
            $this->journal('project_rotation_controller_committed', [
                'rotation_id' => $rotationId,
                'old_project_uuid' => $oldUuid,
                'new_project_uuid' => $newUuid,
                'security_generation' => $securityGeneration,
            ]);
        } catch (\Throwable $throwable) {
            if ($this->publication !== null) {
                $this->abortRoutingMutation(
                    'Committed project identity rotation roll-forward failed: '
                        . $throwable->getMessage(),
                );
            } else {
                $this->state['ready'] = false;
                $this->state['isolation_mode'] = true;
                $this->state['health_state'] = 'SECURITY_MUTATION_FAILED_CLOSED';
                $this->stopDataPlane();
                $this->persistState();
            }
            throw $throwable;
        }
    }

    /**
     * @param array<string,mixed> $transaction
     * @return array<string,mixed>
     */
    private function projectIdentityRotationResponse(
        array $transaction,
        bool $idempotent,
        bool $includeCredential,
    ): array {
        $phase = (string)($transaction['phase'] ?? '');
        $protocolState = match ($phase) {
            'PREPARED', 'NATIVE_PREPARED' => 'ROTATION_PREPARED',
            'LEDGER_COMMITTED', 'BROKER_COMMITTED' => 'COMMITTING',
            default => $phase,
        };
        $newEnrollment = $this->state['enrollments'][
            (string)($transaction['new_project_uuid'] ?? '')
        ] ?? null;
        $secret = (string)(
            $transaction['new_credential_secret']
            ?? (\is_array($newEnrollment)
                ? ($newEnrollment['credential_secret'] ?? '')
                : '')
        );
        $securityGeneration = (int)($transaction['security_generation'] ?? 0);
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $secret) !== 1
            || \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($transaction['new_credential_id'] ?? ''),
            ) !== 1
        ) {
            throw new \RuntimeException(
                'Project identity rotation credential is unavailable.'
            );
        }
        $response = [
            'accepted' => true,
            'idempotent' => $idempotent,
            // Credential response validation deliberately keys this field to
            // the pending/new identity, while request authorization remains
            // bound to payload.project_uuid (the old identity until commit).
            'project_uuid' => (string)$transaction['new_project_uuid'],
            'rotation_id' => (string)$transaction['rotation_id'],
            'old_project_uuid' => (string)$transaction['old_project_uuid'],
            'new_project_uuid' => (string)$transaction['new_project_uuid'],
            'state' => $protocolState,
            'security_generation' => $securityGeneration,
        ];
        if ($securityGeneration > 0) {
            $receipt = [
                'schema_version' => 1,
                'protocol' => self::PROTOCOL,
                'host_id' => $this->hostId(),
                'gateway_epoch' => (string)$this->state['epoch'],
                'rotation_id' => (string)$transaction['rotation_id'],
                'old_project_uuid' => (string)$transaction['old_project_uuid'],
                'new_project_uuid' => (string)$transaction['new_project_uuid'],
                'project_root' => (string)$transaction['project_root'],
                'request_digest' => (string)$transaction['request_digest'],
                'idempotency_key' => (string)$transaction['idempotency_key'],
                'security_generation' => $securityGeneration,
                'new_credential_id' => (string)$transaction['new_credential_id'],
                'state' => $protocolState,
                'issued_at' => (string)(
                    $transaction['finalized_at']
                    ?? $transaction['controller_committed_at']
                    ?? $transaction['broker_committed_at']
                    ?? $transaction['updated_at']
                    ?? $transaction['created_at']
                    ?? ''
                ),
            ];
            $receipt['signature'] = \hash_hmac(
                'sha256',
                $this->canonicalJson($receipt),
                $secret,
            );
            $response['rotation_receipt'] = $receipt;
        }
        if ($includeCredential && !\in_array($phase, ['ABORTED', 'FINALIZED'], true)) {
            $response['credential'] = [
                'schema_version' => 1,
                'protocol' => self::PROTOCOL,
                'host_id' => $this->hostId(),
                'project_uuid' => (string)$transaction['new_project_uuid'],
                'credential_id' => (string)$transaction['new_credential_id'],
                'credential_generation' => (int)(
                    $transaction['new_credential_generation']
                ),
                'secret' => $secret,
                'issued_at' => (string)$transaction['created_at'],
            ];
        }
        return $response;
    }

    /**
     * @param array<string,mixed> $payload
     * @return array{kind:string,uid?:int,gid?:int,sid?:string}
     */
    private function projectRootOwner(string $projectRoot, array $payload): array
    {
        if (\PHP_OS_FAMILY === 'Windows') {
            $peer = \is_array($payload['_broker_peer'] ?? null) ? $payload['_broker_peer'] : [];
            $sid = \strtoupper(\trim((string)($peer['sid'] ?? '')));
            if (\preg_match('/\AS-1-(?:[0-9]+-)+[0-9]+\z/D', $sid) !== 1) {
                throw new \DomainException(
                    'Windows enrollment requires a broker-verified project owner SID.'
                );
            }
            return ['kind' => 'windows', 'sid' => $sid];
        }
        $status = @\lstat($projectRoot);
        if (\is_array($status) && !\is_link($projectRoot)) {
            return [
                'kind' => 'posix',
                'uid' => (int)$status['uid'],
                'gid' => (int)$status['gid'],
            ];
        }
        $uid = $payload['project_owner_uid'] ?? null;
        $gid = $payload['project_owner_gid'] ?? null;
        if ((! \is_int($uid) && !\is_string($uid))
            || (! \is_int($gid) && !\is_string($gid))
            || \preg_match('/\A[0-9]+\z/D', (string)$uid) !== 1
            || \preg_match('/\A[0-9]+\z/D', (string)$gid) !== 1
        ) {
            throw new \DomainException(
                'Enrollment requires a verifiable POSIX project owner.'
            );
        }
        return [
            'kind' => 'posix',
            'uid' => (int)$uid,
            'gid' => (int)$gid,
        ];
    }

    /**
     * @param array<string,mixed> $capabilities
     * @return array<string,bool>
     */
    private function normalizeEnrollmentCapabilities(array $capabilities): array
    {
        $allowed = ['stateless', 'shared_session', 'acme_http_01', 'acme_dns_01'];
        $normalized = [];
        foreach ($allowed as $capability) {
            $normalized[$capability] = ($capabilities[$capability] ?? false) === true;
        }
        return $normalized;
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function revoke(array $payload): array
    {
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        if (!$this->validProjectUuid($projectUuid)) {
            throw new \DomainException('Revocation requires a valid project UUID.');
        }
        $enrollment = $this->state['enrollments'][$projectUuid] ?? null;
        if (!\is_array($enrollment)) {
            return ['accepted' => true, 'idempotent' => true];
        }
        foreach ((array)($this->state['rotation_transactions'] ?? []) as $rotation) {
            if (!\is_array($rotation)
                || \in_array(
                    (string)($rotation['phase'] ?? ''),
                    ['ABORTED', 'FINALIZED'],
                    true,
                )
            ) {
                continue;
            }
            if (\in_array($projectUuid, [
                (string)($rotation['old_project_uuid'] ?? ''),
                (string)($rotation['new_project_uuid'] ?? ''),
            ], true)) {
                throw new \DomainException(
                    'Project revocation is fenced by an active identity rotation.'
                );
            }
        }
        $securityKind = 'PROJECT_REVOKE';
        $securityIntent = \hash('sha256', $this->canonicalJson([
            'kind' => $securityKind,
            'project_uuid' => $projectUuid,
            'credential_id' => (string)($enrollment['credential_id'] ?? ''),
            'enrollment_security_generation' => (int)(
                $enrollment['security_generation'] ?? 0
            ),
        ]));
        $securityTransactionId = \substr(\hash(
            'sha256',
            "wls-security-tx/1\0{$securityKind}\0{$securityIntent}",
        ), 0, 32);
        $reservation = $this->reserveSecurityMutation(
            $securityTransactionId,
            $securityIntent,
            $securityKind,
        );
        $tombstoneGeneration = (int)$reservation['assigned'];
        $this->state['security_transactions'][$securityTransactionId] = [
            'schema_version' => 1,
            'transaction_id' => $securityTransactionId,
            'intent_digest' => $securityIntent,
            'kind' => $securityKind,
            'assigned_generation' => $tombstoneGeneration,
            'phase' => 'RESERVED',
            'updated_at' => \gmdate(DATE_ATOM),
        ];
        $this->persistSecurityLedger();
        $this->persistState();
        $this->beginRoutingMutation('revoke:' . $projectUuid);
        $securityLedgerCommitted = false;
        try {
            $this->state['security']['tombstones']['project:' . $projectUuid] = [
                'kind' => 'project_revoke',
                'project_uuid' => $projectUuid,
                'credential_id' => (string)($enrollment['credential_id'] ?? ''),
                'generation' => $tombstoneGeneration,
                'created_at' => \gmdate(DATE_ATOM),
            ];
            foreach ((array)$this->state['routes'] as $routeId => $route) {
                if (\is_array($route)
                    && \hash_equals($projectUuid, (string)($route['project_uuid'] ?? ''))
                ) {
                    $this->enforceRemovedRoute(
                        $this->state['routes'][$routeId],
                        \time(),
                    );
                    $this->state['routes'][$routeId]['security_tombstone_generation']
                        = $tombstoneGeneration;
                }
            }
            unset($this->state['projects'][$projectUuid]);
            unset($this->state['instances'][$projectUuid]);
            unset($this->state['enrollments'][$projectUuid]);
            $this->markPublicationIrrevocableSecurity();
            // Persist the final transaction phase before asking Native to
            // seal it. A crash leaves the same tx/intent/anchor available for
            // an idempotent SECURITY_COMMIT replay; no post-commit ledger
            // rewrite can diverge from the Broker's sealed digest.
            $this->state['security_transactions'][$securityTransactionId]['phase']
                = 'COMMITTED';
            $this->state['security_transactions'][$securityTransactionId]['updated_at']
                = \gmdate(DATE_ATOM);
            $this->persistSecurityLedger();
            $securityLedgerCommitted = true;
            $this->commitSecurityMutation(
                $securityTransactionId,
                $securityIntent,
                $securityKind,
                $tombstoneGeneration,
            );
            $this->bumpGeneration('revoke', [
                'project_uuid' => $projectUuid,
                'tombstone_generation' => $tombstoneGeneration,
            ]);
            $this->configDirty = true;
            if (!$this->publishIfDirty()) {
                // Revocation is a security decision and is never rolled back.
                // If a filtered config cannot be activated, fail closed instead
                // of allowing the revoked route to remain reachable through LKG.
                throw new \DomainException(
                    'Project access was revoked, but the filtered gateway config failed.'
                );
            }
            return [
                'accepted' => true,
                'tombstone_generation' => $tombstoneGeneration,
            ];
        } catch (\Throwable $throwable) {
            if (!$securityLedgerCommitted) {
                try {
                    $abortReceipt = $this->abortSecurityMutation(
                        $securityTransactionId,
                        $securityIntent,
                        $securityKind,
                        $tombstoneGeneration,
                    );
                    $this->state['security_transactions'][$securityTransactionId]['phase']
                        = 'ABORTED';
                    $this->state['security_transactions'][$securityTransactionId]['receipt']
                        = $abortReceipt;
                    $this->state['security_transactions'][$securityTransactionId]['updated_at']
                        = \gmdate(DATE_ATOM);
                    $this->persistSecurityLedger();
                } catch (\Throwable) {
                }
            }
            $reason = 'Revocation transaction failed closed: ' . $throwable->getMessage();
            try {
                $this->failClosedSecurityMutation(
                    $reason,
                    !$securityLedgerCommitted,
                );
            } catch (\Throwable $failClosedError) {
                $this->stopDataPlane();
                $this->completePublication();
                throw new \RuntimeException(
                    $reason . ' The fail-closed state could not be persisted: '
                    . $failClosedError->getMessage(),
                    0,
                    $throwable,
                );
            }
            throw new \DomainException(
                $reason . ' The data plane was stopped.',
                0,
                $throwable,
            );
        }
    }

    /**
     * Administrator side of the explicit three-step transfer transaction.
     *
     * The administrator fences the current owner, the target project proves
     * its live backend and certificate over its own channel, and the
     * administrator commits one routing generation.
     *
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function transferDomain(array $payload): array
    {
        $phase = \strtolower(\trim((string)($payload['phase'] ?? 'prepare')));
        return match ($phase) {
            'prepare' => $this->prepareDomainTransfer($payload),
            'commit' => $this->commitDomainTransfer($payload),
            'abort' => $this->abortDomainTransfer($payload),
            default => throw new \DomainException(
                'Domain transfer phase must be prepare, commit or abort.'
            ),
        };
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function prepareDomainTransfer(array $payload): array
    {
        $this->assertPayloadBudget($payload, self::MAX_REQUEST_BYTES, 'Domain transfer preparation');
        if (($payload['confirm'] ?? false) !== true) {
            throw new \DomainException(
                'Domain transfer requires explicit administrator confirmation.'
            );
        }
        $domain = $this->normalizeDomain((string)($payload['domain'] ?? ''));
        $from = \strtolower(\trim((string)($payload['from_project_uuid'] ?? '')));
        $to = \strtolower(\trim((string)($payload['to_project_uuid'] ?? '')));
        if (!$this->validProjectUuid($from)
            || !$this->validProjectUuid($to)
            || \hash_equals($from, $to)
        ) {
            throw new \DomainException(
                'Domain transfer requires distinct valid source and target project UUIDs.'
            );
        }
        if (!\is_array($this->state['enrollments'][$from] ?? null)
            || !\is_array($this->state['enrollments'][$to] ?? null)
        ) {
            throw new \DomainException(
                'Both domain transfer projects must have active enrollments.'
            );
        }
        $this->assertDomainsAuthorized($to, [['domain' => $domain]]);
        $sourceRoute = null;
        foreach ((array)($this->state['routes'] ?? []) as $route) {
            if (!\is_array($route)) {
                continue;
            }
            $routeDomain = (string)($route['domain'] ?? '');
            if (!$this->domainsOverlap($domain, $routeDomain)) {
                continue;
            }
            if (!\hash_equals($from, (string)($route['project_uuid'] ?? ''))
                || !\hash_equals($domain, $routeDomain)
            ) {
                throw new \DomainException(
                    'Domain transfer overlaps another exact or wildcard route.'
                );
            }
            if ($sourceRoute !== null) {
                throw new \DomainException(
                    'Domain transfer source ownership is ambiguous.'
                );
            }
            $sourceRoute = $route;
        }
        $sourceCompacted = false;
        if (!\is_array($sourceRoute)) {
            $ownership = $this->state['domain_ownership'][$domain] ?? null;
            if (\is_array($ownership)
                && \hash_equals($from, (string)($ownership['project_uuid'] ?? ''))
                && \hash_equals($domain, (string)($ownership['domain'] ?? ''))
                && \preg_match(
                    '/\A[a-f0-9]{32}\z/D',
                    (string)($ownership['route_id'] ?? ''),
                ) === 1
                && (int)($ownership['route_generation'] ?? 0) > 0
            ) {
                $sourceRoute = [
                    'route_id' => (string)$ownership['route_id'],
                    'project_uuid' => $from,
                    'domain' => $domain,
                    'route_generation' => (int)$ownership['route_generation'],
                    'enrollment_security_generation' => (int)(
                        $ownership['enrollment_security_generation'] ?? 0
                    ),
                    'domain_security_generation' => (int)(
                        $ownership['domain_security_generation'] ?? 0
                    ),
                    'status' => 'COMPACTED',
                ];
                $sourceCompacted = true;
            }
        }
        if (!\is_array($sourceRoute) || !$this->routeAllowedBySecurity($sourceRoute)) {
            throw new \DomainException(
                'The source project does not retain a transferable domain owner fence.'
            );
        }
        foreach ((array)($this->state['transfers'] ?? []) as $transfer) {
            if (\is_array($transfer)
                && $this->domainsOverlap($domain, (string)($transfer['domain'] ?? ''))
                && \in_array(
                    (string)($transfer['status'] ?? ''),
                    ['PREPARED', 'STAGED'],
                    true,
                )
                && $this->transferLeaseValid($transfer)
            ) {
                throw new \DomainException(
                    'Another live transfer already fences this domain.'
                );
            }
        }
        $transferId = \bin2hex(\random_bytes(16));
        $transfer = [
            'transfer_id' => $transferId,
            'domain' => $domain,
            'from_project_uuid' => $from,
            'to_project_uuid' => $to,
            'source_route_id' => (string)($sourceRoute['route_id'] ?? ''),
            'source_route_generation' => (int)($sourceRoute['route_generation'] ?? 0),
            'source_compacted' => $sourceCompacted,
            'source_certificate_digest' => (string)(
                $sourceRoute['certificate']['snapshot_digest'] ?? ''
            ),
            'from_security_generation' => (int)(
                $this->state['enrollments'][$from]['security_generation'] ?? 0
            ),
            'to_security_generation' => (int)(
                $this->state['enrollments'][$to]['security_generation'] ?? 0
            ),
            'status' => 'PREPARED',
            'created_at' => \gmdate(DATE_ATOM),
            'expires_at' => \time() + 300,
            'expires_monotonic' => $this->monotonicNow() + 300.0,
            'lease_boot_id' => $this->hostBootId,
        ];
        $this->state['transfers'][$transferId] = $transfer;
        $this->persistState();
        $this->journal('domain_transfer_prepared', [
            'transfer_id' => $transferId,
            'domain' => $domain,
            'from_project_uuid' => $from,
            'to_project_uuid' => $to,
        ]);
        return [
            'accepted' => true,
            'transfer_id' => $transferId,
            'domain' => $domain,
            'expires_at' => (int)$transfer['expires_at'],
        ];
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function stageDomainTransfer(array $payload): array
    {
        $deadlineMonotonic = $this->monotonicNow() + self::REGISTRATION_BUDGET_SECONDS;
        $this->assertPayloadBudget($payload, self::MAX_REQUEST_BYTES, 'Domain transfer staging');
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        $transferId = \strtolower(\trim((string)($payload['transfer_id'] ?? '')));
        $registration = \is_array($payload['registration'] ?? null)
            ? $payload['registration']
            : [];
        $transfer = \is_array($this->state['transfers'][$transferId] ?? null)
            ? $this->state['transfers'][$transferId]
            : null;
        if (!\is_array($transfer)
            || !\preg_match('/\A[a-f0-9]{32}\z/D', $transferId)
            || !\hash_equals((string)($transfer['to_project_uuid'] ?? ''), $projectUuid)
            || !\in_array(
                (string)($transfer['status'] ?? ''),
                ['PREPARED', 'STAGED'],
                true,
            )
            || !$this->transferLeaseValid($transfer)
        ) {
            throw new \DomainException(
                'Domain transfer ticket is unknown, expired or belongs to another project.'
            );
        }
        $projectRootInput = \trim((string)($registration['project_root'] ?? ''));
        if ($projectRootInput === '' || \strlen($projectRootInput) > 4096) {
            throw new \DomainException('Transfer project root is missing or too long.');
        }
        $projectRoot = $this->canonicalDirectory($projectRootInput);
        $instanceId = \trim((string)($registration['instance_id'] ?? ''));
        $projectGeneration = (int)($registration['project_generation'] ?? 0);
        $projectDigest = \strtolower(\trim((string)(
            $registration['request_digest'] ?? ''
        )));
        $idempotencyKey = \strtolower(\trim((string)($registration['idempotency_key'] ?? '')));
        $instanceGeneration = (int)($registration['instance_generation'] ?? 0);
        $instanceDigest = \strtolower(\trim((string)(
            $registration['instance_digest'] ?? ''
        )));
        $masterEpoch = (int)($registration['master_epoch'] ?? 0);
        $launchId = \strtolower(\trim((string)($registration['launch_id'] ?? '')));
        if (!\hash_equals(
            $projectUuid,
            \strtolower(\trim((string)($registration['project_uuid'] ?? ''))),
        )
            || $instanceId === ''
            || \strlen($instanceId) > self::MAX_INSTANCE_ID_BYTES
            || \preg_match('/\A[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}\z/D', $instanceId) !== 1
            || $projectGeneration < 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $projectDigest) !== 1
            || \preg_match('/\A[a-f0-9]{40}\z/D', $idempotencyKey) !== 1
            || $instanceGeneration < 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $instanceDigest) !== 1
            || $masterEpoch < 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $launchId) !== 1
        ) {
            throw new \DomainException(
                'Transfer target registration identity is incomplete.'
            );
        }
        $gatewayEpoch = \trim((string)($registration['gateway_epoch'] ?? ''));
        if ($gatewayEpoch !== ''
            && !\hash_equals((string)$this->state['epoch'], $gatewayEpoch)
        ) {
            throw new \DomainException(
                'Gateway epoch changed during domain transfer staging.'
            );
        }
        $peer = \is_array($payload['_broker_peer'] ?? null)
            ? $payload['_broker_peer']
            : [];
        $this->assertEnrollment($projectUuid, $projectRoot, $peer);
        if ((int)($this->state['enrollments'][$projectUuid]['security_generation'] ?? 0)
            !== (int)($transfer['to_security_generation'] ?? -1)
        ) {
            throw new \DomainException(
                'Target enrollment changed after domain transfer preparation.'
            );
        }
        $existingProject = \is_array($this->state['projects'][$projectUuid] ?? null)
            ? $this->state['projects'][$projectUuid]
            : [];
        $existingProjectGeneration = (int)($existingProject['generation'] ?? 0);
        if ($existingProjectGeneration > 0
            && ($projectGeneration !== $existingProjectGeneration
                || !\hash_equals((string)($existingProject['digest'] ?? ''), $projectDigest)
                || !\hash_equals(
                    (string)($existingProject['idempotency_key'] ?? ''),
                    $idempotencyKey,
                ))
        ) {
            throw new \DomainException(
                'Transfer proof cannot advance or replace target global desired state.'
            );
        }
        $existingInstance = \is_array(
            $this->state['instances'][$projectUuid][$instanceId] ?? null
        ) ? $this->state['instances'][$projectUuid][$instanceId] : [];
        if ($existingInstance !== []
            && ($instanceGeneration !== (int)($existingInstance['generation'] ?? 0)
                || !\hash_equals((string)($existingInstance['digest'] ?? ''), $instanceDigest)
                || $masterEpoch !== (int)($existingInstance['master_epoch'] ?? 0)
                || !\hash_equals((string)($existingInstance['launch_id'] ?? ''), $launchId))
        ) {
            throw new \DomainException(
                'Transfer proof cannot advance or replace target instance desired state.'
            );
        }
        if ($existingProject === []
            && \count((array)($this->state['projects'] ?? [])) >= self::MAX_PROJECTS
        ) {
            throw new \DomainException('Gateway project quota would be exceeded.');
        }
        if ($existingInstance === []) {
            $projectInstances = (array)($this->state['instances'][$projectUuid] ?? []);
            if (\count($projectInstances) >= self::MAX_INSTANCES_PER_PROJECT) {
                throw new \DomainException('Project instance quota would be exceeded.');
            }
            $totalInstances = 0;
            foreach ((array)($this->state['instances'] ?? []) as $instances) {
                $totalInstances += \count((array)$instances);
            }
            if ($totalInstances >= self::MAX_TOTAL_INSTANCES) {
                throw new \DomainException('Gateway instance quota would be exceeded.');
            }
        }
        $stagingDigest = \hash('sha256', $this->canonicalJson($registration));
        if ((string)($transfer['status'] ?? '') === 'STAGED') {
            if (!\hash_equals((string)($transfer['staging_digest'] ?? ''), $stagingDigest)) {
                throw new \DomainException(
                    'A staged transfer cannot be replaced by a different registration proof.'
                );
            }
            return [
                'accepted' => true,
                'idempotent' => true,
                'transfer_id' => $transferId,
                'status' => 'STAGED',
            ];
        }
        $matching = [];
        $routePayloads = \is_array($registration['routes'] ?? null)
            ? $registration['routes']
            : [];
        if (\count($routePayloads) !== 1) {
            throw new \DomainException(
                'Transfer registration must contain exactly one route proof.'
            );
        }
        foreach ($routePayloads as $routePayload) {
            if (!\is_array($routePayload)) {
                continue;
            }
            if (\hash_equals(
                (string)$transfer['domain'],
                $this->normalizeDomain((string)($routePayload['domain'] ?? '')),
            )) {
                $matching[] = $routePayload;
            }
        }
        if (\count($matching) !== 1) {
            throw new \DomainException(
                'Transfer target registration must prove exactly one matching domain route.'
            );
        }
        // Reject an unauthorized target before contacting its listener or
        // asking the Broker to snapshot project-controlled certificate files.
        $this->assertDomainsAuthorized($projectUuid, [[
            'domain' => (string)$transfer['domain'],
        ]]);
        $this->beginCertificateSnapshotBatch();
        try {
            $candidate = $this->validateRoute(
                $matching[0],
                $projectUuid,
                $projectRoot,
                $instanceId,
                $instanceGeneration,
                $masterEpoch,
                $launchId,
                $deadlineMonotonic,
            );
            $this->assertRetainedRouteCapacity([(string)$candidate['route_id']]);
            if (($candidate['force_root_to_www'] ?? false) === true) {
                // A transfer carries one route proof, so its fixed redirect
                // target must already be a live registration of the same
                // target project. Never synthesize a client-controlled host.
                if ($this->registeredWwwRedirectTarget($candidate) === null) {
                    throw new \DomainException(
                        'force_root_to_www target is not currently serviceable over HTTPS.'
                    );
                }
            }
            if ((string)$candidate['status'] !== 'ACTIVE'
                || !$this->certificateSnapshotValidForDomain(
                    (array)($candidate['certificate'] ?? []),
                    (string)$transfer['domain'],
                )
            ) {
                throw new \DomainException(
                    'Transfer target must prove a valid certificate and healthy authenticated backend.'
                );
            }
            $candidate['instances'] = [
            $instanceId => [
                'instance_id' => $instanceId,
                'generation' => $instanceGeneration,
                'digest' => $instanceDigest,
                'master_epoch' => $masterEpoch,
                'launch_id' => $launchId,
                'backends' => $candidate['backends'],
                'backend_identity' => $candidate['backend_identity'],
                'backend_healthy' => true,
                'status' => 'ACTIVE',
                'last_heartbeat' => \time(),
                'last_heartbeat_monotonic' => $this->monotonicNow(),
                'lease_boot_id' => $this->hostBootId,
                'drain_until' => null,
                'drain_until_monotonic' => null,
            ],
            ];
            $transfer['status'] = 'STAGED';
            $transfer['staged_at'] = \gmdate(DATE_ATOM);
            $transfer['staging_digest'] = $stagingDigest;
            $transfer['candidate'] = $candidate;
            $transfer['target_project'] = [
            'project_uuid' => $projectUuid,
            'project_root' => $projectRoot,
            'generation' => $projectGeneration,
            'digest' => $projectDigest,
            'idempotency_key' => $idempotencyKey,
            ];
            $transfer['target_instance'] = [
            'instance_id' => $instanceId,
            'generation' => $instanceGeneration,
            'digest' => $instanceDigest,
            'master_epoch' => $masterEpoch,
            'launch_id' => $launchId,
            'last_heartbeat' => \time(),
            'last_heartbeat_monotonic' => $this->monotonicNow(),
            'lease_boot_id' => $this->hostBootId,
            'registered_at' => \gmdate(DATE_ATOM),
            ];
            $this->state['transfers'][$transferId] = $transfer;
            $this->persistState();
            $this->journal('domain_transfer_staged', [
                'transfer_id' => $transferId,
                'domain' => (string)$transfer['domain'],
                'to_project_uuid' => $projectUuid,
            ]);
            $this->commitCertificateSnapshotBatch();
            return [
                'accepted' => true,
                'transfer_id' => $transferId,
                'status' => 'STAGED',
            ];
        } catch (\Throwable $throwable) {
            $this->abortCertificateSnapshotBatch();
            throw $throwable;
        }
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function commitDomainTransfer(array $payload): array
    {
        $deadlineMonotonic = $this->monotonicNow() + self::REGISTRATION_BUDGET_SECONDS;
        $this->assertPayloadBudget($payload, self::MAX_REQUEST_BYTES, 'Domain transfer commit');
        if (($payload['confirm'] ?? false) !== true) {
            throw new \DomainException(
                'Domain transfer commit requires explicit administrator confirmation.'
            );
        }
        $transferId = \strtolower(\trim((string)($payload['transfer_id'] ?? '')));
        $transfer = \is_array($this->state['transfers'][$transferId] ?? null)
            ? $this->state['transfers'][$transferId]
            : null;
        if (\is_array($transfer)
            && (string)($transfer['status'] ?? '') === 'COMMITTED'
        ) {
            return [
                'accepted' => true,
                'idempotent' => true,
                'transfer_id' => $transferId,
                'generation' => (int)($transfer['committed_generation'] ?? 0),
            ];
        }
        if (!\is_array($transfer)
            || (string)($transfer['status'] ?? '') !== 'STAGED'
            || !$this->transferLeaseValid($transfer)
        ) {
            throw new \DomainException(
                'Domain transfer is not staged or its ticket expired.'
            );
        }
        $from = (string)$transfer['from_project_uuid'];
        $to = (string)$transfer['to_project_uuid'];
        $domain = (string)$transfer['domain'];
        $sourceRouteId = (string)$transfer['source_route_id'];
        $sourceCompacted = ($transfer['source_compacted'] ?? false) === true;
        if ($sourceCompacted) {
            $ownership = $this->state['domain_ownership'][$domain] ?? null;
            $source = \is_array($ownership) ? [
                'route_id' => (string)($ownership['route_id'] ?? ''),
                'project_uuid' => (string)($ownership['project_uuid'] ?? ''),
                'domain' => (string)($ownership['domain'] ?? ''),
                'route_generation' => (int)($ownership['route_generation'] ?? 0),
                'enrollment_security_generation' => (int)(
                    $ownership['enrollment_security_generation'] ?? 0
                ),
                'domain_security_generation' => (int)(
                    $ownership['domain_security_generation'] ?? 0
                ),
                'status' => 'COMPACTED',
            ] : null;
        } else {
            $source = \is_array($this->state['routes'][$sourceRouteId] ?? null)
                ? $this->state['routes'][$sourceRouteId]
                : null;
        }
        $candidate = \is_array($transfer['candidate'] ?? null)
            ? $transfer['candidate']
            : null;
        if (!\is_array($source)
            || !\is_array($candidate)
            || !\hash_equals($from, (string)($source['project_uuid'] ?? ''))
            || !\hash_equals($domain, (string)($source['domain'] ?? ''))
            || !\hash_equals($sourceRouteId, (string)($source['route_id'] ?? ''))
            || (int)($source['route_generation'] ?? 0)
                !== (int)($transfer['source_route_generation'] ?? -1)
            || (!$sourceCompacted
                && !\in_array(
                    (string)($source['status'] ?? ''),
                    ['ACTIVE', 'DRAINING', 'STALE', 'PENDING_BACKEND', 'PENDING_CERTIFICATE', 'REMOVED'],
                    true,
                ))
            || !$this->routeAllowedBySecurity($source)
            || (int)($this->state['enrollments'][$from]['security_generation'] ?? 0)
                !== (int)($transfer['from_security_generation'] ?? -1)
            || (int)($this->state['enrollments'][$to]['security_generation'] ?? 0)
                !== (int)($transfer['to_security_generation'] ?? -1)
        ) {
            throw new \DomainException(
                'Domain transfer ownership or enrollment fence changed before commit.'
            );
        }
        // Staging can outlive unrelated serialized registrations. Recheck the
        // retained-key union immediately before the irreversible ownership
        // transaction so a queued transfer cannot overflow the host route
        // state after its initial proof was accepted.
        $this->assertRetainedRouteCapacity([(string)($candidate['route_id'] ?? '')]);
        $failureKind = null;
        if ($this->probeBackends(
            (array)($candidate['backends'] ?? []),
            (array)($candidate['backend_identity'] ?? []),
            false,
            $failureKind,
            $deadlineMonotonic,
        ) !== 'HEALTHY' || !$this->certificateSnapshotValidForDomain(
            (array)($candidate['certificate'] ?? []),
            $domain,
        )) {
            throw new \DomainException(
                'Domain transfer target proof is no longer healthy at commit.'
            );
        }
        $this->assertCertificateProgression(
            $to,
            $domain,
            (array)($candidate['certificate'] ?? []),
        );
        $this->assertDeadlineAvailable($deadlineMonotonic, 'Domain transfer commit');

        $securityKind = 'DOMAIN_TRANSFER';
        $securityIntent = \hash('sha256', $this->canonicalJson([
            'kind' => $securityKind,
            'transfer_id' => $transferId,
            'domain' => $domain,
            'from_project_uuid' => $from,
            'to_project_uuid' => $to,
            'source_route_id' => $sourceRouteId,
            'source_route_generation' => (int)$transfer['source_route_generation'],
            'source_compacted' => $sourceCompacted,
            'from_security_generation' => (int)$transfer['from_security_generation'],
            'to_security_generation' => (int)$transfer['to_security_generation'],
            'candidate_digest' => \hash('sha256', $this->canonicalJson($candidate)),
            'administrator_confirmed' => true,
        ]));
        $securityTransactionId = \substr(\hash(
            'sha256',
            "wls-security-tx/1\0{$securityKind}\0{$securityIntent}",
        ), 0, 32);
        $reservation = $this->reserveSecurityMutation(
            $securityTransactionId,
            $securityIntent,
            $securityKind,
        );
        $tombstoneGeneration = (int)$reservation['assigned'];
        $this->state['security_transactions'][$securityTransactionId] = [
            'schema_version' => 1,
            'transaction_id' => $securityTransactionId,
            'intent_digest' => $securityIntent,
            'kind' => $securityKind,
            'assigned_generation' => $tombstoneGeneration,
            'phase' => 'RESERVED',
            'updated_at' => \gmdate(DATE_ATOM),
        ];
        $this->persistSecurityLedger();
        $this->persistState();
        $this->beginRoutingMutation('domain-transfer:' . $domain);
        $securityLedgerCommitted = false;
        try {
            $this->applyCommittedDomainTransfer(
                $transferId,
                $transfer,
                $candidate,
                $tombstoneGeneration,
            );
            $this->markPublicationIrrevocableSecurity();
            $this->state['security_transactions'][$securityTransactionId]['phase']
                = 'COMMITTED';
            $this->state['security_transactions'][$securityTransactionId]['updated_at']
                = \gmdate(DATE_ATOM);
            $this->persistSecurityLedger();
            $securityLedgerCommitted = true;
            $this->commitSecurityMutation(
                $securityTransactionId,
                $securityIntent,
                $securityKind,
                $tombstoneGeneration,
            );
            $this->bumpGeneration('domain_transfer_committed', [
                'transfer_id' => $transferId,
                'domain' => $domain,
                'from_project_uuid' => $from,
                'to_project_uuid' => $to,
                'tombstone_generation' => $tombstoneGeneration,
            ]);
            $this->configDirty = true;
            if (!$this->publishIfDirty()) {
                throw new \DomainException(
                    'Domain ownership changed, but the target gateway config failed.'
                );
            }
            return [
                'accepted' => true,
                'transfer_id' => $transferId,
                'domain' => $domain,
                'from_project_uuid' => $from,
                'to_project_uuid' => $to,
                'generation' => (int)$this->state['generation'],
            ];
        } catch (\Throwable $throwable) {
            if (!$securityLedgerCommitted) {
                try {
                    $abortReceipt = $this->abortSecurityMutation(
                        $securityTransactionId,
                        $securityIntent,
                        $securityKind,
                        $tombstoneGeneration,
                    );
                    $this->state['security_transactions'][$securityTransactionId]['phase']
                        = 'ABORTED';
                    $this->state['security_transactions'][$securityTransactionId]['receipt']
                        = $abortReceipt;
                    $this->state['security_transactions'][$securityTransactionId]['updated_at']
                        = \gmdate(DATE_ATOM);
                    $this->persistSecurityLedger();
                } catch (\Throwable) {
                }
            }
            $reason = 'Domain transfer failed closed: ' . $throwable->getMessage();
            try {
                $this->failClosedSecurityMutation(
                    $reason,
                    !$securityLedgerCommitted,
                );
            } catch (\Throwable $failClosedError) {
                $this->stopDataPlane();
                $this->completePublication();
                throw new \RuntimeException(
                    $reason . ' The fail-closed state could not be persisted: '
                        . $failClosedError->getMessage(),
                    0,
                    $throwable,
                );
            }
            throw new \DomainException(
                $reason . ' The data plane was stopped.',
                0,
                $throwable,
            );
        }
    }

    /**
     * Apply the already-proven transfer as one in-memory desired-state
     * generation. Persistence/publication is deliberately owned by the
     * caller so no observer can see an intermediate dual-owner state.
     *
     * @param array<string,mixed> $transfer
     * @param array<string,mixed> $candidate
     */
    private function applyCommittedDomainTransfer(
        string $transferId,
        array $transfer,
        array $candidate,
        int $tombstoneGeneration,
    ): void {
        $from = (string)$transfer['from_project_uuid'];
        $to = (string)$transfer['to_project_uuid'];
        $domain = (string)$transfer['domain'];
        $sourceRouteId = (string)$transfer['source_route_id'];
        $this->state['security']['tombstones']['domain:' . $domain] = [
            'kind' => 'domain_transfer',
            'domain' => $domain,
            'from_project_uuid' => $from,
            'to_project_uuid' => $to,
            'source_route_id' => $sourceRouteId,
            'generation' => $tombstoneGeneration,
            'created_at' => \gmdate(DATE_ATOM),
        ];
        if (\is_array($this->state['routes'][$sourceRouteId] ?? null)) {
            $this->enforceRemovedRoute($this->state['routes'][$sourceRouteId], \time());
            $this->state['routes'][$sourceRouteId]['security_tombstone_generation']
                = $tombstoneGeneration;
        }
        $candidate['domain_security_generation'] = $tombstoneGeneration;
        $candidate['route_generation'] = \max(
            1,
            (int)($candidate['route_generation'] ?? 0),
        );
        $candidate['updated_at'] = \gmdate(DATE_ATOM);
        $targetRouteId = (string)$candidate['route_id'];
        $this->state['routes'][$targetRouteId] = $candidate;
        $this->retainRouteSecurityClosure(
            $this->state['routes'][$targetRouteId],
            true,
            'ACTIVE',
        );

        $targetProject = \is_array($this->state['projects'][$to] ?? null)
            ? $this->state['projects'][$to]
            : [
                'project_uuid' => $to,
                'project_root' => (string)($transfer['target_project']['project_root'] ?? ''),
                'generation' => 0,
                'digest' => '',
                'idempotency_key' => '',
                'route_ids' => [],
                'registered_at' => \gmdate(DATE_ATOM),
                'transfer_only' => true,
            ];
        $existingTargetRouteIds = (array)(
            $this->state['projects'][$to]['route_ids'] ?? []
        );
        $targetProject['route_ids'] = \array_values(\array_unique([
            ...\array_map('strval', $existingTargetRouteIds),
            $targetRouteId,
        ]));
        $this->state['projects'][$to] = $targetProject;
        $targetInstance = (array)$transfer['target_instance'];
        $targetInstanceId = (string)$targetInstance['instance_id'];
        if (\is_array($this->state['instances'][$to][$targetInstanceId] ?? null)) {
            $this->state['instances'][$to][$targetInstanceId]['last_heartbeat'] = \time();
            $this->state['instances'][$to][$targetInstanceId]['last_heartbeat_monotonic']
                = $this->monotonicNow();
            $this->state['instances'][$to][$targetInstanceId]['lease_boot_id']
                = $this->hostBootId;
        } else {
            $targetInstance['transfer_only'] = true;
            $this->state['instances'][$to][$targetInstanceId] = $targetInstance;
        }
        if (\is_array($this->state['projects'][$from] ?? null)) {
            $sourceRouteIds = \array_map(
                'strval',
                (array)($this->state['projects'][$from]['route_ids'] ?? []),
            );
            $this->state['projects'][$from]['route_ids'] = \array_values(
                \array_filter(
                    $sourceRouteIds,
                    static fn (string $routeId): bool => $routeId !== $sourceRouteId,
                )
            );
        }
        foreach ((array)($this->state['acme_challenges'] ?? []) as $leaseId => $lease) {
            if (\is_array($lease)
                && \hash_equals($from, (string)($lease['project_uuid'] ?? ''))
                && \hash_equals($domain, (string)($lease['domain'] ?? ''))
            ) {
                unset($this->state['acme_challenges'][$leaseId]);
            }
        }
        $this->state['transfers'][$transferId]['status'] = 'COMMITTED';
        $this->state['transfers'][$transferId]['committed_generation']
            = $tombstoneGeneration;
        $this->state['transfers'][$transferId]['committed_at'] = \gmdate(DATE_ATOM);
        unset($this->state['transfers'][$transferId]['candidate']);
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function abortDomainTransfer(array $payload): array
    {
        $transferId = \strtolower(\trim((string)($payload['transfer_id'] ?? '')));
        $transfer = $this->state['transfers'][$transferId] ?? null;
        if (!\is_array($transfer)) {
            return ['accepted' => true, 'idempotent' => true];
        }
        if ((string)($transfer['status'] ?? '') === 'COMMITTED') {
            throw new \DomainException(
                'A committed domain transfer cannot be aborted.'
            );
        }
        unset($this->state['transfers'][$transferId]);
        $this->persistState();
        $this->journal('domain_transfer_aborted', ['transfer_id' => $transferId]);
        return ['accepted' => true, 'transfer_id' => $transferId];
    }

    /**
     * @param array<string,mixed> $transfer
     */
    private function transferLeaseValid(array $transfer): bool
    {
        return \hash_equals(
            $this->hostBootId,
            (string)($transfer['lease_boot_id'] ?? ''),
        ) && (float)($transfer['expires_monotonic'] ?? 0.0) > $this->monotonicNow();
    }

    /**
     * @param array<string,mixed> $certificate
     */
    private function certificateSnapshotAvailable(array $certificate): bool
    {
        $digest = \strtolower(\trim((string)(
            $certificate['snapshot_digest'] ?? ''
        )));
        $cert = (string)($certificate['cert_path'] ?? '');
        $key = (string)($certificate['key_path'] ?? '');
        $root = $this->home . DIRECTORY_SEPARATOR . 'snapshots'
            . DIRECTORY_SEPARATOR . $digest;
        return ($certificate['valid'] ?? false) === true
            && \preg_match('/\A[a-f0-9]{64}\z/D', $digest) === 1
            && $this->snapshotBundleValid($root, $digest)
            && $this->sameBoundaryPath(
                $cert,
                $root . DIRECTORY_SEPARATOR . 'fullchain.pem',
            )
            && $this->sameBoundaryPath(
                $key,
                $root . DIRECTORY_SEPARATOR . 'privkey.pem',
            );
    }

    /** @param array<string,mixed> $certificate */
    private function certificateSnapshotValidForDomain(
        array $certificate,
        string $domain,
    ): bool {
        if (!$this->certificateSnapshotAvailable($certificate)) {
            return false;
        }
        $digest = (string)$certificate['snapshot_digest'];
        $root = $this->home . DIRECTORY_SEPARATOR . 'snapshots'
            . DIRECTORY_SEPARATOR . $digest;
        try {
            $certPem = $this->readStableRegularFile(
                $root . DIRECTORY_SEPARATOR . 'fullchain.pem',
                2 * 1024 * 1024,
                'Gateway certificate snapshot validity check',
            );
            $normalizedBundle = $this->normalizeAndValidateCertificateChain(
                $certPem,
                '',
            );
            $manifest = \json_decode($this->readStableRegularFile(
                $root . DIRECTORY_SEPARATOR . 'manifest.json',
                65_536,
                'Gateway certificate snapshot validity manifest',
            ), true);
            $payload = \is_array($manifest['payload'] ?? null)
                ? $manifest['payload']
                : [];
            $x509 = @\openssl_x509_read($normalizedBundle['leaf']);
            $parsed = $x509 !== false ? @\openssl_x509_parse($x509, false) : false;
            if (!\is_array($parsed)) {
                return false;
            }
            $notBefore = (int)($parsed['validFrom_time_t'] ?? PHP_INT_MAX);
            $notAfter = (int)($parsed['validTo_time_t'] ?? 0);
            return $notBefore <= \time()
                && $notAfter > \time()
                && $notAfter === (int)($certificate['not_after'] ?? 0)
                && $notAfter === (int)($payload['not_after'] ?? 0)
                && \hash_equals($digest, (string)($payload['source_digest'] ?? ''))
                && $this->certificateCoversDomain($parsed, $domain);
        } catch (\Throwable) {
            return false;
        }
    }

    /** @param array<string,mixed> $certificate */
    private function certificateStateValidForLkg(array $certificate, string $domain): bool
    {
        if (($certificate['valid'] ?? false) === true) {
            return \hash_equals('active', $this->certificateLifecycleState($certificate))
                && ($certificate['pending'] ?? true) === false
                && $this->certificateSnapshotValidForDomain($certificate, $domain);
        }
        if (($certificate['pending'] ?? false) !== true) {
            return false;
        }
        if ((string)($certificate['snapshot_digest'] ?? '') !== ''
            || (string)($certificate['cert_path'] ?? '') !== ''
            || (string)($certificate['key_path'] ?? '') !== ''
            || \str_starts_with($domain, '*.')
        ) {
            return false;
        }
        $state = $this->certificateLifecycleState($certificate);
        $generation = (int)($certificate['generation'] ?? -1);
        $sourceDigest = (string)($certificate['source_digest'] ?? '');
        if ($state === 'pending') {
            return $generation === 0
                && \hash_equals(
                    \hash('sha256', "wls-pending-certificate\0" . $domain),
                    $sourceDigest,
                );
        }
        return $state === 'disabled'
            && $generation >= 1
            && \hash_equals(
                \hash(
                    'sha256',
                    "wls-disabled-certificate\0" . $domain . "\0" . $generation,
                ),
                $sourceDigest,
            );
    }

    /** @param array<string,mixed> $certificate */
    private function certificateLifecycleState(array $certificate): string
    {
        $explicit = \strtolower(\trim((string)($certificate['state'] ?? '')));
        if (\in_array($explicit, ['active', 'pending', 'disabled'], true)) {
            return $explicit;
        }
        $generation = (int)($certificate['generation'] ?? -1);
        if (($certificate['valid'] ?? false) === true && $generation >= 1) {
            return 'active';
        }
        if (($certificate['pending'] ?? false) === true && $generation === 0) {
            return 'pending';
        }
        return '';
    }

    /** @return list<string> */
    private function boundedDirectoryEntries(
        string $directory,
        int $maximumEntries,
        string $label,
    ): array {
        $status = @\lstat($directory);
        if ($maximumEntries < 1
            || !\is_array($status)
            || \is_link($directory)
            || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
        ) {
            throw new \RuntimeException($label . ' is missing or unsafe.');
        }
        $entries = [];
        try {
            $iterator = new \FilesystemIterator(
                $directory,
                \FilesystemIterator::SKIP_DOTS,
            );
            foreach ($iterator as $item) {
                if (\count($entries) >= $maximumEntries) {
                    throw new \RuntimeException(
                        $label . ' exceeds its directory entry limit.'
                    );
                }
                $entries[] = $item->getFilename();
            }
        } catch (\UnexpectedValueException $exception) {
            throw new \RuntimeException(
                $label . ' cannot be inspected safely.',
                0,
                $exception,
            );
        }
        return $entries;
    }

    private function directoryHasEntries(string $directory): bool
    {
        $status = @\lstat($directory);
        if (!\is_array($status)
            || \is_link($directory)
            || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
        ) {
            return false;
        }
        try {
            foreach (new \FilesystemIterator(
                $directory,
                \FilesystemIterator::SKIP_DOTS,
            ) as $_item) {
                return true;
            }
        } catch (\UnexpectedValueException) {
            return true;
        }
        return false;
    }

    private function snapshotBundleValid(string $directory, string $digest): bool
    {
        $snapshotRoot = $this->home . DIRECTORY_SEPARATOR . 'snapshots';
        $directoryStatus = @\lstat($directory);
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $digest) !== 1
            || !\is_array($directoryStatus)
            || ((((int)($directoryStatus['mode'] ?? 0)) & 0170000) !== 0040000)
            || \is_link($directory)
            || !$this->sameBoundaryPath(
                $directory,
                $snapshotRoot . DIRECTORY_SEPARATOR . $digest,
            )
            || (\PHP_OS_FAMILY !== 'Windows'
                && ((((int)($directoryStatus['mode'] ?? 0)) & 0777) !== 0700))
        ) {
            return false;
        }
        try {
            $leaves = $this->boundedDirectoryEntries(
                $directory,
                3,
                'Certificate snapshot directory',
            );
        } catch (\Throwable) {
            return false;
        }
        \sort($leaves, SORT_STRING);
        if ($leaves !== ['fullchain.pem', 'manifest.json', 'privkey.pem']) {
            return false;
        }
        $manifestFile = $directory . DIRECTORY_SEPARATOR . 'manifest.json';
        $cert = $directory . DIRECTORY_SEPARATOR . 'fullchain.pem';
        $key = $directory . DIRECTORY_SEPARATOR . 'privkey.pem';
        try {
            $manifestSource = $this->readStableRegularFileWithStatus(
                $manifestFile,
                65_536,
                'Certificate snapshot manifest',
            );
            $certSource = $this->readStableRegularFileWithStatus(
                $cert,
                2 * 1024 * 1024,
                'Certificate snapshot full chain',
            );
            $keySource = $this->readStableRegularFileWithStatus(
                $key,
                1024 * 1024,
                'Certificate snapshot private key',
            );
        } catch (\Throwable) {
            return false;
        }
        if (\PHP_OS_FAMILY !== 'Windows'
            && (((int)$manifestSource['status']['mode'] & 0777) !== 0600
                || ((int)$certSource['status']['mode'] & 0777) !== 0644
                || ((int)$keySource['status']['mode'] & 0777) !== 0600)
        ) {
            return false;
        }
        $decoded = \json_decode($manifestSource['contents'], true);
        $payload = \is_array($decoded['payload'] ?? null)
            ? $decoded['payload']
            : null;
        return \is_array($payload)
            && (int)($payload['schema_version'] ?? 0) === 1
            && \hash_equals($digest, (string)($payload['source_digest'] ?? ''))
            && \hash_equals(
                (string)($decoded['sha256'] ?? ''),
                \hash('sha256', $this->canonicalJson($payload)),
            )
            && \hash_equals(
                (string)($payload['fullchain_sha256'] ?? ''),
                \hash('sha256', $certSource['contents']),
            )
            && \hash_equals(
                (string)($payload['private_key_sha256'] ?? ''),
                \hash('sha256', $keySource['contents']),
            );
    }

    private function removeSnapshotDirectory(string $directory): bool
    {
        $root = $this->home . DIRECTORY_SEPARATOR . 'snapshots';
        $leaf = \basename($directory);
        $status = @\lstat($directory);
        if (!\is_array($status)) {
            return !\file_exists($directory) && !\is_link($directory);
        }
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $leaf) !== 1
            || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
            || \is_link($directory)
            || !$this->sameBoundaryPath(
                $directory,
                $root . DIRECTORY_SEPARATOR . $leaf,
            )
        ) {
            $this->observeCleanupFailure(
                'SNAPSHOT_CLEANUP_FAILED',
                'Certificate snapshot removal target is unsafe.',
            );
            return false;
        }
        if ($this->certificateSnapshotReferenced($leaf)) {
            return false;
        }
        try {
            $entries = $this->boundedDirectoryEntries(
                $directory,
                6,
                'Certificate snapshot removal directory',
            );
        } catch (\Throwable $throwable) {
            $this->observeCleanupFailure(
                'SNAPSHOT_CLEANUP_FAILED',
                $throwable->getMessage(),
            );
            return false;
        }
        $safeFiles = [];
        foreach ($entries as $entry) {
            if (!\in_array($entry, [
                'source-cert.pem',
                'source-key.pem',
                'source-chain.pem',
                'fullchain.pem',
                'privkey.pem',
                'manifest.json',
            ], true)) {
                $this->observeCleanupFailure(
                    'SNAPSHOT_CLEANUP_FAILED',
                    'Certificate snapshot contains an unknown artifact.',
                );
                return false;
            }
            $path = $directory . DIRECTORY_SEPARATOR . $entry;
            $fileStatus = @\lstat($path);
            if (!\is_array($fileStatus)
                || \is_link($path)
                || ((((int)($fileStatus['mode'] ?? 0)) & 0170000) !== 0100000)
                || (int)($fileStatus['nlink'] ?? 0) !== 1
            ) {
                $this->observeCleanupFailure(
                    'SNAPSHOT_CLEANUP_FAILED',
                    'Certificate snapshot contains a linked or special artifact.',
                );
                return false;
            }
            $safeFiles[] = $path;
        }
        foreach ($safeFiles as $path) {
            try {
                $this->removeStableRegularFile(
                    $path,
                    'Gateway certificate snapshot file',
                );
            } catch (\Throwable $throwable) {
                $this->observeCleanupFailure(
                    'SNAPSHOT_CLEANUP_FAILED',
                    $throwable->getMessage(),
                );
                return false;
            }
        }
        if (!@\rmdir($directory)) {
            $this->observeCleanupFailure(
                'SNAPSHOT_CLEANUP_FAILED',
                'Unable to remove the empty certificate snapshot directory.',
            );
            return false;
        }
        try {
            $this->syncDirectory($root);
            $this->invalidateStorageStatus();
        } catch (\Throwable $throwable) {
            $this->observeCleanupFailure(
                'SNAPSHOT_CLEANUP_FAILED',
                $throwable->getMessage(),
            );
            return false;
        }
        return true;
    }

    /**
     * @return array<string,mixed>
     */
    private function repair(array $payload = []): array
    {
        $this->assertBrokerGenerationOwnership('repair');
        if (\array_key_exists('accept_security_reset', $payload)) {
            // broker-security-v2.tsv is the monotonic root of H/K/X, P/C/Q
            // and R/T/Y authority. Clearing only the Controller projection
            // would neither revoke those Native facts nor preserve their
            // generation fence, and the next SECURITY_ATTEST would diverge.
            // A safe reset requires a future cross-platform reset-epoch
            // protocol implemented by every Native ledger scanner.
            throw new \DomainException(
                'Native Broker security reset is not supported by wls-edge/2; '
                    . 'repair cannot clear only the Controller security ledger.'
            );
        }
        if (($payload['accept_storage_recovery'] ?? false) === true) {
            $storage = $this->storageStatus(true);
            if ((int)($storage['free_bytes'] ?? -1)
                < self::MIN_MUTATION_FREE_BYTES
            ) {
                throw new \DomainException(
                    'Gateway storage is still below the safe mutation threshold.'
                );
            }
            $journalReset = ($payload['accept_journal_reset'] ?? false) === true;
            if ((\file_exists($this->journalDistrustMarkerFile())
                    || \is_link($this->journalDistrustMarkerFile()))
                && !$journalReset
            ) {
                throw new \DomainException(
                    'Gateway journal is durably untrusted; storage recovery requires '
                        . 'accept_journal_reset=true.'
                );
            }
            if ($journalReset) {
                $this->resetJournalAfterAdministratorConfirmation();
            } else {
                $this->journalTrusted = true;
                $this->initializeJournalChain();
            }
            if (!$this->journalTrusted) {
                throw new \DomainException(
                    'Gateway journal remains untrusted after storage recovery validation.'
                );
            }
            $marker = $this->diskPressureMarkerFile();
            $this->ensureRecoveryReserve();
            if ($this->securityLedgerBootstrapRequired) {
                $this->persistSecurityLedger();
                $this->securityLedgerBootstrapRequired = false;
            }
            if (\file_exists($marker) || \is_link($marker)) {
                try {
                    $this->removeStableRegularFile(
                        $marker,
                        'Gateway disk-pressure marker',
                    );
                } catch (\Throwable $throwable) {
                    throw new \DomainException(
                        'Gateway disk-pressure marker could not be cleared safely: '
                            . $throwable->getMessage(),
                    );
                }
            }
            $this->readOnlyRecoveryMode = false;
            $this->invalidateStorageStatus();
            $this->reconcileActiveRuntimeSlot();
            $this->reconcileInterruptedPublication();
            $this->state['health_state'] = 'RECOVERING';
            $this->state['recovery']['stage'] = 'STORAGE_RECOVERED';
            $this->state['recovery']['last_failure'] = '';
        }
        if (($payload['accept_clock'] ?? false) === true) {
            unset($this->state['security']['clock_untrusted_since']);
            $this->state['security']['clock_retrusted_at'] = \gmdate(DATE_ATOM);
            $this->clockWallAnchor = \time();
            $this->clockMonotonicAnchor = $this->monotonicNow();
            $this->clockStableSinceMonotonic = 0.0;
            $this->clockStatePersistPending = true;
        }
        if (($payload['retry_h3'] ?? false) === true) {
            $previousRuntime = (string)($this->state['h3_quarantined_runtime_generation'] ?? '');
            $this->state['h3_quarantined_runtime_generation'] = '';
            $this->state['h3_enabled'] = false;
            $this->state['h3_reason'] = 'Administrator requested a fresh H3 runtime probe.';
            $this->journal('h3_runtime_retry_requested', [
                'previous_runtime_generation' => $previousRuntime,
                'active_runtime_generation' => $this->activeRuntimeGeneration(),
            ]);
        }
        // Manual repair is the explicit retry path for a desired generation
        // that was held after a verified LKG rollback.
        $this->state['lkg_rollback_hold_generation'] = 0;
        $this->state['lkg_rollback_hold_since'] = 0;
        $this->state['lkg_rollback_hold_desired_digest'] = '';
        $this->state['recovery']['circuit_open_until'] = 0;
        $this->state['recovery']['circuit_open_until_monotonic'] = 0.0;
        $this->state['recovery']['circuit_boot_id'] = '';
        $this->state['recovery']['next_retry_at'] = 0;
        $this->state['recovery']['backoff_attempt'] = 0;
        $this->state['recovery']['stage'] = 'MANUAL_REPAIR';
        $this->beginRoutingMutation('manual-repair');
        try {
            $this->configDirty = true;
            $published = $this->publishIfDirty();
            if (!$published) {
                $this->restartDataPlane('manual_repair');
            }
            return $this->status();
        } catch (\Throwable $throwable) {
            $this->abortRoutingMutation(
                'Manual repair transaction aborted: ' . $throwable->getMessage()
            );
            throw $throwable;
        }
    }

    /**
     * @return array<string,mixed>
     */
    private function upgradeSnapshot(array $payload = []): array
    {
        if (($payload['activate'] ?? false) === true) {
            throw new \DomainException(
                'A/B activation is a root-owned host transaction; use server:gateway:upgrade.'
            );
        }
        return [
            'active_slot' => (string)$this->state['active_slot'],
            'previous_slot' => (string)$this->state['previous_slot'],
            'binary' => $this->nginxBinary(),
            'binary_sha256' => $this->fileHash($this->nginxBinary()),
            'healthy_since' => (int)($this->state['binary_healthy_since'] ?? 0),
            'healthy_since_monotonic' => (float)(
                $this->state['binary_healthy_since_monotonic'] ?? 0.0
            ),
            'observation_boot_id' => (string)(
                $this->state['binary_observation_boot_id'] ?? ''
            ),
            'transaction' => (array)($this->state['binary_transaction'] ?? []),
        ];
    }

    /**
     * @param array<string,mixed> $payload
     * @return array<string,mixed>
     */
    private function stopGateway(array $payload): array
    {
        if (($payload['confirm'] ?? false) !== true) {
            throw new \DomainException(
                'Gateway stop requires explicit administrator confirmation.'
            );
        }
        $active = \array_filter(
            (array)$this->state['routes'],
            static fn (mixed $route): bool => \is_array($route)
                && \in_array((string)($route['status'] ?? ''), ['ACTIVE', 'DRAINING', 'STALE'], true),
        );
        if ($active !== [] && !($payload['force'] ?? false)) {
            throw new \DomainException('Gateway has active routes; use explicit force after draining tenants.');
        }
        $this->writeAdminStoppedIntent();
        try {
            $result = $this->stopDataPlane();
            if (!($result['ok'] ?? false)) {
                throw new \RuntimeException(
                    (string)($result['message'] ?? 'Unable to stop gateway data plane.')
                );
            }
        } catch (\Throwable $throwable) {
            // The administrator's durable stop intent is authoritative even
            // when the data plane needs manual cleanup. Never silently clear
            // it and let the platform supervisor restart the gateway.
            throw $throwable;
        }
        $this->state['ready'] = false;
        $this->state['health_state'] = 'ADMIN_STOPPED';
        $this->state['admin_stopped_at'] = \gmdate(DATE_ATOM);
        $this->persistState();
        $this->journal('admin_stopped', [
            'force' => ($payload['force'] ?? false) === true,
        ]);
        $this->running = false;
        return ['accepted' => true, 'message' => 'Gateway controller and data plane are stopping.'];
    }

    private function writeAdminStoppedIntent(): void
    {
        if ($this->brokerActionsAvailable('admin')) {
            $this->brokerAction('admin', [
                'STOP',
                (string)$this->state['epoch'],
            ]);
            if (!\is_file($this->adminStoppedIntentFile())
                || \is_link($this->adminStoppedIntentFile())
            ) {
                throw new \RuntimeException(
                    'Native Broker accepted stop intent creation without publishing it.'
                );
            }
            return;
        }
        if ($this->brokerActionsRequired()) {
            throw new \RuntimeException(
                'Production gateway stop requires the native Broker stop-intent action.'
            );
        }
        $secret = \strtolower(\trim($this->readStableRegularFile(
            $this->adminTokenFile(),
            65,
            'Gateway administrator credential',
        )));
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $secret) !== 1) {
            throw new \RuntimeException(
                'Gateway administrator credential is unavailable for stop intent signing.'
            );
        }
        $key = \hex2bin($secret);
        if (!\is_string($key) || \strlen($key) !== 32) {
            throw new \RuntimeException(
                'Gateway administrator credential cannot sign the stop intent.'
            );
        }
        $payload = "WLS-ADMIN-STOPPED/1\n"
            . 'host_id=' . $this->hostId() . "\n"
            . 'epoch=' . (string)$this->state['epoch'] . "\n"
            . 'at=' . \time() . "\n"
            . 'nonce=' . \bin2hex(\random_bytes(16)) . "\n";
        $signature = \hash_hmac('sha256', $payload, $key);
        \sodium_memzero($key);
        $this->atomicWrite(
            $this->adminStoppedIntentFile(),
            $payload . 'signature=' . $signature . "\n",
            0600,
        );
    }

    private function maintenance(): void
    {
        if (!$this->brokerGenerationOwned()) {
            // The stable Launcher/Broker has advanced to a new generation.
            // Retire this orphan without reload, stop or durable writes; the
            // healthy Nginx process remains available for the new Controller
            // to adopt in place.
            $this->running = false;
            return;
        }
        $this->reapDeferredBoundedProcesses();
        $now = $this->monotonicNow();
        $this->observeWallClock();
        $storage = $this->storageStatus();
        if ($this->clockStatePersistPending
            && (bool)($storage['mutation_ready'] ?? false)
            && $now - $this->lastClockStatePersistAttemptAt >= self::HEALTH_INTERVAL
        ) {
            $this->lastClockStatePersistAttemptAt = $now;
            try {
                $this->persistState();
                $this->clockStatePersistPending = false;
            } catch (\Throwable $throwable) {
                $this->state['recovery']['stage'] = 'CLOCK_STATE_PERSIST_FAILED';
                $this->state['recovery']['last_failure']
                    = 'Clock trust transition was not persisted: '
                    . $throwable->getMessage();
            }
        }
        if (!(bool)($storage['mutation_ready'] ?? false)) {
            if (!$this->readOnlyRecoveryMode) {
                $this->markDiskPressure(
                    'DISK_PRESSURE',
                    'durable_maintenance_suspended',
                );
                $this->readOnlyRecoveryMode = true;
            } else {
                $this->state['ready'] = false;
                $this->state['health_state'] = 'DISK_PRESSURE';
                $this->state['recovery']['stage'] = 'DISK_PRESSURE';
                $this->state['recovery']['last_failure'] = 'durable_maintenance_suspended';
            }
            if ($now - $this->lastHealthAt >= self::HEALTH_INTERVAL) {
                $this->lastHealthAt = $now;
                $this->observeDataPlaneDuringDiskPressure();
                $this->pruneNonces();
            }
            return;
        }
        if ($this->leaseCheckpointDirty
            && $now - $this->lastLeaseCheckpointAt
                >= self::HEARTBEAT_CHECKPOINT_INTERVAL_SECONDS
        ) {
            try {
                $this->persistState();
            } catch (\Throwable $throwable) {
                $this->state['health_state'] = 'CONTROL_DEGRADED';
                $this->state['recovery']['stage'] = 'LEASE_CHECKPOINT_FAILED';
                $this->state['recovery']['last_failure'] = $throwable->getMessage();
            }
        }
        $this->processPendingPublication();
        if ($now - $this->lastHealthAt >= self::HEALTH_INTERVAL) {
            $this->lastHealthAt = $now;
            try {
                $this->expireLeases();
                $this->publishIfDirty();
            } catch (\Throwable $throwable) {
                $reason = 'Lease maintenance transaction aborted: ' . $throwable->getMessage();
                $this->abortRoutingMutation($reason);
                $this->recordFailure($reason);
                $this->state['health_state'] = 'CONTROL_DEGRADED';
                $this->persistState();
            }
            $this->recoverDataPlane();
            $this->pruneNonces();
            try {
                $this->compactRemovedRoutes();
            } catch (\Throwable $throwable) {
                $this->recordFailure(
                    'REMOVED route compaction was deferred: ' . $throwable->getMessage()
                );
                $this->state['health_state'] = 'CONTROL_DEGRADED';
                $this->persistState();
            }
            $this->collectSnapshots();
            if ($now - $this->lastRetentionCollectionAt
                >= self::BACKEND_PROBE_INTERVAL
            ) {
                $this->lastRetentionCollectionAt = $now;
                $beforeLkg = $this->canonicalJson((array)($this->state['lkg'] ?? []));
                try {
                    $this->collectLkgArtifacts();
                    if (!\hash_equals(
                        $beforeLkg,
                        $this->canonicalJson((array)($this->state['lkg'] ?? [])),
                    )) {
                        $this->persistState();
                    }
                } catch (\Throwable $throwable) {
                    $this->state['health_state'] = 'CONTROL_DEGRADED';
                    $this->state['recovery']['stage'] = 'LKG_RETENTION_BLOCKED';
                    $this->state['recovery']['last_failure'] = $throwable->getMessage();
                    $this->persistState();
                }
            }
        }
        if ($now - $this->lastBackendProbeAt >= self::BACKEND_PROBE_INTERVAL) {
            $this->lastBackendProbeAt = $now;
            try {
                $retryRequired = $this->probeActiveBackends();
                $this->publishIfDirty();
                if ($retryRequired) {
                    $this->lastBackendProbeAt = $this->monotonicNow()
                        - self::BACKEND_PROBE_INTERVAL
                        + self::BACKEND_PROBE_RETRY_INTERVAL;
                }
            } catch (\Throwable $throwable) {
                $reason = 'Backend probe transaction aborted: ' . $throwable->getMessage();
                $this->abortRoutingMutation($reason);
                $this->recordFailure($reason);
                $this->state['health_state'] = 'CONTROL_DEGRADED';
                $this->persistState();
            }
        }
    }

    private function observeDataPlaneDuringDiskPressure(): void
    {
        $status = $this->nginxStatus();
        $deadline = $this->monotonicNow() + self::PUBLIC_ROUTE_PROBE_BUDGET_SECONDS;
        $coreHealthy = ($status['running'] ?? false)
            && $this->publicPortsReachable(null, false, $deadline);
        $routesHealthy = $coreHealthy
            && $this->publicRoutesReachable(false, $deadline);
        if ($coreHealthy
            && !$routesHealthy
            && \hash_equals('deferred', $this->lastPublicProbeFailureKind)
        ) {
            $this->state['ready'] = ($this->state['ready'] ?? false) === true
                && $this->journalTrusted
                && !($this->state['isolation_mode'] ?? false);
            $this->state['health_state'] = 'DISK_PRESSURE';
            $this->state['recovery']['stage'] = 'DISK_PRESSURE_ROUTE_PROBE_DEFERRED';
            $this->state['recovery']['last_failure'] = 'public_route_probe_deferred';
            return;
        }
        $this->state['ready'] = $routesHealthy
            && $this->journalTrusted
            && !($this->state['isolation_mode'] ?? false);
        $this->state['health_state'] = 'DISK_PRESSURE';
        $this->state['recovery']['stage'] = $routesHealthy
            ? 'DISK_PRESSURE'
            : 'DISK_PRESSURE_DATA_PLANE_DOWN';
        if (!$routesHealthy) {
            $this->state['recovery']['last_failure']
                = (string)($status['message'] ?? 'data_plane_probe_failed_during_disk_pressure');
        }
    }

    private function expireLeases(): void
    {
        $this->beginRoutingMutation('lease-expiration');
        $now = \time();
        $monotonicNow = $this->monotonicNow();
        $changed = false;
        $stateOnlyChanged = false;
        foreach ((array)($this->state['instances'] ?? []) as $projectUuid => $instances) {
            foreach ((array)$instances as $instanceId => $instance) {
                if (!\is_array($instance)) {
                    continue;
                }
                $status = (string)($instance['status'] ?? 'ACTIVE');
                if ($status === 'DRAINING'
                    && (!$this->sameLeaseBoot($instance)
                        || (float)($instance['drain_until_monotonic'] ?? 0.0) <= $monotonicNow)
                ) {
                    // Automatic drain completion is the same irreversible
                    // lifecycle decision as explicit unregister. Persist its
                    // generation floor in the publication journal before the
                    // ordinary state drops the last instance reference.
                    $this->stageInstanceRetirementCandidate(
                        (string)$projectUuid,
                        (string)$instanceId,
                        $instance,
                    );
                    unset($this->state['instances'][$projectUuid][$instanceId]);
                    foreach ((array)$this->state['routes'] as $routeId => $route) {
                        if (\is_array($route)
                            && (string)($route['project_uuid'] ?? '') === (string)$projectUuid
                        ) {
                            unset($this->state['routes'][$routeId]['instances'][$instanceId]);
                        }
                    }
                    $changed = true;
                    continue;
                }
                if ($status === 'ACTIVE'
                    && !$this->publicationLeasePending(
                        (string)$projectUuid,
                        (string)$instanceId,
                        $instance,
                        $monotonicNow,
                    )
                    && (!$this->sameLeaseBoot($instance)
                        || ($leaseAge = $monotonicNow
                            - (float)($instance['last_heartbeat_monotonic'] ?? 0.0)) < 0.0
                        || $leaseAge >= self::HEARTBEAT_TTL)
                ) {
                    $this->state['instances'][$projectUuid][$instanceId]['status'] = 'STALE';
                    foreach ((array)$this->state['routes'] as $routeId => $route) {
                        if (\is_array($route)
                            && (string)($route['project_uuid'] ?? '') === (string)$projectUuid
                            && \is_array($route['instances'][$instanceId] ?? null)
                        ) {
                            $this->state['routes'][$routeId]['instances'][$instanceId]['status'] = 'STALE';
                        }
                    }
                    $changed = true;
                }
            }
            if (($this->state['instances'][$projectUuid] ?? []) === []) {
                unset($this->state['instances'][$projectUuid]);
            }
        }
        foreach ((array)$this->state['routes'] as $routeId => $route) {
            if (!\is_array($route)) {
                continue;
            }
            $before = $this->routeRoutingDigest($route);
            $this->selectRouteBackends($this->state['routes'][$routeId]);
            $status = (string)$this->state['routes'][$routeId]['status'];
            if ($status === 'STALE'
                && $this->routeStaleDuration(
                    $this->state['routes'][$routeId],
                    $monotonicNow,
                ) >= self::STALE_RETENTION
            ) {
                $this->enforceRemovedRoute(
                    $this->state['routes'][$routeId],
                    $now,
                );
            }
            $changed = $changed
                || $before !== $this->routeRoutingDigest($this->state['routes'][$routeId]);
        }
        foreach ((array)($this->state['acme_challenges'] ?? []) as $leaseId => $lease) {
            if (!\is_array($lease) || (int)($lease['expires_at'] ?? 0) <= $now) {
                unset($this->state['acme_challenges'][$leaseId]);
                $changed = true;
            }
        }
        foreach ((array)($this->state['transfers'] ?? []) as $transferId => $transfer) {
            if (!\is_array($transfer)) {
                unset($this->state['transfers'][$transferId]);
                $stateOnlyChanged = true;
                continue;
            }
            if (\in_array(
                (string)($transfer['status'] ?? ''),
                ['PREPARED', 'STAGED'],
                true,
            ) && !$this->transferLeaseValid($transfer)) {
                unset($this->state['transfers'][$transferId]);
                $stateOnlyChanged = true;
            }
        }
        if ($changed) {
            $this->configDirty = true;
            $this->bumpGeneration('lease_transition');
        } else {
            if ($stateOnlyChanged) {
                $this->persistState();
                $this->journal('domain_transfer_expired');
            }
            $this->completePublication();
        }
    }

    private function probeActiveBackends(): bool
    {
        $this->beginRoutingMutation('backend-probe');
        $changed = false;
        $retryRequired = false;
        /** @var list<array{route_id:string,instance_id:string,backends:array,identity:array,key:string}> $targets */
        $targets = [];
        foreach ((array)$this->state['routes'] as $routeId => $route) {
            if (!\is_array($route)
                || (string)($route['status'] ?? '') === 'REMOVED'
            ) {
                continue;
            }
            foreach ((array)($route['instances'] ?? []) as $instanceId => $instance) {
                if (!\is_array($instance)
                    || !\in_array(
                        (string)($instance['status'] ?? ''),
                        ['ACTIVE', 'STALE'],
                        true,
                    )
                ) {
                    continue;
                }
                $backends = (array)($instance['backends'] ?? []);
                $identity = (array)($instance['backend_identity'] ?? []);
                $targets[] = [
                    'route_id' => (string)$routeId,
                    'instance_id' => (string)$instanceId,
                    'backends' => $backends,
                    'identity' => $identity,
                    'key' => $this->backendProbeCacheKey($backends, $identity),
                ];
            }
        }
        if ($targets === []) {
            $this->backendProbeCursor = 0;
            $this->completePublication();
            return false;
        }

        $deadline = $this->monotonicNow() + self::MAINTENANCE_PROBE_BUDGET_SECONDS;
        $count = \count($targets);
        $index = $this->backendProbeCursor % $count;
        $visited = 0;
        $touchedRoutes = [];
        /** @var array<string,array{state:string,failure_kind:string}> $probeCache */
        $probeCache = [];
        while ($visited < $count && $this->monotonicNow() < $deadline) {
            $probeTarget = $targets[$index];
            $probeKey = $probeTarget['key'];
            if (!isset($probeCache[$probeKey])) {
                $failureKind = null;
                $probeCache[$probeKey] = [
                    'state' => $this->probeBackends(
                        $probeTarget['backends'],
                        $probeTarget['identity'],
                        false,
                        $failureKind,
                        $deadline,
                    ),
                    'failure_kind' => (string)$failureKind,
                ];
            }
            $probe = $probeCache[$probeKey];
            if ($probe['state'] === 'DEFERRED') {
                $retryRequired = true;
                break;
            }
            $routeId = $probeTarget['route_id'];
            $instanceId = $probeTarget['instance_id'];
            $routeBefore = $this->routeRoutingDigest(
                (array)($this->state['routes'][$routeId] ?? []),
            );
            $target = &$this->state['routes'][$routeId]['instances'][$instanceId];
            $retryRequired = $this->applyBackendProbeResult(
                $target,
                $probe['state'] === 'HEALTHY',
                $probe['failure_kind'],
            ) || $retryRequired;
            unset($target);
            $this->selectRouteBackends($this->state['routes'][$routeId]);
            $changed = $changed
                || $routeBefore !== $this->routeRoutingDigest($this->state['routes'][$routeId]);
            $touchedRoutes[$routeId] = true;
            ++$visited;
            $index = ($index + 1) % $count;
        }
        $sweepComplete = $visited === $count;
        $this->backendProbeCursor = $sweepComplete ? 0 : $index;
        if ($sweepComplete) {
            foreach (\array_keys($touchedRoutes) as $routeId) {
                $this->state['routes'][$routeId]['last_backend_probe'] = \time();
            }
        } else {
            $retryRequired = true;
        }
        if ($changed) {
            $this->bumpGeneration('backend_health_transition');
            $this->configDirty = true;
        } else {
            $this->persistState();
            $this->completePublication();
        }
        return $retryRequired;
    }

    /**
     * A single transport timeout cannot revoke a previously authenticated
     * backend while its independently maintained project lease is still
     * active. Repeated failures must nevertheless remove the dead listener
     * from the upstream; a live Agent heartbeat proves process intent, not
     * reachability of the exact listener lease. Identity failures remain
     * immediately fail-closed.
     *
     * @param array<string,mixed> $instance
     */
    private function applyBackendProbeResult(
        array &$instance,
        bool $healthy,
        string $failureKind,
    ): bool {
        $instance['last_backend_probe'] = \time();
        if ($healthy) {
            $instance['backend_healthy'] = true;
            $instance['backend_probe_failures'] = 0;
            $instance['backend_probe_first_failure_at'] = 0;
            $instance['last_backend_probe_success'] = \time();
            $instance['last_backend_probe_failure_kind'] = '';
            return false;
        }
        $failures = (int)($instance['backend_probe_failures'] ?? 0) + 1;
        $instance['backend_probe_failures'] = $failures;
        if ((int)($instance['backend_probe_first_failure_at'] ?? 0) < 1) {
            $instance['backend_probe_first_failure_at'] = \time();
        }
        $instance['last_backend_probe_failure_kind'] = $failureKind;
        if ($failureKind !== 'transport'
            || !($instance['backend_healthy'] ?? false)
            || $failures >= self::BACKEND_PROBE_FAST_RETRY_LIMIT
        ) {
            $instance['backend_healthy'] = false;
        }
        return $failureKind === 'transport'
            && $failures < self::BACKEND_PROBE_FAST_RETRY_LIMIT;
    }

    private function startPendingLkgObservation(?float $monotonicNow = null): void
    {
        $this->state['pending_lkg_since'] = \time();
        $this->state['pending_lkg_since_monotonic'] =
            $monotonicNow ?? $this->monotonicNow();
        $this->state['pending_lkg_boot_id'] = $this->hostBootId;
    }

    /**
     * Wall time is diagnostic only. A controller restart on the same host
     * boot preserves the observation, while a host reboot, legacy state or a
     * regressed monotonic value starts a complete fresh stability window.
     */
    private function pendingLkgObservationReady(?float $monotonicNow = null): bool
    {
        if ((int)($this->state['pending_lkg_generation'] ?? 0) < 1) {
            return false;
        }
        $monotonicNow ??= $this->monotonicNow();
        $since = (float)($this->state['pending_lkg_since_monotonic'] ?? 0.0);
        if (!\hash_equals(
                $this->hostBootId,
                (string)($this->state['pending_lkg_boot_id'] ?? ''),
            )
            || !\is_finite($since)
            || $since <= 0.0
            || $since > $monotonicNow
        ) {
            $this->startPendingLkgObservation($monotonicNow);
            return false;
        }
        return $monotonicNow - $since >= self::LKG_OBSERVATION_WINDOW;
    }

    /**
     * Ensure an A/B observation belongs to this host boot before any commit
     * or rollback-window decision. Cross-boot and legacy records restart the
     * full window instead of trusting persisted wall-clock ages.
     */
    private function reconcileBinaryObservationClock(?float $monotonicNow = null): bool
    {
        $transaction = (array)($this->state['binary_transaction'] ?? []);
        if ((string)($transaction['phase'] ?? '') !== 'OBSERVING') {
            return false;
        }
        $monotonicNow ??= $this->monotonicNow();
        $started = (float)($transaction['started_at_monotonic'] ?? 0.0);
        if (!\hash_equals(
                $this->hostBootId,
                (string)($transaction['observation_boot_id'] ?? ''),
            )
            || !\is_finite($started)
            || $started <= 0.0
            || $started > $monotonicNow
        ) {
            $wallNow = \time();
            $transaction['started_at'] = $wallNow;
            $transaction['started_at_monotonic'] = $monotonicNow;
            $transaction['healthy_since'] = 0;
            $transaction['healthy_since_monotonic'] = 0.0;
            $transaction['observation_boot_id'] = $this->hostBootId;
            $transaction['retained_since_at'] = $wallNow;
            $transaction['retained_since_monotonic'] = $monotonicNow;
            $transaction['retain_previous_until'] =
                $wallNow + self::STALE_RETENTION;
            $transaction['retain_previous_until_monotonic'] =
                $monotonicNow + self::STALE_RETENTION;
            $transaction['retention_boot_id'] = $this->hostBootId;
            $this->state['binary_transaction'] = $transaction;
            $this->state['binary_upgrade_started_at'] = $wallNow;
            $this->state['binary_upgrade_started_at_monotonic'] = $monotonicNow;
            $this->state['binary_observation_boot_id'] = $this->hostBootId;
            $this->state['binary_healthy_since'] = 0;
            $this->state['binary_healthy_since_monotonic'] = 0.0;
            return false;
        }

        $retainedSince = (float)(
            $transaction['retained_since_monotonic'] ?? 0.0
        );
        $retainUntil = (float)(
            $transaction['retain_previous_until_monotonic'] ?? 0.0
        );
        $expectedRetainUntil = $retainedSince + self::STALE_RETENTION;
        if (!\hash_equals(
                $this->hostBootId,
                (string)($transaction['retention_boot_id'] ?? ''),
            )
            || !\is_finite($retainedSince)
            || !\is_finite($retainUntil)
            || !\is_finite($expectedRetainUntil)
            || $retainedSince <= 0.0
            || $retainedSince > $monotonicNow
                + self::MONOTONIC_SERIALIZATION_TOLERANCE_SECONDS
            || \abs($retainUntil - $expectedRetainUntil)
                > self::MONOTONIC_SERIALIZATION_TOLERANCE_SECONDS
        ) {
            $wallNow = \time();
            $transaction['retained_since_at'] = $wallNow;
            $transaction['retained_since_monotonic'] = $monotonicNow;
            $transaction['retain_previous_until'] =
                $wallNow + self::STALE_RETENTION;
            $transaction['retain_previous_until_monotonic'] =
                $monotonicNow + self::STALE_RETENTION;
            $transaction['retention_boot_id'] = $this->hostBootId;
        }

        $healthySince = (float)($transaction['healthy_since_monotonic'] ?? 0.0);
        if (!\is_finite($healthySince)
            || $healthySince < 0.0
            || $healthySince > $monotonicNow
        ) {
            $transaction['healthy_since'] = 0;
            $transaction['healthy_since_monotonic'] = 0.0;
            $healthySince = 0.0;
        }
        $this->state['binary_transaction'] = $transaction;
        $this->state['binary_upgrade_started_at'] = (int)(
            $transaction['started_at'] ?? 0
        );
        $this->state['binary_upgrade_started_at_monotonic'] = $started;
        $this->state['binary_observation_boot_id'] = $this->hostBootId;
        $this->state['binary_healthy_since'] = (int)(
            $transaction['healthy_since'] ?? 0
        );
        $this->state['binary_healthy_since_monotonic'] = $healthySince;
        return true;
    }

    private function markBinaryObservationHealthy(?float $monotonicNow = null): void
    {
        $monotonicNow ??= $this->monotonicNow();
        $this->reconcileBinaryObservationClock($monotonicNow);
        $transaction = (array)($this->state['binary_transaction'] ?? []);
        if ((string)($transaction['phase'] ?? '') !== 'OBSERVING') {
            return;
        }
        $healthySince = (float)($transaction['healthy_since_monotonic'] ?? 0.0);
        if ($healthySince <= 0.0 || $healthySince > $monotonicNow) {
            $transaction['healthy_since'] = \time();
            $transaction['healthy_since_monotonic'] = $monotonicNow;
            $transaction['observation_boot_id'] = $this->hostBootId;
            $this->state['binary_transaction'] = $transaction;
        }
        $this->state['binary_healthy_since'] = (int)$transaction['healthy_since'];
        $this->state['binary_healthy_since_monotonic'] = (float)(
            $transaction['healthy_since_monotonic'] ?? 0.0
        );
    }

    private function resetBinaryObservationHealthy(): void
    {
        $transaction = (array)($this->state['binary_transaction'] ?? []);
        if ((string)($transaction['phase'] ?? '') !== 'OBSERVING') {
            return;
        }
        $wallNow = \time();
        $monotonicNow = $this->monotonicNow();
        $transaction['started_at'] = $wallNow;
        $transaction['started_at_monotonic'] = $monotonicNow;
        $transaction['observation_boot_id'] = $this->hostBootId;
        $transaction['healthy_since'] = 0;
        $transaction['healthy_since_monotonic'] = 0.0;
        $this->state['binary_transaction'] = $transaction;
        $this->state['binary_upgrade_started_at'] = $wallNow;
        $this->state['binary_upgrade_started_at_monotonic'] = $monotonicNow;
        $this->state['binary_observation_boot_id'] = $this->hostBootId;
        $this->state['binary_healthy_since'] = 0;
        $this->state['binary_healthy_since_monotonic'] = 0.0;
    }

    private function binaryObservationCommitReady(?float $monotonicNow = null): bool
    {
        $monotonicNow ??= $this->monotonicNow();
        if (!$this->reconcileBinaryObservationClock($monotonicNow)) {
            return false;
        }
        $transaction = (array)$this->state['binary_transaction'];
        $started = (float)($transaction['started_at_monotonic'] ?? 0.0);
        $healthySince = (float)($transaction['healthy_since_monotonic'] ?? 0.0);
        return $healthySince > 0.0
            && $monotonicNow - $started >= self::FAILURE_WINDOW
            && $monotonicNow - $healthySince >= self::FAILURE_WINDOW;
    }

    private function binaryObservationRollbackEligible(?float $monotonicNow = null): bool
    {
        $transaction = (array)($this->state['binary_transaction'] ?? []);
        if ((string)($transaction['phase'] ?? '') !== 'OBSERVING') {
            return false;
        }
        $monotonicNow ??= $this->monotonicNow();
        $validExistingWindow = $this->reconcileBinaryObservationClock($monotonicNow);
        $transaction = (array)$this->state['binary_transaction'];
        $started = (float)($transaction['started_at_monotonic'] ?? 0.0);
        return !$validExistingWindow
            || ($started > 0.0
                && $started <= $monotonicNow
                && $monotonicNow - $started < self::FAILURE_WINDOW);
    }

    private function recoverDataPlane(): void
    {
        $status = $this->nginxStatus();
        if (\PHP_OS_FAMILY === 'Windows'
            && ($status['service_tree_restart_required'] ?? false) === true
        ) {
            $reason = (string)($status['message'] ?? 'Windows Nginx process tree is unavailable.');
            $this->resetBinaryObservationHealthy();
            $this->state['ready'] = false;
            $this->state['health_state'] = 'DATA_PLANE_DOWN';
            $this->state['recovery']['stage'] = 'SERVICE_TREE_RESTART';
            $this->recordFailure($reason);
            $this->persistState();
            throw new \RuntimeException(
                'Windows Nginx process tree requires platform service recovery: ' . $reason,
                self::SERVICE_TREE_RESTART_EXIT,
            );
        }
        $probeDeadline = $this->monotonicNow()
            + self::PUBLIC_ROUTE_PROBE_BUDGET_SECONDS;
        $coreHealthy = ($status['running'] ?? false)
            && $this->publicPortsReachable(null, false, $probeDeadline);
        $routesHealthy = $coreHealthy
            && $this->publicRoutesReachable(false, $probeDeadline);
        if ($coreHealthy
            && !$routesHealthy
            && \hash_equals('deferred', $this->lastPublicProbeFailureKind)
        ) {
            $coverageAge = $this->publicRouteProbeSweepStartedAt > 0.0
                ? \max(
                    0.0,
                    $this->monotonicNow() - $this->publicRouteProbeSweepStartedAt,
                )
                : 0.0;
            // Exhausting a bounded sweep is not evidence that Nginx or a
            // tenant route failed. Preserve previously established readiness,
            // continue from the cursor next cycle, and withhold LKG/A-B health
            // promotion until the sweep (including neutral SNI) completes.
            $this->state['ready'] = ($this->state['ready'] ?? false) === true
                && $this->journalTrusted
                && !($this->state['isolation_mode'] ?? false);
            $this->state['health_state'] = 'CONTROL_DEGRADED';
            $this->state['recovery']['stage'] = $coverageAge
                    > self::PUBLIC_ROUTE_PROBE_COVERAGE_SECONDS
                ? 'ROUTE_PROBE_COVERAGE_OVERDUE'
                : 'ROUTE_PROBE_DEFERRED';
            $this->state['recovery']['last_failure'] = 'public_route_probe_deferred';
            $this->state['recovery']['route_probe_coverage_age_seconds'] = \round(
                $coverageAge,
                3,
            );
            $this->persistState();
            return;
        }
        if ($coreHealthy) {
            if (($this->state['isolation_mode'] ?? false) === true) {
                $this->resetBinaryObservationHealthy();
                if ($routesHealthy) {
                    $this->state['ready'] = false;
                    if (!\str_contains(
                        (string)($this->state['health_state'] ?? ''),
                        'STATE_REBUILD',
                    )) {
                        $this->state['health_state'] = 'STATE_REBUILD';
                    }
                    $this->state['recovery']['stage'] = 'STATE_REBUILD';
                    $this->persistState();
                    return;
                }
                $coreHealthy = false;
            } elseif (!$routesHealthy
                && \in_array(
                    $this->lastPublicProbeFailureKind,
                    ['backend_transport', 'backend_identity'],
                    true,
                )
            ) {
                $this->resetBinaryObservationHealthy();
                $this->state['ready'] = false;
                $this->state['health_state'] = 'ROUTE_DEGRADED';
                $this->state['recovery']['stage'] = 'ROUTE_DEGRADED';
                $this->state['recovery']['last_failure'] =
                    $this->lastPublicProbeFailureKind;
                $this->persistState();
                return;
            } elseif (!$routesHealthy) {
                $coreHealthy = false;
            }
        }
        if ($coreHealthy) {
            $storageReady = ($this->storageStatus()['mutation_ready'] ?? false) === true;
            if (!$storageReady) {
                $this->markDiskPressure(
                    'DISK_PRESSURE',
                    'data_plane_state_persistence_suspended',
                );
                $this->observeDataPlaneDuringDiskPressure();
                return;
            }
            $lkgRollbackHeld = $this->lkgRollbackHoldActive();
            $this->state['ready'] = $this->journalTrusted && $routesHealthy;
            $this->state['health_state'] = !$this->journalTrusted
                ? 'JOURNAL_UNTRUSTED'
                : ($lkgRollbackHeld
                    ? 'CONTROL_DEGRADED'
                    : ($routesHealthy ? 'HEALTHY' : 'ROUTE_DEGRADED'));
            $this->state['recovery']['consecutive_failures'] = 0;
            $this->state['recovery']['backoff_attempt'] = 0;
            $this->state['recovery']['route_probe_coverage_age_seconds'] = 0.0;
            $this->clearRecoveryCircuit();
            if ($storageReady && $this->journalTrusted) {
                $this->state['recovery']['stage'] = $lkgRollbackHeld
                    ? 'CONFIG_ROLLBACK_HELD'
                    : ($routesHealthy ? 'NONE' : 'ROUTE_DEGRADED');
            }
            $monotonicNow = $this->monotonicNow();
            if ($routesHealthy
                && $this->pendingLkgObservationReady($monotonicNow)
            ) {
                $this->promoteLkg();
            }
            if ($routesHealthy) {
                if ((string)($this->state['binary_transaction']['phase'] ?? '')
                    === 'OBSERVING'
                ) {
                    $this->markBinaryObservationHealthy($monotonicNow);
                } elseif ((int)($this->state['binary_healthy_since'] ?? 0) <= 0
                    || !\hash_equals(
                        $this->hostBootId,
                        (string)($this->state['binary_observation_boot_id'] ?? ''),
                    )
                ) {
                    $this->state['binary_healthy_since'] = \time();
                    $this->state['binary_healthy_since_monotonic'] = $monotonicNow;
                    $this->state['binary_observation_boot_id'] = $this->hostBootId;
                }
            }
            if ($routesHealthy
                && $this->binaryObservationCommitReady($monotonicNow)
            ) {
                $wallNow = \time();
                $this->state['binary_transaction']['phase'] = 'COMMITTED';
                $this->state['binary_transaction']['committed_at'] = $wallNow;
                $this->state['binary_transaction']['retained_since_at'] = $wallNow;
                $this->state['binary_transaction']['retained_since_monotonic']
                    = $monotonicNow;
                $this->state['binary_transaction']['retain_previous_until']
                    = $wallNow + self::STALE_RETENTION;
                $this->state['binary_transaction']['retain_previous_until_monotonic']
                    = $monotonicNow + self::STALE_RETENTION;
                $this->state['binary_transaction']['retention_boot_id']
                    = $this->hostBootId;
                $this->state['binary_upgrade_started_at'] = 0;
                $this->state['binary_upgrade_started_at_monotonic'] = 0.0;
            }
            $this->persistState();
            return;
        }

        $this->state['ready'] = false;
        $this->state['health_state'] = 'DATA_PLANE_DOWN';
        $this->resetBinaryObservationHealthy();
        $monotonicNow = $this->monotonicNow();
        if (\hash_equals(
                'BINARY_ROLLBACK_REQUEST_REJECTED',
                (string)($this->state['recovery']['stage'] ?? ''),
            )
            && $this->binaryObservationRollbackEligible($monotonicNow)
        ) {
            // A failed authorization/request write is not permission to
            // restart the same suspect slot. Recheck the durable authority
            // on maintenance, but remain up for control/repair until an exact
            // /2 request can be published.
            $this->rollbackBinarySlot();
            return;
        }
        $circuitAction = $this->recoveryCircuitAction($monotonicNow);
        if ($circuitAction === 'OPEN') {
            $this->state['recovery']['stage'] = 'CIRCUIT_OPEN';
            $this->persistState();
            return;
        }
        if ($circuitAction === 'RETRY') {
            if ($this->brokerDrivenActionPending()) {
                $this->startupDataPlaneRecoveryPending = true;
                $this->state['recovery']['stage'] = 'BROKER_ACTION_PENDING_RECOVERY';
                $this->state['recovery']['last_failure'] =
                    'Circuit maintenance retry is waiting for the Native Broker internal recovery callback.';
                $this->persistState();
                return;
            }
            $this->state['recovery']['stage'] = 'MAINTENANCE_RETRY';
            $this->restartDataPlane('circuit_maintenance_retry');
            return;
        }
        if ($this->startupDataPlaneRecoveryPending
            && $this->brokerDrivenActionPending()
        ) {
            $this->state['recovery']['stage'] = 'BROKER_ACTION_PENDING_RECOVERY';
            $this->state['recovery']['last_failure'] =
                'Data-plane recovery is waiting for the Native Broker internal recovery callback.';
            $this->persistState();
            return;
        }
        $this->recordFailure((string)($status['message'] ?? 'public probes failed'));
        if ($this->recoveryCircuitAction($monotonicNow) === 'OPEN') {
            $this->state['recovery']['stage'] = 'CIRCUIT_OPEN';
            $this->persistState();
            return;
        }
        $recovery = (array)$this->state['recovery'];
        if ((int)($recovery['consecutive_failures'] ?? 0) < 3) {
            $this->persistState();
            return;
        }
        if ($this->brokerDrivenActionPending()) {
            $this->startupDataPlaneRecoveryPending = true;
            $this->state['recovery']['stage'] = 'BROKER_ACTION_PENDING_RECOVERY';
            $this->state['recovery']['last_failure'] =
                'Verified restart/rollback is waiting for a fresh Native PROCESS_ATTEST exchange.';
            $this->persistState();
            return;
        }

        if ($this->binaryObservationRollbackEligible($monotonicNow)) {
            // A newly activated slot may launch successfully yet still fail
            // TCP/TLS/route probes. Treat the third core failure inside the
            // observation window as an upgrade failure before attempting a
            // config-only rollback with the same suspect binary.
            $this->rollbackBinarySlot();
            return;
        }

        $recentFive = \array_filter(
            (array)$this->state['failure_events'],
            fn (mixed $event): bool => \is_array($event)
                && \hash_equals(
                    $this->hostBootId,
                    (string)($event['boot_id'] ?? ''),
                )
                && ($age = $monotonicNow
                    - (float)($event['at_monotonic'] ?? 0.0)) >= 0.0
                && $age <= self::FAILURE_WINDOW,
        );
        if (\count($recentFive) >= 3 && $this->rollbackToLkg()) {
            $this->state['recovery']['stage'] = 'CONFIG_ROLLBACK';
            $this->restartDataPlane('lkg_rollback');
            return;
        }
        $this->state['recovery']['stage'] = 'FAST_RESTART';
        $this->restartDataPlane('health_failure');
    }

    private function recordFailure(string $reason): void
    {
        $now = \time();
        $monotonicNow = $this->monotonicNow();
        $events = (array)$this->state['failure_events'];
        $events[] = [
            'at' => $now,
            'at_monotonic' => $monotonicNow,
            'boot_id' => $this->hostBootId,
            'reason' => $reason,
        ];
        $events = \array_values(\array_filter(
            $events,
            fn (mixed $event): bool => \is_array($event)
                && \hash_equals(
                    $this->hostBootId,
                    (string)($event['boot_id'] ?? ''),
                )
                && ($age = $monotonicNow
                    - (float)($event['at_monotonic'] ?? 0.0)) >= 0.0
                && $age <= self::CIRCUIT_WINDOW,
        ));
        $this->state['failure_events'] = $events;
        $this->state['recovery']['consecutive_failures'] =
            (int)($this->state['recovery']['consecutive_failures'] ?? 0) + 1;
        $this->state['recovery']['last_failure'] = $reason;
        if (\count($events) >= self::CIRCUIT_THRESHOLD) {
            $attempt = \max(1, (int)($this->state['recovery']['backoff_attempt'] ?? 0) + 1);
            $delay = \min(300, 5 * (2 ** \min(6, $attempt - 1)));
            $this->state['recovery']['backoff_attempt'] = $attempt;
            $this->state['recovery']['circuit_open_until'] = $now + $delay;
            $this->state['recovery']['circuit_open_until_monotonic']
                = $monotonicNow + $delay;
            $this->state['recovery']['circuit_boot_id'] = $this->hostBootId;
            $this->state['recovery']['next_retry_at'] = $now + $delay;
        }
        $this->journal('recovery_failure', ['reason' => $reason]);
    }

    private function observeCleanupFailure(string $stage, string $reason): void
    {
        $stage = \preg_match('/\A[A-Z0-9_]{1,64}\z/D', $stage) === 1
            ? $stage
            : 'CLEANUP_FAILED';
        $reason = \substr(\str_replace(["\r", "\n"], ' ', $reason), 0, 1024);
        $cleanupFailures = \max(
            0,
            (int)($this->state['recovery']['cleanup_failure_count'] ?? 0),
        );
        $this->state['recovery']['cleanup_failure_count']
            = $cleanupFailures < PHP_INT_MAX
                ? $cleanupFailures + 1
                : PHP_INT_MAX;
        $this->state['recovery']['last_cleanup_failure'] = $stage . ': ' . $reason;
        $this->state['recovery']['last_cleanup_failure_at'] = \time();
        @\error_log('[WLS Gateway] ' . $stage . ': ' . $reason);
    }

    private function recoveryCircuitAction(?float $monotonicNow = null): string
    {
        $monotonicNow ??= $this->monotonicNow();
        $recovery = (array)($this->state['recovery'] ?? []);
        $until = (float)($recovery['circuit_open_until_monotonic'] ?? 0.0);
        if ($until <= 0.0) {
            if ((int)($recovery['circuit_open_until'] ?? 0) > 0
                || (string)($recovery['circuit_boot_id'] ?? '') !== ''
                || (int)($recovery['next_retry_at'] ?? 0) > 0
            ) {
                $this->clearRecoveryCircuit();
            }
            return 'CLOSED';
        }
        if (!\hash_equals(
            $this->hostBootId,
            (string)($recovery['circuit_boot_id'] ?? ''),
        )) {
            $this->clearRecoveryCircuit();
            return 'CLOSED';
        }
        if ($monotonicNow < $until) {
            return 'OPEN';
        }
        $this->clearRecoveryCircuit();
        return 'RETRY';
    }

    private function clearRecoveryCircuit(): void
    {
        $this->state['recovery']['circuit_open_until'] = 0;
        $this->state['recovery']['circuit_open_until_monotonic'] = 0.0;
        $this->state['recovery']['circuit_boot_id'] = '';
        $this->state['recovery']['next_retry_at'] = 0;
    }

    private function restartDataPlane(string $reason): void
    {
        if ($this->brokerDrivenActionPending()) {
            $this->startupDataPlaneRecoveryPending = true;
            $this->state['ready'] = false;
            $this->state['health_state'] = 'DATA_PLANE_DOWN';
            $this->state['recovery']['stage'] = 'BROKER_ACTION_PENDING_RECOVERY';
            $this->state['recovery']['last_failure'] =
                'Nginx restart is waiting for a fresh Native PROCESS_ATTEST exchange.';
            $this->persistState();
            return;
        }
        $status = $this->nginxStatus();
        if (($status['running'] ?? false) === true) {
            $stop = $this->stopDataPlane();
            if (($stop['ok'] ?? false) !== true
                || ($this->nginxStatus()['running'] ?? false) === true
            ) {
                $this->recordFailure(
                    'Nginx restart refused because the verified owner did not stop: '
                        . (string)($stop['message'] ?? 'stop identity unavailable'),
                );
                $this->state['recovery']['stage'] = 'STOP_CONFIRMATION_FAILED';
                $this->persistState();
                return;
            }
        } elseif (($status['ok'] ?? false) !== true) {
            $this->recordFailure(
                'Nginx restart refused an unsafe process identity: '
                    . (string)($status['message'] ?? 'identity unavailable'),
            );
            $this->state['recovery']['stage'] = 'PROCESS_IDENTITY_UNSAFE';
            $this->persistState();
            return;
        }
        $start = $this->startDataPlane();
        if (!($start['ok'] ?? false)) {
            $this->recordFailure((string)($start['message'] ?? 'Nginx restart failed.'));
            if ($this->binaryObservationRollbackEligible()) {
                $this->rollbackBinarySlot();
            }
        }
        $this->journal('data_plane_restart', ['reason' => $reason, 'result' => $start]);
        $this->persistState();
    }

    private function beginRoutingMutation(string $operation): void
    {
        $this->assertBrokerGenerationOwnership($operation);
        if ($this->publication !== null) {
            if ($this->deferPublication
                && (string)($this->publication['phase'] ?? '') === 'PENDING_PUBLICATION'
                && $this->requestStateBeforeMutation === null
            ) {
                $this->requestStateBeforeMutation = $this->state;
                $this->requestPublicationBeforeMutation = $this->publication;
                $this->requestConfigDirtyBeforeMutation = $this->configDirty;
            }
            return;
        }
        $this->publication = [
            'schema_version' => 1,
            'transaction_id' => \bin2hex(\random_bytes(16)),
            'operation' => $operation,
            'phase' => 'DESIRED',
            'created_at' => \gmdate(DATE_ATOM),
            'previous' => [
                'generation' => (int)($this->state['generation'] ?? 0),
                'projects' => (array)($this->state['projects'] ?? []),
                'instances' => (array)($this->state['instances'] ?? []),
                'routes' => (array)($this->state['routes'] ?? []),
                'acme_challenges' => (array)($this->state['acme_challenges'] ?? []),
                'acme_generations' => (array)($this->state['acme_generations'] ?? []),
                'isolation_mode' => (bool)($this->state['isolation_mode'] ?? false),
                'active_config_generation' => (int)($this->state['active_config_generation'] ?? 0),
                'active_routes' => (array)($this->state['active_routes'] ?? []),
                'active_config_digest' => (string)($this->state['active_config_digest'] ?? ''),
                'pending_lkg_generation' => (int)($this->state['pending_lkg_generation'] ?? 0),
                'pending_lkg_since' => (int)($this->state['pending_lkg_since'] ?? 0),
                'pending_lkg_since_monotonic' => (float)(
                    $this->state['pending_lkg_since_monotonic'] ?? 0.0
                ),
                'pending_lkg_boot_id' => (string)(
                    $this->state['pending_lkg_boot_id'] ?? ''
                ),
                'pending_lkg_config_digest' => (string)(
                    $this->state['pending_lkg_config_digest'] ?? ''
                ),
                'pending_lkg_routes_digest' => (string)(
                    $this->state['pending_lkg_routes_digest'] ?? ''
                ),
                'config_dirty' => $this->configDirty,
            ],
            'candidate_generation' => 0,
            'candidate_file' => '',
            'candidate_digest' => '',
            'rollback_file' => '',
            'irrevocable_security' => false,
            'operation_ids' => [],
        ];
        $this->persistPublication();
    }

    private function persistPublication(): void
    {
        if ($this->publication === null) {
            return;
        }
        $payload = $this->publication;
        $envelope = [
            'payload' => $payload,
            'sha256' => \hash('sha256', $this->canonicalJson($payload)),
        ];
        $encoded = \json_encode(
            $envelope,
            JSON_PRETTY_PRINT
                | JSON_UNESCAPED_SLASHES
                | JSON_PRESERVE_ZERO_FRACTION
                | JSON_THROW_ON_ERROR,
        );
        $this->assertWriterSize($encoded, self::MAX_STATE_BYTES, 'Gateway publication journal');
        $this->atomicWrite($this->publicationFile(), $encoded, 0600);
    }

    private function completePublication(): void
    {
        if (\in_array(
            (string)($this->publication['phase'] ?? ''),
            ['PENDING_PUBLICATION', 'DURABILITY_PENDING'],
            true,
        )) {
            return;
        }
        $file = $this->publicationFile();
        try {
            $this->removeStableRegularFile(
                $file,
                'Completed gateway publication journal',
            );
        } catch (\Throwable $throwable) {
            $this->markDiskPressure(
                'PUBLICATION_CLEANUP_FAILED',
                'publication_journal_remove_failed',
            );
            throw new \RuntimeException(
                'Unable to remove the completed gateway publication journal.',
                0,
                $throwable,
            );
        }
        \clearstatcache(true, $file);
        if (\file_exists($file) || \is_link($file)) {
            $this->markDiskPressure(
                'PUBLICATION_CLEANUP_FAILED',
                'publication_journal_still_present',
            );
            throw new \RuntimeException(
                'Completed gateway publication journal is still present.'
            );
        }
        $this->publication = null;
    }

    private function markPublicationIrrevocableSecurity(): void
    {
        if ($this->publication === null) {
            throw new \RuntimeException(
                'A security mutation requires an active publication transaction.'
            );
        }
        $this->publication['irrevocable_security'] = true;
        $this->persistPublication();
    }

    private function abortRoutingMutation(string $reason): void
    {
        if ($this->requestStateBeforeMutation !== null
            && $this->requestPublicationBeforeMutation !== null
        ) {
            if (($this->publication['irrevocable_security'] ?? false) === true) {
                // The per-request rollback snapshot predates the revocation
                // overlay. Restoring it would reopen a pre-tombstone LKG route.
                // Keep the filtered desired/security state and use the normal
                // irrevocable rollback path, which stops the data plane.
                $this->requestStateBeforeMutation = null;
                $this->requestPublicationBeforeMutation = null;
                $this->requestConfigDirtyBeforeMutation = false;
                try {
                    $this->rollbackRoutingMutation($reason);
                } finally {
                    $this->completePublication();
                }
                return;
            }
            $this->state = $this->requestStateBeforeMutation;
            $this->publication = $this->requestPublicationBeforeMutation;
            $this->configDirty = $this->requestConfigDirtyBeforeMutation;
            $this->requestStateBeforeMutation = null;
            $this->requestPublicationBeforeMutation = null;
            $this->requestConfigDirtyBeforeMutation = false;
            $this->persistState();
            $this->persistPublication();
            $this->journal('publication_request_rolled_back', [
                'transaction_id' => (string)($this->publication['transaction_id'] ?? ''),
                'operation' => $this->requestOperation,
                'reason' => $reason,
            ]);
            return;
        }
        if ($this->publication === null) {
            return;
        }
        try {
            $this->rollbackRoutingMutation($reason);
        } finally {
            $this->completePublication();
        }
    }

    private function rollbackRoutingMutation(string $reason): void
    {
        if ($this->publication === null) {
            return;
        }
        $previous = \is_array($this->publication['previous'] ?? null)
            ? $this->publication['previous']
            : [];
        $irrevocableSecurity = ($this->publication['irrevocable_security'] ?? false) === true;
        if (!$irrevocableSecurity) {
            foreach ([
                'projects',
                'instances',
                'routes',
                'acme_challenges',
                'acme_generations',
            ] as $key) {
                if (\is_array($previous[$key] ?? null)) {
                    $this->state[$key] = $previous[$key];
                }
            }
            $this->state['generation'] = (int)($previous['generation'] ?? 0);
            $this->state['isolation_mode'] = (bool)($previous['isolation_mode'] ?? false);
            $this->state['pending_lkg_generation']
                = (int)($previous['pending_lkg_generation'] ?? 0);
            $this->state['pending_lkg_since'] = (int)($previous['pending_lkg_since'] ?? 0);
            $this->state['pending_lkg_since_monotonic'] = (float)(
                $previous['pending_lkg_since_monotonic'] ?? 0.0
            );
            $this->state['pending_lkg_boot_id'] = (string)(
                $previous['pending_lkg_boot_id'] ?? ''
            );
            $this->state['pending_lkg_config_digest'] = (string)(
                $previous['pending_lkg_config_digest'] ?? ''
            );
            $this->state['pending_lkg_routes_digest'] = (string)(
                $previous['pending_lkg_routes_digest'] ?? ''
            );
            $this->configDirty = (bool)($previous['config_dirty'] ?? false);
        } else {
            // A durable enrollment revocation or tombstone must never be
            // undone by publication rollback. Keep the filtered desired state
            // and force the data plane to remain unavailable until it can be
            // rendered and activated successfully.
            $this->state['ready'] = false;
            $this->state['isolation_mode'] = true;
            $this->configDirty = true;
        }
        $this->state['active_config_generation']
            = (int)($previous['active_config_generation'] ?? 0);
        $this->state['active_routes'] = (array)($previous['active_routes'] ?? []);
        $this->state['active_config_digest'] = (string)(
            $previous['active_config_digest'] ?? ''
        );
        $this->state['last_publication_error'] = $reason;
        $this->state['health_state'] = $irrevocableSecurity
            ? 'SECURITY_MUTATION_FAILED_CLOSED'
            : 'PUBLICATION_FAILED';
        $this->finishPublicationOperations('FAILED', $reason);
        if ($irrevocableSecurity) {
            $this->stopDataPlane();
        }
        $this->persistState();
    }

    private function recordPublicationLeaseCandidate(
        string $projectUuid,
        string $instanceId,
        int $instanceGeneration,
        string $instanceDigest,
        int $masterEpoch,
        string $launchId,
    ): void {
        if ($this->publication === null) {
            throw new \RuntimeException(
                'Registration lease candidate requires an active publication transaction.'
            );
        }
        $transactionId = (string)($this->publication['transaction_id'] ?? '');
        if (!$this->validProjectUuid($projectUuid)
            || $instanceId === ''
            || $instanceGeneration < 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $instanceDigest) !== 1
            || $masterEpoch < 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $launchId) !== 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $transactionId) !== 1
        ) {
            throw new \RuntimeException(
                'Registration lease publication candidate is malformed.'
            );
        }
        $monotonicNow = $this->monotonicNow();
        $key = $projectUuid . ':' . $instanceId;
        $this->publication['lease_candidates'][$key] = [
            'project_uuid' => $projectUuid,
            'instance_id' => $instanceId,
            'instance_generation' => $instanceGeneration,
            'instance_digest' => $instanceDigest,
            'master_epoch' => $masterEpoch,
            'launch_id' => $launchId,
            'transaction_id' => $transactionId,
            'started_at' => \gmdate(DATE_ATOM),
            'started_monotonic' => $monotonicNow,
            'deadline_monotonic' => $monotonicNow
                + self::PUBLICATION_LEASE_PENDING_MAX_SECONDS,
            'boot_id' => $this->hostBootId,
        ];
    }

    /** @param array<string,mixed> $candidate */
    private function publicationLeaseCandidateWithinWindow(
        array $candidate,
        float $monotonicNow,
    ): bool {
        $started = (float)($candidate['started_monotonic'] ?? 0.0);
        $deadline = (float)($candidate['deadline_monotonic'] ?? 0.0);
        $expectedDeadline = $started
            + self::PUBLICATION_LEASE_PENDING_MAX_SECONDS;
        return \hash_equals(
                $this->hostBootId,
                (string)($candidate['boot_id'] ?? ''),
            )
            && \hash_equals(
                (string)($this->publication['transaction_id'] ?? ''),
                (string)($candidate['transaction_id'] ?? ''),
            )
            && \is_finite($started)
            && \is_finite($deadline)
            && \is_finite($expectedDeadline)
            && $started > 0.0
            && $started <= $monotonicNow
                + self::MONOTONIC_SERIALIZATION_TOLERANCE_SECONDS
            && \abs($deadline - $expectedDeadline)
                <= self::MONOTONIC_SERIALIZATION_TOLERANCE_SECONDS
            && $monotonicNow <= $deadline;
    }

    /**
     * @param array<string,mixed> $candidate
     * @param array<string,mixed> $instance
     */
    private function publicationLeaseCandidateMatchesInstance(
        array $candidate,
        array $instance,
    ): bool {
        return (int)($candidate['instance_generation'] ?? 0) > 0
            && (int)($candidate['instance_generation'] ?? 0)
                === (int)($instance['generation'] ?? -1)
            && \hash_equals(
                (string)($candidate['instance_digest'] ?? ''),
                (string)($instance['digest'] ?? ''),
            )
            && (int)($candidate['master_epoch'] ?? 0) > 0
            && (int)($candidate['master_epoch'] ?? 0)
                === (int)($instance['master_epoch'] ?? -1)
            && \hash_equals(
                (string)($candidate['launch_id'] ?? ''),
                (string)($instance['launch_id'] ?? ''),
            );
    }

    /** @param array<string,mixed> $instance */
    private function publicationLeasePending(
        string $projectUuid,
        string $instanceId,
        array $instance,
        float $monotonicNow,
    ): bool {
        if ($this->publication === null
            || !\in_array(
                (string)($this->publication['phase'] ?? ''),
                [
                    'PENDING_PUBLICATION',
                    'DESIRED',
                    'PREPARED',
                    'SHADOW_VERIFIED',
                    'ACTIVATING',
                    'DURABILITY_PENDING',
                ],
                true,
            )
        ) {
            return false;
        }
        $candidate = $this->publication['lease_candidates'][
            $projectUuid . ':' . $instanceId
        ] ?? null;
        return \is_array($candidate)
            && \hash_equals(
                $projectUuid,
                (string)($candidate['project_uuid'] ?? ''),
            )
            && \hash_equals(
                $instanceId,
                (string)($candidate['instance_id'] ?? ''),
            )
            && $this->publicationLeaseCandidateWithinWindow(
                $candidate,
                $monotonicNow,
            )
            && $this->publicationLeaseCandidateMatchesInstance(
                $candidate,
                $instance,
            );
    }

    /** @param array<string,mixed> $candidate */
    private function committedPublicationLeaseCandidateClosureMatches(
        array $candidate,
    ): bool {
        $projectUuid = (string)($candidate['project_uuid'] ?? '');
        $instanceId = (string)($candidate['instance_id'] ?? '');
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        $routeIds = (array)($this->state['projects'][$projectUuid]['route_ids'] ?? []);
        if (!\is_array($instance)
            || !\hash_equals('ACTIVE', (string)($instance['status'] ?? ''))
            || !$this->publicationLeaseCandidateMatchesInstance($candidate, $instance)
            || $routeIds === []
            || !$this->projectPublicationExact($projectUuid)
        ) {
            return false;
        }
        foreach ($routeIds as $routeId) {
            $route = $this->state['routes'][(string)$routeId] ?? null;
            $published = $this->state['active_routes'][(string)$routeId] ?? null;
            $routeInstance = \is_array($route)
                ? ($route['instances'][$instanceId] ?? null)
                : null;
            $publishedInstance = \is_array($published)
                ? ($published['instances'][$instanceId] ?? null)
                : null;
            if (!\is_array($routeInstance)
                || !\is_array($publishedInstance)
                || !\hash_equals('ACTIVE', (string)($routeInstance['status'] ?? ''))
                || !\hash_equals('ACTIVE', (string)($publishedInstance['status'] ?? ''))
                || ($routeInstance['backend_healthy'] ?? false) !== true
                || ($publishedInstance['backend_healthy'] ?? false) !== true
                || !$this->publicationLeaseCandidateMatchesInstance(
                    $candidate,
                    $routeInstance,
                )
                || !$this->publicationLeaseCandidateMatchesInstance(
                    $candidate,
                    $publishedInstance,
                )
            ) {
                return false;
            }
        }
        return true;
    }

    private function activateCommittedPublicationLeaseCandidates(): void
    {
        if ($this->publication === null
            || !\hash_equals(
                'COMMITTED',
                (string)($this->publication['phase'] ?? ''),
            )
        ) {
            return;
        }
        $transactionId = (string)($this->publication['transaction_id'] ?? '');
        $monotonicNow = $this->monotonicNow();
        $wallNow = \time();
        foreach ((array)($this->publication['lease_candidates'] ?? []) as $candidate) {
            if (!\is_array($candidate)
                || !$this->publicationLeaseCandidateWithinWindow(
                    $candidate,
                    $monotonicNow,
                )
                || !$this->committedPublicationLeaseCandidateClosureMatches($candidate)
            ) {
                continue;
            }
            $projectUuid = (string)$candidate['project_uuid'];
            $instanceId = (string)$candidate['instance_id'];
            $instance = &$this->state['instances'][$projectUuid][$instanceId];
            if (\hash_equals(
                $transactionId,
                (string)($instance['lease_committed_transaction_id'] ?? ''),
            )) {
                unset($instance);
                continue;
            }
            $instance['last_heartbeat'] = $wallNow;
            $instance['last_heartbeat_monotonic'] = $monotonicNow;
            $instance['lease_boot_id'] = $this->hostBootId;
            $instance['lease_committed_transaction_id'] = $transactionId;
            unset($instance);
            foreach ((array)($this->state['projects'][$projectUuid]['route_ids'] ?? []) as $routeId) {
                $routeInstance = &$this->state['routes'][(string)$routeId]['instances'][$instanceId];
                $routeInstance['last_heartbeat'] = $wallNow;
                $routeInstance['last_heartbeat_monotonic'] = $monotonicNow;
                $routeInstance['lease_boot_id'] = $this->hostBootId;
                $routeInstance['lease_committed_transaction_id'] = $transactionId;
                $this->state['routes'][(string)$routeId]['last_heartbeat'] = $wallNow;
                unset($routeInstance);
            }
        }
    }

    private function queuePublicationOperation(): void
    {
        if ($this->publication === null) {
            throw new \RuntimeException('Unable to queue a publication without a transaction.');
        }
        $this->pruneOperations();
        $pending = 0;
        foreach ((array)($this->state['operations'] ?? []) as $operation) {
            if (\is_array($operation)
                && \in_array(
                    (string)($operation['state'] ?? ''),
                    ['PENDING_PUBLICATION', 'PREPARING', 'ACTIVATING'],
                    true,
                )
            ) {
                ++$pending;
            }
        }
        if ($pending >= self::MAX_PUBLICATION_QUEUE) {
            throw new \DomainException(
                'Gateway publication queue is full; retry after existing operations finish.'
            );
        }
        $operationId = \bin2hex(\random_bytes(16));
        $now = \time();
        $projectUuid = $this->validProjectUuid($this->requestPrincipal)
            ? $this->requestPrincipal
            : '';
        $this->state['operations'][$operationId] = [
            'operation_id' => $operationId,
            'operation' => $this->requestOperation !== ''
                ? $this->requestOperation
                : (string)($this->publication['operation'] ?? 'publication'),
            'principal' => $this->requestPrincipal !== '' ? $this->requestPrincipal : 'controller',
            'project_uuid' => $projectUuid,
            'state' => 'PENDING_PUBLICATION',
            'desired_generation' => (int)($this->state['generation'] ?? 0),
            'active_generation' => 0,
            'transaction_id' => (string)$this->publication['transaction_id'],
            'created_at' => \gmdate(DATE_ATOM, $now),
            'created_unix' => $now,
            'updated_at' => \gmdate(DATE_ATOM, $now),
            'completed_at' => '',
            'completed_unix' => 0,
            'error' => '',
            'result_context' => $this->requestOperationResultContext,
            'result' => [],
        ];
        $operationIds = \array_values(\array_unique(\array_filter(
            (array)($this->publication['operation_ids'] ?? []),
            static fn (mixed $id): bool => \is_string($id)
                && \preg_match('/\A[a-f0-9]{32}\z/D', $id) === 1,
        )));
        $operationIds[] = $operationId;
        $this->publication['operation_ids'] = $operationIds;
        $this->publication['phase'] = 'PENDING_PUBLICATION';
        $this->publication['queued_at'] ??= \gmdate(DATE_ATOM, $now);
        $this->publication['due_at_unix'] = $now + self::PUBLICATION_DEBOUNCE_SECONDS;
        $this->lastQueuedOperationId = $operationId;
        $this->publicationDueAt = $this->monotonicNow() + self::PUBLICATION_DEBOUNCE_SECONDS;
        $this->persistState();
        $this->persistPublication();
        $this->journal('publication_queued', [
            'transaction_id' => (string)$this->publication['transaction_id'],
            'operation_id' => $operationId,
            'operation' => $this->requestOperation,
            'generation' => (int)($this->state['generation'] ?? 0),
        ]);
        $this->requestStateBeforeMutation = null;
        $this->requestPublicationBeforeMutation = null;
        $this->requestConfigDirtyBeforeMutation = false;
    }

    private function processPendingPublication(): void
    {
        if ($this->publication !== null
            && (string)($this->publication['phase'] ?? '') === 'DURABILITY_PENDING'
        ) {
            try {
                if (($this->publication['irrevocable_security'] ?? false) === true
                    && !$this->publicationSecurityRetirementProven()
                ) {
                    $retirement = $this->retireSecurityDataPlaneGeneration(
                        (int)($this->publication['candidate_generation'] ?? 0),
                        $this->securityRetirementDeadline(),
                    );
                    if (($retirement['ok'] ?? false) !== true) {
                        throw new \RuntimeException(
                            (string)($retirement['message'] ?? 'TLS retirement failed.'),
                        );
                    }
                    $this->publication['security_retirement'] = $retirement['receipt'];
                    $this->persistState();
                    $this->persistPublication();
                }
                $this->persistRouteLkg();
                $this->publication['phase'] = 'COMMITTED';
                $this->finishPublicationOperations('COMMITTED');
                $this->state['recovery']['stage'] = 'NONE';
                $this->state['recovery']['last_failure'] = '';
                $this->persistState();
                $this->persistPublication();
                $this->journal('publication_durability_committed', [
                    'transaction_id' => (string)(
                        $this->publication['transaction_id'] ?? ''
                    ),
                    'generation' => (int)($this->state['active_config_generation'] ?? 0),
                ]);
                $this->archivePublicationRollback($this->publication);
                $this->completePublication();
            } catch (\Throwable $throwable) {
                $securityFailure = ($this->publication['irrevocable_security'] ?? false)
                    === true && !$this->publicationSecurityRetirementProven();
                if ($securityFailure) {
                    $this->forceStopSecurityDataPlane();
                }
                $this->state['health_state'] = $securityFailure
                    ? 'SECURITY_MUTATION_FAILED_CLOSED'
                    : 'CONTROL_DEGRADED';
                $this->state['recovery']['stage'] = $securityFailure
                    ? 'TLS_RETIREMENT_FAILED'
                    : 'ROUTE_LKG_PERSIST_PENDING';
                $this->state['recovery']['last_failure'] = $throwable->getMessage();
                try {
                    $this->persistState();
                } catch (\Throwable) {
                }
            }
            return;
        }
        if ($this->publication === null
            || (string)($this->publication['phase'] ?? '') !== 'PENDING_PUBLICATION'
        ) {
            return;
        }
        if ($this->brokerDrivenActionPending()) {
            $this->startupDataPlaneRecoveryPending = true;
            if (!\hash_equals(
                'BROKER_ACTION_PENDING_PUBLICATION',
                (string)($this->state['recovery']['stage'] ?? ''),
            )) {
                $this->state['health_state'] = 'CONTROL_DEGRADED';
                $this->state['recovery']['stage'] = 'BROKER_ACTION_PENDING_PUBLICATION';
                $this->state['recovery']['last_failure'] =
                    'Queued publication is waiting for the Native Broker internal recovery callback.';
                $this->persistState();
            }
            return;
        }
        $now = $this->monotonicNow();
        if ($this->publicationDueAt <= 0.0) {
            $this->publicationDueAt = $now;
        }
        if ($now < $this->publicationDueAt
            || ($this->lastPublicationAt > 0.0
                && $now - $this->lastPublicationAt < self::PUBLICATION_MIN_INTERVAL_SECONDS)
        ) {
            return;
        }
        $this->deferPublication = false;
        $this->publication['phase'] = 'DESIRED';
        $this->updatePublicationOperations('PREPARING');
        $this->persistPublication();
        $this->persistState();
        try {
            $this->publishIfDirty();
        } catch (\Throwable $throwable) {
            $reason = 'Queued publication failed: ' . $throwable->getMessage();
            $this->recordFailure($reason);
            $this->abortRoutingMutation($reason);
        } finally {
            $this->lastPublicationAt = $this->monotonicNow();
            $this->publicationDueAt = 0.0;
        }
    }

    private function updatePublicationOperations(string $state): void
    {
        if ($this->publication === null) {
            return;
        }
        $now = \time();
        foreach ((array)($this->publication['operation_ids'] ?? []) as $operationId) {
            if (!\is_string($operationId)
                || !\is_array($this->state['operations'][$operationId] ?? null)
            ) {
                continue;
            }
            $this->state['operations'][$operationId]['state'] = $state;
            $this->state['operations'][$operationId]['updated_at'] = \gmdate(DATE_ATOM, $now);
        }
    }

    private function finishPublicationOperations(string $state, string $error = ''): void
    {
        if ($this->publication === null) {
            return;
        }
        if ($state === 'COMMITTED' && !$this->committedPublicationMatchesActiveState()) {
            throw new \RuntimeException(
                'Publication operations cannot be committed before config, route LKG and '
                    . 'active-generation fences all match the verified candidate.'
            );
        }
        if ($state === 'COMMITTED') {
            // Retirement is a host-security fact only after this exact route
            // publication, route LKG and active generation all agree. Seal it
            // before operation receipts can report COMMITTED.
            $this->commitInstanceRetirementCandidates();
            // Only the exact signed register/renew candidates belonging to
            // this committed transaction receive a fresh lease start. Public
            // route/backend probes never enter this candidate set.
            $this->activateCommittedPublicationLeaseCandidates();
        }
        $now = \time();
        foreach ((array)($this->publication['operation_ids'] ?? []) as $operationId) {
            if (!\is_string($operationId)
                || !\is_array($this->state['operations'][$operationId] ?? null)
            ) {
                continue;
            }
            $operationState = $state;
            $operationError = $error;
            $receipt = null;
            $operationResult = [];
            $context = \is_array(
                $this->state['operations'][$operationId]['result_context'] ?? null
            ) ? $this->state['operations'][$operationId]['result_context'] : [];
            if ($state === 'COMMITTED'
                && \hash_equals(
                    'registration_lease',
                    (string)($context['kind'] ?? ''),
                )
            ) {
                try {
                    $receipt = $this->registrationLeaseReceipt(
                        (string)($context['project_uuid'] ?? ''),
                        (string)($context['instance_id'] ?? ''),
                    );
                    $requiredRetirements = \is_array(
                        $context['security_revocations'] ?? null,
                    ) ? $context['security_revocations'] : [];
                    $securityRetirements = $this->securityRetirementResult(
                        $requiredRetirements,
                    );
                    if ($requiredRetirements !== []
                        && \count($securityRetirements) !== \count($requiredRetirements)
                    ) {
                        throw new \RuntimeException(
                            'Old shared-gateway TLS generation retirement is not proven.',
                        );
                    }
                    if ($securityRetirements !== []) {
                        $operationResult['security_retirements'] = $securityRetirements;
                    }
                } catch (\Throwable $throwable) {
                    // The final batched desired state may supersede an older
                    // registration operation. Commit the publication itself,
                    // but never claim that superseded operation received an
                    // exact active lease closure.
                    $operationState = 'FAILED';
                    $operationError = 'Exact registration publication proof is unavailable: '
                        . $throwable->getMessage();
                }
            } elseif ($state === 'COMMITTED'
                && \hash_equals(
                    'instance_drain',
                    (string)($context['kind'] ?? ''),
                )
            ) {
                $operationResult = $this->committedDrainRetirementResult($context);
                if ($operationResult === []) {
                    try {
                        $receipt = $this->registrationLeaseReceipt(
                            (string)($context['project_uuid'] ?? ''),
                            (string)($context['instance_id'] ?? ''),
                            true,
                            (string)($context['drain_operation_id'] ?? ''),
                        );
                    } catch (\Throwable $throwable) {
                        // The route publication remains authoritative, but a
                        // drain operation without its exact launch-bound local
                        // lifecycle receipt cannot safely claim completion to the
                        // project Agent. It remains failed unless the same
                        // publication durably retired that exact launch.
                        $operationState = 'FAILED';
                        $operationError = 'Exact drain publication proof is unavailable: '
                            . $throwable->getMessage();
                    }
                }
            }
            $this->state['operations'][$operationId]['state'] = $operationState;
            $this->state['operations'][$operationId]['active_generation']
                = (int)($this->state['active_config_generation'] ?? 0);
            $this->state['operations'][$operationId]['updated_at'] = \gmdate(DATE_ATOM, $now);
            $this->state['operations'][$operationId]['completed_at'] = \gmdate(DATE_ATOM, $now);
            $this->state['operations'][$operationId]['completed_unix'] = $now;
            $this->state['operations'][$operationId]['error'] = $operationError;
            if ($operationState === 'COMMITTED') {
                if (\is_array($receipt)) {
                    $this->state['operations'][$operationId]['lease_receipt'] = $receipt;
                    $operationResult['lease_receipt'] = $receipt;
                    if (\hash_equals(
                        'instance_drain',
                        (string)($context['kind'] ?? ''),
                    )) {
                        $operationResult['drain_operation_id'] = (string)(
                            $context['drain_operation_id'] ?? ''
                        );
                    }
                }
                if ($operationResult !== []) {
                    $this->state['operations'][$operationId]['result'] = $operationResult;
                }
            }
        }
    }

    private function committedPublicationMatchesActiveState(): bool
    {
        if ($this->publication === null
            || !\hash_equals(
                'COMMITTED',
                (string)($this->publication['phase'] ?? ''),
            )
        ) {
            return false;
        }
        $candidateGeneration = (int)(
            $this->publication['candidate_generation'] ?? 0
        );
        $candidateDigest = \strtolower(\trim((string)(
            $this->publication['candidate_digest'] ?? ''
        )));
        return $candidateGeneration > 0
            && $candidateGeneration
                === (int)($this->state['active_config_generation'] ?? 0)
            && \preg_match('/\A[a-f0-9]{64}\z/D', $candidateDigest) === 1
            && \hash_equals(
                $candidateDigest,
                (string)($this->state['active_config_digest'] ?? ''),
            )
            && $this->activePublicationMatchesPendingLkg()
            && $this->routeLkgMatchesActiveRoutes();
    }

    private function pruneOperations(): void
    {
        $now = \time();
        $operations = [];
        foreach ((array)($this->state['operations'] ?? []) as $operationId => $operation) {
            if (!\is_string($operationId) || !\is_array($operation)) {
                continue;
            }
            $terminal = \in_array(
                (string)($operation['state'] ?? ''),
                ['COMMITTED', 'FAILED'],
                true,
            );
            if ($terminal
                && (int)($operation['completed_unix'] ?? 0) > 0
                && $now - (int)$operation['completed_unix'] > self::OPERATION_RETENTION_SECONDS
            ) {
                continue;
            }
            $operations[$operationId] = $operation;
        }
        if (\count($operations) > self::MAX_PUBLICATION_QUEUE * 2) {
            \uasort(
                $operations,
                static fn (array $left, array $right): int =>
                    (int)($right['created_unix'] ?? 0) <=> (int)($left['created_unix'] ?? 0),
            );
            $pending = \array_filter(
                $operations,
                static fn (array $operation): bool => !\in_array(
                    (string)($operation['state'] ?? ''),
                    ['COMMITTED', 'FAILED'],
                    true,
                ),
            );
            $terminal = \array_filter(
                $operations,
                static fn (array $operation): bool => \in_array(
                    (string)($operation['state'] ?? ''),
                    ['COMMITTED', 'FAILED'],
                    true,
                ),
            );
            $operations = $pending + \array_slice(
                $terminal,
                0,
                self::MAX_PUBLICATION_QUEUE,
                true,
            );
        }
        $this->state['operations'] = $operations;
    }

    private function failClosedSecurityMutation(
        string $reason,
        bool $securityLedgerUntrusted = false,
    ): void
    {
        if ($securityLedgerUntrusted) {
            $this->state['security_ledger_valid'] = false;
            try {
                $this->atomicWrite(
                    $this->securityLedgerFile() . '.untrusted',
                    \gmdate(DATE_ATOM) . "\n",
                    0600,
                );
            } catch (\Throwable) {
                // The data plane still stops below. A failed marker write must
                // never turn a failed revocation into an availability path.
            }
        }
        $this->state['ready'] = false;
        $this->state['isolation_mode'] = true;
        $this->state['health_state'] = 'SECURITY_MUTATION_FAILED_CLOSED';
        $this->state['last_publication_error'] = $reason;
        $this->configDirty = true;
        $this->stopDataPlane();
        try {
            $this->persistState();
        } finally {
            $this->completePublication();
        }
        $this->journal('security_mutation_failed_closed', ['reason' => $reason]);
    }

    private function reconcileInterruptedPublication(): void
    {
        $file = $this->publicationFile();
        if (!\is_file($file) || \is_link($file)) {
            return;
        }
        $decoded = \json_decode((string)($this->tryReadStableRegularFile(
            $file,
            self::MAX_STATE_BYTES,
            'Gateway publication journal',
        ) ?? ''), true);
        $payload = \is_array($decoded['payload'] ?? null) ? $decoded['payload'] : null;
        if (!\is_array($payload)
            || !\hash_equals(
                (string)($decoded['sha256'] ?? ''),
                \hash('sha256', $this->canonicalJson($payload)),
            )
        ) {
            $quarantine = $this->quarantineStableRegularFile(
                $file,
                'corrupt',
            );
            $now = \time();
            foreach ((array)($this->state['operations'] ?? []) as $operationId => $operation) {
                if (!\is_string($operationId)
                    || !\is_array($operation)
                    || \in_array(
                        (string)($operation['state'] ?? ''),
                        ['COMMITTED', 'FAILED'],
                        true,
                    )
                ) {
                    continue;
                }
                $this->state['operations'][$operationId]['state'] = 'FAILED';
                $this->state['operations'][$operationId]['updated_at']
                    = \gmdate(DATE_ATOM, $now);
                $this->state['operations'][$operationId]['completed_at']
                    = \gmdate(DATE_ATOM, $now);
                $this->state['operations'][$operationId]['completed_unix'] = $now;
                $this->state['operations'][$operationId]['error']
                    = 'Publication journal was corrupt and quarantined.';
            }
            $this->state['ready'] = false;
            $this->state['isolation_mode'] = true;
            $this->state['health_state'] = 'STATE_REBUILD';
            $this->configDirty = true;
            $this->persistState();
            $this->journal('publication_corrupt_quarantined', [
                'quarantine' => $quarantine,
            ]);
            return;
        }
        $this->publication = $payload;
        if ((string)($payload['phase'] ?? '') === 'COMMITTED') {
            if (!$this->routeLkgMatchesActiveRoutes()) {
                $this->publication['phase'] = 'DURABILITY_PENDING';
                $this->state['health_state'] = 'CONTROL_DEGRADED';
                $this->state['recovery']['stage'] = 'ROUTE_LKG_PERSIST_PENDING';
                $this->state['recovery']['last_failure'] =
                    'Committed publication route LKG is missing or does not match active routes.';
                $this->persistState();
                $this->persistPublication();
                return;
            }
            $this->finishPublicationOperations('COMMITTED');
            $this->persistState();
            $this->archivePublicationRollback($payload);
            $this->completePublication();
            return;
        }
        $phase = (string)($payload['phase'] ?? '');
        if (\in_array(
            $phase,
            ['PENDING_PUBLICATION', 'DESIRED', 'PREPARED', 'SHADOW_VERIFIED'],
            true,
        )) {
            $candidate = (string)($payload['candidate_file'] ?? '');
            if ($candidate !== '') {
                $this->removePublicationCandidateFile(
                    $candidate,
                    (int)($payload['candidate_generation'] ?? 0),
                    (string)($payload['transaction_id'] ?? ''),
                );
            }
            $this->publication['phase'] = 'PENDING_PUBLICATION';
            $this->publication['candidate_file'] = '';
            $this->publication['candidate_digest'] = '';
            $this->publication['rollback_file'] = '';
            $this->configDirty = true;
            $this->publicationDueAt = $this->monotonicNow();
            $this->updatePublicationOperations('PENDING_PUBLICATION');
            $this->state['health_state'] = 'PUBLICATION_RECOVERY';
            $this->persistState();
            $this->persistPublication();
            return;
        }
        $activationRecoveryDeadline = $this->monotonicNow()
            + (($this->slotManifest()['test_mode'] ?? false) === true ? 3.0 : 20.0);
        if (\in_array($phase, ['ACTIVATING', 'DURABILITY_PENDING'], true)
            && \is_file($this->configFile())
            && !\is_link($this->configFile())
            && \hash_equals(
                (string)($payload['candidate_digest'] ?? ''),
                $this->fileHash($this->configFile()),
            )
            && ($this->nginxStatus()['running'] ?? false) === true
            && $this->observeExistingActivation(
                (int)($payload['candidate_generation'] ?? 0),
                $activationRecoveryDeadline,
            )
        ) {
            if (($payload['irrevocable_security'] ?? false) === true
                && !$this->publicationSecurityRetirementProven()
            ) {
                $retirement = $this->retireSecurityDataPlaneGeneration(
                    (int)($payload['candidate_generation'] ?? 0),
                    $this->securityRetirementDeadline(),
                );
                if (($retirement['ok'] ?? false) !== true) {
                    $reason = 'Interrupted security publication could not prove old TLS '
                        . 'generation retirement: '
                        . (string)($retirement['message'] ?? 'unknown failure');
                    $this->forceStopSecurityDataPlane();
                    $this->rollbackRoutingMutation($reason);
                    $this->state['health_state'] = 'SECURITY_MUTATION_FAILED_CLOSED';
                    $this->state['recovery']['stage'] = 'TLS_RETIREMENT_FAILED';
                    $this->state['recovery']['last_failure'] = $reason;
                    $this->persistState();
                    return;
                }
                $this->publication['security_retirement'] = $retirement['receipt'];
                $this->persistState();
                $this->persistPublication();
            }
            $this->state['active_config_generation']
                = (int)($payload['candidate_generation'] ?? 0);
            $this->state['active_routes'] = $this->publishableActiveRouteSnapshot();
            $this->state['active_config_digest'] = $this->fileHash($this->configFile());
            $this->state['pending_lkg_generation']
                = (int)($payload['candidate_generation'] ?? 0);
            $this->startPendingLkgObservation();
            $this->state['pending_lkg_config_digest'] =
                (string)$this->state['active_config_digest'];
            $this->state['pending_lkg_routes_digest'] = \hash(
                'sha256',
                $this->canonicalJson((array)$this->state['active_routes']),
            );
            $this->configDirty = false;
            try {
                $this->persistRouteLkg();
            } catch (\Throwable $throwable) {
                $this->publication['phase'] = 'DURABILITY_PENDING';
                $this->state['health_state'] = 'CONTROL_DEGRADED';
                $this->state['recovery']['stage'] = 'ROUTE_LKG_PERSIST_PENDING';
                $this->state['recovery']['last_failure'] = $throwable->getMessage();
                $this->persistState();
                $this->persistPublication();
                return;
            }
            $this->publication['phase'] = 'COMMITTED';
            $this->finishPublicationOperations('COMMITTED');
            $this->persistState();
            $this->persistPublication();
            $this->journal('publication_recovered_committed', [
                'transaction_id' => (string)($payload['transaction_id'] ?? ''),
                'generation' => (int)$this->state['active_config_generation'],
            ]);
            $this->archivePublicationRollback($payload);
            $this->completePublication();
            return;
        }
        $rollback = (string)($payload['rollback_file'] ?? '');
        $active = $this->tryReadStableRegularFile(
            $this->configFile(),
            self::MAX_CONFIG_BYTES,
            'Interrupted active Nginx config',
        );
        if ($active !== null && $active !== '') {
            try {
                $this->atomicWrite(
                    $this->configFile() . '.rejected.recovery',
                    $active,
                    0600,
                );
            } catch (\Throwable) {
            }
        }
        $irrevocableSecurity = ($payload['irrevocable_security'] ?? false) === true;
        $previousGeneration = (int)(
            $payload['previous']['active_config_generation'] ?? 0
        );
        $rollbackVerified = false;
        if (!$irrevocableSecurity) {
            $rollbackVerified = $this->restorePublicationDataPlane(
                $this->configFile(),
                $rollback,
                $previousGeneration,
            );
        }
        $reason = $irrevocableSecurity
            ? 'Interrupted security publication was recovered fail closed.'
            : 'Interrupted publication was conservatively rolled back.';
        if (!$irrevocableSecurity && !$rollbackVerified) {
            $reason .= ' Previous data plane could not be restored and verified.';
        }
        $this->rollbackRoutingMutation($reason);
        $this->state['health_state'] = $rollbackVerified
            ? ($previousGeneration > 0
                ? 'PUBLICATION_ROLLBACK_HEALTHY'
                : 'FIRST_PUBLICATION_ROLLED_BACK')
            : 'PUBLICATION_RECOVERY';
        if ($rollbackVerified && $previousGeneration < 1) {
            $this->state['ready'] = false;
        }
        $this->persistState();
        $this->completePublication();
        $this->discardPublicationRollback($rollback);
        if ($rollbackVerified && !$irrevocableSecurity) {
            return;
        }
        // Never restart from a raw rollback file alone: a durable security
        // tombstone may have been committed before the interrupted config
        // activation. Re-render the recovered desired state with the current
        // security ledger overlay before the data plane can be adopted.
        $this->beginRoutingMutation('publication-recovery-security-overlay');
        $this->configDirty = true;
        if (!$this->publishIfDirty()) {
            $this->stopDataPlane();
            $this->state['isolation_mode'] = true;
            $this->state['health_state'] = 'PUBLICATION_RECOVERY_FAILED_CLOSED';
            $this->persistState();
        }
    }

    private function publishIfDirty(): bool
    {
        if (!$this->configDirty) {
            $this->completePublication();
            return true;
        }
        if ($this->lkgRollbackHoldActive()) {
            // The active LKG is verified and the exact desired generation has
            // already failed repeatedly. Do not automatically republish it on
            // the next maintenance tick. A routing generation change or an
            // explicit repair clears the hold.
            return true;
        }
        if ((int)($this->state['lkg_rollback_hold_generation'] ?? 0) > 0
            || (string)($this->state['lkg_rollback_hold_desired_digest'] ?? '') !== ''
        ) {
            $this->state['lkg_rollback_hold_generation'] = 0;
            $this->state['lkg_rollback_hold_since'] = 0;
            $this->state['lkg_rollback_hold_desired_digest'] = '';
        }
        if ($this->brokerDrivenActionPending()) {
            $this->beginRoutingMutation('broker-action-deferred-publication');
            if ($this->publication === null) {
                throw new \RuntimeException(
                    'Unable to persist the publication awaiting Native Broker recovery.'
                );
            }
            $now = \time();
            $this->publication['phase'] = 'PENDING_PUBLICATION';
            $this->publication['queued_at'] ??= \gmdate(DATE_ATOM, $now);
            $this->publication['due_at_unix'] ??= $now;
            $this->publicationDueAt = $this->publicationDueAt > 0.0
                ? $this->publicationDueAt
                : $this->monotonicNow();
            $this->updatePublicationOperations('PENDING_PUBLICATION');
            $this->startupDataPlaneRecoveryPending = true;
            $this->state['health_state'] = 'CONTROL_DEGRADED';
            $this->state['recovery']['stage'] = 'BROKER_ACTION_PENDING_PUBLICATION';
            $this->state['recovery']['last_failure'] =
                'Publication is durable and waiting for a Native Broker action exchange.';
            if ($this->deferPublication) {
                $this->queuePublicationOperation();
                return true;
            }
            $this->persistState();
            $this->persistPublication();
            return true;
        }
        $this->beginRoutingMutation('implicit-publication');
        if ($this->publication === null) {
            throw new \RuntimeException('Unable to establish the gateway publication transaction.');
        }
        if ($this->deferPublication) {
            $this->queuePublicationOperation();
            return true;
        }
        $this->publication['phase'] = 'DESIRED';
        $this->updatePublicationOperations('PREPARING');
        $this->persistPublication();
        $this->persistState();
        $transactionId = (string)$this->publication['transaction_id'];
        $publicationDeadline = $this->monotonicNow()
            + (($this->slotManifest()['test_mode'] ?? false) === true ? 20.0 : 55.0);
        $candidate = $this->configDir() . DIRECTORY_SEPARATOR . 'candidate-'
            . (int)$this->state['generation'] . '-' . $transactionId . '.conf';
        $config = $this->renderNginxConfig(true);
        $this->atomicWrite($candidate, $config, 0600);
        $this->publication['phase'] = 'PREPARED';
        $this->publication['candidate_generation'] = (int)$this->state['generation'];
        $this->publication['candidate_file'] = $candidate;
        $this->publication['candidate_digest'] = $this->fileHash($candidate);
        $this->persistPublication();
        $this->journal('publication_phase', [
            'transaction_id' => $transactionId,
            'phase' => 'PREPARED',
            'generation' => (int)$this->state['generation'],
        ]);
        $test = $this->runNginx(['-t', '-c', $candidate], $publicationDeadline);
        $candidateAttemptedH3 = (bool)($this->state['h3_enabled'] ?? false);
        if (($test['code'] ?? 1) !== 0 && $candidateAttemptedH3) {
            // H3 is an optional capability. A QUIC-only config failure retries
            // without QUIC and records the downgrade, preserving H2/H1.
            $this->quarantineH3ForActiveRuntime(
                'Candidate failed with H3; downgraded to H2/H1: '
                    . (string)($test['output'] ?? ''),
            );
            $this->atomicWrite($candidate, $this->renderNginxConfig(false), 0600);
            $this->publication['candidate_digest'] = $this->fileHash($candidate);
            $this->persistPublication();
            $test = $this->runNginx(['-t', '-c', $candidate], $publicationDeadline);
        }
        $this->lastShadowVerificationError = '';
        $shadowVerified = ($test['code'] ?? 1) === 0
            && $this->shadowVerifyRoutes(
                $candidate,
                $transactionId,
                $publicationDeadline,
            );
        if (!$shadowVerified) {
            $reason = ($test['code'] ?? 1) !== 0
                ? 'nginx -t failed: ' . (string)($test['output'] ?? '')
                : ($this->lastShadowVerificationError !== ''
                    ? $this->lastShadowVerificationError
                    : 'Candidate route/backend/certificate shadow verification failed.');
            $this->recordFailure($reason);
            $this->removePublicationCandidateFile(
                $candidate,
                (int)$this->state['generation'],
                $transactionId,
            );
            $this->rollbackRoutingMutation($reason);
            $this->completePublication();
            return false;
        }
        $this->publication['phase'] = 'SHADOW_VERIFIED';
        $this->persistPublication();
        $this->journal('publication_phase', [
            'transaction_id' => $transactionId,
            'phase' => 'SHADOW_VERIFIED',
        ]);
        $current = $this->configFile();
        $rollback = $current . '.rollback.' . $transactionId;
        if (\is_file($current)) {
            if (\is_link($current)
                || \file_exists($rollback)
            ) {
                $this->removePublicationCandidateFile(
                    $candidate,
                    (int)$this->state['generation'],
                    $transactionId,
                );
                $reason = 'Unable to preserve active Nginx config for publication rollback.';
                $this->recordFailure($reason);
                $this->rollbackRoutingMutation($reason);
                $this->completePublication();
                return false;
            }
            $activeConfig = $this->tryReadStableRegularFile(
                $current,
                16 * 1024 * 1024,
                'Active Nginx rollback source',
            );
            if ($activeConfig === null || $activeConfig === '') {
                $this->removePublicationCandidateFile(
                    $candidate,
                    (int)$this->state['generation'],
                    $transactionId,
                );
                $reason = 'Unable to read active Nginx config for publication rollback.';
                $this->recordFailure($reason);
                $this->rollbackRoutingMutation($reason);
                $this->completePublication();
                return false;
            }
            $this->atomicWrite($rollback, $activeConfig, 0600);
            $this->publication['rollback_file'] = $rollback;
            $this->persistPublication();
        }
        $this->publication['phase'] = 'ACTIVATING';
        $this->updatePublicationOperations('ACTIVATING');
        $this->persistPublication();
        $this->persistState();
        $this->journal('publication_phase', [
            'transaction_id' => $transactionId,
            'phase' => 'ACTIVATING',
        ]);
        $candidateConfig = $this->tryReadStableRegularFile(
            $candidate,
            16 * 1024 * 1024,
            'Candidate Nginx config',
        );
        try {
            if ($candidateConfig === null || $candidateConfig === '') {
                throw new \RuntimeException('Candidate Nginx config became unreadable.');
            }
            // The active path is replaced in one atomic write. The previous
            // config remains addressable through the immutable rollback copy;
            // there is no interval where the active path is absent.
            $this->atomicWrite($current, $candidateConfig, 0600);
            $this->removePublicationCandidateFile(
                $candidate,
                (int)$this->state['generation'],
                $transactionId,
            );
        } catch (\Throwable $throwable) {
            $this->removePublicationCandidateFile(
                $candidate,
                (int)$this->state['generation'],
                $transactionId,
            );
            $reason = 'Atomic Nginx config publication failed: '
                . $throwable->getMessage();
            $this->recordFailure($reason);
            $this->rollbackRoutingMutation($reason);
            $this->discardPublicationRollback($rollback);
            $this->completePublication();
            return false;
        }
        @\chmod($current, 0600);
        $activation = $this->activateCurrentConfigAndProbe(
            (int)$this->state['generation'],
            $publicationDeadline,
        );
        $result = $activation['result'];
        $publicVerified = $activation['verified'];
        if (!$publicVerified && (bool)($this->state['h3_enabled'] ?? false)) {
            // nginx -t and the isolated shadow cannot detect every QUIC
            // runtime or linked-library failure. If the real data plane fails
            // only after activation, retry the same desired routing without
            // H3 before touching the H2/H1 rollback state.
            $this->quarantineH3ForActiveRuntime(
                'Runtime activation failed with H3; downgraded to H2/H1 '
                    . 'until the gateway runtime changes or an administrator explicitly retries H3.',
            );
            $fallbackConfig = $this->renderNginxConfig(false);
            $this->atomicWrite($current, $fallbackConfig, 0600);
            $this->publication['candidate_digest'] = $this->fileHash($current);
            $this->persistPublication();
            $fallbackTest = $this->runNginx(['-t'], $publicationDeadline);
            if (($fallbackTest['code'] ?? 1) === 0
                && $this->shadowVerifyRoutes(
                    $current,
                    $transactionId,
                    $publicationDeadline,
                )
            ) {
                $activation = $this->activateCurrentConfigAndProbe(
                    (int)$this->state['generation'],
                    $publicationDeadline,
                );
                $result = $activation['result'];
                $publicVerified = $activation['verified'];
                if ($publicVerified) {
                    $this->journal('h3_runtime_downgrade', [
                        'transaction_id' => $transactionId,
                        'generation' => (int)$this->state['generation'],
                        'reason' => (string)$this->state['h3_reason'],
                    ]);
                }
            } else {
                $result = [
                    'ok' => false,
                    'message' => 'H3 runtime fallback validation failed: '
                        . (string)($fallbackTest['output'] ?? ''),
                ];
            }
        }
        if (!$publicVerified) {
            $reason = ($result['ok'] ?? false)
                ? 'Published generation failed the public HTTP/HTTPS/health probe.'
                : (string)($result['message'] ?? 'Nginx publication failed.');
            $this->recordFailure($reason);
            $rejected = $current . '.rejected.' . $transactionId;
            $rejectedConfig = $this->tryReadStableRegularFile(
                $current,
                16 * 1024 * 1024,
                'Rejected active Nginx config',
            );
            if ($rejectedConfig !== null && $rejectedConfig !== '') {
                try {
                    $this->atomicWrite($rejected, $rejectedConfig, 0600);
                } catch (\Throwable) {
                    // The active rollback is more important than retaining the
                    // rejected diagnostic copy under disk pressure.
                }
            }
            $irrevocableSecurity = ($this->publication['irrevocable_security'] ?? false)
                === true;
            $rollbackVerified = false;
            if ($irrevocableSecurity) {
                $this->forceStopSecurityDataPlane();
            } else {
                $rollbackVerified = $this->restorePublicationDataPlane(
                    $current,
                    $rollback,
                    (int)($this->publication['previous']['active_config_generation'] ?? 0),
                );
            }
            if (!$rollbackVerified) {
                $reason .= ' Previous data plane could not be restored and verified.';
            }
            $this->rollbackRoutingMutation($reason);
            if (!$rollbackVerified) {
                $this->state['ready'] = false;
                $this->state['health_state'] = 'DATA_PLANE_DOWN';
                $this->state['recovery']['stage'] = 'PUBLICATION_ROLLBACK_FAILED';
                $this->persistState();
            }
            $this->discardPublicationRollback($rollback);
            $this->completePublication();
            return false;
        }
        if (($this->publication['irrevocable_security'] ?? false) === true) {
            $retirement = $this->retireSecurityDataPlaneGeneration(
                (int)$this->state['generation'],
                $this->securityRetirementDeadline(),
            );
            if (($retirement['ok'] ?? false) !== true) {
                $reason = 'Irrevocable certificate publication did not retire the old '
                    . 'shared-gateway TLS generation: '
                    . (string)($retirement['message'] ?? 'retirement proof unavailable');
                $this->recordFailure($reason);
                $this->forceStopSecurityDataPlane();
                $this->rollbackRoutingMutation($reason);
                $this->state['ready'] = false;
                $this->state['health_state'] = 'SECURITY_MUTATION_FAILED_CLOSED';
                $this->state['recovery']['stage'] = 'TLS_RETIREMENT_FAILED';
                $this->persistState();
                $this->discardPublicationRollback($rollback);
                $this->completePublication();
                return false;
            }
            $this->publication['security_retirement'] = $retirement['receipt'];
            $this->persistState();
            $this->persistPublication();
        }
        // Public sentinels prove only backend reachability and identity. They
        // must never renew a project-controlled lease: the bounded probe loop
        // services real heartbeat envelopes, and an Agent that stops sending
        // them must still become STALE after the protocol TTL.
        $this->state['active_config_generation'] = (int)$this->state['generation'];
        $this->state['active_routes'] = $this->publishableActiveRouteSnapshot();
        $this->state['active_config_digest'] = $this->fileHash($current);
        $this->state['pending_lkg_generation'] = (int)$this->state['generation'];
        $this->startPendingLkgObservation();
        $this->state['pending_lkg_config_digest'] =
            (string)$this->state['active_config_digest'];
        $this->state['pending_lkg_routes_digest'] = \hash(
            'sha256',
            $this->canonicalJson((array)$this->state['active_routes']),
        );
        $this->state['lkg_rollback_hold_generation'] = 0;
        $this->state['lkg_rollback_hold_since'] = 0;
        $this->state['lkg_rollback_hold_desired_digest'] = '';
        $this->configDirty = false;
        try {
            $this->persistRouteLkg();
        } catch (\Throwable $throwable) {
            $this->publication['phase'] = 'DURABILITY_PENDING';
            $this->state['health_state'] = 'CONTROL_DEGRADED';
            $this->state['recovery']['stage'] = 'ROUTE_LKG_PERSIST_PENDING';
            $this->state['recovery']['last_failure'] = $throwable->getMessage();
            $this->configDirty = false;
            $this->persistState();
            $this->persistPublication();
            return true;
        }
        $this->publication['phase'] = 'COMMITTED';
        $this->finishPublicationOperations('COMMITTED');
        $this->persistState();
        $this->persistPublication();
        $this->journal('publication_phase', [
            'transaction_id' => $transactionId,
            'phase' => 'COMMITTED',
            'generation' => (int)$this->state['active_config_generation'],
        ]);
        $this->archivePublicationRollback($this->publication);
        $this->completePublication();
        return true;
    }

    private function restorePublicationDataPlane(
        string $current,
        string $rollback,
        int $previousGeneration,
    ): bool {
        if ($rollback !== ''
            && $this->pathInside($rollback, $this->configDir())
            && \is_file($rollback)
            && !\is_link($rollback)
        ) {
            $rollbackConfig = $this->tryReadStableRegularFile(
                $rollback,
                self::MAX_CONFIG_BYTES,
                'Publication rollback config',
            );
            if ($rollbackConfig === null || $rollbackConfig === '') {
                return false;
            }
            try {
                $this->atomicWrite($current, $rollbackConfig, 0600);
            } catch (\Throwable) {
                return false;
            }
            $status = $this->nginxStatus();
            if (($status['running'] ?? false) === true) {
                $result = $this->reloadDataPlane();
            } elseif (($status['ok'] ?? false) === true) {
                $result = $this->startDataPlane();
            } else {
                return false;
            }
            if (($result['ok'] ?? false) !== true) {
                return false;
            }
            $phase = (string)($this->publication['phase'] ?? '');
            $this->publication['phase'] = 'ROLLING_BACK';
            try {
                return $previousGeneration > 0
                    && $this->observeExistingActivation(
                        $previousGeneration,
                        $this->monotonicNow()
                            + (($this->slotManifest()['test_mode'] ?? false) === true
                                ? 3.0
                                : 20.0),
                    );
            } finally {
                $this->publication['phase'] = $phase;
            }
        }

        // First publication has no previous config. Stop the verified owner
        // before removing the rejected artifact; otherwise a live master can
        // become unmanaged while continuing to serve it.
        $status = $this->nginxStatus();
        if (($status['running'] ?? false) === true) {
            $stop = $this->stopDataPlane();
            if (($stop['ok'] ?? false) !== true
                || ($this->nginxStatus()['running'] ?? false) === true
            ) {
                return false;
            }
        } elseif (($status['ok'] ?? false) !== true) {
            // A malformed PID file or unverifiable live identity is not proof
            // that the first-publication process is gone. Keep both config and
            // PID evidence intact for explicit process recovery.
            return false;
        }
        try {
            if (\file_exists($current) || \is_link($current)) {
                $this->removeStableRegularFile(
                    $current,
                    'Rejected first-publication Nginx config',
                    true,
                );
            }
        } catch (\Throwable) {
            return false;
        }
        return true;
    }

    /**
     * @return array{verified:bool,result:array<string,mixed>}
     */
    private function activateCurrentConfigAndProbe(
        int $generation,
        ?float $deadlineMonotonic = null,
    ): array
    {
        $status = $this->nginxStatus();
        if (($status['running'] ?? false) === true) {
            $result = $this->reloadDataPlane();
        } elseif (($status['ok'] ?? false) === true) {
            $result = $this->startDataPlane();
        } else {
            $result = [
                'ok' => false,
                'message' => 'Nginx process identity is unsafe: '
                    . (string)($status['message'] ?? 'status unavailable'),
            ];
        }
        $verified = false;
        if (($result['ok'] ?? false) === true) {
            $testMode = ($this->slotManifest()['test_mode'] ?? false) === true;
            $activationBudgetSeconds = $testMode ? 15.0 : 20.0;
            $observationSeconds = $testMode ? 0.2 : 15.0;
            $activationDeadline = \min(
                $deadlineMonotonic ?? PHP_FLOAT_MAX,
                $this->monotonicNow() + $activationBudgetSeconds,
            );
            $healthySince = null;

            // A successful reload signal only means the master accepted the
            // command. Old workers may still answer while the new generation
            // is becoming ready, so require one continuous healthy interval
            // inside a bounded monotonic activation budget. Any failed strict
            // probe resets the interval without weakening its identity checks.
            do {
                $healthy = $this->publicPortsReachable(
                    $generation,
                    true,
                    $activationDeadline,
                ) && $this->publicRoutesReachable(true, $activationDeadline);
                $observedAt = $this->monotonicNow();
                if ($healthy && $observedAt <= $activationDeadline) {
                    $healthySince ??= $observedAt;
                    if ($observedAt - $healthySince >= $observationSeconds) {
                        $verified = true;
                        break;
                    }
                } else {
                    $healthySince = null;
                }
                if ($observedAt >= $activationDeadline) {
                    break;
                }
                $this->publicationProbePause();
            } while ($this->monotonicNow() < $activationDeadline);
        }
        return ['verified' => $verified, 'result' => $result];
    }

    private function observeExistingActivation(
        int $generation,
        float $deadlineMonotonic,
    ): bool {
        $observationSeconds = ($this->slotManifest()['test_mode'] ?? false) === true
            ? 0.2
            : 15.0;
        $healthySince = null;
        do {
            $healthy = $this->publicPortsReachable(
                $generation,
                true,
                $deadlineMonotonic,
            ) && $this->publicRoutesReachable(true, $deadlineMonotonic);
            $now = $this->monotonicNow();
            if ($healthy) {
                $healthySince ??= $now;
                if ($now - $healthySince >= $observationSeconds) {
                    return true;
                }
            } else {
                $healthySince = null;
            }
            if ($now >= $deadlineMonotonic) {
                break;
            }
            $this->publicationProbePause();
        } while ($this->monotonicNow() < $deadlineMonotonic);
        return false;
    }

    /**
     * Retirement performs a bounded stop, exact PID/start disappearance proof,
     * replacement start and the full public stability observation. It must not
     * inherit a candidate-validation deadline that has already been consumed.
     */
    private function securityRetirementDeadline(): float
    {
        return $this->monotonicNow()
            + (($this->slotManifest()['test_mode'] ?? false) === true ? 6.0 : 45.0);
    }

    /**
     * Keep authenticated status, operation polling and lease heartbeats
     * responsive throughout mandatory publication stability windows.
     */
    private function publicationProbePause(): void
    {
        $this->serviceControlDuringPublicationProbe();
        $deadline = $this->monotonicNow() + 0.1;
        if (!\is_resource($this->controlServer)) {
            $pair = \function_exists('stream_socket_pair')
                ? @\stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, 0)
                : false;
            if (\is_array($pair)) {
                $read = [$pair[0]];
                $write = [];
                $except = [];
                @\stream_select($read, $write, $except, 0, 100000);
                @\fclose($pair[0]);
                @\fclose($pair[1]);
            }
            return;
        }
        $remaining = \max(0.0, $deadline - $this->monotonicNow());
        $read = [$this->controlServer];
        $write = [];
        $except = [];
        $selected = @\stream_select(
            $read,
            $write,
            $except,
            0,
            (int)\ceil($remaining * 1_000_000),
        );
        if ($selected === 1) {
            $this->serviceControlDuringPublicationProbe();
        }
    }

    private function serviceControlDuringPublicationProbe(): void
    {
        if (!\is_resource($this->controlServer)) {
            return;
        }
        // Heartbeats, status and operation polling commonly arrive together.
        // Drain a bounded batch so a publication probe cannot leave all but
        // the first request queued for another potentially blocking route
        // probe. The request-count and wall-clock fences prevent control
        // traffic from starving publication progress.
        $deadline = $this->monotonicNow() + 0.025;
        for ($served = 0; $served < 8 && $this->monotonicNow() < $deadline; ++$served) {
            $read = [$this->controlServer];
            $write = [];
            $except = [];
            $selected = @\stream_select($read, $write, $except, 0, 0);
            if ($selected !== 1) {
                return;
            }
            $client = @\stream_socket_accept($this->controlServer, 0);
            if (!\is_resource($client)) {
                return;
            }
            // The ordinary event loop may spend up to three seconds reading a
            // complete native Broker envelope. Publication probes instead
            // share one 25 ms wall-clock budget: an accepted-but-incomplete
            // peer must fail closed without stretching the mandatory probe
            // window, starving lease heartbeats, or cascading tenants into
            // pure-WLS fallback while the Nginx data plane is still healthy.
            $remaining = $deadline - $this->monotonicNow();
            if ($remaining <= 0.0) {
                @\fclose($client);
                return;
            }
            $this->serveClient($client, \max(0.001, $remaining / 3.0));
        }
    }

    /**
     * @param array<string,mixed> $publication
     */
    private function archivePublicationRollback(array $publication): void
    {
        $rollback = (string)($publication['rollback_file'] ?? '');
        if ($rollback === ''
            || !$this->pathInside($rollback, $this->configDir())
            || !\is_file($rollback)
            || \is_link($rollback)
        ) {
            return;
        }
        // The previous active generation is already retained by the two
        // immutable LKG bundles. Archiving every transaction rollback as an
        // unreferenced `pre-*` file creates an unbounded third retention
        // system that no recovery reader consumes.
        $this->discardPublicationRollback($rollback);
    }

    private function discardPublicationRollback(string $rollback): void
    {
        if ($rollback !== ''
            && $this->pathInside($rollback, $this->configDir())
            && \is_file($rollback)
            && !\is_link($rollback)
        ) {
            $this->removeStableRegularFile(
                $rollback,
                'Publication rollback config',
            );
        }
    }

    private function shadowVerifyRoutes(
        string $candidate,
        string $transactionId,
        ?float $deadlineMonotonic = null,
    ): bool
    {
        if (!\is_file($candidate)
            || \is_link($candidate)
            || !$this->pathInside($candidate, $this->configDir())
            || \preg_match('/\A[a-f0-9]{32}\z/D', $transactionId) !== 1
        ) {
            $this->lastShadowVerificationError =
                'Candidate shadow verification rejected an unsafe config artifact.';
            return false;
        }
        $backendReadinessSeconds = ($this->slotManifest()['test_mode'] ?? false) === true
            ? 0.5
            : 5.0;
        $verificationDeadline = \min(
            $deadlineMonotonic ?? PHP_FLOAT_MAX,
            $this->monotonicNow()
                + (($this->slotManifest()['test_mode'] ?? false) === true ? 5.0 : 25.0),
        );
        if (!$this->awaitActiveRouteBackendReadiness(
            \min(
                $verificationDeadline,
                $this->monotonicNow() + $backendReadinessSeconds,
            ),
        )) {
            return false;
        }
        for ($attempt = 0; $attempt < 3; ++$attempt) {
            $ports = [];
            for ($index = 0; $index < 3; ++$index) {
                $port = $this->allocateShadowPort($ports);
                if ($port < 1) {
                    $this->lastShadowVerificationError =
                        'Candidate shadow verification could not allocate isolated ports.';
                    return false;
                }
                $ports[] = $port;
            }
            $root = $this->runtimeDir() . DIRECTORY_SEPARATOR . 'shadow'
                . DIRECTORY_SEPARATOR . $transactionId . '-' . $attempt;
            if (!@\mkdir($root, 0700) || !\is_dir($root) || \is_link($root)) {
                $this->lastShadowVerificationError =
                    'Candidate shadow verification could not create its isolated runtime.';
                return false;
            }
            if (!$this->createShadowPrefixDirectories($root)) {
                $this->removeShadowDirectory($root);
                $this->lastShadowVerificationError =
                    'Candidate shadow verification could not prepare Nginx runtime directories.';
                return false;
            }
            $config = $root . DIRECTORY_SEPARATOR . 'nginx.conf';
            $pidFile = $root . DIRECTORY_SEPARATOR . 'nginx.pid';
            $source = $this->tryReadStableRegularFile(
                $candidate,
                16 * 1024 * 1024,
                'Shadow candidate Nginx config',
            );
            if ($source === null || $source === '') {
                $this->removeShadowDirectory($root);
                $this->lastShadowVerificationError =
                    'Candidate shadow verification could not read the candidate config.';
                return false;
            }
            $shadow = $this->shadowConfig(
                $source,
                $ports[0],
                $ports[1],
                $ports[2],
                $pidFile,
                $root,
            );
            $this->atomicWrite($config, $shadow, 0600);
            $test = $this->runNginxConfig(
                $config,
                $root,
                ['-t'],
                $verificationDeadline,
            );
            if (($test['code'] ?? 1) !== 0) {
                $this->lastShadowVerificationError =
                    'Candidate shadow nginx -t failed: ' . (string)($test['output'] ?? '');
                $this->removeShadowDirectory($root);
                continue;
            }
            $start = $this->runNginxConfig(
                $config,
                $root,
                [],
                $verificationDeadline,
            );
            if (($start['code'] ?? 1) !== 0) {
                $this->lastShadowVerificationError =
                    'Candidate shadow Nginx failed to start: ' . (string)($start['output'] ?? '');
                $this->removeShadowDirectory($root);
                continue;
            }
            $verified = false;
            try {
                $startupDeadline = \min(
                    $verificationDeadline,
                    $this->monotonicNow() + 3.0,
                );
                while ($this->monotonicNow() < $startupDeadline) {
                    if ($this->shadowHealthReachable(
                        $ports[0],
                        $ports[1],
                        $ports[2],
                        (int)$this->state['generation'],
                        true,
                        $startupDeadline,
                    )) {
                        $verified = true;
                        break;
                    }
                    $this->publicationProbePause();
                }
                if (!$verified) {
                    $this->lastShadowVerificationError =
                        'Candidate shadow health endpoints did not become ready within 3 seconds.';
                    continue;
                }
                $observationSeconds = ($this->slotManifest()['test_mode'] ?? false) === true
                    ? 0.2
                    : 15.0;
                $observationDeadline = \min(
                    $verificationDeadline,
                    $this->monotonicNow() + $observationSeconds,
                );
                do {
                    if (!$this->shadowHealthReachable(
                        $ports[0],
                        $ports[1],
                        $ports[2],
                        (int)$this->state['generation'],
                        true,
                        $observationDeadline,
                    )) {
                        $verified = false;
                        break;
                    }
                    if (!$this->publicRoutesReachable(
                        true,
                        $observationDeadline,
                        $ports[1],
                    )) {
                        $verified = false;
                        $this->lastShadowVerificationError =
                            'Candidate route or neutral-domain probe failed during the '
                            . 'stability window.';
                        break;
                    }
                    $this->publicationProbePause();
                } while ($this->monotonicNow() < $observationDeadline);
            } finally {
                $this->stopShadowDataPlane($config, $root, $pidFile);
                $this->removeShadowDirectory($root);
            }
            if ($verified) {
                $this->lastShadowVerificationError = '';
                return true;
            }
        }
        return false;
    }

    private function awaitActiveRouteBackendReadiness(float $deadlineMonotonic): bool
    {
        if (($this->state['isolation_mode'] ?? false) === true) {
            return true;
        }
        $lastPending = '';
        do {
            $allReady = true;
            foreach ((array)($this->state['routes'] ?? []) as $route) {
                if (!\is_array($route)
                    || !$this->routeAllowedBySecurity($route)
                    || (string)($route['status'] ?? '') !== 'ACTIVE'
                ) {
                    continue;
                }
                $domain = (string)($route['domain'] ?? 'unknown');
                if (!(bool)($route['certificate']['valid'] ?? false)) {
                    $this->lastShadowVerificationError =
                        'Candidate route has no valid certificate snapshot: ' . $domain;
                    return false;
                }
                $backendInstances = $this->routeBackendInstances($route);
                if ($backendInstances === []) {
                    $this->lastShadowVerificationError =
                        'Candidate route has no active backend: ' . $domain;
                    return false;
                }
                foreach ($backendInstances as $instanceId => $backendInstance) {
                    $identity = (array)($backendInstance['backend_identity'] ?? []);
                    $failureKind = null;
                    $probeState = $this->probeBackends(
                        (array)($backendInstance['backends'] ?? []),
                        $identity,
                        true,
                        $failureKind,
                        $deadlineMonotonic,
                    );
                    if ($probeState !== 'HEALTHY') {
                        $allReady = false;
                        $lastPending = $domain
                            . ' instance=' . (string)$instanceId
                            . ' generation=' . (int)($identity['generation'] ?? 0);
                        break 2;
                    }
                }
            }
            if ($allReady) {
                return true;
            }
            $this->publicationProbePause();
        } while ($this->monotonicNow() < $deadlineMonotonic);

        $this->lastShadowVerificationError =
            'Candidate authenticated backend did not become ready within '
            . 'its absolute deadline: '
            . ($lastPending !== '' ? $lastPending : 'unknown route');
        return false;
    }

    /**
     * @param list<int> $excluded
     */
    private function allocateShadowPort(array $excluded): int
    {
        for ($attempt = 0; $attempt < 32; ++$attempt) {
            $socket = @\stream_socket_server(
                'tcp://127.0.0.1:0',
                $errno,
                $error,
                \STREAM_SERVER_BIND | \STREAM_SERVER_LISTEN,
            );
            if (!\is_resource($socket)) {
                continue;
            }
            $name = (string)@\stream_socket_get_name($socket, false);
            @\fclose($socket);
            $separator = \strrpos($name, ':');
            $port = $separator === false ? 0 : (int)\substr($name, $separator + 1);
            if ($port >= 1024 && !\in_array($port, $excluded, true)) {
                return $port;
            }
        }
        return 0;
    }

    private function shadowConfig(
        string $source,
        int $httpPort,
        int $httpsPort,
        int $healthPort,
        string $pidFile,
        string $root,
    ): string {
        $publicHttp = (int)$this->state['public_http'];
        $publicHttps = (int)$this->state['public_https'];
        $source = \str_replace(
            [
                'pid ' . $this->quote($this->nginxPidFile()) . ';',
                'error_log ' . $this->quote(
                    $this->logDir() . DIRECTORY_SEPARATOR . 'error.log'
                ) . ' warn;',
                'access_log ' . $this->quote(
                    $this->logDir() . DIRECTORY_SEPARATOR . 'access.log'
                ) . ';',
                'listen 127.0.0.1:' . $this->healthPort() . ';',
                'listen 0.0.0.0:' . $publicHttp,
                'listen 0.0.0.0:' . $publicHttps,
                'proxy_set_header X-Forwarded-Port ' . $publicHttps . ';',
            ],
            [
                'pid ' . $this->quote($pidFile) . ';',
                'error_log ' . $this->quote($root . DIRECTORY_SEPARATOR . 'error.log') . ' warn;',
                'access_log ' . $this->quote($root . DIRECTORY_SEPARATOR . 'access.log') . ';',
                'listen 127.0.0.1:' . $healthPort . ';',
                'listen 127.0.0.1:' . $httpPort,
                'listen 127.0.0.1:' . $httpsPort,
                'proxy_set_header X-Forwarded-Port ' . $httpsPort . ';',
            ],
            $source,
        );
        $source = (string)\preg_replace(
            '/^\s*listen \[::\]:(?:' . $publicHttp . '|' . $publicHttps
                . ')(?:\s+[^;]+)?;\R/m',
            '',
            $source,
        );
        $source = (string)\preg_replace(
            '/^\s*listen 127\.0\.0\.1:' . $httpsPort . '\s+quic(?:\s+reuseport)?;\R/m',
            '',
            $source,
        );
        $source = (string)\preg_replace(
            '/^\s*add_header Alt-Svc .*?;\R/m',
            '',
            $source,
        );
        return $source;
    }

    private function shadowHealthReachable(
        int $httpPort,
        int $httpsPort,
        int $healthPort,
        int $generation,
        bool $cooperative = false,
        ?float $deadlineMonotonic = null,
    ): bool {
        $deadlineMonotonic ??= $this->monotonicNow() + 3.0;
        foreach ([$httpPort, $httpsPort] as $port) {
            if ($cooperative) {
                $this->serviceControlDuringPublicationProbe();
            }
            $remaining = $deadlineMonotonic - $this->monotonicNow();
            if ($remaining <= 0.0) {
                return false;
            }
            $socket = @\stream_socket_client(
                'tcp://127.0.0.1:' . $port,
                $errno,
                $error,
                \min(0.5, $remaining),
            );
            if (!\is_resource($socket)) {
                return false;
            }
            @\fclose($socket);
        }
        if ($cooperative) {
            $this->serviceControlDuringPublicationProbe();
        }
        $remaining = $deadlineMonotonic - $this->monotonicNow();
        if ($remaining <= 0.0) {
            return false;
        }
        $socket = @\stream_socket_client(
            'tcp://127.0.0.1:' . $healthPort,
            $errno,
            $error,
            \min(0.5, $remaining),
        );
        if (!\is_resource($socket)) {
            return false;
        }
        @\stream_set_timeout($socket, 1);
        if (!$this->writeStreamAll(
            $socket,
            "GET /__wls_gateway_health HTTP/1.1\r\n"
                . "Host: localhost\r\nConnection: close\r\n\r\n",
        )) {
            @\fclose($socket);
            return false;
        }
        $response = $this->readProbeResponse(
            $socket,
            262144,
            1.0,
            $cooperative,
            $deadlineMonotonic,
        );
        @\fclose($socket);
        return $this->gatewayHealthResponseMatches($response, $generation);
    }

    private function stopShadowDataPlane(
        string $config,
        string $root,
        string $pidFile,
    ): void {
        $pid = $this->readPidFile($pidFile);
        if ($pid === null) {
            $this->releaseWindowsNginxProcess($config);
            return;
        }
        if ($pid < 1) {
            return;
        }
        $tracked = $this->windowsTrackedNginxMatches($config, $pid);
        if ($tracked === null && $this->pidRunningState($pid) === false) {
            $this->removeVerifiedPidFile($pidFile);
            $this->releaseWindowsNginxProcess($config);
            return;
        }
        $commandMatches = $tracked === true;
        if ($tracked === null) {
            $command = $this->processCommand($pid);
            if (\PHP_OS_FAMILY === 'Windows') {
                $normalizedCommand = \strtolower(\str_replace('/', '\\', $command));
                $commandMatches = $command !== ''
                    && \str_contains(
                        $normalizedCommand,
                        \strtolower(\str_replace('/', '\\', $this->nginxBinary())),
                    )
                    && \str_contains(
                        $normalizedCommand,
                        \strtolower(\str_replace('/', '\\', $config)),
                    );
            } else {
                $commandMatches = $command !== ''
                    && \str_contains($command, $this->nginxBinary())
                    && \str_contains($command, $config);
            }
        }
        if (!$commandMatches) {
            $this->terminateWindowsNginxProcess($config);
            if ($this->pidRunningState($pid) === false) {
                $this->removeVerifiedPidFile($pidFile);
            }
            return;
        }
        $this->runNginxConfig($config, $root, ['-s', 'quit']);
        $deadline = $this->monotonicNow() + 5.0;
        while ($this->monotonicNow() < $deadline
            && $this->pidRunningState($pid) !== false
        ) {
            if (!$this->brokerGenerationOwned()) {
                $this->running = false;
                return;
            }
            $this->publicationProbePause();
        }
        if ($this->pidRunningState($pid) === false) {
            $this->removeVerifiedPidFile($pidFile);
            $this->releaseWindowsNginxProcess($config);
        } else {
            $this->terminateWindowsNginxProcess($config);
            if ($this->pidRunningState($pid) === false) {
                $this->removeVerifiedPidFile($pidFile);
            }
        }
    }

    /**
     * @param array<string,mixed> $route
     * @return array<string,array{
     *     instance_id:string,
     *     backends:list<array<string,mixed>>,
     *     backend_identity:array<string,mixed>
     * }>
     */
    private function routeBackendInstances(array $route): array
    {
        $instances = \is_array($route['backend_instances'] ?? null)
            ? $route['backend_instances']
            : [];
        if ($instances !== []) {
            return $instances;
        }
        $instanceId = (string)($route['instance_id'] ?? '');
        $backends = \array_values((array)($route['backends'] ?? []));
        $identity = (array)($route['backend_identity'] ?? []);
        if ($instanceId === '' || $backends === [] || $identity === []) {
            return [];
        }
        return [
            $instanceId => [
                'instance_id' => $instanceId,
                'backends' => $backends,
                'backend_identity' => $identity,
            ],
        ];
    }

    /**
     * Rendering is the final boundary before Nginx receives an authenticated
     * transport tuple. Revalidate recovered/durable state here so a corrupted
     * single route cannot silently become distributed and every distributed
     * request switches upstream, token, instance and generation together.
     *
     * @param array<string,mixed> $route
     * @param array<string,array{
     *     instance_id:string,
     *     backends:list<array<string,mixed>>,
     *     backend_identity:array<string,mixed>
     * }> $backendInstances
     */
    private function assertRenderableRouteTransportTopology(
        array $route,
        array $backendInstances,
    ): void {
        $mode = (string)($route['distribution_mode'] ?? 'single');
        $preferred = (string)(
            $route['preferred_instance_id'] ?? $route['instance_id'] ?? ''
        );
        if ($backendInstances === []
            || !\in_array($mode, ['single', 'stateless', 'shared_session'], true)
            || $preferred === ''
            || !isset($backendInstances[$preferred])
            || ($mode === 'single' && \count($backendInstances) !== 1)
            || ($mode !== 'single' && \count($backendInstances) < 2)
            || !\hash_equals(
                $mode,
                $this->routeDistributionMode($route, $backendInstances),
            )
        ) {
            throw new \RuntimeException(
                'Active route transport topology is internally inconsistent.'
            );
        }

        $projectUuid = (string)($route['project_uuid'] ?? '');
        $projectRoot = (string)($route['project_root'] ?? '');
        $flattenedBackends = [];
        foreach ($backendInstances as $instanceId => $backendInstance) {
            if (!\is_array($backendInstance)) {
                throw new \RuntimeException(
                    'Active route transport instance is malformed.'
                );
            }
            $instanceId = (string)$instanceId;
            $declaredInstanceId = (string)($backendInstance['instance_id'] ?? '');
            $backends = \array_values((array)($backendInstance['backends'] ?? []));
            $identity = \is_array($backendInstance['backend_identity'] ?? null)
                ? $backendInstance['backend_identity']
                : [];
            if ($instanceId === ''
                || !\hash_equals($instanceId, $declaredInstanceId)
                || !\hash_equals($instanceId, (string)($identity['instance_id'] ?? ''))
                || !\hash_equals($projectUuid, (string)($identity['project_uuid'] ?? ''))
                || $backends === []
                || $identity === []
            ) {
                throw new \RuntimeException(
                    'Active route transport identity fence is incomplete.'
                );
            }
            foreach ($backends as $backend) {
                if (!\is_array($backend)
                    || !\in_array(
                        (string)($backend['host'] ?? ''),
                        ['127.0.0.1', '::1'],
                        true,
                    )
                    || (int)($backend['port'] ?? 0) < 1
                    || (int)($backend['port'] ?? 0) > 65535
                    || (int)($backend['weight'] ?? 0) < 1
                    || (int)($backend['weight'] ?? 0) > 1000
                ) {
                    throw new \RuntimeException(
                        'Active route transport contains an invalid backend tuple.'
                    );
                }
                $flattenedBackends[] = $backend;
            }
            $this->validateBackendEndpointIdentity(
                $identity,
                $projectRoot,
                $backends,
            );
        }
        if (!\hash_equals(
                $this->canonicalJson($flattenedBackends),
                $this->canonicalJson((array)($route['backends'] ?? [])),
            )
            || !\hash_equals(
                $preferred,
                (string)($route['instance_id'] ?? ''),
            )
            || !\hash_equals(
                $this->canonicalJson((array)$backendInstances[$preferred]['backend_identity']),
                $this->canonicalJson((array)($route['backend_identity'] ?? [])),
            )
        ) {
            throw new \RuntimeException(
                'Active route preferred transport projection is inconsistent.'
            );
        }
    }

    private function removeShadowDirectory(string $root): void
    {
        $shadowRoot = $this->runtimeDir() . DIRECTORY_SEPARATOR . 'shadow';
        $leaf = \basename($root);
        $rootStatus = @\lstat($root);
        if (!\is_array($rootStatus)) {
            return;
        }
        if (\preg_match('/\A[a-f0-9]{32}-[0-2]\z/D', $leaf) !== 1
            || ((((int)($rootStatus['mode'] ?? 0)) & 0170000) !== 0040000)
            || \is_link($root)
            || !$this->sameBoundaryPath(
                $root,
                $shadowRoot . DIRECTORY_SEPARATOR . $leaf,
            )
        ) {
            $this->observeCleanupFailure(
                'SHADOW_CLEANUP_FAILED',
                'Gateway shadow cleanup root is unsafe.',
            );
            return;
        }
        $pidFile = $root . DIRECTORY_SEPARATOR . 'nginx.pid';
        if (\file_exists($pidFile) || \is_link($pidFile)) {
            $pid = $this->readPidFile($pidFile);
            if ($pid !== null
                && $pid > 0
                && $this->pidRunningState($pid) !== false
            ) {
                return;
            }
            if ($pid !== null && $pid < 1) {
                $this->observeCleanupFailure(
                    'SHADOW_CLEANUP_FAILED',
                    'Gateway shadow PID evidence is malformed.',
                );
                return;
            }
            if (!$this->removeVerifiedPidFile($pidFile)) {
                $this->observeCleanupFailure(
                    'SHADOW_CLEANUP_FAILED',
                    'Gateway shadow PID evidence could not be removed safely.',
                );
                return;
            }
        }
        try {
            $iterator = new \RecursiveIteratorIterator(
                new \RecursiveDirectoryIterator(
                    $root,
                    \FilesystemIterator::SKIP_DOTS,
                ),
                \RecursiveIteratorIterator::CHILD_FIRST,
            );
            $iterator->setMaxDepth(64);
            $visited = 0;
            foreach ($iterator as $item) {
                if (++$visited > self::MAX_HOST_DIRECTORY_ENTRIES) {
                    // Cleanup is deliberately incremental. A damaged or
                    // attacker-inflated shadow tree must not monopolize the
                    // single-threaded recovery controller; a later GC pass
                    // may continue after this bounded prefix was removed.
                    $this->observeCleanupFailure(
                        'SHADOW_CLEANUP_FAILED',
                        'Gateway shadow tree exceeds its cleanup entry limit.',
                    );
                    return;
                }
                $path = $item->getPathname();
                if (!$this->removeShadowEntry($root, $path)) {
                    return;
                }
            }
        } catch (\UnexpectedValueException $exception) {
            $this->observeCleanupFailure(
                'SHADOW_CLEANUP_FAILED',
                $exception->getMessage(),
            );
            return;
        }
        if (!@\rmdir($root)) {
            $this->observeCleanupFailure(
                'SHADOW_CLEANUP_FAILED',
                'Unable to remove the empty gateway shadow root.',
            );
            return;
        }
        try {
            $this->syncDirectory($shadowRoot);
        } catch (\Throwable $throwable) {
            $this->observeCleanupFailure(
                'SHADOW_CLEANUP_FAILED',
                $throwable->getMessage(),
            );
        }
    }

    private function removeShadowEntry(string $root, string $path): bool
    {
        if (!$this->pathInside($path, $root)
            || $this->sameBoundaryPath($path, $root)
        ) {
            $this->observeCleanupFailure(
                'SHADOW_CLEANUP_FAILED',
                'Gateway shadow entry escaped its exact runtime root.',
            );
            return false;
        }
        $status = @\lstat($path);
        if (!\is_array($status)) {
            return !\file_exists($path) && !\is_link($path);
        }
        $type = ((int)($status['mode'] ?? 0)) & 0170000;
        try {
            if ($type === 0120000) {
                // unlink removes the link object itself; the target is never
                // resolved, and the lexical path is fenced inside shadow.
                if (!@\unlink($path)) {
                    throw new \RuntimeException('Unable to remove a gateway shadow link.');
                }
                return true;
            }
            if ($type === 0100000) {
                return $this->removeStableRegularFile(
                    $path,
                    'Gateway shadow regular file',
                );
            }
            if ($type === 0040000 && !\is_link($path)) {
                if (!@\rmdir($path)) {
                    throw new \RuntimeException('Unable to remove a gateway shadow directory.');
                }
                return true;
            }
            throw new \RuntimeException(
                'Gateway shadow tree contains an unsupported special entry.'
            );
        } catch (\Throwable $throwable) {
            $this->observeCleanupFailure(
                'SHADOW_CLEANUP_FAILED',
                $throwable->getMessage(),
            );
            return false;
        }
    }

    private function collectStaleShadowDirectories(): void
    {
        $shadowRoot = $this->runtimeDir() . DIRECTORY_SEPARATOR . 'shadow';
        if (!\is_dir($shadowRoot) || \is_link($shadowRoot)) {
            return;
        }
        try {
            $shadowEntries = $this->boundedDirectoryEntries(
                $shadowRoot,
                self::MAX_HOST_DIRECTORY_ENTRIES,
                'Gateway shadow runtime root',
            );
        } catch (\Throwable) {
            return;
        }
        foreach ($shadowEntries as $leaf) {
            if (\preg_match('/\A[a-f0-9]{32}-[0-2]\z/D', $leaf) !== 1) {
                continue;
            }
            $this->removeShadowDirectory(
                $shadowRoot . DIRECTORY_SEPARATOR . $leaf,
            );
        }
    }

    private function createShadowPrefixDirectories(string $root): bool
    {
        $shadowRoot = $this->runtimeDir() . DIRECTORY_SEPARATOR . 'shadow';
        if (!\is_dir($root)
            || \is_link($root)
            || !$this->pathInside($root, $shadowRoot)
        ) {
            return false;
        }
        foreach ([
            'logs',
            'temp',
            'temp' . DIRECTORY_SEPARATOR . 'client_body_temp',
            'temp' . DIRECTORY_SEPARATOR . 'proxy_temp',
            'temp' . DIRECTORY_SEPARATOR . 'fastcgi_temp',
            'temp' . DIRECTORY_SEPARATOR . 'uwsgi_temp',
            'temp' . DIRECTORY_SEPARATOR . 'scgi_temp',
        ] as $relative) {
            $directory = $root . DIRECTORY_SEPARATOR . $relative;
            if ((!\is_dir($directory) && !@\mkdir($directory, 0700))
                || !\is_dir($directory)
                || \is_link($directory)
            ) {
                return false;
            }
            @\chmod($directory, 0700);
        }
        return true;
    }

    private function promoteLkg(): void
    {
        $generation = (int)$this->state['pending_lkg_generation'];
        if ($generation < 1
            || $generation !== (int)($this->state['active_config_generation'] ?? 0)
            || !\is_file($this->configFile())
            || \is_link($this->configFile())
        ) {
            $this->recordFailure('Unable to persist LKG without a verified active generation/config.');
            return;
        }
        try {
            $config = $this->readStableRegularFile(
                $this->configFile(),
                16 * 1024 * 1024,
                'Healthy active Nginx config',
            );
        } catch (\Throwable) {
            $this->recordFailure('Unable to read the healthy active config for LKG promotion.');
            return;
        }
        $configDigest = \hash('sha256', $config);
        $expectedConfigDigest = (string)($this->state['pending_lkg_config_digest'] ?? '');
        $activeConfigDigest = (string)($this->state['active_config_digest'] ?? '');
        $routes = (array)($this->state['active_routes'] ?? []);
        $routesDigest = \hash('sha256', $this->canonicalJson($routes));
        $expectedRoutesDigest = (string)($this->state['pending_lkg_routes_digest'] ?? '');
        if ($expectedConfigDigest === ''
            || $activeConfigDigest === ''
            || $expectedRoutesDigest === ''
            || !\hash_equals($expectedConfigDigest, $configDigest)
            || !\hash_equals($activeConfigDigest, $configDigest)
            || !\hash_equals($expectedRoutesDigest, $routesDigest)
            || !$this->routesAllowedForCurrentSecurity($routes)
            || !$this->routesHaveValidCertificateClosure($routes)
        ) {
            $this->recordFailure(
                'LKG promotion fence no longer matches the verified active config/routes.'
            );
            return;
        }
        $certificateDigests = $this->certificateDigestsFromRoutes($routes);
        $bundleDigest = \substr(\hash(
            'sha256',
            $generation . "\0" . \hash('sha256', $config) . "\0"
                . $this->canonicalJson($routes) . "\0" . \implode(',', $certificateDigests),
        ), 0, 16);
        $bundle = $this->lkgDir() . DIRECTORY_SEPARATOR
            . 'generation-' . $generation . '-' . $bundleDigest;
        $candidate = $this->lkgDir() . DIRECTORY_SEPARATOR
            . '.candidate-' . $generation . '-' . \bin2hex(\random_bytes(8));
        $encodedRoutes = $this->encodedRouteSnapshot($routes);
        if ($encodedRoutes === null) {
            $this->recordFailure('LKG route snapshot exceeds its bounded encoding limit.');
            return;
        }
        try {
            $usage = $this->collectLkgArtifacts();
        } catch (\Throwable $throwable) {
            $this->recordFailure(
                'Gateway LKG retention root is unsafe: ' . $throwable->getMessage()
            );
            return;
        }
        if ((!\file_exists($bundle) && !\is_link($bundle))
            && ($usage['entries'] + 1 > self::MAX_LKG_ENTRIES
                || $usage['bytes']
                    + \strlen($config)
                    + \strlen($encodedRoutes)
                    + self::MAX_LKG_MANIFEST_BYTES
                    > self::MAX_LKG_BYTES)
        ) {
            $this->recordFailure(
                'Gateway LKG quota cannot reserve one complete immutable candidate bundle.'
            );
            return;
        }
        if (\file_exists($bundle) || \is_link($bundle)) {
            $existing = $this->loadLkgBundle([
                'generation' => $generation,
                'bundle_dir' => $bundle,
                'manifest_file' => $bundle . DIRECTORY_SEPARATOR . 'manifest.json',
            ]);
            if ($existing === null) {
                $this->recordFailure('Existing immutable LKG bundle failed digest verification.');
                return;
            }
        } else {
            if (!@\mkdir($candidate, 0700) || \is_link($candidate)) {
                $this->recordFailure('Unable to create the candidate LKG bundle.');
                return;
            }
            try {
                $target = $candidate . DIRECTORY_SEPARATOR . 'nginx.conf';
                $routeTarget = $candidate . DIRECTORY_SEPARATOR . 'routes.json';
                $manifestTarget = $candidate . DIRECTORY_SEPARATOR . 'manifest.json';
                $this->atomicWrite($target, $config, 0600);
                if (!$this->writeRouteSnapshot($routeTarget, $routes)) {
                    throw new \RuntimeException('Unable to persist the LKG route snapshot.');
                }
                $manifestPayload = [
                    'schema_version' => 2,
                    'generation' => $generation,
                    'config_file' => 'nginx.conf',
                    'route_file' => 'routes.json',
                    'config_sha256' => $this->fileHash($target),
                    'route_sha256' => $this->fileHash($routeTarget),
                    'certificate_digests' => $certificateDigests,
                    'created_at' => \gmdate(DATE_ATOM),
                ];
                $encodedManifest = (string)\json_encode([
                        'payload' => $manifestPayload,
                        'sha256' => \hash(
                            'sha256',
                            $this->canonicalJson($manifestPayload),
                        ),
                    ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
                $this->assertWriterSize(
                    $encodedManifest,
                    self::MAX_LKG_MANIFEST_BYTES,
                    'Gateway LKG manifest',
                );
                $this->atomicWrite($manifestTarget, $encodedManifest, 0600);
                $this->moveStableChildDirectory(
                    $candidate,
                    $bundle,
                    $this->lkgDir(),
                    '/\A\.candidate-[1-9][0-9]*-[a-f0-9]{16}\z/D',
                    '/\Ageneration-[1-9][0-9]*-[a-f0-9]{16}\z/D',
                    3,
                    'Gateway LKG bundle',
                );
            } catch (\Throwable $throwable) {
                $this->removeLkgBundle($candidate);
                $this->recordFailure(
                    'Unable to persist the healthy LKG bundle: ' . $throwable->getMessage()
                );
                return;
            }
        }
        $loaded = $this->loadLkgBundle([
            'generation' => $generation,
            'bundle_dir' => $bundle,
            'manifest_file' => $bundle . DIRECTORY_SEPARATOR . 'manifest.json',
        ]);
        if ($loaded === null) {
            $this->recordFailure('Activated LKG bundle failed post-publication verification.');
            return;
        }
        $lkg = (array)$this->state['lkg'];
        \array_unshift($lkg, [
            'generation' => $generation,
            'bundle_dir' => $bundle,
            'manifest_file' => $bundle . DIRECTORY_SEPARATOR . 'manifest.json',
            'file' => $bundle . DIRECTORY_SEPARATOR . 'nginx.conf',
            'route_file' => $bundle . DIRECTORY_SEPARATOR . 'routes.json',
            'certificate_digests' => $certificateDigests,
            'healthy_at' => \time(),
        ]);
        $deduplicated = [];
        foreach ($lkg as $entry) {
            if (!\is_array($entry)) {
                continue;
            }
            $key = (string)($entry['bundle_dir'] ?? '')
                . ':' . (int)($entry['generation'] ?? 0);
            $deduplicated[$key] ??= $entry;
        }
        $lkg = \array_values($deduplicated);
        $discarded = \array_slice($lkg, 2);
        $this->state['lkg'] = \array_slice($lkg, 0, 2);
        foreach ($discarded as $entry) {
            if (!\is_array($entry)) {
                continue;
            }
            $bundleDirectory = (string)($entry['bundle_dir'] ?? '');
            if ($bundleDirectory !== '') {
                $this->removeLkgBundle($bundleDirectory);
                continue;
            }
            // Remove checkpoint-era pairs only after they age out of the two
            // retained LKG generations.
            foreach (['file', 'route_file'] as $legacyKey) {
                $file = (string)($entry[$legacyKey] ?? '');
                if ($file !== '' && $this->pathInside($file, $this->lkgDir())) {
                    try {
                        $this->removeStableRegularFile(
                            $file,
                            'Legacy gateway LKG checkpoint',
                        );
                    } catch (\Throwable) {
                        $this->recordFailure(
                            'Unable to remove an expired legacy LKG checkpoint safely.'
                        );
                    }
                }
            }
        }
        try {
            $this->collectLkgArtifacts();
        } catch (\Throwable $throwable) {
            $this->state['recovery']['stage'] = 'LKG_RETENTION_BLOCKED';
            $this->recordFailure(
                'New LKG is verified but retention cleanup is blocked: '
                    . $throwable->getMessage()
            );
            return;
        }
        $this->state['pending_lkg_generation'] = 0;
        $this->state['pending_lkg_since'] = 0;
        $this->state['pending_lkg_since_monotonic'] = 0.0;
        $this->state['pending_lkg_boot_id'] = '';
        $this->state['pending_lkg_config_digest'] = '';
        $this->state['pending_lkg_routes_digest'] = '';
        $this->persistState();
    }

    private function rollbackToLkg(): bool
    {
        foreach ((array)$this->state['lkg'] as $lkg) {
            if (!\is_array($lkg)) {
                continue;
            }
            $bundle = $this->loadLkgBundle($lkg);
            if ($bundle === null) {
                continue;
            }
            $routes = $this->prepareLkgRoutesForActivation($bundle['routes']);
            if ($routes === null) {
                continue;
            }
            $lkgGeneration = (int)$bundle['generation'];
            $currentRoutes = $this->state['routes'];
            $currentGeneration = $this->state['generation'];
            $activated = false;
            $candidate = '';
            try {
                $this->state['routes'] = $routes;
                $this->state['generation'] = $lkgGeneration;
                $candidate = $this->configDir() . DIRECTORY_SEPARATOR . 'lkg-candidate-'
                    . \bin2hex(\random_bytes(8)) . '.conf';
                $this->atomicWrite($candidate, $this->renderNginxConfig(true), 0600);
                $test = $this->runNginx(['-t', '-c', $candidate]);
                if (($test['code'] ?? 1) !== 0) {
                    $this->atomicWrite($candidate, $this->renderNginxConfig(false), 0600);
                    $test = $this->runNginx(['-t', '-c', $candidate]);
                }
                if (($test['code'] ?? 1) !== 0) {
                    continue;
                }
                $candidateConfig = $this->readStableRegularFile(
                    $candidate,
                    16 * 1024 * 1024,
                    'Verified LKG candidate config',
                );
                $this->atomicWrite($this->configFile(), $candidateConfig, 0600);
                $activated = true;
            } finally {
                if ($candidate !== '') {
                    $this->removeLkgCandidateConfigFile($candidate);
                }
                $this->state['routes'] = $currentRoutes;
                $this->state['generation'] = $currentGeneration;
            }
            if ($activated) {
                $this->state['active_config_generation'] = $lkgGeneration;
                $this->state['active_routes'] = $routes;
                $this->state['active_config_digest'] = $this->fileHash($this->configFile());
                $this->state['pending_lkg_generation'] = 0;
                $this->state['pending_lkg_since'] = 0;
                $this->state['pending_lkg_since_monotonic'] = 0.0;
                $this->state['pending_lkg_boot_id'] = '';
                $this->state['pending_lkg_config_digest'] = '';
                $this->state['pending_lkg_routes_digest'] = '';
                $this->configDirty = !\hash_equals(
                    \hash('sha256', $this->canonicalJson((array)$this->state['routes'])),
                    \hash('sha256', $this->canonicalJson($routes)),
                );
                $this->state['lkg_rollback_hold_generation'] = $this->configDirty
                    ? (int)$currentGeneration
                    : 0;
                $this->state['lkg_rollback_hold_since'] = $this->configDirty
                    ? \time()
                    : 0;
                $this->state['lkg_rollback_hold_desired_digest'] = $this->configDirty
                    ? $this->desiredConfigIntentDigest()
                    : '';
                $this->state['last_lkg_rollback_generation'] = $lkgGeneration;
                $this->state['last_lkg_rollback_at'] = \gmdate(DATE_ATOM);
                $this->persistState();
                return true;
            }
        }
        return false;
    }

    private function lkgRollbackHoldActive(): bool
    {
        $heldGeneration = (int)(
            $this->state['lkg_rollback_hold_generation'] ?? 0
        );
        $heldDigest = (string)(
            $this->state['lkg_rollback_hold_desired_digest'] ?? ''
        );
        return $heldGeneration > 0
            && \preg_match('/\A[a-f0-9]{64}\z/D', $heldDigest) === 1
            && \hash_equals($heldDigest, $this->desiredConfigIntentDigest())
            && ($this->state['isolation_mode'] ?? false) !== true
            && ($this->state['security_ledger_valid'] ?? false) === true
            && ($this->publication['irrevocable_security'] ?? false) !== true;
    }

    private function desiredConfigIntentDigest(): string
    {
        $activeChallenges = [];
        $now = \time();
        foreach ((array)($this->state['acme_challenges'] ?? []) as $leaseId => $lease) {
            if (!\is_array($lease) || (int)($lease['expires_at'] ?? 0) <= $now) {
                continue;
            }
            $activeChallenges[(string)$leaseId] = [
                'project_uuid' => (string)($lease['project_uuid'] ?? ''),
                'domain' => (string)($lease['domain'] ?? ''),
                'token' => (string)($lease['token'] ?? ''),
                'key_authorization' => (string)(
                    $lease['key_authorization'] ?? ''
                ),
                'expires_at' => (int)($lease['expires_at'] ?? 0),
            ];
        }
        \ksort($activeChallenges, SORT_STRING);
        $routes = [];
        foreach ((array)($this->state['routes'] ?? []) as $routeId => $route) {
            if (!\is_array($route)
                || (string)($route['status'] ?? '') === 'REMOVED'
                || !$this->routeAllowedBySecurity($route)
            ) {
                continue;
            }
            $domain = (string)($route['domain'] ?? '');
            $certificate = (array)($route['certificate'] ?? []);
            $routes[(string)$routeId] = [
                'route_id' => (string)($route['route_id'] ?? ''),
                'project_uuid' => (string)($route['project_uuid'] ?? ''),
                'domain' => $domain,
                'status' => (string)($route['status'] ?? ''),
                'backends' => (array)($route['backends'] ?? []),
                'backend_instances' => (array)(
                    $route['backend_instances'] ?? []
                ),
                'backend_identity' => (array)(
                    $route['backend_identity'] ?? []
                ),
                'instance_id' => (string)($route['instance_id'] ?? ''),
                'certificate' => [
                    'state' => (string)($certificate['state'] ?? ''),
                    'valid' => ($certificate['valid'] ?? false) === true,
                    'snapshot_digest' => (string)(
                        $certificate['snapshot_digest'] ?? ''
                    ),
                    'generation' => (int)($certificate['generation'] ?? 0),
                    'cert_path' => (string)($certificate['cert_path'] ?? ''),
                    'key_path' => (string)($certificate['key_path'] ?? ''),
                ],
            ];
        }
        \ksort($routes, SORT_STRING);
        return \hash('sha256', $this->canonicalJson([
            // Generation is deliberately absent. Administrative facts that
            // do not alter rendered traffic must not immediately retry the
            // same failed config; every actual Nginx input is represented.
            'public_http' => (int)($this->state['public_http'] ?? 0),
            'public_https' => (int)($this->state['public_https'] ?? 0),
            'health_port' => $this->healthPort(),
            'isolation_mode' => ($this->state['isolation_mode'] ?? false) === true,
            'security_ledger_valid' => (
                $this->state['security_ledger_valid'] ?? false
            ) === true,
            'h3_capable' => ($this->state['h3_capable'] ?? false) === true,
            'h3_quarantined' => $this->h3QuarantinedForActiveRuntime(),
            'acme_challenges' => $activeChallenges,
            'routes' => $routes,
        ]));
    }

    /**
     * LKG stores durable routing intent, never a durable backend lease. Restore
     * only backend identities that are independently live in current desired
     * state; all other routes retain TLS but render the explicit 503 surface.
     *
     * @param array<string,array<string,mixed>> $routes
     * @return array<string,array<string,mixed>>|null
     */
    private function prepareLkgRoutesForActivation(array $routes): ?array
    {
        $prepared = [];
        foreach ($routes as $routeId => $route) {
            if (!\is_array($route)) {
                return null;
            }
            try {
                $projectUuid = \strtolower(\trim((string)($route['project_uuid'] ?? '')));
                $domain = $this->normalizeDomain((string)($route['domain'] ?? ''));
            } catch (\Throwable) {
                return null;
            }
            $canonicalRouteId = $this->canonicalRouteId($projectUuid, $domain);
            if (!\hash_equals($canonicalRouteId, (string)$routeId)
                || !\hash_equals($canonicalRouteId, (string)($route['route_id'] ?? ''))
                || !$this->routeAllowedBySecurity($route)
                || !$this->certificateStateValidForLkg(
                    (array)($route['certificate'] ?? []),
                    $domain,
                )
            ) {
                return null;
            }
            $live = $this->routeForProjectDomain($projectUuid, $domain);
            $route['instances'] = [];
            if (\is_array($live)) {
                foreach ((array)($live['instances'] ?? []) as $instanceId => $instance) {
                    if (!\is_array($instance)
                        || (string)($instance['status'] ?? '') !== 'ACTIVE'
                        || ($instance['backend_healthy'] ?? false) !== true
                        || !$this->sameLeaseBoot($instance)
                    ) {
                        continue;
                    }
                    $leaseAge = $this->monotonicNow()
                        - (float)($instance['last_heartbeat_monotonic'] ?? 0.0);
                    if ($leaseAge < 0.0 || $leaseAge >= self::HEARTBEAT_TTL) {
                        continue;
                    }
                    $route['instances'][(string)$instanceId] = $instance;
                }
            }
            $route['backends'] = [];
            $route['backend_instances'] = [];
            $route['backend_identity'] = [];
            $route['preferred_instance_id'] = '';
            $route['instance_id'] = '';
            $this->selectRouteBackends($route);
            $prepared[$canonicalRouteId] = $route;
        }
        \ksort($prepared, SORT_STRING);
        return $prepared;
    }

    /**
     * @param array<string,mixed> $entry
     * @return array{generation:int,routes:array<string,array<string,mixed>>,certificate_digests:list<string>}|null
     */
    private function loadLkgBundle(array $entry): ?array
    {
        $bundle = (string)($entry['bundle_dir'] ?? '');
        if ($bundle === '') {
            // Checkpoint compatibility: the pre-bundle LKG pair is still
            // readable for one upgrade window, but it has no cert closure and
            // is therefore never considered a fully verified bundle.
            $routes = $this->loadRouteSnapshot((string)($entry['route_file'] ?? ''));
            $legacyGeneration = (int)($entry['generation'] ?? 0);
            return $legacyGeneration < 1
                || $routes === null
                || !$this->routesHaveValidCertificateClosure($routes)
                ? null
                : [
                'generation' => $legacyGeneration,
                'routes' => $routes,
                'certificate_digests' => $this->certificateDigestsFromRoutes($routes),
                ];
        }
        $bundleLeaf = \basename($bundle);
        $bundleMatch = [];
        if (\preg_match(
            '/\Ageneration-([1-9][0-9]*)-([a-f0-9]{16})\z/D',
            $bundleLeaf,
            $bundleMatch,
        ) !== 1
            || !\is_dir($bundle)
            || \is_link($bundle)
            || !$this->sameBoundaryPath(
                $bundle,
                $this->lkgDir() . DIRECTORY_SEPARATOR . $bundleLeaf,
            )
        ) {
            return null;
        }
        $manifestFile = $bundle . DIRECTORY_SEPARATOR . 'manifest.json';
        $declaredManifest = (string)($entry['manifest_file'] ?? $manifestFile);
        if (!\is_file($manifestFile)
            || \is_link($manifestFile)
            || !$this->sameBoundaryPath($declaredManifest, $manifestFile)
        ) {
            return null;
        }
        try {
            $leaves = $this->boundedDirectoryEntries(
                $bundle,
                3,
                'Gateway LKG bundle',
            );
        } catch (\Throwable) {
            return null;
        }
        \sort($leaves, SORT_STRING);
        if ($leaves !== ['manifest.json', 'nginx.conf', 'routes.json']) {
            return null;
        }
        try {
            $manifestBytes = $this->readStableRegularFile(
                $manifestFile,
                self::MAX_LKG_MANIFEST_BYTES,
                'LKG manifest',
            );
        } catch (\Throwable) {
            return null;
        }
        $manifestEnvelope = \json_decode($manifestBytes, true);
        $manifest = \is_array($manifestEnvelope)
            && \is_array($manifestEnvelope['payload'] ?? null)
            ? $manifestEnvelope['payload']
            : null;
        if (!\is_array($manifest)
            || (int)($manifest['schema_version'] ?? 0) !== 2
            || !\hash_equals('nginx.conf', (string)($manifest['config_file'] ?? ''))
            || !\hash_equals('routes.json', (string)($manifest['route_file'] ?? ''))
            || !\hash_equals(
                (string)($manifestEnvelope['sha256'] ?? ''),
                \hash('sha256', $this->canonicalJson($manifest)),
            )
            || (int)($manifest['generation'] ?? 0) < 1
        ) {
            return null;
        }
        $configFile = $bundle . DIRECTORY_SEPARATOR . 'nginx.conf';
        $routeFile = $bundle . DIRECTORY_SEPARATOR . 'routes.json';
        if (!\is_file($configFile)
            || \is_link($configFile)
            || !\is_file($routeFile)
            || \is_link($routeFile)
        ) {
            return null;
        }
        try {
            $configHash = $this->stableFileHash(
                $configFile,
                self::MAX_CONFIG_BYTES,
                'LKG Nginx config',
            );
            $routeHash = $this->stableFileHash(
                $routeFile,
                self::MAX_STATE_BYTES,
                'LKG route snapshot',
            );
        } catch (\Throwable) {
            return null;
        }
        if (!\hash_equals((string)($manifest['config_sha256'] ?? ''), $configHash)
            || !\hash_equals((string)($manifest['route_sha256'] ?? ''), $routeHash)
        ) {
            return null;
        }
        $routes = $this->loadRouteSnapshot($routeFile);
        if ($routes === null) {
            return null;
        }
        $certificateDigests = [];
        foreach ((array)($manifest['certificate_digests'] ?? []) as $digest) {
            $digest = \strtolower(\trim((string)$digest));
            if (\preg_match('/\A[a-f0-9]{64}\z/D', $digest) !== 1) {
                return null;
            }
            $certificateDigests[] = $digest;
        }
        $certificateDigests = \array_values(\array_unique($certificateDigests));
        \sort($certificateDigests, SORT_STRING);
        if ($certificateDigests !== $this->certificateDigestsFromRoutes($routes)) {
            return null;
        }
        if (!$this->routesHaveValidCertificateClosure($routes)) {
            return null;
        }
        $generation = (int)$manifest['generation'];
        $entryGeneration = (int)($entry['generation'] ?? 0);
        $expectedBundleDigest = \substr(\hash(
            'sha256',
            $generation . "\0" . (string)$manifest['config_sha256'] . "\0"
                . $this->canonicalJson($routes) . "\0"
                . \implode(',', $certificateDigests),
        ), 0, 16);
        if ($generation !== (int)($bundleMatch[1] ?? 0)
            || ($entryGeneration > 0 && $entryGeneration !== $generation)
            || !\hash_equals((string)($bundleMatch[2] ?? ''), $expectedBundleDigest)
        ) {
            return null;
        }
        return [
            'generation' => $generation,
            'routes' => $routes,
            'certificate_digests' => $certificateDigests,
        ];
    }

    /** @param array<string,array<string,mixed>> $routes */
    private function routesHaveValidCertificateClosure(array $routes): bool
    {
        foreach ($routes as $routeId => $route) {
            if (!\is_array($route)) {
                return false;
            }
            try {
                $projectUuid = \strtolower(\trim((string)($route['project_uuid'] ?? '')));
                $domain = $this->normalizeDomain((string)($route['domain'] ?? ''));
            } catch (\Throwable) {
                return false;
            }
            $canonicalRouteId = $this->canonicalRouteId($projectUuid, $domain);
            if (!\hash_equals($canonicalRouteId, (string)$routeId)
                || !\hash_equals($canonicalRouteId, (string)($route['route_id'] ?? ''))
                || !$this->certificateStateValidForLkg(
                    (array)($route['certificate'] ?? []),
                    $domain,
                )
            ) {
                return false;
            }
        }
        return true;
    }

    /** @param array<string,array<string,mixed>> $routes */
    private function routesAllowedForCurrentSecurity(array $routes): bool
    {
        foreach ($routes as $route) {
            if (!\is_array($route)) {
                return false;
            }
            if ((string)($route['status'] ?? '') !== 'REMOVED'
                && !$this->routeAllowedBySecurity($route)
            ) {
                return false;
            }
        }
        return true;
    }

    /**
     * @param array<string,array<string,mixed>> $routes
     * @return list<string>
     */
    private function certificateDigestsFromRoutes(array $routes): array
    {
        $digests = [];
        foreach ($routes as $route) {
            if (!\is_array($route)) {
                continue;
            }
            $digest = \strtolower(\trim((string)(
                $route['certificate']['snapshot_digest'] ?? ''
            )));
            if (\preg_match('/\A[a-f0-9]{64}\z/D', $digest) === 1) {
                $digests[$digest] = true;
            }
        }
        $result = \array_keys($digests);
        \sort($result, SORT_STRING);
        return $result;
    }

    private function removeLkgBundle(string $bundle): bool
    {
        $leaf = \basename($bundle);
        $status = @\lstat($bundle);
        if (!\is_array($status)) {
            return !\file_exists($bundle) && !\is_link($bundle);
        }
        if ($bundle === ''
            || \preg_match(
                '/\A(?:generation-[1-9][0-9]*-[a-f0-9]{16}|\.candidate-[1-9][0-9]*-[a-f0-9]{16})\z/D',
                $leaf,
            ) !== 1
            || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
            || \is_link($bundle)
            || !$this->sameBoundaryPath(
                $bundle,
                $this->lkgDir() . DIRECTORY_SEPARATOR . $leaf,
            )
        ) {
            $this->observeCleanupFailure(
                'LKG_CLEANUP_FAILED',
                'Gateway LKG removal target is unsafe.',
            );
            return false;
        }
        foreach ((array)($this->state['lkg'] ?? []) as $entry) {
            $retained = \is_array($entry) ? (string)($entry['bundle_dir'] ?? '') : '';
            if ($retained !== '' && $this->sameBoundaryPath($bundle, $retained)) {
                $this->observeCleanupFailure(
                    'LKG_CLEANUP_FAILED',
                    'Refusing to remove a state-retained LKG bundle.',
                );
                return false;
            }
        }
        try {
            $entries = $this->boundedDirectoryEntries(
                $bundle,
                3,
                'Gateway LKG removal bundle',
            );
        } catch (\Throwable $throwable) {
            $this->observeCleanupFailure('LKG_CLEANUP_FAILED', $throwable->getMessage());
            return false;
        }
        $safe = [];
        foreach ($entries as $entry) {
            if (!\in_array($entry, ['manifest.json', 'nginx.conf', 'routes.json'], true)) {
                $this->observeCleanupFailure(
                    'LKG_CLEANUP_FAILED',
                    'Gateway LKG bundle contains an unknown artifact.',
                );
                return false;
            }
            $path = $bundle . DIRECTORY_SEPARATOR . $entry;
            $fileStatus = @\lstat($path);
            if (!\is_array($fileStatus)
                || \is_link($path)
                || ((((int)($fileStatus['mode'] ?? 0)) & 0170000) !== 0100000)
                || (int)($fileStatus['nlink'] ?? 0) !== 1
            ) {
                $this->observeCleanupFailure(
                    'LKG_CLEANUP_FAILED',
                    'Gateway LKG bundle contains a linked or special artifact.',
                );
                return false;
            }
            $safe[] = $path;
        }
        foreach ($safe as $path) {
            try {
                $this->removeStableRegularFile($path, 'Gateway LKG bundle file');
            } catch (\Throwable $throwable) {
                $this->observeCleanupFailure('LKG_CLEANUP_FAILED', $throwable->getMessage());
                return false;
            }
        }
        if (!@\rmdir($bundle)) {
            $this->observeCleanupFailure(
                'LKG_CLEANUP_FAILED',
                'Unable to remove the empty gateway LKG bundle.',
            );
            return false;
        }
        try {
            $this->syncDirectory($this->lkgDir());
        } catch (\Throwable $throwable) {
            $this->observeCleanupFailure('LKG_CLEANUP_FAILED', $throwable->getMessage());
            return false;
        }
        return true;
    }

    /**
     * Keep exactly the state-referenced recovery roots, remove abandoned
     * candidates/generations and enforce a hard host-wide byte/entry quota.
     * Unknown or unsafe artifacts are never followed or deleted: they block
     * further LKG writes until an administrator repairs the root.
     *
     * @return array{entries:int,bytes:int}
     */
    private function collectLkgArtifacts(): array
    {
        $root = $this->lkgDir();
        $stateEntries = (array)($this->state['lkg'] ?? []);
        if (\count($stateEntries) > self::MAX_LKG_ENTRIES) {
            throw new \RuntimeException(
                'Gateway LKG state exceeds its retained entry limit.'
            );
        }
        $protectedBundles = [];
        $protectedFiles = [];
        $retained = [];
        foreach ($stateEntries as $entry) {
            if (!\is_array($entry)) {
                throw new \RuntimeException('Gateway LKG state contains an invalid entry.');
            }
            $bundle = (string)($entry['bundle_dir'] ?? '');
            if ($bundle !== '') {
                $leaf = \basename($bundle);
                if (\preg_match(
                    '/\Ageneration-[1-9][0-9]*-[a-f0-9]{16}\z/D',
                    $leaf,
                ) !== 1
                    || !$this->sameBoundaryPath(
                        $bundle,
                        $root . DIRECTORY_SEPARATOR . $leaf,
                    )
                ) {
                    throw new \RuntimeException(
                        'Gateway LKG state references an unsafe bundle path.'
                    );
                }
                if ($this->loadLkgBundle($entry) === null) {
                    // An unusable bundle is not a recovery root. Leave it
                    // unprotected so the bounded safe-removal pass below can
                    // discard it; unsafe contents will instead fail closed.
                    continue;
                }
                if (\count($retained) < 2) {
                    $protectedBundles[$leaf] = true;
                    $retained[] = $entry;
                }
                continue;
            }
            if ($this->loadLkgBundle($entry) === null) {
                continue;
            }
            $legacyFiles = [];
            foreach (['file' => self::MAX_CONFIG_BYTES, 'route_file' => self::MAX_STATE_BYTES]
                as $key => $maximumBytes
            ) {
                $file = (string)($entry[$key] ?? '');
                if ($file === '') {
                    continue;
                }
                $leaf = \basename($file);
                if (!$this->sameBoundaryPath(
                    $file,
                    $root . DIRECTORY_SEPARATOR . $leaf,
                )) {
                    throw new \RuntimeException(
                        'Gateway legacy LKG state references an unsafe file path.'
                    );
                }
                $legacyFiles[$leaf] = $maximumBytes;
            }
            if ($legacyFiles !== [] && \count($retained) < 2) {
                foreach ($legacyFiles as $leaf => $maximumBytes) {
                    $protectedFiles[$leaf] = $maximumBytes;
                }
                $retained[] = $entry;
            }
        }
        $this->state['lkg'] = $retained;

        $leaves = $this->boundedDirectoryEntries(
            $root,
            self::MAX_HOST_DIRECTORY_ENTRIES,
            'Gateway LKG root',
        );
        foreach ($leaves as $leaf) {
            $path = $root . DIRECTORY_SEPARATOR . $leaf;
            if (isset($protectedBundles[$leaf]) || isset($protectedFiles[$leaf])) {
                continue;
            }
            if (\preg_match(
                '/\A(?:generation-[1-9][0-9]*-[a-f0-9]{16}'
                    . '|\.candidate-[1-9][0-9]*-[a-f0-9]{16})\z/D',
                $leaf,
            ) === 1) {
                $this->removeLkgBundle($path);
                if (\file_exists($path) || \is_link($path)) {
                    throw new \RuntimeException(
                        'Gateway LKG contains an abandoned bundle that cannot be removed safely.'
                    );
                }
                continue;
            }
            if (\preg_match(
                '/\Apre-[1-9][0-9]*-[a-f0-9]{32}\.conf\z/D',
                $leaf,
            ) === 1) {
                if ($this->stableRegularFileSize(
                    $path,
                    self::MAX_CONFIG_BYTES,
                    'Legacy publication rollback archive',
                ) === null
                    || !$this->removeStableRegularFile(
                        $path,
                        'Legacy publication rollback archive',
                    )
                ) {
                    throw new \RuntimeException(
                        'Gateway LKG legacy rollback archive cannot be removed safely.'
                    );
                }
                continue;
            }
            throw new \RuntimeException(
                'Gateway LKG root contains an unknown artifact.'
            );
        }

        $remaining = $this->boundedDirectoryEntries(
            $root,
            self::MAX_HOST_DIRECTORY_ENTRIES,
            'Gateway LKG root after collection',
        );
        if (\count($remaining) > self::MAX_LKG_ENTRIES) {
            throw new \RuntimeException(
                'Gateway LKG artifact entry quota is exhausted.'
            );
        }
        $bytes = 0;
        foreach ($remaining as $leaf) {
            $path = $root . DIRECTORY_SEPARATOR . $leaf;
            if (isset($protectedFiles[$leaf])) {
                $size = $this->stableRegularFileSize(
                    $path,
                    (int)$protectedFiles[$leaf],
                    'Retained legacy gateway LKG file',
                );
                if ($size === null) {
                    throw new \RuntimeException('Retained legacy LKG file disappeared.');
                }
                $bytes += $size;
            } elseif (isset($protectedBundles[$leaf])) {
                $bytes += $this->lkgBundleStorageBytes($path);
            } else {
                throw new \RuntimeException(
                    'Gateway LKG collection left an unprotected artifact.'
                );
            }
            if ($bytes > self::MAX_LKG_BYTES) {
                throw new \RuntimeException('Gateway LKG byte quota is exhausted.');
            }
        }
        return ['entries' => \count($remaining), 'bytes' => $bytes];
    }

    private function lkgBundleStorageBytes(string $bundle): int
    {
        $leaf = \basename($bundle);
        if (\preg_match(
            '/\Ageneration-[1-9][0-9]*-[a-f0-9]{16}\z/D',
            $leaf,
        ) !== 1
            || !$this->sameBoundaryPath(
                $bundle,
                $this->lkgDir() . DIRECTORY_SEPARATOR . $leaf,
            )
        ) {
            throw new \RuntimeException('Gateway LKG bundle storage path is unsafe.');
        }
        $maximums = [
            'manifest.json' => self::MAX_LKG_MANIFEST_BYTES,
            'nginx.conf' => self::MAX_CONFIG_BYTES,
            'routes.json' => self::MAX_STATE_BYTES,
        ];
        $leaves = $this->boundedDirectoryEntries(
            $bundle,
            3,
            'Retained gateway LKG bundle',
        );
        \sort($leaves, SORT_STRING);
        if ($leaves !== ['manifest.json', 'nginx.conf', 'routes.json']) {
            throw new \RuntimeException('Retained gateway LKG bundle closure is invalid.');
        }
        $bytes = 0;
        foreach ($maximums as $name => $maximumBytes) {
            $size = $this->stableRegularFileSize(
                $bundle . DIRECTORY_SEPARATOR . $name,
                $maximumBytes,
                'Retained gateway LKG bundle file',
            );
            if ($size === null) {
                throw new \RuntimeException('Retained gateway LKG bundle file disappeared.');
            }
            $bytes += $size;
        }
        return $bytes;
    }

    private function rollbackBinarySlot(): bool
    {
        $previous = (string)($this->state['previous_slot'] ?? '');
        $current = (string)($this->state['active_slot'] ?? '');
        if (!\in_array($current, ['A', 'B'], true)
            || !\in_array($previous, ['A', 'B'], true)
            || \hash_equals($current, $previous)
        ) {
            return $this->rejectBinaryRollbackRequest(
                'Binary rollback slots do not form a valid active/previous pair.',
            );
        }
        $previousBinary = $this->slotDir($previous) . DIRECTORY_SEPARATOR
            . 'bin' . DIRECTORY_SEPARATOR . $this->nginxBinaryName();
        $previousBinaryStatus = @\lstat($previousBinary);
        if (!\is_array($previousBinaryStatus)
            || \is_link($previousBinary)
            || ((((int)($previousBinaryStatus['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($previousBinaryStatus['nlink'] ?? 0) !== 1
        ) {
            return $this->rejectBinaryRollbackRequest(
                'Binary rollback previous-slot executable is missing or unsafe.',
            );
        }

        try {
            $intent = $this->readStableRegularFile(
                $this->trustDir() . DIRECTORY_SEPARATOR . 'upgrade.intent',
                4096,
                'Gateway signed upgrade intent',
            );
            $binding = $this->validateUpgradeIntentForRollback(
                $intent,
                $current,
                $previous,
            );
            $requestedAt = \time();
            if ($requestedAt <= 0) {
                throw new \RuntimeException(
                    'Binary rollback request time is outside the supported range.',
                );
            }
            $requestNonce = \bin2hex(\random_bytes(16));
            $this->atomicWrite(
                $this->stateDir() . DIRECTORY_SEPARATOR . 'upgrade-rollback.request',
                "WLS-UPGRADE-ROLLBACK/2\n"
                    . 'intent_sha256=' . $binding['digest'] . "\n"
                    . 'intent_nonce=' . $binding['nonce'] . "\n"
                    . 'from=' . $current . "\n"
                    . 'to=' . $previous . "\n"
                    . 'at=' . $requestedAt . "\n"
                    . 'request_nonce=' . $requestNonce . "\n",
                0600,
            );
        } catch (\Throwable $throwable) {
            return $this->rejectBinaryRollbackRequest(
                'Binary rollback request was not durably authorized: '
                    . $throwable->getMessage(),
            );
        }

        // State may enter ROLLING_BACK only after the stable launcher has a
        // durable request bound to the exact signed activation intent.
        $this->state['recovery']['stage'] = 'BINARY_ROLLBACK';
        $this->state['binary_transaction']['phase'] = 'ROLLING_BACK';
        $this->state['binary_transaction']['rollback_requested_at'] = $requestedAt;
        try {
            $this->journal('binary_rollback_requested', [
                'from' => $current,
                'to' => $previous,
                'intent_sha256' => $binding['digest'],
            ]);
            $this->persistState();
        } catch (\Throwable $throwable) {
            // The request file is already durable and is the launcher's
            // authority. Bookkeeping failure must not strand the controller
            // on the failed slot or rewrite the authorization envelope.
            $this->state['recovery']['last_failure'] =
                'Binary rollback was requested, but status persistence failed: '
                    . $throwable->getMessage();
        }
        // The root stable launcher owns active-slot. Exiting causes the Broker
        // and platform supervisor to restart through the signed rollback
        // reconciliation path.
        $this->running = false;
        return true;
    }

    /** @return array{digest:string,nonce:string} */
    private function validateUpgradeIntentForRollback(
        string $intent,
        string $current,
        string $previous,
    ): array {
        if (\preg_match(
            '/\AWLS-UPGRADE\/1\n'
                . 'host_id=([a-f0-9]{32})\n'
                . 'from=([AB])\n'
                . 'to=([AB])\n'
                . 'prepared_at=((?:0|[1-9][0-9]{0,18}))\n'
                . 'deadline=((?:0|[1-9][0-9]{0,18}))\n'
                . 'runtime_generation=([a-f0-9]{64})\n'
                . 'nonce=([a-f0-9]{32})\n'
                . 'signature=([a-f0-9]{64})\n\z/D',
            $intent,
            $matches,
        ) !== 1) {
            throw new \RuntimeException('Signed upgrade intent has an invalid envelope.');
        }
        $preparedText = (string)$matches[4];
        $deadlineText = (string)$matches[5];
        $maximumInteger = (string)PHP_INT_MAX;
        foreach ([$preparedText, $deadlineText] as $value) {
            if (\strlen($value) > \strlen($maximumInteger)
                || (\strlen($value) === \strlen($maximumInteger)
                    && \strcmp($value, $maximumInteger) > 0)
            ) {
                throw new \RuntimeException(
                    'Signed upgrade intent time is outside the supported range.',
                );
            }
        }
        $preparedAt = (int)$preparedText;
        $deadline = (int)$deadlineText;
        $runtimeGeneration = $this->activeRuntimeGeneration();
        if (!\hash_equals($this->hostId(), (string)$matches[1])
            || !\hash_equals($previous, (string)$matches[2])
            || !\hash_equals($current, (string)$matches[3])
            || \hash_equals((string)$matches[2], (string)$matches[3])
            || $preparedAt <= 0
            || $preparedAt > PHP_INT_MAX - self::FAILURE_WINDOW
            || $deadline !== $preparedAt + self::FAILURE_WINDOW
            || \preg_match('/\A[a-f0-9]{64}\z/D', $runtimeGeneration) !== 1
            || !\hash_equals($runtimeGeneration, (string)$matches[6])
        ) {
            throw new \RuntimeException(
                'Signed upgrade intent does not match the active rollback transaction.',
            );
        }

        $secret = \strtolower(\trim($this->readStableRegularFile(
            $this->adminTokenFile(),
            65,
            'Gateway administrator credential',
        )));
        $key = \preg_match('/\A[a-f0-9]{64}\z/D', $secret) === 1
            ? \hex2bin($secret)
            : false;
        if (!\is_string($key) || \strlen($key) !== 32) {
            throw new \RuntimeException(
                'Gateway administrator credential cannot verify the upgrade intent.',
            );
        }
        $signatureOffset = \strrpos($intent, 'signature=');
        if ($signatureOffset === false) {
            \sodium_memzero($key);
            throw new \RuntimeException('Signed upgrade intent has no signature boundary.');
        }
        try {
            $expectedSignature = \hash_hmac(
                'sha256',
                \substr($intent, 0, $signatureOffset),
                $key,
            );
        } finally {
            \sodium_memzero($key);
        }
        if (!\hash_equals($expectedSignature, (string)$matches[8])) {
            throw new \RuntimeException('Signed upgrade intent signature is invalid.');
        }

        return [
            'digest' => \hash('sha256', $intent),
            'nonce' => (string)$matches[7],
        ];
    }

    private function rejectBinaryRollbackRequest(string $reason): bool
    {
        $this->state['recovery']['stage'] = 'BINARY_ROLLBACK_REQUEST_REJECTED';
        $this->state['recovery']['last_failure'] = $reason;
        try {
            $this->journal('binary_rollback_request_rejected', ['reason' => $reason]);
            $this->persistState();
        } catch (\Throwable) {
            // Failure to persist diagnostics must not turn a rejected,
            // unsigned rollback into a controller crash/restart loop.
        }
        return false;
    }

    private function reconcileActiveRuntimeSlot(): void
    {
        $active = \strtoupper(\trim($this->readStableRegularFile(
            $this->activeSlotFile(),
            2,
            'Gateway active-slot pointer',
        )));
        if (!\in_array($active, ['A', 'B'], true)
            || !\is_file($this->slotDir($active) . DIRECTORY_SEPARATOR . 'manifest.json')
            || \is_link($this->slotDir($active) . DIRECTORY_SEPARATOR . 'manifest.json')
        ) {
            throw new \RuntimeException(
                'Root-owned active gateway slot is missing or invalid.'
            );
        }
        $previousBytes = $this->readOptionalStableRegularFile(
            $this->trustDir() . DIRECTORY_SEPARATOR . 'previous-slot',
            2,
            'Gateway previous-slot pointer',
        );
        $previous = $previousBytes === null
            ? ''
            : \strtoupper(\trim($previousBytes));
        if (!\in_array($previous, ['A', 'B'], true) || $previous === $active) {
            $previous = $active === 'A' ? 'B' : 'A';
        }
        $pointersAlreadyReconciled = \hash_equals(
            $active,
            (string)($this->state['active_slot'] ?? ''),
        ) && \hash_equals(
            $previous,
            (string)($this->state['previous_slot'] ?? ''),
        );
        $previousTransaction = (array)($this->state['binary_transaction'] ?? []);
        $nativeRollback = $this->nativeRollbackClosure(
            $active,
            $previous,
            $previousTransaction,
        );
        if ($pointersAlreadyReconciled && $nativeRollback === null) {
            return;
        }
        $from = $pointersAlreadyReconciled && $nativeRollback !== null
            ? $previous
            : (string)($this->state['active_slot'] ?? '');
        $wallNow = \time();
        $monotonicNow = $this->monotonicNow();
        $this->state['active_slot'] = $active;
        $this->state['previous_slot'] = $previous;
        $this->state['binary_healthy_since'] = 0;
        $this->state['binary_healthy_since_monotonic'] = 0.0;
        $this->state['binary_upgrade_started_at'] = $wallNow;
        $this->state['binary_upgrade_started_at_monotonic'] = $monotonicNow;
        $this->state['binary_observation_boot_id'] = $this->hostBootId;
        $rolledBack = $nativeRollback !== null || (
            (string)($previousTransaction['phase'] ?? '') === 'ROLLING_BACK'
                && \hash_equals(
                    (string)($previousTransaction['from_slot'] ?? ''),
                    $active,
                )
        );
        $this->state['binary_transaction'] = [
            'phase' => $rolledBack ? 'ROLLED_BACK' : 'OBSERVING',
            'from_slot' => $from,
            'to_slot' => $active,
            'started_at' => $wallNow,
            'started_at_monotonic' => $rolledBack ? 0.0 : $monotonicNow,
            'healthy_since' => 0,
            'healthy_since_monotonic' => 0.0,
            'observation_boot_id' => $rolledBack ? '' : $this->hostBootId,
            'committed_at' => 0,
            'retained_since_at' => $wallNow,
            'retained_since_monotonic' => $monotonicNow,
            'retain_previous_until' => $wallNow + self::STALE_RETENTION,
            'retain_previous_until_monotonic'
                => $monotonicNow + self::STALE_RETENTION,
            'retention_boot_id' => $this->hostBootId,
            'rolled_back_at' => $rolledBack ? $wallNow : 0,
            'native_cleanup_pending' => $nativeRollback !== null
                && ($nativeRollback['cleanup_pending'] ?? false) === true,
            'native_intent_sha256' => (string)(
                $nativeRollback['intent_sha256'] ?? ''
            ),
        ];
        if ($rolledBack) {
            $this->state['binary_upgrade_started_at'] = 0;
            $this->state['binary_upgrade_started_at_monotonic'] = 0.0;
            $this->state['recovery']['last_failure'] = '';
        }
        $this->state['ready'] = false;
        $this->state['recovery']['stage'] = $rolledBack
            ? 'BINARY_ROLLED_BACK'
            : 'BINARY_UPGRADE';
        $this->persistState();
        if (!$this->journal('runtime_slot_reconciled', [
            'from' => $from,
            'to' => $active,
            'previous' => $previous,
        ])) {
            throw new \RuntimeException(
                'Unable to audit the root-owned runtime slot transition.'
            );
        }
    }

    /**
     * Reconcile the Native launcher's root-owned rollback decision. The
     * original A->B intent is cleanup authority only after active has returned
     * to A; it must never authorize a fabricated reverse B->A observation.
     *
     * @param array<string,mixed> $previousTransaction
     * @return array{intent_sha256:string,cleanup_pending:bool}|null
     */
    private function nativeRollbackClosure(
        string $active,
        string $previous,
        array $previousTransaction,
    ): ?array {
        $intent = $this->readOptionalStableRegularFile(
            $this->trustDir() . DIRECTORY_SEPARATOR . 'upgrade.intent',
            4096,
            'Gateway signed upgrade intent',
        );
        $state = $this->readOptionalStableRegularFile(
            $this->trustDir() . DIRECTORY_SEPARATOR . 'upgrade-state',
            2048,
            'Gateway Native upgrade state',
        );
        if ($intent !== null && $state !== null) {
            if (\preg_match(
                '/\AWLS-UPGRADE\/1\n'
                    . 'host_id=([a-f0-9]{32})\nfrom=([AB])\nto=([AB])\n'
                    . 'prepared_at=(0|[1-9][0-9]{0,18})\n'
                    . 'deadline=(0|[1-9][0-9]{0,18})\n'
                    . 'runtime_generation=([a-f0-9]{64})\n'
                    . 'nonce=([a-f0-9]{32})\nsignature=([a-f0-9]{64})\n\z/D',
                $intent,
                $intentMatch,
            ) !== 1) {
                return null;
            }
            $preparedAt = (int)$intentMatch[4];
            $deadline = (int)$intentMatch[5];
            $signatureOffset = \strrpos($intent, 'signature=');
            $secret = \strtolower(\trim($this->readStableRegularFile(
                $this->adminTokenFile(),
                65,
                'Gateway administrator credential',
            )));
            $key = \preg_match('/\A[a-f0-9]{64}\z/D', $secret) === 1
                ? \hex2bin($secret)
                : false;
            if ($signatureOffset === false
                || !\is_string($key)
                || \strlen($key) !== 32
            ) {
                return null;
            }
            try {
                $expectedSignature = \hash_hmac(
                    'sha256',
                    \substr($intent, 0, $signatureOffset),
                    $key,
                );
            } finally {
                \sodium_memzero($key);
            }
            $intentDigest = \hash('sha256', $intent);
            if (!\hash_equals($this->hostId(), (string)$intentMatch[1])
                || !\hash_equals($active, (string)$intentMatch[2])
                || !\hash_equals($previous, (string)$intentMatch[3])
                || $preparedAt <= 0
                || $preparedAt > PHP_INT_MAX - self::FAILURE_WINDOW
                || $deadline !== $preparedAt + self::FAILURE_WINDOW
                || !\hash_equals($expectedSignature, (string)$intentMatch[8])
                || \preg_match(
                    '/\AWLS-UPGRADE-STATE\/2\n'
                        . 'intent_sha256=([a-f0-9]{64})\n'
                        . 'intent_nonce=([a-f0-9]{32})\n'
                        . 'from=([AB])\nto=([AB])\n'
                        . 'runtime_generation=([a-f0-9]{64})\n'
                        . 'boot_id=([0-9A-Za-z-]{1,64})\n'
                        . 'phase=(ROLLBACK_PENDING|ROLLED_BACK)\n'
                        . 'attempts=([0-9]{1,10})\n'
                        . 'observation_started_monotonic_ms=0\n'
                        . 'observation_deadline_monotonic_ms=0\n'
                        . 'total_deadline=(0|[1-9][0-9]{0,18})\n\z/D',
                    $state,
                    $stateMatch,
                ) !== 1
                || !\hash_equals($intentDigest, (string)$stateMatch[1])
                || !\hash_equals((string)$intentMatch[7], (string)$stateMatch[2])
                || !\hash_equals($active, (string)$stateMatch[3])
                || !\hash_equals($previous, (string)$stateMatch[4])
                || !\hash_equals((string)$intentMatch[6], (string)$stateMatch[5])
                || !\hash_equals($this->hostBootId, (string)$stateMatch[6])
                || (int)$stateMatch[8] > 3
                || $preparedAt > PHP_INT_MAX - 900
                || (int)$stateMatch[9] !== $preparedAt + 900
            ) {
                return null;
            }
            return [
                'intent_sha256' => $intentDigest,
                'cleanup_pending' => \hash_equals(
                    'ROLLBACK_PENDING',
                    (string)$stateMatch[7],
                ),
            ];
        }

        $terminal = $this->readOptionalStableRegularFile(
            $this->trustDir() . DIRECTORY_SEPARATOR . 'upgrade-rolled-back',
            1024,
            'Gateway Native rolled-back marker',
        );
        if ($terminal === null
            || \preg_match(
                '/\AWLS-UPGRADE-ROLLED-BACK\/3\n'
                    . 'intent_sha256=([a-f0-9]{64})\n'
                    . 'intent_nonce=([a-f0-9]{32})\n'
                    . 'from=([AB])\nto=([AB])\n'
                    . 'runtime_generation=([a-f0-9]{64})\nat=([1-9][0-9]{0,18})\n\z/D',
                $terminal,
                $terminalMatch,
            ) !== 1
            || !\hash_equals($active, (string)$terminalMatch[3])
            || !\hash_equals($previous, (string)$terminalMatch[4])
            || !\hash_equals(
                $active,
                (string)($previousTransaction['from_slot'] ?? ''),
            )
            || !\hash_equals(
                $previous,
                (string)($previousTransaction['to_slot'] ?? ''),
            )
            || (int)$terminalMatch[6]
                < (int)($previousTransaction['started_at'] ?? 0)
        ) {
            return null;
        }
        return [
            'intent_sha256' => (string)$terminalMatch[1],
            'cleanup_pending' => false,
        ];
    }

    private function renderNginxConfig(bool $allowH3): string
    {
        $this->ensureNeutralCertificate();
        $this->refreshH3CapabilityForActiveRuntime();
        $generation = (int)$this->state['generation'];
        $httpPort = (int)$this->state['public_http'];
        $httpsPort = (int)$this->state['public_https'];
        $pid = $this->quote($this->nginxPidFile());
        $errorLog = $this->quote($this->logDir() . DIRECTORY_SEPARATOR . 'error.log');
        $neutralCert = $this->quote($this->stateDir() . DIRECTORY_SEPARATOR . 'neutral-cert.pem');
        $neutralKey = $this->quote($this->stateDir() . DIRECTORY_SEPARATOR . 'neutral-key.pem');
        $isolation = ($this->state['isolation_mode'] ?? false) === true
            || ($this->state['security_ledger_valid'] ?? true) !== true;
        $h3 = $allowH3
            && !$isolation
            && (bool)($this->state['h3_capable'] ?? false)
            && !$this->h3QuarantinedForActiveRuntime();

        $lines = [
            'worker_processes auto;',
            ...(\PHP_OS_FAMILY === 'Windows'
                ? []
                : ['worker_rlimit_nofile 65536;']),
            'pid ' . $pid . ';',
            'error_log ' . $errorLog . ' warn;',
            'events { worker_connections 32768; multi_accept on; }',
            'http {',
            '  include ' . $this->quote($this->mimeTypesFile()) . ';',
            '  default_type application/octet-stream;',
            // Per-request host logs are unbounded and can take down the shared
            // edge by exhausting its filesystem. Control-plane audit and
            // warning/error logs remain enabled; request logging is opt-in at
            // an external bounded collector.
            '  access_log off;',
            // OpenSSL/Nginx can accept a TLS 1.3 ticket before the selected
            // virtual server's per-route key context forms a trustworthy
            // tenant boundary. Disable resumption globally until the edge can
            // prove route + certificate-generation binding at handshake time.
            '  ssl_session_cache off;',
            '  ssl_session_tickets off;',
            '  sendfile on;',
            '  keepalive_timeout 65;',
            // Match the pure-WLS edge connection budget. Nginx otherwise
            // sends GOAWAY after its default 1,000 requests per client
            // connection; a 100-connection HTTP/2 million-request gate then
            // stops at exactly 100,000 despite a healthy data plane.
            '  keepalive_requests 100000;',
            // Preserve ordinary HTTP/1.1 upstream keepalive. Only WebSocket
            // handshakes may emit "Connection: upgrade"; sending "close" for
            // every non-upgrade request defeats the upstream keepalive pool
            // and creates a two-hop TCP connection storm under HTTP/2 bursts.
            '  map $http_upgrade $connection_upgrade { default upgrade; "" ""; }',
            '  server {',
            '    listen 127.0.0.1:' . $this->healthPort() . ';',
            '    server_name _;',
            '    location = /__wls_gateway_health {',
            '      default_type application/json;',
            '      add_header X-WLS-Gateway-Generation "' . $generation . '" always;',
            '      return 200 \'{"protocol":"wls-edge/2","generation":' . $generation . '}\';',
            '    }',
            '    location / { return 404; }',
            '  }',
            '  server {',
            '    listen 0.0.0.0:' . $httpPort . ' default_server;',
            '    listen [::]:' . $httpPort . ' default_server;',
            '    server_name _;',
            '    return 404;',
            '  }',
            '  server {',
            '    listen 0.0.0.0:' . $httpsPort . ' ssl default_server;',
            '    listen [::]:' . $httpsPort . ' ssl default_server;',
            '    http2 on;',
            '    ssl_protocols TLSv1.3;',
            '    ssl_certificate ' . $neutralCert . ';',
            '    ssl_certificate_key ' . $neutralKey . ';',
            '    server_name _;',
            '    return 421;',
            '  }',
        ];

        /**
         * Each instance keeps a separate upstream and authenticated identity.
         * Sharing one upstream across instances would send the preferred
         * instance token/generation to every backend and either fail closed or
         * silently defeat the instance fence.
         *
         * @var array<string,list<array{
         *     instance_id:string,
         *     upstream:string,
         *     identity:array<string,mixed>
         * }>> $routeTransports
         */
        $routeTransports = [];
        /** @var array<string,list<array<string,mixed>>> $upstreamBackends */
        $upstreamBackends = [];
        foreach ((array)$this->state['routes'] as $route) {
            if (!\is_array($route)
                || $isolation
                || !$this->routeAllowedBySecurity($route)
                || (string)($route['status'] ?? '') === 'REMOVED'
                || (array)($route['backends'] ?? []) === []
            ) {
                continue;
            }
            $routeId = (string)$route['route_id'];
            $backendInstances = $this->routeBackendInstances($route);
            $this->assertRenderableRouteTransportTopology(
                $route,
                $backendInstances,
            );
            foreach ($backendInstances as $instanceId => $backendInstance) {
                if (!\is_array($backendInstance)) {
                    continue;
                }
                $backends = \array_values((array)($backendInstance['backends'] ?? []));
                $backendIdentity = \is_array($backendInstance['backend_identity'] ?? null)
                    ? $backendInstance['backend_identity']
                    : [];
                if ($backends === [] || $backendIdentity === []) {
                    continue;
                }
                $instanceId = (string)$instanceId;
                $upstreamDigest = \hash('sha256', $this->canonicalJson([
                    'project_uuid' => (string)($route['project_uuid'] ?? ''),
                    'instance_id' => $instanceId,
                    'backends' => $backends,
                    'backend_identity' => [
                        'instance_id' => (string)($backendIdentity['instance_id'] ?? ''),
                        'generation' => (int)($backendIdentity['generation'] ?? 0),
                        'edge_capability_digest' => (string)(
                            $backendIdentity['edge_capability_digest'] ?? ''
                        ),
                        'listener_lease_id' => (string)(
                            $backendIdentity['listener_lease_id'] ?? ''
                        ),
                    ],
                ]));
                $upstream = 'wls_backend_' . \substr($upstreamDigest, 0, 32);
                $routeTransports[$routeId][] = [
                    'instance_id' => $instanceId,
                    'upstream' => $upstream,
                    'identity' => $backendIdentity,
                ];
                $upstreamBackends[$upstream] ??= $backends;
            }
        }

        /**
         * Values used by each route's proxy directives. In distributed mode,
         * split_clients selects one authenticated transport per request, and
         * the maps switch all fencing fields as one tuple.
         *
         * @var array<string,array{
         *     upstream:string,
         *     token:string,
         *     instance_id:string,
         *     generation:string
         * }> $routeRoutingValues
         */
        $routeRoutingValues = [];
        foreach ($routeTransports as $routeId => $transports) {
            if (\count($transports) === 1) {
                $identity = (array)$transports[0]['identity'];
                $routeRoutingValues[$routeId] = [
                    'upstream' => (string)$transports[0]['upstream'],
                    'token' => $this->quote(
                        (string)($identity['edge_capability_secret'] ?? ''),
                    ),
                    'instance_id' => $this->quote(
                        (string)$transports[0]['instance_id'],
                    ),
                    'generation' => (string)(int)($identity['generation'] ?? 0),
                ];
                continue;
            }
            $prefix = 'wls_route_' . \substr(\hash('sha256', $routeId), 0, 16);
            $selector = '$' . $prefix . '_selector';
            $lines[] = '  split_clients "$request_id" ' . $selector . ' {';
            $percentage = \floor(10000 / \count($transports)) / 100;
            foreach ($transports as $index => $transport) {
                $bucket = '"' . $index . '"';
                $lines[] = $index === \array_key_last($transports)
                    ? '    * ' . $bucket . ';'
                    : '    ' . \number_format($percentage, 2, '.', '')
                        . '% ' . $bucket . ';';
            }
            $lines[] = '  }';
            foreach ([
                'upstream' => static fn (array $transport): string =>
                    (string)$transport['upstream'],
                'token' => fn (array $transport): string => $this->quote(
                    (string)($transport['identity']['edge_capability_secret'] ?? ''),
                ),
                'instance' => fn (array $transport): string => $this->quote(
                    (string)$transport['instance_id'],
                ),
                'generation' => static fn (array $transport): string =>
                    (string)(int)($transport['identity']['generation'] ?? 0),
            ] as $suffix => $value) {
                $variable = '$' . $prefix . '_' . $suffix;
                $lines[] = '  map ' . $selector . ' ' . $variable . ' {';
                $lines[] = '    default ' . $value($transports[0]) . ';';
                foreach ($transports as $index => $transport) {
                    $lines[] = '    "' . $index . '" ' . $value($transport) . ';';
                }
                $lines[] = '  }';
            }
            $routeRoutingValues[$routeId] = [
                'upstream' => '$' . $prefix . '_upstream',
                'token' => '$' . $prefix . '_token',
                'instance_id' => '$' . $prefix . '_instance',
                'generation' => '$' . $prefix . '_generation',
            ];
        }
        foreach ($upstreamBackends as $upstream => $backends) {
            $lines[] = '  upstream ' . $upstream . ' {';
            // Nginx keeps this cache per Worker. A route-sized pool of 256 can
            // permanently consume the POSIX Dispatcher's entire select() FD
            // budget. Share one bounded pool per authenticated backend
            // identity and retire idle connections promptly.
            $lines[] = '    keepalive 32;';
            $lines[] = '    keepalive_timeout ' . self::UPSTREAM_KEEPALIVE_TIMEOUT_SEC . 's;';
            $lines[] = '    keepalive_requests 10000;';
            foreach ($backends as $backend) {
                if (!\is_array($backend)) {
                    continue;
                }
                $host = (string)$backend['host'];
                if ($host === '::1') {
                    $host = '[::1]';
                }
                $lines[] = '    server ' . $host . ':' . (int)$backend['port']
                    . ' weight=' . (int)$backend['weight'] . ' max_fails=2 fail_timeout=5s;';
            }
            $lines[] = '  }';
        }

        $h3ListenerDeclared = false;
        foreach ((array)$this->state['routes'] as $route) {
            if (!\is_array($route)
                || !$this->routeAllowedBySecurity($route)
                || (string)($route['status'] ?? '') === 'REMOVED'
            ) {
                continue;
            }
            $routeId = (string)$route['route_id'];
            $domain = (string)$route['domain'];
            $status = (string)$route['status'];
            $routing = $routeRoutingValues[$routeId] ?? [
                'upstream' => '',
                'token' => '""',
                'instance_id' => '""',
                'generation' => '0',
            ];
            $upstream = (string)$routing['upstream'];
            $wwwRedirectTarget = $this->registeredWwwRedirectTarget($route);
            $lines[] = '  server {';
            $lines[] = '    listen 0.0.0.0:' . $httpPort . ';';
            $lines[] = '    listen [::]:' . $httpPort . ';';
            $lines[] = '    server_name ' . $domain . ';';
            foreach ($isolation ? [] : $this->activeAcmeChallenges($route) as $challenge) {
                $lines[] = '    location = /.well-known/acme-challenge/'
                    . (string)$challenge['token'] . ' {';
                $lines[] = '      default_type text/plain;';
                $lines[] = '      return 200 '
                    . $this->quote((string)$challenge['key_authorization']) . ';';
                $lines[] = '    }';
            }
            if ($isolation) {
                $lines[] = '    add_header X-WLS-Gateway-Mode "isolation" always;';
                $lines[] = '    add_header X-WLS-Gateway-Generation "' . $generation . '" always;';
                $lines[] = '    return 503;';
            } elseif ($status === 'PENDING_CERTIFICATE'
                && (string)($route['certificate']['state'] ?? '') !== 'disabled'
            ) {
                $lines[] = '    location / { return 404; }';
            } elseif ($status === 'ACTIVE'
                || ($status === 'PENDING_CERTIFICATE'
                    && (string)($route['certificate']['state'] ?? '') === 'disabled')
            ) {
                if ($upstream === '') {
                    $lines[] = '    add_header Retry-After "5" always;';
                    $lines[] = '    return 503;';
                } elseif (($route['force_root_to_www'] ?? false) === true
                    && $wwwRedirectTarget === null
                ) {
                    $lines[] = '    add_header X-WLS-Gateway-Mode "redirect-target-unavailable" always;';
                    $lines[] = '    add_header Retry-After "5" always;';
                    $lines[] = '    return 503;';
                } elseif ((bool)($route['force_https'] ?? true)) {
                    $forceHttpsHost = \str_starts_with($domain, '*.')
                        ? '$host'
                        : $domain;
                    $forceHttpsAuthority = $forceHttpsHost
                        . ($httpsPort === 443 ? '' : ':' . $httpsPort);
                    $lines[] = '    location / { return 308 https://'
                        . $forceHttpsAuthority . '$request_uri; }';
                } else {
                    // Plain HTTP is an explicit per-route policy, not an
                    // unauthenticated shortcut around the TLS proxy. Keep the
                    // public health surface minimal and use the same backend
                    // capability, tenant identity, header scrubbing,
                    // WebSocket/SSE and long-lived drain contract as HTTPS.
                    $lines[] = '    location = /_wls/health {';
                    $lines[] = '      if ($request_method != "GET") { return 404; }';
                    $lines[] = '      if ($args != "") { return 404; }';
                    $lines[] = '      proxy_http_version 1.1;';
                    $lines[] = '      proxy_set_header Host localhost;';
                    $lines[] = '      proxy_set_header Forwarded "";';
                    $lines[] = '      proxy_set_header X-Forwarded-For $remote_addr;';
                    $lines[] = '      proxy_set_header X-WLS-Edge-Token '
                        . (string)$routing['token'] . ';';
                    $lines[] = '      proxy_set_header X-WLS-Edge-Protocol wls-edge/2;';
                    $lines[] = '      proxy_set_header X-WLS-Probe-Nonce "";';
                    $lines[] = '      proxy_set_header X-WLS-Client-Protocol $server_protocol;';
                    $lines[] = '      proxy_set_header Connection "";';
                    $lines[] = '      proxy_hide_header X-WLS-Project-UUID;';
                    $lines[] = '      proxy_hide_header X-WLS-Instance-ID;';
                    $lines[] = '      proxy_hide_header X-WLS-Backend-Generation;';
                    $lines[] = '      proxy_hide_header X-WLS-Probe-Nonce;';
                    $lines[] = '      proxy_pass http://' . $upstream . '/_wls/health?;';
                    $lines[] = '    }';
                    // The Controller's route proof is TLS-bound. Never let an
                    // ordinary HTTP client reach the private sentinel through
                    // the catch-all application proxy.
                    $lines[] = '    location = /__wls_gateway_sentinel { return 404; }';
                    $this->appendRouteApplicationProxyLocation(
                        $lines,
                        $route,
                        $routing,
                        $upstream,
                        'http',
                        $httpPort,
                    );
                }
            } else {
                $lines[] = '    return 503;';
            }
            $lines[] = '  }';
            $certificate = (array)$route['certificate'];
            $certificatePath = (string)($certificate['cert_path'] ?? '');
            $privateKeyPath = (string)($certificate['key_path'] ?? '');
            if (!$this->certificateSnapshotValidForDomain($certificate, $domain)) {
                continue;
            }
            $lines[] = '  server {';
            $lines[] = '    listen 0.0.0.0:' . $httpsPort . ' ssl;';
            $lines[] = '    listen [::]:' . $httpsPort . ' ssl;';
            if ($h3 && !$isolation) {
                $reusePort = $h3ListenerDeclared ? '' : ' reuseport';
                $lines[] = '    listen 0.0.0.0:' . $httpsPort . ' quic' . $reusePort . ';';
                $lines[] = '    listen [::]:' . $httpsPort . ' quic' . $reusePort . ';';
                $h3ListenerDeclared = true;
            }
            $lines[] = '    http2 on;';
            $lines[] = '    ssl_protocols TLSv1.3;';
            $lines[] = '    ssl_early_data off;';
            $lines[] = '    ssl_certificate '
                . $this->quote($certificatePath) . ';';
            $lines[] = '    ssl_certificate_key '
                . $this->quote($privateKeyPath) . ';';
            $lines[] = '    server_name ' . $domain . ';';
            // `$host` falls back to the matched server_name when Host/:authority
            // is absent. Reject the absent wire header first so a correct SNI
            // cannot smuggle HTTP/1.0 or an absolute-form request into a tenant.
            $lines[] = '    if ($http_host = "") { return 421; }';
            $lines[] = '    if ($ssl_server_name != $host) { return 421; }';
            if ($h3 && !$isolation) {
                $lines[] = '    add_header Alt-Svc \'h3=":' . $httpsPort . '"; ma=3600\' always;';
            }
            if ($isolation) {
                $lines[] = '    add_header X-WLS-Gateway-Mode "isolation" always;';
                $lines[] = '    add_header X-WLS-Gateway-Generation "' . $generation . '" always;';
                $lines[] = '    add_header Retry-After "5" always;';
                $lines[] = '    return 503;';
            } elseif ($status !== 'ACTIVE') {
                $lines[] = '    add_header X-WLS-Gateway-Mode "unavailable" always;';
                $lines[] = '    add_header X-WLS-Gateway-Generation "' . $generation . '" always;';
                $lines[] = '    return 503;';
            } elseif (($route['force_root_to_www'] ?? false) === true
                && $wwwRedirectTarget === null
            ) {
                $lines[] = '    add_header X-WLS-Gateway-Mode "redirect-target-unavailable" always;';
                $lines[] = '    add_header Retry-After "5" always;';
                $lines[] = '    return 503;';
            } elseif ($wwwRedirectTarget !== '') {
                $redirectAuthority = $wwwRedirectTarget
                    . ($httpsPort === 443 ? '' : ':' . $httpsPort);
                $lines[] = '    location / { return 301 https://'
                    . $redirectAuthority . '$request_uri; }';
            } else {
                // The public benchmark contract needs the two-byte liveness
                // response, but must never expose detail=1 identity metadata.
                // Drop all query parameters and pin the authenticated project
                // capability before forwarding the exact health path.
                $lines[] = '    location = /_wls/health {';
                $lines[] = '      if ($request_method != "GET") { return 404; }';
                $lines[] = '      if ($args != "") { return 404; }';
                $lines[] = '      proxy_http_version 1.1;';
                $lines[] = '      proxy_set_header Host localhost;';
                $lines[] = '      proxy_set_header Forwarded "";';
                $lines[] = '      proxy_set_header X-Forwarded-For $remote_addr;';
                $lines[] = '      proxy_set_header X-WLS-Edge-Token '
                    . (string)$routing['token'] . ';';
                $lines[] = '      proxy_set_header X-WLS-Edge-Protocol wls-edge/2;';
                $lines[] = '      proxy_set_header X-WLS-Probe-Nonce "";';
                $lines[] = '      proxy_set_header X-WLS-Client-Protocol $server_protocol;';
                $lines[] = '      proxy_set_header Connection "";';
                $lines[] = '      proxy_hide_header X-WLS-Project-UUID;';
                $lines[] = '      proxy_hide_header X-WLS-Instance-ID;';
                $lines[] = '      proxy_hide_header X-WLS-Backend-Generation;';
                $lines[] = '      proxy_hide_header X-WLS-Probe-Nonce;';
                $lines[] = '      proxy_pass http://' . $upstream . '/_wls/health?;';
                $lines[] = '    }';
                $lines[] = '    location = /__wls_gateway_sentinel {';
                $lines[] = '      allow 127.0.0.1;';
                $lines[] = '      allow ::1;';
                $lines[] = '      deny all;';
                $lines[] = '      if ($request_method != "GET") { return 404; }';
                $lines[] = '      if ($args !~ "^nonce=[a-f0-9]{32}$") { return 404; }';
                $lines[] = '      proxy_http_version 1.1;';
                $lines[] = '      proxy_set_header Host localhost;';
                $lines[] = '      proxy_set_header Forwarded "";';
                $lines[] = '      proxy_set_header X-Forwarded-For $remote_addr;';
                $lines[] = '      proxy_set_header X-WLS-Edge-Token '
                    . (string)$routing['token'] . ';';
                $lines[] = '      proxy_set_header X-WLS-Edge-Protocol wls-edge/2;';
                $lines[] = '      proxy_set_header X-WLS-Probe-Nonce $arg_nonce;';
                $lines[] = '      proxy_set_header X-WLS-Client-Protocol $server_protocol;';
                $lines[] = '      proxy_hide_header X-WLS-Project-UUID;';
                $lines[] = '      proxy_hide_header X-WLS-Instance-ID;';
                $lines[] = '      proxy_hide_header X-WLS-Backend-Generation;';
                $lines[] = '      proxy_hide_header X-WLS-Probe-Nonce;';
                $lines[] = '      add_header X-WLS-Project-UUID '
                    . $this->quote((string)$route['project_uuid']) . ' always;';
                $lines[] = '      add_header X-WLS-Instance-ID '
                    . (string)$routing['instance_id'] . ' always;';
                $lines[] = '      add_header X-WLS-Backend-Generation '
                    . (string)$routing['generation'] . ' always;';
                $lines[] = '      add_header X-WLS-Probe-Nonce $arg_nonce always;';
                // The public sentinel proves the selected route reaches a
                // live backend, but never exposes the private signed identity
                // challenge as a public HMAC oracle.
                $lines[] = '      proxy_pass http://' . $upstream . '/_wls/health?;';
                $lines[] = '    }';
                $this->appendRouteApplicationProxyLocation(
                    $lines,
                    $route,
                    $routing,
                    $upstream,
                    'https',
                    $httpsPort,
                );
            }
            $lines[] = '  }';
        }
        $lines[] = '}';
        if ((string)($this->slotManifest()['listen_profile'] ?? 'default') === 'ipv4-only') {
            $lines = \array_values(\array_filter(
                $lines,
                static fn (string $line): bool => !\str_starts_with(
                    \ltrim($line),
                    'listen [::]:',
                ),
            ));
        }
        $this->state['h3_enabled'] = $h3;
        $config = \implode("\n", $lines) . "\n";
        $this->assertWriterSize($config, self::MAX_CONFIG_BYTES, 'Generated Nginx config');
        return $config;
    }

    /**
     * Render the ordinary tenant proxy once for both HTTP opt-in and HTTPS.
     * Keeping one implementation prevents force_https=false from drifting
     * into a weaker identity/header/upgrade/drain policy.
     *
     * @param list<string> $lines
     * @param array<string,mixed> $route
     * @param array{upstream:string,token:string,instance_id:string,generation:string} $routing
     */
    private function appendRouteApplicationProxyLocation(
        array &$lines,
        array $route,
        array $routing,
        string $upstream,
        string $forwardedProtocol,
        int $forwardedPort,
    ): void {
        if (!\in_array($forwardedProtocol, ['http', 'https'], true)
            || $forwardedPort < 1
            || $forwardedPort > 65535
            || $upstream === ''
        ) {
            throw new \RuntimeException(
                'Active route proxy transport facts are incomplete.'
            );
        }
        $lines[] = '    location / {';
        $lines[] = '      proxy_http_version 1.1;';
        $lines[] = '      proxy_set_header Host $host;';
        $lines[] = '      proxy_set_header Forwarded "";';
        $lines[] = '      proxy_set_header X-Forwarded-Proto ' . $forwardedProtocol . ';';
        $lines[] = '      proxy_set_header X-Forwarded-For $remote_addr;';
        $lines[] = '      proxy_set_header X-Forwarded-Host $host;';
        $lines[] = '      proxy_set_header X-Forwarded-Port ' . $forwardedPort . ';';
        $lines[] = '      proxy_set_header X-Real-IP $remote_addr;';
        $lines[] = '      proxy_set_header Upgrade $http_upgrade;';
        $lines[] = '      proxy_set_header Connection $connection_upgrade;';
        $lines[] = '      proxy_set_header X-WLS-Edge-Protocol wls-edge/2;';
        $lines[] = '      proxy_set_header X-WLS-Probe-Nonce "";';
        $lines[] = '      proxy_set_header X-WLS-Edge-Token '
            . (string)$routing['token'] . ';';
        $lines[] = '      proxy_set_header X-WLS-Client-Protocol $server_protocol;';
        $lines[] = '      proxy_set_header X-WLS-Project-UUID '
            . $this->quote((string)$route['project_uuid']) . ';';
        $lines[] = '      proxy_set_header X-WLS-Instance-ID '
            . (string)$routing['instance_id'] . ';';
        $lines[] = '      proxy_set_header X-WLS-Backend-Generation '
            . (string)$routing['generation'] . ';';
        $lines[] = '      proxy_buffering off;';
        // Nginx defaults proxy_next_upstream to "error timeout". Even though
        // each authenticated upstream is scoped to one WLS instance, that
        // default can replay a POST to another listener tuple after bytes may
        // already have reached application code. The gateway cannot prove the
        // request was unsent, so tenant traffic uses the conservative fence.
        $lines[] = '      proxy_next_upstream off;';
        $lines[] = '      proxy_read_timeout 3600s;';
        $lines[] = '      proxy_send_timeout 3600s;';
        $lines[] = '      proxy_pass http://' . $upstream . ';';
        $lines[] = '    }';
    }

    private function activeRuntimeGeneration(): string
    {
        return \strtolower(\trim((string)($this->slotManifest()['runtime_generation'] ?? '')));
    }

    private function refreshH3CapabilityForActiveRuntime(): void
    {
        $runtimeGeneration = $this->activeRuntimeGeneration();
        if ($runtimeGeneration === ''
            || \hash_equals(
                $runtimeGeneration,
                (string)($this->state['h3_capability_runtime_generation'] ?? ''),
            )
        ) {
            return;
        }
        $capabilities = $this->probeBinaryCapabilities($this->nginxBinary());
        $this->state['h3_capable'] = (bool)($capabilities['h3'] ?? false);
        $this->state['h3_capability_runtime_generation'] = $runtimeGeneration;
        $this->state['h3_enabled'] = false;
        if (!$this->h3QuarantinedForActiveRuntime()) {
            $this->state['h3_reason'] = (string)($capabilities['reason'] ?? '');
        }
    }

    private function h3QuarantinedForActiveRuntime(): bool
    {
        $active = $this->activeRuntimeGeneration();
        $quarantined = \strtolower(\trim(
            (string)($this->state['h3_quarantined_runtime_generation'] ?? ''),
        ));
        return $active !== ''
            && $quarantined !== ''
            && \hash_equals($active, $quarantined);
    }

    private function quarantineH3ForActiveRuntime(string $reason): void
    {
        $this->state['h3_enabled'] = false;
        $this->state['h3_reason'] = $reason;
        $this->state['h3_quarantined_runtime_generation'] = $this->activeRuntimeGeneration();
    }

    /**
     * @param array<string,mixed> $route
     * @return list<array<string,mixed>>
     */
    private function activeAcmeChallenges(array $route): array
    {
        $active = [];
        $now = \time();
        foreach ((array)($this->state['acme_challenges'] ?? []) as $challenge) {
            if (!\is_array($challenge)
                || (int)($challenge['expires_at'] ?? 0) <= $now
                || !\hash_equals(
                    (string)($route['project_uuid'] ?? ''),
                    (string)($challenge['project_uuid'] ?? ''),
                )
                || !\hash_equals(
                    (string)($route['domain'] ?? ''),
                    (string)($challenge['domain'] ?? ''),
                )
            ) {
                continue;
            }
            $active[] = $challenge;
        }
        \usort(
            $active,
            static fn (array $left, array $right): int => \strcmp(
                (string)($left['token'] ?? ''),
                (string)($right['token'] ?? ''),
            ),
        );
        return $active;
    }

    /**
     * @return array{ok:bool,message:string,pid?:int}
     */
    private function startDataPlane(): array
    {
        $brokerChannel = (string)($this->activeBrokerPeer['channel'] ?? '');
        if ($this->brokerActionsRequired()
            && (!\in_array($brokerChannel, ['admin', 'project'], true)
                || !$this->brokerActionsAvailable($brokerChannel))
        ) {
            $this->startupDataPlaneRecoveryPending = true;
            $this->state['ready'] = false;
            $this->state['health_state'] = 'CONTROL_DEGRADED';
            $this->state['recovery']['stage'] = 'BROKER_ACTION_PENDING_STARTUP';
            $this->state['recovery']['last_failure'] =
                'Nginx startup is waiting for the Native Broker internal recovery callback.';
            return [
                'ok' => false,
                'message' => 'Nginx start is deferred until Native Broker process attestation is available.',
            ];
        }
        if (!\is_file($this->configFile())) {
            return ['ok' => false, 'message' => 'Gateway Nginx config is missing.'];
        }
        $test = $this->runNginx(['-t']);
        if (($test['code'] ?? 1) !== 0) {
            return ['ok' => false, 'message' => 'nginx -t failed: ' . (string)$test['output']];
        }
        $reopenControl = \is_resource($this->controlServer);
        if ($reopenControl) {
            @\fclose($this->controlServer);
            $this->controlServer = null;
            if (\PHP_OS_FAMILY !== 'Windows') {
                if (!$this->removeUnixSocketFile($this->socketFile())) {
                    throw new \RuntimeException(
                        'Gateway control socket became unsafe before data-plane restart.'
                    );
                }
            }
        }
        try {
            $start = $this->runNginx([]);
        } finally {
            if ($reopenControl) {
                $this->controlServer = $this->openControlServer();
            }
        }
        if (($start['code'] ?? 1) !== 0) {
            return ['ok' => false, 'message' => 'Nginx start failed: ' . (string)$start['output']];
        }
        $status = [
            'ok' => false,
            'running' => false,
            'message' => 'Native process attestation has not completed.',
        ];
        for ($attempt = 0; $attempt < 30; $attempt++) {
            \usleep(100000);
            $status = $this->nginxStatus(true);
            if (($status['running'] ?? false) === true) {
                return ['ok' => true, 'message' => 'started', 'pid' => (int)$status['pid']];
            }
        }
        // A daemonized process that failed PROCESS_ATTEST is intentionally
        // left untouched with its PID/config evidence intact. Signalling or
        // deleting its PID file here would turn an attestation failure into a
        // PID-reuse kill primitive. The platform service tree owns recovery.
        return [
            'ok' => false,
            'message' => 'Nginx did not publish a Native-attested process identity: '
                . (string)($status['message'] ?? 'status unavailable'),
            'service_tree_restart_required' => true,
        ];
    }

    /**
     * @return array{ok:bool,message:string}
     */
    private function reloadDataPlane(): array
    {
        $status = $this->nginxStatus(true);
        if (!($status['running'] ?? false)) {
            return ($status['ok'] ?? false) === true
                ? $this->startDataPlane()
                : [
                    'ok' => false,
                    'message' => 'reload refused an unsafe Nginx identity: '
                        . (string)($status['message'] ?? 'status unavailable'),
                ];
        }
        $reload = $this->runNginx(['-s', 'reload']);
        return ($reload['code'] ?? 1) === 0
            ? ['ok' => true, 'message' => 'reloaded']
            : ['ok' => false, 'message' => 'reload failed: ' . (string)$reload['output']];
    }

    /**
     * Security publication barrier. A successful Nginx reload proves that new
     * handshakes see the candidate, but old workers may retain the previous
     * SSL_CTX for unbounded keepalive/H2/WebSocket/SSE sessions. Terminate the
     * freshly attested master, prove its exact PID/start tuple exited, then
     * start and probe a new master before any revocation operation is committed.
     *
     * @return array{ok:bool,message:string,receipt?:array<string,mixed>}
     */
    private function retireSecurityDataPlaneGeneration(
        int $generation,
        ?float $deadlineMonotonic = null,
    ): array {
        $status = $this->nginxStatus(true);
        $pid = $status['pid'] ?? null;
        $startId = \trim((string)($status['start_id'] ?? ''));
        if (($status['ok'] ?? false) !== true
            || ($status['running'] ?? false) !== true
            || !\is_int($pid)
            || $pid < 1
            || $startId === ''
        ) {
            return [
                'ok' => false,
                'message' => 'Old Nginx generation has no fresh Native-attested process fence.',
            ];
        }
        $stopDeadline = \min(
            $deadlineMonotonic ?? PHP_FLOAT_MAX,
            $this->monotonicNow() + 10.0,
        );
        $stop = $this->runNginx(['-s', 'stop'], $stopDeadline);
        if (($stop['code'] ?? 1) !== 0) {
            return [
                'ok' => false,
                'message' => 'Security stop signal failed: ' . (string)($stop['output'] ?? ''),
            ];
        }
        $retired = false;
        do {
            $running = $this->pidRunningState($pid);
            $observedStart = $running === true
                ? $this->processStartIdentity($pid)
                : '';
            if ($running === false
                || ($observedStart !== '' && !\hash_equals($startId, $observedStart))
            ) {
                $retired = true;
                break;
            }
            if ($this->monotonicNow() >= $stopDeadline) {
                break;
            }
            \usleep(50_000);
        } while (true);
        if (!$retired) {
            return [
                'ok' => false,
                'message' => 'Old Nginx PID/start tuple did not exit within the security deadline.',
            ];
        }
        if ($this->readPidFile($this->nginxPidFile()) === $pid) {
            $this->removeVerifiedPidFile($this->nginxPidFile());
        }
        unset($this->state['nginx_process_attestation']);
        $activation = $this->activateCurrentConfigAndProbe(
            $generation,
            $deadlineMonotonic,
        );
        if (($activation['verified'] ?? false) !== true) {
            return [
                'ok' => false,
                'message' => (string)(
                    $activation['result']['message']
                    ?? 'Replacement Nginx generation failed its exact public probes.'
                ),
            ];
        }
        $replacement = $this->nginxStatus(true);
        $replacementPid = $replacement['pid'] ?? null;
        $replacementStart = \trim((string)($replacement['start_id'] ?? ''));
        $configDigest = $this->fileHash($this->configFile());
        if (($replacement['ok'] ?? false) !== true
            || ($replacement['running'] ?? false) !== true
            || !\is_int($replacementPid)
            || $replacementPid < 1
            || $replacementStart === ''
            || ($replacementPid === $pid && \hash_equals($replacementStart, $startId))
            || \preg_match('/\A[a-f0-9]{64}\z/D', $configDigest) !== 1
        ) {
            return [
                'ok' => false,
                'message' => 'Replacement Nginx process fence is incomplete.',
            ];
        }
        $retiredRoutes = [];
        foreach ((array)($this->state['routes'] ?? []) as $route) {
            if (!\is_array($route)) {
                continue;
            }
            $certificate = \is_array($route['certificate'] ?? null)
                ? $route['certificate']
                : [];
            if (!\hash_equals(
                'disabled',
                \strtolower(\trim((string)($certificate['state'] ?? ''))),
            )) {
                continue;
            }
            $projectUuid = (string)($route['project_uuid'] ?? '');
            $domain = (string)($route['domain'] ?? '');
            $certificateGeneration = $certificate['generation'] ?? null;
            $sourceDigest = (string)($certificate['source_digest'] ?? '');
            if (!$this->validProjectUuid($projectUuid)
                || !\is_int($certificateGeneration)
                || $certificateGeneration < 1
                || !\hash_equals(
                    \hash(
                        'sha256',
                        "wls-disabled-certificate\0" . $domain . "\0"
                            . $certificateGeneration,
                    ),
                    $sourceDigest,
                )
            ) {
                continue;
            }
            $receipt = [
                'schema_version' => 1,
                'project_uuid' => $projectUuid,
                'domain' => $domain,
                'generation' => $certificateGeneration,
                'source_digest' => $sourceDigest,
                'gateway_epoch' => (string)$this->state['epoch'],
                'publication_transaction_id' => (string)(
                    $this->publication['transaction_id'] ?? ''
                ),
                'active_config_generation' => $generation,
                'active_config_digest' => $configDigest,
                'old_master_pid' => $pid,
                'old_master_start_id' => $startId,
                'new_master_pid' => $replacementPid,
                'new_master_start_id' => $replacementStart,
                'old_generation_retired' => true,
                'issued_at' => \gmdate(DATE_ATOM),
            ];
            $receipt['retirement_id'] = \hash(
                'sha256',
                $this->canonicalJson($receipt),
            );
            $this->state['security_retirements'][$projectUuid . ':' . $domain]
                = $receipt;
            $retiredRoutes[] = [
                'project_uuid' => $projectUuid,
                'domain' => $domain,
                'generation' => $certificateGeneration,
                'source_digest' => $sourceDigest,
                'retirement_id' => (string)$receipt['retirement_id'],
            ];
        }
        \usort(
            $retiredRoutes,
            static fn (array $left, array $right): int =>
                ((string)$left['project_uuid'] . ':' . (string)$left['domain'])
                    <=> ((string)$right['project_uuid'] . ':' . (string)$right['domain']),
        );
        return [
            'ok' => true,
            'message' => 'Old shared-gateway TLS generation retired.',
            'receipt' => [
                'schema_version' => 1,
                'gateway_epoch' => (string)$this->state['epoch'],
                'publication_transaction_id' => (string)(
                    $this->publication['transaction_id'] ?? ''
                ),
                'active_config_generation' => $generation,
                'active_config_digest' => $configDigest,
                'old_master_pid' => $pid,
                'old_master_start_id' => $startId,
                'new_master_pid' => $replacementPid,
                'new_master_start_id' => $replacementStart,
                'old_generation_retired' => true,
                'retired_routes_digest' => \hash(
                    'sha256',
                    $this->canonicalJson($retiredRoutes),
                ),
                'completed_at' => \gmdate(DATE_ATOM),
            ],
        ];
    }

    private function forceStopSecurityDataPlane(): bool
    {
        $status = $this->nginxStatus(true);
        $pid = $status['pid'] ?? null;
        $startId = \trim((string)($status['start_id'] ?? ''));
        if (($status['ok'] ?? false) !== true) {
            return false;
        }
        if (($status['running'] ?? false) !== true) {
            return true;
        }
        if (!\is_int($pid) || $pid < 1 || $startId === '') {
            return false;
        }
        $deadline = $this->monotonicNow() + 10.0;
        $stop = $this->runNginx(['-s', 'stop'], $deadline);
        if (($stop['code'] ?? 1) !== 0) {
            return false;
        }
        do {
            $running = $this->pidRunningState($pid);
            $observedStart = $running === true
                ? $this->processStartIdentity($pid)
                : '';
            if ($running === false
                || ($observedStart !== '' && !\hash_equals($startId, $observedStart))
            ) {
                return true;
            }
            \usleep(50_000);
        } while ($this->monotonicNow() < $deadline);
        return false;
    }

    private function publicationSecurityRetirementProven(): bool
    {
        if ($this->publication === null
            || ($this->publication['irrevocable_security'] ?? false) !== true
        ) {
            return true;
        }
        $receipt = \is_array($this->publication['security_retirement'] ?? null)
            ? $this->publication['security_retirement']
            : [];
        $candidateGeneration = (int)(
            $this->publication['candidate_generation'] ?? 0
        );
        $candidateDigest = (string)(
            $this->publication['candidate_digest'] ?? ''
        );
        return ($receipt['schema_version'] ?? null) === 1
            && ($receipt['old_generation_retired'] ?? false) === true
            && $candidateGeneration > 0
            && (int)($receipt['active_config_generation'] ?? 0) === $candidateGeneration
            && \preg_match('/\A[a-f0-9]{64}\z/D', $candidateDigest) === 1
            && \hash_equals(
                $candidateDigest,
                (string)($receipt['active_config_digest'] ?? ''),
            )
            && \hash_equals(
                (string)($this->state['epoch'] ?? ''),
                (string)($receipt['gateway_epoch'] ?? ''),
            )
            && \hash_equals(
                (string)($this->publication['transaction_id'] ?? ''),
                (string)($receipt['publication_transaction_id'] ?? ''),
            )
            && \is_int($receipt['old_master_pid'] ?? null)
            && (int)$receipt['old_master_pid'] > 0
            && \trim((string)($receipt['old_master_start_id'] ?? '')) !== ''
            && \is_int($receipt['new_master_pid'] ?? null)
            && (int)$receipt['new_master_pid'] > 0
            && \trim((string)($receipt['new_master_start_id'] ?? '')) !== '';
    }

    /**
     * @return array{ok:bool,message:string}
     */
    private function stopDataPlane(): array
    {
        $status = $this->nginxStatus(true);
        if (!($status['running'] ?? false)) {
            if (($status['ok'] ?? false) !== true) {
                return [
                    'ok' => false,
                    'message' => (string)($status['message'] ?? 'Nginx PID identity is unsafe.'),
                ];
            }
            $this->removeVerifiedPidFile($this->nginxPidFile());
            $this->releaseWindowsNginxProcess($this->configFile());
            return ['ok' => true, 'message' => 'not running'];
        }
        $pid = (int)$status['pid'];
        $startId = (string)($status['start_id'] ?? '');
        $quit = $this->runNginx(['-s', 'quit']);
        if (($quit['code'] ?? 1) !== 0) {
            return ['ok' => false, 'message' => 'graceful stop failed: ' . (string)$quit['output']];
        }
        $deadline = $this->monotonicNow() + 30.0;
        while ($this->monotonicNow() < $deadline) {
            if (!$this->brokerGenerationOwned()) {
                $this->running = false;
                return [
                    'ok' => false,
                    'message' => 'Nginx stop observation was retired by a new Broker generation.',
                ];
            }
            $currentPid = $this->readPidFile($this->nginxPidFile());
            if ($currentPid === null) {
                unset($this->state['nginx_process_attestation']);
                $this->releaseWindowsNginxProcess($this->configFile());
                return ['ok' => true, 'message' => 'stopped'];
            }
            if ($currentPid !== $pid) {
                return [
                    'ok' => false,
                    'message' => 'Nginx PID changed during graceful stop; no PID evidence was removed.',
                ];
            }
            if ($this->pidRunningState($pid) === false) {
                $this->removeVerifiedPidFile($this->nginxPidFile());
                unset($this->state['nginx_process_attestation']);
                $this->releaseWindowsNginxProcess($this->configFile());
                return ['ok' => true, 'message' => 'stopped'];
            }
            $currentStartId = $this->processStartIdentity($pid);
            if ($startId !== '' && $currentStartId !== ''
                && !\hash_equals($startId, $currentStartId)
            ) {
                return [
                    'ok' => false,
                    'message' => 'Nginx PID was reused during graceful stop; no PID evidence was removed.',
                ];
            }
            \usleep(100000);
        }
        return ['ok' => false, 'message' => 'Nginx graceful stop timed out; no unverified signal was sent.'];
    }

    /**
     * @return array<string,mixed>
     */
    private function nginxStatus(
        bool $requireFreshNativeAttestation = false,
        bool $refreshFromBroker = true,
    ): array
    {
        $pid = $this->readPidFile($this->nginxPidFile());
        if ($pid === null) {
            return ['ok' => true, 'running' => false, 'pid' => null, 'message' => 'not running'];
        }
        if ($pid < 1) {
            return [
                'ok' => false,
                'running' => false,
                'pid' => null,
                'message' => 'unsafe or malformed Nginx PID file',
            ];
        }
        $tracked = $this->windowsTrackedNginxMatches($this->configFile(), $pid);
        $brokerAdopted = \PHP_OS_FAMILY === 'Windows'
            && $this->brokerAdoptedNginxPid !== null
            && $this->brokerAdoptedNginxPid === $pid;
        if ($tracked === null
            && !$brokerAdopted
            && $this->pidRunningState($pid) === false
        ) {
            return ['ok' => true, 'running' => false, 'pid' => $pid, 'message' => 'stale pid'];
        }
        $binary = $this->nginxBinary();
        $expectedHash = (string)($this->slotManifest()['components'][
            'bin/' . $this->nginxBinaryName()
        ]['sha256'] ?? '');
        if ($expectedHash === '') {
            return ['ok' => false, 'running' => false, 'pid' => $pid, 'message' => 'binary digest missing from release manifest'];
        }
        $actualHash = $this->fileHash($binary);
        if ($actualHash === '') {
            return ['ok' => false, 'running' => false, 'pid' => $pid, 'message' => 'binary digest unavailable'];
        }
        if (!\hash_equals($expectedHash, $actualHash)) {
            return ['ok' => false, 'running' => false, 'pid' => $pid, 'message' => 'binary digest mismatch'];
        }
        if ($tracked === false) {
            return [
                'ok' => false,
                'running' => false,
                'pid' => $pid,
                'message' => 'tracked process PID mismatch',
                'service_tree_restart_required' => true,
            ];
        }
        $brokerChannel = (string)($this->activeBrokerPeer['channel'] ?? '');
        if ($refreshFromBroker
            && !$this->readOnlyRecoveryMode
            && \in_array($brokerChannel, ['admin', 'project'], true)
            && $this->brokerActionsAvailable($brokerChannel)
        ) {
            try {
                $attestation = $this->attestNginxProcess(
                    $brokerChannel,
                    $pid,
                    $expectedHash,
                );
                return [
                    'ok' => true,
                    'running' => true,
                    'pid' => $pid,
                    'start_id' => (string)$attestation['start_id'],
                    'attestation' => 'native',
                    'message' => 'running',
                ];
            } catch (\Throwable $throwable) {
                return [
                    'ok' => false,
                    'running' => false,
                    'pid' => $pid,
                    'message' => 'Native PROCESS_ATTEST failed: ' . $throwable->getMessage(),
                    'service_tree_restart_required' => true,
                ];
            }
        }
        $cached = $this->cachedNginxProcessAttestation(
            $pid,
            $expectedHash,
            $requireFreshNativeAttestation,
        );
        if ($cached !== null) {
            return [
                'ok' => true,
                'running' => true,
                'pid' => $pid,
                'start_id' => (string)$cached['start_id'],
                'attestation' => 'cached_native_receipt',
                'message' => 'running',
            ];
        }
        if ($this->brokerActionsRequired()) {
            return [
                'ok' => false,
                'running' => false,
                'pid' => $pid,
                'message' => $requireFreshNativeAttestation
                    ? 'A fresh Native PROCESS_ATTEST receipt is required before signalling Nginx.'
                    : 'The live Nginx process has no valid Native PROCESS_ATTEST receipt.',
                'service_tree_restart_required' => true,
            ];
        }
        if ($tracked === null && !$brokerAdopted) {
            $command = $this->processCommand($pid);
            if (\PHP_OS_FAMILY === 'Windows') {
                $normalizedCommand = \strtolower(\str_replace('/', '\\', $command));
                $identityMatches = $command !== ''
                    && \str_contains(
                        $normalizedCommand,
                        \strtolower(\str_replace('/', '\\', $binary)),
                    )
                    && \str_contains(
                        $normalizedCommand,
                        \strtolower(\str_replace('/', '\\', $this->configFile())),
                    );
            } else {
                $identityMatches = $this->posixNginxIdentityMatches(
                    $pid,
                    $command,
                    $expectedHash,
                );
            }
            if (!$identityMatches) {
                return ['ok' => false, 'running' => false, 'pid' => $pid, 'message' => 'adopted process identity mismatch'];
            }
        }
        return [
            'ok' => true,
            'running' => true,
            'pid' => $pid,
            'start_id' => $this->processStartIdentity($pid),
            'attestation' => 'test_mode_compatibility',
            'message' => 'running',
        ];
    }

    /**
     * @return array<string,mixed>
     */
    private function attestNginxProcess(
        string $channel,
        int $pid,
        string $expectedBinaryDigest,
    ): array {
        $runtimeGeneration = $this->activeRuntimeGeneration();
        $configDigest = $this->fileHash($this->configFile());
        $configPathDigest = \hash('sha256', $this->configFile());
        $publicationGeneration = (int)($this->state['active_config_generation'] ?? 0);
        if ($pid < 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $expectedBinaryDigest) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $runtimeGeneration) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $configDigest) !== 1
            || $publicationGeneration < 0
        ) {
            throw new \RuntimeException(
                'Current runtime/config evidence is incomplete for PROCESS_ATTEST.'
            );
        }
        $stored = \is_array($this->state['nginx_process_attestation'] ?? null)
            ? $this->state['nginx_process_attestation']
            : [];
        $expectedStartId = '';
        if ((int)($stored['pid'] ?? 0) === $pid
            && \preg_match('/\A[1-9][0-9]*\z/D', (string)($stored['start_id'] ?? '')) === 1
        ) {
            // Reusing the last Native birth identity makes PID reuse fail the
            // action instead of silently discovering a different process.
            $expectedStartId = (string)$stored['start_id'];
        } else {
            $expectedStartId = $this->processStartIdentity($pid);
        }
        if ($expectedStartId === '') {
            // macOS has no safe PHP API for proc_pidinfo. Native performs two
            // kernel reads and returns the actual birth identity; subsequent
            // attestations are pinned to that exact value.
            $expectedStartId = '-';
        }
        $response = $this->brokerAction($channel, [
            'PROCESS_ATTEST',
            (string)$pid,
            $expectedStartId,
            $expectedBinaryDigest,
            $runtimeGeneration,
            $configDigest,
            $configPathDigest,
            (string)$publicationGeneration,
        ]);
        if (\count($response) !== 8
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[0]) !== 1
            || (int)$response[1] !== $pid
            || \preg_match('/\A[1-9][0-9]*\z/D', (string)$response[2]) !== 1
            || !\hash_equals($expectedBinaryDigest, (string)$response[3])
            || !\hash_equals($runtimeGeneration, (string)$response[4])
            || !\hash_equals($configDigest, (string)$response[5])
            || !\hash_equals($configPathDigest, (string)$response[6])
            || (int)$response[7] !== $publicationGeneration
            || ($expectedStartId !== '-'
                && !\hash_equals($expectedStartId, (string)$response[2]))
        ) {
            throw new \RuntimeException(
                'Native Broker returned a malformed PROCESS_ATTEST receipt.'
            );
        }
        $receipt = $this->processAttestationReceiptContents([
            'pid' => $pid,
            'start_id' => (string)$response[2],
            'binary_digest' => (string)$response[3],
            'runtime_generation' => (string)$response[4],
            'config_digest' => (string)$response[5],
            'config_path_digest' => (string)$response[6],
            'publication_generation' => (int)$response[7],
        ]);
        $receiptState = $this->readStableRegularFileWithStatus(
            $this->processAttestationReceiptFile(),
            4096,
            'Native Nginx process-attestation receipt',
        );
        if (!\hash_equals($receipt, (string)$receiptState['contents'])
            || !\hash_equals((string)$response[0], \hash('sha256', $receipt))
            || !$this->nativeReceiptOwnerTrusted((array)$receiptState['status'])
        ) {
            throw new \RuntimeException(
                'Native PROCESS_ATTEST receipt is not the root-owned acknowledged artifact.'
            );
        }
        $attestation = [
            'schema_version' => 2,
            'receipt_digest' => (string)$response[0],
            'pid' => $pid,
            'start_id' => (string)$response[2],
            'binary_digest' => (string)$response[3],
            'runtime_generation' => (string)$response[4],
            'config_digest' => (string)$response[5],
            'config_path_digest' => (string)$response[6],
            'publication_generation' => (int)$response[7],
            'attested_at' => \gmdate(DATE_ATOM),
        ];
        $this->state['nginx_process_attestation'] = $attestation;
        $this->persistState();
        return $attestation;
    }

    /**
     * @return array<string,mixed>|null
     */
    private function cachedNginxProcessAttestation(
        int $pid,
        string $expectedBinaryDigest,
        bool $requireFreshNativeAttestation,
    ): ?array {
        $attestation = $this->state['nginx_process_attestation'] ?? null;
        if (!\is_array($attestation)
            || (int)($attestation['schema_version'] ?? 0) !== 2
            || (int)($attestation['pid'] ?? 0) !== $pid
            || !\hash_equals(
                $expectedBinaryDigest,
                (string)($attestation['binary_digest'] ?? ''),
            )
            || !\hash_equals(
                $this->activeRuntimeGeneration(),
                (string)($attestation['runtime_generation'] ?? ''),
            )
            || !\hash_equals(
                $this->fileHash($this->configFile()),
                (string)($attestation['config_digest'] ?? ''),
            )
            || !\hash_equals(
                \hash('sha256', $this->configFile()),
                (string)($attestation['config_path_digest'] ?? ''),
            )
            || (int)($attestation['publication_generation'] ?? -1) < 0
            || (int)($attestation['publication_generation'] ?? -1)
                > (int)($this->state['active_config_generation'] ?? 0)
            || \preg_match(
                '/\A[1-9][0-9]*\z/D',
                (string)($attestation['start_id'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($attestation['receipt_digest'] ?? ''),
            ) !== 1
        ) {
            return null;
        }
        try {
            $receiptState = $this->readStableRegularFileWithStatus(
                $this->processAttestationReceiptFile(),
                4096,
                'Cached Native Nginx process-attestation receipt',
            );
        } catch (\Throwable) {
            return null;
        }
        $receipt = $this->processAttestationReceiptContents($attestation);
        if (!\hash_equals($receipt, (string)$receiptState['contents'])
            || !\hash_equals(
                (string)$attestation['receipt_digest'],
                \hash('sha256', $receipt),
            )
            || !$this->nativeReceiptOwnerTrusted((array)$receiptState['status'])
        ) {
            return null;
        }
        $currentStartId = $this->processStartIdentity($pid);
        if ($currentStartId !== ''
            && !\hash_equals((string)$attestation['start_id'], $currentStartId)
        ) {
            return null;
        }
        if ($requireFreshNativeAttestation && $currentStartId === '') {
            return null;
        }
        if ($currentStartId === '') {
            $command = $this->processCommand($pid);
            if (!$this->posixNginxIdentityMatches(
                $pid,
                $command,
                $expectedBinaryDigest,
            )) {
                return null;
            }
        }
        return $attestation;
    }

    /** @param array<string,mixed> $attestation */
    private function processAttestationReceiptContents(array $attestation): string
    {
        return "WLS-PROCESS-ATTEST/2\n"
            . 'pid=' . (int)($attestation['pid'] ?? 0) . "\n"
            . 'start_id=' . (string)($attestation['start_id'] ?? '') . "\n"
            . 'binary_digest=' . (string)($attestation['binary_digest'] ?? '') . "\n"
            . 'runtime_generation=' . (string)($attestation['runtime_generation'] ?? '') . "\n"
            . 'config_digest=' . (string)($attestation['config_digest'] ?? '') . "\n"
            . 'config_path_digest=' . (string)($attestation['config_path_digest'] ?? '') . "\n"
            . 'publication_generation=' . (int)(
                $attestation['publication_generation'] ?? -1
            ) . "\n";
    }

    /** @param array<string|int,mixed> $status */
    private function nativeReceiptOwnerTrusted(array $status): bool
    {
        if (\PHP_OS_FAMILY === 'Windows') {
            // The Native service writes through the root-owned trust
            // directory ACL and opens without following reparse points.
            return true;
        }
        if ((((int)($status['mode'] ?? 0)) & 0022) !== 0) {
            return false;
        }
        $owner = (int)($status['uid'] ?? -1);
        if ($owner === 0) {
            return true;
        }
        return ($this->slotManifest()['test_mode'] ?? false) === true
            && \function_exists('posix_geteuid')
            && $owner === (int)\posix_geteuid();
    }

    private function processStartIdentity(int $pid): string
    {
        if ($pid < 1) {
            return '';
        }
        if (\PHP_OS_FAMILY === 'Linux') {
            $contents = $this->readLinuxProcPseudoFile(
                '/proc/' . $pid . '/stat',
                4096,
            );
            if ($contents === null || $contents === '') {
                return '';
            }
            $close = \strrpos($contents, ')');
            if ($close === false || !\str_starts_with(\substr($contents, $close + 1), ' ')) {
                return '';
            }
            $fields = \preg_split('/\s+/', \trim(\substr($contents, $close + 2))) ?: [];
            $startId = (string)($fields[19] ?? '');
            return \preg_match('/\A[1-9][0-9]*\z/D', $startId) === 1
                ? $startId
                : '';
        }
        if (\PHP_OS_FAMILY === 'Windows') {
            $systemRoot = \rtrim((string)\getenv('SystemRoot'), '\\/');
            $powershell = $systemRoot !== ''
                ? $systemRoot . '\\System32\\WindowsPowerShell\\v1.0\\powershell.exe'
                : 'powershell.exe';
            try {
                $startId = $this->boundedCommandOutput([
                    $powershell,
                    '-NoLogo',
                    '-NoProfile',
                    '-NonInteractive',
                    '-ExecutionPolicy',
                    'Bypass',
                    '-Command',
                    '(Get-Process -Id ' . $pid . ' -ErrorAction Stop).StartTime.ToUniversalTime().ToFileTimeUtc()',
                ]);
                return \preg_match('/\A[1-9][0-9]*\z/D', $startId) === 1
                    ? $startId
                    : '';
            } catch (\Throwable) {
                return '';
            }
        }
        return '';
    }

    private function readLinuxProcPseudoFile(
        string $path,
        int $maximumBytes,
    ): ?string {
        if (\PHP_OS_FAMILY !== 'Linux'
            || $maximumBytes < 1
            || ($path !== '/proc/sys/kernel/random/boot_id'
                && \preg_match('/\A\/proc\/[1-9][0-9]*\/stat\z/D', $path) !== 1)
        ) {
            throw new \LogicException('Linux proc pseudo-file request is outside the allowlist.');
        }
        $before = @\lstat($path);
        if (!\is_array($before)
            || \is_link($path)
            || ((((int)($before['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($before['nlink'] ?? 0) !== 1
        ) {
            return null;
        }
        $handle = @\fopen($path, 'rb');
        if (!\is_resource($handle)) {
            return null;
        }
        try {
            $opened = @\fstat($handle);
            if (!\is_array($opened)
                || !$this->sameProcFileIdentity($before, $opened)
            ) {
                return null;
            }
            $contents = @\stream_get_contents($handle, $maximumBytes + 1);
            $after = @\fstat($handle);
            $pathAfter = @\lstat($path);
            if (!\is_string($contents)
                || \strlen($contents) > $maximumBytes
                || !\is_array($after)
                || !\is_array($pathAfter)
                || \is_link($path)
                || !$this->sameProcFileIdentity($opened, $after)
                || !$this->sameProcFileIdentity($after, $pathAfter)
            ) {
                return null;
            }
            return $contents;
        } finally {
            @\fclose($handle);
        }
    }

    /**
     * Linux proc pseudo-files report synthetic or changing sizes/timestamps.
     * Bind only the opened object identity and regular-file type, never path
     * metadata that the kernel intentionally mutates while it is read.
     *
     * @param array<string|int,mixed> $before
     * @param array<string|int,mixed> $after
     */
    private function sameProcFileIdentity(array $before, array $after): bool
    {
        foreach (['dev', 'ino', 'mode', 'nlink'] as $key) {
            if (!\array_key_exists($key, $before)
                || !\array_key_exists($key, $after)
                || (int)$before[$key] !== (int)$after[$key]
            ) {
                return false;
            }
        }
        return ((((int)$after['mode']) & 0170000) === 0100000)
            && (int)$after['nlink'] === 1;
    }

    /**
     * A/B activation may leave the verified Nginx master running from the
     * previous immutable slot while the new Controller takes over. Accept
     * only an A/B slot binary with the active release digest and the exact
     * host-gateway config. Linux additionally hashes the live executable via
     * /proc so replacing an on-disk path cannot forge process identity.
     */
    private function posixNginxIdentityMatches(
        int $pid,
        string $command,
        string $expectedHash,
    ): bool {
        if ($pid < 1
            || $command === ''
            || \preg_match('/\A[a-f0-9]{64}\z/D', $expectedHash) !== 1
            || !\str_contains($command, $this->configFile())
        ) {
            return false;
        }

        $matchedBinary = '';
        foreach (['A', 'B'] as $slot) {
            $candidate = $this->slotDir($slot)
                . DIRECTORY_SEPARATOR . 'bin'
                . DIRECTORY_SEPARATOR . $this->nginxBinaryName();
            if (\str_contains($command, $candidate)
                && \hash_equals($expectedHash, $this->fileHash($candidate))
            ) {
                $matchedBinary = $candidate;
                break;
            }
        }
        if ($matchedBinary === '') {
            return false;
        }

        $liveExecutable = '/proc/' . $pid . '/exe';
        if (\PHP_OS_FAMILY === 'Linux' && \file_exists($liveExecutable)) {
            $liveHash = $this->fileHash($liveExecutable);
            if ($liveHash !== '') {
                return \hash_equals($expectedHash, $liveHash);
            }
        }

        // Darwin has no /proc executable link. Linux also denies an
        // unprivileged Controller access to a root-owned Nginx executable,
        // especially after the previous slot inode has been replaced. In
        // both cases the command comes from the kernel process table and the
        // matched A/B slot remains immutable and package-verified.
        return true;
    }

    private function publicPortsReachable(
        ?int $expectedGeneration = null,
        bool $cooperative = false,
        ?float $deadlineMonotonic = null,
    ): bool
    {
        $deadlineMonotonic ??= $this->monotonicNow() + 3.0;
        ++$this->probeCriticalSectionDepth;
        try {
        $hosts = ['127.0.0.1'];
        if ((string)($this->slotManifest()['listen_profile'] ?? 'default') !== 'ipv4-only') {
            $hosts[] = '::1';
        }
        foreach ($hosts as $host) {
            foreach ([(int)$this->state['public_http'], (int)$this->state['public_https']] as $port) {
                if ($cooperative) {
                    $this->serviceControlDuringPublicationProbe();
                }
                $target = $host === '::1'
                    ? 'tcp://[::1]:' . $port
                    : 'tcp://127.0.0.1:' . $port;
                $remaining = $deadlineMonotonic - $this->monotonicNow();
                if ($remaining <= 0.0) {
                    return false;
                }
                $socket = @\stream_socket_client(
                    $target,
                    $errno,
                    $error,
                    \min(0.5, $remaining),
                );
                if (!\is_resource($socket)) {
                    return false;
                }
                @\fclose($socket);
            }
        }
        if ($cooperative) {
            $this->serviceControlDuringPublicationProbe();
        }
        $remaining = $deadlineMonotonic - $this->monotonicNow();
        if ($remaining <= 0.0) {
            return false;
        }
        $socket = @\stream_socket_client(
            'tcp://127.0.0.1:' . $this->healthPort(),
            $errno,
            $error,
            \min(0.5, $remaining),
        );
        if (!\is_resource($socket)) {
            return false;
        }
        if (!$this->writeStreamAll(
            $socket,
            "GET /__wls_gateway_health HTTP/1.1\r\n"
                . "Host: localhost\r\nConnection: close\r\n\r\n",
        )) {
            @\fclose($socket);
            return false;
        }
        $response = $this->readProbeResponse(
            $socket,
            262144,
            1.0,
            $cooperative,
            $deadlineMonotonic,
        );
        @\fclose($socket);
        $expectedGeneration ??= (int)($this->state['active_config_generation'] ?? 0);
        return $this->gatewayHealthResponseMatches($response, $expectedGeneration);
        } finally {
            --$this->probeCriticalSectionDepth;
        }
    }

    private function publicRoutesReachable(
        bool $cooperative = false,
        ?float $deadlineMonotonic = null,
        ?int $httpsPort = null,
    ): bool
    {
        $deadlineMonotonic ??= $this->monotonicNow() + 10.0;
        ++$this->probeCriticalSectionDepth;
        try {
        $this->lastPublicProbeFailureKind = '';
        $isolation = ($this->state['isolation_mode'] ?? false) === true
            || ($this->state['security_ledger_valid'] ?? true) !== true;
        $routes = $this->routesForActiveProbe();
        \ksort($routes, SORT_STRING);
        $routeKeys = \array_keys($routes);
        $routeCount = \count($routeKeys);
        if ($httpsPort === null) {
            $currentProofIds = \array_fill_keys(
                \array_map('strval', $routeKeys),
                true,
            );
            foreach (\array_keys($this->publicRouteProbeResults) as $proofRouteId) {
                if (!isset($currentProofIds[(string)$proofRouteId])) {
                    unset($this->publicRouteProbeResults[(string)$proofRouteId]);
                }
            }
        }
        $incremental = !$cooperative;
        if ($incremental) {
            $probeSetDigest = \hash('sha256', $this->canonicalJson([
                'generation' => $this->expectedPublicProbeGeneration(),
                'isolation' => $isolation,
                'routes' => $routeKeys,
            ]));
            if (!\hash_equals($this->publicRouteProbeSetDigest, $probeSetDigest)) {
                $this->publicRouteProbeSetDigest = $probeSetDigest;
                $this->publicRouteProbeCursor = 0;
                $this->publicRouteProbeSweepStartedAt = $this->monotonicNow();
            } elseif ($this->publicRouteProbeCursor === 0
                && $this->publicRouteProbeSweepStartedAt <= 0.0
            ) {
                $this->publicRouteProbeSweepStartedAt = $this->monotonicNow();
            }
        }
        $routeIndex = $incremental
            ? \min($routeCount, \max(0, $this->publicRouteProbeCursor))
            : 0;
        while ($routeIndex < $routeCount) {
            if ($this->monotonicNow() >= $deadlineMonotonic) {
                if ($incremental) {
                    $this->publicRouteProbeCursor = $routeIndex;
                }
                $this->lastPublicProbeFailureKind = 'deferred';
                return false;
            }
            $route = $routes[(string)$routeKeys[$routeIndex]] ?? null;
            if (!\is_array($route)
                || !$this->routeAllowedBySecurity($route)
            ) {
                ++$routeIndex;
                if ($incremental) {
                    $this->publicRouteProbeCursor = $routeIndex;
                }
                continue;
            }
            $certificate = (array)($route['certificate'] ?? []);
            $certificateValid = $this->certificateSnapshotValidForDomain(
                $certificate,
                (string)($route['domain'] ?? ''),
            );
            $httpOnly = (string)($route['status'] ?? '') === 'PENDING_CERTIFICATE'
                && \hash_equals('disabled', $this->certificateLifecycleState($certificate))
                && ($route['force_https'] ?? true) === false;
            if (!$certificateValid) {
                if ($httpOnly) {
                    if ($cooperative) {
                        $this->serviceControlDuringPublicationProbe();
                    }
                    $healthy = $this->probePublicHttpOnlyRoute(
                        $route,
                        $cooperative,
                        $deadlineMonotonic,
                        $isolation,
                    );
                    if ($httpsPort === null) {
                        $this->recordPublicRouteProbeResult(
                            $route,
                            $healthy,
                            $isolation,
                            $healthy ? '' : $this->lastPublicProbeFailureKind,
                        );
                    }
                    if (!$healthy) {
                        if ($incremental) {
                            $this->publicRouteProbeCursor = \min(
                                $routeCount,
                                $routeIndex + 1,
                            );
                        }
                        return false;
                    }
                    ++$routeIndex;
                    if ($incremental) {
                        $this->publicRouteProbeCursor = $routeIndex;
                    }
                    continue;
                }
                if ((string)($route['status'] ?? '') === 'ACTIVE') {
                    $this->lastPublicProbeFailureKind = 'data_plane';
                    if ($httpsPort === null) {
                        $this->recordPublicRouteProbeResult(
                            $route,
                            false,
                            $isolation,
                            'data_plane',
                        );
                    }
                    if ($incremental) {
                        $this->publicRouteProbeCursor = \min(
                            $routeCount,
                            $routeIndex + 1,
                        );
                    }
                    return false;
                }
                ++$routeIndex;
                if ($incremental) {
                    $this->publicRouteProbeCursor = $routeIndex;
                }
                continue;
            }
            if ($cooperative) {
                $this->serviceControlDuringPublicationProbe();
            }
            if (!$this->probePublicRoute(
                $route,
                $httpsPort,
                $cooperative,
                $deadlineMonotonic,
                $isolation,
            )) {
                if ($this->monotonicNow() >= $deadlineMonotonic
                    && !\in_array(
                        $this->lastPublicProbeFailureKind,
                        ['backend_transport', 'backend_identity'],
                        true,
                    )
                ) {
                    $this->lastPublicProbeFailureKind = 'deferred';
                }
                if ($httpsPort === null
                    && !\hash_equals('deferred', $this->lastPublicProbeFailureKind)
                ) {
                    $this->recordPublicRouteProbeResult(
                        $route,
                        false,
                        $isolation,
                        $this->lastPublicProbeFailureKind,
                    );
                }
                if ($incremental) {
                    // A concrete tenant failure must not pin the shared cursor
                    // forever and starve later projects of their independent
                    // readiness proof. Deferred work has no failure evidence
                    // and resumes the same route; a proved failure advances.
                    $this->publicRouteProbeCursor = \hash_equals(
                        'deferred',
                        $this->lastPublicProbeFailureKind,
                    ) ? $routeIndex : \min($routeCount, $routeIndex + 1);
                }
                return false;
            }
            if ($httpsPort === null) {
                $this->recordPublicRouteProbeResult(
                    $route,
                    true,
                    $isolation,
                    '',
                );
            }
            ++$routeIndex;
            if ($incremental) {
                $this->publicRouteProbeCursor = $routeIndex;
            }
        }
        if ($this->monotonicNow() >= $deadlineMonotonic) {
            if ($incremental) {
                // routeCount is a sentinel meaning only the neutral-domain
                // proof remains; do not restart the route sweep at index zero.
                $this->publicRouteProbeCursor = $routeCount;
            }
            $this->lastPublicProbeFailureKind = 'deferred';
            return false;
        }
        $neutral = $this->probeUnknownDomain(
            $httpsPort,
            $cooperative,
            $deadlineMonotonic,
        );
        if (!$neutral) {
            $this->lastPublicProbeFailureKind = $this->monotonicNow() >= $deadlineMonotonic
                ? 'deferred'
                : 'data_plane';
            if ($incremental) {
                $this->publicRouteProbeCursor = $routeCount;
            }
            return false;
        }
        if ($incremental) {
            $this->publicRouteProbeCursor = 0;
            $this->publicRouteProbeSweepStartedAt = 0.0;
            if (!$this->publicRouteProbeSweepProofsHealthy($routes, $isolation)) {
                return false;
            }
        }
        return true;
        } finally {
            --$this->probeCriticalSectionDepth;
        }
    }

    /** @param array<string,mixed> $route */
    private function probePublicHttpOnlyRoute(
        array $route,
        bool $cooperative,
        float $deadlineMonotonic,
        bool $isolation,
    ): bool {
        $this->lastPublicProbeFailureKind = 'data_plane';
        $domain = (string)($route['domain'] ?? '');
        if ($isolation
            || $domain === ''
            || \str_starts_with($domain, '*.')
            || $this->routeBackendInstances($route) === []
        ) {
            return false;
        }
        for ($attempt = 1; $attempt <= 3; ++$attempt) {
            $remaining = $deadlineMonotonic - $this->monotonicNow();
            if ($remaining <= 0.0) {
                return false;
            }
            if ($cooperative) {
                $this->serviceControlDuringPublicationProbe();
            }
            $socket = @\stream_socket_client(
                'tcp://127.0.0.1:' . (int)$this->state['public_http'],
                $errno,
                $error,
                \min(1.0, $remaining),
                STREAM_CLIENT_CONNECT,
            );
            if (!\is_resource($socket)) {
                if ($attempt < 3 && $cooperative) {
                    $this->publicationProbePause();
                    continue;
                }
                return false;
            }
            try {
                $request = "GET /_wls/health HTTP/1.1\r\n"
                    . "Host: {$domain}\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n";
                if (!$this->writeStreamAll($socket, $request)) {
                    $this->lastPublicProbeFailureKind = 'backend_transport';
                    continue;
                }
                $response = $this->readProbeResponse(
                    $socket,
                    65_536,
                    2.0,
                    $cooperative,
                    $deadlineMonotonic,
                );
                if (($response['complete'] ?? false) === true
                    && (int)($response['status_code'] ?? 0) === 200
                    && \hash_equals('ok', \trim((string)($response['body'] ?? '')))
                ) {
                    $this->lastPublicProbeFailureKind = '';
                    return true;
                }
                $status = (int)($response['status_code'] ?? 0);
                $this->lastPublicProbeFailureKind = \in_array(
                    $status,
                    [502, 503, 504],
                    true,
                ) ? 'backend_transport' : 'backend_identity';
            } finally {
                @\fclose($socket);
            }
            if ($attempt < 3 && $cooperative) {
                $this->publicationProbePause();
            }
        }
        return false;
    }

    /**
     * @param array<string,mixed> $route
     */
    private function probePublicRoute(
        array $route,
        ?int $httpsPort = null,
        bool $cooperative = false,
        ?float $deadlineMonotonic = null,
        ?bool $isolation = null,
    ): bool
    {
        $this->lastPublicProbeFailureKind = 'data_plane';
        $deadlineMonotonic ??= $this->monotonicNow() + 5.0;
        $isolation ??= ($this->state['isolation_mode'] ?? false) === true
            || ($this->state['security_ledger_valid'] ?? true) !== true;
        $unavailable = $isolation || (string)($route['status'] ?? '') !== 'ACTIVE';
        $domain = (string)($route['domain'] ?? '');
        if (\str_starts_with($domain, '*.')) {
            $domain = 'wls-probe.' . \substr($domain, 2);
        }
        $certificate = (array)($route['certificate'] ?? []);
        $certificatePem = $this->tryReadStableRegularFile(
            (string)($certificate['cert_path'] ?? ''),
            2 * 1024 * 1024,
            'Published route certificate snapshot',
        );
        $expectedCertificate = $certificatePem !== null
            ? @\openssl_x509_read($certificatePem)
            : false;
        if ($domain === ''
            || $expectedCertificate === false
            || (string)($route['project_uuid'] ?? '') === ''
            || (!$unavailable && $this->routeBackendInstances($route) === [])
        ) {
            return false;
        }
        $context = \stream_context_create([
            'ssl' => [
                'peer_name' => $domain,
                'SNI_enabled' => true,
                'capture_peer_cert' => true,
                'verify_peer' => false,
                'verify_peer_name' => false,
                'allow_self_signed' => true,
                'disable_compression' => true,
                'crypto_method' => \STREAM_CRYPTO_METHOD_TLSv1_3_CLIENT,
            ],
        ]);
        $expectedFingerprint = (\is_resource($expectedCertificate)
            || $expectedCertificate instanceof \OpenSSLCertificate)
                ? (string)@\openssl_x509_fingerprint($expectedCertificate, 'sha256')
                : '';
        if ($expectedFingerprint === '') {
            return false;
        }

        for ($attempt = 1; $attempt <= 3; $attempt++) {
            $remaining = $deadlineMonotonic - $this->monotonicNow();
            if ($remaining <= 0.0) {
                return false;
            }
            if ($cooperative) {
                $this->serviceControlDuringPublicationProbe();
            }
            $socket = @\stream_socket_client(
                'tls://127.0.0.1:' . ($httpsPort ?? (int)$this->state['public_https']),
                $errno,
                $error,
                \min(1.0, $remaining),
                STREAM_CLIENT_CONNECT,
                $context,
            );
            if (!\is_resource($socket)) {
                if ($attempt < 3 && $cooperative) {
                    $this->publicationProbePause();
                    continue;
                }
                return false;
            }

            $retryable = false;
            try {
                if ($cooperative) {
                    $this->serviceControlDuringPublicationProbe();
                }
                $params = \stream_context_get_params($socket);
                $peerCertificate = $params['options']['ssl']['peer_certificate'] ?? null;
                $peerFingerprint = (\is_resource($peerCertificate)
                    || $peerCertificate instanceof \OpenSSLCertificate)
                        ? (string)@\openssl_x509_fingerprint($peerCertificate, 'sha256')
                        : '';
                if ($peerFingerprint === ''
                    || !\hash_equals(
                        \strtolower($expectedFingerprint),
                        \strtolower($peerFingerprint),
                    )
                ) {
                    return false;
                }

                $nonce = \bin2hex(\random_bytes(16));
                $request = "GET /__wls_gateway_sentinel?nonce={$nonce} HTTP/1.1\r\n"
                    . "Host: {$domain}\r\nConnection: close\r\nCache-Control: no-store\r\n\r\n";
                if (!$this->writeStreamAll($socket, $request)) {
                    $retryable = true;
                } else {
                    $response = $this->readProbeResponse(
                        $socket,
                        262144,
                        2.0,
                        $cooperative,
                        $deadlineMonotonic,
                    );
                    if (($response['complete'] ?? false) !== true) {
                        if ($unavailable) {
                            $this->lastPublicProbeFailureKind = 'data_plane';
                            return false;
                        }
                        if (($response['deadline_exhausted'] ?? false) === true
                            || ($response['eof'] ?? false) !== true
                            || ($response['timed_out'] ?? false) === true
                        ) {
                            $this->lastPublicProbeFailureKind = 'backend_transport';
                            $retryable = true;
                        } else {
                            $this->lastPublicProbeFailureKind = 'backend_identity';
                            return false;
                        }
                    } else {
                        $statusCode = (int)($response['status_code'] ?? 0);
                        $headers = (array)($response['headers'] ?? []);
                        $body = (string)($response['body'] ?? '');
                        if ($unavailable) {
                            $expectedMode = $isolation ? 'isolation' : 'unavailable';
                            $verifiedIsolation = $statusCode === 503
                                && \hash_equals(
                                    $expectedMode,
                                    (string)($headers['x-wls-gateway-mode'] ?? ''),
                                )
                                && \preg_match(
                                    '/\A[1-9][0-9]*\z/D',
                                    (string)(
                                        $headers['x-wls-gateway-generation'] ?? ''
                                    ),
                                ) === 1
                                && (int)$headers['x-wls-gateway-generation']
                                    === $this->expectedPublicProbeGeneration();
                            if (!$verifiedIsolation) {
                                $this->lastPublicProbeFailureKind = 'data_plane';
                            }
                            return $verifiedIsolation;
                        }
                        if (\in_array($statusCode, [502, 503, 504], true)) {
                            $this->lastPublicProbeFailureKind = 'backend_transport';
                            $retryable = true;
                        } elseif ($statusCode !== 200) {
                            $this->lastPublicProbeFailureKind = 'backend_identity';
                            return false;
                        } else {
                            $instanceId = (string)($headers['x-wls-instance-id'] ?? '');
                            $backendInstance = $this->routeBackendInstances(
                                $route,
                            )[$instanceId] ?? null;
                            $identity = \is_array($backendInstance)
                                ? (array)($backendInstance['backend_identity'] ?? [])
                                : [];
                            $sentinel = \json_decode($body, true);
                            $sentinelKeys = \is_array($sentinel)
                                ? \array_keys($sentinel)
                                : [];
                            \sort($sentinelKeys, SORT_STRING);
                            $verified = $identity !== []
                                && $sentinelKeys === [
                                    'instance',
                                    'launch_id',
                                    'master_epoch',
                                    'nonce',
                                    'status',
                                ]
                                && \hash_equals(
                                    'healthy',
                                    (string)($sentinel['status'] ?? ''),
                                )
                                && \hash_equals(
                                    $instanceId,
                                    (string)($sentinel['instance'] ?? ''),
                                )
                                && (int)($identity['master_epoch'] ?? 0)
                                    === (int)($sentinel['master_epoch'] ?? 0)
                                && \hash_equals(
                                    (string)($identity['launch_id'] ?? ''),
                                    (string)($sentinel['launch_id'] ?? ''),
                                )
                                && \hash_equals(
                                    $nonce,
                                    (string)($sentinel['nonce'] ?? ''),
                                )
                                && \hash_equals(
                                    (string)$route['project_uuid'],
                                    (string)($headers['x-wls-project-uuid'] ?? ''),
                                )
                                && \preg_match(
                                    '/\A[1-9][0-9]*\z/D',
                                    (string)(
                                        $headers['x-wls-backend-generation'] ?? ''
                                    ),
                                ) === 1
                                && (int)($identity['generation'] ?? 0)
                                    === (int)$headers['x-wls-backend-generation']
                                && \hash_equals(
                                    $nonce,
                                    (string)($headers['x-wls-probe-nonce'] ?? ''),
                                );
                            if (!$verified) {
                                $this->lastPublicProbeFailureKind = 'backend_identity';
                            }
                            return $verified;
                        }
                    }
                }
            } finally {
                @\fclose($socket);
            }
            if (!$retryable || $attempt >= 3) {
                return false;
            }
            if ($cooperative) {
                $this->publicationProbePause();
            }
        }

        return false;
    }

    /**
     * @param array<string,mixed> $route
     */
    private function recordPublicRouteProbeResult(
        array $route,
        bool $success,
        bool $isolation,
        string $failureKind,
    ): void {
        $routeId = (string)($route['route_id'] ?? '');
        if ($routeId === '') {
            return;
        }
        $this->publicRouteProbeResults[$routeId] = [
            'generation' => $this->expectedPublicProbeGeneration(),
            'route_digest' => $this->routeRoutingDigest($route),
            'isolation' => $isolation,
            'success' => $success,
            'available' => $success
                && !$isolation
                && (\hash_equals('ACTIVE', (string)($route['status'] ?? ''))
                    || (\hash_equals(
                        'PENDING_CERTIFICATE',
                        (string)($route['status'] ?? ''),
                    ) && \hash_equals(
                        'disabled',
                        $this->certificateLifecycleState(
                            (array)($route['certificate'] ?? []),
                        ),
                    ) && ($route['force_https'] ?? true) === false)),
            'failure_kind' => $success ? '' : $failureKind,
            'observed_monotonic' => $this->monotonicNow(),
            'boot_id' => $this->hostBootId,
        ];
    }

    /**
     * A bounded sweep may span maintenance cycles. The cache prevents a later
     * all-green suffix from erasing an earlier tenant failure, while concrete
     * failures advance the cursor so unrelated projects still receive fresh
     * route-local proofs.
     *
     * @param array<string,array<string,mixed>> $routes
     */
    private function publicRouteProbeSweepProofsHealthy(
        array $routes,
        bool $isolation,
    ): bool {
        $aggregateFailure = '';
        foreach ($routes as $route) {
            if (!\is_array($route) || !$this->routeAllowedBySecurity($route)) {
                continue;
            }
            $certificate = (array)($route['certificate'] ?? []);
            if (!$this->certificateSnapshotValidForDomain(
                $certificate,
                (string)($route['domain'] ?? ''),
            )) {
                if (\hash_equals('ACTIVE', (string)($route['status'] ?? ''))) {
                    $aggregateFailure = 'data_plane';
                }
                continue;
            }
            $routeId = (string)($route['route_id'] ?? '');
            $proof = $this->publicRouteProbeResults[$routeId] ?? null;
            $age = \is_array($proof)
                ? $this->monotonicNow()
                    - (float)($proof['observed_monotonic'] ?? 0.0)
                : PHP_FLOAT_MAX;
            $current = \is_array($proof)
                && !\hash_equals('', $routeId)
                && \hash_equals($this->hostBootId, (string)($proof['boot_id'] ?? ''))
                && (int)($proof['generation'] ?? 0)
                    === $this->expectedPublicProbeGeneration()
                && (bool)($proof['isolation'] ?? false) === $isolation
                && \hash_equals(
                    $this->routeRoutingDigest($route),
                    (string)($proof['route_digest'] ?? ''),
                )
                && $age >= 0.0
                && $age <= self::PUBLIC_ROUTE_PROBE_PROOF_TTL_SECONDS;
            if (!$current) {
                $aggregateFailure = $aggregateFailure === ''
                    ? 'deferred'
                    : $aggregateFailure;
                continue;
            }
            if (($proof['success'] ?? false) === true) {
                continue;
            }
            $failureKind = (string)($proof['failure_kind'] ?? 'data_plane');
            if ($failureKind === 'data_plane'
                || ($failureKind === 'backend_identity'
                    && $aggregateFailure !== 'data_plane')
                || ($failureKind === 'backend_transport'
                    && !\in_array(
                        $aggregateFailure,
                        ['data_plane', 'backend_identity'],
                        true,
                    ))
            ) {
                $aggregateFailure = $failureKind;
            }
        }
        if ($aggregateFailure === '') {
            return true;
        }
        $this->lastPublicProbeFailureKind = $aggregateFailure;
        return false;
    }

    /**
     * Read one close-delimited HTTP/1.x probe response. A body reaching its
     * declared Content-Length is not success until EOF proves that no delayed
     * tail, second response or smuggled bytes follow it.
     *
     * @param resource $socket
     * @return array{
     *     complete:bool,
     *     eof:bool,
     *     overflow:bool,
     *     deadline_exhausted:bool,
     *     timed_out:bool,
     *     status_code:int,
     *     headers:array<string,string>,
     *     body:string,
     *     error:string
     * }
     */
    private function readProbeResponse(
        $socket,
        int $maximumBytes,
        float $timeoutSeconds,
        bool $cooperative,
        ?float $deadlineMonotonic = null,
    ): array {
        $maximumBytes = \max(1, $maximumBytes);
        $readDeadline = $this->monotonicNow() + \max(0.1, $timeoutSeconds);
        $deadlineMonotonic = $deadlineMonotonic === null
            ? $readDeadline
            : \min($deadlineMonotonic, $readDeadline);
        $response = '';
        $readError = '';
        $overflow = false;
        $deadlineExhausted = false;
        @\stream_set_blocking($socket, false);
        while (true) {
            if (\strlen($response) > $maximumBytes) {
                $overflow = true;
                break;
            }
            if (\feof($socket)) {
                break;
            }
            if ($this->monotonicNow() >= $deadlineMonotonic) {
                $deadlineExhausted = true;
                break;
            }
            if ($cooperative) {
                $this->serviceControlDuringPublicationProbe();
            }
            $remaining = \max(0.0, $deadlineMonotonic - $this->monotonicNow());
            $waitMicros = (int)\min(100000, \ceil($remaining * 1_000_000));
            $read = [$socket];
            $write = [];
            $except = [];
            $selected = @\stream_select($read, $write, $except, 0, $waitMicros);
            if ($selected === false) {
                $readError = 'select_failed';
                break;
            }
            if ($selected === 0) {
                continue;
            }
            $chunk = @\fread(
                $socket,
                \min(8192, $maximumBytes + 1 - \strlen($response)),
            );
            if (!\is_string($chunk)) {
                $readError = 'read_failed';
                break;
            }
            if ($chunk === '') {
                if (\feof($socket)) {
                    break;
                }
                continue;
            }
            $response .= $chunk;
        }
        $metadata = \stream_get_meta_data($socket);
        $eof = \feof($socket);
        $timedOut = ($metadata['timed_out'] ?? false) === true;
        $result = [
            'complete' => false,
            'eof' => $eof,
            'overflow' => $overflow || \strlen($response) > $maximumBytes,
            'deadline_exhausted' => $deadlineExhausted,
            'timed_out' => $timedOut,
            'status_code' => 0,
            'headers' => [],
            'body' => '',
            'error' => $readError,
        ];
        if (!$eof
            || $result['overflow']
            || $deadlineExhausted
            || $timedOut
            || $readError !== ''
        ) {
            $result['error'] = $result['error'] !== ''
                ? $result['error']
                : (!$eof ? 'eof_required' : 'incomplete');
            return $result;
        }
        $headerBoundary = \strpos($response, "\r\n\r\n");
        if ($headerBoundary === false) {
            $result['error'] = 'header_terminator_missing';
            return $result;
        }
        $headerBlock = \substr($response, 0, $headerBoundary);
        $body = \substr($response, $headerBoundary + 4);
        $lines = \explode("\r\n", $headerBlock);
        $statusLine = (string)\array_shift($lines);
        if (\preg_match('/[\x00-\x1F\x7F]/D', $statusLine) === 1
            || \preg_match(
            '/\AHTTP\/1\.[01] ([0-9]{3}) [^\r\n]*\z/D',
            $statusLine,
            $status,
        ) !== 1) {
            $result['error'] = 'status_line_invalid';
            return $result;
        }
        $statusCode = (int)$status[1];
        if ($statusCode < 200 || $statusCode > 599) {
            $result['error'] = 'informational_or_invalid_status';
            return $result;
        }
        $headers = [];
        foreach ($lines as $line) {
            if ($line === ''
                || $line[0] === ' '
                || $line[0] === "\t"
                || !\str_contains($line, ':')
            ) {
                $result['error'] = 'header_line_invalid';
                return $result;
            }
            [$name, $value] = \explode(':', $line, 2);
            $name = \strtolower(\trim($name));
            if (\preg_match('/\A[a-z0-9!#$%&\'*+.^_`|~-]+\z/D', $name) !== 1
                || \array_key_exists($name, $headers)
                || \preg_match('/[\x00-\x1F\x7F]/D', $value) === 1
            ) {
                $result['error'] = 'duplicate_or_invalid_header';
                return $result;
            }
            $headers[$name] = \trim($value);
        }
        $contentLength = $headers['content-length'] ?? null;
        if ($contentLength === null
            || \array_key_exists('transfer-encoding', $headers)
            || \preg_match('/\A[0-9]{1,9}\z/D', $contentLength) !== 1
            || (int)$contentLength > $maximumBytes
            || \strlen($body) !== (int)$contentLength
        ) {
            $result['error'] = 'response_frame_invalid';
            return $result;
        }
        $result['complete'] = true;
        $result['status_code'] = $statusCode;
        $result['headers'] = $headers;
        $result['body'] = $body;
        $result['error'] = '';
        return $result;
    }

    /** @param array<string,mixed> $response */
    private function gatewayHealthResponseMatches(array $response, int $generation): bool
    {
        if (($response['complete'] ?? false) !== true
            || (int)($response['status_code'] ?? 0) !== 200
        ) {
            return false;
        }
        $headers = (array)($response['headers'] ?? []);
        $payload = \json_decode((string)($response['body'] ?? ''), true);
        $keys = \is_array($payload) ? \array_keys($payload) : [];
        \sort($keys, SORT_STRING);
        return \is_array($payload)
            && $keys === ['generation', 'protocol']
            && \hash_equals(self::PROTOCOL, (string)($payload['protocol'] ?? ''))
            && \is_int($payload['generation'] ?? null)
            && (int)$payload['generation'] === $generation
            && \preg_match(
                '/\A[1-9][0-9]*\z/D',
                (string)($headers['x-wls-gateway-generation'] ?? ''),
            ) === 1
            && (int)$headers['x-wls-gateway-generation'] === $generation;
    }

    private function probeUnknownDomain(
        ?int $httpsPort,
        bool $cooperative,
        float $deadlineMonotonic,
    ): bool {
        $domain = 'unknown-' . \substr(\hash('sha256', (string)$this->state['epoch']), 0, 16)
            . '.invalid';
        $remaining = $deadlineMonotonic - $this->monotonicNow();
        if ($remaining <= 0.0) {
            return false;
        }
        if ($cooperative) {
            $this->serviceControlDuringPublicationProbe();
        }
        $context = \stream_context_create(['ssl' => [
            'peer_name' => $domain,
            'SNI_enabled' => true,
            'verify_peer' => false,
            'verify_peer_name' => false,
            'allow_self_signed' => true,
            'crypto_method' => \STREAM_CRYPTO_METHOD_TLSv1_3_CLIENT,
        ]]);
        $socket = @\stream_socket_client(
            'tls://127.0.0.1:' . ($httpsPort ?? (int)$this->state['public_https']),
            $errno,
            $error,
            \min(1.0, $remaining),
            STREAM_CLIENT_CONNECT,
            $context,
        );
        if (!\is_resource($socket)) {
            return false;
        }
        try {
            if (!$this->writeStreamAll(
                $socket,
                "GET / HTTP/1.1\r\nHost: {$domain}\r\nConnection: close\r\n\r\n",
            )) {
                return false;
            }
            $response = $this->readProbeResponse(
                $socket,
                65_536,
                1.0,
                $cooperative,
                $deadlineMonotonic,
            );
            return ($response['complete'] ?? false) === true
                && (int)($response['status_code'] ?? 0) === 421;
        } finally {
            @\fclose($socket);
        }
    }

    private function adoptOrRecoverDataPlane(): void
    {
        if ($this->diskPressureMarkerActive()) {
            $status = $this->nginxStatus();
            $deadline = $this->monotonicNow()
                + self::PUBLIC_ROUTE_PROBE_BUDGET_SECONDS;
            $healthy = ($status['running'] ?? false) === true
                && $this->publicPortsReachable(null, false, $deadline)
                && $this->publicRoutesReachable(false, $deadline);
            $this->state['ready'] = $healthy && $this->journalTrusted;
            $this->state['health_state'] = 'DISK_PRESSURE';
            $this->state['recovery']['stage'] = $healthy
                ? 'DISK_PRESSURE_READ_ONLY_ADOPTED'
                : 'DISK_PRESSURE_DATA_PLANE_DOWN';
            return;
        }
        try {
            // A stopped data plane must never expose the previously rendered
            // ACTIVE config before persisted leases are reconciled. Otherwise
            // a controller restart after HEARTBEAT_TTL briefly serves stale
            // backends as 200, then flips to the required TLS/503 isolation.
            $this->expireLeases();
            if ($this->configDirty && !$this->publishIfDirty()) {
                throw new \RuntimeException(
                    'Gateway startup lease reconciliation could not publish its fail-closed config.'
                );
            }
        } catch (\Throwable $throwable) {
            $this->abortRoutingMutation(
                'Gateway startup lease reconciliation failed: ' . $throwable->getMessage(),
            );
            $this->stopDataPlane();
            $this->state['isolation_mode'] = true;
            $this->state['ready'] = false;
            $this->state['health_state'] = 'STARTUP_LEASE_RECONCILE_FAILED_CLOSED';
            $this->recordFailure($throwable->getMessage());
            $this->persistState();
            return;
        }
        if (($this->state['isolation_mode'] ?? false) === true
            || ($this->state['security_ledger_valid'] ?? true) !== true
        ) {
            $this->beginRoutingMutation('isolation-recovery');
            $this->configDirty = true;
            if (!$this->publishIfDirty()) {
                $this->stopDataPlane();
                $this->state['ready'] = false;
                $this->state['health_state'] = 'STATE_REBUILD_FAILED_CLOSED';
                $this->persistState();
            }
            return;
        }
        $status = $this->nginxStatus();
        if (($status['running'] ?? false) === true) {
            $deadline = $this->monotonicNow()
                + self::PUBLIC_ROUTE_PROBE_BUDGET_SECONDS;
            $this->state['health_state'] = 'CONTROL_DEGRADED';
            $this->state['ready'] = $this->publicPortsReachable(
                null,
                false,
                $deadline,
            ) && $this->publicRoutesReachable(false, $deadline);
            $this->state['recovery']['stage'] = 'ADOPTED';
            $this->persistState();
            return;
        }
        if (!\is_file($this->configFile())) {
            $this->configDirty = true;
            $this->publishIfDirty();
            return;
        }
        $this->startDataPlane();
    }

    /**
     * @param list<array{host:string,port:int,weight?:int}> $backends
     * @param array<string,mixed> $identity
     */
    private function backendProbeCacheKey(array $backends, array $identity): string
    {
        $endpoints = [];
        foreach ($backends as $backend) {
            if (!\is_array($backend)) {
                $endpoints[] = ['host' => '', 'port' => 0];
                continue;
            }
            $endpoints[] = [
                'host' => (string)($backend['host'] ?? ''),
                'port' => (int)($backend['port'] ?? 0),
            ];
        }
        \usort(
            $endpoints,
            static fn (array $left, array $right): int =>
                ((string)$left['host'] <=> (string)$right['host'])
                    ?: ((int)$left['port'] <=> (int)$right['port']),
        );
        return \hash('sha256', $this->canonicalJson([
            // Weight and presentation order affect Nginx balancing, not
            // listener identity. One exact tuple set is attested once per
            // probe wave even when many domain routes share it.
            'backends' => $endpoints,
            'identity' => $identity,
        ]));
    }

    /**
     * @param list<array{host:string,port:int,weight?:int}> $backends
     * @param array<string,mixed> $identity
     */
    private function probeBackends(
        array $backends,
        array $identity,
        bool $cooperative = false,
        ?string &$failureKind = null,
        ?float $deadlineMonotonic = null,
    ): string
    {
        $deadlineMonotonic ??= $this->monotonicNow()
            + (float)self::BACKEND_PROBE_READ_TIMEOUT;
        if ($backends === []) {
            $failureKind = 'identity';
            return 'FAILED';
        }

        $identityFailure = false;
        $transportFailure = false;
        $deferred = false;
        foreach ($backends as $backend) {
            if ($this->monotonicNow() >= $deadlineMonotonic) {
                $deferred = true;
                break;
            }
            if ($cooperative) {
                $this->serviceControlDuringPublicationProbe();
            }
            if (!\is_array($backend)) {
                $identityFailure = true;
                continue;
            }
            $backendFailureKind = null;
            if ($this->probeBackendHealth(
                $backend,
                $identity,
                $backendFailureKind,
                $deadlineMonotonic,
            ) !== null
            ) {
                continue;
            }
            if ($backendFailureKind === 'deferred') {
                $deferred = true;
            } elseif ($backendFailureKind === 'transport') {
                $transportFailure = true;
            } else {
                // Unknown probe failures belong to the identity/security class.
                // A new failure kind must be reviewed before it may become retryable.
                $identityFailure = true;
            }
        }
        // Every advertised tuple is written into the upstream configuration.
        // Therefore one valid tuple cannot attest the identity of its siblings.
        // Identity mismatches are terminal even when a later probe exhausts the
        // cooperative deadline; otherwise an attacker can hide an unbound tuple
        // behind a deliberately slow endpoint and have the whole list admitted.
        if ($identityFailure) {
            $failureKind = 'identity';
            return 'FAILED';
        }
        if ($deferred) {
            $failureKind = 'deferred';
            return 'DEFERRED';
        }
        if ($transportFailure) {
            $failureKind = 'transport';
            return 'FAILED';
        }
        $failureKind = null;
        return 'HEALTHY';
    }

    /**
     * @param array<string,mixed> $backend
     * @param array<string,mixed> $identity
     * @return array<string,mixed>|null
     */
    private function probeBackendHealth(
        array $backend,
        array $identity,
        ?string &$failureKind = null,
        ?float $deadlineMonotonic = null,
    ): ?array
    {
        $failureKind = 'identity';
        $secret = \strtolower(\trim((string)($identity['edge_capability_secret'] ?? '')));
        $expectedDigest = \strtolower(\trim((string)(
            $identity['edge_capability_digest'] ?? ''
        )));
        $expectedProject = \strtolower(\trim((string)(
            $identity['project_uuid'] ?? ''
        )));
        $expectedInstance = (string)($identity['instance_id'] ?? '');
        $expectedGeneration = (int)($identity['generation'] ?? 0);
        $expectedEpoch = (int)($identity['master_epoch'] ?? 0);
        $expectedLaunchId = \strtolower(\trim((string)($identity['launch_id'] ?? '')));
        $expectedListenerLeaseId = \strtolower(\trim((string)(
            $identity['listener_lease_id'] ?? ''
        )));
        $expectedSessionMode = \strtolower(\trim((string)(
            $identity['session_capability'] ?? 'isolated'
        )));
        $expectedEvidenceDigest = \strtolower(\trim((string)(
            $identity['session_capability_evidence_digest'] ?? ''
        )));
        if ($expectedEvidenceDigest === '' && $expectedSessionMode === 'isolated') {
            $expectedEvidenceDigest = \str_repeat('0', 64);
        }
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $secret) !== 1
            || !\hash_equals($expectedDigest, \hash('sha256', $secret))
            || \preg_match(
                '/\A[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\z/D',
                $expectedProject,
            ) !== 1
            || $expectedInstance === ''
            || $expectedGeneration < 1
            || $expectedEpoch < 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $expectedLaunchId) !== 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $expectedListenerLeaseId) !== 1
            || !\in_array(
                $expectedSessionMode,
                ['isolated', 'stateless', 'shared_session'],
                true,
            )
            || \preg_match('/\A[a-f0-9]{64}\z/D', $expectedEvidenceDigest) !== 1
        ) {
            return null;
        }
        $host = (string)($backend['host'] ?? '');
        $port = (int)($backend['port'] ?? 0);
        if (!\in_array($host, ['127.0.0.1', '::1'], true) || $port < 1 || $port > 65535) {
            return null;
        }
        $address = $host === '::1' ? 'tcp://[::1]:' . $port : 'tcp://' . $host . ':' . $port;
        $connectTimeout = 1.0;
        if ($deadlineMonotonic !== null) {
            $remaining = $deadlineMonotonic - $this->monotonicNow();
            if ($remaining <= 0.0) {
                $failureKind = 'deferred';
                return null;
            }
            $connectTimeout = \min($connectTimeout, $remaining);
        }
        $socket = @\stream_socket_client($address, $errno, $error, $connectTimeout);
        if (!\is_resource($socket)) {
            $failureKind = 'transport';
            return null;
        }
        $nonce = \bin2hex(\random_bytes(16));
        $readTimeout = (float)self::BACKEND_PROBE_READ_TIMEOUT;
        if ($deadlineMonotonic !== null) {
            $remaining = $deadlineMonotonic - $this->monotonicNow();
            if ($remaining <= 0.0) {
                @\fclose($socket);
                $failureKind = 'deferred';
                return null;
            }
            $readTimeout = \min($readTimeout, $remaining);
        }
        $this->configureClientReadTimeout($socket, $readTimeout);
        $request = "GET /_wls/health?detail=1&gateway=1&nonce={$nonce} HTTP/1.1\r\n"
            . "Host: localhost\r\n"
            // This is the private loopback attestation plane. Worker policy
            // intentionally requires the exact edge capability even for a
            // loopback peer; the public sentinel receives its token only from
            // Nginx and never exposes this secret in a response.
            . "X-WLS-Edge-Token: {$secret}\r\n"
            . "X-WLS-Client-Protocol: HTTP/1.1\r\n"
            . "Connection: close\r\n\r\n";
        if (!$this->writeStreamAll($socket, $request)) {
            @\fclose($socket);
            $failureKind = 'transport';
            return null;
        }
        $response = $this->readProbeResponse(
            $socket,
            131072,
            $readTimeout,
            false,
            $deadlineMonotonic,
        );
        @\fclose($socket);
        if (($response['complete'] ?? false) !== true) {
            $absoluteDeadlineExhausted = $deadlineMonotonic !== null
                && $this->monotonicNow() >= $deadlineMonotonic;
            $failureKind = ($response['deadline_exhausted'] ?? false) === true
                && $absoluteDeadlineExhausted
                ? 'deferred'
                : ((($response['eof'] ?? false) !== true
                    || ($response['timed_out'] ?? false) === true)
                    ? 'transport'
                    : 'identity');
            return null;
        }
        $statusCode = (int)($response['status_code'] ?? 0);
        if ($statusCode !== 200) {
            // A reachable listener that explicitly rejects the edge token or
            // health path is not an unavailable transport. Treat 4xx as an
            // identity failure so a forged tuple cannot be persisted merely
            // as pending; only a backend-side 5xx remains retryable transport.
            $failureKind = $statusCode >= 500 && $statusCode <= 599
                ? 'transport'
                : 'identity';
            return null;
        }
        $body = (string)($response['body'] ?? '');
        $health = $body !== '' ? \json_decode($body, true) : null;
        $attestation = \is_array($health)
            && \is_array($health['backend_attestation'] ?? null)
            ? $health['backend_attestation']
            : null;
        if (!\is_array($attestation)) {
            return null;
        }
        $attestationKeys = \array_keys($attestation);
        \sort($attestationKeys, SORT_STRING);
        if ($attestationKeys !== [
            'backend_host',
            'backend_port',
            'edge_capability_digest',
            'instance_generation',
            'instance_id',
            'issued_at',
            'launch_id',
            'listener_lease_id',
            'master_epoch',
            'nonce',
            'project_uuid',
            'schema',
            'session_capability',
            'session_capability_evidence_digest',
            'signature',
        ]) {
            return null;
        }
        $signature = \strtolower(\trim((string)($attestation['signature'] ?? '')));
        $unsigned = $attestation;
        unset($unsigned['signature']);
        $binaryKey = \hex2bin($secret);
        if (!\is_string($binaryKey) || \strlen($binaryKey) !== 32) {
            return null;
        }
        try {
            $expectedSignature = \hash_hmac(
                'sha256',
                $this->canonicalJson($unsigned),
                $binaryKey,
            );
        } finally {
            if (\function_exists('sodium_memzero')) {
                \sodium_memzero($binaryKey);
            }
        }
        $issuedAt = (int)($attestation['issued_at'] ?? 0);
        if (!\hash_equals(
                'wls-backend-attestation/1',
                (string)($attestation['schema'] ?? ''),
            )
            || \preg_match('/\A[a-f0-9]{64}\z/D', $signature) !== 1
            || !\hash_equals($expectedSignature, $signature)
            || !\hash_equals($nonce, (string)($attestation['nonce'] ?? ''))
            || !\hash_equals(
                $expectedProject,
                (string)($attestation['project_uuid'] ?? ''),
            )
            || !\hash_equals(
                $expectedInstance,
                (string)($attestation['instance_id'] ?? ''),
            )
            || $expectedGeneration !== (int)($attestation['instance_generation'] ?? 0)
            || $expectedEpoch !== (int)($attestation['master_epoch'] ?? 0)
            || !\hash_equals($expectedLaunchId, (string)($attestation['launch_id'] ?? ''))
            || !\hash_equals(
                $expectedListenerLeaseId,
                (string)($attestation['listener_lease_id'] ?? ''),
            )
            || !\hash_equals(
                $expectedDigest,
                (string)($attestation['edge_capability_digest'] ?? ''),
            )
            || !\hash_equals($host, (string)($attestation['backend_host'] ?? ''))
            || $port !== (int)($attestation['backend_port'] ?? 0)
            || !\hash_equals(
                $expectedSessionMode,
                (string)($attestation['session_capability'] ?? ''),
            )
            || !\hash_equals(
                $expectedEvidenceDigest,
                (string)($attestation['session_capability_evidence_digest'] ?? ''),
            )
            || $issuedAt <= 0
            || \abs(\time() - $issuedAt) > 10
        ) {
            return null;
        }
        $failureKind = null;
        return $health;
    }

    /**
     * @param list<array<string,mixed>> $candidateRoutes
     */
    private function assertNoDomainConflicts(string $projectUuid, array $candidateRoutes): void
    {
        foreach ($candidateRoutes as $candidate) {
            $domain = (string)$candidate['domain'];
            foreach ($this->domainOwnershipRecords($domain, $this->state) as $ownership) {
                if (!\hash_equals(
                    $projectUuid,
                    (string)($ownership['project_uuid'] ?? ''),
                )) {
                    throw new \DomainException(
                        'Domain ownership is retained by project '
                            . (string)($ownership['project_uuid'] ?? '') . ': ' . $domain
                    );
                }
            }
            foreach ($this->domainOwnershipTombstones($domain, $this->state) as $ownership) {
                if (!\hash_equals(
                    $projectUuid,
                    (string)($ownership['to_project_uuid'] ?? ''),
                )) {
                    throw new \DomainException(
                        'Domain ownership is fenced to project '
                            . (string)($ownership['to_project_uuid'] ?? '') . ': ' . $domain
                    );
                }
            }
            foreach ((array)$this->state['routes'] as $existing) {
                if (!\is_array($existing)
                    || (string)($existing['status'] ?? '') === 'REMOVED'
                    || (string)$existing['project_uuid'] === $projectUuid
                ) {
                    continue;
                }
                if ($this->domainsOverlap((string)$candidate['domain'], (string)$existing['domain'])) {
                    throw new \DomainException(
                        'Domain conflict with project ' . (string)$existing['project_uuid']
                        . ': ' . (string)$candidate['domain']
                    );
                }
            }
        }
    }

    private function domainsOverlap(string $left, string $right): bool
    {
        if ($left === $right) {
            return true;
        }
        foreach ([[$left, $right], [$right, $left]] as [$wildcard, $exact]) {
            if (\str_starts_with($wildcard, '*.')
                && \substr_count($wildcard, '.') === \substr_count($exact, '.')
                && \str_ends_with($exact, \substr($wildcard, 1))
            ) {
                return true;
            }
        }
        return false;
    }

    /**
     * Exact and wildcard ownership tombstones share one overlap namespace.
     * A child exact route cannot bypass a wildcard transfer, and a wildcard
     * route cannot reclaim an exact child without an explicit transfer.
     *
     * @param array<string,mixed> $state
     * @return list<array<string,mixed>>
     */
    private function domainOwnershipTombstones(string $domain, array $state): array
    {
        $matches = [];
        foreach ((array)($state['security']['tombstones'] ?? []) as $key => $tombstone) {
            if (!\is_array($tombstone)
                || !\str_starts_with((string)$key, 'domain:')
            ) {
                continue;
            }
            $ownedDomain = (string)($tombstone['domain'] ?? \substr((string)$key, 7));
            if ($ownedDomain !== '' && $this->domainsOverlap($domain, $ownedDomain)) {
                $matches[] = $tombstone;
            }
        }
        \usort(
            $matches,
            static fn (array $left, array $right): int =>
                (int)($right['generation'] ?? 0) <=> (int)($left['generation'] ?? 0),
        );
        return $matches;
    }

    /**
     * @param array<string,mixed> $state
     * @return list<array<string,mixed>>
     */
    private function domainOwnershipRecords(string $domain, array $state): array
    {
        $matches = [];
        foreach ((array)($state['domain_ownership'] ?? []) as $ownedDomain => $ownership) {
            if (!\is_array($ownership)) {
                continue;
            }
            $recordDomain = (string)($ownership['domain'] ?? $ownedDomain);
            if ($recordDomain !== '' && $this->domainsOverlap($domain, $recordDomain)) {
                $matches[] = $ownership;
            }
        }
        \usort(
            $matches,
            static fn (array $left, array $right): int =>
                (int)($right['ownership_generation'] ?? 0)
                    <=> (int)($left['ownership_generation'] ?? 0),
        );
        return $matches;
    }

    private function normalizeDomain(string $domain): string
    {
        $domain = \strtolower(\rtrim(\trim($domain), '.'));
        $wildcard = \str_starts_with($domain, '*.');
        $body = $wildcard ? \substr($domain, 2) : $domain;
        if (\function_exists('idn_to_ascii')) {
            $ascii = @\idn_to_ascii($body, IDNA_DEFAULT, INTL_IDNA_VARIANT_UTS46);
            if (\is_string($ascii) && $ascii !== '') {
                $body = \strtolower($ascii);
            }
        }
        if (\strlen($body) > 253
            || \preg_match('/^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?)(?:\.(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?))+$/D', $body) !== 1
        ) {
            throw new \DomainException('Route domain is not a valid IDNA ASCII hostname.');
        }
        return $wildcard ? '*.' . $body : $body;
    }

    private function canonicalRouteId(string $projectUuid, string $domain): string
    {
        return \substr(\hash('sha256', $projectUuid . "\0" . $domain), 0, 32);
    }

    /** @param array<string,mixed> $payload */
    private function assertPayloadBudget(array $payload, int $maximumBytes, string $label): void
    {
        $encoded = \json_encode(
            $payload,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION,
        );
        if (!\is_string($encoded) || \strlen($encoded) > $maximumBytes) {
            throw new \DomainException($label . ' payload exceeds its byte quota.');
        }
    }

    private function assertWriterSize(string $contents, int $maximumBytes, string $label): void
    {
        if (\strlen($contents) > $maximumBytes) {
            throw new \RuntimeException($label . ' exceeds its reader/writer size contract.');
        }
    }

    private function assertDeadlineAvailable(float $deadlineMonotonic, string $operation): void
    {
        if ($deadlineMonotonic <= $this->monotonicNow()) {
            throw new \DomainException($operation . ' exceeded its absolute deadline.');
        }
    }

    /** @param array<string,mixed> $certificate */
    private function assertCertificateProgression(
        string $projectUuid,
        string $domain,
        array $certificate,
    ): void {
        $incomingGeneration = (int)($certificate['generation'] ?? -1);
        $incomingDigest = \strtolower(\trim((string)(
            $certificate['source_digest'] ?? ''
        )));
        $incomingState = \strtolower(\trim((string)(
            $certificate['state']
                ?? (($incomingGeneration > 0
                    && ($certificate['pending'] ?? true) === false)
                    ? 'active'
                    : 'pending')
        )));
        if ($incomingGeneration < 0
            || \preg_match('/\A[a-f0-9]{64}\z/D', $incomingDigest) !== 1
            || !\in_array($incomingState, ['active', 'pending', 'disabled'], true)
        ) {
            throw new \DomainException('Certificate generation fence is invalid.');
        }
        $floor = $this->state['certificate_floors'][
            $this->certificateFloorKey($projectUuid, $domain)
        ] ?? null;
        $existing = $this->routeForProjectDomain($projectUuid, $domain);
        $current = \is_array($floor)
            ? $floor
            : (\is_array($existing) ? (array)($existing['certificate'] ?? []) : []);
        $currentGeneration = (int)($current['generation'] ?? 0);
        $currentDigest = (string)($current['source_digest'] ?? '');
        $revocationGeneration = \is_array($floor)
            ? (int)($floor['revocation_generation'] ?? 0)
            : 0;
        $revocationDigest = \is_array($floor)
            ? (string)($floor['revocation_source_digest'] ?? '')
            : '';
        if ($incomingGeneration < $currentGeneration
            || ($incomingGeneration === $currentGeneration
                && $currentDigest !== ''
                && !\hash_equals($currentDigest, $incomingDigest))
            || $incomingGeneration < $revocationGeneration
            || ($incomingGeneration === $revocationGeneration
                && $revocationGeneration > 0
                && ($incomingState !== 'disabled'
                    || !\hash_equals($revocationDigest, $incomingDigest)))
        ) {
            throw new \DomainException(
                'Certificate generation is stale or ambiguous for project/domain.'
            );
        }
    }

    private function certificateFloorKey(string $projectUuid, string $domain): string
    {
        return $projectUuid . '|' . $domain;
    }

    /**
     * Retain the authoritative owner and certificate monotonic floor outside
     * the disposable route body. REMOVED route compaction can then reclaim
     * backend/certificate references without reopening domain ownership or
     * accepting an older project-managed certificate generation.
     *
     * @param array<string,mixed> $route
     */
    private function retainRouteSecurityClosure(
        array $route,
        bool $allowOwnerChange = false,
        string $ownershipStatus = '',
    ): void {
        $projectUuid = \strtolower(\trim((string)($route['project_uuid'] ?? '')));
        $domain = (string)($route['domain'] ?? '');
        $routeId = (string)($route['route_id'] ?? '');
        $routeGeneration = (int)($route['route_generation'] ?? 0);
        $enrollmentGeneration = (int)(
            $route['enrollment_security_generation'] ?? 0
        );
        $domainSecurityGeneration = (int)(
            $route['domain_security_generation'] ?? 0
        );
        try {
            $normalizedDomain = $this->normalizeDomain($domain);
        } catch (\Throwable) {
            $normalizedDomain = '';
        }
        if (!$this->validProjectUuid($projectUuid)
            || $normalizedDomain === ''
            || !\hash_equals($normalizedDomain, $domain)
            || !\hash_equals($this->canonicalRouteId($projectUuid, $domain), $routeId)
            || $routeGeneration < 1
            || $enrollmentGeneration < 1
            || $domainSecurityGeneration < 0
        ) {
            throw new \RuntimeException(
                'Route security closure cannot retain a malformed owner fence.'
            );
        }
        $existingOwnership = $this->state['domain_ownership'][$domain] ?? null;
        if (\is_array($existingOwnership)
            && !\hash_equals(
                $projectUuid,
                (string)($existingOwnership['project_uuid'] ?? ''),
            )
            && !$allowOwnerChange
        ) {
            throw new \RuntimeException(
                'Route security closure refused an implicit domain owner change.'
            );
        }
        $ownershipGeneration = \max(
            $enrollmentGeneration,
            $domainSecurityGeneration,
            (int)(\is_array($existingOwnership)
                ? ($existingOwnership['ownership_generation'] ?? 0)
                : 0),
        );
        $this->state['domain_ownership'][$domain] = [
            'schema_version' => 1,
            'domain' => $domain,
            'project_uuid' => $projectUuid,
            'route_id' => $routeId,
            'route_generation' => \max(
                $routeGeneration,
                (int)(\is_array($existingOwnership)
                    && \hash_equals(
                        $projectUuid,
                        (string)($existingOwnership['project_uuid'] ?? ''),
                    )
                    ? ($existingOwnership['route_generation'] ?? 0)
                    : 0),
            ),
            'enrollment_security_generation' => $enrollmentGeneration,
            'domain_security_generation' => $domainSecurityGeneration,
            'ownership_generation' => $ownershipGeneration,
            'status' => $ownershipStatus !== ''
                ? $ownershipStatus
                : (string)($route['status'] ?? 'ACTIVE'),
            'updated_at' => \gmdate(DATE_ATOM),
        ];

        $certificate = \is_array($route['certificate'] ?? null)
            ? $route['certificate']
            : [];
        $certificateGeneration = (int)($certificate['generation'] ?? 0);
        $sourceDigest = \strtolower(\trim((string)(
            $certificate['source_digest'] ?? ''
        )));
        if ($certificateGeneration < 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $sourceDigest) !== 1
        ) {
            return;
        }
        $floorKey = $this->certificateFloorKey($projectUuid, $domain);
        $floor = $this->state['certificate_floors'][$floorKey] ?? null;
        $floorGeneration = \is_array($floor) ? (int)($floor['generation'] ?? 0) : 0;
        $floorDigest = \is_array($floor) ? (string)($floor['source_digest'] ?? '') : '';
        $certificateState = \strtolower(\trim((string)(
            $certificate['state']
                ?? (($certificateGeneration > 0
                    && ($certificate['pending'] ?? true) === false)
                    ? 'active'
                    : 'pending')
        )));
        $revocationGeneration = \is_array($floor)
            ? (int)($floor['revocation_generation'] ?? 0)
            : 0;
        $revocationDigest = \is_array($floor)
            ? (string)($floor['revocation_source_digest'] ?? '')
            : '';
        if ($certificateGeneration < $floorGeneration
            || ($certificateGeneration === $floorGeneration
                && $floorDigest !== ''
                && !\hash_equals($floorDigest, $sourceDigest))
            || $certificateGeneration < $revocationGeneration
            || ($certificateGeneration === $revocationGeneration
                && $revocationGeneration > 0
                && ($certificateState !== 'disabled'
                    || !\hash_equals($revocationDigest, $sourceDigest)))
        ) {
            throw new \RuntimeException(
                'Route security closure detected a certificate generation rollback.'
            );
        }
        if ($certificateState === 'disabled') {
            if (!\hash_equals(
                \hash(
                    'sha256',
                    "wls-disabled-certificate\0" . $domain . "\0"
                        . $certificateGeneration,
                ),
                $sourceDigest,
            )) {
                throw new \RuntimeException(
                    'Route security closure rejected an invalid certificate revocation fact.'
                );
            }
            $revocationGeneration = $certificateGeneration;
            $revocationDigest = $sourceDigest;
            if ($this->publication !== null
                && ($this->publication['irrevocable_security'] ?? false) !== true
            ) {
                $this->markPublicationIrrevocableSecurity();
            }
        }
        $this->state['certificate_floors'][$floorKey] = [
            'schema_version' => 1,
            'project_uuid' => $projectUuid,
            'domain' => $domain,
            'generation' => $certificateGeneration,
            'source_digest' => $sourceDigest,
            'revocation_generation' => $revocationGeneration,
            'revocation_source_digest' => $revocationDigest,
            'route_generation' => $routeGeneration,
            'updated_at' => \gmdate(DATE_ATOM),
        ];
    }

    private function retainSecurityClosureAcrossRoutingRollback(): void
    {
        if (!\is_array($this->requestStateBeforeMutation)) {
            return;
        }
        $this->requestStateBeforeMutation['domain_ownership'] =
            (array)($this->state['domain_ownership'] ?? []);
        $this->requestStateBeforeMutation['certificate_floors'] =
            (array)($this->state['certificate_floors'] ?? []);
        $this->requestStateBeforeMutation['instance_retirements'] =
            (array)($this->state['instance_retirements'] ?? []);
        $this->requestStateBeforeMutation['security_generation_high_water'] =
            (int)($this->state['security_generation_high_water'] ?? 0);
        $this->requestStateBeforeMutation['security_committed_high_water'] =
            (int)($this->state['security_committed_high_water'] ?? 0);
    }

    /** @return array<string,mixed>|null */
    private function routeForProjectDomain(string $projectUuid, string $domain): ?array
    {
        foreach ((array)($this->state['routes'] ?? []) as $route) {
            if (\is_array($route)
                && (string)($route['status'] ?? '') !== 'REMOVED'
                && \hash_equals($projectUuid, (string)($route['project_uuid'] ?? ''))
                && \hash_equals($domain, (string)($route['domain'] ?? ''))
            ) {
                return $route;
            }
        }
        return null;
    }

    /**
     * Return the fixed redirect target for an apex route. The target must be
     * another registered, security-authorized route of the same project;
     * redirecting to a request-derived Host would create an open redirect.
     *
     * @param array<string,mixed> $route
     */
    private function registeredWwwRedirectTarget(array $route): ?string
    {
        if (($route['force_root_to_www'] ?? false) !== true) {
            return '';
        }
        $projectUuid = (string)($route['project_uuid'] ?? '');
        $domain = $this->normalizeDomain((string)($route['domain'] ?? ''));
        if (!$this->validProjectUuid($projectUuid)
            || \str_starts_with($domain, '*.')
            || \str_starts_with($domain, 'www.')
        ) {
            throw new \DomainException(
                'force_root_to_www source route is not an exact apex identity.'
            );
        }
        $targetDomain = $this->normalizeDomain('www.' . $domain);
        $target = $this->routeForProjectDomain($projectUuid, $targetDomain);
        if (!\is_array($target)
            || !$this->routeAllowedBySecurity($target)
            || (string)($target['status'] ?? '') === 'REMOVED'
        ) {
            throw new \DomainException(
                'force_root_to_www target is not registered by the same project.'
            );
        }
        if ((string)($target['status'] ?? '') !== 'ACTIVE'
            || !$this->certificateSnapshotValidForDomain(
                (array)($target['certificate'] ?? []),
                $targetDomain,
            )
            || $this->routeBackendInstances($target) === []
        ) {
            // The desired redirect remains configured, but publishing a
            // Location to an HTTPS route that cannot currently terminate TLS
            // and reach a live backend creates an availability black hole.
            // Render the source route as explicit 503 until the same
            // publication view can serve the fixed target.
            return null;
        }
        return $targetDomain;
    }

    private function maybeLeaveIsolationMode(): void
    {
        if (($this->state['isolation_mode'] ?? false) !== true
            || ($this->state['security_ledger_valid'] ?? false) !== true
        ) {
            return;
        }
        // Global isolation protects an untrusted ledger and the initial LKG
        // rebuild surface. Once one route has completed a full registration
        // in the new epoch, recovery becomes route-scoped: that ACTIVE route
        // may serve while absent tenants remain STALE/PENDING and therefore
        // keep their certificate-bound TLS/503 surfaces. Requiring every LKG
        // tenant here lets one permanently absent project deadlock all others.
        foreach ((array)($this->state['routes'] ?? []) as $route) {
            if (!\is_array($route)
                || (string)($route['status'] ?? '') === 'REMOVED'
                || !$this->routeAllowedBySecurity($route)
            ) {
                continue;
            }
            if ((string)($route['status'] ?? '') !== 'ACTIVE'
                || !$this->certificateSnapshotValidForDomain(
                    (array)($route['certificate'] ?? []),
                    (string)($route['domain'] ?? ''),
                )
                || $this->routeBackendInstances($route) === []
            ) {
                continue;
            }
            foreach ((array)($route['instances'] ?? []) as $instance) {
                if (\is_array($instance)
                    && (string)($instance['status'] ?? '') === 'ACTIVE'
                    && ($instance['backend_healthy'] ?? false) === true
                    && $this->sameLeaseBoot($instance)
                ) {
                    $this->state['isolation_mode'] = false;
                    $this->state['health_state'] = 'RECOVERY_REPUBLISH_REQUIRED';
                    return;
                }
            }
        }
    }

    /** @return array<string,array<string,mixed>> */
    private function routesForActiveProbe(): array
    {
        if (\in_array(
            (string)($this->publication['phase'] ?? ''),
            ['PREPARED', 'SHADOW_VERIFIED', 'ACTIVATING'],
            true,
        )) {
            return (array)($this->state['routes'] ?? []);
        }
        $active = (array)($this->state['active_routes'] ?? []);
        return (int)($this->state['active_config_generation'] ?? 0) > 0
            ? $active
            : (array)($this->state['routes'] ?? []);
    }

    /** @return array<string,array<string,mixed>> */
    private function publishableActiveRouteSnapshot(): array
    {
        $routes = [];
        foreach ((array)($this->state['routes'] ?? []) as $routeId => $route) {
            if (!\is_array($route)
                || (string)($route['status'] ?? '') === 'REMOVED'
                || !$this->routeAllowedBySecurity($route)
            ) {
                continue;
            }
            $routes[(string)$routeId] = $route;
        }
        \ksort($routes, SORT_STRING);
        return $routes;
    }

    private function expectedPublicProbeGeneration(): int
    {
        $phase = (string)($this->publication['phase'] ?? '');
        if (\in_array($phase, ['PREPARED', 'SHADOW_VERIFIED', 'ACTIVATING'], true)) {
            return (int)($this->publication['candidate_generation']
                ?? $this->state['generation']
                ?? 0);
        }
        if ($phase === 'ROLLING_BACK') {
            return (int)($this->publication['previous']['active_config_generation'] ?? 0);
        }
        $active = (int)($this->state['active_config_generation'] ?? 0);
        return $active > 0 ? $active : (int)($this->state['generation'] ?? 0);
    }

    /**
     * @param array<string,mixed> $peer
     */
    private function assertEnrollment(string $projectUuid, string $projectRoot, array $peer): void
    {
        $existing = $this->state['enrollments'][$projectUuid] ?? null;
        if (!\is_array($existing)) {
            throw new \DomainException(
                'Project registration requires an explicit administrator enrollment.'
            );
        }
        if (!\hash_equals((string)$existing['project_root'], $projectRoot)) {
            throw new \DomainException('Enrolled project UUID belongs to another project root.');
        }
        $tombstone = $this->state['security']['tombstones']['project:' . $projectUuid] ?? null;
        if (\is_array($tombstone)
            && (int)($tombstone['generation'] ?? 0)
                >= (int)($existing['security_generation'] ?? 0)
        ) {
            throw new \DomainException('Project enrollment is superseded by a security tombstone.');
        }
        $owner = \is_array($existing['owner'] ?? null) ? $existing['owner'] : [];
        if ((string)($owner['kind'] ?? '') === 'posix'
            && (int)($owner['uid'] ?? -1) !== (int)($peer['uid'] ?? -2)
        ) {
            throw new \DomainException('Project registration OS owner does not match enrollment.');
        }
        if ((string)($owner['kind'] ?? '') === 'windows'
            && !\hash_equals(
                \strtoupper((string)($owner['sid'] ?? '')),
                \strtoupper((string)($peer['sid'] ?? '')),
            )
        ) {
            throw new \DomainException('Project registration SID does not match enrollment.');
        }
    }

    /**
     * Security state is an overlay on every desired/LKG route. A route is
     * publishable only while its enrollment exists and no equal-or-newer
     * tombstone supersedes the enrollment captured at registration.
     *
     * @param array<string,mixed> $route
     */
    private function routeAllowedBySecurity(array $route): bool
    {
        return $this->routeAllowedBySecurityState($route, $this->state);
    }

    /**
     * @param array<string,mixed> $route
     * @param array<string,mixed> $state
     */
    private function routeAllowedBySecurityState(array $route, array $state): bool
    {
        if (($state['security_ledger_valid'] ?? true) !== true) {
            return false;
        }
        $projectUuid = \strtolower(\trim((string)($route['project_uuid'] ?? '')));
        $enrollment = $state['enrollments'][$projectUuid] ?? null;
        if ($projectUuid === '' || !\is_array($enrollment)) {
            return false;
        }
        $routeGeneration = (int)($route['enrollment_security_generation'] ?? 0);
        $enrollmentGeneration = (int)($enrollment['security_generation'] ?? 0);
        if ($routeGeneration < 1
            || $enrollmentGeneration < 1
            || $routeGeneration !== $enrollmentGeneration
        ) {
            return false;
        }
        $tombstone = $state['security']['tombstones']['project:' . $projectUuid] ?? null;
        if (\is_array($tombstone)) {
            // Legacy/LKG routes without an enrollment generation cannot prove
            // they were created after a revocation and therefore fail closed.
            if ($routeGeneration < 1
                || (int)($tombstone['generation'] ?? 0) >= $routeGeneration
            ) {
                return false;
            }
        }
        $domain = (string)($route['domain'] ?? '');
        $requiredOwnershipGeneration = 0;
        foreach ($this->domainOwnershipRecords($domain, $state) as $ownership) {
            if (!\hash_equals(
                $projectUuid,
                (string)($ownership['project_uuid'] ?? ''),
            )) {
                return false;
            }
            $requiredOwnershipGeneration = \max(
                $requiredOwnershipGeneration,
                (int)($ownership['domain_security_generation'] ?? 0),
            );
        }
        $certificateFloor = $state['certificate_floors'][
            $this->certificateFloorKey($projectUuid, $domain)
        ] ?? null;
        if (\is_array($certificateFloor)) {
            $revocationGeneration = (int)(
                $certificateFloor['revocation_generation'] ?? 0
            );
            if ($revocationGeneration > 0) {
                $certificate = \is_array($route['certificate'] ?? null)
                    ? $route['certificate']
                    : [];
                $certificateGeneration = (int)($certificate['generation'] ?? -1);
                $certificateState = (string)($certificate['state'] ?? '');
                $sourceDigest = (string)($certificate['source_digest'] ?? '');
                $revocationDigest = (string)(
                    $certificateFloor['revocation_source_digest'] ?? ''
                );
                if ($certificateGeneration < $revocationGeneration
                    || ($certificateGeneration === $revocationGeneration
                        && ($certificateState !== 'disabled'
                            || !\hash_equals($revocationDigest, $sourceDigest)))
                ) {
                    return false;
                }
            }
        }
        $domainOwnerships = $this->domainOwnershipTombstones($domain, $state);
        if ($domainOwnerships === []) {
            return (int)($route['domain_security_generation'] ?? 0)
                >= $requiredOwnershipGeneration;
        }
        $requiredGeneration = $requiredOwnershipGeneration;
        foreach ($domainOwnerships as $domainOwnership) {
            if (!\hash_equals(
                $projectUuid,
                (string)($domainOwnership['to_project_uuid'] ?? ''),
            )) {
                return false;
            }
            $requiredGeneration = \max(
                $requiredGeneration,
                (int)($domainOwnership['generation'] ?? PHP_INT_MAX),
            );
        }
        return (int)($route['domain_security_generation'] ?? 0) >= $requiredGeneration;
    }

    private function touchInstanceLease(
        string $projectUuid,
        string $instanceId,
        int $masterEpoch,
        string $launchId,
        int $instanceGeneration,
        ?array $drainCounters = null,
    ): void
    {
        $instance = $this->state['instances'][$projectUuid][$instanceId] ?? null;
        if (!\is_array($instance)
            || (int)($instance['generation'] ?? 0) !== $instanceGeneration
            || (int)($instance['master_epoch'] ?? 0) !== $masterEpoch
            || !\hash_equals((string)($instance['launch_id'] ?? ''), $launchId)
        ) {
            throw new \DomainException('Instance lease fencing identity is stale or unknown.');
        }
        $now = \time();
        $monotonicNow = $this->monotonicNow();
        $this->state['instances'][$projectUuid][$instanceId]['last_heartbeat'] = $now;
        $this->state['instances'][$projectUuid][$instanceId]['last_heartbeat_monotonic']
            = $monotonicNow;
        $this->state['instances'][$projectUuid][$instanceId]['lease_boot_id'] = $this->hostBootId;
        if ($drainCounters !== null) {
            $drainCounters['reported_at'] = $now;
            $drainCounters['reported_monotonic'] = $monotonicNow;
            $drainCounters['lease_boot_id'] = $this->hostBootId;
            $this->state['instances'][$projectUuid][$instanceId]['drain_counters']
                = $drainCounters;
        }
        foreach ((array)$this->state['routes'] as $routeId => $route) {
            if (!\is_array($route)
                || (string)$route['project_uuid'] !== $projectUuid
                || !\is_array($route['instances'][$instanceId] ?? null)
            ) {
                continue;
            }
            $this->state['routes'][$routeId]['instances'][$instanceId]['last_heartbeat'] = $now;
            $this->state['routes'][$routeId]['instances'][$instanceId]['last_heartbeat_monotonic']
                = $monotonicNow;
            $this->state['routes'][$routeId]['instances'][$instanceId]['lease_boot_id']
                = $this->hostBootId;
        }
        // Heartbeat is deliberately state-only. It cannot reactivate STALE or
        // DRAINING routing, clear a drain fence, or trigger Nginx publication.
        // A fenced register/renew request is required for every route change.
        $this->leaseCheckpointDirty = true;
    }

    /**
     * @return array<string,int|bool>|null
     */
    private function normalizeDrainCounters(mixed $counters): ?array
    {
        if ($counters === null) {
            return null;
        }
        if (!\is_array($counters)
            || (int)($counters['version'] ?? 0) !== 1
            || !\is_bool($counters['counters_known'] ?? null)
        ) {
            throw new \DomainException('Heartbeat drain counters are invalid.');
        }
        $normalized = [
            'version' => 1,
            'counters_known' => (bool)$counters['counters_known'],
        ];
        foreach ([
            'worker_count',
            'reported_worker_count',
            'active_requests',
            'long_lived_connections',
            'sse_connections',
            'websocket_connections',
        ] as $field) {
            $value = $counters[$field] ?? null;
            if (!\is_int($value) || $value < 0 || $value > 1_000_000) {
                throw new \DomainException('Heartbeat drain counters are invalid.');
            }
            $normalized[$field] = $value;
        }
        if ($normalized['counters_known']) {
            if ($normalized['worker_count'] < 1
                || $normalized['reported_worker_count'] !== $normalized['worker_count']
                || $normalized['sse_connections'] > $normalized['long_lived_connections']
                || $normalized['websocket_connections'] > $normalized['long_lived_connections']
            ) {
                throw new \DomainException('Heartbeat drain counter topology is inconsistent.');
            }
        } elseif ($normalized['active_requests'] !== 0
            || $normalized['long_lived_connections'] !== 0
            || $normalized['sse_connections'] !== 0
            || $normalized['websocket_connections'] !== 0
        ) {
            throw new \DomainException('Unknown heartbeat drain counters must be zero.');
        }
        return $normalized;
    }

    /**
     * An unchanged project generation may update only the capability evidence
     * of the same live endpoint. Domain, certificate, backend, route set and
     * every other identity field remain fenced.
     *
     * @param array<string,mixed> $existingInstance
     * @param list<array<string,mixed>> $candidateRoutes
     */
    private function assertCapabilityOnlyInstanceRefresh(
        string $projectUuid,
        string $instanceId,
        array $existingInstance,
        array $candidateRoutes,
    ): void {
        $reject = static function (): never {
            throw new \DomainException(
                'Same instance generation may refresh capability evidence only.'
            );
        };
        $existingProject = \is_array($this->state['projects'][$projectUuid] ?? null)
            ? $this->state['projects'][$projectUuid]
            : [];
        $expectedRouteIds = \array_values(\array_map(
            'strval',
            (array)($existingProject['route_ids'] ?? []),
        ));
        $incomingRouteIds = \array_values(\array_map(
            static fn (array $route): string => (string)($route['route_id'] ?? ''),
            $candidateRoutes,
        ));
        \sort($expectedRouteIds, SORT_STRING);
        \sort($incomingRouteIds, SORT_STRING);
        if ($expectedRouteIds === [] || $expectedRouteIds !== $incomingRouteIds) {
            $reject();
        }

        $incomingIdentity = [];
        $incomingBackends = [];
        foreach ($candidateRoutes as $candidate) {
            $routeId = (string)($candidate['route_id'] ?? '');
            $existingRoute = \is_array($this->state['routes'][$routeId] ?? null)
                ? $this->state['routes'][$routeId]
                : [];
            $existingDesired = [
                'route_id' => $routeId,
                'domain' => (string)($existingRoute['domain'] ?? ''),
                'force_https' => (bool)($existingRoute['force_https'] ?? false),
                'force_root_to_www' => (bool)(
                    $existingRoute['force_root_to_www'] ?? false
                ),
                'certificate_source_digest' => (string)(
                    $existingRoute['certificate']['source_digest'] ?? ''
                ),
                'certificate_generation' => (int)(
                    $existingRoute['certificate']['generation'] ?? 0
                ),
            ];
            $incomingDesired = [
                'route_id' => $routeId,
                'domain' => (string)($candidate['domain'] ?? ''),
                'force_https' => (bool)($candidate['force_https'] ?? false),
                'force_root_to_www' => (bool)(
                    $candidate['force_root_to_www'] ?? false
                ),
                'certificate_source_digest' => (string)(
                    $candidate['certificate']['source_digest'] ?? ''
                ),
                'certificate_generation' => (int)(
                    $candidate['certificate']['generation'] ?? 0
                ),
            ];
            if (!\hash_equals(
                $this->canonicalJson($existingDesired),
                $this->canonicalJson($incomingDesired),
            )) {
                $reject();
            }
            $candidateIdentity = \is_array($candidate['backend_identity'] ?? null)
                ? $candidate['backend_identity']
                : [];
            if ($incomingIdentity === []) {
                $incomingIdentity = $candidateIdentity;
            } elseif (!\hash_equals(
                $this->canonicalJson($incomingIdentity),
                $this->canonicalJson($candidateIdentity),
            )) {
                $reject();
            }
            foreach ((array)($candidate['backends'] ?? []) as $backend) {
                if (!\is_array($backend)) {
                    $reject();
                }
                $key = (string)($backend['host'] ?? '') . ':'
                    . (int)($backend['port'] ?? 0) . ':'
                    . (int)($backend['weight'] ?? 1);
                $incomingBackends[$key] = $backend;
            }
        }
        \ksort($incomingBackends, SORT_STRING);
        $existingBackends = [];
        foreach ((array)($existingInstance['backends'] ?? []) as $backend) {
            if (!\is_array($backend)) {
                $reject();
            }
            $key = (string)($backend['host'] ?? '') . ':'
                . (int)($backend['port'] ?? 0) . ':'
                . (int)($backend['weight'] ?? 1);
            $existingBackends[$key] = $backend;
        }
        \ksort($existingBackends, SORT_STRING);
        if (!\hash_equals(
            $this->canonicalJson($existingBackends),
            $this->canonicalJson($incomingBackends),
        )) {
            $reject();
        }

        $existingIdentity = \is_array($existingInstance['backend_identity'] ?? null)
            ? $existingInstance['backend_identity']
            : [];
        $capabilityKeys = [
            'session_capability',
            'session_capability_evidence',
            'session_capability_evidence_digest',
        ];
        $existingCapability = [];
        $incomingCapability = [];
        foreach ($capabilityKeys as $key) {
            if (\array_key_exists($key, $existingIdentity)) {
                $existingCapability[$key] = $existingIdentity[$key];
            }
            if (\array_key_exists($key, $incomingIdentity)) {
                $incomingCapability[$key] = $incomingIdentity[$key];
            }
            unset($existingIdentity[$key], $incomingIdentity[$key]);
        }
        // Both digests are expected to rotate when the capability evidence
        // changes. Compare the signed facts themselves here; each incoming
        // private/public digest was already validated during route parsing.
        unset(
            $existingIdentity['digest'],
            $existingIdentity['public_digest'],
            $incomingIdentity['digest'],
            $incomingIdentity['public_digest'],
        );
        if ($existingIdentity === []
            || !\hash_equals(
                $this->canonicalJson($existingIdentity),
                $this->canonicalJson($incomingIdentity),
            )
            || \hash_equals(
                $this->canonicalJson($existingCapability),
                $this->canonicalJson($incomingCapability),
            )
            || !\hash_equals(
                $instanceId,
                (string)($incomingIdentity['instance_id'] ?? ''),
            )
        ) {
            $reject();
        }
    }

    /**
     * A live launch may update endpoint-validated runtime identity evidence
     * without inventing a project or process generation. Both independent
     * process fences must still match exactly; route validation follows.
     *
     * @param array<string,mixed> $existingInstance
     */
    private function mayRefreshInstanceDigest(
        array $existingInstance,
        int $masterEpoch,
        string $launchId,
    ): bool {
        $existingMasterEpoch = (int)($existingInstance['master_epoch'] ?? 0);
        $existingLaunchId = \strtolower(\trim((string)($existingInstance['launch_id'] ?? '')));
        return $masterEpoch > 0
            && $existingMasterEpoch === $masterEpoch
            && \preg_match('/\A[a-f0-9]{32}\z/D', $existingLaunchId) === 1
            && \hash_equals($existingLaunchId, $launchId);
    }

    /**
     * @param array<string,mixed> $instance
     * @param array<string,mixed> $payload
     */
    private function assertInstancePayloadFence(array $instance, array $payload): void
    {
        if ((int)($instance['generation'] ?? 0) !== (int)($payload['instance_generation'] ?? 0)
            || (int)($instance['master_epoch'] ?? 0) !== (int)($payload['master_epoch'] ?? 0)
            || !$this->sameLeaseBoot($instance)
            || !\hash_equals(
                (string)($instance['launch_id'] ?? ''),
                \strtolower(\trim((string)($payload['launch_id'] ?? ''))),
            )
        ) {
            throw new \DomainException('Instance lifecycle request has stale fencing identity.');
        }
    }

    /** @param array<string,mixed> $payload */
    private function assertCurrentHostBootPayload(
        array $payload,
        string $operation,
    ): void {
        $bootId = \strtolower(\trim((string)($payload['host_boot_id'] ?? '')));
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $bootId) !== 1
            || !\hash_equals($this->hostBootId, $bootId)
        ) {
            throw new WlsEdgeProtocolException(
                'host_boot_changed',
                $operation . ' host boot identity is stale or missing; fetch status and '
                    . 'submit a full registration for the current boot.',
            );
        }
    }

    /** @param array<string,mixed> $payload */
    private function assertGatewayEpochPayload(
        array $payload,
        string $operation,
    ): void {
        $epoch = \strtolower(\trim((string)($payload['gateway_epoch'] ?? '')));
        if (\preg_match('/\A[a-f0-9]{32}\z/D', $epoch) !== 1
            || !\hash_equals((string)($this->state['epoch'] ?? ''), $epoch)
        ) {
            throw new \DomainException(
                $operation . ' gateway epoch is stale or missing; full registration is required.'
            );
        }
    }

    /**
     * @param array<string,mixed> $route
     */
    private function selectRouteBackends(array &$route): void
    {
        $projectUuid = (string)($route['project_uuid'] ?? '');
        $projectTombstone = $projectUuid === ''
            ? null
            : ($this->state['security']['tombstones']['project:' . $projectUuid] ?? null);
        if ((string)($route['status'] ?? '') === 'REMOVED'
            || (\is_array($projectTombstone)
                && \hash_equals(
                    $projectUuid,
                    (string)($projectTombstone['project_uuid'] ?? ''),
                ))
        ) {
            // A project revocation is an irreversible security decision. Lease
            // sweeps, backend probes and delayed lifecycle messages must never
            // repopulate routing secrets or reactivate the removed route.
            $this->enforceRemovedRoute($route);
            return;
        }

        $now = \time();
        $monotonicNow = $this->monotonicNow();
        $active = [];
        $draining = false;
        $backendPending = false;
        foreach ((array)($route['instances'] ?? []) as $instanceId => $instance) {
            if (!\is_array($instance)) {
                continue;
            }
            $status = (string)($instance['status'] ?? '');
            if ($status === 'DRAINING') {
                $draining = true;
                continue;
            }
            if ($status !== 'ACTIVE') {
                continue;
            }
            $leaseAge = $monotonicNow
                - (float)($instance['last_heartbeat_monotonic'] ?? 0.0);
            $publicationLeasePending = $this->publicationLeasePending(
                $projectUuid,
                (string)$instanceId,
                $instance,
                $monotonicNow,
            );
            if (!$publicationLeasePending
                && (!$this->sameLeaseBoot($instance)
                || $leaseAge < 0.0
                || $leaseAge >= self::HEARTBEAT_TTL)
            ) {
                continue;
            }
            if (!($instance['backend_healthy'] ?? false)) {
                $backendPending = true;
                continue;
            }
            $active[(string)$instanceId] = $instance;
        }
        \ksort($active, SORT_STRING);
        $selected = [];
        $selectedInstances = [];
        $preferred = '';
        $distributionMode = 'single';
        if ($active !== []) {
            $preferred = (string)\array_key_first($active);
            $distributionMode = $this->routeDistributionMode($route, $active);
            $eligibleInstances = $distributionMode === 'single'
                ? [$preferred => $active[$preferred]]
                : $active;
            foreach ($eligibleInstances as $instanceId => $instance) {
                $instanceBackends = [];
                foreach ((array)($instance['backends'] ?? []) as $backend) {
                    if (\is_array($backend)) {
                        $selected[] = $backend;
                        $instanceBackends[] = $backend;
                    }
                    if (\count($selected) >= 16) {
                        break;
                    }
                }
                if ($instanceBackends !== []) {
                    $selectedInstances[(string)$instanceId] = [
                        'instance_id' => (string)$instanceId,
                        'backends' => $instanceBackends,
                        'backend_identity' => (array)($instance['backend_identity'] ?? []),
                    ];
                }
                if (\count($selected) >= 16) {
                    break;
                }
            }
        }
        if (\count($selectedInstances) < 2) {
            $distributionMode = 'single';
        }
        $route['preferred_instance_id'] = $preferred;
        $route['instance_id'] = $preferred;
        $route['backend_identity'] = $preferred === ''
            ? []
            : (array)($active[$preferred]['backend_identity'] ?? []);
        $route['backends'] = $selected;
        $route['backend_instances'] = $selectedInstances;
        $route['distribution_mode'] = $distributionMode;
        $route['last_heartbeat'] = $active === []
            ? (int)($route['last_heartbeat'] ?? 0)
            : \max(\array_map(
                static fn (array $instance): int => (int)($instance['last_heartbeat'] ?? 0),
                $active,
            ));
        if (!(bool)($route['certificate']['valid'] ?? false)) {
            $route['status'] = 'PENDING_CERTIFICATE';
        } elseif ($selected !== []) {
            $route['status'] = 'ACTIVE';
            $route['stale_since'] = null;
            $route['stale_since_monotonic'] = null;
            $route['stale_boot_id'] = null;
        } elseif ($draining) {
            $route['status'] = 'DRAINING';
        } elseif ($backendPending) {
            $route['status'] = 'PENDING_BACKEND';
            $route['stale_since'] = null;
            $route['stale_since_monotonic'] = null;
            $route['stale_boot_id'] = null;
        } else {
            $route['status'] = 'STALE';
            if (!\hash_equals(
                $this->hostBootId,
                (string)($route['stale_boot_id'] ?? ''),
            ) || (float)($route['stale_since_monotonic'] ?? 0.0) > $monotonicNow) {
                $route['stale_since'] = $now;
                $route['stale_since_monotonic'] = $monotonicNow;
                $route['stale_boot_id'] = $this->hostBootId;
            } else {
                $route['stale_since'] ??= $now;
                $route['stale_since_monotonic'] ??= $monotonicNow;
            }
        }
    }

    /**
     * @param array<string,mixed> $route
     */
    private function enforceRemovedRoute(array &$route, ?int $removedAt = null): void
    {
        $this->retainRouteSecurityClosure($route, false, 'REMOVED');
        $route['status'] = 'REMOVED';
        if ((int)($route['removed_at'] ?? 0) <= 0) {
            $route['removed_at'] = $removedAt ?? \time();
        }
        $route['instances'] = [];
        $route['backends'] = [];
        $route['backend_instances'] = [];
        $route['preferred_instance_id'] = '';
        $route['instance_id'] = '';
        $route['backend_identity'] = [];
        $route['distribution_mode'] = 'single';
    }

    /**
     * Multiple WLS instances may share traffic only when the administrator
     * enrollment and every currently eligible runtime independently attest
     * the same session-safe capability. Any mixed or missing proof retains
     * the deterministic preferred-instance/hot-standby topology.
     *
     * @param array<string,mixed> $route
     * @param array<string,array<string,mixed>> $active
     */
    private function routeDistributionMode(array $route, array $active): string
    {
        if (\count($active) < 2) {
            return 'single';
        }
        $projectUuid = (string)($route['project_uuid'] ?? '');
        $enrollment = \is_array($this->state['enrollments'][$projectUuid] ?? null)
            ? $this->state['enrollments'][$projectUuid]
            : [];
        $capabilities = \is_array($enrollment['capabilities'] ?? null)
            ? $enrollment['capabilities']
            : [];
        $mode = '';
        $sharedEvidenceDigest = '';
        foreach ($active as $instance) {
            $identity = \is_array($instance['backend_identity'] ?? null)
                ? $instance['backend_identity']
                : [];
            $instanceMode = (string)($identity['session_capability'] ?? 'isolated');
            if (!\in_array($instanceMode, ['stateless', 'shared_session'], true)
                || ($capabilities[$instanceMode] ?? false) !== true
                || !$this->validStoredDistributionCapability($identity, $instanceMode)
            ) {
                return 'single';
            }
            if ($mode === '') {
                $mode = $instanceMode;
            } elseif (!\hash_equals($mode, $instanceMode)) {
                return 'single';
            }
            if ($instanceMode === 'shared_session') {
                $instanceEvidenceDigest = (string)(
                    $identity['session_capability_evidence_digest'] ?? ''
                );
                if ($sharedEvidenceDigest === '') {
                    $sharedEvidenceDigest = $instanceEvidenceDigest;
                } elseif (!\hash_equals($sharedEvidenceDigest, $instanceEvidenceDigest)) {
                    return 'single';
                }
            }
        }
        return $mode !== '' ? $mode : 'single';
    }

    /**
     * Rejects legacy, incomplete or corrupted capability claims after state
     * recovery. Shared Session instances are compared by the validated digest
     * in routeDistributionMode(), so different services fail closed.
     *
     * @param array<string,mixed> $identity
     * @param 'stateless'|'shared_session' $mode
     */
    private function validStoredDistributionCapability(array $identity, string $mode): bool
    {
        $evidence = \is_array($identity['session_capability_evidence'] ?? null)
            ? $identity['session_capability_evidence']
            : [];
        $digest = \strtolower(\trim((string)(
            $identity['session_capability_evidence_digest'] ?? ''
        )));
        if ($evidence === []
            || \preg_match('/\A[a-f0-9]{64}\z/D', $digest) !== 1
            || !\hash_equals(
                $digest,
                \hash('sha256', $this->canonicalJson($evidence)),
            )
        ) {
            return false;
        }
        if ($mode === 'stateless') {
            return $this->exactCapabilityEvidenceFields($evidence, [
                    'schema',
                    'runtime_source',
                    'runtime_declared',
                    'instance_generation',
                    'reason',
                ])
                && \is_bool($evidence['runtime_declared'] ?? null)
                && \is_int($evidence['instance_generation'] ?? null)
                && \hash_equals(
                    'wls-stateless-capability/1',
                    (string)($evidence['schema'] ?? ''),
                )
                && \hash_equals(
                    'project_endpoint',
                    (string)($evidence['runtime_source'] ?? ''),
                )
                && ($evidence['runtime_declared'] ?? false) === true
                && (int)($evidence['instance_generation'] ?? 0)
                    === (int)($identity['generation'] ?? 0)
                && \hash_equals(
                    'declared_stateless_runtime',
                    (string)($evidence['reason'] ?? ''),
                );
        }

        $host = \strtolower(\trim((string)($evidence['host'] ?? '')));
        $port = (int)($evidence['port'] ?? 0);
        return $this->exactCapabilityEvidenceFields($evidence, [
                'schema',
                'storage',
                'runtime_source',
                'runtime_registered',
                'runtime_shared_service',
                'host',
                'port',
                'token_scope_digest',
                'probe',
                'reason',
            ])
            && \is_bool($evidence['runtime_registered'] ?? null)
            && \is_bool($evidence['runtime_shared_service'] ?? null)
            && \is_int($evidence['port'] ?? null)
            && \hash_equals(
                'wls-session-capability/1',
                (string)($evidence['schema'] ?? ''),
            )
            && \hash_equals('wls', (string)($evidence['storage'] ?? ''))
            && \hash_equals(
                'project_shared_state',
                (string)($evidence['runtime_source'] ?? ''),
            )
            && ($evidence['runtime_registered'] ?? false) === true
            && ($evidence['runtime_shared_service'] ?? false) === true
            && \in_array($host, ['127.0.0.1', '::1'], true)
            && $port > 0
            && $port <= 65535
            && \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($evidence['token_scope_digest'] ?? ''),
            ) === 1
            && \hash_equals('healthy', (string)($evidence['probe'] ?? ''))
            && \hash_equals(
                'authenticated_session_runtime',
                (string)($evidence['reason'] ?? ''),
            );
    }

    /**
     * @param array<string,mixed> $route
     */
    private function routeRoutingDigest(array $route): string
    {
        if ($route === []) {
            return '';
        }
        return \hash('sha256', $this->canonicalJson([
            'status' => (string)($route['status'] ?? ''),
            'domain' => (string)($route['domain'] ?? ''),
            'force_https' => (bool)($route['force_https'] ?? true),
            'force_root_to_www' => (bool)($route['force_root_to_www'] ?? false),
            'backends' => (array)($route['backends'] ?? []),
            'backend_instances' => (array)($route['backend_instances'] ?? []),
            'distribution_mode' => (string)($route['distribution_mode'] ?? 'single'),
            'preferred_instance_id' => (string)($route['preferred_instance_id'] ?? ''),
            'certificate' => [
                'state' => $this->certificateLifecycleState(
                    (array)($route['certificate'] ?? []),
                ),
                'source_digest' => (string)(
                    $route['certificate']['source_digest'] ?? ''
                ),
                'snapshot_digest' => (string)($route['certificate']['snapshot_digest'] ?? ''),
                'generation' => (int)($route['certificate']['generation'] ?? 0),
            ],
        ]));
    }

    /**
     * @return list<array<string,mixed>>
     */
    private function projectRoutes(string $projectUuid): array
    {
        return $this->projectRoutesFromState(
            $projectUuid,
            (array)($this->state['routes'] ?? []),
        );
    }

    /**
     * @param array<string,array<string,mixed>> $routes
     * @return list<array<string,mixed>>
     */
    private function projectRoutesFromState(string $projectUuid, array $routes): array
    {
        $result = \array_values(\array_filter(
            $routes,
            static fn (mixed $route): bool => \is_array($route)
                && (string)($route['project_uuid'] ?? '') === $projectUuid
                && (string)($route['status'] ?? '') !== 'REMOVED',
        ));
        \usort(
            $result,
            static fn (array $left, array $right): int =>
                (string)($left['domain'] ?? '') <=> (string)($right['domain'] ?? ''),
        );
        return $result;
    }

    /**
     * @return list<array<string,mixed>>
     */
    private function projectInstanceStatuses(string $projectUuid): array
    {
        $statuses = [];
        foreach ((array)($this->state['instances'][$projectUuid] ?? []) as $instanceId => $instance) {
            if (!\is_array($instance)) {
                continue;
            }
            $status = (string)($instance['status'] ?? 'ACTIVE');
            if ($status !== 'DRAINING') {
                $statuses[] = [
                    'instance_id' => (string)$instanceId,
                    'status' => $status,
                    'generation' => (int)($instance['generation'] ?? 0),
                    'digest' => (string)($instance['digest'] ?? ''),
                    'master_epoch' => (int)($instance['master_epoch'] ?? 0),
                    'launch_id' => (string)($instance['launch_id'] ?? ''),
                    'drain_until' => (int)($instance['drain_until'] ?? 0),
                    'backend_count' => \count((array)($instance['backends'] ?? [])),
                    'reachable_backends' => 0,
                    'counters_known' => false,
                    'active_requests' => 0,
                    'long_lived_connections' => 0,
                    'sse_connections' => 0,
                    'websocket_connections' => 0,
                    'counter_source' => 'none',
                    'drain_complete' => false,
                ];
                continue;
            }
            $activeRequests = 0;
            $longLived = 0;
            $sse = 0;
            $webSocket = 0;
            $reachable = 0;
            $counterCapable = 0;
            $backends = (array)($instance['backends'] ?? []);
            if (\array_key_exists('drain_counters', $instance)) {
                $reported = \is_array($instance['drain_counters'])
                    ? $instance['drain_counters']
                    : [];
                $reportAge = $this->monotonicNow()
                    - (float)($reported['reported_monotonic'] ?? 0.0);
                $countersKnown = (int)($reported['version'] ?? 0) === 1
                    && ($reported['counters_known'] ?? false) === true
                    && $this->hostBootId === (string)($reported['lease_boot_id'] ?? '')
                    && $reportAge >= 0.0
                    && $reportAge <= 25.0
                    && (int)($reported['worker_count'] ?? 0) > 0
                    && (int)($reported['reported_worker_count'] ?? -1)
                        === (int)($reported['worker_count'] ?? 0);
                $activeRequests = $countersKnown
                    ? (int)($reported['active_requests'] ?? 0)
                    : 0;
                $longLived = $countersKnown
                    ? (int)($reported['long_lived_connections'] ?? 0)
                    : 0;
                $sse = $countersKnown
                    ? (int)($reported['sse_connections'] ?? 0)
                    : 0;
                $webSocket = $countersKnown
                    ? (int)($reported['websocket_connections'] ?? 0)
                    : 0;
                $statuses[] = [
                    'instance_id' => (string)$instanceId,
                    'status' => $status,
                    'generation' => (int)($instance['generation'] ?? 0),
                    'digest' => (string)($instance['digest'] ?? ''),
                    'master_epoch' => (int)($instance['master_epoch'] ?? 0),
                    'launch_id' => (string)($instance['launch_id'] ?? ''),
                    'drain_until' => (int)($instance['drain_until'] ?? 0),
                    'backend_count' => \count($backends),
                    'reachable_backends' => 0,
                    'counters_known' => $countersKnown,
                    'active_requests' => $activeRequests,
                    'long_lived_connections' => $longLived,
                    'sse_connections' => $sse,
                    'websocket_connections' => $webSocket,
                    'counter_source' => 'master-heartbeat',
                    'drain_complete' => $countersKnown
                        && $activeRequests === 0
                        && $longLived === 0,
                ];
                continue;
            }
            $identity = (array)($instance['backend_identity'] ?? []);
            if ($backends === [] || $identity === []) {
                $legacyBackends = [];
                foreach ($this->projectRoutes($projectUuid) as $route) {
                    $routeInstance = $route['instances'][$instanceId] ?? null;
                    if (!\is_array($routeInstance)) {
                        continue;
                    }
                    $identity = $identity !== []
                        ? $identity
                        : (array)($routeInstance['backend_identity'] ?? []);
                    foreach ((array)($routeInstance['backends'] ?? []) as $backend) {
                        if (!\is_array($backend)) {
                            continue;
                        }
                        $legacyBackends[(string)($backend['host'] ?? '') . ':'
                            . (int)($backend['port'] ?? 0)] = $backend;
                    }
                }
                $backends = \array_values($legacyBackends);
            }
            foreach ($backends as $backend) {
                if (!\is_array($backend)) {
                    continue;
                }
                $health = $this->probeBackendHealth($backend, $identity);
                if ($health === null) {
                    continue;
                }
                ++$reachable;
                if ((int)($health['drain_counters_version'] ?? 0) === 1) {
                    ++$counterCapable;
                }
                $activeRequests += \max(0, (int)($health['active_requests'] ?? 0));
                $longLived += \max(0, (int)($health['long_lived_connections'] ?? 0));
                $sse += \max(0, (int)($health['sse_connections'] ?? 0));
                $webSocket += \max(0, (int)($health['websocket_connections'] ?? 0));
            }
            $countersKnown = $backends !== []
                && $reachable === \count($backends)
                && $counterCapable === \count($backends);
            $statuses[] = [
                'instance_id' => (string)$instanceId,
                'status' => $status,
                'generation' => (int)($instance['generation'] ?? 0),
                'digest' => (string)($instance['digest'] ?? ''),
                'master_epoch' => (int)($instance['master_epoch'] ?? 0),
                'launch_id' => (string)($instance['launch_id'] ?? ''),
                'drain_until' => (int)($instance['drain_until'] ?? 0),
                'backend_count' => \count($backends),
                'reachable_backends' => $reachable,
                'counters_known' => $countersKnown,
                'active_requests' => $activeRequests,
                'long_lived_connections' => $longLived,
                'sse_connections' => $sse,
                'websocket_connections' => $webSocket,
                'counter_source' => 'legacy-backend-probe',
                'drain_complete' => $status === 'DRAINING'
                    && $countersKnown
                    && $activeRequests === 0
                    && $longLived === 0,
            ];
        }
        return $statuses;
    }

    /**
     * @param array<string,mixed> $identity
     * @return array<string,mixed>
     */
    private function publicBackendIdentityProjection(array $identity): array
    {
        if (!\hash_equals(
            self::BACKEND_IDENTITY_SCHEMA,
            (string)($identity['schema'] ?? ''),
        )) {
            throw new \RuntimeException(
                'Backend identity cannot be projected from an unknown schema.'
            );
        }
        $projection = [];
        foreach (self::BACKEND_IDENTITY_PUBLIC_FIELDS as $field) {
            if (\array_key_exists($field, $identity)) {
                $projection[$field] = $identity[$field];
            }
        }
        $publicDigest = \strtolower(\trim((string)(
            $projection['public_digest'] ?? ''
        )));
        $digestFacts = $projection;
        unset($digestFacts['public_digest']);
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $publicDigest) !== 1
            || !\hash_equals(
                $publicDigest,
                \hash('sha256', $this->canonicalJson($digestFacts)),
            )
        ) {
            throw new \RuntimeException(
                'Backend public identity digest is missing or inconsistent.'
            );
        }
        // Recovered state predating the strict evidence schema may still have
        // a self-consistent public digest. Never project an oversized or
        // extension-bearing capability object merely because its digest is
        // valid: doing so can make every paged status response unrepresentable
        // inside the fixed protocol frame.
        $this->validateBackendSessionCapabilityClaim($projection);
        return $projection;
    }

    private function projectBackendIdentitiesForResponse(
        mixed $value,
        int $depth = 0,
    ): mixed {
        if ($depth > 64 || !\is_array($value)) {
            return $value;
        }
        if (\hash_equals(
            self::BACKEND_IDENTITY_SCHEMA,
            (string)($value['schema'] ?? ''),
        )) {
            try {
                return $this->publicBackendIdentityProjection($value);
            } catch (\Throwable) {
                // A pre-upgrade or damaged stored listener identity must not
                // leak its private half or make the entire authenticated
                // status response unavailable. An empty projection is
                // deliberately unusable by the Agent and forces re-attested
                // registration before that route can be trusted again.
                return [];
            }
        }
        $projected = [];
        foreach ($value as $key => $item) {
            $projected[$key] = $this->projectBackendIdentitiesForResponse(
                $item,
                $depth + 1,
            );
        }
        return $projected;
    }

    /**
     * @param resource $client
     * @param array<string,mixed> $payload
     */
    private function writeResponse(
        $client,
        string $requestId,
        bool $ok,
        array $payload = [],
        string $errorCode = '',
        string $message = '',
        string $responseSecret = '',
        bool $allowEnrollmentCredential = false,
    ): void {
        $isPublicDerivative = static function (string $normalizedKey): bool {
            if (\preg_match(
                '/(?:digest|hash|fingerprint|thumbprint)/',
                $normalizedKey,
            ) === 1) {
                return true;
            }
            return \preg_match(
                '/\A(?:response)?(?:signature|mac)(?:algorithm|version|metadata|keyid|status)?\z/D',
                $normalizedKey,
            ) === 1;
        };
        $credentialPublicSuffix = '/credential(?:id|identifier|reference|generation|digest|hash|fingerprint|thumbprint)\z/D';
        $hasSensitiveMaterial = static function (string $normalizedKey): bool {
            return \str_contains($normalizedKey, 'secret')
                || \str_contains($normalizedKey, 'token')
                || \str_contains($normalizedKey, 'authorization')
                || \str_contains($normalizedKey, 'password')
                || \str_contains($normalizedKey, 'passphrase')
                || \str_contains($normalizedKey, 'apikey')
                || \str_contains($normalizedKey, 'signingkey')
                || \str_contains($normalizedKey, 'privatekey')
                || \preg_match(
                    '/(?:auth|authentication)(?:data|header|material|value|key|bearer)/',
                    $normalizedKey,
                ) === 1;
        };
        $isSensitiveKey = static function (string $key) use (
            $credentialPublicSuffix,
            $hasSensitiveMaterial,
            $isPublicDerivative,
        ): bool {
            $normalizedKey = \strtolower((string)\preg_replace('/[^a-z0-9]+/i', '', $key));
            if ($normalizedKey === '') {
                return false;
            }
            if ($normalizedKey === 'credentialreceipt') {
                return false;
            }
            if (\str_contains($normalizedKey, 'credential')) {
                if (\preg_match($credentialPublicSuffix, $normalizedKey) !== 1) {
                    return true;
                }
                $credentialPrefix = (string)\preg_replace(
                    $credentialPublicSuffix,
                    '',
                    $normalizedKey,
                );
                return $hasSensitiveMaterial($credentialPrefix);
            }
            if ($isPublicDerivative($normalizedKey)) {
                return false;
            }
            return $hasSensitiveMaterial($normalizedKey);
        };
        $seenObjects = new \SplObjectStorage();
        $sanitize = function (
            mixed $value,
            int $depth = 0,
        ) use (&$sanitize, $isSensitiveKey, $seenObjects): mixed {
            if ($depth > 64) {
                return null;
            }
            if (\is_object($value)) {
                if ($seenObjects->contains($value)) {
                    return null;
                }
                $object = $value;
                $seenObjects->attach($object);
                try {
                    $normalized = $object instanceof \JsonSerializable
                        ? $object->jsonSerialize()
                        : \get_object_vars($object);
                    return $sanitize($normalized, $depth + 1);
                } finally {
                    $seenObjects->detach($object);
                }
            }
            if (!\is_array($value)) {
                return $value;
            }
            $sanitized = [];
            foreach ($value as $key => $item) {
                if (\is_string($key) && $isSensitiveKey($key)) {
                    continue;
                }
                $sanitized[$key] = $sanitize($item, $depth + 1);
            }
            return $sanitized;
        };

        $response = [
            'protocol' => self::PROTOCOL,
            'request_id' => $requestId,
            'ok' => $ok,
            'epoch' => (string)($this->state['epoch'] ?? ''),
            'payload' => $payload,
        ];
        if (!$ok) {
            $response['error'] = ['code' => $errorCode, 'message' => $message];
        }
        // Full listener identity binds a per-instance HMAC secret and its
        // private digest. Responses expose only the independently digested
        // public projection; deleting the secret while retaining the full
        // digest would create an authenticated but semantically impossible
        // identity and force healthy projects into fallback.
        $response = $this->projectBackendIdentitiesForResponse($response);
        $enrollmentCredential = null;
        $credential = \is_array($payload['credential'] ?? null)
            ? $payload['credential']
            : null;
        $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
        $enrollment = $this->state['enrollments'][$projectUuid] ?? null;
        $rotationCredentialAuthorized = false;
        if (\is_array($credential)) {
            $rotationId = \strtolower(\trim((string)(
                $payload['rotation_id'] ?? ''
            )));
            foreach ((array)($this->state['rotation_transactions'] ?? []) as $rotation) {
                if (!\is_array($rotation)
                    || \in_array(
                        (string)($rotation['phase'] ?? ''),
                        ['ABORTED', 'FINALIZED'],
                        true,
                    )
                    || !\hash_equals(
                        $rotationId,
                        (string)($rotation['rotation_id'] ?? ''),
                    )
                    || !\hash_equals(
                        $projectUuid,
                        (string)($rotation['new_project_uuid'] ?? ''),
                    )
                    || !\hash_equals(
                        (string)($credential['credential_id'] ?? ''),
                        (string)($rotation['new_credential_id'] ?? ''),
                    )
                    || !\hash_equals(
                        (string)($credential['secret'] ?? ''),
                        (string)($rotation['new_credential_secret'] ?? ''),
                    )
                    || (int)($credential['credential_generation'] ?? 0)
                        !== (int)($rotation['new_credential_generation'] ?? -1)
                    || (int)($payload['security_generation'] ?? -1)
                        !== (int)($rotation['security_generation'] ?? 0)
                ) {
                    continue;
                }
                $rotationCredentialAuthorized = true;
                break;
            }
        }
        $issuedAt = \is_array($credential)
            ? (string)($credential['issued_at'] ?? '')
            : '';
        $issuedAtValue = $issuedAt !== ''
            ? \DateTimeImmutable::createFromFormat(DATE_ATOM, $issuedAt)
            : false;
        if ($allowEnrollmentCredential
            && $ok
            && ($payload['accepted'] ?? false) === true
            && \is_array($credential)
            && (\is_array($enrollment) || $rotationCredentialAuthorized)
            && (int)($credential['schema_version'] ?? 0) === 1
            && \hash_equals(self::PROTOCOL, (string)($credential['protocol'] ?? ''))
            && \hash_equals($this->hostId(), (string)($credential['host_id'] ?? ''))
            && $this->validProjectUuid($projectUuid)
            && \hash_equals($projectUuid, (string)($credential['project_uuid'] ?? ''))
            && \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($credential['credential_id'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($credential['secret'] ?? ''),
            ) === 1
            && ($rotationCredentialAuthorized || (
                \hash_equals(
                    (string)($enrollment['credential_id'] ?? ''),
                    (string)$credential['credential_id'],
                )
                && \hash_equals(
                    (string)($enrollment['credential_secret'] ?? ''),
                    (string)$credential['secret'],
                )
                && (int)($enrollment['credential_generation'] ?? 0)
                    === (int)($credential['credential_generation'] ?? -1)
                && (int)($enrollment['security_generation'] ?? 0)
                    === (int)($payload['security_generation'] ?? -1)
            ))
            && $issuedAtValue instanceof \DateTimeImmutable
            && $issuedAtValue->format(DATE_ATOM) === $issuedAt
        ) {
            $enrollmentCredential = [
                'schema_version' => 1,
                'protocol' => self::PROTOCOL,
                'host_id' => (string)$credential['host_id'],
                'project_uuid' => $projectUuid,
                'credential_id' => (string)$credential['credential_id'],
                'credential_generation' => (int)$credential['credential_generation'],
                'secret' => (string)$credential['secret'],
                'issued_at' => $issuedAt,
            ];
        }
        $response = $sanitize($response);
        if ($enrollmentCredential !== null && \is_array($response['payload'] ?? null)) {
            $response['payload']['credential'] = $enrollmentCredential;
        }
        $response = $this->fitResponseFrameBeforeSigning(
            $response,
            $responseSecret,
            $enrollmentCredential,
        );
        $signed = \preg_match('/\A[a-f0-9]{64}\z/D', $responseSecret) === 1;
        if ($signed) {
            $response['signature'] = \hash_hmac(
                'sha256',
                $this->canonicalJson($response),
                $responseSecret,
            );
        }
        $encoded = \json_encode(
            $response,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION,
        );
        if (!\is_string($encoded)
            || \strlen($encoded) + 1 > self::MAX_RESPONSE_FRAME_BYTES
        ) {
            // fitResponseFrameBeforeSigning reserves the exact signature field.
            // Reaching this branch means the encoder contract itself changed;
            // close without a partial frame so the Broker cannot be desynced.
            return;
        }
        $this->writeStreamAll($client, $encoded . "\n");
    }

    /**
     * @param array<string,mixed> $response
     * @param array<string,mixed>|null $oneTimeCredential
     * @return array<string,mixed>
     */
    private function fitResponseFrameBeforeSigning(
        array $response,
        string $responseSecret,
        ?array $oneTimeCredential,
    ): array {
        $candidate = $response;
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $responseSecret) === 1) {
            $candidate['signature'] = \str_repeat('0', 64);
        }
        $encoded = \json_encode(
            $candidate,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION,
        );
        if (\is_string($encoded)
            && \strlen($encoded) + 1 <= self::MAX_RESPONSE_FRAME_BYTES
        ) {
            return $response;
        }

        $payload = \is_array($response['payload'] ?? null)
            ? $response['payload']
            : [];
        $digest = \is_string($encoded)
            ? \hash('sha256', $encoded)
            : \hash('sha256', $this->canonicalJson($response));
        $receipt = [
            'receipt' => [
                'schema' => 1,
                'code' => 'response_too_large',
                'committed' => ($response['ok'] ?? false) === true,
                'operation' => $this->requestOperation,
                'principal' => $this->requestPrincipal,
                'result_digest' => $digest,
            ],
        ];
        foreach ([
            'accepted',
            'ready',
            'state',
            'project_uuid',
            'generation',
            'security_generation',
            'operation_id',
            'rotation_id',
            'transfer_id',
        ] as $field) {
            if (\array_key_exists($field, $payload)
                && (\is_scalar($payload[$field]) || $payload[$field] === null)
            ) {
                $receipt[$field] = $payload[$field];
            }
        }
        if ($oneTimeCredential !== null) {
            $receipt['credential'] = $oneTimeCredential;
        }
        $bounded = [
            'protocol' => (string)($response['protocol'] ?? self::PROTOCOL),
            'request_id' => (string)($response['request_id'] ?? ''),
            'ok' => (bool)($response['ok'] ?? false),
            'epoch' => (string)($response['epoch'] ?? ''),
            'payload' => $receipt,
        ];
        if (($response['ok'] ?? false) !== true) {
            $bounded['error'] = [
                'code' => 'response_too_large',
                'message' => 'The authenticated gateway response exceeded its fixed frame limit.',
            ];
        }
        return $bounded;
    }

    /**
     * @param array<string,mixed> $request
     * @param array<string,mixed> $broker
     * @return array{error:string,secret:string,project_uuid:string,error_code?:string}
     */
    private function authenticate(array $request, array $broker): array
    {
        if ((string)($request['protocol'] ?? '') !== self::PROTOCOL) {
            return ['error' => 'Protocol mismatch.', 'secret' => '', 'project_uuid' => ''];
        }
        $channel = (string)($broker['channel'] ?? '');
        if (!\hash_equals($channel, (string)($request['channel'] ?? ''))) {
            return [
                'error' => 'The request channel does not match the broker channel.',
                'secret' => '',
                'project_uuid' => '',
            ];
        }
        if (!\hash_equals($this->hostId(), (string)($request['host_id'] ?? ''))) {
            return [
                'error' => 'The request belongs to another gateway host.',
                'secret' => '',
                'project_uuid' => '',
            ];
        }
        $timestamp = (int)($request['timestamp'] ?? 0);
        $requestMonotonic = $request['monotonic_timestamp'] ?? null;
        $monotonicNow = $this->monotonicNow();
        if ((! \is_int($requestMonotonic) && !\is_float($requestMonotonic))
            || \abs($monotonicNow - (float)$requestMonotonic) > 60.0
        ) {
            return [
                'error' => 'Request monotonic timestamp is outside the accepted window.',
                'secret' => '',
                'project_uuid' => '',
            ];
        }
        if (\abs(\time() - $timestamp) > 60 && $this->observeWallClock()) {
            return [
                'error' => 'Request timestamp is outside the accepted window.',
                'secret' => '',
                'project_uuid' => '',
            ];
        }
        $nonce = \strtolower((string)($request['nonce'] ?? ''));
        if (!\preg_match('/\A[a-f0-9]{32}\z/D', $nonce) || isset($this->nonces[$nonce])) {
            return [
                'error' => 'Request nonce is invalid or replayed.',
                'secret' => '',
                'project_uuid' => '',
            ];
        }
        $operation = \strtolower(\trim((string)($request['operation'] ?? '')));
        $adminOperations = [
            'status',
            'routes',
            'doctor',
            'operation-status',
            'bootstrap',
            'enroll',
            'revoke',
            'transfer',
            'repair',
            'upgrade',
            'stop',
        ];
        $projectOperations = [
            'own-status',
            'operation-status',
            'register',
            'renew',
            'heartbeat',
            'acme-challenge-sync',
            'transfer-stage',
            'drain',
            'unregister',
            'rotate-prepare',
            'rotate-commit',
            'rotate-status',
            'rotate-finalize',
            'rotate-abort',
        ];
        $projectUuid = '';
        $secret = '';
        if ($channel === 'admin') {
            if (!\hash_equals('admin', (string)($request['credential_id'] ?? ''))
                || !$this->administratorPeerAllowed($broker)
            ) {
                return [
                    'error' => 'Administrator operation or OS identity is not authorized.',
                    'secret' => '',
                    'project_uuid' => '',
                ];
            }
            $secret = \strtolower(\trim($this->readStableRegularFile(
                $this->adminTokenFile(),
                65,
                'Gateway administrator credential',
            )));
            if (!\in_array($operation, $adminOperations, true)) {
                return [
                    'error' => 'The administrator channel does not support this operation.',
                    'secret' => $secret,
                    'project_uuid' => '',
                ];
            }
        } elseif ($channel === 'project') {
            $payload = \is_array($request['payload'] ?? null) ? $request['payload'] : [];
            $projectUuid = \strtolower(\trim((string)($payload['project_uuid'] ?? '')));
            $enrollment = $this->validProjectUuid($projectUuid)
                ? ($this->state['enrollments'][$projectUuid] ?? null)
                : null;
            $tombstone = $this->state['security']['tombstones']['project:' . $projectUuid] ?? null;
            $rotationRole = \is_array($enrollment)
                ? (string)($enrollment['rotation_role'] ?? '')
                : '';
            $oldRotationRecovery = $rotationRole === 'old'
                && \in_array(
                    $operation,
                    ['rotate-prepare', 'rotate-commit', 'rotate-status'],
                    true,
                );
            if (!\is_array($enrollment)
                || (\is_array($tombstone)
                    && (int)($tombstone['generation'] ?? 0)
                        >= (int)($enrollment['security_generation'] ?? 0)
                    && !$oldRotationRecovery)
                || !\hash_equals(
                    (string)($enrollment['credential_id'] ?? ''),
                    (string)($request['credential_id'] ?? ''),
                )
                || !$this->peerMatchesEnrollment($broker, $enrollment)
            ) {
                return [
                    'error' => 'Project capability or OS peer identity is not authorized.',
                    'secret' => '',
                    'project_uuid' => '',
                ];
            }
            $secret = \strtolower((string)($enrollment['credential_secret'] ?? ''));
            if ($rotationRole === 'old'
                && !\in_array(
                    $operation,
                    ['rotate-prepare', 'rotate-commit', 'rotate-status'],
                    true,
                )
            ) {
                return [
                    'error' => 'The old project identity is restricted to rotation recovery.',
                    'secret' => $secret,
                    'project_uuid' => $projectUuid,
                ];
            }
            if ($rotationRole === 'new'
                && !\in_array(
                    $operation,
                    ['rotate-status', 'rotate-finalize'],
                    true,
                )
            ) {
                return [
                    'error' => 'The new project identity must finalize rotation before use.',
                    'secret' => $secret,
                    'project_uuid' => $projectUuid,
                ];
            }
            if (!\in_array($operation, $projectOperations, true)) {
                return [
                    'error' => 'The project channel cannot perform administrator operations.',
                    'secret' => $secret,
                    'project_uuid' => $projectUuid,
                ];
            }
        }
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $secret) !== 1) {
            return [
                'error' => 'The selected gateway credential is unavailable.',
                'secret' => '',
                'project_uuid' => '',
            ];
        }
        $requestDigest = \strtolower((string)($request['request_digest'] ?? ''));
        $expectedDigest = \hash('sha256', $this->canonicalJson([
            'operation' => $operation,
            'payload' => \is_array($request['payload'] ?? null) ? $request['payload'] : [],
        ]));
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $requestDigest) !== 1
            || !\hash_equals($expectedDigest, $requestDigest)
        ) {
            return [
                'error' => 'Request digest is invalid.',
                'secret' => $secret,
                'project_uuid' => $projectUuid,
            ];
        }
        $signature = \strtolower((string)($request['signature'] ?? ''));
        unset($request['signature']);
        $expected = \hash_hmac('sha256', $this->canonicalJson($request), $secret);
        if (!\preg_match('/\A[a-f0-9]{64}\z/D', $signature) || !\hash_equals($expected, $signature)) {
            return [
                'error' => 'Request signature is invalid.',
                'secret' => $secret,
                'project_uuid' => $projectUuid,
            ];
        }
        $clockTrusted = $this->observeWallClock();
        $this->nonces[$nonce] = [
            'seen_at' => \time(),
            'seen_monotonic' => $monotonicNow,
            'boot_id' => $this->hostBootId,
        ];
        $this->state['security']['nonces'] = $this->nonces;
        if (!$this->authenticationOperationIsReadOnly($operation)) {
            try {
                $this->appendNonceWal($nonce, $this->nonces[$nonce]);
                $this->clockStatePersistPending = false;
                $this->lastClockStatePersistAttemptAt = $monotonicNow;
            } catch (\Throwable) {
                // Keep the authenticated nonce in memory so the same live
                // controller still rejects a replay, but never let a
                // read-only filesystem or exhausted inode table tear down the
                // control plane before it can return a signed failure.
                $this->markDiskPressure(
                    'PERSISTENCE_UNAVAILABLE',
                    'authentication_state_persist_failed',
                );
                return [
                    'error' => 'Gateway durable authentication state is unavailable; '
                        . 'persistent operation rejected while verified traffic is retained.',
                    'error_code' => 'storage_unavailable',
                    'secret' => $secret,
                    'project_uuid' => $projectUuid,
                ];
            }
        }
        $requestPayload = \is_array($request['payload'] ?? null)
            ? $request['payload']
            : [];
        $clockAcknowledgement = $channel === 'admin'
            && $operation === 'repair'
            && $requestPayload === ['accept_clock' => true];
        if (!$clockTrusted
            && !$clockAcknowledgement
            && !\in_array(
                $operation,
                ['status', 'routes', 'doctor', 'own-status', 'operation-status', 'heartbeat'],
                true,
            )
        ) {
            return [
                'error' => 'Gateway wall clock is untrusted; security-sensitive mutation rejected.',
                'secret' => $secret,
                'project_uuid' => $projectUuid,
            ];
        }
        return ['error' => '', 'secret' => $secret, 'project_uuid' => $projectUuid];
    }

    private function authenticationOperationIsReadOnly(string $operation): bool
    {
        return \in_array(
            $operation,
            ['status', 'routes', 'doctor', 'own-status', 'operation-status'],
            true,
        );
    }

    /**
     * @param array<string,mixed> $broker
     */
    private function administratorPeerAllowed(array $broker): bool
    {
        if (($this->slotManifestFromActiveFile()['test_mode'] ?? false) === true) {
            return (int)($broker['uid'] ?? -1) >= 0
                || (string)($broker['sid'] ?? '') !== '';
        }
        if (isset($broker['uid'])) {
            return (int)$broker['uid'] === 0;
        }
        return ($broker['is_admin'] ?? false) === true;
    }

    /**
     * @param array<string,mixed> $broker
     * @param array<string,mixed> $enrollment
     */
    private function peerMatchesEnrollment(array $broker, array $enrollment): bool
    {
        $owner = \is_array($enrollment['owner'] ?? null) ? $enrollment['owner'] : [];
        if ((string)($owner['kind'] ?? '') === 'posix') {
            return (int)($owner['uid'] ?? -1) >= 0
                && (int)($owner['uid'] ?? -1) === (int)($broker['uid'] ?? -2);
        }
        if ((string)($owner['kind'] ?? '') === 'windows') {
            $expected = \strtoupper((string)($owner['sid'] ?? ''));
            $actual = \strtoupper((string)($broker['sid'] ?? ''));
            return $expected !== '' && \hash_equals($expected, $actual);
        }
        return false;
    }

    private function assertRateLimit(string $channel, string $principal, string $operation): void
    {
        $readOnly = \in_array(
            $operation,
            ['status', 'routes', 'doctor', 'own-status', 'operation-status'],
            true,
        );
        $leaseHeartbeat = $channel === 'project'
            && \hash_equals('heartbeat', $operation);
        $bucket = $readOnly ? 'read' : ($leaseHeartbeat ? 'lease' : 'update');
        $rate = $readOnly
            ? 10.0
            : ($leaseHeartbeat ? 2.0 : ($channel === 'project' ? 1.0 : 2.0));
        $capacity = $readOnly
            ? 20.0
            : ($leaseHeartbeat ? 5.0 : ($channel === 'project' ? 5.0 : 10.0));
        $key = $channel . ':' . $principal . ':' . $bucket;
        $now = \hrtime(true) / 1_000_000_000;
        $window = $this->rateWindows[$key] ?? ['tokens' => $capacity, 'at' => $now];
        $tokens = \min($capacity, (float)$window['tokens'] + ($now - (float)$window['at']) * $rate);
        if ($tokens < 1.0) {
            $retryAfter = \max(1, (int)\ceil((1.0 - $tokens) / $rate));
            throw new \DomainException(
                'Gateway request rate limit exceeded; retry_after=' . $retryAfter . '.'
            );
        }
        $this->rateWindows[$key] = ['tokens' => $tokens - 1.0, 'at' => $now];
        if (\count($this->rateWindows) > 1024) {
            \uasort(
                $this->rateWindows,
                static fn (array $left, array $right): int => $right['at'] <=> $left['at'],
            );
            $this->rateWindows = \array_slice($this->rateWindows, 0, 1024, true);
        }
    }

    private function observeWallClock(): bool
    {
        $nowWall = \time();
        $nowMonotonic = $this->monotonicNow();
        $expectedWall = $this->clockWallAnchor
            + ($nowMonotonic - $this->clockMonotonicAnchor);
        if (\abs($nowWall - $expectedWall) > 5.0) {
            if (!isset($this->state['security']['clock_untrusted_since'])) {
                $this->state['security']['clock_untrusted_since'] = \gmdate(DATE_ATOM);
                $this->clockStatePersistPending = true;
            }
            $this->state['health_state'] = 'CLOCK_UNTRUSTED';
            $this->state['recovery']['stage'] = 'CLOCK_STABILITY_WAIT';
            $this->clockWallAnchor = $nowWall;
            $this->clockMonotonicAnchor = $nowMonotonic;
            $this->clockStableSinceMonotonic = 0.0;
            return false;
        }
        if (!isset($this->state['security']['clock_untrusted_since'])) {
            $this->clockStableSinceMonotonic = 0.0;
            return true;
        }
        $this->state['health_state'] = 'CLOCK_UNTRUSTED';
        $this->state['recovery']['stage'] = 'CLOCK_STABILITY_WAIT';
        if ($this->clockStableSinceMonotonic <= 0.0) {
            $this->clockStableSinceMonotonic = $nowMonotonic;
            return false;
        }
        if (($nowMonotonic - $this->clockStableSinceMonotonic)
            < self::CLOCK_RECOVERY_STABLE_SECONDS
        ) {
            return false;
        }

        unset($this->state['security']['clock_untrusted_since']);
        $this->state['security']['clock_retrusted_at'] = \gmdate(DATE_ATOM);
        $this->state['health_state'] = 'RECOVERING';
        $this->state['recovery']['stage'] = 'CLOCK_STABLE';
        $this->clockStableSinceMonotonic = 0.0;
        $this->clockStatePersistPending = true;
        return true;
    }

    private function monotonicNow(): float
    {
        return \hrtime(true) / 1_000_000_000;
    }

    private function nullDevice(): string
    {
        return \PHP_OS_FAMILY === 'Windows' ? 'NUL' : '/dev/null';
    }

    private function detectHostBootId(): string
    {
        if (\PHP_OS_FAMILY === 'Linux') {
            $bootId = \strtolower(\trim((string)$this->readLinuxProcPseudoFile(
                '/proc/sys/kernel/random/boot_id',
                128,
            )));
            if (\preg_match(
                '/\A[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}\z/D',
                $bootId,
            ) === 1) {
                return \hash(
                    'sha256',
                    'wls-gateway-host-boot/1|' . $bootId,
                );
            }
            throw new \RuntimeException('Linux boot identity is unavailable.');
        }
        if (\PHP_OS_FAMILY === 'Darwin') {
            // Prefer shared probe: Master may inherit FD 3, which makes the
            // bounded runner return 125 even when kern.boottime stdout is valid.
            $platformToken = \Weline\Server\Service\Edge\Gateway\GatewayHostBootIdentity::platformToken();
            if (\preg_match('/\Adarwin-\d+-\d+\z/D', $platformToken) !== 1) {
                throw new \RuntimeException('macOS boot identity is unavailable.');
            }
            return \hash(
                'sha256',
                'wls-gateway-host-boot/1|' . $platformToken,
            );
        }
        if (\PHP_OS_FAMILY === 'Windows') {
            if (!\class_exists(\FFI::class, false)) {
                throw new \RuntimeException(
                    'Direct Windows Controller startup requires PHP FFI for boot identity.'
                );
            }
            try {
                $ffi = \FFI::cdef(
                    <<<'CDEF'
typedef long NTSTATUS;
typedef unsigned long ULONG;
typedef unsigned long long ULONGLONG;
typedef long long LONGLONG;
typedef struct {
    LONGLONG boot_time;
    LONGLONG current_time;
    LONGLONG time_zone_bias;
    ULONG time_zone_id;
    ULONG reserved;
    ULONGLONG boot_time_bias;
    ULONGLONG sleep_time_bias;
} WLS_SYSTEM_TIMEOFDAY_INFORMATION;
NTSTATUS NtQuerySystemInformation(
    int information_class,
    void *information,
    ULONG information_length,
    ULONG *return_length
);
CDEF,
                    'ntdll.dll',
                );
                $information = $ffi->new('WLS_SYSTEM_TIMEOFDAY_INFORMATION');
                $status = (int)$ffi->NtQuerySystemInformation(
                    3,
                    \FFI::addr($information),
                    \FFI::sizeof($information),
                    null,
                );
                $bootTime = (int)$information->boot_time;
            } catch (\Throwable $throwable) {
                throw new \RuntimeException(
                    'Windows native boot identity query failed.',
                    0,
                    $throwable,
                );
            }
            if ($status < 0 || $bootTime <= 0) {
                throw new \RuntimeException('Windows boot identity is unavailable.');
            }
            $platformToken = 'windows-' . \sprintf('%016x', $bootTime);
            return \hash(
                'sha256',
                'wls-gateway-host-boot/1|' . $platformToken,
            );
        }
        throw new \RuntimeException(
            'Unsupported platform for WLS Gateway boot identity: ' . \PHP_OS_FAMILY
        );
    }

    /**
     * @param list<string> $command
     */
    private function boundedCommandOutput(array $command, float $timeoutSeconds = 3.0): string
    {
        $this->reapDeferredBoundedProcesses();
        if (\count($this->deferredProcessReaps) >= self::MAX_DEFERRED_PROCESS_REAPS) {
            throw new \RuntimeException(
                'Platform identity probes are suspended while prior commands await reaping.'
            );
        }
        $process = @\proc_open($command, [
            0 => ['file', $this->nullDevice(), 'r'],
            1 => ['pipe', 'w'],
            2 => ['pipe', 'w'],
        ], $pipes, null, null, ['bypass_shell' => true]);
        if (!\is_resource($process)) {
            throw new \RuntimeException('Unable to start platform identity probe.');
        }
        \stream_set_blocking($pipes[1], false);
        \stream_set_blocking($pipes[2], false);
        $stdout = '';
        $stderr = '';
        $tooLarge = false;
        $timedOut = false;
        $deadline = $this->monotonicNow() + \max(0.1, $timeoutSeconds);
        $status = \proc_get_status($process);
        while (($status['running'] ?? false) && $this->monotonicNow() < $deadline) {
            $read = [$pipes[1], $pipes[2]];
            $write = null;
            $except = null;
            @\stream_select($read, $write, $except, 0, 100_000);
            foreach ($read as $stream) {
                $target = $stream === $pipes[1] ? $stdout : $stderr;
                $readBytes = $this->readProcessPipeChunk(
                    $stream,
                    $target,
                    self::MAX_PLATFORM_PROBE_OUTPUT_BYTES,
                );
                if ($stream === $pipes[1]) {
                    $stdout = $target;
                } else {
                    $stderr = $target;
                }
                if ($readBytes < 0) {
                    $tooLarge = true;
                    break 2;
                }
            }
            $status = \proc_get_status($process);
        }
        if (!\is_array($status)) {
            $this->terminateBoundedProcess($process, $pipes);
            throw new \RuntimeException(
                'Platform identity probe process state is indeterminate.'
            );
        }
        if (($status['running'] ?? false) && !$tooLarge) {
            $timedOut = true;
        }
        if ($timedOut || $tooLarge) {
            // Close inherited output handles before signalling. Otherwise a
            // TERM-ignoring child or surviving grandchild can keep a pipe
            // open and turn proc_close() into an unbounded controller stall.
            $this->terminateBoundedProcess($process, $pipes);
            throw new \RuntimeException($tooLarge
                ? 'Platform identity probe exceeded its output limit.'
                : 'Platform identity probe exceeded its hard deadline.');
        }
        foreach ([1, 2] as $pipeIndex) {
            while (!$tooLarge && !\feof($pipes[$pipeIndex])) {
                $target = $pipeIndex === 1 ? $stdout : $stderr;
                $readBytes = $this->readProcessPipeChunk(
                    $pipes[$pipeIndex],
                    $target,
                    self::MAX_PLATFORM_PROBE_OUTPUT_BYTES,
                );
                if ($pipeIndex === 1) {
                    $stdout = $target;
                } else {
                    $stderr = $target;
                }
                if ($readBytes < 0) {
                    $tooLarge = true;
                    break;
                }
                if ($readBytes === 0) {
                    break;
                }
            }
        }
        if ($tooLarge) {
            $this->terminateBoundedProcess($process, $pipes);
            throw new \RuntimeException(
                'Platform identity probe exceeded its output limit.'
            );
        }
        $this->closeBoundedProcessPipes($pipes);
        $exitCode = @\proc_close($process);
        if ($exitCode !== 0 && (int)($status['exitcode'] ?? -1) !== 0
        ) {
            throw new \RuntimeException(
                'Platform identity probe failed: '
                    . ($this->sanitizeCommandDiagnostic($stderr)
                        ?: 'no bounded diagnostic was returned')
            );
        }
        return \trim($stdout);
    }

    /**
     * @param resource $stream
     * @return int -1 when the limit was exceeded, otherwise bytes appended
     */
    private function readProcessPipeChunk($stream, string &$buffer, int $limit): int
    {
        $remaining = \max(0, $limit - \strlen($buffer));
        $chunk = @\stream_get_contents(
            $stream,
            \min(8192, $remaining + 1),
        );
        if (!\is_string($chunk) || $chunk === '') {
            return 0;
        }
        if (\strlen($chunk) > $remaining) {
            if ($remaining > 0) {
                $buffer .= \substr($chunk, 0, $remaining);
            }
            return -1;
        }
        $buffer .= $chunk;
        return \strlen($chunk);
    }

    /**
     * Stop a timed-out or output-flooding command without ever waiting
     * unboundedly in proc_close().
     *
     * @param resource $process
     * @param array<int,resource> $pipes
     */
    private function terminateBoundedProcess($process, array &$pipes): void
    {
        $this->closeBoundedProcessPipes($pipes);
        if (!\is_resource($process)) {
            return;
        }
        $status = @\proc_get_status($process);
        if (!\is_array($status)) {
            $this->deferredProcessReaps[\get_resource_id($process)] = $process;
            return;
        }
        if (!($status['running'] ?? false)) {
            @\proc_close($process);
            return;
        }

        $cleanupDeadline = $this->monotonicNow()
            + self::COMMAND_TERMINATION_GRACE_SECONDS;
        $termDeadline = \min(
            $cleanupDeadline,
            $this->monotonicNow()
                + (self::COMMAND_TERMINATION_GRACE_SECONDS / 4.0),
        );
        @\proc_terminate($process);
        while ($this->monotonicNow() < $termDeadline) {
            \usleep(10_000);
            $status = @\proc_get_status($process);
            if (\is_array($status) && !($status['running'] ?? false)) {
                @\proc_close($process);
                return;
            }
        }

        // Signal 9 maps to SIGKILL on POSIX; proc_terminate is already a
        // forceful TerminateProcess operation on Windows. Polling remains
        // bounded on both platforms.
        @\proc_terminate($process, 9);
        while ($this->monotonicNow() < $cleanupDeadline) {
            \usleep(10_000);
            $status = @\proc_get_status($process);
            if (\is_array($status) && !($status['running'] ?? false)) {
                @\proc_close($process);
                return;
            }
        }

        // An uninterruptible process must not make this recovery controller
        // wait forever. Keep its handle alive and retry only after a later
        // non-blocking status check reports exit; new command fan-out is
        // capped so this exceptional path cannot leak without bound.
        $this->deferredProcessReaps[\get_resource_id($process)] = $process;
    }

    /** @param array<int,resource> $pipes */
    private function closeBoundedProcessPipes(array &$pipes): void
    {
        foreach ($pipes as $index => $pipe) {
            if (\is_resource($pipe)) {
                @\fclose($pipe);
            }
            unset($pipes[$index]);
        }
    }

    private function reapDeferredBoundedProcesses(): void
    {
        foreach ($this->deferredProcessReaps as $resourceId => $process) {
            if (!\is_resource($process)) {
                unset($this->deferredProcessReaps[$resourceId]);
                continue;
            }
            $status = @\proc_get_status($process);
            if (!\is_array($status) || ($status['running'] ?? false)) {
                continue;
            }
            @\proc_close($process);
            unset($this->deferredProcessReaps[$resourceId]);
        }
    }

    private function sanitizeCommandDiagnostic(
        string $diagnostic,
        int $maximumBytes = 2048,
    ): string
    {
        $diagnostic = (string)\preg_replace(
            '/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/D',
            '',
            $diagnostic,
        );
        $diagnostic = \trim($diagnostic);
        return $diagnostic === ''
            ? ''
            : \substr($diagnostic, 0, \max(1, $maximumBytes));
    }

    /**
     * @param array<string,mixed> $instance
     */
    private function sameLeaseBoot(array $instance): bool
    {
        $bootId = (string)($instance['lease_boot_id'] ?? '');
        return $bootId !== '' && \hash_equals($this->hostBootId, $bootId);
    }

    /**
     * @param array<string,mixed> $route
     */
    private function routeStaleDuration(array $route, float $monotonicNow): float
    {
        $bootId = (string)($route['stale_boot_id'] ?? '');
        $started = (float)($route['stale_since_monotonic'] ?? 0.0);
        if ($bootId === ''
            || !\hash_equals($this->hostBootId, $bootId)
            || $started <= 0.0
            || $started > $monotonicNow
        ) {
            return 0.0;
        }
        return $monotonicNow - $started;
    }

    private function pruneNonces(): void
    {
        $now = $this->monotonicNow();
        $this->nonces = \array_filter(
            $this->nonces,
            function (array $record) use ($now): bool {
                if (!\hash_equals(
                    $this->hostBootId,
                    (string)($record['boot_id'] ?? ''),
                )) {
                    // Across a reboot the monotonic origin changes. Retain the
                    // bounded record conservatively so a wall-clock rollback
                    // cannot revive a recently signed request.
                    return true;
                }
                $age = $now - (float)($record['seen_monotonic'] ?? 0.0);
                return $age < 0.0 || $age <= 120.0;
            },
        );
        if (\count($this->nonces) > 2048) {
            $this->nonces = \array_slice($this->nonces, -2048, null, true);
        }
        $this->state['security']['nonces'] = $this->nonces;
    }

    /**
     * @return array<string,array{seen_at:int,seen_monotonic:float,boot_id:string}>
     */
    private function normalizePersistedNonces(mixed $persisted): array
    {
        if (!\is_array($persisted)) {
            return [];
        }
        $normalized = [];
        foreach ($persisted as $nonce => $record) {
            if (!\is_string($nonce)
                || \preg_match('/\A[a-f0-9]{32}\z/D', $nonce) !== 1
            ) {
                continue;
            }
            if (\is_int($record)) {
                $normalized[$nonce] = [
                    'seen_at' => $record,
                    'seen_monotonic' => 0.0,
                    'boot_id' => 'legacy',
                ];
                continue;
            }
            if (!\is_array($record)
                || !\is_int($record['seen_at'] ?? null)
                || (!\is_int($record['seen_monotonic'] ?? null)
                    && !\is_float($record['seen_monotonic'] ?? null))
                || !\is_string($record['boot_id'] ?? null)
                || (string)$record['boot_id'] === ''
            ) {
                continue;
            }
            $normalized[$nonce] = [
                'seen_at' => (int)$record['seen_at'],
                'seen_monotonic' => (float)$record['seen_monotonic'],
                'boot_id' => (string)$record['boot_id'],
            ];
        }
        return $normalized;
    }

    private function loadNonceWal(): void
    {
        $file = $this->nonceWalFile();
        if (!\file_exists($file) && !\is_link($file)) {
            return;
        }
        try {
            $raw = $this->readStableRegularFile(
                $file,
                self::NONCE_WAL_MAX_BYTES,
                'Gateway authentication nonce WAL',
                true,
            );
        } catch (\Throwable) {
            $this->journalTrusted = false;
            $this->state['health_state'] = 'NONCE_WAL_UNTRUSTED';
            return;
        }
        foreach (\explode("\n", $raw) as $line) {
            if ($line === '') {
                continue;
            }
            $decoded = \json_decode($line, true);
            $payload = \is_array($decoded['payload'] ?? null)
                ? $decoded['payload']
                : null;
            $nonce = \is_array($payload)
                ? \strtolower((string)($payload['nonce'] ?? ''))
                : '';
            if (!\is_array($payload)
                || \preg_match('/\A[a-f0-9]{32}\z/D', $nonce) !== 1
                || !\hash_equals(
                    (string)($decoded['sha256'] ?? ''),
                    \hash('sha256', $this->canonicalJson($payload)),
                )
            ) {
                $this->journalTrusted = false;
                $this->state['health_state'] = 'NONCE_WAL_UNTRUSTED';
                return;
            }
            $normalized = $this->normalizePersistedNonces([
                $nonce => [
                    'seen_at' => (int)($payload['seen_at'] ?? 0),
                    'seen_monotonic' => (float)($payload['seen_monotonic'] ?? 0.0),
                    'boot_id' => (string)($payload['boot_id'] ?? ''),
                ],
            ]);
            if (isset($normalized[$nonce])) {
                $this->nonces[$nonce] = $normalized[$nonce];
            }
        }
        $this->state['security']['nonces'] = $this->nonces;
    }

    /** @param array{seen_at:int,seen_monotonic:float,boot_id:string} $record */
    private function appendNonceWal(string $nonce, array $record): void
    {
        if ($this->readOnlyRecoveryMode) {
            throw new \RuntimeException('Nonce WAL is read-only during disk-pressure recovery.');
        }
        $file = $this->nonceWalFile();
        $size = $this->stableRegularFileSize(
            $file,
            self::NONCE_WAL_MAX_BYTES,
            'Gateway authentication nonce WAL',
        ) ?? 0;
        if ($size >= self::NONCE_WAL_MAX_BYTES) {
            throw new \RuntimeException('Gateway authentication nonce WAL quota is exhausted.');
        }
        $payload = [
            'schema_version' => 1,
            'nonce' => $nonce,
            'seen_at' => (int)$record['seen_at'],
            'seen_monotonic' => (float)$record['seen_monotonic'],
            'boot_id' => (string)$record['boot_id'],
        ];
        $line = (string)\json_encode([
            'payload' => $payload,
            'sha256' => \hash('sha256', $this->canonicalJson($payload)),
        ], JSON_UNESCAPED_SLASHES | JSON_PRESERVE_ZERO_FRACTION) . "\n";
        if ($size + \strlen($line) > self::NONCE_WAL_MAX_BYTES) {
            throw new \RuntimeException('Gateway authentication nonce WAL quota is exhausted.');
        }
        $existing = @\lstat($file);
        $handle = \is_array($existing)
            ? (!\is_link($file) ? @\fopen($file, 'ab') : false)
            : ((!\file_exists($file) && !\is_link($file)) ? @\fopen($file, 'xb') : false);
        if (!\is_resource($handle)) {
            throw new \RuntimeException('Gateway authentication nonce WAL cannot be opened.');
        }
        try {
            if (\PHP_OS_FAMILY !== 'Windows'
                && !(\function_exists('fchmod') ? @\fchmod($handle, 0600) : @\chmod($file, 0600))
            ) {
                throw new \RuntimeException('Gateway authentication nonce WAL mode is unsafe.');
            }
            if (!$this->writeStreamAll($handle, $line)
                || !@\fflush($handle)
                || (\function_exists('fsync') && !@\fsync($handle))
            ) {
                throw new \RuntimeException('Gateway authentication nonce WAL append failed.');
            }
        } finally {
            @\fclose($handle);
        }
    }

    private function canonicalJson(mixed $value): string
    {
        $normalize = static function (mixed $item) use (&$normalize): mixed {
            if (!\is_array($item)) {
                return $item;
            }
            if (!\array_is_list($item)) {
                \ksort($item, SORT_STRING);
            }
            foreach ($item as $key => $child) {
                $item[$key] = $normalize($child);
            }
            return $item;
        };
        return (string)\json_encode(
            $normalize($value),
            JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_PRESERVE_ZERO_FRACTION,
        );
    }

    /**
     * @return array<string,mixed>
     */
    private function loadState(bool $allowRepair = true): array
    {
        $defaults = $this->defaultState();
        $securityLedger = $this->loadSecurityLedger($allowRepair);
        $stateFile = $this->stateFile();
        $stateStatus = @\lstat($stateFile);
        if (!\is_array($stateStatus)
            && !\file_exists($stateFile)
            && !\is_link($stateFile)
        ) {
            $state = $this->applySecurityLedger($defaults, $securityLedger);
            if ($this->freshInstallBootstrapAllowed) {
                return $state;
            }
            $state['routes'] = $this->recoverableLkgRoutes();
            $state['isolation_mode'] = true;
            $state['health_state'] = 'STATE_MISSING';
            $state['epoch'] = $this->newEpoch();
            $state['_state_rebuild_required'] = true;
            return $this->sanitizeIsolationState($state);
        }
        try {
            $raw = $this->readStableRegularFile(
                $stateFile,
                64 * 1024 * 1024,
                'Gateway state snapshot',
            );
        } catch (\Throwable) {
            $raw = null;
        }
        $envelope = \is_string($raw) ? \json_decode($raw, true) : null;
        $payload = \is_array($envelope) && \is_array($envelope['payload'] ?? null)
            ? $envelope['payload']
            : null;
        $hash = \is_array($envelope) ? (string)($envelope['sha256'] ?? '') : '';
        if (!\is_array($payload)
            || !\preg_match('/^[a-f0-9]{64}$/D', $hash)
            || !\hash_equals($hash, \hash('sha256', $this->canonicalJson($payload)))
        ) {
            if ($allowRepair) {
                $this->quarantineStableRegularFile($this->stateFile(), 'corrupt');
            }
            $defaults['routes'] = $this->recoverableLkgRoutes();
            $defaults['isolation_mode'] = true;
            $defaults['health_state'] = 'STATE_REBUILD';
            $defaults['epoch'] = $this->newEpoch();
            $defaults['_state_rebuild_required'] = true;
            return $this->sanitizeIsolationState(
                $this->applySecurityLedger($defaults, $securityLedger),
            );
        }
        $state = \array_replace_recursive($defaults, $payload);
        $state = $this->applySecurityLedger($state, $securityLedger);
        // Nonces are retained across controller restarts so a replay cannot
        // bypass the in-memory window by crashing the control plane.
        $state['controller_started_at'] = \time();
        return $state;
    }

    private function enforceLoadedInstanceRetirementFloors(): void
    {
        foreach ((array)($this->state['instance_retirements'] ?? [])
            as $projectUuid => $retirements
        ) {
            foreach ((array)$retirements as $instanceId => $retirement) {
                if (!\is_array($retirement)) {
                    continue;
                }
                $floor = (int)($retirement['instance_generation'] ?? 0);
                $instance = $this->state['instances'][(string)$projectUuid][(string)$instanceId]
                    ?? null;
                $violatesState = \is_array($instance)
                    && (int)($instance['generation'] ?? 0) <= $floor;
                $violatesRoute = false;
                foreach ((array)($this->state['routes'] ?? []) as $route) {
                    $routeInstance = \is_array($route)
                        ? ($route['instances'][(string)$instanceId] ?? null)
                        : null;
                    if (\is_array($route)
                        && \hash_equals(
                            (string)$projectUuid,
                            (string)($route['project_uuid'] ?? ''),
                        )
                        && \is_array($routeInstance)
                        && (int)($routeInstance['generation'] ?? 0) <= $floor
                    ) {
                        $violatesRoute = true;
                        break;
                    }
                }
                if (!$violatesState && !$violatesRoute) {
                    continue;
                }
                // A crash may leave an older ordinary state snapshot beside a
                // newer host security ledger. Never adopt that LKG/backend
                // closure: isolate every runtime lease and require each
                // project to replay a strictly newer full registration.
                $this->state = $this->sanitizeIsolationState($this->state);
                $this->state['health_state'] = 'INSTANCE_RETIREMENT_REBUILD';
                $this->state['_state_rebuild_required'] = true;
                return;
            }
        }
    }

    /**
     * @return array<string,mixed>
     */
    private function defaultState(): array
    {
        $manifest = $this->slotManifestFromActiveFile();
        $activeSlot = \in_array((string)($manifest['slot'] ?? ''), ['A', 'B'], true)
            ? (string)$manifest['slot']
            : 'A';
        $capabilities = $this->probeBinaryCapabilities($this->slotDir($activeSlot)
            . DIRECTORY_SEPARATOR . 'bin' . DIRECTORY_SEPARATOR . $this->nginxBinaryName());
        return [
            'protocol' => self::PROTOCOL,
            'epoch' => $this->newEpoch(),
            'generation' => 1,
            'active_config_generation' => 0,
            'controller_started_at' => \time(),
            'public_http' => $this->environmentPort('WLS_GATEWAY_LISTEN_HTTP', 80),
            'public_https' => $this->environmentPort('WLS_GATEWAY_LISTEN_HTTPS', 443),
            'health_port' => $this->environmentPort('WLS_GATEWAY_HEALTH_PORT', 27643),
            'active_slot' => $activeSlot,
            'previous_slot' => $activeSlot === 'A' ? 'B' : 'A',
            'binary_healthy_since' => 0,
            'binary_healthy_since_monotonic' => 0.0,
            'binary_upgrade_started_at' => 0,
            'binary_upgrade_started_at_monotonic' => 0.0,
            'binary_observation_boot_id' => '',
            'binary_transaction' => [
                'phase' => 'COMMITTED',
                'from_slot' => $activeSlot,
                'to_slot' => $activeSlot,
                'started_at' => 0,
                'started_at_monotonic' => 0.0,
                'healthy_since' => 0,
                'healthy_since_monotonic' => 0.0,
                'observation_boot_id' => '',
                'committed_at' => 0,
                'retained_since_at' => 0,
                'retained_since_monotonic' => 0.0,
                'retain_previous_until' => 0,
                'retain_previous_until_monotonic' => 0.0,
                'retention_boot_id' => '',
            ],
            'h3_capable' => (bool)($capabilities['h3'] ?? false),
            'h3_enabled' => false,
            'h3_reason' => (string)($capabilities['reason'] ?? ''),
            'ready' => false,
            'supervisor_ready' => $this->supervisorReady(),
            'health_state' => 'STARTING',
            'isolation_mode' => false,
            'projects' => [],
            'instances' => [],
            'routes' => [],
            'operations' => [],
            'acme_challenges' => [],
            'acme_generations' => [],
            'transfers' => [],
            'enrollments' => [],
            'enrollment_transactions' => [],
            'rotation_transactions' => [],
            'security_transactions' => [],
            'security_sealed_transactions' => [],
            'domain_ownership' => [],
            'certificate_floors' => [],
            'security_retirements' => [],
            'instance_retirements' => [],
            'security_ledger_valid' => true,
            'security_generation_high_water' => 0,
            'security_committed_high_water' => 0,
            'native_security_ledger_digest' => \str_repeat('0', 64),
            'native_security_anchor_digest' => \str_repeat('0', 64),
            'native_security_attested' => false,
            'security' => [
                'nonces' => [],
                'tombstones' => [],
            ],
            'lkg' => $this->discoverLkgEntries(),
            'active_routes' => [],
            'active_config_digest' => '',
            'pending_lkg_generation' => 0,
            'pending_lkg_since' => 0,
            'pending_lkg_since_monotonic' => 0.0,
            'pending_lkg_boot_id' => '',
            'pending_lkg_config_digest' => '',
            'pending_lkg_routes_digest' => '',
            'lkg_rollback_hold_generation' => 0,
            'lkg_rollback_hold_since' => 0,
            'lkg_rollback_hold_desired_digest' => '',
            'snapshot_gc_candidates' => [],
            'failure_events' => [],
            'recovery' => [
                'stage' => 'NONE',
                'consecutive_failures' => 0,
                'last_failure' => '',
                'backoff_attempt' => 0,
                'circuit_open_until' => 0,
                'circuit_open_until_monotonic' => 0.0,
                'circuit_boot_id' => '',
                'next_retry_at' => 0,
                'cleanup_failure_count' => 0,
                'last_cleanup_failure' => '',
                'last_cleanup_failure_at' => 0,
            ],
        ];
    }

    /**
     * Recovery state deliberately retains only durable routing facts. Runtime
     * backend capabilities are fenced by the new gateway epoch and must be
     * submitted again before isolation can be lifted.
     *
     * @param array<string,mixed> $state
     * @return array<string,mixed>
     */
    private function sanitizeIsolationState(array $state): array
    {
        $state['instances'] = [];
        $state['acme_challenges'] = [];
        $state['transfers'] = [];
        foreach ((array)($state['routes'] ?? []) as $routeId => $route) {
            if (!\is_array($route)
                || !$this->routeAllowedBySecurityState($route, $state)
                || (string)($route['status'] ?? '') === 'REMOVED'
            ) {
                unset($state['routes'][$routeId]);
                continue;
            }
            try {
                $projectUuid = \strtolower(\trim((string)($route['project_uuid'] ?? '')));
                $domain = $this->normalizeDomain((string)($route['domain'] ?? ''));
            } catch (\Throwable) {
                unset($state['routes'][$routeId]);
                continue;
            }
            $canonicalRouteId = $this->canonicalRouteId($projectUuid, $domain);
            if (!\hash_equals($canonicalRouteId, (string)$routeId)
                || !\hash_equals($canonicalRouteId, (string)($route['route_id'] ?? ''))
            ) {
                unset($state['routes'][$routeId]);
                continue;
            }
            $certificate = \is_array($route['certificate'] ?? null)
                ? $route['certificate']
                : [];
            if (!$this->certificateSnapshotValidForDomain($certificate, $domain)) {
                $certificate['valid'] = false;
                $certificate['snapshot_digest'] = '';
                $certificate['cert_path'] = '';
                $certificate['key_path'] = '';
            }
            $state['routes'][$routeId] = [
                'route_id' => (string)($route['route_id'] ?? $routeId),
                'project_uuid' => $projectUuid,
                'project_root' => (string)($route['project_root'] ?? ''),
                'enrollment_security_generation' => (int)(
                    $route['enrollment_security_generation'] ?? 0
                ),
                'instance_id' => '',
                'domain' => $domain,
                'backends' => [],
                'backend_instances' => [],
                'backend_identity' => [],
                'instances' => [],
                'certificate' => $certificate,
                'route_generation' => \max(1, (int)($route['route_generation'] ?? 0)),
                'domain_security_generation' => (int)(
                    $route['domain_security_generation'] ?? 0
                ),
                'status' => 'STALE',
                'last_heartbeat' => 0,
                'last_backend_probe' => 0,
                'stale_since' => \time(),
                'stale_since_monotonic' => $this->monotonicNow(),
                'stale_boot_id' => $this->hostBootId,
                'drain_until' => null,
                'force_https' => (bool)($route['force_https'] ?? true),
                'force_root_to_www' => (bool)(
                    $route['force_root_to_www'] ?? false
                ),
                'recovery_required' => true,
                'updated_at' => \gmdate(DATE_ATOM),
            ];
        }
        $state['isolation_mode'] = true;
        $state['ready'] = false;
        $state['active_routes'] = [];
        $state['active_config_digest'] = '';
        $state['pending_lkg_generation'] = 0;
        $state['pending_lkg_since'] = 0;
        $state['pending_lkg_since_monotonic'] = 0.0;
        $state['pending_lkg_boot_id'] = '';
        $state['pending_lkg_config_digest'] = '';
        $state['pending_lkg_routes_digest'] = '';
        return $state;
    }

    /** @return array<string,array<string,mixed>> */
    private function recoverableLkgRoutes(): array
    {
        $routes = $this->loadRouteLkg();
        if ($routes !== []) {
            return $routes;
        }
        foreach ($this->discoverLkgEntries() as $entry) {
            $bundle = $this->loadLkgBundle($entry);
            if ($bundle !== null) {
                return (array)$bundle['routes'];
            }
        }
        return [];
    }

    /** @return list<array<string,mixed>> */
    private function discoverLkgEntries(): array
    {
        $entries = [];
        try {
            $leaves = $this->boundedDirectoryEntries(
                $this->lkgDir(),
                self::MAX_HOST_DIRECTORY_ENTRIES,
                'Gateway LKG root',
            );
        } catch (\Throwable) {
            return [];
        }
        foreach ($leaves as $leaf) {
            if (\preg_match(
                '/\Ageneration-([1-9][0-9]*)-([a-f0-9]{16})\z/D',
                (string)$leaf,
                $matches,
            ) !== 1) {
                continue;
            }
            $bundle = $this->lkgDir() . DIRECTORY_SEPARATOR . $leaf;
            $entry = [
                'generation' => (int)$matches[1],
                'bundle_dir' => $bundle,
                'manifest_file' => $bundle . DIRECTORY_SEPARATOR . 'manifest.json',
                'file' => $bundle . DIRECTORY_SEPARATOR . 'nginx.conf',
                'route_file' => $bundle . DIRECTORY_SEPARATOR . 'routes.json',
            ];
            if ($this->loadLkgBundle($entry) !== null) {
                $entries[] = $entry;
            }
        }
        \usort(
            $entries,
            static fn (array $left, array $right): int =>
                (int)$right['generation'] <=> (int)$left['generation'],
        );
        return \array_slice($entries, 0, 2);
    }

    /** @param array<string,array<string,array<string,mixed>>> $retirements */
    private function validInstanceRetirements(array $retirements): bool
    {
        if (\count($retirements) > self::MAX_PROJECTS) {
            return false;
        }
        $total = 0;
        foreach ($retirements as $projectUuid => $instances) {
            if (!\is_string($projectUuid)
                || !$this->validProjectUuid($projectUuid)
                || !\is_array($instances)
                || \count($instances) > self::MAX_RETIRED_INSTANCES_PER_PROJECT
            ) {
                return false;
            }
            $total += \count($instances);
            if ($total > self::MAX_TOTAL_RETIRED_INSTANCES) {
                return false;
            }
            foreach ($instances as $instanceId => $retirement) {
                if (!\is_string($instanceId)
                    || \preg_match(
                        '/\A[a-zA-Z0-9][a-zA-Z0-9._-]{0,127}\z/D',
                        $instanceId,
                    ) !== 1
                    || !\is_array($retirement)
                    || !$this->validInstanceRetirementEntry(
                        $retirement,
                        $projectUuid,
                        $instanceId,
                    )
                ) {
                    return false;
                }
            }
        }
        return true;
    }

    /** @param array<string,array<string,mixed>> $floors */
    private function validCertificateFloors(array $floors): bool
    {
        foreach ($floors as $key => $floor) {
            if (!\is_string($key) || !\is_array($floor)) {
                return false;
            }
            $projectUuid = (string)($floor['project_uuid'] ?? '');
            $domain = (string)($floor['domain'] ?? '');
            try {
                $normalizedDomain = $this->normalizeDomain($domain);
            } catch (\Throwable) {
                return false;
            }
            $generation = (int)($floor['generation'] ?? 0);
            $revocationGeneration = (int)($floor['revocation_generation'] ?? 0);
            $revocationDigest = (string)($floor['revocation_source_digest'] ?? '');
            if ((int)($floor['schema_version'] ?? 0) !== 1
                || !$this->validProjectUuid($projectUuid)
                || !\hash_equals($normalizedDomain, $domain)
                || !\hash_equals($this->certificateFloorKey($projectUuid, $domain), $key)
                || $generation < 1
                || \preg_match(
                    '/\A[a-f0-9]{64}\z/D',
                    (string)($floor['source_digest'] ?? ''),
                ) !== 1
                || (int)($floor['route_generation'] ?? 0) < 1
                || $revocationGeneration < 0
                || $revocationGeneration > $generation
                || ($revocationGeneration === 0 && $revocationDigest !== '')
                || ($revocationGeneration > 0
                    && (\preg_match('/\A[a-f0-9]{64}\z/D', $revocationDigest) !== 1
                        || !\hash_equals(
                            \hash(
                                'sha256',
                                "wls-disabled-certificate\0" . $domain . "\0"
                                    . $revocationGeneration,
                            ),
                            $revocationDigest,
                        )))
            ) {
                return false;
            }
        }
        return true;
    }

    /** @param array<string,mixed> $retirement */
    private function validInstanceRetirementEntry(
        array $retirement,
        string $projectUuid,
        string $instanceId,
    ): bool {
        $retiredAt = (string)($retirement['retired_at'] ?? '');
        $retiredAtValue = $retiredAt !== ''
            ? \DateTimeImmutable::createFromFormat(DATE_ATOM, $retiredAt)
            : false;
        $digest = (string)($retirement['retirement_digest'] ?? '');
        return (int)($retirement['schema_version'] ?? 0) === 1
            && \hash_equals($projectUuid, (string)($retirement['project_uuid'] ?? ''))
            && \hash_equals($instanceId, (string)($retirement['instance_id'] ?? ''))
            && (int)($retirement['instance_generation'] ?? 0) >= 1
            && (int)($retirement['master_epoch'] ?? 0) >= 1
            && \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($retirement['launch_id'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($retirement['instance_digest'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($retirement['gateway_epoch'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($retirement['host_boot_id'] ?? ''),
            ) === 1
            && \preg_match(
                '/\A[a-f0-9]{32}\z/D',
                (string)($retirement['transaction_id'] ?? ''),
            ) === 1
            && \is_int($retirement['retired_unix'] ?? null)
            && (int)$retirement['retired_unix'] >= 1
            && $retiredAtValue instanceof \DateTimeImmutable
            && $retiredAtValue->format(DATE_ATOM) === $retiredAt
            && \preg_match('/\A[a-f0-9]{64}\z/D', $digest) === 1
            && \hash_equals($digest, $this->instanceRetirementDigest($retirement));
    }

    /** @param array<string,mixed> $retirement */
    private function instanceRetirementDigest(array $retirement): string
    {
        unset($retirement['retirement_digest']);
        return \hash('sha256', $this->canonicalJson($retirement));
    }

    /**
     * @return array<string,mixed>
     */
    private function instanceRetirementFloor(
        string $projectUuid,
        string $instanceId,
    ): array {
        $floor = $this->state['instance_retirements'][$projectUuid][$instanceId] ?? null;
        $floor = \is_array($floor) ? $floor : [];
        foreach ((array)($this->publication['instance_retirement_candidates'] ?? [])
            as $candidate
        ) {
            if (!\is_array($candidate)
                || !\hash_equals(
                    $projectUuid,
                    (string)($candidate['project_uuid'] ?? ''),
                )
                || !\hash_equals(
                    $instanceId,
                    (string)($candidate['instance_id'] ?? ''),
                )
            ) {
                continue;
            }
            if (!$this->validInstanceRetirementEntry(
                $candidate,
                $projectUuid,
                $instanceId,
            )) {
                throw new \RuntimeException(
                    'Pending instance retirement candidate is malformed.'
                );
            }
            if ((int)($candidate['instance_generation'] ?? 0)
                > (int)($floor['instance_generation'] ?? 0)
            ) {
                $floor = $candidate;
            }
        }
        return $floor;
    }

    /** @return array<string,mixed> */
    private function assertInstanceRetirementFence(
        string $projectUuid,
        string $instanceId,
        int $instanceGeneration,
    ): array {
        $floor = $this->instanceRetirementFloor($projectUuid, $instanceId);
        if ($floor !== []
            && $instanceGeneration <= (int)($floor['instance_generation'] ?? 0)
        ) {
            throw new WlsEdgeProtocolException(
                'instance_generation_retired',
                'Instance generation was permanently retired; increment instance_generation '
                    . 'and submit a full registration.',
            );
        }
        return $floor;
    }

    /** @param array<string,mixed> $instance @return array<string,mixed> */
    private function stageInstanceRetirementCandidate(
        string $projectUuid,
        string $instanceId,
        array $instance,
    ): array {
        if ($this->publication === null) {
            throw new \RuntimeException(
                'Instance retirement requires an active publication transaction.'
            );
        }
        $transactionId = (string)($this->publication['transaction_id'] ?? '');
        $retirement = [
            'schema_version' => 1,
            'project_uuid' => $projectUuid,
            'instance_id' => $instanceId,
            'instance_generation' => (int)($instance['generation'] ?? 0),
            'instance_digest' => (string)($instance['digest'] ?? ''),
            'master_epoch' => (int)($instance['master_epoch'] ?? 0),
            'launch_id' => (string)($instance['launch_id'] ?? ''),
            'gateway_epoch' => (string)($this->state['epoch'] ?? ''),
            'host_boot_id' => $this->hostBootId,
            'transaction_id' => $transactionId,
            'retired_unix' => \time(),
            'retired_at' => \gmdate(DATE_ATOM),
        ];
        $retirement['retirement_digest'] = $this->instanceRetirementDigest($retirement);
        if (!$this->validInstanceRetirementEntry(
            $retirement,
            $projectUuid,
            $instanceId,
        )) {
            throw new \RuntimeException('Instance retirement candidate is malformed.');
        }

        $known = [];
        foreach ((array)($this->state['instance_retirements'] ?? [])
            as $knownProject => $knownInstances
        ) {
            foreach ((array)$knownInstances as $knownInstance => $_retirement) {
                $known[(string)$knownProject . "\0" . (string)$knownInstance] = true;
            }
        }
        foreach ((array)($this->publication['instance_retirement_candidates'] ?? [])
            as $candidate
        ) {
            if (\is_array($candidate)) {
                $known[(string)($candidate['project_uuid'] ?? '') . "\0"
                    . (string)($candidate['instance_id'] ?? '')] = true;
            }
        }
        $candidateKey = $projectUuid . "\0" . $instanceId;
        if (!isset($known[$candidateKey])) {
            $projectCount = 0;
            foreach (\array_keys($known) as $knownKey) {
                if (\str_starts_with($knownKey, $projectUuid . "\0")) {
                    ++$projectCount;
                }
            }
            if ($projectCount >= self::MAX_RETIRED_INSTANCES_PER_PROJECT
                || \count($known) >= self::MAX_TOTAL_RETIRED_INSTANCES
            ) {
                throw new WlsEdgeProtocolException(
                    'instance_retirement_quota_exceeded',
                    'The host instance-retirement ledger is full; administrator repair is required.',
                );
            }
        }
        $key = \hash('sha256', $candidateKey);
        $existing = $this->publication['instance_retirement_candidates'][$key] ?? null;
        if (\is_array($existing)
            && (int)($existing['instance_generation'] ?? 0)
                > (int)$retirement['instance_generation']
        ) {
            throw new \RuntimeException(
                'Instance retirement candidate attempted to move its floor backward.'
            );
        }
        $this->publication['instance_retirement_candidates'][$key] = $retirement;
        $this->persistPublication();
        return $retirement;
    }

    private function commitInstanceRetirementCandidates(): void
    {
        if ($this->publication === null) {
            return;
        }
        $candidates = (array)(
            $this->publication['instance_retirement_candidates'] ?? []
        );
        if ($candidates === []) {
            return;
        }
        \ksort($candidates, SORT_STRING);
        $advanced = [];
        foreach ($candidates as $candidate) {
            if (!\is_array($candidate)) {
                throw new \RuntimeException(
                    'Committed instance retirement candidate is malformed.'
                );
            }
            $projectUuid = (string)($candidate['project_uuid'] ?? '');
            $instanceId = (string)($candidate['instance_id'] ?? '');
            if (!$this->validInstanceRetirementEntry(
                $candidate,
                $projectUuid,
                $instanceId,
            )) {
                throw new \RuntimeException(
                    'Committed instance retirement candidate failed its digest fence.'
                );
            }
            $active = $this->state['instances'][$projectUuid][$instanceId] ?? null;
            if (\is_array($active)
                && (int)($active['generation'] ?? 0)
                    <= (int)$candidate['instance_generation']
            ) {
                throw new \RuntimeException(
                    'Committed retirement would leave a retired instance generation active.'
                );
            }
            $existing = $this->state['instance_retirements'][$projectUuid][$instanceId]
                ?? null;
            $existingGeneration = \is_array($existing)
                ? (int)($existing['instance_generation'] ?? 0)
                : 0;
            if ($existingGeneration === (int)$candidate['instance_generation']
                && \is_array($existing)
                && !\hash_equals(
                    (string)($existing['retirement_digest'] ?? ''),
                    (string)$candidate['retirement_digest'],
                )
            ) {
                throw new \RuntimeException(
                    'Equal instance retirement generations have different security digests.'
                );
            }
            if ((int)$candidate['instance_generation'] > $existingGeneration) {
                $this->state['instance_retirements'][$projectUuid][$instanceId]
                    = $candidate;
                $advanced[] = $candidate;
            }
        }
        if ($advanced === []) {
            return;
        }
        $this->markPublicationIrrevocableSecurity();
        $this->retainSecurityClosureAcrossRoutingRollback();
        $this->persistSecurityLedger();
        $this->persistState();
        foreach ($advanced as $retirement) {
            if (!$this->journal('instance_retired', [
                'project_uuid' => (string)$retirement['project_uuid'],
                'instance_id' => (string)$retirement['instance_id'],
                'instance_generation' => (int)$retirement['instance_generation'],
                'master_epoch' => (int)$retirement['master_epoch'],
                'launch_id' => (string)$retirement['launch_id'],
                'transaction_id' => (string)$retirement['transaction_id'],
                'retirement_digest' => (string)$retirement['retirement_digest'],
            ])) {
                // The monotonic floor and matching route removal are already
                // durable at this point. Throwing would enter the request-level
                // rollback path and could restore an instance at or below that
                // irreversible floor. Journal failure has already fenced later
                // mutations and published the disk-pressure marker; preserve
                // the safe state and let recovery repair the audit chain.
                $this->state['ready'] = false;
                $this->state['health_state'] = 'DISK_PRESSURE';
                $this->state['recovery']['stage'] = 'INSTANCE_RETIREMENT_AUDIT_PENDING';
                $this->state['recovery']['last_failure'] =
                    'instance_retirement_audit_append_failed';
                break;
            }
        }
    }

    /**
     * @param array<string,array<string,mixed>> $enrollments
     * @param array<string,array<string,mixed>> $tombstones
     */
    private function securityGenerationHighWater(array $enrollments, array $tombstones): int
    {
        $highWater = 0;
        foreach ($enrollments as $enrollment) {
            if (\is_array($enrollment)) {
                $highWater = \max(
                    $highWater,
                    (int)($enrollment['security_generation'] ?? 0),
                );
            }
        }
        foreach ($tombstones as $tombstone) {
            if (\is_array($tombstone)) {
                $highWater = \max($highWater, (int)($tombstone['generation'] ?? 0));
            }
        }
        return $highWater;
    }

    private function nextSecurityGeneration(): int
    {
        $transactionHighWater = 0;
        foreach ((array)($this->state['enrollment_transactions'] ?? []) as $transaction) {
            if (\is_array($transaction)) {
                $transactionHighWater = \max(
                    $transactionHighWater,
                    (int)($transaction['security_generation'] ?? 0),
                );
            }
        }
        $generation = \max(
            (int)($this->state['security_generation_high_water'] ?? 0),
            $this->securityGenerationHighWater(
                (array)($this->state['enrollments'] ?? []),
                (array)($this->state['security']['tombstones'] ?? []),
            ),
            $transactionHighWater,
        ) + 1;
        $this->state['security_generation_high_water'] = $generation;
        return $generation;
    }

    /**
     * @return array{status:string,payload?:array<string,mixed>}
     */
    private function loadSecurityLedger(bool $allowRepair = true): array
    {
        $file = $this->securityLedgerFile();
        $untrustedMarker = $file . '.untrusted';
        if (\is_file($untrustedMarker) || \is_link($untrustedMarker)) {
            return ['status' => 'invalid'];
        }
        if (!\file_exists($file) && !\is_link($file)) {
            return ['status' => 'missing'];
        }
        if (!\is_file($file) || \is_link($file)) {
            if ($allowRepair) {
                $this->atomicWrite($untrustedMarker, \gmdate(DATE_ATOM) . "\n", 0600);
            }
            return ['status' => 'invalid'];
        }
        try {
            $raw = $this->readStableRegularFile(
                $file,
                64 * 1024 * 1024,
                'Gateway security ledger',
            );
        } catch (\Throwable) {
            if ($allowRepair) {
                try {
                    $this->atomicWrite(
                        $untrustedMarker,
                        \gmdate(DATE_ATOM) . "\n",
                        0600,
                    );
                } catch (\Throwable) {
                }
            }
            return ['status' => 'invalid'];
        }
        $envelope = \json_decode($raw, true);
        $payload = \is_array($envelope) && \is_array($envelope['payload'] ?? null)
            ? $envelope['payload']
            : null;
        $hash = \is_array($envelope) ? (string)($envelope['sha256'] ?? '') : '';
        if (!\is_array($payload)
            || !\in_array((int)($payload['schema_version'] ?? 0), [5, 6], true)
            || !\is_array($payload['enrollments'] ?? null)
            || !\is_array($payload['tombstones'] ?? null)
            || !\is_array($payload['enrollment_transactions'] ?? null)
            || !\is_array($payload['rotation_transactions'] ?? null)
            || !\is_array($payload['security_transactions'] ?? null)
            || !\is_array($payload['domain_ownership'] ?? null)
            || !\is_array($payload['certificate_floors'] ?? null)
            || ((int)($payload['schema_version'] ?? 0) >= 6
                && !\is_array($payload['instance_retirements'] ?? null))
            || !\array_key_exists('allocated_high_water', $payload)
            || !\array_key_exists('committed_high_water', $payload)
            || !\is_int($payload['allocated_high_water'])
            || !\is_int($payload['committed_high_water'])
            || (int)$payload['allocated_high_water'] < 0
            || (int)$payload['committed_high_water'] < 0
            || (int)$payload['committed_high_water']
                > (int)$payload['allocated_high_water']
            || !\is_string($payload['native_security_ledger_digest'] ?? null)
            || !\is_string($payload['native_security_anchor_digest'] ?? null)
            || !\is_bool($payload['native_security_attested'] ?? null)
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($payload['native_security_ledger_digest'] ?? ''),
            ) !== 1
            || \preg_match(
                '/\A[a-f0-9]{64}\z/D',
                (string)($payload['native_security_anchor_digest'] ?? ''),
            ) !== 1
            || (((int)($payload['allocated_high_water'] ?? 0) > 0
                    || (array)($payload['enrollments'] ?? []) !== []
                    || (array)($payload['tombstones'] ?? []) !== []
                    || (array)($payload['enrollment_transactions'] ?? []) !== []
                    || (array)($payload['rotation_transactions'] ?? []) !== []
                    || (array)($payload['security_transactions'] ?? []) !== []
                    || (array)($payload['domain_ownership'] ?? []) !== []
                    || (array)($payload['certificate_floors'] ?? []) !== []
                    || (array)($payload['instance_retirements'] ?? []) !== [])
                && \hash_equals(
                    \str_repeat('0', 64),
                    (string)($payload['native_security_ledger_digest'] ?? ''),
                ))
            || (($payload['native_security_attested'] ?? null) === false
                && ((int)($payload['allocated_high_water'] ?? 0) !== 0
                    || (int)($payload['committed_high_water'] ?? 0) !== 0
                    || (array)($payload['enrollments'] ?? []) !== []
                    || (array)($payload['tombstones'] ?? []) !== []
                    || (array)($payload['enrollment_transactions'] ?? []) !== []
                    || (array)($payload['rotation_transactions'] ?? []) !== []
                    || (array)($payload['security_transactions'] ?? []) !== []
                    || (array)($payload['domain_ownership'] ?? []) !== []
                    || (array)($payload['certificate_floors'] ?? []) !== []
                    || (array)($payload['instance_retirements'] ?? []) !== []
                    || !\hash_equals(
                        \str_repeat('0', 64),
                        (string)($payload['native_security_ledger_digest'] ?? ''),
                    )
                    || !\hash_equals(
                        \str_repeat('0', 64),
                        (string)($payload['native_security_anchor_digest'] ?? ''),
                    )))
            || (($payload['native_security_attested'] ?? null) === true
                && \hash_equals(
                    \str_repeat('0', 64),
                    (string)($payload['native_security_ledger_digest'] ?? ''),
                ))
            || !\preg_match('/\A[a-f0-9]{64}\z/D', $hash)
            || !\hash_equals($hash, \hash('sha256', $this->canonicalJson($payload)))
            || !$this->validInstanceRetirements(
                (array)($payload['instance_retirements'] ?? []),
            )
            || !$this->validCertificateFloors(
                (array)($payload['certificate_floors'] ?? []),
            )
        ) {
            if ($allowRepair) {
                $this->quarantineStableRegularFile($file, 'corrupt');
                $this->atomicWrite($untrustedMarker, \gmdate(DATE_ATOM) . "\n", 0600);
            }
            return ['status' => 'invalid'];
        }
        return ['status' => 'valid', 'payload' => $payload];
    }

    /**
     * @param array<string,mixed> $state
     * @param array{status:string,payload?:array<string,mixed>} $ledger
     * @return array<string,mixed>
     */
    private function applySecurityLedger(array $state, array $ledger): array
    {
        $status = (string)($ledger['status'] ?? 'invalid');
        if ($status === 'missing') {
            if ($this->freshInstallBootstrapAllowed) {
                $state['security_ledger_valid'] = true;
                $state['_security_ledger_bootstrap'] = true;
                return $state;
            }
            $state['enrollments'] = [];
            $state['enrollment_transactions'] = [];
            $state['rotation_transactions'] = [];
            $state['security_transactions'] = [];
            $state['domain_ownership'] = [];
            $state['certificate_floors'] = [];
            $state['instance_retirements'] = [];
            $state['security']['tombstones'] = [];
            $state['security_ledger_valid'] = false;
            $state['isolation_mode'] = true;
            $state['health_state'] = 'SECURITY_LEDGER_MISSING';
            return $state;
        }
        if ($status !== 'valid') {
            $state['enrollments'] = [];
            $state['enrollment_transactions'] = [];
            $state['rotation_transactions'] = [];
            $state['security_transactions'] = [];
            $state['domain_ownership'] = [];
            $state['certificate_floors'] = [];
            $state['instance_retirements'] = [];
            $state['security']['tombstones'] = [];
            $state['security_ledger_valid'] = false;
            $state['isolation_mode'] = true;
            $state['health_state'] = 'SECURITY_LEDGER_UNTRUSTED';
            return $state;
        }
        $payload = (array)($ledger['payload'] ?? []);
        $state['enrollments'] = (array)($payload['enrollments'] ?? []);
        $state['security']['tombstones'] = (array)($payload['tombstones'] ?? []);
        $state['enrollment_transactions'] = (array)$payload['enrollment_transactions'];
        $state['rotation_transactions'] = (array)$payload['rotation_transactions'];
        $state['security_transactions'] = (array)$payload['security_transactions'];
        $state['domain_ownership'] = (array)$payload['domain_ownership'];
        $state['certificate_floors'] = (array)$payload['certificate_floors'];
        $state['instance_retirements'] = (array)(
            $payload['instance_retirements'] ?? []
        );
        $highWater = \max(
            0,
            (int)($payload['allocated_high_water']
                ?? $payload['generation_high_water']
                ?? 0),
            $this->securityGenerationHighWater(
                (array)$state['enrollments'],
                (array)$state['security']['tombstones'],
            ),
        );
        $committedHighWater = \max(
            0,
            (int)($payload['committed_high_water']
                ?? $payload['generation_high_water']
                ?? 0),
            $this->securityGenerationHighWater(
                (array)$state['enrollments'],
                (array)$state['security']['tombstones'],
            ),
        );
        if ($committedHighWater > $highWater) {
            $state['security_ledger_valid'] = false;
            $state['isolation_mode'] = true;
            $state['health_state'] = 'SECURITY_LEDGER_UNTRUSTED';
            return $state;
        }
        $state['security_generation_high_water'] = $highWater;
        $state['security_committed_high_water'] = $committedHighWater;
        $state['native_security_ledger_digest'] = (string)(
            $payload['native_security_ledger_digest'] ?? ''
        );
        $state['native_security_anchor_digest'] = (string)(
            $payload['native_security_anchor_digest'] ?? ''
        );
        $state['native_security_attested'] = (bool)(
            $payload['native_security_attested'] ?? false
        );
        $state['generation'] = \max((int)($state['generation'] ?? 1), $highWater);
        $state['security_ledger_valid'] = true;
        return $state;
    }

    private function persistSecurityLedger(): void
    {
        if (!$this->validCertificateFloors(
            (array)($this->state['certificate_floors'] ?? []),
        )) {
            throw new \RuntimeException(
                'Gateway certificate security floor ledger is malformed.'
            );
        }
        $derivedCommittedHighWater = $this->securityGenerationHighWater(
            (array)($this->state['enrollments'] ?? []),
            (array)($this->state['security']['tombstones'] ?? []),
        );
        $allocatedHighWater = \max(
            0,
            (int)($this->state['security_generation_high_water'] ?? 0),
            $derivedCommittedHighWater,
        );
        $committedHighWater = \max(
            0,
            (int)($this->state['security_committed_high_water'] ?? 0),
            $derivedCommittedHighWater,
        );
        if ($committedHighWater > $allocatedHighWater) {
            throw new \RuntimeException(
                'Gateway security committed generation exceeds its allocation high-water.'
            );
        }
        $this->state['security_generation_high_water'] = $allocatedHighWater;
        $this->state['security_committed_high_water'] = $committedHighWater;
        $zeroDigest = \str_repeat('0', 64);
        $nativeLedgerDigest = (string)(
            $this->state['native_security_ledger_digest'] ?? ''
        );
        $nativeAnchorDigest = (string)(
            $this->state['native_security_anchor_digest'] ?? ''
        );
        $nativeAttested = ($this->state['native_security_attested'] ?? false) === true;
        $freshSecurityState = $allocatedHighWater === 0
            && $committedHighWater === 0
            && (array)($this->state['enrollments'] ?? []) === []
            && (array)($this->state['security']['tombstones'] ?? []) === []
            && (array)($this->state['enrollment_transactions'] ?? []) === []
            && (array)($this->state['rotation_transactions'] ?? []) === []
            && (array)($this->state['security_transactions'] ?? []) === []
            && (array)($this->state['domain_ownership'] ?? []) === []
            && (array)($this->state['certificate_floors'] ?? []) === []
            && (array)($this->state['instance_retirements'] ?? []) === [];
        if ($freshSecurityState
            && (\preg_match('/\A[a-f0-9]{64}\z/D', $nativeLedgerDigest) !== 1
                || \preg_match('/\A[a-f0-9]{64}\z/D', $nativeAnchorDigest) !== 1)
        ) {
            $nativeLedgerDigest = $zeroDigest;
            $nativeAnchorDigest = $zeroDigest;
            $nativeAttested = false;
            $this->state['native_security_ledger_digest'] = $nativeLedgerDigest;
            $this->state['native_security_anchor_digest'] = $nativeAnchorDigest;
            $this->state['native_security_attested'] = false;
        }
        if (!$freshSecurityState && !$this->brokerActionsRequired()) {
            // Test slots have no Native Broker ledger. Preserve the same
            // schema contract with a deterministic synthetic attestation;
            // production can never enter this branch.
            $nativeLedgerDigest = \hash('sha256', $this->canonicalJson([
                'allocated' => $allocatedHighWater,
                'committed' => $committedHighWater,
                'enrollments' => (array)($this->state['enrollments'] ?? []),
                'tombstones' => (array)(
                    $this->state['security']['tombstones'] ?? []
                ),
                'enrollment_transactions' => (array)(
                    $this->state['enrollment_transactions'] ?? []
                ),
                'rotation_transactions' => (array)(
                    $this->state['rotation_transactions'] ?? []
                ),
                'security_transactions' => (array)(
                    $this->state['security_transactions'] ?? []
                ),
                'domain_ownership' => (array)(
                    $this->state['domain_ownership'] ?? []
                ),
                'certificate_floors' => (array)(
                    $this->state['certificate_floors'] ?? []
                ),
                'instance_retirements' => (array)(
                    $this->state['instance_retirements'] ?? []
                ),
            ]));
            $nativeAnchorDigest = \hash('sha256', $this->canonicalJson([
                'committed' => $committedHighWater,
                'enrollments' => (array)($this->state['enrollments'] ?? []),
                'tombstones' => (array)(
                    $this->state['security']['tombstones'] ?? []
                ),
                'domain_ownership' => (array)(
                    $this->state['domain_ownership'] ?? []
                ),
                'certificate_floors' => (array)(
                    $this->state['certificate_floors'] ?? []
                ),
                'instance_retirements' => (array)(
                    $this->state['instance_retirements'] ?? []
                ),
            ]));
            $this->state['native_security_ledger_digest'] = $nativeLedgerDigest;
            $this->state['native_security_anchor_digest'] = $nativeAnchorDigest;
            $this->state['native_security_attested'] = true;
            $nativeAttested = true;
        }
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $nativeLedgerDigest) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $nativeAnchorDigest) !== 1
            || (!$freshSecurityState && \hash_equals($zeroDigest, $nativeLedgerDigest))
            || (!$freshSecurityState && !$nativeAttested)
            || ($nativeAttested && \hash_equals($zeroDigest, $nativeLedgerDigest))
            || (!$nativeAttested
                && (!\hash_equals($zeroDigest, $nativeLedgerDigest)
                    || !\hash_equals($zeroDigest, $nativeAnchorDigest)))
        ) {
            throw new \RuntimeException(
                'Native Broker security digests are unavailable for durable ledger publication.'
            );
        }
        $payload = [
            'schema_version' => 6,
            'enrollments' => (array)($this->state['enrollments'] ?? []),
            'tombstones' => (array)($this->state['security']['tombstones'] ?? []),
            'enrollment_transactions' => (array)(
                $this->state['enrollment_transactions'] ?? []
            ),
            'security_transactions' => (array)(
                $this->state['security_transactions'] ?? []
            ),
            'rotation_transactions' => (array)(
                $this->state['rotation_transactions'] ?? []
            ),
            'domain_ownership' => (array)($this->state['domain_ownership'] ?? []),
            'certificate_floors' => (array)($this->state['certificate_floors'] ?? []),
            'instance_retirements' => (array)(
                $this->state['instance_retirements'] ?? []
            ),
            'generation_high_water' => $allocatedHighWater,
            'allocated_high_water' => $allocatedHighWater,
            'committed_high_water' => $committedHighWater,
            'native_security_ledger_digest' => $nativeLedgerDigest,
            'native_security_anchor_digest' => $nativeAnchorDigest,
            'native_security_attested' => $nativeAttested,
            'updated_at' => \gmdate(DATE_ATOM),
        ];
        $envelope = [
            'payload' => $payload,
            'sha256' => \hash('sha256', $this->canonicalJson($payload)),
        ];
        $encoded = \json_encode(
            $envelope,
            JSON_PRETTY_PRINT
                | JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION,
        );
        if (!\is_string($encoded)) {
            throw new \RuntimeException('Unable to encode the host security ledger.');
        }
        $this->assertWriterSize($encoded, self::MAX_STATE_BYTES, 'Gateway security ledger');
        $this->atomicWrite($this->securityLedgerFile(), $encoded, 0600);
        $this->persistSecurityAnchor(
            \hash('sha256', $encoded),
            $allocatedHighWater,
            $committedHighWater,
        );
        $marker = $this->securityLedgerFile() . '.untrusted';
        if (\file_exists($marker) || \is_link($marker)) {
            $this->removeStableRegularFile(
                $marker,
                'Gateway security-ledger distrust marker',
            );
        }
        $this->securityAnchorTrusted = true;
        if ($this->initializationMarkerTrusted
            && (\file_exists($this->initializationMarkerFile())
                || \is_link($this->initializationMarkerFile()))
        ) {
            $this->persistInitializationMarker();
        }
    }

    private function verifySecurityAnchor(): bool
    {
        $file = $this->securityAnchorFile();
        if (!\file_exists($file) && !\is_link($file)) {
            return $this->freshInstallBootstrapAllowed
                && !\file_exists($this->securityLedgerFile())
                && !\is_link($this->securityLedgerFile());
        }
        try {
            $decoded = \json_decode($this->readStableRegularFile(
                $file,
                65_536,
                'Gateway security rollback anchor',
            ), true);
        } catch (\Throwable) {
            return false;
        }
        $payload = \is_array($decoded['payload'] ?? null)
            ? $decoded['payload']
            : null;
        $ledgerDigest = $this->fileHash($this->securityLedgerFile());
        $allocatedHighWater = (int)(
            $this->state['security_generation_high_water'] ?? 0
        );
        $committedHighWater = (int)(
            $this->state['security_committed_high_water'] ?? $allocatedHighWater
        );
        $schemaVersion = (int)($payload['schema_version'] ?? 0);
        return \is_array($payload)
            && \in_array($schemaVersion, [1, 2], true)
            && \hash_equals(self::PROTOCOL, (string)($payload['protocol'] ?? ''))
            && \hash_equals($this->hostId(), (string)($payload['host_id'] ?? ''))
            && $allocatedHighWater >= 0
            && $committedHighWater >= 0
            && $committedHighWater <= $allocatedHighWater
            && $allocatedHighWater === (int)($payload['allocated_high_water']
                ?? $payload['generation_high_water']
                ?? -1)
            && $committedHighWater === (int)($payload['committed_high_water']
                ?? $payload['generation_high_water']
                ?? -1)
            && $ledgerDigest !== ''
            && \hash_equals($ledgerDigest, (string)($payload['ledger_sha256'] ?? ''))
            && \preg_match('/\A[a-f0-9]{64}\z/D', (string)($decoded['sha256'] ?? '')) === 1
            && \hash_equals(
                (string)$decoded['sha256'],
                \hash('sha256', $this->canonicalJson($payload)),
            );
    }

    private function persistSecurityAnchor(
        string $ledgerDigest,
        int $allocatedGeneration,
        int $committedGeneration,
    ): void
    {
        if ($this->readOnlyRecoveryMode
            || \preg_match('/\A[a-f0-9]{64}\z/D', $ledgerDigest) !== 1
            || $allocatedGeneration < 0
            || $committedGeneration < 0
            || $committedGeneration > $allocatedGeneration
        ) {
            throw new \RuntimeException(
                'Gateway security rollback anchor cannot be advanced safely.'
            );
        }
        $payload = [
            'schema_version' => 2,
            'protocol' => self::PROTOCOL,
            'host_id' => $this->hostId(),
            'generation_high_water' => $allocatedGeneration,
            'allocated_high_water' => $allocatedGeneration,
            'committed_high_water' => $committedGeneration,
            'ledger_sha256' => $ledgerDigest,
            'gateway_epoch' => (string)($this->state['epoch'] ?? ''),
            'committed_at' => \gmdate(DATE_ATOM),
        ];
        $encoded = (string)\json_encode([
            'payload' => $payload,
            'sha256' => \hash('sha256', $this->canonicalJson($payload)),
        ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
        $this->atomicWrite($this->securityAnchorFile(), $encoded, 0600);
    }

    private function attestBrokerSecurityRoot(string $operation): void
    {
        if (!$this->brokerActionsRequired()) {
            return;
        }
        $channel = (string)($this->activeBrokerPeer['channel'] ?? '');
        if (!\in_array($channel, ['admin', 'project'], true)
            || !$this->brokerActionsAvailable($channel)
        ) {
            throw new \DomainException(
                'Native Broker security-root attestation is unavailable for ' . $operation . '.'
            );
        }
        if ($this->fileHash($this->securityLedgerFile()) === ''
            || $this->fileHash($this->securityAnchorFile()) === ''
        ) {
            throw new \DomainException(
                'Gateway security-root files cannot be attested for ' . $operation . '.'
            );
        }
        $allocatedHighWater = (int)(
            $this->state['security_generation_high_water'] ?? 0
        );
        $committedHighWater = (int)(
            $this->state['security_committed_high_water'] ?? 0
        );
        if ($allocatedHighWater < 0
            || $committedHighWater < 0
            || $committedHighWater > $allocatedHighWater
        ) {
            throw new \DomainException(
                'Gateway security generation anchor is invalid for ' . $operation . '.'
            );
        }
        $nativeLedgerDigest = \strtolower(\trim((string)(
            $this->state['native_security_ledger_digest'] ?? ''
        )));
        $nativeAnchorDigest = \strtolower(\trim((string)(
            $this->state['native_security_anchor_digest'] ?? ''
        )));
        $pendingAuthorizationAllocation = false;
        $pendingUnobservedAuthorizations = 0;
        foreach ((array)($this->state['enrollment_transactions'] ?? []) as $transaction) {
            if (!\is_array($transaction)
                || !\in_array(
                    (string)($transaction['phase'] ?? ''),
                    ['PREPARED', 'ABORT_PENDING'],
                    true,
                )
            ) {
                continue;
            }
            $pendingGeneration = (int)($transaction['security_generation'] ?? 0);
            if ($pendingGeneration === 0) {
                ++$pendingUnobservedAuthorizations;
                $pendingAuthorizationAllocation = true;
            } elseif ($pendingGeneration > $committedHighWater
                && $pendingGeneration <= $allocatedHighWater
            ) {
                $pendingAuthorizationAllocation = true;
            }
        }
        foreach ((array)($this->state['rotation_transactions'] ?? []) as $transaction) {
            if (!\is_array($transaction)
                || !\in_array(
                    (string)($transaction['phase'] ?? ''),
                    ['PREPARED', 'NATIVE_PREPARED'],
                    true,
                )
            ) {
                continue;
            }
            $pendingGeneration = (int)($transaction['security_generation'] ?? 0);
            if ($pendingGeneration === 0) {
                ++$pendingUnobservedAuthorizations;
                $pendingAuthorizationAllocation = true;
            } elseif ($pendingGeneration > $committedHighWater
                && $pendingGeneration <= $allocatedHighWater
            ) {
                $pendingAuthorizationAllocation = true;
            }
        }
        foreach ((array)($this->state['security_transactions'] ?? []) as $transaction) {
            if (!\is_array($transaction)
                || !\in_array(
                    (string)($transaction['phase'] ?? ''),
                    ['PREPARED', 'RESERVED'],
                    true,
                )
            ) {
                continue;
            }
            $pendingGeneration = (int)(
                $transaction['assigned_generation'] ?? 0
            );
            if ($pendingGeneration === 0) {
                ++$pendingUnobservedAuthorizations;
                $pendingAuthorizationAllocation = true;
            } elseif ($pendingGeneration > $committedHighWater
                && $pendingGeneration <= $allocatedHighWater
            ) {
                $pendingAuthorizationAllocation = true;
            }
        }
        $freshNativeBootstrap = $allocatedHighWater === 0
            && $committedHighWater === 0
            && (array)($this->state['enrollments'] ?? []) === []
            && (array)($this->state['security']['tombstones'] ?? []) === []
            && (array)($this->state['enrollment_transactions'] ?? []) === []
            && (array)($this->state['rotation_transactions'] ?? []) === []
            && (array)($this->state['security_transactions'] ?? []) === []
            && (array)($this->state['domain_ownership'] ?? []) === []
            && (array)($this->state['certificate_floors'] ?? []) === []
            && (array)($this->state['instance_retirements'] ?? []) === [];
        $discoverNativeDigests = ($freshNativeBootstrap
                && ($this->state['native_security_attested'] ?? false) !== true)
            || $pendingAuthorizationAllocation;
        if (!$discoverNativeDigests
            && (\preg_match('/\A[a-f0-9]{64}\z/D', $nativeLedgerDigest) !== 1
                || \preg_match('/\A[a-f0-9]{64}\z/D', $nativeAnchorDigest) !== 1)
        ) {
            throw new \DomainException(
                'Native Broker security digest anchor is unavailable for ' . $operation . '.'
            );
        }
        $response = $this->brokerAction($channel, [
            'SECURITY_ATTEST',
            $this->hostId(),
            (string)$committedHighWater,
            $discoverNativeDigests ? '-' : $nativeLedgerDigest,
            $discoverNativeDigests ? '-' : $nativeAnchorDigest,
        ]);
        if (\count($response) !== 5
            || !\hash_equals($this->hostId(), (string)$response[0])
            || \preg_match('/\A[0-9]+\z/D', (string)$response[1]) !== 1
            || \preg_match('/\A[0-9]+\z/D', (string)$response[2]) !== 1
            || ($pendingUnobservedAuthorizations === 0
                && (int)$response[1] !== $allocatedHighWater)
            || ($pendingUnobservedAuthorizations > 0
                && ((int)$response[1] < $allocatedHighWater
                    || (int)$response[1]
                        > $allocatedHighWater + $pendingUnobservedAuthorizations))
            || (int)$response[2] !== $committedHighWater
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[3]) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', (string)$response[4]) !== 1
            || \hash_equals(\str_repeat('0', 64), (string)$response[3])
            || (!$discoverNativeDigests
                && (!\hash_equals($nativeLedgerDigest, (string)$response[3])
                    || !\hash_equals($nativeAnchorDigest, (string)$response[4])))
        ) {
            throw new \DomainException(
                'Native Broker security-root high-water does not match the durable ledger for '
                    . $operation . '.'
            );
        }
        if ($discoverNativeDigests) {
            $this->state['security_generation_high_water'] = (int)$response[1];
            $this->state['security_committed_high_water'] = (int)$response[2];
            $this->state['native_security_ledger_digest'] = (string)$response[3];
            $this->state['native_security_anchor_digest'] = (string)$response[4];
            $this->state['native_security_attested'] = true;
            // Replace the explicit fresh-install zero sentinel (and any
            // recovered pending-allocation digest) in both durable authority
            // files before the request performs its higher-level mutation.
            $this->persistSecurityLedger();
            $this->persistState();
        }
    }

    private function persistState(): void
    {
        $payload = $this->state;
        $envelope = [
            'payload' => $payload,
            'sha256' => \hash('sha256', $this->canonicalJson($payload)),
        ];
        $encoded = \json_encode(
            $envelope,
            JSON_PRETTY_PRINT
                | JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION,
        );
        if (!\is_string($encoded)) {
            throw new \RuntimeException('Unable to encode gateway state.');
        }
        $this->assertWriterSize($encoded, self::MAX_STATE_BYTES, 'Gateway state');
        $this->atomicWrite($this->stateFile(), $encoded, 0600);
        $this->leaseCheckpointDirty = false;
        $this->lastLeaseCheckpointAt = $this->monotonicNow();
    }

    /**
     * @param array<string,mixed> $context
     */
    private function bumpGeneration(string $event, array $context = []): void
    {
        $this->state['generation'] = (int)$this->state['generation'] + 1;
        $this->persistState();
        if (!$this->journal(
            $event,
            $context + ['generation' => (int)$this->state['generation']],
        )) {
            throw new \RuntimeException(
                'Gateway mutation was persisted but its durable audit record failed.'
            );
        }
    }

    /**
     * @param array<string,mixed> $context
     */
    private function journal(string $event, array $context = []): bool
    {
        $this->assertBrokerGenerationOwnership('journal append');
        $estimated = \json_encode(
            ['event' => $event, 'context' => $context],
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION,
        );
        if (!\is_string($estimated)
            || !$this->rotateJournalIfNeeded(\strlen($estimated) + 1024)
        ) {
            $this->markJournalWriteFailure('rotation_or_estimate_failed');
            return false;
        }
        $entry = [
            'schema_version' => 2,
            'sequence' => $this->journalSequence + 1,
            'previous_sha256' => $this->journalHead !== ''
                ? $this->journalHead
                : \str_repeat('0', 64),
            'at' => \gmdate(DATE_ATOM),
            'epoch' => (string)($this->state['epoch'] ?? ''),
            'event' => $event,
            'context' => $context,
        ];
        if ($this->journalSequence === 0
            && \is_array($this->state['journal_archive'] ?? null)
            && (int)($this->state['journal_archive']['schema_version'] ?? 0) === 1
        ) {
            $entry['previous_segment_head'] = (string)(
                $this->state['journal_archive']['head_sha256'] ?? ''
            );
            $entry['previous_segment_sequence'] = (int)(
                $this->state['journal_archive']['sequence'] ?? 0
            );
            $entry['previous_segment_file_sha256'] = (string)(
                $this->state['journal_archive']['sha256'] ?? ''
            );
        }
        $entry['sha256'] = \hash('sha256', $this->canonicalJson($entry));
        $encoded = \json_encode(
            $entry,
            JSON_UNESCAPED_SLASHES
                | JSON_UNESCAPED_UNICODE
                | JSON_PRESERVE_ZERO_FRACTION,
        );
        if (!\is_string($encoded)) {
            $this->markJournalWriteFailure('encode_failed');
            return false;
        }
        $journalFile = $this->journalFile();
        $pathStatus = @\lstat($journalFile);
        $created = !\is_array($pathStatus);
        if (\is_array($pathStatus)) {
            $safeExisting = !\is_link($journalFile)
                && ((((int)($pathStatus['mode'] ?? 0)) & 0170000) === 0100000)
                && (int)($pathStatus['nlink'] ?? 0) === 1
                && (int)($pathStatus['size'] ?? -1) >= 0
                && (int)($pathStatus['size'] ?? -1) <= self::MAX_JOURNAL_BYTES;
            $stream = $safeExisting ? @\fopen($journalFile, 'r+b') : false;
        } else {
            $safeMissing = !\file_exists($journalFile) && !\is_link($journalFile);
            $stream = $safeMissing ? @\fopen($journalFile, 'x+b') : false;
        }
        $openedStatus = \is_resource($stream) ? @\fstat($stream) : false;
        if (!\is_resource($stream)
            || !\is_array($openedStatus)
            || ((((int)($openedStatus['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($openedStatus['nlink'] ?? 0) !== 1
            || (\is_array($pathStatus)
                && !$this->sameStableFileState($pathStatus, $openedStatus))
            || !@\flock($stream, LOCK_EX)
        ) {
            if (\is_resource($stream)) {
                @\fclose($stream);
            }
            $this->markJournalWriteFailure('open_or_lock_failed');
            return false;
        }
        $pathAfterLock = @\lstat($journalFile);
        if (!\is_array($pathAfterLock)
            || !$this->sameStableFileState($openedStatus, $pathAfterLock)
        ) {
            @\flock($stream, LOCK_UN);
            @\fclose($stream);
            $this->markJournalWriteFailure('path_changed_while_locking');
            return false;
        }
        $line = $encoded . "\n";
        $written = false;
        try {
            if (\PHP_OS_FAMILY !== 'Windows'
                && !(\function_exists('fchmod') ? @\fchmod($stream, 0600) : @\chmod($journalFile, 0600))
            ) {
                throw new \RuntimeException('Unable to seal the gateway journal mode.');
            }
            $written = @\fseek($stream, 0, SEEK_END) === 0
                && $this->writeStreamAll($stream, $line)
                && @\fflush($stream)
                && (!\function_exists('fsync') || @\fsync($stream));
            if ($written) {
                $afterWrite = @\fstat($stream);
                $pathAfterWrite = @\lstat($journalFile);
                $written = \is_array($afterWrite)
                    && \is_array($pathAfterWrite)
                    && $this->sameStableFileState($afterWrite, $pathAfterWrite)
                    && (int)($afterWrite['size'] ?? -1) <= self::MAX_JOURNAL_BYTES
                    && (\PHP_OS_FAMILY === 'Windows'
                        || ((((int)($afterWrite['mode'] ?? 0)) & 0777) === 0600));
            }
        } catch (\Throwable) {
            $written = false;
        } finally {
            @\flock($stream, LOCK_UN);
            @\fclose($stream);
        }
        if ($written && $created) {
            try {
                $this->syncDirectory(\dirname($journalFile));
            } catch (\Throwable) {
                $written = false;
            }
        }
        if (!$written) {
            $this->markJournalWriteFailure('append_or_fsync_failed');
            return false;
        }
        $this->journalSequence = (int)$entry['sequence'];
        $this->journalHead = (string)$entry['sha256'];
        return true;
    }

    private function initializeJournalChain(bool $allowRepair = true): void
    {
        $this->journalTrusted = true;
        $this->journalHead = \str_repeat('0', 64);
        if (\file_exists($this->journalDistrustMarkerFile())
            || \is_link($this->journalDistrustMarkerFile())
        ) {
            $this->markJournalUntrustedInMemory('durable_journal_distrust_marker');
            return;
        }
        $file = $this->journalFile();
        if (!\file_exists($file) && !\is_link($file)) {
            if (!$this->freshInstallBootstrapAllowed) {
                $this->markJournalUntrustedInMemory('journal_missing');
            }
            return;
        }
        if (!\is_file($file) || \is_link($file)) {
            $this->rejectOrQuarantineJournal('unsafe_journal_path', $allowRepair);
            return;
        }
        try {
            $raw = $this->readStableRegularFile(
                $file,
                64 * 1024 * 1024,
                'Gateway journal',
                true,
            );
        } catch (\Throwable) {
            $this->rejectOrQuarantineJournal('journal_read_failed', $allowRepair);
            return;
        }
        if ($raw === '') {
            if (!$this->freshInstallBootstrapAllowed) {
                $this->rejectOrQuarantineJournal('journal_empty', $allowRepair);
            }
            return;
        }
        if (\strlen($raw) > 64 * 1024 * 1024) {
            $this->rejectOrQuarantineJournal('journal_quota_exceeded', $allowRepair);
            return;
        }
        $hasFinalNewline = \str_ends_with($raw, "\n");
        $lines = \explode("\n", $raw);
        if ($hasFinalNewline) {
            \array_pop($lines);
        }
        $sequence = 0;
        $head = \str_repeat('0', 64);
        $legacy = false;
        $tailTruncated = false;
        foreach ($lines as $index => $line) {
            if ($line === '') {
                $this->rejectOrQuarantineJournal('empty_middle_record', $allowRepair);
                return;
            }
            $entry = \json_decode($line, true);
                if (!\is_array($entry)) {
                if (!$hasFinalNewline && $index === \array_key_last($lines)) {
                    if (!$allowRepair) {
                        $this->markJournalUntrustedInMemory('truncated_tail');
                        return;
                    }
                    if ($sequence < 1
                        && !\is_file($this->journalFile() . '.1')
                    ) {
                        $this->rejectOrQuarantineJournal(
                            'unanchored_only_record_truncated',
                            $allowRepair,
                        );
                        return;
                    }
                    $this->truncateJournalTail($raw);
                    $tailTruncated = true;
                    break;
                }
                $this->rejectOrQuarantineJournal('invalid_middle_record', $allowRepair);
                return;
            }
            if ((int)($entry['schema_version'] ?? 0) !== 2) {
                $legacyDigest = (string)($entry['sha256'] ?? '');
                unset($entry['sha256']);
                if (\preg_match('/\A[a-f0-9]{64}\z/D', $legacyDigest) !== 1
                    || !\hash_equals(
                        $legacyDigest,
                        \hash('sha256', $this->canonicalJson($entry)),
                    )
                ) {
                    $this->rejectOrQuarantineJournal(
                        'legacy_record_digest_mismatch',
                        $allowRepair,
                    );
                    return;
                }
                $legacy = true;
                continue;
            }
            if ($index === 0 && !$this->verifyJournalSegmentAnchor($entry)) {
                $this->rejectOrQuarantineJournal(
                    'journal_segment_anchor_mismatch',
                    $allowRepair,
                );
                return;
            }
            if ($legacy
                || (int)($entry['sequence'] ?? 0) !== $sequence + 1
                || !\hash_equals($head, (string)($entry['previous_sha256'] ?? ''))
            ) {
                $this->rejectOrQuarantineJournal(
                    'sequence_or_previous_hash_mismatch',
                    $allowRepair,
                );
                return;
            }
            $digest = (string)($entry['sha256'] ?? '');
            unset($entry['sha256']);
            if (\preg_match('/\A[a-f0-9]{64}\z/D', $digest) !== 1
                || !\hash_equals($digest, \hash('sha256', $this->canonicalJson($entry)))
            ) {
                if (!$hasFinalNewline && $index === \array_key_last($lines)) {
                    if (!$allowRepair) {
                        $this->markJournalUntrustedInMemory('truncated_tail_digest');
                        return;
                    }
                    if ($sequence < 1
                        && !\is_file($this->journalFile() . '.1')
                    ) {
                        $this->rejectOrQuarantineJournal(
                            'unanchored_only_record_digest_truncated',
                            $allowRepair,
                        );
                        return;
                    }
                    $this->truncateJournalTail($raw);
                    $tailTruncated = true;
                    break;
                }
                $this->rejectOrQuarantineJournal('record_digest_mismatch', $allowRepair);
                return;
            }
            $sequence++;
            $head = $digest;
        }
        if ($legacy) {
            if (!$allowRepair) {
                $this->markJournalUntrustedInMemory('legacy_journal_requires_migration');
                return;
            }
            $this->quarantineStableRegularFile($file, 'legacy');
            $this->journalSequence = 0;
            $this->journalHead = \str_repeat('0', 64);
            return;
        }
        $this->journalSequence = $sequence;
        $this->journalHead = $head;
        if ($allowRepair && !$hasFinalNewline && !$tailTruncated && $lines !== []) {
            try {
                $this->atomicWrite($file, $raw . "\n", 0600);
            } catch (\Throwable) {
                $this->quarantineJournal('final_newline_repair_failed');
            }
        }
    }

    private function rejectOrQuarantineJournal(string $reason, bool $allowRepair): void
    {
        if ($allowRepair) {
            $this->quarantineJournal($reason);
            return;
        }
        $this->markJournalUntrustedInMemory($reason);
    }

    private function markJournalUntrustedInMemory(string $reason): void
    {
        $this->journalTrusted = false;
        $this->journalSequence = 0;
        $this->journalHead = \str_repeat('0', 64);
        $this->state['ready'] = false;
        $this->state = $this->sanitizeIsolationState($this->state);
        $this->state['epoch'] = $this->newEpoch();
        $this->state['health_state'] = 'JOURNAL_UNTRUSTED';
        $this->state['recovery']['stage'] = 'JOURNAL_UNTRUSTED';
        $this->state['recovery']['last_failure'] = $reason;
    }

    private function truncateJournalTail(string $raw): void
    {
        $lastNewline = \strrpos($raw, "\n");
        $trusted = $lastNewline === false ? '' : \substr($raw, 0, $lastNewline + 1);
        try {
            $this->atomicWrite($this->journalFile(), $trusted, 0600);
        } catch (\Throwable) {
            $this->quarantineJournal('truncated_tail_repair_failed');
        }
    }

    private function quarantineJournal(string $reason): void
    {
        $file = $this->journalFile();
        if (\file_exists($file) || \is_link($file)) {
            $this->quarantineStableRegularFile($file, 'corrupt');
        }
        $this->journalTrusted = false;
        $this->journalSequence = 0;
        $this->journalHead = \str_repeat('0', 64);
        $this->state = $this->sanitizeIsolationState($this->state);
        $this->state['health_state'] = 'JOURNAL_UNTRUSTED';
        $this->state['epoch'] = $this->newEpoch();
        if (!$this->readOnlyRecoveryMode) {
            try {
                $this->atomicWrite(
                    $this->journalDistrustMarkerFile(),
                    \gmdate(DATE_ATOM) . "\t" . $reason . "\n",
                    0600,
                );
            } catch (\Throwable) {
            }
        }
        try {
            if (!$this->readOnlyRecoveryMode) {
                $this->persistState();
            }
        } catch (\Throwable) {
        }
    }

    private function resetJournalAfterAdministratorConfirmation(): void
    {
        foreach ([$this->journalFile(), $this->journalFile() . '.1'] as $file) {
            if (!\file_exists($file) && !\is_link($file)) {
                continue;
            }
            $this->quarantineStableRegularFile($file, 'administrator-reset');
        }
        $marker = $this->journalDistrustMarkerFile();
        if (\file_exists($marker) || \is_link($marker)) {
            $this->removeStableRegularFile(
                $marker,
                'Gateway journal distrust marker',
            );
        }
        unset($this->state['journal_archive']);
        $this->journalTrusted = true;
        $this->journalSequence = 0;
        $this->journalHead = \str_repeat('0', 64);
        $this->state['epoch'] = $this->newEpoch();
        $this->state = $this->sanitizeIsolationState($this->state);
        if (!$this->journal('journal_administrator_reset', [
            'host_id' => $this->hostId(),
            'security_generation_high_water' => (int)(
                $this->state['security_generation_high_water'] ?? 0
            ),
        ])) {
            throw new \RuntimeException(
                'Administrator-confirmed journal reset could not establish a new audit chain.'
            );
        }
    }

    private function markJournalWriteFailure(string $reason): void
    {
        $this->journalTrusted = false;
        $this->markDiskPressure('JOURNAL_WRITE_FAILED', $reason);
        \fwrite(STDERR, '[wls-edge/2] journal write failed: ' . $reason . "\n");
    }

    private function rotateJournalIfNeeded(int $incomingBytes): bool
    {
        $file = $this->journalFile();
        try {
            $size = $this->stableRegularFileSize(
                $file,
                self::MAX_JOURNAL_BYTES,
                'Gateway journal',
            ) ?? 0;
        } catch (\Throwable) {
            $this->markDiskPressure('JOURNAL_ROTATION_FAILED', 'active_journal_unsafe');
            return false;
        }
        if ($size + $incomingBytes <= self::MAX_JOURNAL_BYTES) {
            return true;
        }
        $archive = $file . '.1';
        if (\file_exists($archive) || \is_link($archive)) {
            try {
                $this->removeStableRegularFile(
                    $archive,
                    'Gateway journal archive',
                );
            } catch (\Throwable) {
                $this->markDiskPressure(
                    'JOURNAL_ROTATION_FAILED',
                    'old_archive_remove_failed',
                );
                return false;
            }
        }
        try {
            $this->moveStableRegularFile(
                $file,
                $archive,
                'Gateway journal rotation',
            );
        } catch (\Throwable) {
            $this->markDiskPressure('JOURNAL_ROTATION_FAILED', 'active_archive_rename_failed');
            return false;
        }
        try {
            $archiveSize = $this->stableRegularFileSize(
                $archive,
                self::MAX_JOURNAL_BYTES,
                'Gateway journal archive',
            );
        } catch (\Throwable) {
            $this->markDiskPressure(
                'JOURNAL_ROTATION_FAILED',
                'archive_verification_failed',
            );
            return false;
        }
        if ($archiveSize !== $size) {
            $this->markDiskPressure(
                'JOURNAL_ROTATION_FAILED',
                'archive_size_changed',
            );
            return false;
        }
        $previousSequence = $this->journalSequence;
        $previousHead = $this->journalHead;
        $this->journalSequence = 0;
        $this->journalHead = \str_repeat('0', 64);
        $this->state['journal_archive'] = [
            'schema_version' => 1,
            'path' => \basename($archive),
            'sha256' => $this->fileHash($archive),
            'head_sha256' => $previousHead,
            'sequence' => $previousSequence,
            'rotated_at' => \gmdate(DATE_ATOM),
        ];
        return true;
    }

    /** @param array<string,mixed> $firstEntry */
    private function verifyJournalSegmentAnchor(array $firstEntry): bool
    {
        $hasAnchor = \array_key_exists('previous_segment_head', $firstEntry)
            || \array_key_exists('previous_segment_sequence', $firstEntry)
            || \array_key_exists('previous_segment_file_sha256', $firstEntry);
        if (!$hasAnchor) {
            return !\is_file($this->journalFile() . '.1')
                && !\is_link($this->journalFile() . '.1')
                && !\is_array($this->state['journal_archive'] ?? null);
        }
        $archive = $this->journalFile() . '.1';
        if (!\is_file($archive) || \is_link($archive)) {
            return false;
        }
        $expectedFileHash = (string)($firstEntry['previous_segment_file_sha256'] ?? '');
        $expectedHead = (string)($firstEntry['previous_segment_head'] ?? '');
        $expectedSequence = (int)($firstEntry['previous_segment_sequence'] ?? 0);
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $expectedFileHash) !== 1
            || \preg_match('/\A[a-f0-9]{64}\z/D', $expectedHead) !== 1
            || $expectedSequence < 1
            || !\hash_equals($expectedFileHash, $this->fileHash($archive))
        ) {
            return false;
        }
        try {
            $raw = $this->readStableRegularFile(
                $archive,
                self::MAX_JOURNAL_BYTES,
                'Gateway journal archive',
                true,
            );
        } catch (\Throwable) {
            return false;
        }
        $lines = \array_values(\array_filter(
            \explode("\n", $raw),
            static fn (string $line): bool => $line !== '',
        ));
        $tail = $lines !== [] ? \json_decode((string)\end($lines), true) : null;
        return \is_array($tail)
            && (int)($tail['sequence'] ?? 0) === $expectedSequence
            && \hash_equals($expectedHead, (string)($tail['sha256'] ?? ''));
    }

    private function assertPersistentMutationPreconditions(string $operation): void
    {
        $this->assertBrokerGenerationOwnership($operation);
        if (!$this->journalTrusted
            || !$this->initializationMarkerTrusted
            || !$this->securityAnchorTrusted
            || ($this->state['security_ledger_valid'] ?? false) !== true
            || $this->readOnlyRecoveryMode
        ) {
            throw new \DomainException(
                'Gateway durable state is untrusted; refusing ' . $operation . '.'
            );
        }
        $storage = $this->storageStatus();
        if (!($storage['mutation_ready'] ?? false)) {
            $this->markDiskPressure(
                'DISK_PRESSURE',
                'insufficient_free_space_for_' . $operation,
            );
            throw new \DomainException(
                'Gateway storage reserve is below the safe mutation threshold; '
                . 'verified active traffic is retained but new durable operations are rejected.'
            );
        }
    }

    private function assertPersistentMutationAllowed(string $operation): void
    {
        // SECURITY_ATTEST can persist a first-use or recovered Native digest,
        // so the durable-state and disk-reserve guards must precede it.
        $this->assertPersistentMutationPreconditions($operation);
        $this->attestBrokerSecurityRoot($operation);
    }

    /** @return array<string,mixed> */
    private function storageStatus(bool $refresh = false): array
    {
        $testMode = (string)\getenv('WLS_GATEWAY_TEST_MODE') === '1';
        $monotonicNow = $this->monotonicNow();
        if (!$refresh
            && !$testMode
            && $this->storageStatusCache !== null
            && $monotonicNow - $this->storageStatusCachedAt
                < self::STORAGE_STATUS_CACHE_SECONDS
        ) {
            return $this->storageStatusCache;
        }
        $override = (string)\getenv('WLS_GATEWAY_TEST_DISK_FREE_BYTES');
        $free = $testMode
            && $override !== ''
            && \preg_match('/\A[0-9]+\z/D', $override) === 1
                ? (int)$override
                : @\disk_free_space($this->stateDir());
        $freeBytes = \is_int($free) || \is_float($free) ? (int)$free : -1;
        $pressureMarker = $this->diskPressureMarkerActive();
        $expectedReserveBytes = $testMode
            ? self::TEST_RECOVERY_RESERVE_BYTES
            : self::RECOVERY_RESERVE_BYTES;
        try {
            $reserveBytes = $this->stableRegularFileSize(
                $this->recoveryReserveFile(),
                self::RECOVERY_RESERVE_BYTES,
                'Gateway recovery reserve',
            ) ?? 0;
        } catch (\Throwable) {
            $reserveBytes = 0;
        }
        $reserveReady = $reserveBytes === $expectedReserveBytes;
        $persistenceWritable = !$pressureMarker
            && !$this->readOnlyRecoveryMode
            && $reserveReady
            && $this->storagePersistenceWritable();
        try {
            $snapshotBytes = $this->snapshotStorageBytes();
        } catch (\Throwable) {
            $snapshotBytes = self::MAX_SNAPSHOT_BYTES + 1;
        }
        try {
            $journalBytes = $this->stableRegularFileSize(
                $this->journalFile(),
                self::MAX_JOURNAL_BYTES + 1,
                'Gateway journal',
            ) ?? 0;
        } catch (\Throwable) {
            $journalBytes = self::MAX_JOURNAL_BYTES + 1;
        }
        $status = [
            'free_bytes' => $freeBytes,
            'minimum_mutation_free_bytes' => self::MIN_MUTATION_FREE_BYTES,
            'reserve_bytes' => $reserveBytes,
            'reserve_expected_bytes' => $expectedReserveBytes,
            'recovery_reserve_ready' => $reserveReady,
            'persistence_writable' => $persistenceWritable,
            'pressure_marker' => $pressureMarker,
            'mutation_ready' => $freeBytes >= self::MIN_MUTATION_FREE_BYTES
                && !$pressureMarker
                && $reserveReady
                && $persistenceWritable,
            'snapshot_bytes' => $snapshotBytes,
            'snapshot_quota_bytes' => self::MAX_SNAPSHOT_BYTES,
            'journal_bytes' => $journalBytes,
            'journal_quota_bytes' => self::MAX_JOURNAL_BYTES,
        ];
        if (!$testMode) {
            $this->storageStatusCache = $status;
            $this->storageStatusCachedAt = $monotonicNow;
        }
        return $status;
    }

    private function storagePersistenceWritable(): bool
    {
        try {
            $probe = $this->stateDir() . DIRECTORY_SEPARATOR
                . '.persistence-probe-' . \bin2hex(\random_bytes(8));
        } catch (\Throwable) {
            return false;
        }
        $handle = @\fopen($probe, 'xb');
        if (!\is_resource($handle)) {
            return false;
        }
        $valid = false;
        try {
            if (\PHP_OS_FAMILY !== 'Windows'
                && !(\function_exists('fchmod') ? @\fchmod($handle, 0600) : @\chmod($probe, 0600))
            ) {
                $valid = false;
            } elseif (!$this->writeStreamAll($handle, "1")
                || !@\fflush($handle)
                || (\function_exists('fsync') && !@\fsync($handle))
            ) {
                $valid = false;
            } else {
                $opened = @\fstat($handle);
                $pathStatus = @\lstat($probe);
                $valid = \is_array($opened)
                    && \is_array($pathStatus)
                    && $this->sameStableFileState($opened, $pathStatus)
                    && (int)($opened['nlink'] ?? 0) === 1
                    && (int)($opened['size'] ?? -1) === 1
                    && (\PHP_OS_FAMILY === 'Windows'
                        || ((((int)($opened['mode'] ?? 0)) & 0777) === 0600));
            }
        } finally {
            @\fclose($handle);
        }
        try {
            $removed = $this->removeStableRegularFile(
                $probe,
                'Gateway persistence probe',
            );
        } catch (\Throwable) {
            $removed = false;
        }
        return $valid && $removed;
    }

    private function markDiskPressure(string $stage, string $reason): void
    {
        $this->invalidateStorageStatus();
        $this->state['ready'] = (bool)($this->state['ready'] ?? false);
        $this->state['health_state'] = 'DISK_PRESSURE';
        $this->state['recovery']['stage'] = $stage;
        $this->state['recovery']['last_failure'] = $reason;
        $reserve = $this->recoveryReserveFile();
        if (\file_exists($reserve) || \is_link($reserve)) {
            try {
                $this->removeStableRegularFile(
                    $reserve,
                    'Gateway recovery reserve',
                );
            } catch (\Throwable) {
            }
        }
        $marker = $this->diskPressureMarkerFile();
        if (\file_exists($marker) || \is_link($marker)) {
            return;
        }
        $handle = @\fopen($marker, 'xb');
        if (!\is_resource($handle)) {
            return;
        }
        try {
            $record = \gmdate(DATE_ATOM) . "\t" . $stage . "\t" . $reason . "\n";
            if (\PHP_OS_FAMILY !== 'Windows'
                && !(\function_exists('fchmod') ? @\fchmod($handle, 0600) : @\chmod($marker, 0600))
            ) {
                return;
            }
            if (!$this->writeStreamAll($handle, $record)
                || !@\fflush($handle)
                || (\function_exists('fsync') && !@\fsync($handle))
            ) {
                return;
            }
            $opened = @\fstat($handle);
            $pathStatus = @\lstat($marker);
            if (!\is_array($opened)
                || !\is_array($pathStatus)
                || !$this->sameStableFileState($opened, $pathStatus)
                || (int)($opened['nlink'] ?? 0) !== 1
                || (int)($opened['size'] ?? -1) !== \strlen($record)
            ) {
                return;
            }
        } finally {
            @\fclose($handle);
        }
        try {
            $this->syncDirectory($this->stateDir());
        } catch (\Throwable) {
        }
    }

    private function ensureRecoveryReserve(): void
    {
        $file = $this->recoveryReserveFile();
        $bytes = (string)\getenv('WLS_GATEWAY_TEST_MODE') === '1'
            ? self::TEST_RECOVERY_RESERVE_BYTES
            : self::RECOVERY_RESERVE_BYTES;
        $injectedFailure = (string)\getenv('WLS_GATEWAY_TEST_MODE') === '1'
            ? (string)\getenv('WLS_GATEWAY_TEST_RECOVERY_RESERVE_FAILURE')
            : '';
        if ($injectedFailure === '1'
            || $injectedFailure === 'before_allocation'
        ) {
            throw new \RuntimeException(
                'Injected gateway recovery reserve allocation failure.'
            );
        }
        try {
            $existingSize = $this->stableRegularFileSize(
                $file,
                self::RECOVERY_RESERVE_BYTES,
                'Gateway recovery reserve',
            );
        } catch (\Throwable $throwable) {
            throw new \RuntimeException(
                'Existing gateway recovery reserve is unsafe.',
                0,
                $throwable,
            );
        }
        if ($existingSize === $bytes) {
            return;
        }
        if ($existingSize !== null) {
            $this->removeStableRegularFile($file, 'Gateway recovery reserve');
        }
        $handle = @\fopen($file, 'xb');
        if (!\is_resource($handle)) {
            throw new \RuntimeException('Unable to establish the gateway recovery disk reserve.');
        }
        $remaining = $bytes;
        $ready = false;
        try {
            if (\PHP_OS_FAMILY !== 'Windows'
                && !(\function_exists('fchmod') ? @\fchmod($handle, 0600) : @\chmod($file, 0600))
            ) {
                throw new \RuntimeException(
                    'Unable to seal the gateway recovery disk reserve.'
                );
            }
            while ($remaining > 0) {
                $write = \min($remaining, 65_536);
                if (!$this->writeStreamAll($handle, \random_bytes($write))) {
                    throw new \RuntimeException(
                        'Unable to allocate the gateway recovery disk reserve.'
                    );
                }
                $remaining -= $write;
            }
            if ($injectedFailure === 'after_write') {
                throw new \RuntimeException(
                    'Injected gateway recovery reserve persistence failure.'
                );
            }
            if (!@\fflush($handle)
                || (\function_exists('fsync') && !@\fsync($handle))
            ) {
                throw new \RuntimeException(
                    'Unable to persist the gateway recovery disk reserve.'
                );
            }
            $opened = @\fstat($handle);
            $pathStatus = @\lstat($file);
            if (!\is_array($opened)
                || !\is_array($pathStatus)
                || !$this->sameStableFileState($opened, $pathStatus)
                || (int)($opened['nlink'] ?? 0) !== 1
                || (int)($opened['size'] ?? -1) !== $bytes
                || (\PHP_OS_FAMILY !== 'Windows'
                    && ((((int)($opened['mode'] ?? 0)) & 0777) !== 0600))
            ) {
                throw new \RuntimeException(
                    'Gateway recovery disk reserve identity changed during allocation.'
                );
            }
            $ready = true;
        } finally {
            @\fclose($handle);
            if (!$ready) {
                try {
                    $this->removeStableRegularFile(
                        $file,
                        'incomplete gateway recovery reserve',
                    );
                } catch (\Throwable) {
                }
            }
        }
        $this->syncDirectory($this->stateDir());
        $this->invalidateStorageStatus();
    }

    private function snapshotStorageBytes(): int
    {
        $root = $this->home . DIRECTORY_SEPARATOR . 'snapshots';
        $rootStatus = @\lstat($root);
        if (!\is_array($rootStatus)
            || \is_link($root)
            || ((((int)($rootStatus['mode'] ?? 0)) & 0170000) !== 0040000)
        ) {
            throw new \RuntimeException('Gateway snapshot root is unsafe.');
        }
        $bytes = 0;
        $allowedLeaves = [
            'source-cert.pem' => 1_048_576,
            'source-key.pem' => 1_048_576,
            'source-chain.pem' => 1_048_576,
            'fullchain.pem' => 2_097_152,
            'privkey.pem' => 1_048_576,
            'manifest.json' => 65_536,
        ];
        $entries = $this->boundedDirectoryEntries(
            $root,
            self::MAX_HOST_DIRECTORY_ENTRIES,
            'Gateway snapshot root',
        );
        foreach ($entries as $digest) {
            if (\preg_match('/\A[a-f0-9]{64}\z/D', $digest) !== 1) {
                throw new \RuntimeException('Gateway snapshot root contains an unknown entry.');
            }
            $directory = $root . DIRECTORY_SEPARATOR . $digest;
            $status = @\lstat($directory);
            if (!\is_array($status)
                || \is_link($directory)
                || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
                || !$this->sameBoundaryPath(
                    $directory,
                    $root . DIRECTORY_SEPARATOR . $digest,
                )
            ) {
                throw new \RuntimeException('Gateway snapshot directory is unsafe.');
            }
            $leaves = $this->boundedDirectoryEntries(
                $directory,
                6,
                'Gateway snapshot directory',
            );
            foreach ($leaves as $leaf) {
                if (!isset($allowedLeaves[$leaf])) {
                    throw new \RuntimeException('Gateway snapshot contains an unknown file.');
                }
                $size = $this->stableRegularFileSize(
                    $directory . DIRECTORY_SEPARATOR . $leaf,
                    $allowedLeaves[$leaf],
                    'Gateway certificate snapshot file',
                );
                if ($size === null) {
                    throw new \RuntimeException('Gateway certificate snapshot file disappeared.');
                }
                $bytes += $size;
                if ($bytes > self::MAX_SNAPSHOT_BYTES) {
                    return $bytes;
                }
            }
        }
        return $bytes;
    }

    private function persistRouteLkg(): void
    {
        if (!$this->activePublicationMatchesPendingLkg()) {
            throw new \RuntimeException(
                'Active config/routes no longer match the pending durable publication fence.'
            );
        }
        $routes = (array)($this->state['active_routes'] ?? $this->state['routes'] ?? []);
        if (!$this->writeRouteSnapshot($this->routeLkgFile(), $routes)) {
            throw new \RuntimeException(
                'Unable to persist the durable gateway route recovery snapshot.'
            );
        }
        if (!$this->routeLkgMatchesActiveRoutes()) {
            throw new \RuntimeException(
                'Durable gateway route recovery snapshot failed read-back verification.'
            );
        }
    }

    private function routeLkgMatchesActiveRoutes(): bool
    {
        $stored = $this->loadRouteSnapshot($this->routeLkgFile());
        if ($stored === null) {
            return false;
        }
        $active = (array)($this->state['active_routes'] ?? []);
        return \hash_equals(
            \hash('sha256', $this->canonicalJson($active)),
            \hash('sha256', $this->canonicalJson($stored)),
        );
    }

    private function activePublicationMatchesPendingLkg(): bool
    {
        $generation = (int)($this->state['pending_lkg_generation'] ?? 0);
        $routes = (array)($this->state['active_routes'] ?? []);
        if ($generation < 1
            || $generation !== (int)($this->state['active_config_generation'] ?? 0)
            || !\is_file($this->configFile())
            || \is_link($this->configFile())
            || !$this->routesAllowedForCurrentSecurity($routes)
            || !$this->routesHaveValidCertificateClosure($routes)
        ) {
            return false;
        }
        try {
            $configDigest = $this->fileHash($this->configFile());
        } catch (\Throwable) {
            return false;
        }
        $routesDigest = \hash('sha256', $this->canonicalJson($routes));
        return $configDigest !== ''
            && \hash_equals(
                (string)($this->state['active_config_digest'] ?? ''),
                $configDigest,
            )
            && \hash_equals(
                (string)($this->state['pending_lkg_config_digest'] ?? ''),
                $configDigest,
            )
            && \hash_equals(
                (string)($this->state['pending_lkg_routes_digest'] ?? ''),
                $routesDigest,
            );
    }

    /**
     * @return array<string,array<string,mixed>>
     */
    private function loadRouteLkg(): array
    {
        return $this->loadRouteSnapshot($this->routeLkgFile()) ?? [];
    }

    /**
     * @param array<string,array<string,mixed>> $routes
     */
    private function writeRouteSnapshot(string $file, array $routes): bool
    {
        $encoded = $this->encodedRouteSnapshot($routes);
        if ($encoded === null) {
            return false;
        }
        try {
            $this->atomicWrite($file, $encoded, 0600);
            return true;
        } catch (\Throwable) {
            return false;
        }
    }

    /**
     * @param array<string,array<string,mixed>> $routes
     */
    private function encodedRouteSnapshot(array $routes): ?string
    {
        $encoded = \json_encode([
            'payload' => $routes,
            'sha256' => \hash('sha256', $this->canonicalJson($routes)),
        ], JSON_PRETTY_PRINT
            | JSON_UNESCAPED_SLASHES
            | JSON_UNESCAPED_UNICODE
            | JSON_PRESERVE_ZERO_FRACTION);
        if (!\is_string($encoded)) {
            return null;
        }
        try {
            $this->assertWriterSize(
                $encoded,
                self::MAX_STATE_BYTES,
                'Gateway route snapshot',
            );
        } catch (\Throwable) {
            return null;
        }
        return $encoded;
    }

    /**
     * @return array<string,array<string,mixed>>|null
     */
    private function loadRouteSnapshot(string $file): ?array
    {
        if ($file === ''
            || !\is_file($file)
            || \is_link($file)
            || (!$this->pathInside($file, $this->stateDir())
                && !$this->pathInside($file, $this->lkgDir()))
        ) {
            return null;
        }
        try {
            $raw = $this->readStableRegularFile(
                $file,
                64 * 1024 * 1024,
                'Gateway security ledger',
            );
        } catch (\Throwable) {
            $raw = null;
        }
        $envelope = \is_string($raw) ? \json_decode($raw, true) : null;
        $payload = \is_array($envelope) && \is_array($envelope['payload'] ?? null)
            ? $envelope['payload']
            : [];
        $hash = \is_array($envelope) ? (string)($envelope['sha256'] ?? '') : '';
        return $hash !== '' && \hash_equals($hash, \hash('sha256', $this->canonicalJson($payload)))
            ? $payload
            : null;
    }

    private function compactRemovedRoutes(): void
    {
        if ($this->readOnlyRecoveryMode) {
            return;
        }
        $now = \time();
        $compacted = [];
        foreach ((array)($this->state['routes'] ?? []) as $routeId => $route) {
            if (!\is_array($route)
                || (string)($route['status'] ?? '') !== 'REMOVED'
            ) {
                continue;
            }
            $removedAt = (int)($route['removed_at'] ?? 0);
            if ($removedAt <= 0
                || $removedAt > $now
                || $now - $removedAt < self::REMOVED_ROUTE_COMPACTION_SECONDS
                || \is_array($this->state['active_routes'][$routeId] ?? null)
            ) {
                continue;
            }
            $this->retainRouteSecurityClosure($route, false, 'COMPACTED');
            unset($this->state['routes'][$routeId]);
            $projectUuid = (string)($route['project_uuid'] ?? '');
            if (\is_array($this->state['projects'][$projectUuid] ?? null)) {
                $this->state['projects'][$projectUuid]['route_ids'] = \array_values(
                    \array_filter(
                        \array_map(
                            'strval',
                            (array)($this->state['projects'][$projectUuid]['route_ids'] ?? []),
                        ),
                        static fn (string $candidate): bool => $candidate !== (string)$routeId,
                    ),
                );
            }
            $compacted[] = (string)$routeId;
        }
        if ($compacted === []) {
            return;
        }
        // Security closure is durable before route bodies disappear. Snapshot
        // GC runs afterwards and still protects the active config plus both
        // retained LKG bundles independently.
        $this->persistSecurityLedger();
        $this->persistState();
        if (!$this->journal('removed_routes_compacted', [
            'route_ids' => $compacted,
            'count' => \count($compacted),
        ])) {
            // The security ledger and state already contain the committed
            // closure/deletion. Never report this as an uncommitted deferred
            // compaction; surface the audit degradation without replaying a
            // now non-existent route body.
            $this->state['health_state'] = 'CONTROL_DEGRADED';
            $this->state['recovery']['stage'] = 'COMPACTION_AUDIT_PENDING';
            $this->state['recovery']['last_failure'] =
                'REMOVED route compaction committed but its audit append failed.';
            $this->persistState();
        }
    }

    private function collectSnapshots(): void
    {
        $root = $this->home . DIRECTORY_SEPARATOR . 'snapshots';
        $rootStatus = @\lstat($root);
        if (!\is_array($rootStatus)
            || ((((int)($rootStatus['mode'] ?? 0)) & 0170000) !== 0040000)
            || \is_link($root)
        ) {
            return;
        }
        $referenced = [];
        $visited = 0;
        foreach ([(array)$this->state['routes'], (array)($this->state['active_routes'] ?? [])]
            as $routeSet
        ) {
            if (!$this->collectSnapshotDigests(
                $routeSet,
                $referenced,
                $visited,
            )) {
                return;
            }
        }
        if ($this->publication !== null
            && !$this->collectSnapshotDigests(
                $this->publication,
                $referenced,
                $visited,
            )
        ) {
            return;
        }
        foreach (\array_keys($this->stagedCertificateSnapshots) as $digest) {
            if (\preg_match('/\A[a-f0-9]{64}\z/D', (string)$digest) === 1) {
                $referenced[(string)$digest] = true;
            }
        }
        $routeLkgFile = $this->routeLkgFile();
        $routeLkg = $this->loadRouteSnapshot($routeLkgFile);
        if ((\is_file($routeLkgFile) || \is_link($routeLkgFile))
            && $routeLkg === null
        ) {
            return;
        }
        if ($routeLkg !== null
            && !$this->collectSnapshotDigests($routeLkg, $referenced, $visited)
        ) {
            return;
        }
        foreach ((array)$this->state['lkg'] as $lkg) {
            if (!\is_array($lkg)) {
                continue;
            }
            $bundle = $this->loadLkgBundle($lkg);
            if ($bundle === null) {
                // A damaged retained LKG is a recovery incident. Avoid any
                // certificate GC until an administrator repairs or replaces it.
                return;
            }
            foreach ($bundle['certificate_digests'] as $digest) {
                $referenced[$digest] = true;
            }
        }
        try {
            $snapshotEntries = $this->boundedDirectoryEntries(
                $root,
                self::MAX_HOST_DIRECTORY_ENTRIES,
                'Gateway snapshot GC root',
            );
        } catch (\Throwable) {
            return;
        }
        if (\count($snapshotEntries) > self::MAX_HOST_DIRECTORY_ENTRIES) {
            return;
        }
        $existingCandidates = (array)(
            $this->state['snapshot_gc_candidates'] ?? []
        );
        if (\count($existingCandidates) > self::MAX_HOST_DIRECTORY_ENTRIES) {
            return;
        }
        $nextCandidates = [];
        $eligible = [];
        $nowWall = \time();
        $nowMonotonic = $this->monotonicNow();
        $clockTrusted = (string)(
            $this->state['security']['clock_untrusted_since'] ?? ''
        ) === '';
        foreach ($snapshotEntries as $digest) {
            if (\preg_match('/\A[a-f0-9]{64}\z/D', $digest) !== 1) {
                // Unknown root entries are a storage integrity incident. Do
                // not age or delete any certificate while the closure cannot
                // be enumerated exactly.
                return;
            }
            if (isset($referenced[$digest])) {
                continue;
            }
            $directory = $root . DIRECTORY_SEPARATOR . $digest;
            $status = @\lstat($directory);
            if (!\is_array($status)
                || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
                || \is_link($directory)
                || !$this->sameBoundaryPath(
                    $directory,
                    $root . DIRECTORY_SEPARATOR . $digest,
                )
            ) {
                return;
            }
            $candidate = \is_array($existingCandidates[$digest] ?? null)
                ? $existingCandidates[$digest]
                : [];
            $candidateWall = (int)($candidate['unreferenced_at'] ?? 0);
            $candidateMonotonic = (float)(
                $candidate['unreferenced_monotonic'] ?? 0.0
            );
            $candidateBoot = (string)($candidate['boot_id'] ?? '');
            $validCandidate = $candidateWall > 0
                && $candidateWall <= $nowWall
                && $candidateMonotonic >= 0.0
                && $candidateBoot !== '';
            if (!$validCandidate
                || (!$clockTrusted
                    && !\hash_equals($this->hostBootId, $candidateBoot))
            ) {
                $candidate = [
                    'unreferenced_at' => $nowWall,
                    'unreferenced_monotonic' => $nowMonotonic,
                    'boot_id' => $this->hostBootId,
                ];
            }
            $nextCandidates[$digest] = $candidate;
            $sameBootMature = \hash_equals(
                $this->hostBootId,
                (string)$candidate['boot_id'],
            )
                && $nowMonotonic >= (float)$candidate['unreferenced_monotonic']
                && $nowMonotonic - (float)$candidate['unreferenced_monotonic']
                    >= self::SNAPSHOT_RETENTION;
            $trustedWallMature = $clockTrusted
                && $nowWall >= (int)$candidate['unreferenced_at']
                && $nowWall - (int)$candidate['unreferenced_at']
                    >= self::SNAPSHOT_RETENTION;
            if ($sameBootMature || $trustedWallMature) {
                $eligible[$digest] = $directory;
            }
        }
        $beforeCandidates = (array)(
            $this->state['snapshot_gc_candidates'] ?? []
        );
        if (!\hash_equals(
            $this->canonicalJson($beforeCandidates),
            $this->canonicalJson($nextCandidates),
        )) {
            $this->state['snapshot_gc_candidates'] = $nextCandidates;
            try {
                // Persist the first-observed-unreferenced timestamp before it
                // can authorize deletion. A failed checkpoint only delays GC.
                $this->persistState();
            } catch (\Throwable) {
                $this->state['snapshot_gc_candidates'] = $beforeCandidates;
                return;
            }
        }
        $removed = false;
        foreach ($eligible as $digest => $directory) {
            $this->removeSnapshotDirectory($directory);
            if (!\file_exists($directory) && !\is_link($directory)) {
                unset($this->state['snapshot_gc_candidates'][$digest]);
                $removed = true;
            }
        }
        if ($removed) {
            try {
                $this->persistState();
            } catch (\Throwable) {
                // A stale candidate for an already absent immutable digest is
                // harmless and will be compacted on the next safe checkpoint.
            }
        }
    }

    /**
     * @param array<string,true> $digests
     */
    private function collectSnapshotDigests(
        mixed $value,
        array &$digests,
        int &$visited,
        int $depth = 0,
    ): bool {
        if ($depth > 64 || ++$visited > self::MAX_HOST_DIRECTORY_ENTRIES * 64) {
            return false;
        }
        if (!\is_array($value)) {
            return true;
        }
        foreach ($value as $key => $item) {
            if (\is_string($key) && \hash_equals('snapshot_digest', $key)) {
                $digest = \strtolower(\trim((string)$item));
                if ($digest !== ''
                    && \preg_match('/\A[a-f0-9]{64}\z/D', $digest) !== 1
                ) {
                    return false;
                }
                if ($digest !== '') {
                    $digests[$digest] = true;
                }
            }
            if (\is_array($item)
                && !$this->collectSnapshotDigests(
                    $item,
                    $digests,
                    $visited,
                    $depth + 1,
                )
            ) {
                return false;
            }
        }
        return true;
    }

    private function openControlServer()
    {
        $endpoint = $this->controlEndpoint();
        if ($endpoint['transport'] === 'unix') {
            $existing = @\stream_socket_client($endpoint['address'], $errno, $error, 0.2);
            if (\is_resource($existing)) {
                @\fclose($existing);
                // A completed connect proves that a listener owns the socket.
                // PID files are advisory and may be stale after a crash; they
                // must never authorize unlinking a live controller endpoint.
                throw new \RuntimeException(
                    'Another WLS Gateway controller already owns the control socket.'
                );
            }
            if (!$this->removeUnixSocketFile($this->socketFile())) {
                throw new \RuntimeException(
                    'Stale gateway control socket is linked or special.'
                );
            }
        }
        $server = @\stream_socket_server(
            $endpoint['address'],
            $errno,
            $error,
            \STREAM_SERVER_BIND | \STREAM_SERVER_LISTEN,
        );
        if (!\is_resource($server)) {
            throw new \RuntimeException('Unable to bind gateway control endpoint: ' . $error);
        }
        \stream_set_blocking($server, false);
        if ($endpoint['transport'] === 'unix') {
            if (!@\chmod($this->socketFile(), 0660)) {
                @\fclose($server);
                $this->removeUnixSocketFile($this->socketFile());
                throw new \RuntimeException(
                    'Unable to restrict the native Broker controller socket.'
                );
            }
        }
        if ($this->brokerInternalEndpoint === null) {
            $this->atomicWrite(
                $this->endpointFile(),
                (string)\json_encode($endpoint, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES),
                0600,
            );
        }
        return $server;
    }

    /**
     * @return array{transport:string,address:string}
     */
    private function controlEndpoint(): array
    {
        if ($this->brokerInternalEndpoint !== null) {
            if (\str_starts_with($this->brokerInternalEndpoint, 'tcp://')) {
                return [
                    'transport' => 'tcp',
                    'address' => $this->brokerInternalEndpoint,
                ];
            }
            return [
                'transport' => 'unix',
                'address' => $this->brokerInternalEndpoint,
            ];
        }
        if (\PHP_OS_FAMILY === 'Windows') {
            return [
                'transport' => 'tcp',
                'address' => 'tcp://127.0.0.1:' . $this->environmentPort('WLS_GATEWAY_CONTROL_PORT', 27642),
            ];
        }
        return ['transport' => 'unix', 'address' => 'unix://' . $this->socketFile()];
    }

    private function ensureNeutralCertificate(): void
    {
        $certFile = $this->stateDir() . DIRECTORY_SEPARATOR . 'neutral-cert.pem';
        $keyFile = $this->stateDir() . DIRECTORY_SEPARATOR . 'neutral-key.pem';
        if (\is_file($certFile) && \is_file($keyFile)) {
            return;
        }
        $opensslOptions = [
            'private_key_bits' => 2048,
            'private_key_type' => OPENSSL_KEYTYPE_RSA,
            'digest_alg' => 'sha256',
        ];
        if (\PHP_OS_FAMILY === 'Windows') {
            foreach ([
                (string)\getenv('OPENSSL_CONF'),
                \dirname(\PHP_BINARY) . DIRECTORY_SEPARATOR . 'extras'
                    . DIRECTORY_SEPARATOR . 'ssl' . DIRECTORY_SEPARATOR . 'openssl.cnf',
                \dirname(\PHP_BINARY) . DIRECTORY_SEPARATOR . 'openssl.cnf',
                'C:\\Program Files\\Common Files\\SSL\\openssl.cnf',
            ] as $configFile) {
                if ($configFile !== '' && \is_file($configFile)) {
                    $opensslOptions['config'] = $configFile;
                    break;
                }
            }
        }
        $key = @\openssl_pkey_new($opensslOptions);
        $csr = $key !== false
            ? @\openssl_csr_new(
                ['commonName' => 'unconfigured.wls.invalid'],
                $key,
                $opensslOptions,
            )
            : false;
        $cert = $csr !== false && $key !== false
            ? @\openssl_csr_sign($csr, null, $key, 3650, $opensslOptions)
            : false;
        if ($key === false || $cert === false) {
            throw new \RuntimeException('Unable to generate neutral gateway certificate.');
        }
        $certPem = '';
        $keyPem = '';
        if (!@\openssl_x509_export($cert, $certPem)
            || !@\openssl_pkey_export(
                $key,
                $keyPem,
                null,
                isset($opensslOptions['config'])
                    ? ['config' => $opensslOptions['config']]
                    : [],
            )
        ) {
            throw new \RuntimeException('Unable to export neutral gateway certificate.');
        }
        $this->atomicWrite($certFile, $certPem, 0644);
        $this->atomicWrite($keyFile, $keyPem, 0600);
    }

    /**
     * @param list<string> $arguments
     * @return array{code:int,output:string}
     */
    private function runNginx(
        array $arguments,
        ?float $deadlineMonotonic = null,
    ): array
    {
        return $this->runNginxConfig(
            $this->configFile(),
            $this->runtimeDir(),
            $arguments,
            $deadlineMonotonic,
        );
    }

    /**
     * @param list<string> $arguments
     * @return array{code:int,output:string}
     */
    private function runNginxConfig(
        string $config,
        string $prefix,
        array $arguments,
        ?float $deadlineMonotonic = null,
    ): array {
        if (!$this->brokerGenerationOwned()) {
            $this->running = false;
            return [
                'code' => 126,
                'output' => 'Retired Controller generation refuses to signal Nginx.',
            ];
        }
        $binary = $this->nginxBinary();
        if (!\is_file($binary)) {
            return ['code' => 127, 'output' => 'Gateway Nginx binary is missing.'];
        }
        $command = \array_merge([
            $binary,
            '-p',
            \rtrim($prefix, '/\\') . DIRECTORY_SEPARATOR,
            '-c',
            $config,
        ], $arguments);
        $deadlineMonotonic ??= $this->monotonicNow()
            + self::COMMAND_TIMEOUT_SECONDS;
        if ($deadlineMonotonic <= $this->monotonicNow()) {
            return ['code' => 124, 'output' => 'Nginx command deadline expired.'];
        }
        if (\PHP_OS_FAMILY === 'Windows' && $arguments === []) {
            $this->reapDeferredBoundedProcesses();
            $this->reapStoppedWindowsNginxProcesses();
            if (\count($this->deferredProcessReaps) >= self::MAX_DEFERRED_PROCESS_REAPS
                || \count($this->windowsNginxProcesses) >= self::MAX_DEFERRED_PROCESS_REAPS
            ) {
                return [
                    'code' => 126,
                    'output' => 'Windows Nginx starts are suspended while prior process handles remain indeterminate.',
                ];
            }
            $logDirectory = $prefix . DIRECTORY_SEPARATOR . 'logs';
            if ((!\is_dir($logDirectory) && !@\mkdir($logDirectory, 0700))
                || !\is_dir($logDirectory)
                || \is_link($logDirectory)
            ) {
                return ['code' => 1, 'output' => 'Unable to prepare Windows Nginx start log.'];
            }
            $this->releaseWindowsNginxProcess($config);
            if (isset($this->windowsNginxProcesses[$config])) {
                return ['code' => 1, 'output' => 'Windows Nginx process is already running.'];
            }
            $pipes = [];
            $process = @\proc_open(
                $command,
                [
                    0 => ['file', $this->nullDevice(), 'r'],
                    // This handle owns the long-lived Windows data plane, not
                    // a bounded helper. Never attach an append-only capture
                    // file whose growth survives for the process lifetime;
                    // Nginx writes operational diagnostics through its
                    // generation-scoped managed error/access logs.
                    1 => ['file', $this->nullDevice(), 'a'],
                    2 => ['file', $this->nullDevice(), 'a'],
                ],
                $pipes,
                $prefix,
                null,
                [
                    'bypass_shell' => true,
                    'create_process_group' => false,
                    'create_new_console' => false,
                ],
            );
            if (!\is_resource($process)) {
                return ['code' => 1, 'output' => 'Unable to create Windows Nginx process.'];
            }
            while ($this->monotonicNow() < $deadlineMonotonic) {
                \usleep(10_000);
                break;
            }
            if (!$this->brokerGenerationOwned()) {
                // This handle is the Windows data plane itself, not a helper
                // command. Preserve it for no-stop adoption and retire the
                // old Controller rather than killing healthy shared traffic.
                $this->windowsNginxProcesses[$config] = $process;
                $this->running = false;
                return [
                    'code' => 126,
                    'output' => 'Controller generation changed during Windows Nginx startup.',
                ];
            }
            $status = \proc_get_status($process);
            if (!\is_array($status)) {
                $this->terminateBoundedProcess($process, $pipes);
                return [
                    'code' => 126,
                    'output' => 'Windows Nginx startup process state is indeterminate.',
                ];
            }
            if (!($status['running'] ?? false)) {
                $exitCode = (int)($status['exitcode'] ?? 1);
                @\proc_close($process);
                return [
                    'code' => $exitCode >= 0 ? $exitCode : 1,
                    'output' => 'Windows Nginx exited during startup.',
                ];
            }
            $this->windowsNginxProcesses[$config] = $process;
            return ['code' => 0, 'output' => 'Windows Nginx process started.'];
        }
        return $this->runBoundedProcess($command, $deadlineMonotonic, $prefix);
    }

    /**
     * @param list<string> $command
     * @return array{code:int,output:string}
     */
    private function runBoundedProcess(
        array $command,
        float $deadlineMonotonic,
        ?string $workingDirectory = null,
    ): array {
        $this->reapDeferredBoundedProcesses();
        if (\count($this->deferredProcessReaps) >= self::MAX_DEFERRED_PROCESS_REAPS) {
            return [
                'code' => 126,
                'output' => 'Gateway commands are suspended while prior processes await reaping.',
            ];
        }
        $process = @\proc_open($command, [
            0 => ['file', $this->nullDevice(), 'r'],
            1 => ['pipe', 'w'],
            2 => ['pipe', 'w'],
        ], $pipes, $workingDirectory, null, [
            'bypass_shell' => true,
            'create_process_group' => \PHP_OS_FAMILY === 'Windows',
            'create_new_console' => false,
        ]);
        if (!\is_resource($process)) {
            return ['code' => 127, 'output' => 'Unable to start bounded gateway command.'];
        }
        @\stream_set_blocking($pipes[1], false);
        @\stream_set_blocking($pipes[2], false);
        $output = '';
        $timedOut = false;
        $tooLarge = false;
        $status = \proc_get_status($process);
        while (($status['running'] ?? false)) {
            if (!$this->brokerGenerationOwned()) {
                $this->running = false;
                $this->terminateBoundedProcess($process, $pipes);
                return [
                    'code' => 126,
                    'output' => 'Controller generation changed during a bounded Nginx command.',
                ];
            }
            $remaining = $deadlineMonotonic - $this->monotonicNow();
            if ($remaining <= 0.0) {
                $timedOut = true;
                break;
            }
            $read = [$pipes[1], $pipes[2]];
            $write = null;
            $except = null;
            $micros = (int)\min(100_000, \max(1, \ceil($remaining * 1_000_000)));
            @\stream_select($read, $write, $except, 0, $micros);
            foreach ($read as $stream) {
                if ($this->readProcessPipeChunk(
                    $stream,
                    $output,
                    self::MAX_COMMAND_OUTPUT_BYTES,
                ) < 0) {
                    $tooLarge = true;
                    break 2;
                }
            }
            $status = \proc_get_status($process);
        }
        if (!\is_array($status)) {
            $this->terminateBoundedProcess($process, $pipes);
            return [
                'code' => 126,
                'output' => 'Gateway command process state is indeterminate.',
            ];
        }
        if ($timedOut || $tooLarge) {
            $this->terminateBoundedProcess($process, $pipes);
            return $timedOut
                ? ['code' => 124, 'output' => 'Gateway command exceeded its hard deadline.']
                : ['code' => 125, 'output' => 'Gateway command exceeded its output limit.'];
        }
        if (!$this->brokerGenerationOwned()) {
            $this->running = false;
            $this->terminateBoundedProcess($process, $pipes);
            return [
                'code' => 126,
                'output' => 'Controller generation changed before Nginx command completion.',
            ];
        }
        // proc_get_status() exposes a completed process' real exit code only
        // once on some PHP/platform combinations. Preserve that first
        // observation before any pipe cleanup or later status check.
        $observedExitCode = (int)($status['exitcode'] ?? -1);
        foreach ([1, 2] as $pipeIndex) {
            while (!$tooLarge && !\feof($pipes[$pipeIndex])) {
                $readBytes = $this->readProcessPipeChunk(
                    $pipes[$pipeIndex],
                    $output,
                    self::MAX_COMMAND_OUTPUT_BYTES,
                );
                if ($readBytes < 0) {
                    $tooLarge = true;
                    break;
                }
                if ($readBytes === 0) {
                    break;
                }
            }
        }
        if ($tooLarge) {
            $this->terminateBoundedProcess($process, $pipes);
            return ['code' => 125, 'output' => 'Gateway command exceeded its output limit.'];
        }
        $this->closeBoundedProcessPipes($pipes);
        $lastStatus = \proc_get_status($process);
        if (!\is_array($lastStatus)) {
            $this->deferredProcessReaps[\get_resource_id($process)] = $process;
            return [
                'code' => 126,
                'output' => 'Gateway command completion state is indeterminate.',
            ];
        }
        if (($lastStatus['running'] ?? false) === true) {
            $this->terminateBoundedProcess($process, $pipes);
            return [
                'code' => 126,
                'output' => 'Gateway command completion could not be confirmed.',
            ];
        }
        $closedCode = @\proc_close($process);
        $exitCode = $observedExitCode;
        if ($exitCode < 0) {
            $exitCode = (int)($lastStatus['exitcode'] ?? -1);
        }
        if ($exitCode < 0) {
            $exitCode = \is_int($closedCode) && $closedCode >= 0 ? $closedCode : 1;
        }
        return [
            'code' => $exitCode,
            'output' => $this->sanitizeCommandDiagnostic(
                $output,
                self::MAX_COMMAND_OUTPUT_BYTES,
            ),
        ];
    }

    private function releaseWindowsNginxProcess(string $config): void
    {
        $process = $this->windowsNginxProcesses[$config] ?? null;
        if (!\is_resource($process)) {
            unset($this->windowsNginxProcesses[$config]);
            return;
        }
        $status = \proc_get_status($process);
        if (!\is_array($status)) {
            // Never call proc_close() on an indeterminate handle: a live
            // process or inherited handle could turn cleanup into an
            // unbounded wait. Keep the tracked identity for a later probe.
            return;
        }
        if ($status['running'] ?? false) {
            return;
        }
        @\proc_close($process);
        unset($this->windowsNginxProcesses[$config]);
    }

    /**
     * Reap only handles whose stopped state is explicit. Unknown and live
     * process identities remain retained, while the caller-enforced hard cap
     * prevents repeated shadow/start failures from growing this map without
     * bound.
     */
    private function reapStoppedWindowsNginxProcesses(): void
    {
        if (\PHP_OS_FAMILY !== 'Windows') {
            return;
        }
        foreach ($this->windowsNginxProcesses as $config => $process) {
            if (!\is_resource($process)) {
                unset($this->windowsNginxProcesses[$config]);
                continue;
            }
            $status = @\proc_get_status($process);
            if (!\is_array($status) || ($status['running'] ?? false)) {
                continue;
            }
            @\proc_close($process);
            unset($this->windowsNginxProcesses[$config]);
        }
    }

    private function windowsTrackedNginxMatches(string $config, int $pid): ?bool
    {
        if (\PHP_OS_FAMILY !== 'Windows') {
            return null;
        }
        $process = $this->windowsNginxProcesses[$config] ?? null;
        if (!\is_resource($process)) {
            return null;
        }
        $status = \proc_get_status($process);
        if (!\is_array($status)) {
            return null;
        }
        return ($status['running'] ?? false) && (int)($status['pid'] ?? 0) === $pid;
    }

    private function terminateWindowsNginxProcess(string $config): void
    {
        if (\PHP_OS_FAMILY !== 'Windows') {
            return;
        }
        $process = $this->windowsNginxProcesses[$config] ?? null;
        if (!\is_resource($process)) {
            unset($this->windowsNginxProcesses[$config]);
            return;
        }
        $status = \proc_get_status($process);
        if (!\is_array($status)) {
            return;
        }
        if ($status['running'] ?? false) {
            @\proc_terminate($process);
            $deadline = $this->monotonicNow() + 5.0;
            do {
                \usleep(100000);
                $status = \proc_get_status($process);
                if (!\is_array($status)) {
                    return;
                }
                if (!$this->brokerGenerationOwned()) {
                    $this->running = false;
                    return;
                }
            } while (($status['running'] ?? false) && $this->monotonicNow() < $deadline);
        }
        if (\is_array($status) && !($status['running'] ?? false)) {
            @\proc_close($process);
            unset($this->windowsNginxProcesses[$config]);
        }
    }

    /**
     * @return array{h3:bool,reason:string}
     */
    private function probeBinaryCapabilities(string $binary): array
    {
        if (!\is_file($binary)) {
            return ['h3' => false, 'reason' => 'Gateway Nginx binary is missing.'];
        }
        $probe = $this->runBoundedProcess(
            [$binary, '-V'],
            $this->monotonicNow() + 3.0,
            \dirname($binary),
        );
        $compiled = ($probe['code'] ?? 1) === 0
            && \str_contains((string)($probe['output'] ?? ''), '--with-http_v3_module');
        return [
            // Compile flags are not a runtime QUIC proof. Until the immutable
            // host package supplies a pinned H3 client that validates UDP,
            // SNI, certificate and the route sentinel, H3 stays fail-closed.
            'h3' => false,
            'reason' => $compiled
                ? 'HTTP/3 module present but runtime QUIC attestation is unavailable; H3 disabled.'
                : 'HTTP/3 unavailable; gateway uses HTTP/2 and HTTP/1.1.',
        ];
    }

    /**
     * @param list<string> $allowedRoots
     */
    private function authorizedRegularFile(string $path, array $allowedRoots): string
    {
        $real = \realpath($path);
        if (!\is_string($real) || !\is_file($real)) {
            throw new \DomainException('Certificate source file is missing.');
        }
        foreach ($allowedRoots as $root) {
            $rootReal = \realpath($root);
            if (!\is_string($rootReal) || !$this->pathInside($real, $rootReal)) {
                continue;
            }
            if ($this->pathHasSymlink($real, $rootReal)) {
                throw new \DomainException('Certificate source contains a symbolic-link traversal.');
            }
            return $real;
        }
        throw new \DomainException('Certificate source is outside enrolled roots.');
    }

    /**
     * @param array<string,mixed> $reference
     */
    private function resolveCertificateReference(string $projectUuid, array $reference): string
    {
        $alias = \strtolower(\trim((string)($reference['root_alias'] ?? '')));
        $relative = \trim((string)($reference['relative_path'] ?? ''));
        if (\preg_match('/\A[a-z][a-z0-9_]{0,31}\z/D', $alias) !== 1
            || $relative === ''
            || \str_contains($relative, "\0")
            || \str_starts_with($relative, '/')
            || \str_starts_with($relative, '\\')
            || \preg_match('/\A[A-Za-z]:[\\\\\\/]/D', $relative) === 1
        ) {
            throw new \DomainException('Certificate source reference is invalid.');
        }
        $segments = \preg_split('#[\\\\/]+#', $relative) ?: [];
        if ($segments === []) {
            throw new \DomainException('Certificate source reference is empty.');
        }
        foreach ($segments as $segment) {
            if ($segment === '' || $segment === '.' || $segment === '..') {
                throw new \DomainException('Certificate source reference contains traversal.');
            }
        }
        $enrollment = $this->state['enrollments'][$projectUuid] ?? null;
        $roots = \is_array($enrollment)
            ? (array)($enrollment['certificate_roots'] ?? [])
            : [];
        $root = (string)($roots[$alias] ?? '');
        if ($root === '') {
            throw new \DomainException('Certificate source root alias is not enrolled.');
        }
        $candidate = \rtrim($root, '/\\') . DIRECTORY_SEPARATOR
            . \implode(DIRECTORY_SEPARATOR, $segments);
        return $this->authorizedRegularFile($candidate, [$root]);
    }

    private function pathHasSymlink(string $path, string $root): bool
    {
        $relative = \ltrim(\substr($path, \strlen(\rtrim($root, '/\\'))), '/\\');
        $current = \rtrim($root, '/\\');
        foreach (\preg_split('#[\\\\/]+#', $relative) ?: [] as $segment) {
            if ($segment === '') {
                continue;
            }
            $current .= DIRECTORY_SEPARATOR . $segment;
            $stat = @\lstat($current);
            if (\is_array($stat) && (($stat['mode'] ?? 0) & 0170000) === 0120000) {
                return true;
            }
        }
        return false;
    }

    private function pathInside(string $path, string $root): bool
    {
        $path = $this->normalizeBoundaryPath($path);
        $root = $this->normalizeBoundaryPath($root);
        return $path !== null && $root !== null
            && ($path === $root || \str_starts_with($path, $root . '/'));
    }

    private function sameBoundaryPath(string $left, string $right): bool
    {
        $left = $this->normalizeBoundaryPath($left);
        $right = $this->normalizeBoundaryPath($right);
        return $left !== null && $right !== null && \hash_equals($left, $right);
    }

    private function normalizeBoundaryPath(string $path): ?string
    {
        if ($path === '' || \str_contains($path, "\0")) {
            return null;
        }
        $path = \str_replace('\\', '/', $path);
        if (\preg_match('#(?:^|/)(?:\.|\.\.)(?:/|$)#D', $path) === 1) {
            return null;
        }
        $path = \rtrim($path, '/');
        if ($path === '') {
            return null;
        }
        return \PHP_OS_FAMILY === 'Windows' ? \strtolower($path) : $path;
    }

    private function canonicalDirectory(string $path): string
    {
        $path = \trim($path);
        if ($path === '' || \str_contains($path, "\0")) {
            throw new \DomainException('Project or certificate root cannot be resolved.');
        }
        if (\PHP_OS_FAMILY === 'Windows') {
            $real = \realpath($path);
            if (!\is_string($real)
                || !\is_dir($real)
                || $this->isFilesystemRootPath($real)
            ) {
                throw new \DomainException('Project or certificate root cannot be resolved.');
            }
            return \rtrim($real, '/\\');
        }
        if (!\str_starts_with($path, '/')) {
            throw new \DomainException('Project or certificate root must be absolute.');
        }
        $segments = [];
        foreach (\explode('/', $path) as $segment) {
            if ($segment === '') {
                continue;
            }
            if ($segment === '.' || $segment === '..') {
                throw new \DomainException(
                    'Project or certificate root cannot contain traversal segments.'
                );
            }
            $segments[] = $segment;
        }
        if ($segments === []) {
            throw new \DomainException('The filesystem root cannot be enrolled as a project.');
        }
        return '/' . \implode('/', $segments);
    }

    private function isFilesystemRootPath(string $path): bool
    {
        $normalized = \str_replace('\\', '/', \trim($path));
        if (\preg_match('#\A/+\z#D', $normalized) === 1) {
            return true;
        }
        $normalized = \rtrim($normalized, '/');
        return \preg_match('/\A[A-Za-z]:\z/D', $normalized) === 1
            || \preg_match('#\A//(?![?.](?:/|\z))[^/]+(?:/[^/]+)?\z#D', $normalized) === 1
            || \preg_match('#\A//[?.]/[A-Za-z]:\z#Di', $normalized) === 1
            || \preg_match('#\A//[?.]/UNC(?:/[^/]+(?:/[^/]+)?)?\z#Di', $normalized) === 1
            || \preg_match('#\A//[?.]/Volume\{[0-9A-Fa-f-]+\}\z#Di', $normalized) === 1;
    }

    private function removePublicationCandidateFile(
        string $path,
        int $generation,
        string $transactionId,
    ): bool {
        if ($generation < 1
            || \preg_match('/\A[a-f0-9]{32}\z/D', $transactionId) !== 1
        ) {
            $this->observeCleanupFailure(
                'PUBLICATION_CANDIDATE_CLEANUP_FAILED',
                'Candidate identity is incomplete.',
            );
            return false;
        }
        $expected = $this->configDir() . DIRECTORY_SEPARATOR . 'candidate-'
            . $generation . '-' . $transactionId . '.conf';
        return $this->removeExactConfigCandidate(
            $path,
            $expected,
            'Gateway publication candidate config',
            'PUBLICATION_CANDIDATE_CLEANUP_FAILED',
        );
    }

    private function removeLkgCandidateConfigFile(string $path): bool
    {
        $leaf = \basename($path);
        if (\preg_match('/\Alkg-candidate-[a-f0-9]{16}\.conf\z/D', $leaf) !== 1) {
            $this->observeCleanupFailure(
                'LKG_CANDIDATE_CLEANUP_FAILED',
                'Candidate filename is invalid.',
            );
            return false;
        }
        return $this->removeExactConfigCandidate(
            $path,
            $this->configDir() . DIRECTORY_SEPARATOR . $leaf,
            'Gateway LKG candidate config',
            'LKG_CANDIDATE_CLEANUP_FAILED',
        );
    }

    private function removeExactConfigCandidate(
        string $path,
        string $expected,
        string $label,
        string $failureStage,
    ): bool {
        if ($path === ''
            || \str_contains($path, "\0")
            || !$this->sameBoundaryPath($path, $expected)
            || $this->sameBoundaryPath($path, $this->configFile())
        ) {
            $this->observeCleanupFailure(
                $failureStage,
                $label . ' path does not match its exact generated identity.',
            );
            return false;
        }
        if (!\file_exists($path) && !\is_link($path)) {
            return true;
        }
        try {
            return $this->removeStableRegularFile($path, $label);
        } catch (\Throwable $throwable) {
            $this->observeCleanupFailure($failureStage, $throwable->getMessage());
            return false;
        }
    }

    private function atomicWrite(string $path, string $contents, int $mode): void
    {
        $this->assertBrokerGenerationOwnership('atomic gateway write');
        $directory = \dirname($path);
        $parent = @\lstat($directory);
        if (!\is_array($parent)
            || \is_link($directory)
            || ((((int)($parent['mode'] ?? 0)) & 0170000) !== 0040000)
        ) {
            throw new \RuntimeException('Atomic gateway write path is unsafe.');
        }
        if (\file_exists($path) || \is_link($path)) {
            $existing = @\lstat($path);
            if (!\is_array($existing)
                || \is_link($path)
                || ((((int)($existing['mode'] ?? 0)) & 0170000) !== 0100000)
                || (int)($existing['nlink'] ?? 0) !== 1
            ) {
                throw new \RuntimeException('Atomic gateway write target is unsafe.');
            }
        }
        $temporary = $path . '.tmp-' . \bin2hex(\random_bytes(6));
        if ($this->injectedAtomicWriteFailure('temporary_open_failed')) {
            $this->markDiskPressure('ATOMIC_WRITE_FAILED', 'temporary_open_failed');
            throw new \RuntimeException('Unable to stage an atomic gateway file.');
        }
        $handle = @\fopen($temporary, 'xb');
        if (!\is_resource($handle)) {
            $this->markDiskPressure('ATOMIC_WRITE_FAILED', 'temporary_open_failed');
            throw new \RuntimeException('Unable to stage an atomic gateway file.');
        }
        $failure = null;
        $stagedStatus = null;
        try {
            if ($this->injectedAtomicWriteFailure('temporary_write_or_fsync_failed')
            ) {
                $this->markDiskPressure('ATOMIC_WRITE_FAILED', 'temporary_write_or_fsync_failed');
                throw new \RuntimeException('Unable to persist a temporary gateway file.');
            }
            if (!$this->writeStreamAll($handle, $contents)) {
                $this->markDiskPressure('ATOMIC_WRITE_FAILED', 'temporary_write_or_fsync_failed');
                throw new \RuntimeException('Unable to persist a temporary gateway file.');
            }
            if (\PHP_OS_FAMILY !== 'Windows'
                && !(\function_exists('fchmod') ? @\fchmod($handle, $mode) : @\chmod($temporary, $mode))
            ) {
                throw new \RuntimeException('Unable to seal a temporary gateway file.');
            }
            if (!@\fflush($handle)
                || (\function_exists('fsync') && !@\fsync($handle))
            ) {
                $this->markDiskPressure('ATOMIC_WRITE_FAILED', 'temporary_write_or_fsync_failed');
                throw new \RuntimeException('Unable to persist a temporary gateway file.');
            }
            $opened = @\fstat($handle);
            $pathStatus = @\lstat($temporary);
            if (!\is_array($opened)
                || !\is_array($pathStatus)
                || !$this->sameStableFileState($opened, $pathStatus)
                || (int)($opened['size'] ?? -1) !== \strlen($contents)
            ) {
                throw new \RuntimeException(
                    'Temporary gateway file identity changed before publication.'
                );
            }
            $stagedStatus = $opened;
        } catch (\Throwable $throwable) {
            $failure = $throwable;
        } finally {
            @\fclose($handle);
        }
        if ($failure instanceof \Throwable) {
            try {
                $this->removeStableRegularFile(
                    $temporary,
                    'Failed atomic gateway staging file',
                );
            } catch (\Throwable $cleanupFailure) {
                $this->observeCleanupFailure(
                    'ATOMIC_WRITE_CLEANUP_FAILED',
                    $cleanupFailure->getMessage(),
                );
                throw new \RuntimeException(
                    $failure->getMessage() . ' Staging cleanup also failed: '
                        . $cleanupFailure->getMessage(),
                    0,
                    $failure,
                );
            }
            throw $failure;
        }
        $injectedRenameFailure = $this->injectedAtomicWriteFailure(
            'atomic_rename_failed',
        );
        $publishedByRename = false;
        if (!$injectedRenameFailure) {
            $attempts = \PHP_OS_FAMILY === 'Windows' ? 5 : 1;
            for ($attempt = 0; $attempt < $attempts; ++$attempt) {
                if (@\rename($temporary, $path)) {
                    $publishedByRename = true;
                    break;
                }
                if ($attempt + 1 < $attempts) {
                    \usleep(10_000);
                }
            }
        }
        if (!$publishedByRename) {
            try {
                $channel = (string)($this->activeBrokerPeer['channel'] ?? '');
                if (\PHP_OS_FAMILY !== 'Windows'
                    || !\in_array($channel, ['admin', 'project'], true)
                    || !$this->brokerActionsAvailable($channel)
                ) {
                    throw new \RuntimeException(
                        'Atomic replacement is unavailable; the committed target was preserved.'
                    );
                }
                $targetDigest = \hash('sha256', $contents);
                $targetMode = \decoct($mode);
                $response = $this->brokerAction($channel, [
                    'ATOMIC_REPLACE',
                    \bin2hex($temporary),
                    \bin2hex($path),
                    $targetDigest,
                    (string)\strlen($contents),
                    $targetMode,
                ]);
                if (\count($response) !== 5
                    || !\hash_equals('-', (string)$response[0])
                    || !\hash_equals('-', (string)$response[1])
                    || !\hash_equals($targetDigest, (string)$response[2])
                    || (int)$response[3] !== \strlen($contents)
                    || !\hash_equals($targetMode, (string)$response[4])
                ) {
                    throw new \RuntimeException(
                        'Native Broker returned an invalid ATOMIC_REPLACE receipt.'
                    );
                }
            } finally {
                if (\file_exists($temporary) || \is_link($temporary)) {
                    $this->removeStableRegularFile(
                        $temporary,
                        'Atomic gateway staging file',
                    );
                }
            }
            if (!\is_file($path)
                || \is_link($path)
                || !\hash_equals(\hash('sha256', $contents), $this->fileHash($path))
            ) {
                $this->markDiskPressure('ATOMIC_WRITE_FAILED', 'broker_atomic_replace_failed');
                throw new \RuntimeException(
                    'Native Broker atomic replacement did not publish the staged identity.'
                );
            }
        }
        $published = @\lstat($path);
        if (!\is_array($published)
            || ((((int)($published['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($published['nlink'] ?? 0) !== 1
            || (\PHP_OS_FAMILY !== 'Windows'
                && (((int)($published['mode'] ?? 0)) & 0777) !== $mode)
            || ($publishedByRename
                && (!\is_array($stagedStatus)
                    || !$this->sameStableFileIdentity($stagedStatus, $published)))
            || (int)($published['size'] ?? -1) !== \strlen($contents)
        ) {
            throw new \RuntimeException('Published atomic gateway file is unsafe.');
        }
        if (\PHP_OS_FAMILY !== 'Windows' && \function_exists('fsync')) {
            $directoryHandle = @\fopen($directory, 'rb');
            if (!\is_resource($directoryHandle)) {
                throw new \RuntimeException('Unable to open atomic gateway parent for sync.');
            }
            try {
                if (!@\fsync($directoryHandle)) {
                    throw new \RuntimeException('Unable to durably publish atomic gateway file.');
                }
            } finally {
                @\fclose($directoryHandle);
            }
        }
    }

    private function replaceLockedAtomicFile(
        string $path,
        string $contents,
        int $mode,
    ): void {
        throw new \RuntimeException(
            'In-place locked replacement is forbidden because it destroys the previous commit.'
        );
    }

    private function injectedAtomicWriteFailure(string $stage): bool
    {
        return (string)\getenv('WLS_GATEWAY_TEST_MODE') === '1'
            && \hash_equals(
                $stage,
                (string)\getenv('WLS_GATEWAY_TEST_ATOMIC_WRITE_FAILURE'),
            );
    }

    private function readStableRegularFile(
        string $path,
        int $maximumBytes,
        string $label,
        bool $allowEmpty = false,
    ): string {
        return $this->readStableRegularFileWithStatus(
            $path,
            $maximumBytes,
            $label,
            $allowEmpty,
        )['contents'];
    }

    /**
     * @return array{contents:string,status:array<string|int,mixed>}
     */
    private function readStableRegularFileWithStatus(
        string $path,
        int $maximumBytes,
        string $label,
        bool $allowEmpty = false,
    ): array {
        $pathStatus = @\lstat($path);
        if ($maximumBytes < 1
            || !\is_array($pathStatus)
            || \is_link($path)
            || ((((int)($pathStatus['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($pathStatus['nlink'] ?? 0) !== 1
            || (int)($pathStatus['size'] ?? -1) < ($allowEmpty ? 0 : 1)
            || (int)($pathStatus['size'] ?? -1) > $maximumBytes
        ) {
            throw new \RuntimeException($label . ' is missing, linked, or special.');
        }
        $handle = @\fopen($path, 'rb');
        if (!\is_resource($handle)) {
            throw new \RuntimeException('Unable to open ' . $label . '.');
        }
        try {
            $openedStatus = @\fstat($handle);
            if (!\is_array($openedStatus)
                || !$this->sameStableFileState($pathStatus, $openedStatus)
            ) {
                throw new \RuntimeException($label . ' changed before reading.');
            }
            $contents = @\stream_get_contents($handle, $maximumBytes + 1);
            $afterStatus = @\fstat($handle);
            $pathAfter = @\lstat($path);
            if (!\is_string($contents)
                || \strlen($contents) > $maximumBytes
                || !\is_array($afterStatus)
                || !\is_array($pathAfter)
                || !$this->sameStableFileState($openedStatus, $afterStatus)
                || !$this->sameStableFileState($afterStatus, $pathAfter)
                || (int)($afterStatus['size'] ?? -1) !== \strlen($contents)
            ) {
                throw new \RuntimeException($label . ' changed while being read.');
            }
            return ['contents' => $contents, 'status' => $afterStatus];
        } finally {
            @\fclose($handle);
        }
    }

    private function readOptionalStableRegularFile(
        string $path,
        int $maximumBytes,
        string $label,
    ): ?string {
        $status = @\lstat($path);
        if (!\is_array($status)) {
            if (\file_exists($path) || \is_link($path)) {
                throw new \RuntimeException($label . ' path is indeterminate or unsafe.');
            }
            return null;
        }
        return $this->readStableRegularFile($path, $maximumBytes, $label);
    }

    private function tryReadStableRegularFile(
        string $path,
        int $maximumBytes,
        string $label,
        bool $allowEmpty = false,
    ): ?string {
        try {
            return $this->readStableRegularFile(
                $path,
                $maximumBytes,
                $label,
                $allowEmpty,
            );
        } catch (\Throwable) {
            return null;
        }
    }

    /**
     * @param array<string|int,mixed> $before
     * @param array<string|int,mixed> $after
     */
    private function sameStableFileState(array $before, array $after): bool
    {
        foreach (['dev', 'ino', 'mode', 'nlink', 'size', 'mtime', 'ctime'] as $key) {
            if (!\array_key_exists($key, $before)
                || !\array_key_exists($key, $after)
                || (int)$before[$key] !== (int)$after[$key]
            ) {
                return false;
            }
        }
        return true;
    }

    /**
     * @param array<string|int,mixed> $before
     * @param array<string|int,mixed> $after
     */
    private function sameStableFileIdentity(array $before, array $after): bool
    {
        foreach (['dev', 'ino', 'mode', 'nlink', 'size'] as $key) {
            if (!\array_key_exists($key, $before)
                || !\array_key_exists($key, $after)
                || (int)$before[$key] !== (int)$after[$key]
            ) {
                return false;
            }
        }
        return true;
    }

    private function stableRegularFileSize(
        string $path,
        int $maximumBytes,
        string $label,
    ): ?int {
        $pathStatus = @\lstat($path);
        if (!\is_array($pathStatus)) {
            if (\file_exists($path) || \is_link($path)) {
                throw new \RuntimeException($label . ' path is indeterminate or unsafe.');
            }
            return null;
        }
        $size = (int)($pathStatus['size'] ?? -1);
        if ($maximumBytes < 0
            || \is_link($path)
            || ((((int)($pathStatus['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($pathStatus['nlink'] ?? 0) !== 1
            || $size < 0
            || $size > $maximumBytes
        ) {
            throw new \RuntimeException($label . ' is linked, special, or oversized.');
        }
        $handle = @\fopen($path, 'rb');
        if (!\is_resource($handle)) {
            throw new \RuntimeException('Unable to inspect ' . $label . '.');
        }
        try {
            $opened = @\fstat($handle);
            $pathAfter = @\lstat($path);
            if (!\is_array($opened)
                || !\is_array($pathAfter)
                || !$this->sameStableFileState($pathStatus, $opened)
                || !$this->sameStableFileState($opened, $pathAfter)
            ) {
                throw new \RuntimeException($label . ' changed while being inspected.');
            }
            return $size;
        } finally {
            @\fclose($handle);
        }
    }

    private function removeStableRegularFile(
        string $path,
        string $label,
        bool $allowRejectedFirstConfig = false,
    ): bool
    {
        if ($this->protectedActiveArtifactPath($path, $allowRejectedFirstConfig)) {
            throw new \RuntimeException(
                $label . ' cannot remove a protected active or LKG artifact.'
            );
        }
        $pathStatus = @\lstat($path);
        if (!\is_array($pathStatus)) {
            return !\file_exists($path) && !\is_link($path);
        }
        if (\is_link($path)
            || ((((int)($pathStatus['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($pathStatus['nlink'] ?? 0) !== 1
        ) {
            throw new \RuntimeException($label . ' removal target is unsafe.');
        }
        $handle = @\fopen($path, 'rb');
        if (!\is_resource($handle)) {
            throw new \RuntimeException('Unable to verify ' . $label . ' before removal.');
        }
        $removed = false;
        try {
            $opened = @\fstat($handle);
            $pathBefore = @\lstat($path);
            if (!\is_array($opened)
                || !\is_array($pathBefore)
                || !$this->sameStableFileState($pathStatus, $opened)
                || !$this->sameStableFileState($opened, $pathBefore)
            ) {
                throw new \RuntimeException($label . ' changed before removal.');
            }
            if (\PHP_OS_FAMILY !== 'Windows') {
                if (!@\unlink($path)) {
                    throw new \RuntimeException('Unable to remove ' . $label . '.');
                }
                $removed = true;
            }
        } finally {
            @\fclose($handle);
        }
        if (!$removed && !@\unlink($path)) {
            throw new \RuntimeException('Unable to remove ' . $label . '.');
        }
        $this->syncDirectory(\dirname($path));
        return true;
    }

    private function protectedActiveArtifactPath(
        string $path,
        bool $allowRejectedFirstConfig = false,
    ): bool {
        if ((!$allowRejectedFirstConfig
                && $this->sameBoundaryPath($path, $this->configFile()))
            || $this->sameBoundaryPath($path, $this->routeLkgFile())
        ) {
            return true;
        }
        foreach ((array)($this->state['lkg'] ?? []) as $entry) {
            if (!\is_array($entry)) {
                continue;
            }
            foreach (['file', 'route_file', 'manifest_file'] as $field) {
                $protected = (string)($entry[$field] ?? '');
                if ($protected !== '' && $this->sameBoundaryPath($path, $protected)) {
                    return true;
                }
            }
        }
        return false;
    }

    private function quarantineStableRegularFile(
        string $path,
        string $reason,
    ): string {
        if (\preg_match('/\A[a-z0-9-]{1,32}\z/D', $reason) !== 1) {
            throw new \InvalidArgumentException('Gateway quarantine reason is invalid.');
        }
        $quarantine = $path . '.' . $reason . '-'
            . \gmdate('YmdHis') . '-' . \bin2hex(\random_bytes(4));
        $this->moveStableRegularFile(
            $path,
            $quarantine,
            'Gateway quarantined state file',
        );
        return $quarantine;
    }

    private function moveStableRegularFile(
        string $source,
        string $destination,
        string $label,
    ): void {
        if ($source === ''
            || $destination === ''
            || \str_contains($source, "\0")
            || \str_contains($destination, "\0")
            || \file_exists($destination)
            || \is_link($destination)
            || $this->protectedActiveArtifactPath($source)
            || $this->protectedActiveArtifactPath($destination)
        ) {
            throw new \RuntimeException($label . ' destination is unsafe.');
        }
        $sourceStatus = @\lstat($source);
        $destinationParent = @\lstat(\dirname($destination));
        if (!\is_array($sourceStatus)
            || \is_link($source)
            || ((((int)($sourceStatus['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($sourceStatus['nlink'] ?? 0) !== 1
            || !\is_array($destinationParent)
            || \is_link(\dirname($destination))
            || ((((int)($destinationParent['mode'] ?? 0)) & 0170000) !== 0040000)
        ) {
            throw new \RuntimeException($label . ' source or destination is unsafe.');
        }
        $handle = @\fopen($source, 'rb');
        if (!\is_resource($handle)) {
            throw new \RuntimeException('Unable to verify ' . $label . ' source.');
        }
        $moved = false;
        try {
            $opened = @\fstat($handle);
            $pathBeforeMove = @\lstat($source);
            if (!\is_array($opened)
                || !\is_array($pathBeforeMove)
                || !$this->sameStableFileState($sourceStatus, $opened)
                || !$this->sameStableFileState($opened, $pathBeforeMove)
            ) {
                throw new \RuntimeException($label . ' changed before moving.');
            }
            if (\PHP_OS_FAMILY !== 'Windows') {
                if (!@\rename($source, $destination)) {
                    throw new \RuntimeException('Unable to move ' . $label . '.');
                }
                $moved = true;
            }
        } finally {
            @\fclose($handle);
        }
        if (!$moved) {
            $pathBeforeMove = @\lstat($source);
            if (!\is_array($pathBeforeMove)
                || !$this->sameStableFileState($sourceStatus, $pathBeforeMove)
                || !@\rename($source, $destination)
            ) {
                throw new \RuntimeException('Unable to move ' . $label . '.');
            }
        }
        $published = @\lstat($destination);
        if (!\is_array($published)
            || !$this->sameStableFileIdentity($sourceStatus, $published)
        ) {
            throw new \RuntimeException($label . ' destination identity is invalid.');
        }
        $this->syncDirectory(\dirname($source));
        if (!\hash_equals(\dirname($source), \dirname($destination))) {
            $this->syncDirectory(\dirname($destination));
        }
    }

    private function moveStableChildDirectory(
        string $source,
        string $destination,
        string $parent,
        string $sourceLeafPattern,
        string $destinationLeafPattern,
        int $maximumEntries,
        string $label,
    ): void {
        $sourceLeaf = \basename($source);
        $destinationLeaf = \basename($destination);
        $parentStatus = @\lstat($parent);
        $sourceStatus = @\lstat($source);
        if ($source === ''
            || $destination === ''
            || \str_contains($source, "\0")
            || \str_contains($destination, "\0")
            || $maximumEntries < 1
            || \preg_match($sourceLeafPattern, $sourceLeaf) !== 1
            || \preg_match($destinationLeafPattern, $destinationLeaf) !== 1
            || !$this->sameBoundaryPath(
                $source,
                $parent . DIRECTORY_SEPARATOR . $sourceLeaf,
            )
            || !$this->sameBoundaryPath(
                $destination,
                $parent . DIRECTORY_SEPARATOR . $destinationLeaf,
            )
            || !\is_array($parentStatus)
            || \is_link($parent)
            || ((((int)($parentStatus['mode'] ?? 0)) & 0170000) !== 0040000)
            || !\is_array($sourceStatus)
            || \is_link($source)
            || ((((int)($sourceStatus['mode'] ?? 0)) & 0170000) !== 0040000)
            || \file_exists($destination)
            || \is_link($destination)
        ) {
            throw new \RuntimeException($label . ' source or destination is unsafe.');
        }
        $this->boundedDirectoryEntries($source, $maximumEntries, $label);
        $sourceBeforeMove = @\lstat($source);
        if (!\is_array($sourceBeforeMove)
            || !$this->sameStableDirectoryIdentity($sourceStatus, $sourceBeforeMove)
            || !@\rename($source, $destination)
        ) {
            throw new \RuntimeException('Unable to atomically move ' . $label . '.');
        }
        \clearstatcache(true, $source);
        \clearstatcache(true, $destination);
        $published = @\lstat($destination);
        if (!\is_array($published)
            || \is_link($destination)
            || !$this->sameStableDirectoryIdentity($sourceStatus, $published)
            || \is_array(@\lstat($source))
        ) {
            throw new \RuntimeException($label . ' destination identity is invalid.');
        }
        $this->boundedDirectoryEntries($destination, $maximumEntries, $label);
        $this->syncDirectory($parent);
    }

    /**
     * @param array<string|int,mixed> $before
     * @param array<string|int,mixed> $after
     */
    private function sameStableDirectoryIdentity(array $before, array $after): bool
    {
        foreach (['dev', 'ino', 'mode', 'nlink'] as $key) {
            if (!\array_key_exists($key, $before)
                || !\array_key_exists($key, $after)
                || (int)$before[$key] !== (int)$after[$key]
            ) {
                return false;
            }
        }
        return ((((int)$after['mode']) & 0170000) === 0040000);
    }

    private function syncDirectory(string $directory): void
    {
        if (\PHP_OS_FAMILY === 'Windows' || !\function_exists('fsync')) {
            return;
        }
        $status = @\lstat($directory);
        if (!\is_array($status)
            || \is_link($directory)
            || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
        ) {
            throw new \RuntimeException('Gateway directory synchronization target is unsafe.');
        }
        $handle = @\fopen($directory, 'rb');
        if (!\is_resource($handle)) {
            throw new \RuntimeException('Unable to open gateway directory for synchronization.');
        }
        try {
            if (!@\fsync($handle)) {
                throw new \RuntimeException('Unable to synchronize gateway directory.');
            }
        } finally {
            @\fclose($handle);
        }
    }

    private function invalidateStorageStatus(): void
    {
        $this->storageStatusCache = null;
        $this->storageStatusCachedAt = 0.0;
    }

    private function fileHash(string $file): string
    {
        return $this->stableFileHash(
            $file,
            self::MAX_SNAPSHOT_BYTES,
            'Gateway file',
        );
    }

    private function stableFileHash(
        string $file,
        int $maximumBytes,
        string $label,
    ): string {
        try {
            $pathStatus = @\lstat($file);
            if ($maximumBytes < 1
                || !\is_array($pathStatus)
                || \is_link($file)
                || ((((int)($pathStatus['mode'] ?? 0)) & 0170000) !== 0100000)
                || (int)($pathStatus['nlink'] ?? 0) !== 1
                || (int)($pathStatus['size'] ?? -1) < 1
                || (int)($pathStatus['size'] ?? -1) > $maximumBytes
            ) {
                return '';
            }
            $handle = @\fopen($file, 'rb');
            if (!\is_resource($handle)) {
                return '';
            }
            try {
                $opened = @\fstat($handle);
                if (!\is_array($opened)
                    || !$this->sameStableFileState($pathStatus, $opened)
                ) {
                    return '';
                }
                $context = \hash_init('sha256');
                $bytes = 0;
                while (!\feof($handle)) {
                    $chunk = @\fread($handle, 1_048_576);
                    if (!\is_string($chunk)
                        || ($chunk === '' && !\feof($handle))
                    ) {
                        return '';
                    }
                    if ($chunk === '') {
                        continue;
                    }
                    $bytes += \strlen($chunk);
                    if ($bytes > $maximumBytes) {
                        return '';
                    }
                    \hash_update($context, $chunk);
                }
                $after = @\fstat($handle);
                $pathAfter = @\lstat($file);
                if (!\is_array($after)
                    || !\is_array($pathAfter)
                    || !$this->sameStableFileState($opened, $after)
                    || !$this->sameStableFileState($after, $pathAfter)
                    || (int)($after['size'] ?? -1) !== $bytes
                ) {
                    return '';
                }
                return \strtolower(\hash_final($context));
            } finally {
                @\fclose($handle);
            }
        } catch (\Throwable) {
            return '';
        }
    }

    /**
     * Missing PID files return null; unsafe or malformed files return -1.
     */
    private function readPidFile(string $file): ?int
    {
        $status = @\lstat($file);
        if (!\is_array($status)) {
            return (!\file_exists($file) && !\is_link($file)) ? null : -1;
        }
        try {
            $raw = \trim($this->readStableRegularFile(
                $file,
                32,
                'Gateway process PID file',
            ));
        } catch (\Throwable) {
            return -1;
        }
        if (\preg_match('/\A[1-9][0-9]*\z/D', $raw) !== 1) {
            return -1;
        }
        $pid = (int)$raw;
        return $pid > 0 ? $pid : -1;
    }

    private function removeVerifiedPidFile(string $file): bool
    {
        $status = @\lstat($file);
        if (!\is_array($status)) {
            return !\file_exists($file) && !\is_link($file);
        }
        if (\is_link($file)) {
            return false;
        }
        if (((((int)($status['mode'] ?? 0)) & 0170000) !== 0100000)
            || (int)($status['nlink'] ?? 0) !== 1
        ) {
            return false;
        }
        try {
            return $this->removeStableRegularFile($file, 'Gateway process PID file');
        } catch (\Throwable) {
            return false;
        }
    }

    private function removeUnixSocketFile(string $file): bool
    {
        if (!$this->sameBoundaryPath($file, $this->socketFile())) {
            $this->observeCleanupFailure(
                'CONTROL_SOCKET_CLEANUP_FAILED',
                'Gateway control socket path does not match its exact host endpoint.',
            );
            return false;
        }
        $status = @\lstat($file);
        if (!\is_array($status)) {
            return !\file_exists($file) && !\is_link($file);
        }
        if (\is_link($file)
            || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0140000)
            || (int)($status['nlink'] ?? 0) !== 1
        ) {
            $this->observeCleanupFailure(
                'CONTROL_SOCKET_CLEANUP_FAILED',
                'Gateway control socket is linked or special.',
            );
            return false;
        }
        if (!@\unlink($file)) {
            $this->observeCleanupFailure(
                'CONTROL_SOCKET_CLEANUP_FAILED',
                'Unable to remove the stale gateway control socket.',
            );
            return false;
        }
        try {
            $this->syncDirectory(\dirname($file));
        } catch (\Throwable $throwable) {
            $this->observeCleanupFailure(
                'CONTROL_SOCKET_CLEANUP_FAILED',
                $throwable->getMessage(),
            );
            return false;
        }
        return true;
    }

    private function pidRunning(int $pid): bool
    {
        return $this->pidRunningState($pid) === true;
    }

    /**
     * Return null when the platform query cannot distinguish a live process
     * from an unavailable/failed inspector. Callers that remove PID evidence
     * must require an explicit false; runtime admission continues to require
     * an explicit true through pidRunning().
     */
    private function pidRunningState(int $pid): ?bool
    {
        if ($pid < 1) {
            return false;
        }
        if (\PHP_OS_FAMILY !== 'Windows' && \function_exists('posix_kill')) {
            if (@\posix_kill($pid, 0)) {
                return true;
            }
            // POSIX signal 0 returns EPERM when the process exists but belongs
            // to another user. The controller is intentionally unprivileged,
            // so cross-user project Masters must not be reported as dead.
            if (!\function_exists('posix_get_last_error')) {
                return null;
            }
            $error = \posix_get_last_error();
            if ($error === 1) {
                return true;
            }
            return $error === 3 ? false : null;
        }
        if (\PHP_OS_FAMILY === 'Windows') {
            $systemRoot = \rtrim((string)\getenv('SystemRoot'), '\\/');
            $tasklist = $systemRoot !== ''
                ? $systemRoot . '\\System32\\tasklist.exe'
                : 'tasklist.exe';
            try {
                $output = $this->boundedCommandOutput([
                    $tasklist,
                    '/FI',
                    'PID eq ' . $pid,
                    '/FO',
                    'CSV',
                    '/NH',
                ]);
            } catch (\Throwable) {
                return null;
            }
            foreach ((array)\preg_split('/\r\n|\r|\n/', $output) as $line) {
                $fields = \str_getcsv((string)$line);
                $candidate = \trim((string)($fields[1] ?? ''));
                if (\preg_match('/\A[1-9][0-9]*\z/D', $candidate) === 1
                    && (int)$candidate === $pid
                ) {
                    return true;
                }
            }
            return false;
        }
        return \PHP_OS_FAMILY === 'Linux'
            ? \is_dir('/proc/' . $pid)
            : null;
    }

    private function processCommand(int $pid): string
    {
        if (\PHP_OS_FAMILY === 'Windows') {
            $systemRoot = \rtrim((string)\getenv('SystemRoot'), '\\/');
            $powershell = $systemRoot !== ''
                ? $systemRoot . '\\System32\\WindowsPowerShell\\v1.0\\powershell.exe'
                : 'powershell.exe';
            try {
                return $this->boundedCommandOutput([
                    $powershell,
                    '-NoLogo',
                    '-NoProfile',
                    '-NonInteractive',
                    '-Command',
                    'Get-CimInstance -ClassName Win32_Process '
                        . '| Where-Object ProcessId -EQ ' . $pid . ' '
                        . '| Select-Object -ExpandProperty CommandLine',
                ]);
            } catch (\Throwable) {
                return '';
            }
        }
        try {
            return $this->boundedCommandOutput([
                'ps',
                '-p',
                (string)$pid,
                '-o',
                'command=',
            ]);
        } catch (\Throwable) {
            return '';
        }
    }

    private function environmentPort(string $name, int $default): int
    {
        $raw = \getenv($name);
        if ($raw === false || \trim((string)$raw) === '') {
            return $default;
        }
        $value = \trim((string)$raw);
        if (\preg_match('/\A[0-9]+\z/D', $value) !== 1
            || (int)$value < 1
            || (int)$value > 65535
        ) {
            throw new \RuntimeException($name . ' must be an integer port in 1..65535.');
        }
        return (int)$value;
    }

    private function supervisorReady(): bool
    {
        if ((string)\getenv('WLS_GATEWAY_TEST_MODE') === '1') {
            return true;
        }
        return \is_file($this->stateDir() . DIRECTORY_SEPARATOR . 'platform-supervisor.ready');
    }

    private function writePid(): void
    {
        $this->atomicWrite($this->controllerPidFile(), (string)\getmypid() . "\n", 0600);
    }

    private function newEpoch(): string
    {
        return \bin2hex(\random_bytes(16));
    }

    private function validProjectUuid(string $projectUuid): bool
    {
        return \preg_match(
            '/\A[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}\z/D',
            $projectUuid,
        ) === 1;
    }

    private function quote(string $value): string
    {
        return '"' . \str_replace(['\\', '"'], ['\\\\', '\\"'], $value) . '"';
    }

    /**
     * @return array<string,mixed>
     */
    private function slotManifest(): array
    {
        try {
            $raw = $this->readStableRegularFile(
                $this->slotDir((string)$this->state['active_slot'])
                    . DIRECTORY_SEPARATOR . 'manifest.json',
                16_777_216,
                'Gateway active runtime manifest',
            );
            $manifest = \json_decode($raw, true);
            return \is_array($manifest) ? $manifest : [];
        } catch (\Throwable) {
            return [];
        }
    }

    /**
     * @return array<string,mixed>
     */
    private function slotManifestFromActiveFile(): array
    {
        $slot = \strtoupper(\trim($this->readStableRegularFile(
            $this->activeSlotFile(),
            2,
            'Gateway active-slot pointer',
        )));
        if (!\in_array($slot, ['A', 'B'], true)) {
            throw new \RuntimeException('Gateway active-slot pointer is invalid.');
        }
        $raw = $this->readStableRegularFile(
            $this->slotDir($slot) . DIRECTORY_SEPARATOR . 'manifest.json',
            16_777_216,
            'Gateway active runtime manifest',
        );
        $manifest = \json_decode($raw, true);
        if (!\is_array($manifest)
            || !\hash_equals($slot, (string)($manifest['slot'] ?? ''))
        ) {
            throw new \RuntimeException('Gateway active runtime manifest is invalid.');
        }
        return $manifest;
    }

    private function ensureDirectories(bool $readOnlyRecovery = false): void
    {
        $homeStatus = @\lstat($this->home);
        if (!\is_array($homeStatus)
            || \is_link($this->home)
            || ((((int)($homeStatus['mode'] ?? 0)) & 0170000) !== 0040000)
        ) {
            throw new \RuntimeException('Gateway home directory is missing or unsafe.');
        }
        foreach ([
            $this->runtimeDir(),
            $this->runDir(),
            $this->logDir(),
            $this->stateDir(),
            $this->configDir(),
            $this->runtimeDir() . DIRECTORY_SEPARATOR . 'temp',
            $this->runtimeDir() . DIRECTORY_SEPARATOR . 'temp'
                . DIRECTORY_SEPARATOR . 'client_body_temp',
            $this->runtimeDir() . DIRECTORY_SEPARATOR . 'temp'
                . DIRECTORY_SEPARATOR . 'proxy_temp',
            $this->runtimeDir() . DIRECTORY_SEPARATOR . 'temp'
                . DIRECTORY_SEPARATOR . 'fastcgi_temp',
            $this->runtimeDir() . DIRECTORY_SEPARATOR . 'temp'
                . DIRECTORY_SEPARATOR . 'uwsgi_temp',
            $this->runtimeDir() . DIRECTORY_SEPARATOR . 'temp'
                . DIRECTORY_SEPARATOR . 'scgi_temp',
            $this->runtimeDir() . DIRECTORY_SEPARATOR . 'shadow',
            $this->lkgDir(),
            $this->home . DIRECTORY_SEPARATOR . 'snapshots',
        ] as $directory) {
            if ($readOnlyRecovery && !\is_dir($directory)) {
                throw new \RuntimeException(
                    'Disk-pressure recovery cannot create a missing gateway directory: '
                        . $directory
                );
            }
            if (!\is_dir($directory) && !@\mkdir($directory, 0700) && !\is_dir($directory)) {
                throw new \RuntimeException('Unable to create gateway directory: ' . $directory);
            }
            $status = @\lstat($directory);
            if (!\is_array($status)
                || \is_link($directory)
                || ((((int)($status['mode'] ?? 0)) & 0170000) !== 0040000)
            ) {
                throw new \RuntimeException('Gateway directory is unsafe: ' . $directory);
            }
            if (\PHP_OS_FAMILY !== 'Windows' && !$readOnlyRecovery) {
                $modeApplied = @\chmod($directory, 0700);
                $verified = @\lstat($directory);
                if (!$modeApplied
                    || !\is_array($verified)
                    || ((((int)($verified['mode'] ?? 0)) & 0777) !== 0700)
                ) {
                    throw new \RuntimeException(
                        'Gateway directory mode is unsafe: ' . $directory
                    );
                }
            }
        }
        if (!\is_dir($this->trustDir()) || \is_link($this->trustDir())) {
            throw new \RuntimeException(
                'Gateway trust directory is missing or unsafe.'
            );
        }
        $diskPressureRecovery = $readOnlyRecovery || $this->diskPressureMarkerActive();
        if (!$diskPressureRecovery) {
            $this->collectStaleShadowDirectories();
            try {
                $this->ensureRecoveryReserve();
            } catch (\Throwable $exception) {
                $this->markDiskPressure(
                    'RECOVERY_RESERVE_FAILED',
                    'startup_reserve_allocation_failed',
                );
                if (!$this->diskPressureMarkerActive()) {
                    throw new \RuntimeException(
                        'Gateway recovery reserve failed and disk pressure could not be latched.',
                        0,
                        $exception,
                    );
                }
            }
        }
        if ($this->brokerInternalEndpoint === null) {
            throw new \RuntimeException('Gateway Controller must be launched through the native platform broker.');
        }
        try {
            $token = \strtolower(\trim($this->readStableRegularFile(
                $this->adminTokenFile(),
                65,
                'Gateway administrator credential',
            )));
        } catch (\Throwable) {
            $token = '';
        }
        if (\preg_match('/\A[a-f0-9]{64}\z/D', $token) !== 1) {
            throw new \RuntimeException('Gateway administrator credential is missing or invalid.');
        }
        $this->hostId();
    }

    private function runtimeDir(): string
    {
        return $this->home . DIRECTORY_SEPARATOR . 'runtime';
    }

    private function runDir(): string
    {
        return $this->runtimeDir() . DIRECTORY_SEPARATOR . 'run';
    }

    private function logDir(): string
    {
        return $this->runtimeDir() . DIRECTORY_SEPARATOR . 'logs';
    }

    private function stateDir(): string
    {
        return $this->home . DIRECTORY_SEPARATOR . 'state';
    }

    private function freshInstallBootstrapAllowed(): bool
    {
        $marker = $this->initializationMarkerFile();
        if (\file_exists($marker) || \is_link($marker)) {
            try {
                $decoded = \json_decode($this->readStableRegularFile(
                    $marker,
                    16_384,
                    'Gateway initialization marker',
                ), true);
                $payload = \is_array($decoded['payload'] ?? null)
                    ? $decoded['payload']
                    : null;
                $ledgerDigest = $this->fileHash($this->securityLedgerFile());
                $anchorDigest = $this->fileHash($this->securityAnchorFile());
                $this->initializationMarkerTrusted = \is_array($payload)
                    && (int)($payload['schema_version'] ?? 0) === 2
                    && \hash_equals(self::PROTOCOL, (string)($payload['protocol'] ?? ''))
                    && \hash_equals($this->hostId(), (string)($payload['host_id'] ?? ''))
                    && $ledgerDigest !== ''
                    && $anchorDigest !== ''
                    && \hash_equals(
                        $ledgerDigest,
                        (string)($payload['security_ledger_sha256'] ?? ''),
                    )
                    && \hash_equals(
                        $anchorDigest,
                        (string)($payload['security_anchor_sha256'] ?? ''),
                    )
                    && \hash_equals(
                        (string)($decoded['sha256'] ?? ''),
                        \hash('sha256', $this->canonicalJson($payload)),
                    );
            } catch (\Throwable) {
                $this->initializationMarkerTrusted = false;
            }
            return false;
        }
        $this->initializationMarkerTrusted = true;
        return !$this->gatewayHasHistoricalMutableState();
    }

    private function gatewayHasHistoricalMutableState(): bool
    {
        foreach ([
            $this->stateFile(),
            $this->securityLedgerFile(),
            $this->publicationFile(),
            $this->routeLkgFile(),
            $this->journalFile(),
            $this->journalFile() . '.1',
            $this->configFile(),
        ] as $file) {
            if (\file_exists($file) || \is_link($file)) {
                return true;
            }
        }
        foreach ([$this->lkgDir(), $this->home . DIRECTORY_SEPARATOR . 'snapshots'] as $dir) {
            if ($this->directoryHasEntries($dir)) {
                return true;
            }
        }
        return false;
    }

    private function persistInitializationMarker(): void
    {
        $file = $this->initializationMarkerFile();
        if (\file_exists($file) || \is_link($file)) {
            if (!$this->initializationMarkerTrusted) {
                throw new \RuntimeException(
                    'Gateway initialization marker is untrusted and cannot be overwritten.'
                );
            }
        }
        $ledgerDigest = $this->fileHash($this->securityLedgerFile());
        $anchorDigest = $this->fileHash($this->securityAnchorFile());
        if ($ledgerDigest === '' || $anchorDigest === '') {
            throw new \RuntimeException(
                'Gateway initialization marker requires committed security anchors.'
            );
        }
        $payload = [
            'schema_version' => 2,
            'protocol' => self::PROTOCOL,
            'host_id' => $this->hostId(),
            'security_generation_high_water' => (int)(
                $this->state['security_generation_high_water'] ?? 0
            ),
            'security_ledger_sha256' => $ledgerDigest,
            'security_anchor_sha256' => $anchorDigest,
            'initialized_at' => \gmdate(DATE_ATOM),
        ];
        $encoded = (string)\json_encode([
            'payload' => $payload,
            'sha256' => \hash('sha256', $this->canonicalJson($payload)),
        ], JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR);
        $this->atomicWrite($file, $encoded, 0600);
    }

    private function trustDir(): string
    {
        return $this->home . DIRECTORY_SEPARATOR . 'trust';
    }

